-- Sources: data/i18n/deDE. Lore text adapted from warcraft.wiki.gg (CC BY-SA 4.0); the core add-on's src fields name the articles.
local P = LoreForeverPacks.Begin("LoreForever_Lang_deDE")
P.entries["quest:1012"] = {n="Irrsinnige Druiden",s="Im östlichen Eschental erfährt Kayneth Stillwind durch eine Vision von einem Gemetzel. Die Nachtelfenschildwache kämpft gegen Gifte der Verlassenen, als die Geister der Druiden des Dor'danil-Grabhügels vor Qual aufschreien.",h="Im östlichen Eschental erfährt Kayneth Stillwind durch eine Vision von einem Gemetzel.",kw={"eschental","der dor'danil-grabhügel","forest song","verlassene","irrsinnige druiden","kayneth stillwind","mavoris cloudsbreak","taneel darkwood","uthil mooncall"},ang={["class:Druid"]="Als Druide könnt Ihr Taneel Darkwood, Uthil Mooncall und Mavoris Cloudsbreak feierlich Gnade gewähren. Ihr befreit andere, die wie Ihr die Künste Cenarions ausüben, von alchemistischem Wahnsinn.",["faction:Alliance"]="Als Mitglied der Allianz seht Ihr, wie die Grausamkeit der Verlassenen weit über Lordaeron hinausreicht. Ihre Seuchen werden in ferne Länder getragen, um Unschuldige im Schlaf zu töten.",["race:NightElf"]="Als Nachtelf könnt Ihr das Gemetzel an schlafenden Druiden im Dor'danil-Grabhügel als Frevel an der Natur und den Kaldorei betrachten. Die Verlassenen müssen sich dafür verantworten."},sec={{t="Eine Vision des Gemetzels",b="Während Kayneth Stillwind im östlichen Eschental gegen die Wirkung der Gifte der Verlassenen kämpft, sieht er im Wachzustand ein Massaker in einer Vision. Unter den Erdhügeln des Dor'danil-Grabhügels vergifteten untote Eindringlinge die Druiden im Schlaf und schlachteten sie ab. Das Gift riss ihre Seelen aus ihren Körpern und hinterließ wilde Geister, die vor Qual kreischen."},{t="Gnade für die erschlagenen Anführer",b="Kayneth Stillwind bittet Euch, das Leid unter dem Dor'danil-Grabhügel zu lindern. Die Phantome der Druiden wurden durch ihren Tod in den Wahnsinn getrieben und finden in den unterirdischen Kammern keine Erlösung. Drei Anführer ihres Zirkels sind noch immer unter den ruhelosen Toten: Taneel Darkwood, Uthil Mooncall und Mavoris Cloudsbreak. Bettet sie zur Ruhe, und der Grabhügel kann beginnen, sich von seiner Entweihung zu erholen."}},faq={{q="Wer hat die Druiden im Dor'danil-Grabhügel vergiftet?",a="Eindringlinge der Verlassenen vergifteten und ermordeten die Druiden im Dor'danil-Grabhügel. Kayneth Stillwind sah das Verbrechen in einer Vision, während er unter Giften der Verlassenen litt, die von untoten Agenten im Eschental stammten.",al={"wer tötete die dru iden von dor'danil","wer ermordete die druiden","verlassene vergiften druiden"}},{q="Warum wurden die Druiden zu wahnsinnigen Geistern?",a="Die Druiden wurden zu wahnsinnigen Geistern, nachdem sie im Schlaf getötet worden waren. Die alchemistischen Gifte der Verlassenen rissen ihre Seelen auf unnatürliche und qualvolle Weise aus ihren Körpern.",al={"warum sind die druiden geister","warum sind druiden wahnsinnig","warum irrsinnige druiden"}},{q="Wer sind Taneel Darkwood, Uthil Mooncall und Mavoris Cloudsbreak?",a="Taneel Darkwood, Uthil Mooncall und Mavoris Cloudsbreak führten den Druidenzirkel im Dor'danil-Grabhügel an. Ihre Geister halten den Wahnsinn im Grabhügel fest, weshalb sie zur Ruhe gebettet werden müssen, damit die anderen Frieden finden können.",al={"druidenanführer","taneel darkwood","uthil mooncall","mavoris cloudsbreak"}},{q="Wo liegt der Dor'danil-Grabhügel?",a="Der Dor'danil-Grabhügel liegt unter der Erde im südöstlichen Eschental, unmittelbar südlich der Ruinen von Forest Song.",al={"dor'danil standort","wo ist dor danil","grabhügel eschental"}},{q="Wer erteilt den Auftrag, die Druiden zur Ruhe zu betten?",a="Kayneth Stillwind, ein Nachtelf in Forest Song im östlichen Eschental, bittet Euch um Hilfe, nachdem Ihr ihn bei der Erforschung der Krankheiten der Verlassenen unterstützt habt.",al={"wer vergibt irrsinnige druiden","kayneth stillwind quest","wo beginnt irrsinnige druiden"}},{q="Wird der Grabhügel durch das Töten der Anführer vollständig gereinigt?",a="Das Töten der drei Anführer lindert die Seelenqual im Grabhügel. Kayneth sagt, dies sei ein Schritt, um den übrigen wahnsinnigen Geistern zu helfen, Frieden zu finden.",al={"ist dor'danil gerettet","wird der grabhügel gereinigt"}}},fx={["7181097d"]={q="Warum möchte Kayneth Stillwind, dass die Druidenanführer vernichtet werden?",a="Während Kayneth gegen die Gifte der Verlassenen kämpfte, offenbarte ihm eine Vision das schreckliche Schicksal seiner Verwandten im Dor'danil-Grabhügel. Die ermordeten Druiden verweilen als gequälte, wahnsinnige Geister, und ihre anhaltende Qual verfolgt ihn bis in seine Träume. Kayneth hofft, dass durch die Vernichtung ihrer ehemaligen Anführer ihre spirituelle Qual enden und den verbleibenden unruhigen Geistern in den Grabhügeln endlich Frieden finden lassen wird.",al={"kayneth motiv","warum wahnsinnige druiden töten","warum druidengeister vernichten"}}},fp="13,200,21.331.0,27.374.0,48.202.0,40.172.0,65.203.0,42.104.0,46.139.0,48.160.0"}
P.entries["quest:1013"] = {n="Das Buch von Ur",s="Bewahrer Bel'dugur schickt Champions der Horde in die Burg Shadowfang, um Urs Buch zu finden. Im Apothekarium der Unterstadt sucht er das Werk von Ur, einem verstorbenen Magier aus Dalaran, damit die Verlassenen dessen Forschungen zu anderen Ebenen nutzen können.",h="Bewahrer Bel'dugur schickt Champions der Horde in die Burg Shadowfang, um Urs Buch zu finden.",kw={"das apothekarium","arugal","bel'dugur","buch von ur","dalaran","fenrus","kirin tor","burg shadowfang","worgen"},ang={["class:Mage"]="Urs Buch steht für ein düsteres Kapitel in der Geschichte der Kirin Tor. Es zeigt, wie Forschungen über außerweltliche Wesen durch labile Magieanwender wie Arugal zu apokalyptischen Flüchen verdreht werden konnten.",["class:Warlock"]="Urs Neugier auf das, was jenseits der sterblichen Wirklichkeit liegt, erinnert an den Hunger eines Hexenmeisters nach Wissen über andere Ebenen. Bel'dugur sagt, Ur sei gescheitert, weil ihm der Mut fehlte, seine Entdeckungen einzusetzen.",["faction:Horde"]="Die Burg Shadowfang zu säubern und Arugals Quellen zu sichern hilft, den Silberwald zu stabilisieren und die Bedrohung durch wilde Worgen nahe den Gebieten der Horde einzudämmen.",["race:Undead"]="Die Bergung des Buches dient Lady Sylvanas und der Royal Apothecary Society. Sie stützt die Überzeugung der Verlassenen, dass Überleben bedeutet, verbotenes Wissen ohne sterbliche Skrupel anzunehmen."},sec={{t="Ein Relikt außerweltlicher Magie",b="Bevor der Dritte Krieg Dalaran zerstörte, widmete der brillante menschliche Zauberer Ur seine Forschungen Reichen jenseits von Azeroth. Die Kirin Tor regelten Beschwörungen und Kontakte zu äußeren Ebenen streng, doch Ur erforschte Wesen aus anderen Dimensionen, darunter die wilden Worgen. Er zögerte, ihre fremdartigen Kräfte einzusetzen, da er sie für gefährlich unkontrollierbar hielt. So wurde sein schriftliches Werk zu einer begehrten Beute für jene mit weniger Skrupeln."},{t="In dunklen Händen",b="Erzmagier Arugal nahm Urs Abhandlung an sich und nutzte die darin enthaltenen Forschungen, bevor er sich in der Burg Shadowfang niederließ. Ohne Urs Bedenken beschwor Arugal blutrünstige Worgen in den Silberwald. Ihr Fluch verschlang Pyrewood und die umliegenden Täler. Nun liegt der Band vernachlässigt in den Türmen der Burg, bewacht von Arugals wilden Haustieren."},{t="Der Ehrgeiz der Verlassenen",b="Bewahrer Bel'dugur und die Royal Apothecary Society sehen Urs Schicksal als sterbliche Schwäche, nicht als Warnung vor Hochmut. Bel'dugur glaubt, dass Urs Gewissen ihn handlungsunfähig machte, als die Gefahr kam. Die Verlassenen suchen das Buch von Ur für die Unterstadt, um akademisches Zögern abzulegen und sein Wissen über andere Dimensionen nutzbar zu machen. Sie wollen ihr Überleben sichern und Sylvanas Windläufers Herrschaft über ganz Lordaeron aufrechterhalten."}},faq={{q="Wer war Ur?",a="Ur war ein brillanter Magier aus Dalaran, der seine Forschungen vor dem Dritten Krieg Reichen jenseits von Azeroth widmete. Er erforschte Kreaturen aus anderen Dimensionen, darunter Worgen, und starb während des Einfalls der Geißel in Dalaran.",al={"urs geschichte","wer ist ur","magier ur"}},{q="Wo befindet sich das Buch von Ur?",a="Das Buch von Ur liegt in der Burg Shadowfang, auf einem Bücherregal in der Kammer von Fenrus dem Verschlinger, tief im Inneren der Festung.",al={"wo ist das buch","buch von ur fundort","shadowfang buch fundort"}},{q="Wer ist Bewahrer Bel'dugur?",a="Bewahrer Bel'dugur ist ein Archivar und Forscher der Verlassenen im Apothekarium der Unterstadt. Er sammelt dunkles, arkanes und außerweltliches Wissen, um die Macht und das Überleben der Verlassenen zu sichern.",al={"beldugur","bewahrer bel dugur","questgeber"}},{q="Warum wollen die Verlassenen das Buch?",a="Bel'dugur und seine Mitstreiter suchen Urs Forschungen zu Wesen aus anderen Ebenen, damit die Verlassenen deren Kräfte nutzen können. Sie glauben, dass sein Gewissen Ur davon abhielt, seine Entdeckungen auszunutzen, und die Unterstadt beabsichtigt kein solches Zögern.",al={"warum wollen die verlassenen urs buch","unterstadt zweck buch von ur"}},{q="Wie gelangte das Buch in die Burg Shadowfang?",a="Nach dem Fall Dalarans gelangte Erzmagier Arugal an Urs Aufzeichnungen und nutzte sie, um Worgen nach Lordaeron zu beschwören. Er brachte die Forschungen in die Burg Shadowfang, als er die Festung an sich riss.",al={"wie bekam arugal das buch","warum ist das buch in der burg shadowfang"}},{q="Hängt das Buch von Ur mit dem Fluch der Worgen zusammen?",a="Ja. Urs Forschungen beschrieben die Dimension, aus der die Worgen stammen. Arugal nutzte die Abhandlung, um die Bestien auf den Silberwald loszulassen, und verursachte damit die dortige Plage.",al={"worgen ursprung buch","buch von ur worgen"}}},fx={["8665acc9"]={q="Was ist Das Buch von Ur?",a="Das Buch von Ur ist ein wertvoller arkaner Foliant, der von dem verstorbenen Magier aus Dalaran namens Ur geschrieben wurde, bevor die Geißel über Lordaeron hereinbrach. Ur widmete seine Studien extradimensionalen Bereichen und seltsamen, außerweltlichen Bestien – einschließlich der wilden Worgen. Obwohl Ur über immenses magisches Wissen verfügte, weigerte er sich aufgrund seines moralischen Gewissens letztendlich, sich zu tief mit diesen tödlichen Kräften einzulassen. Für die Verlassenen, die solche ethischen Bedenken verachten, bietet seine Forschung unschätzbare Geheimnisse über andere Welten und gefährliche planare Entitäten.",al={"was ist das buch von ur","wissen über das buch von ur","inhalt des buches von ur"}}},fp="14,216,29.416.0,24.315.0,23.407.1,11.212.0,32.118.0,24.181.0,36.218.0,43.174.0,46.168.0"}
P.entries["quest:1014"] = {n="Arugal muss sterben",s="Im Grabmal ruft Dalar Morgenweber Streiter dazu auf, sich Arugal zu stellen. Der abtrünnige Erzmagier herrscht über Burg Shadowfang, und seine Worgen bedrohen die Herrschaft der Verlassenen über den Silberwald.",h="Im Grabmal ruft Dalar Morgenweber Streiter dazu auf, sich Arugal zu stellen.",kw={"arugal","dalar morgenweber","arugals kopf","das grabmal","burg shadowfang","silberwald","sylvanas","worgen"},ang={["class:Mage"]="Als Magier steht Ihr einem Magier der Kirin Tor gegenüber, den außerweltliche Beschwörungen verdorben haben, einer Warnung vor arkaner Hybris.",["faction:Horde"]="Als Mitglied der Horde helft Ihr, einen fest verwurzelten Zauberer zu bezwingen und wichtige Straßen zu öffnen, was den wachsenden Einfluss der Horde in den Östlichen Königreichen zeigt.",["race:Undead"]="Als Verlassener helft Ihr, Eure südwestliche Grenze zu sichern und die Wege zwischen dem Grabmal und Unterstadt zu schützen."},sec={{t="Ein Dorn im Auge der Dark Lady",b="Burg Shadowfang erhebt sich über den Wäldern, und Erzmagier Arugal befehligt die Worgen darin. Die Verlassenen haben das Grabmal zu ihrem Stützpunkt gemacht, doch der Silberwald bleibt gefährlich und heftig umkämpft. Schuldgefühle und dunkle Zauberei trieben Arugal in den Wahnsinn. Er ließ die wilden Worgen auf Lordaeron los, und nun durchstreifen seine gefräßigen Bestien die Waldpfade und behindern Fürstin Sylvanas Windläufers Bemühungen, die Region zu sichern."},{t="Der Bestie an die Kehle",b="Dalar Morgenweber weiß, dass die Jagd auf Worgen im ganzen Wald die Gefahr nicht bannen wird. Ihr Ursprung liegt in Burg Shadowfang. Ihr müsst in die alte Festung eindringen, Euch durch Arugals Worgenbrut kämpfen und den wahnsinnigen Zauberer in seinem Horst stellen. Sein abgetrennter Kopf beweist seinen Tod, und seine Niederlage kann seine Herrschaft über die Region brechen."}},faq={{q="Warum will Dalar Morgenweber Arugal tot sehen?",a="Dalar Morgenweber will Arugal tot sehen, weil dessen Worgen den Silberwald überrennen. Solange der Magier lebt, können die Verlassenen die Region nicht zu einer sicheren Bastion machen.",al={"warum arugal töten","dalar morgenwebers ziel","arugal ziel"}},{q="Wo ist Arugal zu finden?",a="Erzmagier Arugal ist in Burg Shadowfang zu finden, hoch über dem südlichen Silberwald.",al={"wo ist arugal","arugals aufenthaltsort","arugal finden"}},{q="Welcher Beweis ist erforderlich, um die Mission abzuschließen?",a="Dalar Morgenweber verlangt Arugals abgetrennten Kopf als Beweis für den Tod des Zauberers.",al={"was braucht dalar","arugals kopf quest","beweis für den tod"}},{q="Welche Bedrohung stellt Arugal für die Horde dar?",a="Arugal befehligt Legionen verfluchter Worgen, die Streitkräfte der Horde bedrängen und die Herrschaft der Verlassenen im gesamten Silberwald bedrohen. Er verfügt außerdem über mächtige Angriffsmagie.",al={"warum ist arugal gefährlich","worgenbedrohung silberwald","ist arugal eine bedrohung"}},{q="Wem dient Dalar Morgenweber?",a="Dalar Morgenweber dient Fürstin Sylvanas Windläufer und den Verlassenen. Vom Grabmal aus arbeitet er daran, die Herrschaft der Verlassenen in ganz Lordaeron zu stärken.",al={"für wen arbeitet morgenweber","führung im grabmal"}},{q="Was geschieht nach Arugals Niederlage?",a="Arugals Tod bricht seinen magischen Einfluss auf den Silberwald. Dann können die Verlassenen ihre Herrschaft im Westen Lordaerons ausweiten, ohne seine koordiniert vorgehenden Worgenrudel fürchten zu müssen.",al={"nach arugals tod","folgen von arugals tod"}}},fx={["375fc177"]={q="Wofür ist Arugals Kopf?",a="Dalar Morgenweber verlangt den abgetrennten Kopf des Erzmagiers Arugal als untrüglichen Beweis dafür, dass die Herrschaft des wahnsinnigen Zauberers über Burg Shadowfang beendet ist. Über die einfache Bestätigung der Tötung hinaus beabsichtigt Dalar, die Überreste persönlich zu untersuchen, um die üble, nachwirkende Magie zu entschlüsseln und auszumerzen, die Arugal über den Silberwald gelegt hat, um sicherzustellen, dass sein Fluch die Verlassenen nicht länger bedrohen kann.",al={"zweck von arugals kopf","warum arugals kopf nehmen","was macht dalar mit arugals kopf"}},["62d569dd"]={q="Wer ist Erzmagier Arugal?",a="Erzmagier Arugal war einst ein Zauberer der Kirin Tor in Dalaran. In den Wahnsinn getrieben, entfesselte er die grimmigen Worgen auf Lordaeron, um die Geißel zu bekämpfen, verlor jedoch die Kontrolle über die Bestien. Er zog sich nach Burg Shadowfang zurück, schlachtete Baron Silberlein ab und beanspruchte die Festung für sich, wobei er die wilden Monster als seine verfluchten 'Kinder' annahm und seither den Silberwald terrorisiert.",al={"wer ist arugal","burg shadowfang boss arugal","warum ist arugal in burg shadowfang"}}},fp="15,176,31.405.0,30.330.0,43.162.0,26.87.0,47.86.0,42.164.0,32.143.0,38.168.1"}
P.entries["quest:1016"] = {n="Die Rückeroberung des Mystralsees",s="In der Silberwindzuflucht sucht Schildwache Velene Sternenschlag nach dem Urheber der verseuchten Gewässer. Sie bittet Euch, intakte Armschienen von feindseligen Elementaren zu sammeln, damit eine Rolle der Bestimmung ihren Beschwörer enthüllen kann.",h="In der Silberwindzuflucht sucht Schildwache Velene Sternenschlag nach dem Urheber der verseuchten Gewässer.",kw={"eschental","bestimmte rolle","rolle der bestimmung","die rückeroberung des mystralsees","magier-beschwörer","mystralsee","schildwache velene sternenschlag","silberwindzuflucht"},ang={["class:Mage"]="Als Magier könnt Ihr erkennen, wie die Fesseln beschworener Elementare die arkane Signatur ihres Meisters tragen, und so leichtfertige Beschwörungen zu ihrem Ursprung zurückverfolgen.",["faction:Alliance"]="Als Mitglied der Allianz stärkt Ihr Euer Ansehen im umkämpften Herzen des zentralen Eschentals, indem Ihr den Silverwind Sentinels helft.",["race:NightElf"]="Als Nachtelf wisst Ihr, dass Eschentals natürliche Gewässer heiliger Boden sind. Arkane Beschwörer, die fremde Verderbnis bringen, beleidigen die Kaldorei."},sec={{t="Verseuchte Gewässer",b="Schurken unter den Wasserelementaren bedrohen Eschentals heilige Gewässer. Anders als die wilden Geister, die zur Welt gehören, tragen diese Kreaturen Zeichen einer Beschwörung. Ihr plötzliches Auftauchen in der Silberwindzuflucht warnt die Schildwachen, dass fremde Verderbnis tiefer in die Wasserläufe des Waldes vordringt."},{t="Den Beschwörer aufspüren",b="Schildwache Velene Sternenschlag glaubt, dass jemand die Elementare gebunden und entfesselt hat. Sie gibt Euch eine magische Rolle der Bestimmung, um den Schuldigen zu ermitteln. Der Zauber benötigt intakte Armschienen, die den Geistern abgenommen werden, bevor sie sich auflösen. Ihre verbleibende arkane Signatur kann die Rolle zu demjenigen führen, der die Elementare ins Dasein gerufen hat."},{t="Die Einmischung eines Zauberers",b="Die Rolle der Bestimmung liest die intakten Armschienen und bestätigt Velenes schlimmste Befürchtung: Ein einzelner Magier lässt verderbte Elementare in Eschentals Gewässern entstehen. Die Entdeckung empört die nachtelfischen Verteidiger. Sie bereiten rasche Vergeltung gegen den Beschwörer vor, der die Unantastbarkeit der Wälder bedroht."}},faq={{q="Warum gibt es Wasserelementare in Eschental?",a="Die feindseligen Wasserelementare sind keine natürlichen Bewohner Eschentals. Ein fremder Zauberwirker hat sie beschworen und damit die heiligen Gewässer gestört und die Nachtelfen erzürnt.",al={"warum sind hier elementare","eschental wasserelementare","woher kommen die elementare"}},{q="Wer vergibt die Quest Die Rückeroberung des Mystralsees?",a="Schildwache Velene Sternenschlag vergibt den Auftrag. Sie ist in der Silberwindzuflucht am Ufer des Mystralsees in Eschental stationiert.",al={"questgeber","wer startet die rückeroberung des mystralsees","wo die rückeroberung des mystralsees annehmen"}},{q="Wozu dient die Rolle der Bestimmung?",a="Die Rolle der Bestimmung liest die magische Signatur, die auf den Elementaren zurückbleibt. Wird sie auf fünf intakte Armschienen angewandt, verfolgt sie die arkane Verbindung bis zu dem Beschwörer, der sie erschaffen hat.",al={"was bewirkt die rolle","rolle der bestimmung zweck","warum die rolle der bestimmung verwenden"}},{q="Warum eignen sich nur intakte Armschienen für das Ritual?",a="Nur intakte Armschienen bewahren genügend stabile arkane Resonanz, damit die Rolle sie untersuchen kann. Wird ein Elementar vernichtet, werden seine magischen Fesseln oft beschädigt oder zerschmettert, sodass sie den Beschwörer nicht mehr enthüllen können.",al={"warum intakte armschienen","zerbrochene armschienen","intakte elementararmschienen"}},{q="Was geschieht nach der Anwendung der Rolle?",a="Nachdem Ihr die Bestimmte Rolle zu Schildwache Velene Sternenschlag zurückgebracht habt, identifiziert sie den verantwortlichen abtrünnigen Zauberwirker und schickt Euch in der Folgequest „Magier-Beschwörer“ auf die Jagd nach dem Beschwörer.",al={"die rückeroberung des mystralsees folgequest","what comes next","nächste quest nach der rückeroberung des mystralsees"}},{q="Warum liegen Schildwache Velene diese Elementare so sehr am Herzen?",a="Nachtelfen verehren die natürliche Reinheit von Eschentals Wäldern und Gewässern. Ein sterblicher Zauberer, der ihre Seen absichtlich mit verderbten Elementaren verschmutzt und aus dem Gleichgewicht bringt, verhöhnt ihre Hüterschaft.",al={"schildwache velene beweggründe","warum sich nachtelfen um elementare kümmern"}}},fx={b81920f2={q="Wofür ist die Bestimmte Rolle?",a="Die Bestimmte Rolle enthält die mystische Spur, die von den intakten Armschienen der Elementare gesammelt wurde. Durch die Durchführung des Wahrsagerituals prägt Ihr die magischen Signaturen der Wasserelementare auf das Pergament. Die Rückgabe dieser vervollständigten Rolle an Schildwache Velene Sternenschlag liefert den Schildwachen die entscheidenden arkanen Hinweise, die erforderlich sind, um den genauen abtrünnigen Magier zu identifizieren, der für die Beschwörung der verdorbenen Kreaturen in die unberührten Gewässer des Eschentals verantwortlich ist.",al={"zweck der bestimmten rolle","warum bestimmte rolle","was macht die bestimmte rolle"}}},fp="17,203,14.288.0,21.319.0,19.294.1,44.167.0,38.126.0,43.164.0,47.200.0,39.183.1,61.199.0"}
P.entries["quest:1017"] = {n="Magier-Beschwörer",s="In der Silberwindzuflucht entsendet Schildwache Velene Sternenschlag einen Stoßtrupp nach Süden, nachdem Wasserelementare nahe dem Mystralsee verderbt wurden. Die Schildwachen schicken Abenteurer über die Grenze, um den untoten Magier Sarilus Foulborne auf dem Glutnebelgipfel zu töten.",h="In der Silberwindzuflucht entsendet Schildwache Velene Sternenschlag einen Stoßtrupp nach Süden, nachdem...",kw={"eschental","glutnebelgipfel","licht von elune","sarilus foulborne","silberwindzuflucht","brachland","velene starstrike","wasserelementare"},ang={["class:Mage"]="Die Konfrontation mit Foulborne stellt Arkanisten der Allianz einem untoten Magieanwender gegenüber, der die Beschwörung von Elementaren auf rücksichtslose Weise ins Extrem treibt.",["class:Priest"]="Wenn Ihr das Licht von Elune von den Schildwachen erhaltet, verbindet sich Euer Weg mit der seltenen, wundersamen Gnade der Göttin im Kampf gegen untote Verderbnis.",["faction:Alliance"]="Ein Angriff auf einen Verlassenen tief im Brachland ist eine kühne Machtdemonstration gegen die Vorstöße der Horde entlang der südlichen Grenze des Eschentals.",["race:NightElf"]="Sarilus' arkane Schändung der Natur jenseits der Waldgrenze beleidigt die Kaldorei. Bei seiner Hinrichtung geht es sowohl um das Gleichgewicht des Waldes als auch um Stolz."},sec={{t="Über die Grenze",b="Nachtelfen schicken selten ohne schwerwiegenden Grund Späher nach Süden ins Brachland. Schildwache Velene Sternenschlag führte unnatürliche Störungen unter den Wasserelementaren rund um den Mystralsee auf Sarilus Foulborne zurück, einen Beschwörer der Verlassenen, der seine Künste direkt jenseits der Grenze ausübt. Für die Schildwachen in der Silberwindzuflucht ist es unerträglich, dass ein feindlicher Zauberer so nahe ihrer Heimat die Natur schändet."},{t="Der Beschwörer auf dem Gipfel",b="Sarilus Foulborne hat seinen Unterschlupf hoch oben auf dem Glutnebelgipfel eingerichtet, einem schroffen Berg, auf dem es von Kultisten der Burning Blade wimmelt. Von dort aus beschwört er Scharen von Wasserelementaren und unterwirft sie seinem Willen, während er vom Gebiet der Horde aus der Autorität der Nachtelfen trotzt. Um ihn zu erreichen, muss man sich in feindliches Gebiet wagen und seine beschworenen Streitkräfte durchbrechen. Die Schildwachen verlangen seinen abgetrennten Kopf als Beweis dafür, dass ihre Rache über die Waldgrenze hinausreicht."},{t="Elunes Segen",b="Velene Starstrike nimmt Foulbornes abgetrennten Kopf entgegen und überreicht seinem Bezwinger das Licht von Elune. Dieser heilige Trunk aus Mondlicht ist ein geschätzter Schutz unter Priesterinnen und Schildwachen, der vollständigen Schutz gewährt, wenn der Tod naht. Das Geschenk erinnert an die göttliche Gunst der Nachtelfen, während sich verderbte Magie in Kalimdor ausbreitet."}},faq={{q="Wer ist Sarilus Foulborne?",a="Sarilus Foulborne ist ein untoter Magier, der ins Brachland floh und sich auf dem Glutnebelgipfel niederließ. Er versklavt Wasserelementare durch arkane Beschwörungen und zieht damit den Zorn der Schildwachen aus dem nahen Eschental auf sich.",al={"sarilus foulborne","wer ist der magier-beschwörer","foulborne hintergrundgeschichte"}},{q="Wo liegt der Glutnebelgipfel?",a="Der Glutnebelgipfel ist ein schroffer Berg im nördlichen Brachland, direkt südlich der Grenze zum Eschental. Sarilus Foulborne wartet an seinem höchsten Punkt.",al={"wo ist der glutnebelgipfel","glutnebelgipfel lage","wie den glutnebelgipfel finden"}},{q="Warum will Schildwache Velene Sternenschlag Sarilus tot sehen?",a="Sarilus schändet und verdirbt Wasserelementare nahe der Grenze zum Eschental. Velene findet seine Auflehnung unerträglich und will seinen unnatürlichen Beschwörungen ein Ende setzen, um zu beweisen, dass Feinde die Schildwachen nicht von jenseits der Grenze verspotten können.",al={"warum sarilus töten","velene starstrike beweggrund"}},{q="Was ist das Licht von Elune, das als Belohnung vergeben wird?",a="Das Licht von Elune ist eine seltene Phiole, gesegnet mit göttlichem Mondlicht. Trinkt ihren Inhalt in höchster Not, um kurzzeitig vollständig gegen Schaden und Zaubereffekte immun zu werden und dem sonst sicheren Tod zu entgehen.",al={"licht von elune trank","licht von elune hintergrundgeschichte"}},{q="Was geht dieser Quest voraus?",a="Zuvor sammeln Abenteurer unversehrte Armschienen von den wahrsagenden Wasserelementaren rund um den Mystralsee im Eschental. Velene nutzt sie, um herauszufinden, wer die Elementare manipuliert.",al={"voraussetzung für magier-beschwörer","quest vor magier-beschwörer"}},{q="Warum ist es für Spieler der Allianz gefährlich, das Brachland zu betreten?",a="Das Brachland gehört der Horde und ist die Heimat von Tauren und Orcs. Soldaten und Abenteurer der Allianz, die es betreten, laufen Gefahr, von Patrouillen der Horde und rivalisierenden Streitern abgefangen zu werden.",al={"brachland gefährlich","quest im gebiet der horde"}}},fx={b17c8b5b={q="Warum verlangt Schildwache Velene Sternenschlag den Kopf von Sarilus Faulmut?",a="Schildwache Velene Sternenschlag fordert den Kopf von Sarilus Faulmut als endgültigen Beweis für seinen Tod. Der Magier der Verlassenen hat schamlos die Wasserelementare im Eschental geschändet und die Schildwachen von seinem Platz jenseits der Grenze aus verspottet. Wenn Ihr seinen abgetrennten Kopf zur Silberwindzuflucht zurückbringt, stellt Ihr zweifelsfrei sicher, dass seiner Arroganz ein Ende gesetzt wurde, und wischt sein abscheuliches Lächeln für immer aus.",al={"sarilus faulmuts kopf","warum sarilus kopf bringen","zweck von sarilus kopf"}},bcfc7529={q="Warum schickt Schildwache Velene Sternenschlag Euch an ihrer statt?",a="Sarilus Faulmut hat auf dem Glutnebelgipfel tief im Brachland Zuflucht gesucht. Da dieses trockene Land fest in der Hand der Horde ist, würde die Entsendung einer offiziellen militärischen Einheit von Nachtelf-Schildwachen das Risiko eines offenen Grenzkonflikts mit den wachsamen Garnisonen der Horde bergen. Ein fähiger Abenteurer, der allein reist, kann die Grenze unbemerkt überqueren, den nekromantischen Magier niederstrecken und zurückkehren, bevor der Feind eine Verteidigung aufbaut.",al={"warum schickt mich mage summoner","warum tötet velene sarilus nicht","warum braucht schildwache velene mich"}}},fp="13,237,21.376.0,24.422.0,17.314.1,25.206.0,32.146.0,54.233.0,45.195.0,29.180.0,59.164.0"}
P.entries["quest:102"] = {n="Auf Patrouille durch Westfall",s="Gnollrudel bedrohen die Menschen, die noch in Westfalls Grasland leben. Von der Späherkuppe aus ruft Hauptmann Danuvin Freiwillige auf, sie zu jagen, da er ihre Zusammenarbeit mit Dieben in den Todesminen fürchtet.",h="Gnollrudel bedrohen die Menschen, die noch in Westfalls Grasland leben.",kw={"danuvin","die todesminen","gnolle","pfoten","volksmiliz","späherkuppe","sturmwind","westfall"},ang={["faction:Alliance"]="Für die Allianz stehen Westfalls notleidende Landbewohner im Gegensatz zum Adel in Burg Sturmwind, der sich von ihrer Not abgewandt hat.",["race:Human"]="Als Mensch seht Ihr an Westfalls goldenen Feldern, die von Gnollen überrannt werden, wie zerbrechlich die Erholung des Königreichs nach den jüngsten Kriegen bleibt."},sec={{t="Von der Krone verlassen",b="Die Späherkuppe ist Westfalls wichtigste Verteidigungsstellung, gehalten von örtlichen Freiwilligen statt königlichen Truppen. Da Sturmwind keine Soldaten zum Schutz der abgelegenen Ackerflächen entsendet, gründeten die Menschen die Volksmiliz. Hauptmann Danuvin war einst Bauer in Westfall. Nun führt er die Miliz an und weigert sich, seine Heimat aufzugeben.\n\nDie Miliz ist auf durchreisende Abenteurer angewiesen, die helfen, ihren Verteidigungsring gegen die Gefahren zu halten, die sich auf den Ebenen sammeln."},{t="Die Aasfresser des Graslands",b="Gnolle bedrohen die Flüchtlinge und Hausbesetzer, die in Westfall ums Überleben kämpfen. Danuvins Späher glauben, dass die Rudel mit Banditen zusammenarbeiten, die in den Todesminen hausen. Deshalb schickt er Jäger aus, um Gnollpfoten zu sammeln. Er hofft, die zunehmenden Patrouillen der Rudel einzudämmen und jede Zusammenarbeit zwischen den Bestien und den Gesetzlosen zu unterbinden."}},faq={{q="Wer ist Hauptmann Danuvin?",a="Hauptmann Danuvin befehligt die freiwilligen Verteidiger auf der Späherkuppe. Einst war er Bauer in Westfall, doch als Sturmwind seine Unterstützung zurückzog, übernahm er die Führung und weigert sich, die verbliebenen Menschen aufzugeben.",al={"hauptmann danuvin","wer ist danuvin","questgeber späherkuppe"}},{q="Warum kämpft die Volksmiliz gegen Gnolle statt der Soldaten aus Sturmwind?",a="Sturmwinds House of Nobles hat Westfalls Not weitgehend ignoriert und die Region ohne königliche Soldaten zurückgelassen. Vertriebene Bauern und Arbeiter gründeten die Volksmiliz, um ihr Land gegen Banditen und wilde Bestien zu verteidigen.",al={"warum keine armee aus sturmwind","wo sind sturmwinds wachen","warum miliz"}},{q="Sind die Gnolle in Westfall organisiert?",a="Gnolle sind meist chaotische Aasfresser, doch Hauptmann Danuvin sieht Anzeichen dafür, dass Westfalls Rudel sich mit Dieben aus den Todesminen abstimmen. Möglicherweise bewachen sie die Randgebiete des Einflussbereichs der Verbrecher.",al={"arbeiten gnolle mit defias zusammen","gnollbündnis","todesminen diebe gnolle"}},{q="Warum verlangt Hauptmann Danuvin Gnollpfoten?",a="Hauptmann Danuvin verlangt Gnollpfoten als Beweis dafür, dass die Bestien getötet und aus dem Grasland beseitigt wurden.",al={"warum gnollpfoten","kopfgeld für pfoten","beweis für tötungen"}},{q="Wo sind die Gnolle gewöhnlich zu finden?",a="Jagdtrupps und Lager der Gnolle sind über Westfalls zentrale und südliche Ebenen verteilt. Sie durchstreifen offene Felder rund um verlassene Gehöfte und nahe den Hügelhängen.",al={"gnollstandorte","wo gnolle in westfall finden"}},{q="Was geschieht, wenn die Bedrohung durch die Gnolle zurückgedrängt ist?",a="Die Volksmiliz hofft, dass die Menschen die Ebenen zurückgewinnen und die einstige Kornkammer des Königreichs wiederherstellen können, wenn die Reihen der Gnolle und Gesetzlosen ausgedünnt werden.",al={"wie weiter in westfall","ziel der miliz","kornkammer von sturmwind"}}},fx={["939494a1"]={q="Warum möchte Hauptmann Danuvin, dass Ihr Westfall patrouilliert?",a="Hauptmann Danuvin weigert sich, seine Heimat aufzugeben. Die Krone von Sturmwind hat Westfall den Rücken gekehrt und die verbleibenden Farmer und Bewohner der grassierenden Gesetzlosigkeit überlassen. Danuvin und die The People's Militia sind entschlossen, die Region zurückzuerobern und sie wieder zu der fruchtbaren Kornkammer zu machen, die sie einmal war. Sie können die Ebenen jedoch nicht sichern, solange Gnolle ungehindert umherstreifen und die Einheimischen belästigen.",al={"warum westfall patrouillieren","motiv von danuvin","warum gnolle in westfall töten"}},["91e73c26"]={q="Warum sind die Gnolle in Westfall?",a="Die Gnolle, die durch das Grasland streifen, scheinen mit den Dieben zusammenzuarbeiten, die sich in den Todesminen verschanzt haben. Diese Plünderer nutzen den militärischen Abzug des Königreichs aus, terrorisieren die örtlichen Farmen und arbeiten mit den Banditen zusammen, um die Späherkuppe und die verbleibende Bevölkerung belagert und gespalten zu halten.",al={"wer sind die gnolle","warum sind gnolle hier","westfall gnolle todesminen"}}},fp="19,191,22.427.0,32.307.0,23.192.0,74.225.0,37.188.0,44.110.0,37.158.0,50.159.0"}
P.entries["quest:1020"] = {n="Orendils Heilmittel",s="In Eschental wartet ein Kind in Astranaar auf Orendils Heilmittel. Orendil Rundblatt schickt Euch mit einem Heilmittel aus seltenen Pflanzen los.",h="In Eschental wartet ein Kind in Astranaar auf Orendils Heilmittel.",kw={"eschental","astranaar","bathranshaar","heilmittel","orendil rundblatt","pelturas weißmond","relara"},ang={["class:Priest"]="Als Priester wisst Ihr, dass Kräuter Relaras Körper eine Zeit lang Linderung verschaffen können, während ihr anhaltendes Leiden Elunes heiliges Eingreifen und Mondriten erfordert.",["profession:Herbalism"]="Kräuterkunde zeigt, wie Pflanzenkunde und Schlachtfeldmedizin zusammenkommen. Gesammelte Kräuter aus Eschental wie Bathranshaar können über das Leben eines Kindes entscheiden.",["race:NightElf"]="Als Nachtelf helft Ihr, Astranaars Kinder zu schützen und die Gemeinschaft Eures Volkes in einem umkämpften Wald zu stärken."},sec={{t="Die Verzweiflung eines Vaters",b="Pelturas Weißmond sieht mit an, wie seine Tochter Relara in Astranaar dahinsiecht. Eine schwere Krankheit stellt die Menschen vor Ort vor ein Rätsel. Deshalb suchte er bei Kräuterkundigen in ganz Eschental Hilfe, bevor die Hoffnung zu schwinden begann."},{t="Wettlauf durch die Wälder",b="Orendil Rundblatt braut einen Trank, um Relaras Leiden aufzuhalten. Dafür braucht er mehrere Bestandteile, darunter Bathranshaar. Er vertraut Euch das Heilmittel an und schickt Euch auf der Waldstraße nach Süden und Osten bis nach Astranaar, wo Relara wartet."},{t="Eine zerbrechliche Atempause",b="Orendils Trank verschafft Relara Linderung, doch er kann das übernatürliche Leiden, das an ihrem Geist nagt, nicht beenden. Das Heilmittel verschafft Zeit, um in alten Kaldorei-Ruinen nach Relikten zu suchen, die von Elune gesegnet wurden. Diese Relikte könnten ihre Rettung vollenden."}},faq={{q="Wer ist in Astranaar krank?",a="Relara Whitemoon, die junge Tochter von Pelturas Weißmond, liegt in Astranaar krank im Bett. Ihr Zustand ist kritisch, und ihr Vater sucht verzweifelt nach einem Heilmittel.",al={"wer ist krank","wer braucht das heilmittel","krankes kind astranaar"}},{q="Wer hat Orendils Heilmittel gebraut?",a="Orendil Rundblatt, ein nachtelfischer Kräuterkundiger im nördlichen Eschental, braute die Mischung, nachdem er Pflanzenmaterial aus Bathrans Schlupfwinkel erhalten hatte.",al={"wer hat das heilmittel hergestellt","orendil rundblatt","woher stammt das heilmittel"}},{q="Wo befindet sich Pelturas Weißmond?",a="Pelturas Weißmond lebt in Astranaar, der Allianzstadt an der Hauptstraße durch das zentrale Eschental. In einem der Waldhäuser wacht er am Krankenbett seiner Tochter.",al={"pelturas aufenthaltsort","wo ist pelturas","pelturas in astranaar finden"}},{q="Heilt Orendils Heilmittel Relara vollständig?",a="Nein. Der Trank stabilisiert Relaras akuten Zustand und gibt ihrem Vater neue Hoffnung, doch ihre Krankheit erfordert tiefere spirituelle Hilfe. Reisende suchen nach Elunes Träne.",al={"ist relara geheilt","wirkt das heilmittel","wirkung des heilmittels"}},{q="Welche Zutaten wurden für dieses Heilmittel verwendet?",a="Die Hauptzutat war Bathranshaar, gesammelt auf dem verfluchten Boden von Bathrans Schlupfwinkel nördlich von Maestras Posten.",al={"zutaten des heilmittels","woraus besteht das heilmittel","bathranshaar"}},{q="Warum haben die Heiler von Astranaar das Heilmittel nicht selbst gebraut?",a="Relaras Leiden widerstand den üblichen Heilmitteln von Astranaar, weshalb Pelturas das botanische Fachwissen von Orendil Rundblatt suchte. Orendil weiß, wie man mit den wirkkräftigen Pflanzen des nördlichen Eschentals umgeht.",al={"warum orendil","warum astranaars heiler scheiterten","warum rundblatt"}}},fx={["49e0bc34"]={q="Warum möchte Orendil Rundblatt, dass dies getan wird?",a="Orendil Rundblatt ist ein geschickter Kräuterkundiger, der weiß, dass Pelturas Weißmonds jungem Kind, Relara, die Zeit davonläuft. Orendil hat erfolgreich eine Mischung aus der seltenen Pflanze Bathranshaar hergestellt und möchte, dass das Heilmittel unverzüglich nach Astranaar geliefert wird, um das tödliche Leiden des Kindes zu stoppen und ihr Leben zu retten.",al={"warum schickt orendil das heilmittel","motiv von orendil rundblatt","warum relara helfen"}}},fp="14,124,18.193.0,27.237.0,17.228.1,25.154.0,26.142.0,36.177.0,43.171.1,47.118.0,62.199.0"}
P.entries["quest:1021"] = {n="Elende Satyrn! Die Dryaden sind in Gefahr!",s="Im Eschental wartet Illiyana auf Nachricht von ihren Schwestern, die seit ihrem Aufbruch zur Bergung eines gestohlenen Relikts vermisst werden. Sie bittet vorbeiziehende Reisende der Allianz, sie in den verderbten Ruinen von Xavian zu finden.",h="Im Eschental wartet Illiyana auf Nachricht von ihren Schwestern, die seit ihrem Aufbruch zur Bergung eines...",kw={"anilia","eschental","zweig des cenarius","cenarius","dryade","illiyana","satyr","xavian"},ang={["class:Druid"]="Als Druide teilt Ihr eine tiefe Verbundenheit mit den Kindern des Cenarius. Ihr habt geschworen, die dämonische Verderbnis zu läutern, die sich von Satyrhochburgen wie Xavian ausbreitet.",["faction:Alliance"]="Als Reisender der Allianz stärkt Ihr die Bande der Allianz zu den mystischen Bewohnern des Eschentals, wenn Ihr Illiyana angesichts wachsender Bedrohungen in der Region helft.",["race:NightElf"]="Als Nachtelf seid Ihr mit den Dryaden verbunden, den Töchtern des Cenarius. Ihre Not und die Entweihung uralter Elfentempel in Xavian appellieren an Eure Ehre und Eure spirituelle Pflicht."},sec={{t="Eine verzweifelte Schwester",b="Die Dryade Illiyana wartet im Eschental und bangt um ihre Schwestern. Sie zogen in die verderbten nördlichen Ausläufer des Waldes, um den Zweig des Cenarius zurückzuholen, ein von Satyrn gestohlenes heiliges Relikt. Sie versprachen, rasch zurückzukehren, doch seit zwei Tagen fehlt jede Nachricht. Daher bittet Illiyana vorbeiziehende Reisende der Allianz, sie zu finden, bevor es zu spät ist."},{t="Die Ruinen von Xavian",b="Xavian liegt im Nordosten, eine uralte Tempelanlage der Nachtelfen, die schon lange von der Brennenden Legion verderbt ist. Von Teufelsmagie befleckte Satyrn wimmeln durch die Ruinen und machen die Suche gefährlich. Tief im Inneren liegt Anilia, die Anführerin der Dryadenexpedition, schwer verwundet und dem Tode nahe, nachdem die dämonischen Bewohner sie angegriffen haben."}},faq={{q="Wer ist Illiyana?",a="Illiyana ist eine Dryade, die im Eschental lebt. Aus Sorge um ihre Schwestern bittet sie Reisende, in Xavian nach ihnen zu suchen.",al={"illiyana","wer vergibt elende satyrn die dryaden sind in gefahr","questgeber"}},{q="Was ist der Zweig des Cenarius?",a="Der Zweig des Cenarius ist ein heiliges Relikt, das Dryaden und Nachtelfen viel bedeutet. Satyrn im nördlichen Eschental haben ihn gestohlen, und Anilia und ihre Schwestern zogen nach Xavian, um ihn zurückzuholen.",al={"zweig des cenarius","welches relikt suchten sie","dryadenartefakt"}},{q="Was ist Xavian?",a="Xavian ist ein uralter Tempel der Nachtelfen im östlichen Eschental. Dämonische Satyrn haben seine Ruinen überrannt, wo die Verderbnis durch Teufelsmagie die Beschützer der Natur bedroht.",al={"xavian","ruinen von xavian","wo sind die dryaden"}},{q="Wer ist Anilia?",a="Anilia ist die Dryade, die den Suchtrupp anführte, um den Zweig des Cenarius von den Satyrn zurückzuholen. Illiyana bittet Reisende, sie in Xavian zu finden.",al={"anilia","vermisste dryadenanführerin","wo ist anilia"}},{q="Warum stehen die Dryaden im Konflikt mit den Satyrn?",a="Dryaden sind Töchter des Halbgottes Cenarius und widmen sich dem Schutz der Natur und dem Gleichgewicht des Waldes. Satyrn sind uralte Nachtelfen, die durch dämonische Teufelsmagie entstellt wurden, und sie verderben die Wildnis und entweihen heilige Haine.",al={"warum hassen dryaden satyrn","krieg zwischen dryaden und satyrn","verderbnis der satyrn"}},{q="Welche Quest folgt auf diese?",a="Mit dem Auffinden Anilias endet die Suche und führt zu ‚Der Zweig des Cenarius‘, wo die Bemühungen zur Bergung des gestohlenen Relikts weitergehen.",al={"nächste quest","questreihe die dryaden sind in gefahr","nach elende satyrn"}}},fx={a04fd548={q="Warum benötigt Illiyana Hilfe bei der Suche nach ihren Schwestern?",a="Illiyana fürchtet um ihre Schwestern. Anilia führte eine Schar Dryaden nach Nordosten in die verderbten Ruinen von Xavian, um ein heiliges Relikt, den Zweig des Cenarius, von den Satyrn zurückzuholen. Sie versprachen, rasch zurückzukehren, doch zwei Tage sind ohne jede Nachricht vergangen. Aus Sorge, sie könnten in einen Hinterhalt geraten sein oder von den finsteren Kreaturen überwältigt worden sein, die in den Ruinen lauern, benötigt Illiyana dringend jemanden, der fähig ist, Xavian zu trotzen, um sie aufzuspüren und zu sehen, ob eine von ihnen noch lebt.",al={"warum schickt illiyana euch aus","illiyanas beweggrund","warum anilia suchen"}}},fp="29,186,18.337.0,19.300.1,16.117.0,31.172.0,15.152.0,14.142.1,46.224.0,28.132.1"}
P.entries["quest:1022"] = {n="Das Heulende Tal",s="Worgen haben einen verfallenen Schrein im Heulenden Tal nahe dem Teufelswald überrannt. Schildwache Melyria Frostschatten sucht nach dem Grund für ihre Ankunft im Eschental.",h="Worgen haben einen verfallenen Schrein im Heulenden Tal nahe dem Teufelswald überrannt.",kw={"eschental","teufelswald","das heulende tal","mel'thandris","melyria frostschatten","sichel von elune","terrowulf","buch von mel'thandris","velinde starsong","worgen"},ang={["class:Priest"]="Als Priester erlebt Ihr die Suche nach Priesterin Velinde Sternensang womöglich als ernüchternde Geschichte der Hingabe an Elune.",["faction:Alliance"]="Als Mitglied der Allianz sucht Ihr nach dem Ursprung der furchterregenden Worgen, die im nördlichen Kalimdor und in den Östlichen Königreichen umherstreifen.",["race:NightElf"]="Als Nachtelf berührt die Entweihung des Schreins von Mel'Thandris Eure Pflicht, das Eschental zu schützen. Die Visionen von Priesterin Velinde Sternensang gewähren einen traurigen Einblick in diese Bürde."},sec={{t="Eine unheimliche Gegenwart",b="Worgenschreie hallen aus einem verfallenen Schrein im nördlichen Eschental. Hinter einem Höhlenpfad nahe der Grenze zum Teufelswald liegt der überrannte Schrein von Mel'Thandris. Schildwache Melyria Frostschatten fürchtet, die Worgen könnten weiteres Unheil über das Waldreich bringen. Die Schildwachen der Nachtelfen wenden bereits große Mühe auf, um die dämonische Verderbnis aus dem Teufelswald zurückzuhalten."},{t="Die lebendige Chronik",b="Melyria schickt Suchende zum überrannten Schrein, um das Buch von Mel'Thandris zu befragen. Mel'Thandris segnete seine Seiten, damit sie bedeutsame Ereignisse festhalten. Wird das Buch inmitten der feindseligen Worgen geöffnet, beschwört es eine geisterhafte Vision von Priesterin Velinde Sternensang. Die Vision enthüllt ihre verhängnisvolle Anrufung der geheimnisvollen Sichel von Elune."}},faq={{q="Wo liegt das Heulende Tal?",a="Das Heulende Tal liegt im nördlichen Zentrum des Eschentals, unmittelbar südwestlich der Grenze zum Teufelswald. Ein Höhlengang führt in das Tal und zum verfallenen Schrein von Mel'Thandris.",al={"heulendes tal lage","wie gelangt man ins heulende tal","wo ist der schrein von mel'thandris"}},{q="Was sind die Wolfsmenschen im Tal?",a="Die Wolfsmenschen sind Worgen, genauer gesagt Mitglieder des Terrowulf-Rudels. Diese wilden, widernatürlichen Bestien gehen auf zwei Beinen und erschienen plötzlich in Kalimdor, wo sie die Ruinen nahe der Grenze zum Teufelswald heimsuchen.",al={"wolfsmenschen eschental","was sind die monster im heulenden tal","terrowulf worgen"}},{q="Was ist das Buch von Mel'Thandris?",a="Das Buch von Mel'Thandris ist ein verzaubertes Relikt in den Schreinruinen. Mel'Thandris segnete seine Seiten, damit sie entscheidende Ereignisse festhalten und jenen, die das Buch studieren, als Visionen zeigen.",al={"buch von melthandris","was bewirkt das buch","mel'thandris buch"}},{q="Wer war Velinde Sternensang?",a="Velinde Sternensang war eine Nachtelfenpriesterin, die am Kampf gegen Dämonen nahe dem Teufelswald beteiligt war. Das Buch von Mel'Thandris könnte mehr über ihre Geschichte enthüllen.",al={"velinde starsong","priesterin velinde","wer ist der geist im buch"}},{q="Wer vergibt diese Quest?",a="Schildwache Melyria Frostschatten erteilt den Auftrag am Schrein von Aessina im Eschental. Die dämonischen Vorstöße aus dem Teufelswald und das unerklärliche Auftauchen der Worgen in der Nähe beunruhigen sie.",al={"wer startet das heulende tal","heulendes tal questgeber","melyria frostschatten"}},{q="Warum kümmert sich Schildwache Melyria um den Schrein?",a="Die Schildwachen im Eschental schützen das Land vor der Verderbnis aus dem Teufelswald. Wolfsmenschen hatten eine uralte heilige Stätte der Nachtelfen nahe der Grenze eingenommen, und die Schildwachen mussten herausfinden, ob Dämonen dahintersteckten oder eine neue Gefahr aufgetaucht war.",al={"warum das heulende tal untersuchen","forest song schildwachen"}}},fp="16,145,19.337.0,20.319.1,34.164.0,34.196.0,33.171.0,25.151.1,21.171.0,48.220.0"}
P.entries["quest:1023"] = {n="Raenes Säuberung",s="Am Falathimsee ist Raene Wolfsläufers Suche nach Teronis zur Suche nach dem geworden, was er hinterlassen hat. Ihr sollt ihr sein Tagebuch und einen leuchtenden Edelstein, den die Murlocs besitzen, nach Astranaar bringen.",h="Am Falathimsee ist Raene Wolfsläufers Suche nach Teronis zur Suche nach dem geworden, was er hinterlassen hat.",kw={"eschental","astranaar","leuchtender edelstein","falathimsee","murloc","raenes säuberung","schildwachen","teronis"},ang={["faction:Alliance"]="Als Mitglied der Allianz helft Ihr Raene Wolfsläufer und den Schildwachen, von Astranaar aus die nördlichen Zugänge zum Eschental zu verteidigen.",["race:NightElf"]="Als Nachtelf wisst Ihr, dass der Tod eines Kameraden der Schildwachen am Falathimsee auf eine Gefahr hinweist, die sich Kalimdors uralten heiligen Hainen nähert."},sec={{t="Ein gefallener Späher",b="Raene Wolfsläufer hat Euch zum Falathimsee geschickt, um Teronis zu finden, einen Nachtelfen der Schildwachen. Ihr findet ihn tot am Wasser. Sein Tagebuch ist unversehrt und berichtet von seinem Auftrag und seinen Erkenntnissen über die seltsamen Unruhen im Eschental."},{t="Der Leuchtende Edelstein",b="Teronis verfolgte die Spur eines seltenen, leuchtenden Steins bis zum Falathimsee. Nun besitzen ihn die aggressiven Murlocs des Sees. Bergt den Edelstein und Teronis' Tagebuch, damit seine Arbeit fortgesetzt werden kann."},{t="Trauer in Astranaar",b="Raene Wolfsläufer trauert, als Ihr mit der Nachricht über Teronis nach Astranaar zurückkehrt. Sie muss eine Patrouille zusammenstellen, um den Leichnam ihres gefallenen Kameraden zu bergen, während Verderbnis den Wald bedroht.\n\nRaene bittet Euch, Teronis' Arbeit fortzusetzen und den Stab wiederherzustellen, der, so hoffte er, die Angriffe der Furbolgs verlangsamen würde."}},faq={{q="Wer war Teronis?",a="Teronis war ein Nachtelfenspäher, den Raene Wolfsläufer von Astranaar aus entsandte, um den Falathimsee zu untersuchen und einen mystischen Edelstein sicherzustellen. Feindselige Wildtiere töteten ihn, bevor er seinen Auftrag erfüllen konnte.",al={"teronis","wer ist teronis","teronis geschichte"}},{q="Wo findet sich der Leuchtende Edelstein?",a="Murlocs im und am Falathimsee im nordwestlichen Eschental tragen den Leuchtenden Edelstein bei sich, nahe der Stelle, an der Teronis' Leichnam gefunden wurde.",al={"wo ist der leuchtende edelstein","leuchtender edelstein fundort","leuchtenden edelstein finden"}},{q="Warum widmet sich Raene Wolfsläufer dieser Aufgabe so sehr?",a="Teronis war Raenes langjähriger Freund, und er glaubte, der Stab könne die Angriffe der Furbolgs auf ihr Volk verlangsamen. Noch immer überfallen Furbolgs das Eschental, daher widmet sich Raene seiner unvollendeten Arbeit trotz seines Todes mit großer Dringlichkeit.",al={"warum raenes säuberung","raene wolfsläufer beweggrund"}},{q="Was geschieht nach dieser Quest mit Teronis' Leichnam?",a="Raene Wolfsläufer verspricht, eine Abteilung der Schildwachen aus Astranaar zu entsenden, um Teronis' sterbliche Überreste für die Trauerfeier und die traditionellen Bestattungsriten der Nachtelfen zu bergen.",al={"teronis leichnam schicksal","was geschieht mit teronis"}},{q="Wozu dient Teronis' Tagebuch?",a="Teronis' Tagebuch dokumentiert seine Nachforschungen über Dartol, einen menschlichen Magier, der mit druidischer Magie versuchte, sich mit den Furbolgs anzufreunden und sie zu kontrollieren. Es enthält auch seine Notizen zur Bergung der Teile von Dartols Stab.",al={"teronis' tagebuch","was ist das tagebuch"}},{q="Geht diese Questreihe nach der Abgabe weiter?",a="Ja. Wenn Ihr Raene Wolfsläufer den Edelstein und das Tagebuch bringt, bittet sie Euch, Teronis' Arbeit fortzusetzen und die übrigen Teile von Dartols Stab zu suchen.",al={"questfortschritt","nächste quest nach teronis"}}},fx={["699dfe26"]={q="Warum ist es wichtig, Teronis' Tagebuch und den Edelstein zu finden?",a="Teronis kam ums Leben, bevor er die wichtige Aufgabe erfüllen konnte, die ihm von Astranaar anvertraut wurde. Indem Ihr sein unversehrtes Tagebuch bergt und den Leuchtender Edelstein aus den nahegelegenen Gewässern sichert, stellt Ihr sicher, dass sein Opfer nicht umsonst war, und ermöglicht es Raene Wolfsläufer, seine Reinigungsmission zu verstehen und fortzuführen.",al={"warum teronis' tagebuch finden","warum leuchtender edelstein bergen","motiv von teronis quest"}},["9d747809"]={q="Was ist der Leuchtender Edelstein?",a="Der Leuchtender Edelstein ist ein verzauberter Stein, den Teronis bis zum Falathimsee verfolgte, bevor er sein Ende fand. Das strahlende Relikt, das von Raene Wolfsläufer für ihre Reinigungsbemühungen heiß begehrt wird, wurde von den aggressiven Murlocs des Sees geplündert und muss zurückerobert werden, um Teronis' heilige Pflicht wieder aufzunehmen.",al={"was ist der leuchtender edelstein","leuchtender edelstein lore","warum leuchtender edelstein"}},a4b5e1af={q="Warum halten die Murlocs am Falathimsee den Edelstein fest?",a="Die Murlocs mit den üblen Flossen, die die Ufer und Gewässer des Falathimsees befallen, plündern alles Schimmernde oder Mächtige, das in ihr Territorium gespült wird. Nach Teronis' Tod am Rande des Sees schnappten sich diese wilden Kreaturen schnell den strahlenden Stein und bewachen ihn nun erbittert in ihren Klauen.",al={"warum haben murlocs den edelstein","murlocs falathimsee","falathimsee murlocs"}}},fp="17,193,14.234.0,15.162.0,18.282.1,16.186.0,31.121.0,48.208.0,47.156.0,29.202.0,51.146.0"}
P.entries["quest:1024"] = {n="Raenes Säuberung",s="Im Eschental sucht Raene Wolfsläufer nach einem Weg, Dartols uralten Stab wiederherzustellen. Ein Leuchtender Edelstein hat sie zu Shael'dryn geführt, einer Dryade östlich des Irissees.",h="Im Eschental sucht Raene Wolfsläufer nach einem Weg, Dartols uralten Stab wiederherzustellen.",kw={"eschental","dartols stab","leuchtender edelstein","irissee","mondbrunnen","raene wolfsläufer","raenes säuberung","shael'dryn","teronis"},ang={["class:Druid"]="Als Druide erfüllt Ihr mit Eurer Hilfe für Shael'dryn Eure Cenarion-Pflicht, die zerrissenen Bande zwischen der Natur und der Magie der Kaldorei zu erneuern.",["faction:Alliance"]="Als Mitglied der Allianz unterstützt Ihr die Kriegsanstrengungen gegen wachsende Bedrohungen in der Region, indem Ihr uralte Artefakte sichert und Astranaars nördliche Verteidigung stärkt.",["race:NightElf"]="Die Wiederherstellung des Stabs führt Teronis' unvollendete Untersuchung der Probleme der Furbolgs des Eschentals fort."},sec={{t="Ein Hinweis in Teronis' Notizen",b="Raene Wolfsläufer studiert die Feldnotizen von Teronis, der Schildwache, die bei der Untersuchung der beunruhigten Furbolgs des Eschentals starb. Seine Arbeit deutet auf einen uralten Stab hin, den ein Nachtelf namens Dartol gefertigt hat. Raene hat einen Leuchtenden Edelstein gefunden, doch ihr Können als Jägerin reicht nicht aus, um die arkanen und natürlichen Geheimnisse des Relikts zu ergründen."},{t="Suche nach den Daughters of Cenarius",b="Raene schickt Euch nach Nordosten zum Irissee, um Shael'dryn zu finden, eine Dryade, die an einem Mondbrunnen lebt. Als eine der Daughters of Cenarius versteht Shael'dryn den Wald und seine uralten Relikte. Bringt ihr den Leuchtenden Edelstein, und vielleicht verrät sie Euch, was noch benötigt wird, um Dartols Stab wiederherzustellen."}},faq={{q="Wer war Teronis?",a="Teronis war ein Nachtelfenspäher, der von Astranaar ausgesandt wurde, um die Verderbnis zu untersuchen, die sich im Eschental ausbreitete. Er starb auf dieser Mission, doch sein Tagebuch lieferte einen Hinweis: Die Wiederherstellung von Dartols Stab könnte dem Land helfen.",al={"teronis","teronis' notizen","wer ist teronis"}},{q="Was ist Dartols Stab?",a="Dartols Stab ist ein uraltes magisches Artefakt, von dem Raene Wolfsläufer sich Hilfe bei ihrer Untersuchung der Furbolgs des Eschentals erhofft. Der Leuchtende Edelstein, den sie geborgen hat, ist eines der Teile, die zu seiner Wiederherstellung benötigt werden.",al={"dartols stab","was ist der stab","stab von dartol"}},{q="Wo kann ich Shael'dryn finden?",a="Shael'dryn lebt an einem abgeschiedenen Mondbrunnen nordöstlich von Astranaar, in den Hügeln unmittelbar östlich des Irissees. Folgt der Straße nach Osten und biegt dann nach Norden ab, bevor Ihr die gefährlichen Gebiete nahe Rajenbaum erreicht.",al={"wo ist shael'dryn","shaeldryn fundort","dryade finden"}},{q="Was ist der Leuchtende Edelstein?",a="Der Leuchtende Edelstein ist ein Teil von Dartols Stab und wurde aus den Ruinen geborgen, in denen Teronis Nachforschungen anstellte. Shael'dryn benötigt ihn, um herauszufinden, welche weiteren Teile für den Stab gebraucht werden.",al={"leuchtender edelstein","wozu dient der edelstein","teronis edelstein"}},{q="Warum schickt Raene Wolfsläufer Euch zu einer Dryade?",a="Raene Wolfsläufer ist eine Jägerin und Anführerin der Schildwachen von Astranaar, entschlossen, die Stadt zu verteidigen. Dryaden, die Daughters of Cenarius, verstehen uralte Relikte und die Wiederherstellung der Natur.",al={"warum eine dryade aufsuchen","raene wolfsläufer dryade","warum shael'dryn"}},{q="Warum ist der Wald um den Irissee in Gefahr?",a="Verderbnis und Unruhe breiten sich unter den Wildtieren und Furbolgstämmen des Eschentals aus. Raene hofft, durch die Wiederherstellung des Stabs die Notlage der Furbolgs zu verstehen.",al={"eschental verderbnis","warum ist das eschental verderbt","irissee gefahr"}}},fx={["3ee5b81a"]={q="Warum muss Raene, dass Ihr den Edelstein zu Shael'dryn bringt?",a="Als Jägerin und Anführerin, die in Astranaar stationiert ist, ist Raene Wolfsläufer an die Koordination der Verteidigung des Eschentals gegen zunehmende dämonische und territoriale Bedrohungen gebunden. Sie kann ihren Posten nicht verlassen, um sich in obskure magische Forschungen zu vertiefen oder zu entfernten Mondbrunnen zu reisen. Da Ihr Teronis' Tagebuch und den Edelstein von den Murlocs geborgen habt, vertraut sie Euch, die Arbeit des gefallenen Spähers zu Ende zu bringen.",al={"warum schickt ihr mich zu shael'dryn","warum geht raene nicht selbst","warum ich raenes reinigung"}}},fp="17,147,25.303.0,33.287.0,16.207.0,21.183.0,28.193.0,24.166.0,46.189.0,45.159.0"}
P.entries["quest:1025"] = {n="Eine aggressive Verteidigung",s="In Eschental schickt Raene Wolfsläufer Verteidiger der Allianz gegen die Furbolgs der Foulweald. Verderbnis hat den Stamm entlang der Straße östlich von Astranaar gefährlich gemacht.",h="In Eschental schickt Raene Wolfsläufer Verteidiger der Allianz gegen die Furbolgs der Foulweald.",kw={"eschental","astranaar","falfarren","foulweald","furbolg","raene wolfsläufer","schildwachen"},ang={["class:Druid"]="Als Druide seht Ihr im Wahnsinn der Foulweald ein Warnzeichen für den Makel der Teufelsmagie in Kalimdors heiliger Wildnis.",["faction:Alliance"]="Als Verteidiger der Allianz helft Ihr, die Straße von Astranaar zu den östlichen Außenposten für Nachschub und Reisende freizuhalten.",["race:NightElf"]="Als Kaldorei steht Ihr vor der bitteren Notwendigkeit, gegen einstige Verwandte des Waldes zu kämpfen, deren Verstand der Verderbnis verfallen ist."},sec={{t="Bedrohung der Hauptstraße",b="Furbolgs greifen Reisende auf der Straße an, die von Astranaar nach Osten zum Falfarren führt. Schildwache Raene Wolfsläufer schickt fähige Verteidiger aus, um die Lager der Foulweald unmittelbar südlich der Hauptstraße anzugreifen. Ihre Angriffe haben diese lebenswichtige Straße durch Eschental für alle gefährlich gemacht, die sie bereisen."},{t="Eine bittere Vergangenheit",b="Die Foulweald waren einst Freunde und Verbündete der Nachtelfen. Seit uralten Zeiten teilten Kaldorei und Furbolgs die Ehrfurcht vor der Natur und den wilden Göttern. Die Invasion der Brennenden Legion hinterließ einen Makel, der den Verstand vieler Furbolgs zerrüttete. Friedliche Nachbarn wurden zu gewalttätigen Räubern, und unschuldige Reisende sind nun ihren Angriffen ausgesetzt."}},faq={{q="Wer vergibt diese Aufgabe und wo ist diese Person zu finden?",a="Schildwache Raene Wolfsläufer leitet die Verteidigung von Astranaar aus, der wichtigsten Siedlung der Nachtelfen im Herzen von Eschental.",al={"questgeber","wer vergibt eine aggressive verteidigung","raene wolfsläufer standort"}},{q="Warum sind die Furbolgs in Eschental feindselig?",a="Die Foulweald verfielen dem dämonischen Makel, den die Brennende Legion während des Dritten Krieges hinterließ. Ihr Verstand wurde von Gewalt erfüllt, was sie dazu trieb, Reisende und ehemalige Verbündete anzugreifen.",al={"warum sind furbolgs wahnsinnig","foulweald feindselig","furbolg verderbnis"}},{q="Wo befinden sich die Lager der Foulweald?",a="Die Lager der Foulweald liegen südlich der Hauptstraße, die von Astranaar nach Osten führt, westlich des Falfarren.",al={"foulweald standort","wo foulweald finden","wo sind die furbolgs"}},{q="Waren die Furbolgs schon immer Feinde der Nachtelfen?",a="Nein. Furbolgs und Nachtelfen lebten Jahrtausende lang Seite an Seite in Harmonie. Dämonische Verderbnis in Eschental und im Teufelswald trieb Stämme wie die Foulweald zur Feindseligkeit.",al={"furbolg nachtelfen hintergrundgeschichte","waren furbolgs gut","kaldorei und furbolgs"}},{q="Hängt diese Quest mit anderen Ereignissen in Astranaar zusammen?",a="Raenes Angriff ist ein Teil der Verteidigung Astranaars. Sie weist Verteidiger auch an, verderbte Mondbrunnen zu untersuchen und bei der Reinigung des Waldes zu helfen.",al={"questvoraussetzungen","raene reinigung zusammenhang"}},{q="Welche Furbolgs müssen genau getötet werden?",a="Raene verlangt, dass ein Foulweald Den Watcher, zwei Ursas, zehn Totemics und zwölf Krieger getötet werden. Das wird die Führung des Stammes nahe der Straße zerschlagen.",al={"questziele","wer muss getötet werden","foulweald ziele"}}},fx={bc4e30a1={q="Warum will Raene Wolfsläufer, dass die Foulweald-Furbolgs dezimiert werden?",a="Korrumpierte Foulweald-Furbolgs haben südlich der Straße, die nach Osten zum Falfarren führt, Lager aufgeschlagen. Durch den verseuchten Zustand des Waldes in den Wahnsinn getrieben und bösartig geworden, jagen sie Reisende und unschuldige Wanderer. Raene muss ihre aggressive Anzahl verringern, um die Straße zu sichern und den Druck auf die überlasteten Verteidiger von Astranaar zu verringern.",al={"warum foulweald töten","motiv von raene wolfsläufer","warum aggressive verteidigung"}},bea6b71d={q="Wer sind die Foulweald-Furbolgs, gegen die Ihr kämpfen sollt?",a="Die Foulweald sind ein lokaler Stamm von Furbolgs, die im Eschental leben und deren Geist den dunklen, korrumpierenden Energien verfallen ist, die durch das Waldgebiet sickern. Einst zurückgezogene Nachbarn der Nachtelfen, manifestiert sich ihr Wahnsinn nun in blutrünstiger Raubgier, was sie dazu veranlasst, Reisende entlang der Straße östlich von Astranaar zu überfallen.",al={"wer sind foulweald furbolgs","was sind die foulweald","wer sind die ziele"}}},fp="21,161,21.283.0,16.313.0,48.118.0,42.164.0,36.96.0,52.172.0,53.141.0,42.151.0"}
P.entries["quest:1026"] = {n="Raenes Säuberung",s="Im Eschental bringt Raenes Säuberung Dartols Rute ihrer Wiederherstellung näher. Shael'dryn weiß, wo ihr Eisenschaft liegt: in einer Truhe nahe der Grenze zum Teufelswald. Die Suche führt zu Treants, die von Verderbnis verändert wurden.",h="Im Eschental bringt Raenes Säuberung Dartols Rute ihrer Wiederherstellung näher.",kw={"eschental","wahnsinniger uralter","dartols rute","teufelswald","eisenschaft","mondbrunnen","raenes säuberung","shael'dryn","verdorrter uralter","holzschlüssel"},ang={["class:Druid"]="Der Wahnsinn der Uralten, ausgelöst durch die vordringende Verderbnis des Teufelswalds, erinnert an das Ringen des Smaragdgrünen Traums, die verwundete Oberflächenwelt zu heilen.",["faction:Alliance"]="Dartols Relikt wiederherzustellen ist unerlässlich, um die Straßen im nördlichen Eschental gegen zunehmende Angriffe verderbter Furbolgs und dämonischer Streitkräfte zu sichern.",["race:NightElf"]="Die Wahnsinnigen Uralten zu töten ist qualvoll. Diese lebenden Bäume waren geliebte Gefährten und Hüter des Waldes, bevor die dämonische Verderbnis ihre Geister vergiftete."},sec={{t="Ein Bruchstück nahe der Verderbnis",b="Raene Wolfsläufer schickt Euch zu Shael'dryn, einer Wächterin, die tief im Eschental über einen Mondbrunnen wacht. Shael'dryn weiß, wo der Eisenschaft von Dartols Rute liegt. Um ihn zu erreichen, müsst Ihr Euch der Verderbnis stellen, die sich in den nördlichen Wäldern ausbreitet. Der Schaft ruht in einer alten Truhe auf einer stillen Lichtung nahe der Grenze zum Teufelswald."},{t="Die gefallenen Wächter",b="Ein Holzschlüssel öffnet die Truhe, und Wahnsinnige und Verdorrte Uralte tragen ihn bei sich. Diese Treants wandern auf der Bergstraße nach Norden in Richtung Teufelswald. Verderbnis aus den dämonischen Ödlanden breitet sich nach Süden aus und hat ihre natürliche Harmonie zerstört. Einst waren sie Wächter der Wildnis, nun sind sie gequält und feindselig. Der Schlüssel ist in ihrem Besitz."}},faq={{q="Wer ist Shael'dryn?",a="Shael'dryn ist eine Dryade an einem abgelegenen Mondbrunnen im Eschental, östlich von Astranaar und südlich der Straße zum Teufelswald. Sie kennt die Geschichte des Waldes und Dartols uralte Handwerkskunst und berät jene, die versuchen, die Rute wiederherzustellen.",al={"shaeldryn","wer ist die wächterin des mondbrunnens","shael'dryns geschichte"}},{q="Warum sind die Treants verderbt?",a="Dämonische Verderbnis aus dem Dritten Krieg breitet sich noch immer vom Teufelswald nach Süden ins Eschental aus. Sie entstellt die Treants entlang der nördlichen Bergrücken, treibt die uralten Beschützer in den Wahnsinn und verdreht ihre Verbindung zum Land.",al={"verderbte treants","warum sind treants wahnsinnig","geschichte der wahnsinnigen uralten"}},{q="Was ist Dartols Rute?",a="Dartols Rute ist ein verzaubertes Relikt, geschaffen von Dartol, einem inzwischen verstorbenen bösen Zauberer. Zusammengesetzt und gereinigt kann sie ihren Träger als Furbolg tarnen, eine Macht, die Raene braucht, um die örtlichen Stämme zu erforschen.",al={"dartols rute","rute der transformation","was bewirkt die rute"}},{q="Wo befindet sich die versteckte Truhe?",a="Die abgenutzte Truhe mit dem Eisenschaft ruht auf einer kleinen, stillen Lichtung unmittelbar westlich der Bergstraße, die vom Eschental nordwärts zum Teufelswald hinaufführt.",al={"fundort der abgenutzten truhe","wo ist der eisenschaft","wo ist die truhe"}},{q="Warum trauert Shael'dryn um die Treants?",a="Shael'dryn trauert um die Treants, weil sie zeitlose Hüter der Wälder der Kaldorei sind, verehrt als heilige Naturgeister. Für ihren Wahnsinn und ihre Verderbnis ist kein Heilmittel bekannt, weshalb es Trauer bereitet, sie zu töten, und nicht aus Bosheit geschieht.",al={"shaeldryn treants","warum ist shaeldryn traurig"}},{q="Wie fügt sich diese Aufgabe in die größere Säuberungsquestreihe ein?",a="Raenes Säuberung dient dazu, die Bruchstücke von Dartols zerbrochener Rute zusammenzutragen. Sobald der Eisenschaft und die anderen Teile beisammen sind, gilt es, die Rute von der ihr noch anhaftenden Magie zu reinigen.",al={"raenes säuberungsquestreihe","raenes questreihe"}}},fx={["348d2e5e"]={q="Was ist der Eisenschaft?",a="Der Eisenschaft ist eine Schlüsselkomponente von Dartols Rute der Transformation, einem uralten Relikt, dessen Magie es seinem Träger ermöglicht, die Gestalt eines Furbolgs anzunehmen. Die Teile der Rute wurden verstreut, und dieses metallische Segment wurde in einer versteckten Truhe nahe der Grenze zum Teufelswald eingeschlossen.",al={"was ist der eisenschaft","eisenschaft dartol","eisenschaft raenes reinigung"}},["410ea010"]={q="Wofür ist der Holzschlüssel?",a="Der Holzschlüssel öffnet die abgenutzte, versteckte Truhe nahe der Grenze zum Teufelswald, die ein Teil von Dartols Rute der Transformation enthält. Der Schlüssel, der lange den Wächtern der Lichtung anvertraut war, befindet sich immer noch im Besitz der uralten Treants, die inzwischen dem Wahnsinn und der Fäulnis anheimgefallen sind.",al={"was macht der holzschlüssel","zweck des holzschlüssels","warum wird der holzschlüssel benötigt"}},["8a6f94e5"]={q="Warum müsst Ihr gegen die Treants um den Schlüssel kämpfen?",a="Die verdorrten und wahnsinnigen Uralten im Nordosten nahe der Grenze zum Teufelswald waren einst edle Beschützer des Waldes, aber die dämonische Verderbnis, die aus dem Norden sickert, hat ihren Geist zerrüttet. Shael'dryn betrauert ihren Fall, doch da ihre Natur über alle Vernunft hinaus verdreht ist, kann der Schlüssel, den sie bewachen, nur mit Gewalt zurückgewonnen werden.",al={"warum treants töten","warum sind wahnsinnige uralte feindselig","warum verdorrte uralte angreifen"}}},fp="17,207,26.301.0,20.315.0,18.218.0,30.199.0,21.197.1,34.147.0,38.225.0,54.175.0"}
P.entries["quest:1027"] = {n="Raenes Säuberung",s="Im Eschental suchen Raene Wolfsläufer und Shael'dryn das letzte Stück von Dartols Stab. Sie hoffen, dass das Relikt den Wald reinigen und die Angriffe der Furbolgs auf seine Nachtelfen verlangsamen kann.",h="Im Eschental suchen Raene Wolfsläufer und Shael'dryn das letzte Stück von Dartols Stab.",kw={"eschental","dartols stab","dor'danil","eisenschwertknauf","mondbrunnen","raenes säuberung","shael'dryn"},ang={["class:Druid"]="Als Druide seht Ihr beim Besuch der entweihten Stätten von Dor'Danil, welche Verluste der Zirkel des Cenarius und die Kaldorei-Druiden im Eschental erlitten haben.",["faction:Alliance"]="Als Mitglied der Allianz wisst Ihr, dass die Verteidigung des Eschentals gegen Verderbnis für den Einfluss der Allianz im nördlichen Kalimdor entscheidend ist, während Streitkräfte der Horde von Splintertree aus vorrücken.",["race:NightElf"]="Als Nachtelf ehrt Ihr mit der Bergung von Dartols Erbstück die gefallenen Hüter von Dor'Danil und die Verteidigung der uralten Ländereien der Kaldorei."},sec={{t="Die Ruinen von Dor'Danil",b="Im Dor'danil-Grabhügel bewachten Nachtelfendruiden den Eisenschwertknauf von Dartols Stab. Eine Katastrophe brach herein, und die Druiden wurden erschlagen. Ihr Zufluchtsort fiel, und das Versteck des Knaufs geriet in Vergessenheit. Nun verschlingen Aasfresser und umherwandernde Schlicke alles, was in den Ruinen östlich der südlichen Straße übrig geblieben ist."},{t="Dartols Vermächtnis wiederherstellen",b="Dartol war ein böser Zauberer, und er ist gestorben. Doch der Stab, den er erschuf, birgt Kräfte, die Verwandlungen bewirken können. Raene Wolfsläufer und Shael'dryn wollen ihn wieder zusammensetzen und hoffen, damit die Angriffe der Furbolgs auf die Nachtelfen des Eschentals zu verlangsamen. Der Eisenschwertknauf ist das letzte Stück, das Shael'dryn braucht, bevor sie versuchen kann, den zerbrochenen Stab am Mondbrunnen zu reparieren."}},faq={{q="Was ist der Eisenschwertknauf?",a="Der Eisenschwertknauf ist das letzte Stück von Dartols Stab. Ohne ihn lässt sich das Relikt weder neu schmieden noch zur Reinigung des Eschentals einsetzen.",al={"eisenschwertknauf","letztes stabstück","was ist der knauf"}},{q="Was geschah mit den Druiden von Dor'Danil?",a="Die Druiden im Dor'danil-Grabhügel wurden erschlagen, als ihr Heiligtum fiel. Schlicke und wilde Tiere suchen nun ihren verlassenen Zufluchtsort heim, und Shael'dryn fällt es schwer, über ihr Schicksal zu sprechen.",al={"dordanil druiden","wer hat die druiden getötet","dor danil"}},{q="Wo liegt Dor'Danil?",a="Dor'Danil liegt im südlichen Eschental, östlich der Hauptstraße zur Grenze des Brachlands und südlich des Splitterholzpostens.",al={"wo ist dordanil","dor danil lage"}},{q="Wer ist Shael'dryn?",a="Shael'dryn ist eine Dryade, die einen heiligen Mondbrunnen im Eschental hütet. Sie hilft Raene Wolfsläufer, die verstreuten Stücke von Dartols Stab zu finden, und leitet seine Reparatur an.",al={"shaeldryn","wer ist shaeldryn"}},{q="Warum haben Schlicke den Knauf verschlungen?",a="Nachdem der Grabhügel gefallen war, breiteten sich gallertartige Schleime in der Gegend aus und verschlangen zurückgelassene Relikte, Truhen und Leichen. Die Schlicke verschlangen den Eisenschwertknauf zusammen mit den anderen Überresten.",al={"schleim truhe","knauf schleim","warum haben schleime ihn"}},{q="Was geschieht, nachdem der Knauf gefunden wurde?",a="Wenn Ihr Shael'dryn den Knauf zurückbringt, kann sie mit der Reparatur des Stabs beginnen. Sobald er repariert ist, kann er Raene Wolfsläufer helfen, den Wald zu reinigen.",al={"nächster schritt","was macht shaeldryn"}}},fx={["414ae6aa"]={q="Warum möchte Shael'dryn, dass dies getan wird?",a="Shael'dryn unterstützt Raene Wolfsläufer bei ihren Bemühungen, das Eschental von der Verderbnis zu reinigen. Die Bergung des letzten Teils von Dartols Rute der Transformation – des Eisenschwertknauf – ist entscheidend, denn die Wiedervereinigung aller Komponenten wird es Shael'dryn ermöglichen, das uralte Artefakt zu rekonstruieren, damit es wieder zu voller Kraft zurückgeführt werden kann.",al={"warum shael'dryn helfen","motiv von shaeldryn","warum das rutenteil finden"}}},fp="17,174,22.281.0,26.328.0,24.127.0,41.175.0,27.117.0,18.155.0,37.172.0,38.136.0"}
P.entries["quest:1028"] = {n="Raenes Säuberung",s="Auf Shael'dryns Geheiß steigt Ihr zu einem Bergschrein im Südosten von Eschental hinauf. Das dortige Becken birgt die Magie, um den wieder zusammengesetzten Stab von Dartol wiederherzustellen.",h="Auf Shael'dryns Geheiß steigt Ihr zu einem Bergschrein im Südosten von Eschental hinauf.",kw={"eschental","becken","dartols stab","verborgener schrein","mondbrunnen","raenes säuberung","wieder zusammengesetzter stab","shael'dryn"},ang={["class:Druid"]="Als Druide könnt Ihr spüren, wie der Schrein mit seinem feinen Widerhall die tiefe Verbindung zwischen uralter nachtelfischer Handwerkskunst und den wilden Energien der Natur widerspiegelt.",["faction:Alliance"]="Als Mitglied der Allianz helft Ihr Raene Wolfsläufer durch die Wiederherstellung dieses Relikts, Astranaar zu sichern und die verderbten Lande im Norden Kalimdors zu heilen.",["race:NightElf"]="Als Nachtelf könnt Ihr Eschentals verborgene Bergschreine als stille Heiligtümer betrachten, die Eure Vorfahren vor den heutigen Invasionen in der Wildnis errichteten."},sec={{t="Ein Pfad in die Höhen",b="Shael'dryn schickt Euch von ihrem Mondbrunnen zu den wilden Hängen im Südosten von Eschental. Dort standen uralte Schreine oft hoch zwischen Bergklippen, fernab der Straßen und unter dichten Baumkronen verborgen. Ihr durchquert unmarkiertes Gelände entlang der Felswände und erklimmt verschlungene Pfade, die meist nur Wächterinnen und Waldeinsiedlern bekannt sind."},{t="Dartols Stab wiederherstellen",b="Ein Steinbecken wartet in einer stillen Waldnische. Obwohl der Schrein ruht, birgt er Schutzmagie, die Nachtelfen vor langer Zeit dort hinterließen. Legt den wieder zusammengesetzten Stab von Dartol in das Becken, und die schlummernde Macht des Schreins erwacht. Seine Magie fließt in den Stab und stellt dessen Verzauberung wieder her, damit er das Land reinigen kann."}},faq={{q="Wo liegt der verborgene Schrein?",a="Der Schrein liegt in den Bergen südöstlich von Shael'dryns Mondbrunnen. Verlasst die Hauptstraßen, folgt den felsigen Steilwänden und sucht nach einem gewundenen Pfad hinauf zu den Bergrücken.",al={"standort des schreins","wo ist der schrein","wie den schrein finden","pfad zum verborgenen schrein"}},{q="Wer war Dartol?",a="Dartol war ein böser Zauberer, der den Stab erschuf, und ist inzwischen tot. Raene hofft, dass seine Magie dabei hilft, die Angriffe der Furbolgs in Eschental zu untersuchen.",al={"wer ist dartol","dartols geschichte","erschaffer des stabs"}},{q="Warum muss Dartols Stab in den Schrein gelegt werden?",a="Shael'dryn konnte den zerbrochenen Stab wieder zusammensetzen, doch seine uralten Verzauberungen waren erschöpft. Der verborgene Schrein birgt unberührte Naturmagie, die seine Macht wiederherstellen kann.",al={"warum den stab aufladen","zweck des stabs","was bewirkt der schrein"}},{q="Wer ist Shael'dryn?",a="Shael'dryn ist eine Dryade, die an einem stillen Mondbrunnen im Osten von Eschental lebt. Sie hilft Raene Wolfsläufer, Relikte und Riten zu erforschen, die die verderbte Wildnis reinigen könnten.",al={"shaeldryn","questgeber","priesterin am mondbrunnen"}},{q="Was geschieht, nachdem der Stab wieder aufgeladen wurde?",a="Nachdem der Schrein die Macht des Stabs wiederhergestellt hat, könnt Ihr ihn zu Shael'dryn zurückbringen, damit er Raenes Untersuchung der Furbolgs von Eschental dient.",al={"was kommt als nächstes","nach dem schrein","nächster schritt"}},{q="Wird der Schrein bewacht?",a="Der Schrein ist ein friedliches Heiligtum, doch wilde Tiere und verderbte Furbolgstämme durchstreifen die umliegenden Berge und Wälder. Der Aufstieg ist gefährlich.",al={"gibt es gegner am schrein","gefahren am schrein"}}},fx={c5f164a1={q="Warum möchte Shael'dryn, dass Dartols Rute der Transformation aufgeladen wird?",a="Shael'dryn versucht, Dartols Rute der Transformation wiederherzustellen, um die laufende Reinigung des Eschentals zu erfüllen. Die Rekonstruktion der zerbrochenen Teile war nur der erste Schritt; ohne sie in die uralte Magie des verborgenen Bergschreins zu tauchen, bleibt die Rute ein inaktives Relikt, das nicht in der Lage ist, ihre schlummernde Transformationskraft freizusetzen.",al={"warum dartols rute aufladen","motiv von shaeldryn","warum möchte shael'dryn, dass dies getan wird"}},da3545ca={q="Warum schickt Shael'dryn Euch zum verborgenen Schrein, anstatt selbst zu gehen?",a="Shael'dryn bleibt an den Mondbrunnen am Irissee gebunden, kümmert sich um dessen heilige Gewässer und unterstützt die Verteidiger von Astranaar. Da Ihr Euren Mut bereits bewiesen habt, indem Ihr die zerbrochenen Teile von Dartols Rute der Transformation im gesamten Eschental geborgen habt, seid Ihr die Person, der sie vertraut, um die ungezähmten Bergpfade zu trotzen und den vergessenen Schrein zu finden.",al={"warum geht shael'dryn nicht selbst","warum schickt ihr mich zum schrein","warum ich shael'dryn"}}},fp="17,158,23.316.0,22.306.0,35.163.0,15.144.0,54.162.0,18.173.0,40.132.0,22.147.0"}
P.entries["quest:1029"] = {n="Raenes Säuberung",s="Am Irissee vertraut Shael'dryn Euch eine wiederhergestellte Rute für Raene Wolfsläufer in Astranaar an. Ihr bringt sie zurück, um von Eurem Erfolg zu berichten und Teronis, den gefallenen Späher, zu ehren.",h="Am Irissee vertraut Shael'dryn Euch eine wiederhergestellte Rute für Raene Wolfsläufer in Astranaar an.",kw={"eschental","astranaar","dartols rute","raene wolfsläufer","raenes säuberung","shael'dryn","teronis"},ang={["faction:Alliance"]="Wenn Ihr als Reisender der Allianz Raene Wolfsläufer helft, stärkt Ihr Euer Ansehen bei den zurückgezogen lebenden Sentinels von Astranaar.",["race:NightElf"]="Als Nachtelf bringt Ihr Astranaar Frieden, indem Ihr Teronis' Vermächtnis weitertragt, und zeigt, dass gefallene Angehörige Eures Volkes angesichts wachsender Bedrohungen für Kalimdors heilige Haine nicht vergessen sind."},sec={{t="Die wiederhergestellte Rute",b="Dartols Rute der Transformation wurde aus Komponenten und uralten Edelsteinsplittern neu geschmiedet, die in verderbten Gegenden des Eschentals gesammelt wurden. Nahe dem Irissee erneuert die Dryade Shael'dryn ihre Magie. Dann schickt sie Euch über die Waldwege nach Astranaar, wo Raene Wolfsläufer die wiederhergestellte Rute erwartet."},{t="Teronis zu Ehren",b="Teronis begann, nach Dartols Rute zu suchen, um die Angriffe der Furbolgs auf sein Volk einzudämmen. Raenes langjähriger Freund starb oben auf der Insel im Falathimsee. Murlocs hatten den Edelstein an sich genommen, den er suchte, und streckten ihn dort nieder. Die wiederhergestellte Rute zu Raene zu bringen, bedeutet einen bittersüßen Sieg und verleiht Teronis' Opfer einen Sinn, dessen Erfüllung er nicht mehr erlebte."}},faq={{q="Was ist Dartols Rute der Transformation?",a="Dartols Rute der Transformation ist eine magische Rute, die Dartol erschuf, ein verstorbener böser Zauberer. Wiederhergestellt kann sie Raene bei der Untersuchung der Furbolgangriffe im Eschental helfen.",al={"dartols rute","was bewirkt die rute"}},{q="Wer war Teronis?",a="Teronis war ein junger Nachtelf und eine Schildwache, den Raene Wolfsläufer damit beauftragte, im Eschental Komponenten uralter Magie zu finden. Murlocs nahmen den Edelstein an sich, den er suchte, und töteten ihn oben auf der Insel im Falathimsee. Durchreisende der Allianz können seine Mission vollenden.",al={"wer ist teronis","teronis tod"}},{q="Wer ist Raene Wolfsläufer?",a="Raene Wolfsläufer ist eine erfahrene Nachtelfenkommandantin der Schildwachen im Herzen von Astranaar. Sie leitet die Verteidigung des zentralen Eschentals gegen dämonische Verderbnis, feindselige Satyrn und verderbte Tiere der Gegend.",al={"raene","raene wolfsläufer"}},{q="Wer ist Shael'dryn?",a="Shael'dryn ist eine Dryade, die nahe dem Mondbrunnen östlich des Irissees lebt. Ihr Wissen über den Wald und seine uralten Relikte erlaubt es ihr, verderbte Relikte zu reinigen und uralte Machtwerkzeuge wiederherzustellen.",al={"shaeldryn","irissee priesterin"}},{q="Wo findet diese Quest statt?",a="Ihr reist vom Ufer des Irissees im zentralen Eschental auf den Hauptwegen nach Westen bis nach Astranaar, dem wichtigsten Stützpunkt der Allianz in diesem Gebiet.",al={"questort","wohin geht es"}},{q="Was geschieht, nachdem die Rute Raene übergeben wurde?",a="Raene ist erleichtert und stolz, dass Teronis' letzte Mission erfolgreich war. Die Säuberung des Eschentals geht weiter, und sie sucht nach Wegen, die Macht der Rute gegen die anhaltende Verderbnis des Waldes einzusetzen.",al={"nächste quest","raenes säuberung fortsetzung"}}},fx={f5799a7d={q="Warum möchte Shael'dryn, dass Ihr die Rute zu Raene bringt?",a="Da Dartols Rute der Transformation endlich wiederhergestellt ist, weiß Shael'dryn, dass ihr Teil der Vorbereitung abgeschlossen ist. Raene Wolfsläufer beaufsichtigt die Schildwachen in Astranaar und hatte ursprünglich Teronis damit beauftragt, die üble Verderbnis zu untersuchen, die das Eschental plagt. Shael'dryn schickt Euch zurück zu Raene, damit die Führung der Nachtelfen das fertige Relikt einsetzen und entscheiden kann, wie Teronis' unvollendete Mission am besten fortgesetzt werden kann.",al={"warum rute zu raene bringen","motiv von shaeldryn","warum raene wolfsläufer aufsuchen"}}},fp="17,165,16.293.0,16.348.1,39.170.0,16.263.0,24.203.0,18.188.0,33.133.0,47.188.1"}
P.entries["quest:103"] = {n="Bewahrer der Flamme",s="Am Leuchtturm von Westfall wacht Kapitän Grausohn über die Küste. Er sucht Öl, damit das Leuchtfeuer weiterbrennt und Schiffe sicher an den Riffen vorbeileitet, nachdem Murlocs die lebenden Wärter getötet haben.",h="Am Leuchtturm von Westfall wacht Kapitän Grausohn über die Küste.",kw={"leuchtfeuer","kapitän grausohn","ölkolben","großes meer","erntemonster","trübauge der alte","der leuchtturm von westfall"},ang={["faction:Alliance"]="Westfalls Leuchtfeuer hilft Handels- und Kriegsschiffen auf dem Weg zum Hafen von Sturmwind, an der bröckelnden Küste des Königreichs nicht auf Grund zu laufen.",["profession:Engineering"]="Ernteschnitter, die Westfalls Höfe durchstreifen, tragen flüchtige Maschinenflüssigkeiten bei sich, die als Brennstoff für eine Laterne dienen können."},sec={{t="Eine geisterhafte Pflicht",b="Der Leuchtturm von Westfall steht auf einer felsigen kleinen Insel vor Westfalls Südwestküste. Sein Licht leitete einst Seeleute durch die seichten Gewässer des großen Meeres. Diese Aufgabe endete, als Trübauge der Alte einen Murlocangriff anführte und den Wärter und seine Familie tötete. Kapitän Grausohn starb in den Gewässern bei diesen Felsen und wacht nun als Geist über den Turm. Zu Lebzeiten konnte er das Gemetzel nicht verhindern, doch er wird den Leuchtturm nicht erlöschen lassen."},{t="Brennstoff fürs Leuchtfeuer",b="Kein lebender Wärter ist mehr da, um die Flamme zu hüten, also braucht Kapitän Grausohn einen ungewöhnlichen Brennstoff. Ernteschnitter durchstreifen Westfalls verlassenes Ackerland und tragen in ihren verrosteten Körpern Kolben mit Maschinenöl. Grayson schickt Euch an Land, um das Öl aus diesen beschädigten Konstrukten zu bergen. Damit kann das Leuchtfeuer weiterbrennen und Kapitäne an den Riffen vorbeileiten."}},faq={{q="Wer ist Kapitän Grausohn?",a="Kapitän Grausohn ist der Geist eines Seemanns, der an Westfalls gefährlicher Küste Schiffbruch erlitt und starb. Er wacht über den Leuchtturm von Westfall, um lebende Seeleute vor demselben Schicksal zu bewahren.",al={"kapitän grausohn","leuchtturmgeist","wer ist der geist am leuchtturm von westfall"}},{q="Was geschah mit den ursprünglichen Leuchtturmwärtern?",a="Trübauge der Alte führte den Murlocangriff an, bei dem der Leuchtturmwärter und seine Familie getötet wurden. Kapitän Grausohn sah als Geist hilflos zu.",al={"was geschah mit dem leuchtturmwärter","wer hat den leuchtturmwärter getötet","wärterfamilie tot"}},{q="Woher stammt das Öl für die Leuchtturmflamme?",a="Ernteschnitter, die Westfalls verlassene Höfe und Felder durchstreifen, tragen das Öl für den Leuchtturm bei sich.",al={"woher öl bekommen","erntemonster öl","ölkolben"}},{q="Warum liegt Grayson so viel daran, das Leuchtfeuer am Brennen zu halten?",a="Grayson will, dass das Leuchtfeuer Seeleute über das große Meer und an den Küstenfelsen vorbeileitet. Er starb an diesen Riffen und wacht nun über den Leuchtturm.",al={"warum die fackel entzünden","graysons beweggrund","zweck der leuchtturmflamme"}},{q="Wer ist Trübauge der Alte?",a="Trübauge der Alte ist ein berüchtigter Murloc, der an Westfalls Küste umherstreift und Angriffe auf Küstensiedlungen anführt. Seine Plünderer töteten den Leuchtturmwärter und seine Familie.",al={"trübauge der alte","trübauge","murlocanführer westfall"}},{q="Wo befindet sich der Leuchtturm von Westfall?",a="Der Leuchtturm von Westfall steht auf einer felsigen kleinen Insel vor Westfalls Südwestküste. Ihr könnt ihn erreichen, indem Ihr durch die seichten Küstengewässer schwimmt.",al={"leuchtturmstandort","wo ist der leuchtturm von westfall","leuchtturm finden"}}},fx={cbe3424a={q="Warum benötigt Kapitän Grausohn Eure Hilfe, anstatt das Öl selbst zu sammeln?",a="Kapitän Grausohn ist ein ruheloser Geist, der an die unmittelbare Nähe des Leuchtturms von Westfall gebunden ist. Da sein Geist nicht ins Landesinnere reisen kann, um selbst Jagd auf die fehlerhaften Erntemaschinen zu machen, ist er darauf angewiesen, dass vorbeiziehende Abenteurer sich in die Felder wagen und den Treibstoff ernten, der für die Instandhaltung des Leuchtfeuers notwendig ist.",al={"warum benötigt mich grausohn","warum kann grausohn kein öl sammeln","warum ich grausohn"}},["44c879dd"]={q="Warum sind Ernter-Monster die Quelle für das Leuchtturmöl?",a="Die mechanischen Ernter-Monster, die durch die verlassenen Felder von Westfall streifen, werden mit Flaschen voll schwerem Maschinenöl betrieben. Da die Familie des Leuchtturmwärters tot ist und die normalen Versorgungswege abgeschnitten sind, muss sich Kapitän Grausohn auf jeden Brennstoff verlassen, der aus diesen abtrünnigen Automaten geborgen werden kann, um das Signalfeuer des Leuchtturms am Brennen zu halten.",al={"ernter-monster öl","warum ernter golem öl","ziel der ernter-monster"}}},fp="19,185,15.419.0,18.348.0,23.190.0,49.131.0,54.98.0,51.150.0,20.161.0,41.145.0"}
P.entries["quest:1030"] = {n="Raenes Säuberung",s="In Eschental sucht Raene Wolfsläufer einen Weg, mit einem unverdorbenen Furbolg zu sprechen. Südöstlich des Mystralsees offenbart Krolg den Groll, den manche überlebenden Furbolgs gegen die Nachtelfen hegen.",h="In Eschental sucht Raene Wolfsläufer einen Weg, mit einem unverdorbenen Furbolg zu sprechen.",kw={"eschental","dartols rute der transformation","teufelsmoos","furbolg","krolg","mystralsee","raene wolfsläufer","raenes säuberung"},ang={["class:Druid"]="Für einen Druiden ist das Schicksal der Furbolgs ein tiefer Kummer. Einst enge Verbündete der Natur, leiden sie nun durch anhaltende dämonische Verderbnis unter schrecklichem Wahnsinn.",["faction:Alliance"]="Für die Allianz hängt Astranaars Überleben davon ab, Gefahren entlang der Grenzstraßen aufzudecken. Dieses geheime Treffen kann helfen, das östliche Eschental zu sichern.",["race:NightElf"]="Für einen Nachtelfen offenbaren Krolgs Worte, dass viele Ureinwohner Eschentals die Kaldorei als leichtfertige Urheber des wiederkehrenden Verderbens des Landes sehen, nicht als dessen Hüter."},sec={{t="Eine Tarnung aus Fell und Klauen",b="Raene Wolfsläufer glaubt, dass der verstorbene Nachtelf sich den Furbolgs mithilfe von Dartols wiederhergestellter Rute der Transformation nähern wollte. Die Wälder von Eschental sind gefährlich geworden, und Wahnsinn breitet sich unter den Stämmen aus. Es gibt keinen Weg zur direkten Diplomatie. Die Rute verleiht Euch die Gestalt eines Furbolgs, sodass Ihr versuchen könnt, ihren Revierzorn zu umgehen und jemanden zu finden, der zum Reden bereit ist."},{t="Die Bitterkeit des Verbannten",b="Südöstlich des Mystralsees lebt Krolg fern seiner Sippe und bleibt vom Teufelsmoos unberührt. Im Glauben, Ihr wärt einer der Seinen, spricht er offen über seine Verbannung und seine Trauer. Er sieht die Nachtelfen nicht als Verbündete oder Beschützer. Stattdessen gibt er ihrem Stolz und ihren alten Verfehlungen die Schuld an der dämonischen Verderbnis, die sein Volk verheert."}},faq={{q="Was bewirkt Dartols Rute der Transformation?",a="Dartols Rute der Transformation verwandelt ihren Träger kurzzeitig in einen Furbolg. Die Tarnung erlaubt Euch, Euch unverdorbenen Furbolgs zu nähern, ohne sofort angegriffen zu werden.",al={"was bewirkt die rute","dartols rute der transformation","furbolgtarnung rute"}},{q="Wer ist Krolg?",a="Krolg ist ein unverdorbener Furbolg, der südöstlich des Mystralsees in der Verbannung lebt. Er entkam dem Teufelsmoos, das seine Sippe befiel, und lebt allein jenseits eines von Fackeln gesäumten Bachs. Dort trauert er um seinen verlorenen Stamm und hegt Groll gegen die Nachtelfen.",al={"wer ist krolg","unverdorbener furbolg mystralsee","furbolg südöstlich des mystralsees"}},{q="Warum greift Krolg an, wenn Ihr die Rute nicht benutzt?",a="Krolg fürchtet und misstraut Fremden, besonders Nachtelfen, denen er die Schuld am Untergang seines Volkes gibt. Ohne die Tarnung der Rute sieht er Euch als Eindringling und greift an, um sein Lager zu verteidigen.",al={"warum greift krolg an","krolg aggressiv","warum die rute bei krolg benutzen"}},{q="Warum gibt Krolg den Nachtelfen die Schuld an der Verderbnis?",a="Krolg gibt dem Stolz der Nachtelfen die Schuld an der dämonischen Verderbnis, die den Wald verheert. Seiner Ansicht nach brachten die einstigen Kaldorei durch ihre arkanen Machenschaften Verderben über Kalimdor und überließen dessen einheimische Stämme ihrem Leid.",al={"warum hasst krolg nachtelfen","furbolgs geben nachtelfen die schuld","krolgs hass auf nachtelfen"}},{q="Wo ist Krolg zu finden?",a="Krolg lebt südöstlich des Mystralsees in Eschental. Ein gewundener, von brennenden Fackeln markierter Trampelpfad überquert einen kleinen Bach und führt zu seinem einsamen Lager.",al={"wo ist krolg","krolg standort","unverdorbenen furbolg finden"}},{q="Was ist Teufelsmoos und wie wirkte es sich auf die Furbolgs aus?",a="Teufelsmoos ist ein dämonischer Bewuchs, der sich in Eschental ausbreitet und Boden und Pflanzen verdirbt. Sein Einfluss trieb die örtlichen Furbolgstämme in gewalttätigen Wahnsinn und zerrüttete ihre Gesellschaft.",al={"was ist teufelsmoos","teufelsmoos furbolgs","warum wurden furbolgs wahnsinnig"}}},fx={b9c958d0={q="Warum möchte Raene Wolfsläufer, dass Ihr einen nicht verderbten Furbolg findet?",a="Raene hofft, dass es Euch mit dem wiederhergestellten Stab gelingen wird, Euch einem nicht verderbten Furbolg zu nähern und mehr über das Leid seines Stammes zu erfahren. Sie schickt Euch in die Länder südöstlich des Mystralsees, um die Untersuchung fortzusetzen.",al={"warum einen nicht verderbten furbolg finden","raene wolfsläufer motiv","warum benötigt raene das"}}},fp="17,189,23.363.0,22.316.1,44.164.0,13.225.0,47.193.0,56.201.0,25.152.0,52.178.0"}
P.entries["quest:1031"] = {n="Der Zweig des Cenarius",s="Im östlichen Eschental schickt Euch Anilias letzte Bitte los, den Zweig des Cenarius zurückzuholen. Geltharis hat das heilige Relikt an sich genommen, und Illiyana erwartet seine Rückkehr.",h="Im östlichen Eschental schickt Euch Anilias letzte Bitte los, den Zweig des Cenarius zurückzuholen.",kw={"anilia","dryaden des eschentals","zweig des cenarius","geltharis","illiyana","nachtflucht","satyr"},ang={["class:Druid"]="Als Druide sind Euch die Relikte des Cenarius heilig, denn er lehrte die ersten sterblichen Druiden. Seinen Zweig von einem dämonisch verderbten Satyr zurückzuholen ist eine spirituelle Pflicht.",["faction:Alliance"]="Als Mitglied der Allianz könnt Ihr den Dryaden des Eschentals helfen, dämonische Bedrohungen im ungezähmten Osten zurückzudrängen.",["race:NightElf"]="Als Nachtelf kennt Ihr die Töchter des Cenarius als geliebte Verbündete. Rächt Anilia und vertreibt die Satyrn aus Euren angestammten Wäldern."},sec={{t="Die Bitte einer Sterbenden",b="Anilia liegt im Sterben, wo Ihr im östlichen Eschental nach vermissten Dryaden sucht. Die verwundete Tochter des Cenarius deutet nach Norden zu den Satyrruinen. Mit ihren letzten Atemzügen nennt sie Geltharis als denjenigen, der den Zweig des Cenarius genommen hat. Sie fleht Euch an, ihn zurückzubringen."},{t="Verderbnis in den Ruinen",b="Geltharis versteckt sich in den uralten Elfenruinen von Xavian. Die Satyrn sind uralte Diener der Brennenden Legion. Sie schätzen Relikte, die mit Cenarius verbunden sind, als Trophäen, um sie zu schänden und zu verspotten. Geltharis den Zweig abzunehmen erfüllt Anilias Bitte und hilft, Eschentals heilige Pflanzen vor der Verderbnis zu schützen, die diese Diener verbreiten."},{t="Trauer unter den Dryaden",b="Ihr bringt den Zweig zu Illiyana zurück, doch Anilia ist tot. Das heilige Relikt ist vor dämonischer Verderbnis sicher, doch die Nachricht von Anilias Tod erfüllt ihre überlebenden Angehörigen mit Trauer. Krieg und Verderbnis rücken den Dryaden des Eschentals immer näher."}},faq={{q="Was ist der Zweig des Cenarius?",a="Der Zweig des Cenarius ist ein heiliges Naturrelikt, das mit dem Waldherrn Cenarius verbunden ist und von seinen Dryadentöchtern verehrt wird. Satyrn nahmen ihn an sich, und Anilia wurde tödlich verwundet, als sie ihre Schwestern anführte, um ihn zurückzuholen. Mit ihrem letzten Atemzug nannte sie Geltharis als den Dieb.",al={"zweig des cenarius relikt","was ist der zweig","cenarius zweig"}},{q="Wer hat Anilia getötet?",a="Anilia wurde in den von Satyrn besetzten Ruinen von Xavian tödlich verwundet, als sie versuchte, den Zweig des Cenarius zurückzuholen. Mit ihrem letzten Atemzug nannte sie Geltharis als den Satyr, der ihn genommen hatte.",al={"anilias mörder","wer hat anilia angegriffen","wer hat die dryade getötet"}},{q="Wo befindet sich Geltharis?",a="Geltharis versteckt sich in den Ruinen von Xavian, nördlich der Stelle, an der Anilia im Sterben lag.",al={"geltharis aufenthaltsort","geltharis finden","wo geltharis töten"}},{q="Wohin bringe ich den Zweig des Cenarius, nachdem er geborgen wurde?",a="Bringt den geborgenen Zweig zu Illiyana am Schrein von Aessina im Eschental.",al={"zweig des cenarius abgeben","illiyana aufenthaltsort","wer bekommt den zweig"}},{q="Warum wollen die Satyrn die Artefakte des Cenarius?",a="Satyrn sind uralte Nachtelfen, die durch dämonische Pakte verwandelt wurden. Sie hassen die Natur und Cenarius. Heilige Relikte zu stehlen oder zu verderben dient ihren dämonischen Meistern und ihrem Hass auf ihre einstigen Verwandten.",al={"motive der satyrn","warum den zweig des cenarius stehlen","warum hat geltharis ihn genommen"}},{q="Was war Anilia für Illiyana?",a="Anilia und Illiyana waren enge Gefährtinnen unter den Dryaden, Schwestern im Geiste. Sie verbrachten unzählige Tage damit, frei durch die Wildnis des Eschentals zu laufen und zu spielen, bevor die Gefahren der Verderbnis Anilias Leben forderten.",al={"anilia und illiyana","sind die dryaden schwestern"}}},fx={["4863107a"]={q="Warum möchte Anilia, dass der Zweig des Cenarius geborgen wird?",a="Mit ihrem letzten Atemzug ist Anilias einziger Wunsch, sicherzustellen, dass das heilige Relikt ihres Vaters nicht in den Händen der niederträchtigen Satyrn bleibt. Sie hat Euch mit seiner Bergung betraut, damit der Zweig des Cenarius sicher zu ihren Schwester-Dryaden zurückkehren kann, anstatt geschändet zu werden.",al={"anilia motiv","warum zweig bergen","anilias letzter wunsch"}},["9fd6df2e"]={q="Wer ist Geltharis und warum werdet Ihr gegen ihn ausgesandt?",a="Geltharis ist der Satyr, der dafür verantwortlich ist, Anilia in einen Hinterhalt gelockt und den Zweig des Cenarius gestohlen zu haben. Er lauert in den antiken Ruinen im Norden, nachdem er das heilige Relikt von der sterbenden Dryade an sich gerissen hat.",al={"wer ist geltharis","warum geltharis töten","geltharis hintergrund"}},["59d5db2f"]={q="Warum benötigt Anilia Euch, um den Zweig zu bergen?",a="Anilia kann das Artefakt nicht selbst bergen, da ihre Wunden tödlich sind. Als sie Euch zu sich heranzieht, um ihre letzten Worte zu flüstern, haucht sie ihr Leben aus und hinterlässt Euch als die einzige anwesende Person, die sie rächen und ihren letzten Wunsch erfüllen kann.",al={"warum ich zweig des cenarius","warum benötigt anilia hilfe"}}},fp="22,156,15.261.0,23.320.0,23.222.1,31.265.0,18.177.0,27.69.0,60.76.0,44.199.0,27.189.0"}
P.entries["quest:1032"] = {n="Satyrn schlachten!",s="Am Schrein von Aessina ruft Illiyana Champions der Allianz zum Kampf gegen die Satyrn des Eschentals auf. Sie trauert um ihre Schwester Anilia und bittet Euch, Satyrhörner als Beweis zurückzubringen.",h="Am Schrein von Aessina ruft Illiyana Champions der Allianz zum Kampf gegen die Satyrn des Eschentals auf.",kw={"anilia","eschental","dryade","illiyana","satyr","satyrhörner","satyrn schlachten"},ang={["class:Druid"]="Als Druide bekämpft Ihr die Verderbnis in der von Cenarius geliebten Wildnis, indem Ihr eine gefallene Dryade rächt und die Hörner dämonischer Satyrn nehmt.",["faction:Alliance"]="Als Champion der Allianz lichtet Ihr die Reihen der Satyrn und schützt den Wald des Eschentals vor den wilden Bedrohungen rings um Euch.",["race:NightElf"]="Als Nachtelf kennt Ihr die Satyrn als schändliche Erinnerung daran, wie die Highborne einst der Knechtschaft der Teufelsmagie verfielen. Ihr helft, das Land von dieser uralten Verderbnis zu reinigen."},sec={{t="Die Trauer einer Dryade",b="Anilias Tod hat Illiyana am Schrein von Aessina in Trauer zurückgelassen. Dryaden sind naturverbundene Waldgeister, oft verspielt und heiter, doch für Sterbliche schwer zu fassen. Anilias brutale Ermordung hat diese Ruhe zerschlagen. Nun ruft Illiyana Reisende der Allianz dazu auf, die verantwortlichen dämonischen Bestien niederzustrecken."},{t="Die verderbte Verwandtschaft",b="Einst waren die Satyrn Nachtelfen, doch während des Krieges der Ahnen wurden sie von dämonischer Energie verdorben. Sie lauern in geschändeten Hainen im gesamten Eschental und machen als Diener der Brennenden Legion Jagd auf die Waldbewohner. Ihre Hörner beweisen Illiyana die Vergeltung und stehen für einen Schlag gegen die Teufelspräsenz, die ins östliche Eschental vordringt."}},faq={{q="Wer ist Illiyana?",a="Illiyana ist eine Dryade, die am Schrein von Aessina im Eschental lebt. Von Natur aus sanftmütig, trauert sie um ihre Schwester Anilia, die von den dortigen Satyrn getötet wurde.",al={"illiyana hintergrund","wer ist der questgeber","forest song dryade"}},{q="Wer war Anilia?",a="Anilia war eine Dryade und Illijanas geliebte Schwester. Sie verbrachten Zeitalter unter den uralten Baumkronen des Eschentals, bis Satyrn Anilia auflauerten und sie töteten.",al={"anilia","illiyanas schwester","wer ist gestorben"}},{q="Warum bittet Illiyana um Satyrhörner?",a="Illiyana verlangt Satyrhörner als Beweis dafür, dass die Kreaturen, die Anilia getötet haben, erschlagen wurden. Sie hofft, dass dieser Beweis dem Geist ihrer Schwester Frieden bringt.",al={"warum satyrhörner","satyrhörner als beweis"}},{q="Was sind Satyrn?",a="Satyrn sind Nachtelfen, die während des Krieges der Ahnen durch die dämonischen Mächte der Brennenden Legion verdorben und verwandelt wurden. Sie leben in verderbten Enklaven, verbreiten Verderbnis und vernichten Waldgeister.",al={"satyrn hintergrund","was sind die satyrn im eschental"}},{q="Wo liegt Forest Song?",a="Forest Song ist eine uralte, fast verlassene Nachtelfenruine im äußersten Osten des Eschentals, nahe der Grenze zu Azshara. Illiyana wartet am Schrein von Aessina, nicht in Forest Song.",al={"forest song lage","wo liegt forest song"}},{q="Hängt dies mit anderen Jagden zusammen?",a="Illiyana nimmt auch dann noch Satyrhörner entgegen, wenn Anilia gerächt ist. Die Verteidiger des Eschentals arbeiten weiterhin daran, die Satyrn aus dem Wald zu vertreiben.",al={"satyrhörner quest","folgequest","wiederholbare satyrquest"}}},fx={f313c3da={q="Warum möchte Illiyana, dass die Satyrn getötet werden?",a="Illiyana trauert um den Verlust ihrer Schwester Anilia, die von den niederträchtigen Satyrn, die im Eschental lauern, entführt und getötet wurde. Niedergeschlagen durch den Verlust ihrer geliebten Gefährtin aus Kindertagen, sucht sie Trost in der Rache. Die dafür verantwortlichen Kreaturen zu töten und ihre abgetrennten Hörner zu sehen, bietet ihr einen grimmigen Frieden und ehrt das Andenken ihrer gefallenen Schwester.",al={"warum satyrn töten","illiyana motiv","warum möchte illiyana rache"}},["45b4e644"]={q="Warum sind die Satyrn im Eschental?",a="Satyrn sind verdrehte Nachtelfen, die während des Krieges der Ahnen der dämonischen Verderbnis erlagen und zu bestienartigen Ungeheuern verflucht wurden, die der Brennenden Legion dienen. Gruppen dieser unsterblichen Schrecken halten sich in den dunklen, verdorbenen Winkeln des Eschentals auf, wie zum Beispiel Xavian und Nachtflucht, und planen ständig, die heiligen Wälder zu verheeren und jeden Kaldorei abzuschlachten, der ihnen unvorbereitet in die Hände fällt.",al={"warum sind satyrn hier","satyrn im eschental","was machen satyrn hier"}}},fp="14,170,15.293.0,17.325.0,16.139.0,15.143.0,38.150.0,16.196.0,21.173.0,37.135.0"}
P.entries["quest:1033"] = {n="Elunes Träne",s="In Astranaar sucht Pelturas Weißmond nach einem Heilmittel für seine kranke Tochter Relara. Ein Gebräu aus Bathranshaar verlangsamte ihre Krankheit, vertrieb sie aber nicht. Nun bittet Pelturas Euch, Elunes Träne vom Irissee zu holen, in der Hoffnung, ihre heilige Macht könne die Verderbnis aus ihr vertreiben.",h="In Astranaar sucht Pelturas Weißmond nach einem Heilmittel für seine kranke Tochter Relara.",kw={"eschental","astranaar","heilmittel","elune","elunes träne","irissee","orendil rundblatt","pelturas weißmond","relara","wasserelementare"},ang={["class:Druid"]="Als Druide kennt Ihr die Gewässer des Eschentals und die unberechenbaren Elementare, die das stille Herz des Irissees bewachen.",["class:Priest"]="Als Priester im Dienste Elunes kennt Ihr das Vertrauen in heilige Relikte im Kampf gegen finstere, unnatürliche Seuchen. Manchmal braucht das Gebet ein greifbares Hilfsmittel.",["faction:Alliance"]="Als Mitglied der Allianz helft Ihr Astranaars Verteidigern durch eine persönliche Krise, während die Gefahr im ganzen Eschental wächst.",["race:NightElf"]="Als Nachtelf kennt Ihr das Vertrauen in heilige Steine, die nach der Mondgöttin benannt sind. Ihr vertraut auf Elune's Grace, um Wunden zu reinigen, die gewöhnliche Heilmittel nicht erreichen können."},sec={{t="Die wachsende Angst eines Vaters",b="Pelturas Weißmonds junge Tochter Relara liegt schwer krank in Astranaar. Orendil Rundblatts Gebräu aus Bathranshaar verlangsamte ihre Krankheit, konnte sie aber nicht aus ihrem Körper vertreiben. Gewöhnliche Heilmittel haben versagt. Daher wendet sich Pelturas den alten Traditionen seines Volkes zu und sucht ein Heilmittel, das von göttlichem, reinigendem Licht berührt ist."},{t="Der Stein des Irissees",b="Orendil Rundblatt nannte ein stärkeres Heilmittel für den Fall, dass das Kräutergebräu versagen sollte: Elunes Träne, einen heiligen Stein auf einer Insel im Irissee, östlich von Astranaar. Die Nachtelfen glauben, dass der Stein den Segen der Mondgöttin trägt und Verderbnis aus Lebewesen tilgen kann. Unruhige Wasserelementare durchstreifen die Untiefen und Ufer des Sees und bewachen seine Gewässer."},{t="Ein wenig Hoffnung",b="Wenn Ihr den Stein nach Astranaar bringt, will Pelturas ihn in einer heilenden Brühe für Relara ziehen lassen. Er dankt Euch, doch die Verderbnis hält sich noch immer. Ihr Leben bleibt in Gefahr."}},faq={{q="Was ist Elunes Träne?",a="Elunes Träne ist ein heiliger Stein auf der mittleren Insel des Irissees im Eschental. Nach den Überlieferungen der Nachtelfen kann er starke Gifte und hartnäckige Verderbnis tilgen.",al={"was ist elunes träne","elunes träne gegenstand","stein des irissees"}},{q="Warum hat Orendils vorheriges Heilmittel versagt?",a="Orendil Rundblatts Gebräu aus Bathranshaar verlangsamte Relaras Krankheit, konnte sie aber nicht überwinden. Daher wandte sich Pelturas heiligen Heilmitteln zu, als sich Kräuter als unzureichend erwiesen.",al={"warum versagte orendils heilmittel","hat orendils heilmittel gewirkt","relara noch krank"}},{q="Wo liegt der Irissee?",a="Der Irissee liegt östlich von Astranaar im Eschental. Folgt der Hauptstraße nach Osten aus dem Ort und nehmt dann den unbefestigten Pfad nach Norden neben einem Bach, der den See speist.",al={"wo ist der irissee","irissee lage","irissee finden"}},{q="Welche Gefahren lauern am Irissee?",a="Wasserelementare, die ihr Revier verteidigen, bewohnen den Irissee und seine mittlere Insel. Wer sich der Insel nähert, um die Träne zu holen, muss an diesen feindseligen Naturgeistern vorbei.",al={"irissee gegner","was greift am irissee an"}},{q="Wie will Pelturas den Stein verwenden?",a="Pelturas will Elunes Träne in einem heilenden Eintopf für seine Tochter Relara ziehen lassen. Er hofft, dass ihre reinigende Kraft ihr Leiden vertreibt.",al={"elunes träne verwenden","elunes träne eintopf"}},{q="Wer ist Relara Whitemoon?",a="Relara Whitemoon ist die junge Nachtelfentochter von Pelturas Weißmond und lebt in Astranaar. Eine unnatürliche Verderbnis hat sie schwer erkranken lassen und bedroht ihr Leben.",al={"wer ist relara","pelturas tochter"}}},fx={["58c1c268"]={q="Warum möchte Pelturas Weißmond, dass dies erledigt wird?",a="Pelturas ist verzweifelt und möchte seine kranke Tochter Relara retten. Orendil Rundblatts anfängliches Heilmittel konnte die tückische Verderbnis, die ihren Körper zerfrisst, nur verlangsamen, anstatt sie zu vertreiben. Da die Zeit knapp wird, wendet sich Pelturas den legendären heilenden Kräften von Elunes Träne zu, da dies seine größte Hoffnung ist, die Krankheit zu reinigen, bevor sie ihr Leben fordert.",al={"warum möchte pelturas elunes träne","pelturas motiv","warum pelturas helfen"}}},fp="12,274,24.320.0,22.345.0,17.177.1,21.161.0,37.172.0,27.152.0,35.154.0,40.141.0,24.172.0"}
P.entries["quest:1034"] = {n="Die Sternenstaubruinen",s="In Astranaar sucht Pelturas Weißmond nach einem Weg, seine Tochter Relara zu retten. Elunes Träne linderte ihre Albträume, doch ein heftiges Fieber hält sie noch immer im Griff. Orendil Rundblatt schickt ihn nach Süden, um zwischen den uralten Nachtelfensteinen kühlenden Sternenstaub zu finden.",h="In Astranaar sucht Pelturas Weißmond nach einem Weg, seine Tochter Relara zu retten.",kw={"eschental","astranaar","heilung","elune","fieber","orendil","pelturas","umschlag","relara","sternenstaub"},ang={["class:Druid"]="Als Druide müsst Ihr Euch in den überfluteten Ruinen mit aufgewühlten Wassergeistern auseinandersetzen, um lindernden Sternenstaub zu sammeln. Ihre Gegenwart zeugt vom empfindlichen Gleichgewicht des Eschentals.",["class:Priest"]="Als Priester wisst Ihr, dass Elune's Grace Relaras Albträume gelindert hat. Um sterbliches Leben zu bewahren, braucht das Gebet womöglich irdische Heilmittel an seiner Seite.",["profession:Herbalism"]="Als Kräuterkundiger wisst Ihr, dass die Suche nach glitzerndem Pulver im Gestrüpp bedeutet, seltene Pflanzen an den feuchten Orten des Eschentals zu erkennen.",["race:NightElf"]="Als Nachtelf erkennt Ihr, dass die Ruinen südlich von Astranaar Überreste der uralten Zivilisation der Kaldorei sind. Ihre fortwirkende Magie kann noch immer bei der Heilung helfen."},sec={{t="Die anhaltende Verzweiflung eines Vaters",b="Pelturas Weißmond wacht am Bett seiner Tochter Relara, während eine bösartige Krankheit ihren Körper verzehrt. Elunes Träne linderte ihre Albträume, doch die Krankheit bleibt. Ein heftiges Fieber quält sie noch immer, gegen das gewöhnliche Arzneien nichts ausrichten können. Da die Tempelheiler überlastet sind, wendet sich Pelturas Heilmitteln aus der Natur zu und hofft, ihr Leben zu retten."},{t="Das Glitzern des Sternenstaubs",b="Orendil Rundblatt, ein betagter Kräuterkundiger, weist Pelturas von Astranaar aus nach Süden, über den Fluss zu den Sternenstaubruinen. Bereifter, schimmernder Staub sammelt sich auf Pflanzen zwischen den umgestürzten Marmorsäulen und Torbögen dieses uralten Heiligtums der Kaldorei. Das als Sternenstaub bekannte Pulver ist von Natur aus kalt genug, um unnatürliche Hitze zu entziehen. Pelturas hofft, es für einen Umschlag zu zermahlen und Relaras Fieber zu lindern."},{t="Lauernde Gefahren im Wasser",b="Wasserelementare und Wildtiere machen das Sammeln des bereiften Staubs zwischen den überfluteten Steinen gefährlich. Durch Veränderungen im Gleichgewicht des Eschentals verdorben oder aufgewühlt, wogen die Elementare um versunkene Plätze, wo die Büsche am dichtesten wachsen. Ihr watet durch seichte Gewässer, die ruhig wirken, und haltet nach Hinterhalten aus den trüben Tiefen Ausschau. Die glitzernden Büsche müssen genügend reinen Staub liefern, um ihn nach Astranaar zurückzubringen."}},faq={{q="Warum braucht Pelturas Sternenstaub?",a="Relara, die Tochter von Pelturas Weißmond, leidet in Astranaar unter schwerem Fieber. Elunes Träne linderte ihre Albträume, doch das Fieber bleibt. Orendil Rundblatt sagt, bereifter Staub aus den Sternenstaubruinen könne sie als Umschlag kühlen.",al={"warum sternenstaub","zweck der sternenstaubruinen","relaras fieber heilen"}},{q="Wo liegen die Sternenstaubruinen?",a="Die Sternenstaubruinen liegen südlich von Astranaar im Herzen des Eschentals. Uraltes, überwuchertes Mauerwerk der Kaldorei umgibt dort einen kleinen See.",al={"lage der sternenstaubruinen","wo sind die sternenstaubruinen","sternenstaubruinen finden"}},{q="Was ist Sternenstaub in diesem Zusammenhang?",a="Sternenstaub ist bereifter Staub, der sich auf Pflanzen am See sammelt. Pelturas hofft, dass seine kühlende Wirkung als Umschlag das Fieber seiner Tochter lindert.",al={"was ist sternenstaub","beschaffenheit von sternenstaub","sternenstaub hintergrund"}},{q="Heilt der Sternenstaub Relara vollständig?",a="Pelturas hofft, dass ein Umschlag mit Sternenstaub Relaras Fieber senkt. Ob sie dadurch all ihre Kräfte zurückgewinnt, zeigt sich nach der Behandlung.",al={"heilt sternenstaub relara","relara geheilt","wird das mädchen gerettet"}},{q="Welche Gefahren lauern in den Sternenstaubruinen?",a="Aggressive Wasserelementare lauern unter der Oberfläche der überfluteten Ruinen und verteidigen die Gewässer. Sie bedrohen jeden, der durch das seichte Wasser watet, um die schimmernden Büsche zu durchsuchen.",al={"feinde in den sternenstaubruinen","was greift in den sternenstaubruinen an"}},{q="Wer ist Orendil?",a="Orendil Rundblatt ist ein Nachtelf und Kräuterkundiger, der im nördlichen Eschental nahe Maestras Posten lebt. Er erforscht die Pflanzen der Region seit Jahrhunderten und berät Pelturas zu seltenen pflanzlichen Heilmitteln, wenn die Behandlungen im Tempel nicht ausreichen.",al={"wer erzählte pelturas von sternenstaub","orendil rundblatt"}}},fp="21,249,28.347.0,21.391.0,22.392.0,32.229.0,40.134.0,33.144.0,41.133.1,48.178.0,15.227.0"}
P.entries["quest:1035"] = {n="Der Himmelssturzsee",s="Am Himmelssturzsee könnte ein Mondstein Relara heilen, bevor ihre Kräfte schwinden. Ihr Vater, Pelturas Weißmond, schickt Euch südöstlich von Astranaar, um einen unter den gefallenen Steinen zu finden.",h="Am Himmelssturzsee könnte ein Mondstein Relara heilen, bevor ihre Kräfte schwinden.",kw={"eschental","astranaar","gefallener mondstein","himmelssturzsee","pelturas weißmond","relara","shadethicket oracle"},ang={["class:Druid"]="Die feindseligen Shadethicket-Moorbestien zeigen die Zwietracht, die sich unter den natürlichen Wächtern des Eschentals ausbreitet. Sich ihnen zu stellen, lastet schwer auf jenen, die das Gleichgewicht wiederherstellen wollen.",["class:Priest"]="Gefallene Mondsteine sind wegen ihrer göttlichen Energien begehrt. Ihre heilende Gnade, die mit der Mondgöttin Elune verbunden ist, kann helfen, ein sterbendes Kind zu retten.",["faction:Alliance"]="Pelturas Weißmond zu helfen, unterstützt die Pflicht der Allianz, Astranaars Bürger vor der Verderbnis zu schützen, die das Eschental erfasst.",["race:NightElf"]="Für die Kaldorei ist der Schutz von Astranaars Kindern eine Pflicht der ganzen Gemeinschaft. Mondsteine zu bergen, die mit Elunes Segen verbunden sind, ist ein Akt der Barmherzigkeit und Ehrfurcht."},sec={{t="Die letzten Atemzüge einer Tochter",b="Seit Tagen sieht Pelturas Weißmond zu, wie seine junge Tochter Relara dem Tod näher kommt. Heilmittel aus Bathranshaar und Sternenstaub senkten ihr Fieber, doch sie blieb schwach und gebrechlich. Er fürchtet, ihr bleiben nur noch wenige Atemzüge, bevor ihr Geist in die Nacht entschwindet."},{t="Der Gefallene Mondstein",b="Pelturas setzt auf Mondsteine, um Relaras Kräfte wiederherzustellen. Diese Bruchstücke fielen in den Himmelssturzsee südöstlich von Astranaar, und Nachtelfen sammelten sie wegen ihrer Heilkraft. Aggressive Elementare oder verderbte Rinde beanspruchen nun die Steine. Ihr müsst Euch mit Klinge und Zauber der Gefahr stellen, um einen zu bergen."},{t="Das Reich der Shadethickets",b="Shadethicket-Moorbestien beanspruchten die Wildnis um den Himmelssturzsee und versperrten den Nachtelfen den einfachen Zugang zu seinem Wasser. Ihr Anführer, das Shadethicket Oracle, hortet gefallene Mondsteine auf einem Inselchen in der Mitte des Sees. Ihr müsst Euch dem Oracle stellen, bevor Relaras Kräfte schwinden. Pelturas zermahlt den geborgenen Stein und bereitet daraus Tee. Relara trinkt ihn und gewinnt ihre Kräfte zurück."}},faq={{q="Warum braucht Relara einen Mondstein, wenn ihr Fieber bereits gesunken ist?",a="Relaras Fieber hat ihre Lebenskraft aufgezehrt, und Ruhe allein kann sie nicht wiederherstellen. Pelturas glaubt, ein gefallener Mondstein könne ihren Geist erneuern, bevor die Erschöpfung sie dahinrafft.",al={"warum mondstein","relara noch krank","relaras fieber gesunken"}},{q="Wo liegt der Himmelssturzsee?",a="Der Himmelssturzsee liegt im mittleren Osten des Eschentals, südöstlich von Astranaar. Feindselige Moorbestien beherrschen seine Gewässer, in deren Mitte eine kleine Insel liegt.",al={"wo liegt der himmelssturzsee","lage des sees","lage des shadethicket-sees"}},{q="Wer hat den gefallenen Mondstein?",a="Das Shadethicket Oracle besitzt den Mondstein. Das Oracle führt die feindseligen Moorbestien an und haust auf einer Insel in der Mitte des Himmelssturzsees.",al={"wer lässt den mondstein fallen","standort des shadethicket oracle","wo den mondstein finden"}},{q="Was geschieht nach dieser Quest?",a="Pelturas' Suche nach einem Heilmittel endet mit dem gefallenen Mondstein. Er braucht ihn, um Relaras Kräfte wiederherzustellen, und ihr Schicksal offenbart sich, sobald der Stein überbracht wird.",al={"gibt es eine folgequest","was kommt als nächstes","fortsetzung der quest"}},{q="Warum horten die Shadethickets die Mondsteine?",a="Während die wilden Geschöpfe und Moorbestien des Eschentals immer unberechenbarer und verderbter werden, vertreiben die Shadethickets Außenstehende mit Gewalt. Ihr Oracle sammelt und bewacht die Mondreliquien und hält sie von den Nachtelfen Astranaars fern.",al={"warum nehmen treants die steine","oracle hortet mondsteine"}},{q="Welche vorherigen Quests führen zu dieser Aufgabe?",a="Die Questreihe beginnt mit Bathranshaar, gefolgt von Orendils Heilmittel, Elunes Träne und den Sternenstaubruinen. Bei jedem Schritt werden seltene Bestandteile gesammelt, um Relaras sich verschlechternden Zustand zu behandeln.",al={"questreihe vor dem himmelssturzsee","questvoraussetzungen","was kommt davor"}}},fx={fb73f711={q="Wofür wird der Gefallene Mondstein verwendet?",a="Die gefallenen Mondsteine, die um den Himmelssturzsee gesammelt werden, tragen wiederherstellende Magie in sich, die mit dem Nachthimmel verbunden ist. Während Relaras schweres Fieber gebrochen ist, bleibt ihr Körper kritisch geschwächt. Pelturas glaubt, dass gewöhnliche Ruhe sie nicht retten wird; nur die konzentrierte mystische Kraft in einem Mondstein kann ihre verlorene Lebenskraft wiederherstellen, bevor ihre Kräfte gänzlich schwinden.",al={"verwendung gefallener mondstein","was bewirkt der mondstein","warum gefallener mondstein"}}},fp="15,181,27.264.0,20.299.0,23.365.1,60.160.0,33.153.0,29.141.0,30.151.1,50.230.0,42.180.0"}
P.entries["quest:1037"] = {n="Velinde Sternensang",s="In Eschental sucht Melyria Frostschatten nach Nachrichten über die Kommandantin, die vor ihr dort diente. Velinde Sternensang verschwand im Kampf gegen die Verderbnis aus dem Teufelswald, und Melyria schickt Euch nach Darnassus, um Antworten zu finden.",h="In Eschental sucht Melyria Frostschatten nach Nachrichten über die Kommandantin, die vor ihr dort diente.",kw={"eschental","darnassus","teufelswald","melyria frostschatten","schildwachen","thyn'tel klingenweber","velinde sternensang","die terrasse der krieger"},ang={["class:Priest"]="Als Priester Elunes fühlt Ihr Euch vielleicht einer Glaubensschwester verbunden, die darum kämpfte, die dämonische Verderbnis aus dem Teufelswald einzudämmen.",["faction:Alliance"]="Als Mitglied der Allianz erlebt Ihr das strenge Militärprotokoll von Darnassus, das Fälle von Verschwinden auf dem Schlachtfeld innerhalb der Führung der Schildwachen hält.",["race:NightElf"]="Als nachtelfischer Verteidiger steht Ihr dem Schicksal einer angesehenen Kommandantin und Priesterin gegenüber, inmitten der fragilen Lage im nördlichen Kalimdor nach dem Dritten Krieg."},sec={{t="Eine verschwundene Vorgängerin",b="Melyria Frostschatten hält Wache in Eschental und folgt dem Weg, den einst Velinde Sternensang beschritt. Velinde war eine Priesterin mit dem Auftrag, die dämonische Verderbnis einzudämmen, die sich vom Teufelswald nach Süden ausbreitete. Frühe Berichte besagten, sie habe die Gefahr unter Kontrolle, doch mit der Zeit geriet ihr Feldzug ins Stocken. Dann verschwand sie ohne Vorwarnung oder offizielle Ablösung, ließ den Kampf unvollendet zurück, und ihr Schicksal blieb unbekannt."},{t="Geheimnisse der Terrasse",b="Hinweise im Wald beunruhigen Melyria, weshalb sie Euch nach Darnassus schickt. Auf der Terrasse der Krieger überwacht Thyn'tel Klingenweber, Kommandantin der Schildwachen, die militärischen Einsätze. Die Schildwachen wissen, dass Velinde verschwunden ist, doch ihre Führung hält die Umstände geheim. Thyn'tel muss erst überzeugt werden, bevor sie Einblick in vertraulichere Aufzeichnungen gewährt."}},faq={{q="Wer war Velinde Sternensang?",a="Velinde Sternensang war eine Priesterin und Kommandantin der Schildwachen, die in Eschental stationiert war. Sie sollte die Nordgrenze gegen dämonische Schrecken aus dem Teufelswald verteidigen, verschwand dann aber aus dem Dienst.",al={"velinde sternensang hintergrundgeschichte","wer ist velinde","priesterin velinde"}},{q="Warum erkundigt sich Schildwache Melyria jetzt nach ihr?",a="Melyria Frostschatten trat nach Velindes Verschwinden an ihre Stelle. Entdeckungen im Heulenden Tal haben ihre Sorge um die damaligen Geschehnisse und Eschentals Sicherheit erneut geweckt.",al={"warum velindes verschwinden untersuchen","melyria quest grund"}},{q="Wohin muss ich gehen, um diese Quest abzuschließen?",a="Reist von Eschental nach Darnassus, hoch oben auf Teldrassil. Kommandantin Thyn'tel Klingenweber ist auf der Terrasse der Krieger stationiert.",al={"wo velinde sternensang abgeben","thyn'tel klingenweber standort"}},{q="Warum spricht Kommandantin Klingenweber nur widerwillig darüber?",a="Die Schildwachen wissen, dass Velinde verschwunden ist, doch die Einzelheiten ihrer letzten Einsätze sind vertrauliche militärische Angelegenheiten. Die Führung von Darnassus gibt sie nicht leichtfertig an Außenstehende weiter.",al={"warum geheim","warum spricht thyn'tel nicht"}},{q="Welche Verbindung hat Velinde zum Teufelswald?",a="Velinde leitete die Bemühungen der Schildwachen, die dämonische Verderbnis einzudämmen, die sich vom Teufelswald ausbreitete. Nach anfänglichen Erfolgen geriet ihr Feldzug ins Stocken, kurz bevor sie verschwand.",al={"velinde teufelswald","was geschah im teufelswald"}},{q="Welche Quest führt unmittelbar zu dieser?",a="Diese Quest folgt auf das Heulende Tal, wo Ihr seltsame und feindselige Geschehnisse tief in Eschentals Wäldern untersucht.",al={"velinde sternensang voraussetzung","vorherige quest"}}},fx={["8a014bde"]={q="Warum schickt Schildwache Melyria Euch nach Darnassus, anstatt selbst zu gehen?",a="Schildwache Melyria Frostschatten wurde speziell ins Eschental versetzt, um Velinde Starsongs verlassene Pflichten zu übernehmen und die wachsenden Bedrohungen einzudämmen, die vom Teufelswald aus herandrängen. Da die nördliche Grenze ständig instabil ist, kann sie ihren Grenzposten nicht verlassen, um die lange Reise zurück nach Darnassus selbst anzutreten. Ein Abenteurer kann frei reisen, um Kommandant Thyn'tel Klingenweber aufzusuchen, ohne die Verteidigung des Eschentals unterbesetzt zu lassen.",al={"warum schickt ihr mich","warum geht melyria nicht","warum kann melyria nicht selbst gehen"}}},fp="16,210,22.386.0,22.312.1,25.191.0,45.166.0,45.122.0,47.172.0,45.159.0,40.108.0"}
P.entries["quest:1038"] = {n="Velindes Besitztümer",s="In Darnassus untersuchen die Schildwachen Velindes Verschwinden. Schildwache Velinde Sternensang verschwand nach vielen Dienstjahren, und Thyn'tel Klingenweber bittet Euch, ihr Tagebuch aus dem Quartier der Schildwachen zu holen.",h="In Darnassus untersuchen die Schildwachen Velindes Verschwinden.",kw={"klingenweber","kasernenbau","darnassus","tagebuch","mel'thandris","schildwachen","starsong","thyn'tel","die terrasse der händler","velinde"},ang={["class:Priest"]="Als Priester könnt Ihr in Velinde eine verehrte Priesterin erkennen, die sich heiligen Pflichten verschrieben hat. Ihr habt Grund, dem nachzugehen, was sie vom Weg abbrachte.",["faction:Alliance"]="Als Mitglied der Allianz könnt Ihr erkennen, wie Bedrohungen in ganz Kalimdor die noch junge Allianzführung in Darnassus fordern, wenn gegen hochrangige Nachtelfenoffiziere ermittelt werden muss.",["race:NightElf"]="Als Nachtelf könnt Ihr in Velinde Starsongs Geschichte die stillen Opfer der Sisterhood of Elune und der Schildwachen erkennen. Ihr plötzliches Verschwinden beunruhigt ihre Angehörigen in Darnassus."},sec={{t="Eine geschätzte Schildwache",b="Priesterin Velinde Sternensang diente den Nachtelfen viele Jahre lang und gewann ihr tiefes Vertrauen. Als sie ihre Pflichten stillschweigend hinter sich ließ, vermuteten die Schildwachen persönliche Gründe und erwarteten ihre Rückkehr. Später fanden Außenstehende Hinweise im Zusammenhang mit dem Tome of Mel'Thandris. Erst dann erlaubte die Führung der Schildwachen, Velindes persönliche Besitztümer zu durchsuchen."},{t="Die Truhe im Quartier",b="Thyn'tel Klingenweber ist auf der Terrasse der Krieger in Darnassus stationiert und gibt Euch den Schlüssel zu Velindes verschlossener Truhe. Sie steht im Kasernenbau der Schildwachen auf der Terrasse der Händler. Darin liegt Velindes persönliches Tagebuch mit Berichten über ihre Aufträge und Gedanken. Seine Seiten beunruhigen die Schildwachen, denn sie deuten auf geheime Angelegenheiten hin, die Velinde dazu trieben, Teldrassil allein zu verlassen."}},faq={{q="Wer ist Velinde Sternensang?",a="Velinde Sternensang ist eine angesehene Nachtelfenpriesterin und Befehlshaberin der Schildwachen. Ihr hingebungsvoller Dienst brachte ihr den tiefen Respekt ihrer Gefährten ein, bevor sie auf einer ungeklärten Mission verschwand.",al={"velinde starsong hintergrundgeschichte","wer ist velinde","velinde vorgeschichte"}},{q="Wo befindet sich Velindes Truhe?",a="Velindes Truhe steht im Quartier der Schildwachen im Obergeschoss eines Gebäudes auf der Terrasse der Händler in Darnassus. Überquert die erhöhte Brücke vom benachbarten Geschäft für Kettenrüstungen aus, um dorthin zu gelangen.",al={"velinde truhe fundort","wo sind velindes besitztümer","schildwachen kasernenbau darnassus"}},{q="Warum suchten die Schildwachen nicht früher nach ihr?",a="Die Schildwachen vertrauten auf Velindes tadellosen Ruf. Ihre Vorgesetzten glaubten, sie habe triftige persönliche Gründe für ihren Aufbruch, und erwarteten ihre Rückkehr, sobald ihre Angelegenheiten erledigt wären.",al={"warum ignorierten die schildwachen velinde","warum wurde velinde nicht als vermisst gemeldet"}},{q="Was wird im Tagebuch entdeckt?",a="Velindes Tagebuch zeigt, dass ihre Abwesenheit beunruhigender war als eine gewöhnliche Beurlaubung. Thyn'tel Klingenweber sucht sofort Hilfe von außen, um ihren Weg nachzuverfolgen.",al={"velindes tagebuch inhalt","was schrieb velinde"}},{q="Welche Verbindung hatte Velinde zum Tome of Mel'Thandris?",a="Der uralte elfische Text enthielt Verweise auf Velindes frühere Nachforschungen und Tätigkeiten. Diese Verweise brachten Forscher und Abenteurer erstmals dazu, ihrem Verbleib nachzugehen.",al={"tome of melthandris velinde","warum der tome of mel'thandris"}},{q="Wohin führen die Ermittlungen nach dem Fund ihrer Besitztümer?",a="Die Hinweise im Tagebuch führen ins Brachland und folgen Velindes Weg nach Süden zu Kalimdors Verkehrsknotenpunkten und Häfen.",al={"wohin nach velindes besitztümern","velindes besitztümer nächste quest"}}},fx={c0fc6707={q="Warum möchte Thyn'tel Klingenweber, dass Velindes Habseligkeiten durchsucht werden?",a="Die Schildwachen nahmen lange an, dass Velinde Sternensang Darnassus aus eigenem Antrieb verlassen hatte und zu gegebener Zeit zurückkehren würde, da sie ihrem engagierten Dienst vertrauten. Die Enthüllungen, die Ihr jedoch aus dem Folianten von Mel'Thandris ans Licht gebracht habt, legen nahe, dass ihr Verschwinden weitaus komplizierter sein könnte. Klingenweber gewährt Euch Zugang zu ihrer persönlichen Truhe in der Hoffnung, dass Velindes Diensttagebuch entscheidende Hinweise auf ihr plötzliches Verschwinden und ihren derzeitigen Aufenthaltsort liefert.",al={"warum möchte thyntel das","thyntel klingenweber motiv","warum velindes habseligkeiten durchsuchen"}}},fp="17,223,18.346.0,26.372.1,24.179.0,33.192.0,48.165.0,38.155.0,54.173.0,60.114.1"}
P.entries["quest:1039"] = {n="Der Brachlandhafen",s="Thyn'tel Klingenweber schickt Euch nach Süden nach Ratschet, um Velinde Sternensang zu suchen. Die Schildwachen glauben, dass sie über das große Meer in die Östlichen Königreiche gesegelt ist, und ihre Spur führt durch gefährliche Lande der Horde.",h="Thyn'tel Klingenweber schickt Euch nach Süden nach Ratschet, um Velinde Sternensang zu suchen.",kw={"eschental","ratschet","scythe of elune","steamwheedle cartel","brachland","thyn'tel klingenweber","velinde starsong","wharfmaster dizzywig"},ang={["faction:Alliance"]="Als Späher der Allianz durchquert Ihr im Brachland Gebiete, in denen die Horde patrouilliert, bevor Ihr die neutralen Docks der Goblins erreicht. Auf dem Weg ist Vorsicht geboten.",["race:NightElf"]="Als Nachtelf spürt Ihr die Lücke, die Velinde Sternensang in der Führung von Darnassus hinterlassen hat. Ihrer verzweifelten Reise nachzuspüren, ist eine Pflicht der Kaldorei."},sec={{t="Der Priesterin auf der Spur",b="Hinweise unter Velinde Starsongs persönlichen Habseligkeiten deuten auf eine Überfahrt über das Meer in Richtung der Östlichen Königreiche hin. Ratschet ist der einzige betriebsfähige Hafen des Brachlands. Dort können Reisende aus dem nördlichen Kalimdor eine Überfahrt nach Süden oder Osten finden, ohne von den Landen der Nachtelfen aus in See zu stechen. Thyn'tel Klingenweber schickt Euch, die Geschäftsbücher des Hafenmeisters nach Velindes Namen zu durchsuchen."},{t="Eine gefährliche Überquerung",b="Die Straße nach Ratschet führt mitten durch die Lande der Horde. Südlich von Eschental durchstreifen orkische Vorreiter und Patrouillen der Tauren den Mor'shan-Schutzwall und das trockene Brachland. Neutrale Goblins des Steamwheedle Cartel regieren Ratschet und stellen den Handel über die Rivalitäten der Fraktionen. An den Docks verzeichnet Werftmeister Dizzywig jeden Passagier und jede Frachtkiste."}},faq={{q="Warum schicken mich die Schildwachen ins Brachland?",a="Ratschet ist der wichtigste neutrale Handelshafen im zentralen Kalimdor. Da Velinde Sternensang auf der Suche nach einer Überfahrt in die Östlichen Königreiche verschwand, glauben die Nachtelfen, sie könnte ein Handelsschiff der Goblins gebucht haben, statt die offiziellen militärischen Wege zu nutzen.",al={"warum nach ratschet","warum der brachlandhafen"}},{q="Wer ist Werftmeister Dizzywig?",a="Werftmeister Dizzywig beaufsichtigt die Abfahrten und Frachtaufzeichnungen an Ratschets Docks. Er arbeitet für das Steamwheedle Cartel und führt Buch über die Schiffe, Passagiere und Warenlieferungen, die im Hafen eintreffen und ihn verlassen.",al={"wer ist dizzywig","ratschet hafenmeister"}},{q="Warum wäre ein Mitglied der Allianz in Ratschet sicher?",a="Das neutrale Steamwheedle Cartel regiert Ratschet anstelle der Horde. Seine Goblins stellen Handel und Profit an erste Stelle, während ihre Schläger für Frieden sorgen. Reisende der Allianz können Geschäfte machen, solange sie innerhalb der Stadt keine Waffen ziehen.",al={"ist ratschet sicher für die allianz","greifen wachen in ratschet an"}},{q="Was geschieht, nachdem ich Werftmeister Dizzywig gefunden habe?",a="Nachdem er seine Aufzeichnungen geprüft hat, bestätigt Dizzywig, dass Velinde an Bord eines Schiffes in die Östlichen Königreiche aufgebrochen ist. Er schickt Euch nach Beutebucht im Schlingendorntal, um ihre Spur jenseits des großen Meeres wieder aufzunehmen.",al={"was kommt nach dem brachlandhafen","velinde quest fortsetzung"}},{q="Wie erreicht ein Reisender der Allianz Ratschet sicher?",a="Von Eschental aus können Reisende der Allianz nach Süden am Hain der Silberschwingen vorbeiziehen und dann den bewachten Mor'shan-Schutzwall durch die Hügel unmittelbar östlich der Hauptstraße umgehen. Folgt im Brachland den Wegen zur Ostküste, um Ratschets Docks zu erreichen.",al={"sicherster weg nach ratschet allianz","wie nach ratschet gelangen allianz"}},{q="Wer ist Velinde Sternensang?",a="Velinde Sternensang war eine Nachtelfenpriesterin und Melyria Frostshadows Vorgängerin in Eschental. Sie hatte den Auftrag, den Wald von Dämonen zu säubern, kam jedoch kaum voran, bevor sie verschwand. Ihre Spur scheint nun über das Meer zu führen.",al={"wer ist velinde","velinde starsong geschichte"}}},fx={["1c038d53"]={q="Warum benötigt Thyn'tel Klingenweber mich, anstatt eine Schildwache nach Ratschet zu schicken?",a="Das Brachland wird fest von der Horde kontrolliert, und bewaffnete Nachtelfen-Schildwachen, die vom Eschental nach Süden marschieren, würden einen sofortigen und blutigen Scharmützel provozieren. Während der neutrale Hafen von Ratschet friedliche Reisende willkommen heißt, würde eine offizielle militärische Präsenz der Kaldorei den brüchigen Waffenstillstand stören und intensives Misstrauen erregen. Ein einzelner Abenteurer kann unbemerkt an den Grenzen der Horde vorbeischlüpfen und sich mit den Goblins befassen, ohne einen offenen Krieg zu entfachen.",al={"warum schickt ihr mich","warum keine schildwache schicken","warum ich brachland hafen"}}},fp="16,207,22.351.0,20.335.0,46.265.0,28.208.0,48.233.0,48.197.1,51.240.0,24.225.0"}
P.entries["quest:104"] = {n="Bedrohung an der Küste",s="An Westfalls felsiger Küste ruft Kapitän Grausohns Geist Reisende auf, sich der Bedrohung an der Küste zu stellen. Sein Schiff zerschellte an den Felsen, nachdem Murlocs die Familie des Leuchtturmwärters von ihrem Posten vertrieben hatten. Die Familie kehrte zurück, doch Trübauge der Alte führte einen weiteren Angriff an und tötete sie. Nun fordert Grayson den Tod des Häuptlings und Gerechtigkeit für die Küste.",h="An Westfalls felsiger Küste ruft Kapitän Grausohns Geist Reisende auf, sich der Bedrohung an der Küste zu...",kw={"kapitän grausohn","bedrohung an der küste","großes meer","murloc","trübauge der alte","schuppe von trübauge dem alten","westfall","der leuchtturm von westfall"},ang={["faction:Alliance"]="Durch Westfalls Küstengewässer verläuft lebenswichtiger Schiffsverkehr für Sturmwind. Anführer wie Trübauge den Alten zu vertreiben hilft, die südlichen Seewege vor Sabotage zu schützen.",["race:Human"]="Als Mensch kennt Ihr den Mord an der Familie des Leuchtturmwärters als düsteres Kapitel in Westfalls Verlust an Sicherheit. Ihr Tod gibt Euch einen weiteren Grund, Eure Mitbürger zu rächen."},sec={{t="Ein Leuchtfeuer im Dunkeln",b="Der Leuchtturm von Westfall führte Schiffe einst durch die zerklüfteten Untiefen entlang der Südküste. Nachdem Murlocs die Familie des Leuchtturmwärters von ihrem Posten verscheucht hatten, lief Kapitän Grausohns Schiff im Dunkeln auf die Felsen. Die Familie kehrte zurück und entzündete die Flamme erneut, doch die Gefahr lauerte weiterhin an der Küste."},{t="Die Geißel der Küste",b="Trübauge der Alte scharte die willensschwächeren Murlocs entlang der Küste um sich und führte sie gegen den Leuchtturm. Bei diesem zweiten Angriff starb die Familie des Wärters, während Kapitän Grausohn hilflos zusah. Nun fordert der geisterhafte Kapitän Murk-Eyes Tod und verlangt eine Schuppe als Beweis. Er hofft, den Toten Frieden zu bringen und Seeleute auf dem großen Meer zu schützen."}},faq={{q="Wer ist Trübauge der Alte?",a="Trübauge der Alte ist ein gerissener Murloc-Häuptling, der an Westfalls Südküste umherstreift. Er schart andere Murlocs um sich und führt Angriffe auf menschliche Siedlungen entlang der Küste an.",al={"murk-eye","murk eye","wer ist murk eye","wer ist die bedrohung an der küste"}},{q="Warum will Kapitän Grausohn Trübauge den Alten tot sehen?",a="Kapitän Grausohn will Trübauge den Alten tot sehen, weil Murlocs die Familie des Leuchtturmwärters von ihrem Posten vertrieben. Als die Küste im Dunkeln lag, lief Graysons Schiff auf die Felsen. Später sah Grayson zu, wie Murk-Eye einen zweiten Angriff anführte, bei dem der zurückgekehrte Wärter und seine Familie starben.",al={"graysons groll","warum murk eye töten","graysons vorgeschichte"}},{q="Wo ist Trübauge der Alte zu finden?",a="Trübauge der Alte streift an Westfalls offenen Stränden und durch die Untiefen nahe dem Leuchtturm von Westfall und den nahen Murloc-Lagern umher.",al={"murk-eye fundort","wo ist murk eye","murk eye finden"}},{q="Welchen Beweis verlangt Grayson?",a="Kapitän Grausohn verlangt eine Schuppe von Trübauge dem Alten als Beweis dafür, dass der Häuptling tot ist.",al={"todesbeweis","schuppe von murk eye","quest abgeben"}},{q="Wer war Kapitän Grausohn zu Lebzeiten?",a="Kapitän Grausohn war ein Schiffskapitän, dessen Schiff unterhalb des Leuchtturms von Westfall auf die Felsen lief. Sein Geist verweilt nahe der Küste und sucht Vergeltung an den Murlocs sowie sicherere Gewässer für vorbeifahrende Schiffe.",al={"kapitän grausohn","geist am leuchtturm","leuchtturmgeist"}},{q="Was geschah mit der Familie des Leuchtturmwärters?",a="Die Familie des Leuchtturmwärters floh zunächst, nachdem Trübauge der Alte den Turm heimgesucht hatte. Sie kehrte zurück, um das Leuchtfeuer erneut zu entzünden, doch Murk-Eye führte einen zweiten Angriff an, bei dem die ganze Familie starb.",al={"familie des wärters","wer lebte im leuchtturm","massaker am leuchtturm"}}},fx={["871c093a"]={q="Warum benötigt Kapitän Grausohn Euch, um Trübauge der Alte zu töten?",a="Kapitän Grausohn ist ein Geist, der an die felsige Küste gebunden ist, wo sein Schiff an den Untiefen zerschellte. Körperlos und machtlos, um die geschlachtete Familie des Wächters physisch zu rächen oder den Küsten Gerechtigkeit zu verschaffen, kann er den Murloc-Anführer nicht selbst erschlagen. Zudem fehlt es Westfall an jeglicher organisierten Militär- oder Wachtruppe entlang der südwestlichen Strände, was die Aufgabe vollständig in die Hände reisender Abenteurer legt.",al={"warum kann grausohn trübauge nicht töten","warum benötigt grausohn mich","warum benötigt grausohn hilfe"}}},fp="18,331,20.302.0,24.344.0,20.161.0,48.264.0,32.116.0,32.89.0,32.205.0,48.181.0"}
P.entries["quest:1040"] = {n="Passage nach Beutebucht",s="In Beutebucht führt die Spur von Velinde Sternensang aus Ratschet zu Karawanenführer Ruzzgot. Reisende der Allianz suchen nun den Goblin-Karawanenführer.",h="In Beutebucht führt die Spur von Velinde Sternensang aus Ratschet zu Karawanenführer Ruzzgot.",kw={"black osprey","beutebucht","karawanenführer ruzzgot","passage nach beutebucht","ratschet","sichel von elune","velinde starsong","wharfmaster dizzywig"},ang={["faction:Alliance"]="Als Reisende der Allianz braucht Ihr in neutralen Goblinhäfen wie Ratschet und Beutebucht Geduld und diplomatisches Geschick. Mercenaries und Kartellbürokraten gehören zum Weg dazu.",["race:NightElf"]="Als Kaldorei habt Ihr einen dringenden Grund, Velinde Sternensang zu finden. Sie verschwand mit der Sichel von Elune und hinterließ ein gefährliches Rätsel in den Wäldern von Eschental."},sec={{t="Eine Spur übers Meer",b="Die Aufzeichnungen von Werftmeister Dizzywig führen die Suche nach Velinde Sternensang von Eschental bis ans Meer. Die Nachtelfenschildwache buchte in Ratschet eine Überfahrt auf der Black Osprey. Alte Frachtverzeichnisse zeigen, dass das Schiff Beutebucht im Schlingendorntal ansteuerte."},{t="Der Weg nach Beutebucht",b="Eine Goblinfähre bringt Reisende von Ratschet über das große Meer zur Südspitze der Östlichen Königreiche. In Beutebucht führt die Spur zu Karawanenführer Ruzzgot, dem Transportmeister der Goblins, den Dizzywig Velinde empfohlen hatte. Sie hatte sich nach gefährlichen Landreisen durch die südliche Wildnis erkundigt."}},faq={{q="Wer ist Velinde Sternensang?",a="Velinde Sternensang war eine Nachtelfenpriesterin, die die Bemühungen anführte, die dämonische Präsenz im Teufelswald einzudämmen. Ihre Bemühungen gerieten ins Stocken, und sie verschwand. Die Schildwachen verfolgen nun ihre Reise über das Meer.",al={"velinde","wer ist velinde","velinde starsong hintergrundgeschichte"}},{q="Warum reiste Velinde nach Beutebucht?",a="Velinde reiste nach Beutebucht, um eine Überfahrt über das große Meer zu finden. Die Black Osprey segelte von Ratschet nach Beutebucht, wo sie sich nach Landreisen in Richtung der Königreiche der Menschen und Zwerge erkundigte.",al={"warum beutebucht","velinde beutebucht","warum ging sie nach beutebucht"}},{q="Wer ist Werftmeister Dizzywig?",a="Werftmeister Dizzywig verwaltet für das Steamwheedle Cartel die Schiffsanleger von Ratschet. Von Natur aus ungeduldig, führt er Logbücher und Passagierlisten für Schiffe, die zwischen Kalimdor und den Östlichen Königreichen verkehren.",al={"dizzywig","wer ist dizzywig","werftmeister"}},{q="Wer ist Karawanenführer Ruzzgot?",a="Karawanenführer Ruzzgot ist ein in Beutebucht ansässiger Goblin-Fuhrmann. Er koordiniert Versorgungskonvois und Landtransporte durch die gefährlichen Dschungel des Schlingendorntals und darüber hinaus.",al={"ruzzgot","karawanenführer ruzzgot","wer ist ruzzgot"}},{q="Welches Schiff nahm Velinde?",a="Die Schifffahrtsregister von Werftmeister Dizzywig zeigen, dass Velinde Sternensang eine Überfahrt an Bord der Black Osprey buchte. Das Schiff segelte von Ratschet über das große Meer nach Beutebucht.",al={"velindes schiff","welches boot nahm velinde","black osprey"}},{q="Wie reise ich von Ratschet nach Beutebucht?",a="Das Steamwheedle Cartel betreibt eine Passagierfähre, die von Ratschets südlichem Anleger über das große Meer verkehrt. Sie legt in Beutebucht an der Südspitze des Schlingendorntals an.",al={"reise nach beutebucht","wie nach beutebucht kommen","boot nach beutebucht"}}},fx={["416fbc17"]={q="Warum möchte Werftmeister Dizzywig, dass Ihr nach Beutebucht geht?",a="Er hat kein persönliches Interesse an Velinde Sternensang oder ihrem Schicksal – er möchte Euch einfach nur aus seinem Büro haben. Dizzywig hält die geschäftigen Docks von Ratschet am Laufen, und das Durchwühlen alter Versandbücher nach einem alten Passagier ist schon mehr Entgegenkommen, als ein Goblin-Hafenmeister normalerweise kostenlos bietet. Sobald er bestätigt, dass sie mit der Black Osprey segelte und Landkarawanen erwähnte, sorgt ein Hinweis auf Karawanenführer Ruzzgot auf der anderen Seite des Meeres in Beutebucht dafür, dass Ihr aufhört, ihn zu belästigen, damit er sich wieder seiner Arbeit widmen kann.",al={"dizzywig motiv","warum schickt euch dizzywig","dizzywig beutebucht warum"}}},fp="20,141,22.253.0,21.306.0,24.199.0,36.195.0,28.210.0,26.176.0,27.172.0,42.164.0"}
P.entries["quest:1041"] = {n="Die Karawanenstraße",s="In Beutebucht führt die Suche nach Velinde Sternensang nordwärts nach Dunkelhain. Karawanenführer Ruzzgot erinnert sich, die vermisste Nachtelfenpriesterin durch das Schlingendorntal befördert zu haben.",h="In Beutebucht führt die Suche nach Velinde Sternensang nordwärts nach Dunkelhain.",kw={"beutebucht","karawanenführer ruzzgot","amtmann daltry","dunkelhain","dämmerwald","schlingendorntal","die karawanenstraße","velinde starsong"},ang={["faction:Alliance"]="Als Reisender der Allianz überbringt Ihr Nachrichten zwischen neutralen Goblinhäfen und entlegenen Außenposten der Allianz wie Dunkelhain und verbindet Orte in einer von jüngsten Kriegen zerrissenen Welt.",["race:NightElf"]="Als Nachtelf teilt Ihr womöglich die Sorge Eures Volkes um Velinde Sternensang, eine Sentinel-Priesterin Elunes, deren geheime Unternehmungen sie in die Östlichen Königreiche geführt haben."},sec={{t="Eine Priesterin im Dschungel",b="Karawanenführer Ruzzgot erinnert sich an Velinde Sternensang als Passagierin seiner Karawane. Eure Suche nach der vermissten Nachtelfenpriesterin hat Euch vom Eschental nach Beutebucht am südlichen Rand des Schlingendorntals geführt. Sie reiste mit seiner Karawane durch den Dschungel, ein ungewöhnlicher Weg für eine Nachtelfenpriesterin."},{t="Nordwärts nach Dunkelhain",b="Ruzzgot sagt, seine und Velindes Wege hätten sich auf der Reise nach Norden durch das Schlingendorntal getrennt. Sie brach zum Dämmerwald auf, und ihre Spur führt nach Dunkelhain. Amtmann Daltry führt die Aufzeichnungen der Stadt, darunter die Namen unbekannter Reisender, die sie betreten. Sein Register könnte den nächsten Hinweis auf Velindes Aufenthaltsort enthalten."}},faq={{q="Wer ist Velinde Sternensang?",a="Velinde Sternensang ist eine Nachtelfenpriesterin Elunes, die ihre Heimat in Kalimdor unter rätselhaften Umständen verließ. Ihr Verschwinden hat eine Suche über die Kontinente hinweg ausgelöst, die ihrer Spur vom Eschental durch die Östlichen Königreiche folgt.",al={"velinde","wer ist velinde","wen suchen wir"}},{q="Warum reiste Velinde mit einer Karawane?",a="Velinde reiste mit dem Transportunternehmen von Karawanenführer Ruzzgot durch Goblingebiet. Sie bezahlte für die Mitreise auf dem gefährlichen Weg nach Norden durch das Schlingendorntal.",al={"warum karawane","velinde karawane","ruzzgot karawane"}},{q="Wer ist Amtmann Daltry?",a="Amtmann Daltry ist der Stadtschreiber und Archivar von Dunkelhain im Dämmerwald. Inmitten der seltsamen Vorkommnisse und Bedrohungen in der Region erfasst er Fremde und Besucher.",al={"amtmann daltry","daltry dunkelhain","wer ist daltry"}},{q="Wohin führt diese Questreihe nach Dunkelhain?",a="Nachdem Ihr die Aufzeichnungen von Amtmann Daltry eingesehen habt, verweist er Euch an Jonathan Treuwein. Mit dem Gespräch mit Jonathan beginnt die Suche nach Hinweisen auf Velindes Aufenthalt im Dämmerwald bei seiner Familie.",al={"nächste quest","what comes next","nach dunkelhain"}},{q="Warum ist die Reise von Beutebucht nach Dunkelhain gefährlich?",a="Im Schlingendorntal leben Raubtiere, feindselige Trollstämme und Blutsegelbukaniere. Die Reise nach Norden ist gefährlich, deshalb müssen Reisende nahe an der Hauptstraße bleiben.",al={"gefahr im dschungel","schlingendorntal stufe","schlingendorntal gefährlich"}},{q="Wo begann diese Untersuchung?",a="Die Suche begann im Eschental, wo nachtelfische Ermittler Velindes unerklärten Aufbruch mit einem Artefakt von großer Macht bemerkten. Hinweise deuteten auf ein Schiff mit Kurs auf die südlichen Meere.",al={"ausgangspunkt","wo begann die questreihe","eschental anfang"}}},fx={a495199a={q="Warum hilft Euch Karawanenführer Ruzzgot dabei, Velinde zu finden?",a="Karawanenführer Ruzzgot hat Euch anfangs falsch eingeschätzt, aber nachdem Ihr Euch bewiesen habt, ist er bereit, sein Wissen guten Glaubens zu teilen. Eine Nachtelfen-Priesterin, die mit seiner rauen Schifffahrtsgesellschaft reiste, war ungewöhnlich genug, um ihm im Gedächtnis zu bleiben. Da er sich auf der Straße nach Norden von Velinde Sternensang getrennt hat, hat er nichts zu verlieren, wenn er Euch in Richtung Dunkelhain und zu dessen Archivar verweist.",al={"ruzzgot motiv","warum hilft ruzzgot","warum helfen velinde zu finden"}}},fp="16,171,25.306.0,18.304.0,24.239.0,41.162.0,20.155.0,49.170.1,55.177.0,35.186.0"}
P.entries["quest:1042"] = {n="Die Familie Treuwein",s="In Dunkelhain führt die Suche nach Velinde Sternensang Fremde zur Familie Treuwein. Amtmann Daltry hört von Wolfsmenschen in Eschental und schickt sie zu den Jägern.",h="In Dunkelhain führt die Suche nach Velinde Sternensang Fremde zur Familie Treuwein.",kw={"calor","treuwein","amtmann daltry","dunkelhain","dämmerwald","jonathan treuwein","velinde starsong","wolfsmenschen","worgen"},ang={["class:Hunter"]="Als Jäger erkennt Ihr die Familie Treuwein als örtliche Bestienjäger, die unnatürliche Unholde und verfluchte Raubtiere verfolgen.",["faction:Alliance"]="Als Reisender der Allianz seht Ihr, wie abgeschieden und wachsam Dämmerwalds Siedlungen sein müssen, um in den verheerten Wäldern zu bestehen.",["race:NightElf"]="Als Nachtelf findet Ihr in menschlichen Monsterjägern mit abgetrennten Köpfen von Kreaturen, die mit Velinde Sternensang in Verbindung stehen, einen beunruhigenden Hinweis auf ihre Reise."},sec={{t="Eine Spur aus Klauen und Schatten",b="Die Suche nach Velinde Sternensang führt von Kalimdors uralten Wäldern nach Dämmerwald. In Dunkelhain findet Amtmann Daltry keine städtischen Aufzeichnungen über den Aufenthalt einer elfischen Priesterin. Doch als er von wilden Wolfsmenschen in Eschental hört, lauscht er aufmerksam. Solche Bestien haben begonnen, die Wälder um die Stadt in Angst und Schrecken zu versetzen."},{t="Jäger der Nacht",b="Die Familie Treuwein jagt die Schrecken, die Dämmerwald heimsuchen. Die Einheimischen kennen sie als Jäger von Dämonen, Untoten und anderen Monstern, und sie haben bereits gegen die Wolfsmenschen gekämpft. Ihr Fährtenleser Calor schleppte kürzlich eine grausige Kette abgetrennter Wolfsmenschenköpfe durch Dunkelhains Straßen. Deshalb schickt Amtmann Daltry Euch zu Jonathan Treuwein, dem strengen Familienoberhaupt, um zu erfahren, was die Jäger über die Worgen wissen."},{t="Ein kühler Empfang",b="Jonathan Treuwein begegnet Fremden mit tiefem Misstrauen. Die Schrecken, die Dämmerwald verschlingen, lassen ihn jedem misstrauen, der unangekündigt erscheint und nach Worgen fragt. Bevor er preisgibt, was seine Jäger über die Bestien erfahren haben, verlangt er zu wissen, wer vor ihm steht und warum sie nach Dingen suchen, die besser im Dunkeln begraben blieben."}},faq={{q="Wer ist Jonathan Treuwein?",a="Jonathan Treuwein ist das Oberhaupt der Familie Treuwein in Dunkelhain. In der ganzen verheerten Region ist seine Familie als erfahrene Jäger bekannt, die Dämonen, Untote und monströse Bestien aufspüren und töten.",al={"jonathan treuwein","wer ist treuwein","oberhaupt der familie treuwein"}},{q="Warum verweist Amtmann Daltry Euch an die Familie Treuwein?",a="Amtmann Daltry hat keine Aufzeichnungen über die vermisste Nachtelfin Velinde Sternensang, doch er erkennt die Wolfsmenschen, die Ihr beschreibt. Calor, der Fährtenleser der Familie Treuwein, brachte kürzlich ihre abgetrennten Köpfe nach Dunkelhain, weshalb Daltry Euch schickt, um zu erfahren, was die Familie weiß.",al={"warum treuwein aufsuchen","amtmann daltry treuwein","warum zu jonathan gehen"}},{q="Wer ist Calor?",a="Calor ist ein Jäger und Fährtenleser, der mit der Familie Treuwein in Dunkelhain verbündet ist. Kürzlich marschierte er mit einer Kette abgetrennter Worgenköpfe durch die Stadt, ein düsteres Zeichen dafür, dass die Wolfsmenschen in der Nähe ihr Unwesen treiben.",al={"calor","wer ist calor","treuwein jäger calor"}},{q="Wie verbindet diese Quest Eschental mit Dämmerwald?",a="Die Suche beginnt in Eschental, wo Velinde Sternensang verschwunden ist und Worgen aufgetaucht sind. Die Karawanenroute führt Euch von Kalimdor über das Meer nach Dämmerwald, wo dieselben monströsen Wolfsbestien aufgetaucht sind.",al={"verbindung zu velinde starsong","warum dämmerwald","von eschental nach dunkelhain"}},{q="Warum misstraut Jonathan Treuwein Fremden so sehr?",a="Dämmerwald ist von Schatten, Untoten und finsteren Mächten überrannt, weshalb seine überlebenden Bewohner zutiefst misstrauisch sind. Wenn ein Fremder erscheint und nach tödlichen Worgen fragt, vermutet Jonathan böse Absichten, bis Ihr Euch bewährt habt.",al={"warum ist treuwein feindselig","treuweins misstrauen"}},{q="Auf welche Monster hat sich die Familie Treuwein spezialisiert?",a="Die Familie Treuwein jagt monströse Bedrohungen, besonders Dämonen, Untote und seltsame Bestien wie die Worgen, die Dämmerwald heimsuchen.",al={"treuwein monster","was jagt die familie treuwein"}}},fp="18,159,28.304.0,20.404.0,16.313.1,24.183.0,55.251.0,13.195.0,50.220.0,51.212.0,53.126.0"}
P.entries["quest:1043"] = {n="Die Sichel von Elune",s="In Dunkelhain führt die Suche nach der Sichel von Elune zur Jagd auf Worgen. Jonathan Treuwein schickt Euch nach Rolands Verdammnis, wo die Bestien erstmals auftauchten, und verknüpft damit ein uraltes Nachtelfenrelikt in Kalimdor mit den Worgen, die den Dämmerwald heimsuchen.",h="In Dunkelhain führt die Suche nach der Sichel von Elune zur Jagd auf Worgen.",kw={"calor","dunkelhain","dämmerwald","jonathan treuwein","nachtheuler","rolands verdammnis","sichel von elune","velinde starsong","worgen"},ang={["class:Druid"]="Als Druide erkennt Ihr, wie die von der Sichel von Elune entfesselten wilden Worgen vor dem Preis unkontrollierbarer Kräfte warnen.",["faction:Alliance"]="Die Aufklärung des Rätsels um die Nachtheuler-Worgen gibt Dunkelhain und der Allianz erste handfeste Antworten zu den Schrecken, die den südlichen Dämmerwald durchstreifen.",["race:NightElf"]="Als Nachtelf enthüllt Euch der Fund der letzten Ruhestätte von Priesterin Velinde Sternensang den schrecklichen Preis dafür, dass die Sichel von Elune der Obhut der Sisterhood entglitt."},sec={{t="Jagd im Dunkeln",b="Ihr habt die Spur von Priesterin Velinde Sternensang durch Kalimdor verfolgt und mit dem Haushalt der Carevin Family in Dunkelhain gesprochen. Nun verfolgen Jonathan Treuwein und Ihr dasselbe Ziel. Nachtheuler-Worgen haben den südlichen Dämmerwald überrannt, Minenarbeiter vertrieben und bedroht, was von der Ortschaft noch übrig ist. Treuwein versteht ihren übernatürlichen Ursprung nicht, doch er weiß, wie wertvoll ein williger Jäger ist. Er weist Euch den Weg nach Rolands Verdammnis, wo die Scheusale zuerst gesichtet wurden."},{t="Geister von Rolands Verdammnis",b="Tief in Rolands Verdammnis durchstreifen Rudel bösartiger Nachtheuler die Tunnel. Dort, unter ihnen, verbirgt ein unberührter Erdhaufen das Gespenst von Velinde Sternensang. Die Nachtelfenpriesterin kam mit der Sichel von Elune in diese Höhle, fand jedoch unter dem Dämmerwald ihr Ende. Velinde beklagt, dass die von ihr entfesselten Worgen nun ungezügelt wüten und die von ihrer Göttin gewährte Sichel verloren ist."}},faq={{q="Wo suche ich nach Spuren der Sichel?",a="Durchsucht Rolands Verdammnis, die verlassene Mine im südöstlichen Dämmerwald. Kämpft Euch durch die Nachtheuler-Worgen bis zu einem unberührten Erdhaufen in den Tunneln.",al={"wo ist die sichel","sichel von elune fundort","rolands verdammnis höhle"}},{q="Wer ist Jonathan Treuwein?",a="Jonathan Treuwein gehört zur Carevin Family in Dunkelhain. Da nur wenige Verteidiger gegen das Böse übrig sind, tauscht er Informationen mit Fremden aus, die bereit sind, die Worgen zu dezimieren.",al={"jonathan treuwein","treuwein dunkelhain"}},{q="Was geschah mit Velinde Sternensang in der Mine?",a="Ein unberührter Erdhaufen tief in Rolands Verdammnis birgt die Antwort auf Velinde Starsongs Schicksal und den Verbleib der Sichel. Untersucht ihn, um zu erfahren, was Ihr Jonathan Treuwein zurückbringen sollt.",al={"velinde starsong schicksal","was geschah mit velinde"}},{q="Was ist die Sichel von Elune?",a="Die Sichel von Elune ist ein heiliges Nachtelfenartefakt, das Priesterin Velinde Sternensang anvertraut wurde. Die Sentinels glauben, dass die Göttin Elune es ihr als Gunstbeweis gewährte.",al={"was ist die sichel","sichel von elune hintergrund"}},{q="Warum tauchten die Worgen im Dämmerwald auf?",a="Jonathan Treuwein sagt, die Worgen seien aus dem Nichts aufgetaucht und zuerst in Rolands Verdammnis im Süden entdeckt worden. Spuren der Sichel von Elune in der Mine enthüllen, warum sie auftauchten.",al={"warum worgen im dämmerwald","dämmerwald worgen ursprung"}},{q="Wer ist Calor?",a="Calor ist ein Vertrauter der Carevin Family in Dunkelhain. Nach Euren Entdeckungen in Rolands Verdammnis weist Jonathan ihn an, sich ganz darauf zu konzentrieren, die Bedrohung durch die Worgen einzudämmen.",al={"npc calor","wer ist calor"}}},fx={["48e90786"]={q="Warum möchte Jonathan Treuwein, dass dies erledigt wird?",a="Der Dämmerwald wird von allen Seiten von Monstern bedrängt, und die Worgen gehören zu den tödlichsten Raubtieren, die durch die dunklen Wälder streifen. Jonathan Treuwein versteht vielleicht nicht vollständig Eure Jagd nach der Sichel von Elune, aber er erkennt eine Gelegenheit. Wenn Eure Jagd die Bestien zurücktreibt, die Rolands Verdammnis befallen haben, und aufdeckt, wie sie dorthin gelangt sind, unterstützt dies die Verteidigung von Dunkelhain. Die Nachtwache hat kaum Ressourcen übrig, daher hilft jede Information oder Dezimierung des wilden Rudels direkt dabei, die überlebenden Stadtbewohner zu schützen.",al={"warum treuwein helfen","jonathan treuwein motiv","warum möchte treuwein sense"}}},fp="19,237,18.439.0,23.381.1,40.150.0,24.167.0,46.185.1,28.160.0,38.176.1,13.168.1"}
P.entries["quest:1044"] = {n="Beantwortete Fragen",s="Die Suche nach Velinde Sternensang führt Euch vom Eschental nach Darnassus, wo ein Bericht auf Euch wartet.",h="Die Suche nach Velinde Sternensang führt Euch vom Eschental nach Darnassus, wo ein Bericht auf Euch wartet.",kw={"beantwortete fragen","darnassus","dämmerwald","jonathan treuwein","rolands verdammnis","sichel von elune","thyn'tel klingenweber","velinde starsong","worgen"},ang={["class:Priest"]="Als Priester spürt Ihr vielleicht die spirituelle Schwere von Velindes Geschichte: die Macht von Elunes Gaben und die Gefahr, unbekannte Bestien Eurem Willen unterwerfen zu wollen.",["faction:Alliance"]="Als Mitglied der Allianz seht Ihr die Verbindungen zwischen den Nachtelfen in Kalimdor und den bedrängten menschlichen Siedlungen des Dämmerwalds, die beide finsteren Bedrohungen gegenüberstehen.",["race:NightElf"]="Als Nachtelf könnt Ihr der Führung helfen, der Spur einer vermissten Priesterin und eines heiligen Artefakts zu folgen."},sec={{t="Eine tragische Wahrheit",b="Velinde Starsongs Spur führt vom Eschental über zwei Kontinente zu den heimgesuchten Hainen und verlassenen Minen des Dämmerwalds. Sie ergriff die Sichel von Elune, um Kalimdor gegen Dämonen zu verteidigen, und beschwor damit dann die grimmigen Worgen. Velinde verlor die Kontrolle über sie und starb tief in der Mine von Rolands Verdammnis. Der Dämmerwald blieb mit den monströsen Folgen zurück."},{t="Rückkehr nach Darnassus",b="Nachdem Velindes Tagebuch geborgen und ihr Schicksal geklärt wurde, schickt Jonathan Treuwein im Dämmerwald Euch zurück nach Teldrassil. Schildwache Thyn'tel Klingenweber nimmt Euren Bericht in Darnassus entgegen. Velinde war eine enge Freundin von Hohepriesterin Tyrande Wisperwind, daher trifft ihr Schicksal die Sisterhood of Elune persönlich und spirituell schwer."},{t="Ein verschollenes Artefakt",b="Velindes Schicksal ist bekannt, doch die Sichel von Elune bleibt verschollen. Die Göttin schenkte sie als heilige Gabe und Waffe, und nun liegt sie verloren in der Wildnis, fern der Priesterinnen, die sie verehrten. Wilde Worgen durchstreifen die Östlichen Königreiche, eine anhaltende und unberechenbare Bedrohung, entstanden durch den Verlust der Sichel."}},faq={{q="Was ist die Quest Beantwortete Fragen?",a="Beantwortete Fragen schließt die Suche nach Velinde Sternensang ab. Jonathan Treuwein im Dämmerwald schickt Euch nach Darnassus, um Thyn'tel Klingenweber über ihr Schicksal und den Verbleib der Sichel von Elune zu berichten.",al={"beantwortete fragen quest","beantwortete fragen classic","ende der quest sichel von elune"}},{q="Wer war Velinde Sternensang?",a="Velinde Sternensang war eine Nachtelfenpriesterin Elunes und die Vorgängerin von Schildwache Melyria Frostschatten im Eschental. Sie sollte die Dämonen im Teufelswald zurückhalten und erhielt die Sichel von Elune, verschwand dann jedoch. Ihre Spur führte über das Meer in den Dämmerwald.",al={"velinde starsong","wer ist velinde","was geschah mit velinde"}},{q="Wo ist die Sichel von Elune am Ende dieser Quest?",a="Die Sichel von Elune ist noch immer verschollen, als Ihr Thyn'tel Klingenweber in Darnassus Bericht erstattet. Jonathan Treuwein bittet Euch, ihr Eure Erkenntnisse zu überbringen.",al={"wo ist die sichel von elune","wurde die sichel gefunden","sichel von elune fundort"}},{q="Wie ist Tyrande Wisperwind mit Velinde verbunden?",a="Hohepriesterin Tyrande Wisperwind und Velinde Sternensang waren vor Velindes Verschwinden enge Freundinnen. Ihr Schicksal lastet schwer auf den Anführern der Nachtelfen.",al={"tyrande und velinde","verbindung zur hohepriesterin"}},{q="Wer ist Jonathan Treuwein?",a="Jonathan Treuwein ist ein menschlicher Bewohner des Dämmerwalds, der Euch bei der Suche in den örtlichen Minen hilft. Er schwört, die Worgen dort in Schach zu halten, und schickt Euch dann nach Kalimdor, um Velindes Volk Eure Erkenntnisse mitzuteilen.",al={"jonathan treuwein","wer vergibt beantwortete fragen"}},{q="Wo steht Thyn'tel Klingenweber?",a="Thyn'tel Klingenweber befindet sich in Darnassus auf der Insel Teldrassil. Sie dient der Führung der Nachtelfen und leitet die Suche nach vermissten Schildwachen und Priesterinnen.",al={"wo ist thyn'tel klingenweber","thyn'tel klingenweber standort","beantwortete fragen abgeben"}}},fx={["6f485fee"]={q="Warum schickt Jonathan Treuwein Euch zurück nach Darnassus?",a="Jonathan Treuwein erkennt, dass das, was in den Minen des Dämmerwalds aufgedeckt wurde, weit über die Nachtwache hinausgeht. Velinde Sternensang diente den Nachtelfen und der Göttin Elune, und Treuwein glaubt, dass ihr Schicksal – und der beunruhigende Verlust der Sichel von Elune – eine wichtige Nachricht ist, die direkt ihrem Volk in Darnassus überbracht werden muss, anstatt in den Minen begraben zu bleiben.",al={"warum möchte jonathan treuwein das erledigt haben","jonathan treuwein motiv","warum zurück nach darnassus"}}},fp="18,95,14.345.1,19.325.1,18.303.1,37.200.1,25.251.0,54.147.1,48.148.0,24.197.1,38.163.0"}
P.entries["quest:1045"] = {n="Raenes Säuberung",s="Am Lake Mystral bittet Krolg Euch, Ran Bloodtooth zu töten. Getarnt durch Dartols Rute der Transformation könnt Ihr das Vertrauen der unverdorbenen Furbolgs gewinnen. Krolg hegt Groll gegen die Nachtelfen und fürchtet die Fäulnis unter seinem Volk. Er will, dass die Furbolgs die Ihren zur Rechenschaft ziehen.",h="Am Lake Mystral bittet Krolg Euch, Ran Bloodtooth zu töten.",kw={"eschental","bloodtooth wache","verderbnis","dartols rute","furbolg","krolg","lake mystral","ran bloodtooth"},ang={["class:Druid"]="Als Druide seht Ihr in Ran Bloodtooth ein natürliches Geschöpf, das der dämonischen Verderbnis verfallen ist und das Gleichgewicht des Eschentals bedroht.",["faction:Alliance"]="Als Champion der Allianz nutzt Ihr Dartols verzauberte Rute, um Euch unbemerkt zu nähern und abtrünnigen Häuptlingen tief hinter den feindlichen Linien entgegenzutreten.",["race:NightElf"]="Als Nachtelf mögen Krolgs Worte für Euch wie ein hartes Urteil klingen. Die örtlichen Stämme geben dem Hochmut der Kaldorei die Schuld am einstigen Auseinanderbrechen und der anhaltenden Verderbnis des Eschentals, trotz der langen Wacht Eures Volkes über den Wald."},sec={{t="Ein verbitterter Einsiedler",b="Nahe Lake Mystral lebt Krolg abseits der anderen, vertrieben und müde. Er macht den uralten Hochmut der Nachtelfen für das Unheil über Kalimdor und die dunkle Fäulnis verantwortlich, die sich im Eschental ausbreitet. Dartols Rute der Transformation lässt Euch den Furbolgs in Verkleidung näherkommen. Krolg hasst die Kaldorei, doch er fordert weder ein Gemetzel noch den Tod Unschuldiger."},{t="Die Ihren zur Rechenschaft ziehen",b="Krolg glaubt, dass sein Volk für seine eigenen Taten einstehen muss, statt der dämonischen Verderbnis nachzugeben, die die Stämme im Griff hat. Die Verderbnis gab ihnen nicht ihre Schwächen; sie verstärkte ihre schlimmsten Triebe. Ran Bloodtooth zeigt die Gefahr. Schon vor der Verderbnis war der Häuptling rücksichtslos und machthungrig und nahm die Dunkelheit bereitwillig an. Nun bedroht er Elfen und unschuldige Tiere gleichermaßen. Krolg wird nicht zulassen, dass ein einzelner Furbolg für sie alle spricht."},{t="Eine gemeinsame Pflicht",b="Getarnt durch Dartols Magie schlagt Ihr gegen Ran Bloodtooth und seine Elitewachen zu. Ihr Tod kann Gerechtigkeit bringen, ohne weiteren Zwist unter den Stämmen zu schüren. Ein gegen die Nachtelfen verbitterter Furbolg und ein Agent der Allianz verfolgen ein gemeinsames Ziel gegen den Wahnsinn im Eschental: den heiligen Wald zu reinigen."}},faq={{q="Warum hasst Krolg die Nachtelfen?",a="Krolg macht die einstigen Eingriffe der Nachtelfen in gefährliche Magie für die Verderbnis des Eschentals verantwortlich. Er gibt ihnen die Schuld an der Verderbnis des Landes und dem Leid der Stämme.",al={"krolg nachtelfenhass","warum hasst krolg elfen","krolgs vorgeschichte"}},{q="Wer ist Ran Bloodtooth?",a="Ran Bloodtooth ist ein verderbter, machthungriger Furbolghäuptling, der in den Bergen östlich von Lake Mystral lagert. Die dunklen Mächte, die das Eschental vergiften, haben ihn in den Wahnsinn getrieben. Sein Verlangen nach Gewalt bedroht die natürlichen Geschöpfe des Waldes.",al={"ran bloodtooth hintergrund","wer ist bloodtooth","ran bloodtooth"}},{q="Warum will Krolg Ran Bloodtooth tot sehen?",a="Krolg hegt Groll gegen die Nachtelfen, doch er duldet kein Abschlachten Unschuldiger. Er glaubt, dass die Furbolgs die Ihren zur Rechenschaft ziehen müssen. Rans Verderbnis hat ihn zu einer Bedrohung für den ganzen Wald gemacht.",al={"warum ran bloodtooth töten","krolgs beweggrund bloodtooth"}},{q="Wie können Spieler der Allianz mit Krolg sprechen, ohne angegriffen zu werden?",a="Dartols Rute der Transformation lässt Euch die Gestalt eines Furbolgs annehmen und Euch Krolg gefahrlos nähern. Die verzauberte Rute gelangte während eines früheren Abschnitts Eurer Reise in Euren Besitz.",al={"wie mit krolg sprechen","dartols rute krolg","warum ist krolg freundlich"}},{q="Wo befindet sich Ran Bloodtooth?",a="Ran Bloodtooth und seine Wachen lagern in den Bergen östlich von Krolgs Zuflucht nahe Lake Mystral.",al={"ran bloodtooth aufenthaltsort","wo ist ran bloodtooth","blutreißers lager"}},{q="Wie hilft Ran Bloodtooths Tod, das Eschental zu reinigen?",a="Ran Bloodtooths Tod beseitigt einen der gewalttätigsten Furbolgs, die durch die Verderbnis gestärkt wurden, eine Gefahr für jedes natürliche Geschöpf des Waldes. Das Eschental bleibt verdorben, doch Krolg sieht darin einen kleinen Schritt hin zu seiner einstigen Pracht.",al={"eschental reinigen ran","warum gehört bloodtooth zu raenes säuberung"}}},fp="17,259,15.361.0,18.424.0,13.319.1,36.169.0,22.228.0,40.198.0,63.164.0,32.101.0,55.227.0"}
P.entries["quest:1046"] = {n="Raenes Säuberung",s="In Astranaar bringt Ihr Raenes Säuberung mit Ran Blutreißers Schädel zum Abschluss. Die Suche begann mit Teronis, und die Furbolgbedrohung im Eschental ist nun eingedämmt.",h="In Astranaar bringt Ihr Raenes Säuberung mit Ran Blutreißers Schädel zum Abschluss.",kw={"eschental","astranaar","dartol's rod","furbolg","krolg","raene wolfsläufer","raenes säuberung","ran blutreißer","teronis"},ang={["faction:Alliance"]="Als Mitglied der Allianz zeigt Ihr mit der Übergabe von Blutreißers Schädel, dass Euer Volk Astranaar gemeinsam mit den nachtelfischen Schildwachen entschlossen verteidigt.",["race:NightElf"]="Als Nachtelf ehrt Ihr gefallene Verbündete wie Teronis, indem Ihr Ran Blutreißers Wüten beendet, und helft, die heiligen Haine des Eschentals zurückzuerobern."},sec={{t="Eine bittere Trophäe",b="Krolg schickt Euch zurück nach Astranaar, nachdem Ran Blutreißer gefallen ist. Ihr bringt den abgetrennten Schädel des Häuptlings zu Schildwache Raene Wolfsläufer. Er beweist, dass die Bedrohung, die in den Tiefen des Waldes umherstreifte, niedergestreckt wurde."},{t="Zum Andenken an Teronis",b="Raene Wolfsläufer legt Ran Blutreißers Schädel an einem Ort der Ehrfurcht neben Dartol's Rod. Das düstere Zeichen ehrt Teronis, dessen Nachforschungen zur Reinigung der verderbten Furbolgs dieses verzweifelte Unterfangen einleiteten."}},faq={{q="Wer ist Ran Blutreißer?",a="Ran Blutreißer war unter den verderbten Furbolgs die größte Bedrohung in den Wäldern des Eschentals. Sein Fall beseitigt einen Häuptling, der das Waldland heimsuchte.",al={"ran blutreißer","blutreißers schädel","wer war ran blutreißer"}},{q="Warum will Raene Wolfsläufer den Schädel?",a="Raene Wolfsläufer bewahrt Ran Blutreißers Schädel neben Dartol's Rod auf, um den Sieg zu ehren und an die überwundene Gefahr zu erinnern. Der Schädel beweist, dass die Schildwachen und ihre Verbündeten eine tödliche Bedrohung für das Eschental niedergestreckt haben.",al={"warum schädel","wolfsläufer schädel","was macht raene mit dem schädel"}},{q="Wer war Teronis?",a="Teronis war ein nachtelfischer Ermittler, dessen Tod zu Beginn der Suche die Jagd nach den reinigenden Edelsteinen und Dartol's Rod antrieb. Mit dem Abschluss der Arbeit wird sein unvollendeter Auftrag weitergeführt.",al={"teronis","wer ist teronis","teronis stolz"}},{q="Wo endet diese Quest?",a="Ihr schließt die Arbeit in Astranaar ab, wo Ihr mit Schildwache Raene Wolfsläufer sprecht. Es ist die wichtigste Siedlung der Nachtelfen im Eschental.",al={"abgabeort","wo ist raene","raene wolfsläufer aufenthaltsort"}},{q="Wer ist Krolg?",a="Krolg ist ein Verbündeter, der Euch schickt, um Ran Blutreißers abgetrennten Schädel nach Astranaar zurückzubringen. Dort kann Euer Volk den Sieg würdigen.",al={"krolg","wer gibt die quest","npc krolg"}},{q="Was ist Dartol's Rod?",a="Dartol's Rod ist ein verzaubertes Relikt, das während dieser Ereignisse zusammengesetzt wurde. Es ist durch tiefe magische Bande mit dem Wesen der Furbolgs und der Reinigung verbunden.",al={"dartol's rod","stab der verwandlung","furbolgstab"}}},fx={d3b35236={q="Warum schickt Krolg Euch nach Astranaar?",a="Nachdem Ran Bloodtooth, die stärkste Furbolg-Bedrohung im Eschental, erschlagen wurde, erkennt Krolg Euren Triumph an. Da er Euch dank Dartol's Rod für einen seiner Artgenossen hält, gibt er Euch Rans Schädel und sagt Euch, Ihr sollt zu Eurem eigenen Stamm zurückkehren, ihnen die Trophäe zeigen und Euch im Ruhm Eures Sieges sonnen.",al={"warum möchte krolg das erledigt haben","krolg motiv","warum krolg schädel astranaar"}}},fp="17,162,15.206.0,20.209.1,22.139.0,41.217.0,16.190.1,26.126.0,13.135.0,21.123.0"}
P.entries["quest:1048"] = {n="Into The Scarlet Monastery",s="Varimathras in Unterstadt bittet Euch, gegen Anführer und Champions von Scarlet vorzugehen. Ihre Niederlage ist ihm so wichtig, dass er Eure Rückmeldung erwartet.",h="Varimathras in Unterstadt bittet Euch, gegen Anführer und Champions von Scarlet vorzugehen.",kw={"herod","hundemeister loksey","mograine","scarlet","scarlet champion","das scharlachrote kloster","unterstadt","varimathras","whitemane"},sec={{t="Ein Bericht für Varimathras",b="Varimathras schickt Euch gegen vier scharlachrote Gestalten: Hochinquisitor Whitemane, Scharlachroter Kommandant Mograine, Herod, the Scarlet Champion, und Hundemeister Loksey. Sobald sie getötet sind, sollt Ihr Euch bei ihm in der Unterstadt zurückmelden."}},faq={{q="Wer erteilt diesen Auftrag?",a="Varimathras erteilt ihn und erwartet, dass Ihr ihm in Unterstadt Bericht erstattet.",al={"wer hat mich geschickt","varimathras auftrag"}},{q="Wen soll ich besiegen?",a="Die genannten Ziele sind Hochinquisitor Whitemane, der Scharlachrote Kommandant Mograine, Herod, der Scarlet Champion und Hundemeister Loksey.",al={"wen töten","scarlet ziele"}},{q="Wo erstatte ich Bericht?",a="Erstattet Varimathras in Unterstadt Bericht.",al={"varimathras bericht erstatten","wohin zurückkehren"}}},fp="26,145,24.228.0,26.76.0,28.129.0,23.44.0"}
P.entries["quest:1050"] = {n="Mythologie der Titanen",s="In Eisenschmiede sucht Bibliothekarin Mae Paledust Mythology of the Titans, ein Buch, das im alten Kloster von Tirisfal gelegen haben soll. Sein Studium könnte zeigen, was die Vergangenheit über das Unbekannte lehren kann, das vor uns liegt.",h="In Eisenschmiede sucht Bibliothekarin Mae Paledust Mythology of the Titans, ein Buch, das im alten Kloster...",kw={"buch","eisenschmiede","bibliothekarin mae paledust","mae paledust","mythology of the titans","altes kloster","tirisfal","titanen"},sec={{t="Ein verschollener Band",b="Bevor Unheil über Lordaeron hereinbrach, beherbergte das alte Kloster in Tirisfal eine Bibliothek voller Wissen. Mae bittet Euch, ihr ein Buch namens Mythology of the Titans zu bringen. Es soll dort sein, und sie hofft, dass sein Studium Geheimnisse der Vergangenheit enthüllen wird."}},faq={{q="Wer bittet um das Buch?",a="Bibliothekarin Mae Paledust in Eisenschmiede bittet Euch, ihr Mythology of the Titans zu bringen.",al={"wer will es","mae paledust buch","bibliothekarin mae"}},{q="Wo soll sich Mythology of the Titans befinden?",a="Gerüchten zufolge befindet sich das Buch in der Bibliothek des alten Klosters in Tirisfal.",al={"wo ist das buch","klosterbuch","titanenbuch fundort"}},{q="Was ist Mythology of the Titans?",a="Mythology of the Titans ist ein Buch, das in der Bibliothek des alten Klosters in Tirisfal aufbewahrt worden sein soll.",al={"was ist das buch","titanenmythologie","mythologiebuch"}},{q="Warum möchte Mae das Buch haben?",a="Mae hofft, dass das Studium des Buches Geheimnisse der Vergangenheit enthüllen und helfen könnte, sich auf das Unbekannte vorzubereiten.",al={"warum es holen","warum mae es braucht","wozu dient es"}}},fp="23,191,13.246.0,27.82.0,44.81.0,32.107.0,27.92.0"}
P.entries["quest:1052"] = {n="Auf dem Scharlachroten Pfad",s="Bruder Anton schickt Euch von Desolace nach Süderstade mit einem versiegelten Brief für Raleigh den Andächtigen. Eure Taten gegen die Untoten sind erst der Anfang; die wahre Gefahr der Seuche liegt in Lordaeron.",h="Bruder Anton schickt Euch von Desolace nach Süderstade mit einem versiegelten Brief für Raleigh den...",kw={"bruder anton","auf dem scharlachroten pfad","herdweiler","empfehlungsschreiben","lordaeron","raleigh der andächtige","das scharlachrote kloster","süderstade","tirisfal"},sec={{t="Festungen des Kreuzzugs",b="Bruder Anton ist stolz auf die Festungen des Scharlachroten Kreuzzugs in Lordaeron. Der Kreuzzug beansprucht Bastionen der Läuterung von Herdweiler bis Tirisfal. Eure Arbeit gegen die Untoten in Desolace habe Euch bewährt, sagt Anton. Doch die wahre Gefahr der Seuche liegt in Lordaeron."},{t="Ein Brief für Süderstade",b="Bruder Anton schickt Euch nach Süderstade, einer Stadt in den Östlichen Königreichen, um Raleigh den Andächtigen, einen Kreuzfahrer, zu finden. Anton versiegelt einen Brief mit seinem Zeichen. Er sagt, Raleigh werde Euch Geleit zu einem Ehrenplatz im Scharlachroten Kloster geben."},{t="Raleighs Reaktion",b="Raleigh bricht das Siegel und liest Bruder Antons Brief. Die Nachricht, dass Anton noch immer die Kunde vom Scharlachroten Kreuzzug verbreitet, beunruhigt Raleigh. Er sagt Euch, dass hier etwas Euer Verständnis übersteigt."}},faq={{q="Wer schickt Euch auf diese Reise?",a="Bruder Anton gibt Euch ein versiegeltes Empfehlungsschreiben für Raleigh den Andächtigen.",al={"wer vergibt auf dem scharlachroten pfad","questgeber auf dem scharlachroten pfad"}},{q="Wohin werdet Ihr geschickt?",a="Bruder Anton schickt Euch nach Süderstade in den Östlichen Königreichen, um Raleigh den Andächtigen, einen Kreuzfahrer, zu finden.",al={"wohin gehen","wo ist raleigh","auf dem scharlachroten pfad ort"}},{q="Was soll der Brief laut Bruder Anton bewirken?",a="Anton sagt, Raleigh werde Euch nach dem Lesen seines versiegelten Briefes zu einem Ehrenplatz im Scharlachroten Kloster geleiten.",al={"was bewirkt der brief","empfehlungsschreiben zweck"}},{q="Welches Gebiet beansprucht der Scharlachrote Kreuzzug in Lordaeron?",a="Bruder Anton sagt, der Scharlachrote Kreuzzug beanspruche Festungen von Herdweiler bis Tirisfal, Bastionen der Läuterung, auf die er stolz ist.",al={"gebiete des scharlachroten kreuzzugs","wo sind die festungen des scharlachroten kreuzzugs"}}},fp="21,192,26.267.0,23.236.0,18.200.1,30.79.0,25.103.0,47.116.0,59.131.0"}
P.entries["quest:1053"] = {n="In the Name of the Light",s="Raleigh der Andächtige in Süderstade bittet Euch, Euch vier namentlich genannten Gestalten zu stellen. Er erwartet Euren Bericht, wenn die Arbeit getan ist.",h="Raleigh der Andächtige in Süderstade bittet Euch, Euch vier namentlich genannten Gestalten zu stellen.",kw={"herod","hochinquisitor whitemane","hundemeister loksey","raleigh der andächtige","scarlet champion","scharlachroter kommandant mograine","süderstade"},sec={{t="Raleighs Auftrag",b="Raleigh der Andächtige in Süderstade schickt Euch gegen Hochinquisitor Whitemane, Scharlachroten Kommandanten Mograine, Herod, the Scarlet Champion und Hundemeister Loksey. Wenn Ihr ihnen begegnet seid, erwartet Raleigh Euren Bericht."}},faq={{q="Wer bittet mich darum?",a="Raleigh der Andächtige in Süderstade bittet Euch, vier namentlich genannte Gestalten zur Rede zu stellen und ihm Bericht zu erstatten.",al={"wer gab den auftrag","raleighs auftrag"}},{q="Wem soll ich mich stellen?",a="Die genannten Figuren sind Hochinquisitor Whitemane, Scharlachroter Kommandant Mograine, Herod, the Scarlet Champion und Hundemeister Loksey.",al={"wen töten","ziele"}},{q="Wo soll ich Bericht erstatten?",a="Erstattet Raleigh dem Andächtigen in Süderstade Bericht.",al={"wo bericht erstatten","bericht an raleigh"}}},fp="24,118,16.211.0,23.96.0,26.128.0,23.48.0"}
P.entries["quest:1054"] = {n="Die Auswahl der Bedrohung",s="Astranaar fürchtet einen Angriff der Furbolgs der Distelfelle, die sich im Norden sammeln. Raene Wolfsläufer bittet Euch, ihren Häuptling Dal Blutklaue zu töten, bevor sie zuschlagen.",h="Astranaar fürchtet einen Angriff der Furbolgs der Distelfelle, die sich im Norden sammeln.",kw={"eschental","astranaar","die auswahl der bedrohung","dal blutklaue","furbolg","raene wolfsläufer","distelfelle"},ang={["class:Druid"]="Als Druide betrachtet Ihr den Wahnsinn der Distelfelle mit tiefer Trauer. Die anhaltende Verderbnis in Eschental macht aus edlen Furbolgs blutrünstige Bestien.",["faction:Alliance"]="Ihr wisst, dass Astranaar für die Nachschubwege und die Verständigung der Allianz im zentralen Kalimdor lebenswichtig ist. Die Gefahr nördlich der Stadt verlangt rasches Handeln.",["race:NightElf"]="Als Kaldorei steht Ihr vor dem Schmerz, uralte, dem Wahnsinn verfallene Verbündete niederzustrecken, während Ihr zu brutalen Maßnahmen greift, um Astranaar vor dem Untergang zu bewahren."},sec={{t="Drohende Gefahr im Norden",b="Astranaar liegt im Herzen von Eschental, auf allen Seiten von nahen Gefahren umgeben. Die Furbolgs der Distelfelle leben direkt nördlich der Stadt. Einst friedliche Waldbewohner, sind sie wie viele ihrer Artgenossen dem Wahnsinn und der Aggression verfallen. Späher der Schildwachen haben beobachtet, wie ihre Zahl in den vergangenen Monaten gewachsen ist. Nun fürchten sie, dass der Stamm geschlossen gegen Astranaar ziehen wird."},{t="Schlag gegen den Häuptling",b="Raene Wolfsläufer ruft Reisende dazu auf, zuzuschlagen, bevor die Distelfelle Astranaars Palisaden überrennen. Dal Blutklaue führt den Stamm und gibt seinen Mitgliedern Ordnung und Mut. Die Schildwachen bitten Euch, seinen Schädel nach Astranaar zurückzubringen. Sie hoffen, dass sein Tod die Einigkeit der Furbolgs bricht und der bedrängten Stadt wertvolle Zeit verschafft."}},faq={{q="Wer vergibt die Quest Die Auswahl der Bedrohung?",a="Raene Wolfsläufer, eine Kommandantin der Schildwachen in der Nachtelfenstadt Astranaar, bittet Euch zu handeln.",al={"questgeber","wer startet die auswahl der bedrohung","wo beginnt die auswahl der bedrohung"}},{q="Warum will Astranaar Dal Blutklaue tot sehen?",a="Dal Blutklaue führt den Stamm der Distelfelle direkt nördlich von Astranaar. Ihre Zahl wächst rasch, und Raene Wolfsläufer fürchtet, dass er einen Angriff anführen wird, wenn seine Führung nicht gebrochen wird.",al={"warum dal blutklaue töten","dal blutklaue hintergrund","warum die distelfelle angreifen"}},{q="Warum sind die Furbolgs der Distelfelle den Nachtelfen feindlich gesinnt?",a="Furbolgs und Nachtelfen waren einst Verbündete, doch dämonische und verderbende Einflüsse in ganz Eschental haben viele Stämme, darunter die Distelfelle, in gewalttätige Raserei und Angst vor Fremden getrieben.",al={"warum greifen furbolgs an","verderbte furbolgs eschental","distelfelle hintergrund"}},{q="Wo ist Dal Blutklaue zu finden?",a="Dal Blutklaue ist im Lager der Distelfelle und den nahe gelegenen Grabhügeln zu finden, direkt nördlich von Astranaar in Eschental.",al={"dal blutklaue fundort","wo ist dal blutklaue"}},{q="Beseitigt der Tod von Dal Blutklaue die Bedrohung durch die Furbolgs dauerhaft?",a="Nein. Raene Wolfsläufer sagt, dass Dal Blutklaues Tod die Angriffslust der Distelfelle eine Zeit lang eindämmen wird. Solange die Verderbnis Eschental im Griff hat, bleiben die Furbolgs eine Gefahr.",al={"sind die distelfelle besiegt","haben wir astranaar gerettet"}},{q="Welcher Beweis für Dal Blutklaues Tod wird verlangt?",a="Bringt Dal Blutklaues Schädel direkt zu Raene Wolfsläufer in Astranaar.",al={"was zu raene bringen","die auswahl der bedrohung abgabegegenstand"}}},fx={d8b26d15={q="Wer ist Dal Bloodclaw?",a="Dal Bloodclaw ist der Häuptling der Distelfell-Furbolgs, die in ihrem Dorf direkt nördlich von Astranaar leben. Unter seiner Führung haben sich die verderbten Furbolgs in den letzten Monaten schnell vermehrt und drohen, die umliegenden Wälder zu überwältigen und einen Großangriff auf die Nachtelfensiedlung zu starten.",al={"wer ist dal bloodclaw","wer ist der furbolg häuptling","dal bloodclaw hintergrund"}},["05594dd8"]={q="Warum benötigt Raene Wolfsläufer einen Abenteurer anstelle der Astranaar-Schildwachen?",a="Die im Astranaar stationierten Schildwachen sind damit ausgelastet, die Stadt selbst gegen die von allen Seiten eindringenden Bedrohungen zu verteidigen. Raene Wolfsläufer muss zurückbleiben, um die lokale Verteidigung zu koordinieren, was fähige Reisende zur idealen Wahl macht, um in das Gebiet der Distelfell zu schlüpfen und ihren Anführer zu erledigen, bevor ein Angriff Gestalt annimmt.",al={"warum schickt ihr mich","warum schickt raene keine wachen","warum greifen astranaar schildwachen nicht an"}}},fp="18,164,28.347.0,22.324.0,39.91.0,43.183.0,59.191.0,33.114.0,64.172.0,48.70.0"}
P.entries["quest:1055"] = {n="Raenes Säuberung",s="Am versteckten Schrein in Eschental habt Ihr den Stab der Verwandlung wiederhergestellt. Nun müsst Ihr ihn zu Shael'dryn an ihrem Mondbrunnenheiligtum zurückbringen.",h="Am versteckten Schrein in Eschental habt Ihr den Stab der Verwandlung wiederhergestellt.",kw={"eschental","astranaar","elune","versteckter schrein","mondbrunnen","raenes säuberung","stab der verwandlung","shael'dryn"},ang={["class:Priest"]="Als Priester helft Ihr Shael'dryn, ein magisches Relikt wiederherzustellen, das Raene für ihre Untersuchung in Eschental benötigt.",["faction:Alliance"]="Als Mitglied der Allianz ist die Sicherung des Eschentals für Eure Stellung im nördlichen Kalimdor wichtig und hilft, Astranaar vor örtlicher Verderbnis und feindlichen Mächten zu schützen.",["race:NightElf"]="Als Nachtelf helft Ihr durch die Wiederherstellung des Stabs Raene dabei, die Furbolgangriffe zu untersuchen, die Astranaar und die umliegenden Haine bedrohen."},sec={{t="Ein wiederhergestelltes Relikt",b="Ihr habt den Stab der Verwandlung am versteckten Schrein in Eschental wiederhergestellt. Sein Schaft, sein Knauf und der Leuchtende Edelstein sind vereint, und seine Magie ist erneuert. Shael'dryn benötigt den Stab für Raenes Untersuchung der Furbolgangriffe."},{t="Rückkehr zu Shael'dryn",b="Shael'dryn wartet neben dem Mondbrunnen des Waldes, wo sie die Wiederherstellung des Stabs angeleitet hat. Ihr bringt ihr das fertige Relikt und bestätigt, dass seine Magie zurückgekehrt ist. Dann können die Sentinel-Verteidiger die nächsten Schritte unternehmen, um ihre belagerte Heimat zu schützen."}},faq={{q="Was ist das Ziel dieses Abschnitts der Quest?",a="Ihr habt den Stab der Verwandlung am versteckten Schrein zusammengesetzt. Bringt ihn zu Shael'dryn zurück, die am Mondbrunnen im nördlichen Eschental wartet.",al={"was tun raenes säuberung 7","was ist diese quest","questziel"}},{q="Wer ist Shael'dryn?",a="Shael'dryn ist eine Dryade, die einen heiligen Mondbrunnen in Eschental hütet. Sie arbeitet daran, den uralten Wald von der sich ausbreitenden Verderbnis zu reinigen, und weist vertraute Verbündete an, Relikte zu sammeln, Bestandteile zu reinigen und heilige Artefakte wiederherzustellen.",al={"shaeldryn","wer ist shael'dryn","priesterin am mondbrunnen"}},{q="Wo befindet sich Shael'dryn?",a="Shael'dryn wartet an einem stillen Mondbrunnen im nördlichen Eschental, östlich der Hauptstraße zwischen Astranaar und dem Teufelswald. Die ruhigen Wasser stehen unter ihrer Obhut.",al={"shael'dryn standort","wo ist shaeldryn","wo ist der mondbrunnen"}},{q="Was ist der Stab der Verwandlung?",a="Der Stab der Verwandlung ist Dartols magische Schöpfung. Seine wiederhergestellte Macht soll Raene helfen, die Furbolgs zu untersuchen; welche Gestalt er verleiht, wird erst später entdeckt.",al={"was ist der stab der verwandlung","geschichte des stabs der verwandlung","der stab"}},{q="Warum ist es für Astranaar so wichtig, den Stab zusammenzusetzen?",a="Raene Wolfsläufer hofft, dass der Stab es einem Ermittler ermöglicht, sich den Furbolgs zu nähern und mehr über die Angriffe zu erfahren, die Astranaar bedrohen.",al={"warum raenes säuberung","warum es astranaar kümmert","raenes bedeutung"}},{q="Endet die Säuberungsquestreihe mit dem Zusammensetzen des Stabs?",a="Nein. Shael'dryn bittet Euch als Nächstes, zu Raene Wolfsläufer in Astranaar zurückzukehren und ihr mitzuteilen, dass der Stab fertig ist.",al={"ist dies die letzte quest","endet raenes säuberung hier","ende der questreihe"}}},fp="17,147,16.232.0,20.242.0,47.140.0,18.221.0,28.149.0,34.163.0,52.133.0,48.105.0"}
P.entries["quest:1057"] = {n="Die Rückeroberung des Verbrannten Tals",s="Bewahrer Albagorm entsendet Kämpfer der Allianz vom Steinkrallengipfel, um die Bloodfury-Harpyien aus dem verwüsteten Verbrannten Tal zu vertreiben. Ihre Vertreibung wird den Weg für Druiden und Pfleger freimachen, damit sie das versengte Land heilen können.",h="Bewahrer Albagorm entsendet Kämpfer der Allianz vom Steinkrallengipfel, um die Bloodfury-Harpyien aus dem...",kw={"bloodfury","das verbrannte tal","harpyien","bewahrer albagorm","die rückeroberung des verbrannten tals","steinkrallengebirge","der steinkrallengipfel"},ang={["class:Druid"]="Als Druide dient Ihr dem Zirkel des Cenarius und verteidigt die Harmonie der Natur. Ihr helft den Bewahrern, verheerte Nester zu beseitigen, damit die magische Wiederaufforstung beginnen kann.",["faction:Alliance"]="Als Held der Allianz helft Ihr, die hohen Pässe und die südlichen Täler zu sichern. Ihr schützt gefährdete Nachtelfensiedlungen und Heiligtümer auf dem gesamten Steinkrallengipfel vor räuberischen Bedrohungen.",["race:NightElf"]="Als Nachtelf verehrt Ihr die wilden Wälder des Steinkrallengebirges. Niederträchtige Harpyien aus heiligen Hainen zu vertreiben, die von fremden Maschinen entweiht wurden, ist eine dringliche Aufgabe."},sec={{t="Das verwundete Tal",b="Südlich des Steinkrallengipfels liegt das Verbrannte Tal in Asche und schwelenden Trümmern. Einst lag dort eine üppige alpine Zuflucht. Eine mechanisierte Holzfäller- und Bergbauarmee rodete die Bäume und ließ Brände ungehindert wüten. Für die Wächter des Steinkrallengebirges ist der Verlust des Waldes durch industrielle Gier eine Wunde, die sie nicht ignorieren können."},{t="Die Harpyienbedrohung",b="Bloodfury-Harpyien nahmen die Asche in Besitz, die die mechanischen Brände hinterließen. Sie durchschwärmen die rauchenden Niederungen, nisten dort und überfallen jeden, der sich nähert. Bewahrer Albagorm und seine Verbündeten können das Land nicht betreten, um die Saat der Erneuerung auszubringen. Die Harpyien versperren allen Außenstehenden den Weg."},{t="Den Weg zur Erneuerung freimachen",b="Die Nistplätze der Bloodfury müssen zerstört werden, bevor die Wiederherstellung beginnen kann. Bewahrer Albagorm entsendet erfahrene Kämpfer der Allianz tief in die Reihen des Stammes, um dessen Jäger, Hinterhaltjäger und Schurkenfedern zu töten. Ihre Zahl muss sinken, bevor das Land für die Natur zurückgewonnen werden kann und die Waldgeister wieder frei atmen können."}},faq={{q="Was ist das Verbrannte Tal?",a="Das Verbrannte Tal liegt in den südwestlichen Höhen des Steinkrallengebirges. Feuer verzehrte seinen einst üppigen Wald und versengte es bis auf den nackten Fels. Industrielle Holzfällertruppen beuteten das Land ohne jede Zurückhaltung aus.",al={"geschichte des verbrannten tals","was geschah mit dem verbrannten tal","warum ist es verbrannt"}},{q="Wer ist Bewahrer Albagorm?",a="Bewahrer Albagorm ist ein Waldhüter und Pfleger in der Allianz-Siedlung auf dem Steinkrallengipfel. Er schützt die Natur und die Waldgeister, wirkt der Verwüstung im Gebirge entgegen und drängt vordringende Bestien zurück.",al={"bewahrer albagorm","wer vergibt die rückeroberung des verbrannten tals","albagorm geschichte"}},{q="Warum leben Harpyien im Verbrannten Tal?",a="Bloodfury-Harpyien gedeihen in zerrütteten, verheerten Landstrichen. Nachdem Feuer das Tal verwüstet hatte, zog der opportunistische Schwarm in den Talkessel und greift jeden an, der ihn zu betreten versucht.",al={"bloodfury-harpyien","warum sind hier harpyien","bloodfury im steinkrallengebirge"}},{q="Wer hat das Verbrannte Tal ursprünglich in Brand gesetzt?",a="Bewahrer Albagorm nennt eine gierige, mechanisierte Armee von Industriellen als Ursache. Ihre unkontrolliert eingesetzten Holzfällermaschinen und ihre explosive Expansion lösten verheerende Brände aus, die den Wald verzehrten.",al={"wer verbrannte das verbrannte tal","mechanisierte armee von industriellen","venture company verbranntes tal"}},{q="Was muss nach dem Ausdünnen der Harpyien getan werden?",a="Sobald die Zahl der Bloodfury eingedämmt ist, beginnt Bewahrer Albagorm, Samen zu pflanzen und heilende Magie zu kanalisieren, um dem versengten Boden neues Leben zu entlocken.",al={"nächste quest im verbrannten tal","die rückeroberung des verbrannten tals teil zwei","was geschieht als nächstes"}},{q="Ist diese Quest für Abenteurer der Horde verfügbar?",a="Nein. Bewahrer Albagorm wirkt von der Allianz-Bastion auf dem Steinkrallengipfel aus, daher können nur Helden der Allianz die Bloodfury-Harpyien für ihn beseitigen.",al={"kann die horde diese quest machen","horde rückeroberung des verbrannten tals"}}},fx={d7987d6f={q="Warum möchte Bewahrer Albagorm, dass die Blutwut-Harpyien dezimiert werden?",a="Als Hüter des Hains und Beschützer der Waldgeister versucht Albagorm, die vernarbte, verbrannte Landschaft des verbrannten Tals zu heilen und wieder in das üppige Refugium zu verwandeln, das es einst war. Die aggressiven Blutwut-Harpyien, die die Ruinen überflutet haben, blockieren jedoch jeden Zugang und verhindern aktiv, dass der Zirkel des Cenarius seine heiligen Riten der Erneuerung und des Nachwachsens einleiten kann.",al={"grund für die säuberung des verbrannten tals","beweggrund von bewahrer albagorm","warum die harpyien im verbrannten tal töten"}}},fp="27,203,18.304.0,16.260.0,28.303.0,25.205.0,23.215.0,43.169.0,52.191.0,45.148.1,45.138.0"}
P.entries["quest:1058"] = {n="Jin'Zils Waldmagie",s="In Malaka'jin hält Hexendoktor Jin'Zil drei Nachtelfenspäher in groben Eisenkäfigen gefangen. Er schickt Reisende der Horde nach Norden, um Reagenzien für eine finstere Waldmagie zu sammeln.",h="In Malaka'jin hält Hexendoktor Jin'Zil drei Nachtelfenspäher in groben Eisenkäfigen gefangen.",kw={"rennerauge","fey dragon","waldmagie","jin'zil","malaka'jin","gefangene","steinkrallengebirge","twilight runner","hexendoktor"},ang={["class:Druid"]="Als Druide seht Ihr, wie majestätische fey drakes, Waldläufer und uralter Waldsaft für tödliches Gift ausgebeutet werden, eine finstere Verkehrung des Gleichgewichts der Natur.",["faction:Horde"]="Als Mitglied der Horde wisst Ihr, dass die Sicherung Malaka'jins bedeutet, den Widerstand der Nachtelfen im gesamten Gebirge zu brechen, selbst durch die unorthodoxen Methoden eines zurückgezogen lebenden Hexendoktors.",["race:NightElf"]="Als Nachtelf betrachtet Ihr die Hinrichtung von Gefangenen mit zweckentfremdeten Stoffen des Waldes als eine der grausameren Taten der Horde im Steinkrallengebirge.",["race:Troll"]="Als Troll kennt Ihr Jin'Zils finsteren Humor und seine praktische Voodooalchemie als Markenzeichen der Hexendoktorenkunst der Dunkelspeer."},sec={{t="Ein bitteres Gebräu",b="Hexendoktor Jin'Zil übt sein Handwerk in Malaka'jins roter Felsschlucht unter den wachsamen Blicken der Horde aus. Als ihm drei gefangene Nachtelfen in die Hände fallen, wählt er für seine Waldfeinde ein spöttisches Ritual statt gewöhnlichen Abschlachtens. Er schickt Euch nach Norden in die Gipfel, um dickflüssigen Baumsaft, Schnurrhaare von räuberischen Twilight Runnern, eine schimmernde Siechdrachenschuppe und Dutzende Augen heimischer Waldläufer zu sammeln."},{t="Ein Hauch von Heimat",b="Jin'Zil verbirgt grausamen Trollhumor hinter einem verspielten Auftreten. Er sagt, sein Gebräu werde den gefangenen Elfen helfen, sich heimisch zu fühlen, obwohl sie keinen Wald zum Herumtollen haben.\n\nMagische Fauna und konzentrierter Saft ergeben ein flüchtiges, tödliches Gift. Als Jin'Zil es in der Höhle freisetzt, erstickt das Gebräu das Leben der Gefangenen in ihren Käfigen. Ihre Körper sterben, und ihre Ahnengeister lösen sich in leuchtende Irrwische auf, die in die Berge schweben und leere Käfige zurücklassen."}},faq={{q="Wer ist Hexendoktor Jin'Zil?",a="Hexendoktor Jin'Zil ist ein Dunkelspeertroll in Malaka'jin im südlichen Steinkrallengebirge. Er unterstützt die Kriegsanstrengungen der Horde gegen die Nachtelfen mit Trollalchemie, Voodoo und Verhören.",al={"wer ist jin'zil","hexendoktor jin'zil","jinzil geschichte"}},{q="Warum will Jin'Zil so viele Waldläuferaugen?",a="Jin'Zil sagt, mächtige Waldmagie brauche reichlich Augen. Trollhexendoktoren verwenden seltsame organische Zutaten für ihre Tränke, und die absurde Menge passt zu Jin'Zils verschrobener, rachsüchtiger Natur.",al={"warum waldläuferaugen","dreißig waldläuferaugen","warum so viele augen"}},{q="Was geschieht mit den eingesperrten Nachtelfen, wenn die Quest endet?",a="Nachdem Ihr die Reagenzien gebracht habt, setzt Jin'Zil giftiges Gebräu in seiner Höhle frei. Es vergiftet die drei Gefangenen und tötet sie, und ihre Geister schweben als Irrwische davon.",al={"was geschieht mit den elfen","schicksal der eingesperrten elfen","jin'zils gefangene"}},{q="Wo sind all diese Reagenzien zu finden?",a="Waldläuferaugen und Steinkrallensaft lassen sich rund um den Mirkfallonsee und im nördlichen Hochland des Steinkrallengebirges sammeln. Schnurrhaare von Twilight Runnern und die seltene Siechdrachenschuppe stammen aus dem Gebiet weiter nördlich nahe dem Steinkrallengipfel, wo magische Tiere umherstreifen.",al={"wo reagenzien für waldmagie finden","steinkrallensaft fundort","siechdrachenschuppe fundort"}},{q="Warum bekämpft die Horde Nachtelfen im Steinkrallengebirge?",a="Der Holzeinschlag der Horde im benachbarten Eschental ist auf erbitterten Widerstand der Sentinels gestoßen. Die Nachtelfen halten noch immer den Steinkrallengipfel und seine heiligen Haine oberhalb von Außenposten der Horde wie Malaka'jin.",al={"warum nachtelfen im steinkrallengebirge bekämpfen","konflikt horde nachtelfen steinkrallengebirge","krieg im steinkrallengebirge"}},{q="Warum werden die sterbenden Elfen zu Irrwischen?",a="Irrwische sind die Geister verstorbener Nachtelfen, die eng mit der Natur verbunden sind. Wenn Nachtelfen sterben, nehmen ihre Seelen eine leuchtende, baumartige Gestalt an, statt als gewöhnliche Geister oder Schemen zu verweilen.",al={"warum werden elfen zu irrwischen","elfenirrwische in der höhle","geschichte der irrwische"}}},fx={["58b555cd"]={q="Warum will Hexendoktor Jin'Zil, dass dies getan wird?",a="Hexendoktor Jin'Zil hat drei Schildwachen der Nachtelfen gefangen genommen und sie in Käfige innerhalb seiner Höhle in Malaka'jin gesperrt. Anstatt sie einfach hinzurichten, möchte er einen boshaften Trank brauen, den er spöttisch „Waldmagie“ nennt. Durch die Kombination roher, starker Essenzen aus ihrer geliebten Wildnis beabsichtigt er, ein tödliches Gift zu erschaffen, das die eigenen natürlichen Gaben des Waldes gegen seine Gefangenen richtet.",al={"warum jinzils waldmagie","grund für die waldmagie","beweggrund von jinzil"}},["840e6ff0"]={q="Wofür ist der Steinkrallensaft gut?",a="Das aus dem lebenden Holz und den Saftbestien der Region gewonnene, dicke Harz dient als zähe, klebrige Basis für Jin'Zils Gebräu. Es fängt die anderen Waldreagenzien ein, vermischt sie und verankert seinen toxischen Trank in der rohen Essenz der Berge.",al={"nutzen von steinkrallensaft","warum saft sammeln","wofür ist der saft"}},["70cbdf3f"]={q="Wofür ist die Siechdrachenschuppe gut?",a="Siechdrachen sind mystische Kreaturen, die tief mit der smaragdgrünen Kraft des Steinkrallengipfels und der Kaldorei verwoben sind. Jin'Zil benötigt eine Schuppe, um sein Gebräu mit ihrer angeborenen magischen Abwehr und wilden Energien zu durchtränken und es so in ein tödliches Mittel zu verwandeln, das speziell darauf abgestimmt ist, Nachtelfen zu schaden.",al={"nutzen von siechdrachenschuppe","warum siechdrachenschuppe benötigt","wofür ist die siechdrachenschuppe"}},a0fa7c69={q="Wofür ist das Schnurrhaar eines Mondlichtläufers gut?",a="Diese Schnurrhaare, die von den durch die Wälder streifenden Dämmerungsläufern stammen, bringen den wilden, räuberischen Instinkt der heimischen Raubtiere des Steinkrallengebirge in die Mischung ein und schärfen das Gebräu zu einem aggressiven Gift.",al={"nutzen von schnurrhaar eines mondlichtläufers","warum schnurrhaare","wofür sind die schnurrhaare"}}},fp="22,162,13.410.0,15.452.1,28.193.0,43.198.0,62.159.1,35.219.0,52.192.0,39.182.0"}
P.entries["quest:1059"] = {n="Die Rückeroberung des Verbrannten Tals",s="Weit im Süden sucht Bewahrer Albagorm Hilfe, um das Verbrannte Tal wiederherzustellen. Die Bloodfury-Harpyien wurden vorerst zurückgedrängt, doch Gewalt allein kann das verwundete Land nicht heilen.",h="Weit im Süden sucht Bewahrer Albagorm Hilfe, um das Verbrannte Tal wiederherzustellen.",kw={"bloodfuries","das verbrannte tal","falfindel wegeshut","feralas","thalanaar","bewahrer albagorm","der steinkrallengipfel","tausend nadeln"},ang={["class:Druid"]="Als Druide teilt Ihr die Cenarion-Pflicht, über örtliche Garnisonen hinauszublicken und urtümliche Naturgeister anzurufen, um von widernatürlicher Verwüstung gezeichnete Lande zu heilen.",["faction:Alliance"]="Als Mitglied der Allianz verlasst Ihr Euch auf den Stützpunkt am Steinkrallengipfel und die Verbindungen zwischen Grenzaußenposten in den weiten, umkämpften Gebieten Kalimdors."},sec={{t="Die Narben des Tals",b="Asche bedeckt das Verbrannte Tal im südlichen Steinkrallengebirge, wo schreckliche Zerstörung das Land gezeichnet hat. Streitkräfte der Allianz unter Bewahrer Albagorm vertrieben die Bloodfury-Harpyien aus ihren Nestern in den Ruinen, doch die Harpyien könnten zurückkehren. Gewalt kann sie nur zurückhalten. Die verwüstete Erde muss heilen, bevor sie zurückkehren, um das Tal für sich zu beanspruchen."},{t="Eine Bitte nach Süden",b="Die Hainehüter können das versengte Land nicht allein wiederherstellen. Deshalb schickt Bewahrer Albagorm Euch nach Süden, vorbei an den Salzebenen und Schluchten von Tausend Nadeln, nach Thalanaar an der Grenze zu Feralas. Falfindel Wegeshut wartet dort. Der Nachtelfendruide ist für eine seltene Gabe bekannt: Er ruft uralte Waldgeister herbei, die totem Boden neues Leben schenken."}},faq={{q="Wer ist Bewahrer Albagorm?",a="Bewahrer Albagorm hütet den Hain auf dem Steinkrallengipfel. Er leitet die Bemühungen der Allianz, das verseuchte Verbrannte Tal zu reinigen und wiederherzustellen.",al={"wer ist albagorm","bewahrer albagorm"}},{q="Wo befindet sich Falfindel Wegeshut?",a="Falfindel Wegeshut ist in Thalanaar, an der westlichen Grenze, wo Tausend Nadeln auf Feralas trifft.",al={"wo ist falfindel","falfindel wegeshut standort","wegeshut finden"}},{q="Warum nach einem Druiden im fernen Feralas schicken?",a="Bewahrer Albagorm glaubt, dass Falfindel uralte Waldgeister beschwören kann, die mächtig genug sind, die tiefen Wunden im Verbrannten Tal zu heilen.",al={"warum nach feralas reisen","warum falfindel"}},{q="Welche Bedrohung lauert im Verbrannten Tal?",a="Feindselige Bloodfury-Harpyien, Feuerelementare und wilde Tiere leben im Tal und gedeihen seit dem Brand.",al={"verbranntes tal feinde","was greift das tal an"}},{q="Erfordert diese Quest Kämpfe?",a="Es sind keine Kämpfe erforderlich. Ihr tragt Bewahrer Albagorms Botschaft durch das zentrale und südliche Kalimdor.",al={"ist diese quest schwer","kämpfe bei der quest im verbrannten tal"}},{q="Wie erreicht Ihr Tausend Nadeln vom Steinkrallengebirge aus?",a="Reist vom Steinkrallengebirge nach Osten ins Brachland und dann auf der Goldstraße nach Süden. Fahrt mit dem Großen Aufzug nach Tausend Nadeln hinab und reist dann weiter nach Westen in Richtung Feralas.",al={"wie nach tausend nadeln gelangen","reiseroute nach feralas"}}},fx={edca7440={q="Warum möchte Bewahrer Albagorm, dass dies getan wird?",a="Obwohl Ihr viele der Blutwut-Harpyien niedergeschlagen habt, weiß Bewahrer Albagorm, dass sie sich schnell neu formieren und ihre Kontrolle über Das verbrannte Tal zurückgewinnen werden, wenn keine dauerhaften Maßnahmen ergriffen werden. Das Land bleibt ruiniert und verwundbar, und das bloße Dezimieren von Bestien kann die versengte Erde nicht heilen. Er benötigt dringend die mächtigen Waldgeister, die nur ein Druide wie Falfindel Wegeshut beschwören kann, um das Leben im Tal wiederherzustellen, bevor die Harpyien sich sammeln und Euren Fortschritt zunichtemachen.",al={"beweggrund von bewahrer albagorm","warum nach falfindel senden","warum das verbrannte tal zurückerobern"}}},fp="27,176,21.335.0,19.328.0,23.130.0,37.96.0,44.127.0,40.116.0,31.96.0,50.171.0"}
P.entries["quest:106"] = {n="Junge Liebende",s="Maybell Maclure liebt Tommy Joe Steinfeld, obwohl ihre Familien erbitterte Rivalen sind. Sie bittet Euch, ihm ihren Brief zum Fluss zu bringen.",h="Maybell Maclure liebt Tommy Joe Steinfeld, obwohl ihre Familien erbitterte Rivalen sind.",kw={"wald von elwynn","fehde","liebesbrief","weinberge der maclures","maybell maclure","hof der steinfelds","tommy joe steinfeld","junge liebende"},ang={["faction:Alliance"]="Als Mitglied der Allianz auf der Durchreise durch Elwynn könnt Ihr Botschaften zwischen den verfeindeten Steinfelds und Maclures überbringen. Selbst wenn das Königreich in Gefahr ist, geht der kleine Liebeskummer weiter.",["race:Human"]="Als Mensch, der Elwynn kennt, habt Ihr von dem alten Groll zwischen den Steinfelds und den Maclures gehört. Die Romanze zwischen Maybell und Tommy Joe ist unter den Nachbarn ein heikler Skandal."},sec={{t="Eine verbotene Romanze",b="Die Steinfelds und die Maclures hegen seit Jahren einen Groll gegeneinander im Bauernland im Süden von Elwynn. Maybell kann Tommy Joe nicht besuchen, ohne den Zorn ihrer Familie zu wecken. Also vertraut sie Reisenden an, ihre Briefe über die Grenze zwischen den beiden Höfen zu bringen."},{t="Das Treffen am Flussufer",b="Tommy Joe hält sich am ruhigen Flussufer gleich westlich vom Hof der Steinfelds außerhalb der Sichtweite seiner Verwandten auf. Ein Brief von Maybell bringt Erleichterung und neue Sehnsucht. Die Trennung wird für ihn unerträglich, und die beiden beginnen, nach Möglichkeiten für heimliche Treffen zu suchen."}},faq={{q="Wer vergibt die Quest Junge Liebende?",a="Maybell Maclure vergibt sie bei den Weinbergen der Maclures im Wald von Elwynn. Sie liebt Tommy Joe Steinfeld, aber ihre Familien sind erbitterte Rivalen, weshalb sie sich nicht offen treffen können.",al={"wer vergibt junge liebende","wer startet junge liebende","junge liebende questgeber"}},{q="Wo ist Tommy Joe Steinfeld zu finden?",a="Tommy Joe Steinfeld wartet am Flussufer gleich westlich vom Hof der Steinfelds, der genau westlich der Weinberge der Maclures liegt. Dort bleibt er außerhalb der Sichtweite seiner Familie.",al={"wo ist tommy joe steinfeld","tommy joe finden","tommy joe aufenthaltsort"}},{q="Warum werden Maybell und Tommy Joe voneinander ferngehalten?",a="Die Steinfelds und die Maclures hegen seit Jahren einen Groll gegeneinander. Keine der beiden Familien erlaubt ihren Kindern den Umgang miteinander, also schreibt sich das junge Paar heimliche Briefe.",al={"warum streiten die familien","steinfeld maclure fehde","warum dürfen maybell und tommy joe sich nicht sehen"}},{q="Welchen Gegenstand überbringt Ihr während dieser Quest?",a="Ihr bringt Maybells Liebesbrief zu Tommy Joe Steinfeld am Fluss. Darin erzählt sie ihm von ihrer Zuneigung und Hingabe, ob nun eine Fehde herrscht oder nicht.",al={"was ist maybells brief","was wird in junge liebende überbracht","liebesbrief elwynn"}},{q="Wie reagiert Tommy Joe auf den Brief?",a="Tommy Joe ist begeistert und nennt Maybell das Licht seines tristen Lebens. Ihre Worte machen die Trennung für ihn unerträglich, also beginnt er, nach einer Möglichkeit für ein Treffen zu suchen.",al={"wie reagiert tommy joe","tommy joes antwort","was passiert bei der briefübergabe"}},{q="Wo spielt diese Quest?",a="Die Geschichte spielt im Süden des Walds von Elwynn, zwischen den Weinbergen der Maclures und dem Fluss beim Hof der Steinfelds. Ein kleinlicher Familienstreit stört den Frieden in diesem ruhigen Bauernland des Menschenkönigreichs.",al={"wo spielt junge liebende","junge liebende gebiet","hof der steinfelds lage"}}},fp="12,138,19.252.0,24.243.0,33.165.0,40.161.0,41.162.0,43.130.0,39.166.0,33.194.0"}
P.entries["quest:1060"] = {n="Brief an Jin'Zil",s="Darsok Schnelldolch schickt Euch mit Neuigkeiten für seinen alten Freund, Hexendoktor Jin'Zil, ins Steinkrallengebirge. Serena Bloodfeather ist gefallen, und Darsok möchte, dass Jin'Zil von ihrem Tod erfährt.",h="Darsok Schnelldolch schickt Euch mit Neuigkeiten für seinen alten Freund, Hexendoktor Jin'Zil, ins...",kw={"bloodfury","darsok schnelldolch","harpyien","brief an jin'zil","malaka'jin","serena bloodfeather","steinkrallengebirge","hexendoktor jin'zil"},ang={["faction:Horde"]="Als Krieger der Horde tragt Ihr die Bemühungen zur Sicherung der Handelswege innerhalb des Brachlands ins umkämpfte Steinkrallengebirge.",["race:Troll"]="Als Troll findet Ihr Jin'Zils Höhle in Malaka'jin, einem wichtigen spirituellen und taktischen Außenposten der Dunkelspeertrolle, die die Gebirgszugänge sichern."},sec={{t="Eine Nachricht ins Gebirge",b="Nachdem Serena Bloodfeather gefallen ist, schickt Darsok Schnelldolch Euch ins Steinkrallengebirge. Die Bruten der Witchwing und der Bloodfeather kamen von den schroffen Graten nordwestlich des nördlichen Brachlands, nicht aus dem Buschland. Ihr habt Serena besiegt, und Darsok bittet Euch, Hexendoktor Jin'Zil, einem alten Bekannten, die Nachricht von ihrem Tod zu überbringen. Jin'Zil lebt in Malaka'jin, einer Trollsiedlung inmitten der gefährlichen Berggipfel."},{t="Echos der Bloodfury Claws",b="Hexendoktor Jin'Zil erinnert sich an einen früheren Feldzug, als er von Serena Bloodfeathers Fall hört. Der Schattenjäger Rokhan und der wandernde Bestienmeister Rexxar erschlugen Serenas ältere Schwester Bloodfeather. Serenas Tod setzt der langen Fehde zwischen den Grenzaußenposten der Horde und Kalimdors blutrünstigen Harpyien ein endgültiges Ende."}},faq={{q="Wer vergibt die Quest Brief an Jin'Zil?",a="Darsok Schnelldolch gibt Euch die Aufgabe am Wegekreuz im Brachland, nachdem Ihr die Jagd auf Serena Bloodfeather abgeschlossen habt.",al={"questgeber","wo quest erhalten","wer startet brief an jin'zil"}},{q="Wo kann ich Hexendoktor Jin'Zil finden?",a="Hexendoktor Jin'Zil lebt in einer Höhle in Malaka'jin, einem Lager der Dunkelspeertrolle nahe dem Hauptweg vom Brachland ins Steinkrallengebirge.",al={"wo ist jin'zil","jin'zil standort","malaka'jin standort"}},{q="Warum schickt Darsok Euch ins Steinkrallengebirge?",a="Darsok schickt Euch, um seinem alten Freund Jin'Zil zu berichten, dass Serena Bloodfeathers Tod die Bedrohung durch die Harpyien gebrochen hat. Außerdem schickt er einen fähigen Abenteurer zu den größeren Herausforderungen, denen die Horde auf den Gipfeln des Steinkrallengebirges gegenübersteht.",al={"warum ins steinkrallengebirge","warum darsok einen brief schickt"}},{q="Auf welche Schwester Serenas aus früherer Zeit bezieht sich Jin'Zil?",a="Jin'Zil meint Bloodfeather, Serenas ältere Schwester, die Jahre zuvor Kalimdor terrorisierte. Der Schattenjäger Rokhan und der Halb-Oger-Krieger Rexxar erschlugen sie, als sie mit der Horde während ihrer Gründungszeit unterwegs waren.",al={"serenas ältere schwester","rokhan und rexxar harpyie","bloodfury"}},{q="Ist diese Quest Teil einer größeren Questreihe?",a="Ja. Sie folgt auf Harpy Raiders, Harpy Lieutenants und Serena Bloodfeather und schließt die Harpyienjagd im nördlichen Brachland ab. Außerdem weist sie den Weg ins Steinkrallengebirge.",al={"questreihe","voraussetzungen","was führt hierzu"}},{q="Welche Fraktion kann diese Aufgabe übernehmen?",a="Nur die Horde kann diese Arbeit übernehmen. Darsok Schnelldolch und Hexendoktor Jin'Zil dienen beide der Horde an der Grenze.",al={"ist das nur für die horde","kann die allianz diese quest machen"}}},fx={a93c7265={q="Warum muss Darsok, dass Ihr den Brief an Jin'Zil überbringt?",a="Darsok Schnelldolch bleibt am Wegekreuz stationiert und hält Wache über das nördliche Brachland. Nachdem er beobachtet hat, wie Ihr erfolgreich die Hexenflügelharpyien gesäubert und ihre Anführerin Serena Bloodfeather getötet habt, sieht er Euch als einen bewährten, fähigen Boten an, der die gefährliche Reise in das Steinkrallengebirge bewältigen kann. Die Nachricht von Serenas Untergang gibt Euch zudem einen würdigen Vorwand, Länder jenseits der trockenen Ebenen zu erkunden.",al={"warum ihr den brief an jinzil überbringen sollt","warum kann darsok den brief nicht selbst überbringen","warum ich für den brief an jinzil"}}},fp="17,185,28.409.0,29.322.1,38.124.0,38.147.0,49.214.0,55.201.0,37.167.0,37.114.0"}
P.entries["quest:1061"] = {n="Die Geister des Steinkrallengebirges",s="Unter den Geistern des Steinkrallengebirges regt sich Unruhe, und Zor Einbaum schickt Streiter der Horde nach Westen, um den Grund zu erfahren. Von Orgrimmar aus reist Ihr am Wegekreuz vorbei und erstattet Seereth Bruchstein nahe dem Hochwipfeltal Bericht.",h="Unter den Geistern des Steinkrallengebirges regt sich Unruhe, und Zor Einbaum schickt Streiter der Horde nach...",kw={"das wegekreuz","abholzung","hochwipfeltal","seereth bruchstein","steinkrallengebirge","valley of wisdom","venture company","zor einbaum"},ang={["class:Shaman"]="Als Schamane hört Ihr die Elemente darum flehen, dass Ihr das Band zwischen der Erde und den Lebenden wiederherstellt.",["faction:Horde"]="Als Mitglied der Horde helft Ihr, die Reisewege zwischen dem Steinkrallengebirge und dem Brachland von skrupellosen Handelssyndikaten freizuhalten.",["race:Tauren"]="Als Tauren habt Ihr die in Eurer Kultur verwurzelte Pflicht, die Erde zu besänftigen und heilige Wälder vor dem Holzeinschlag der Goblins zu schützen."},sec={{t="Ein Hilferuf aus dem Westen",b="In Grommash Hold lauscht Zor Einbaum der Natur und spürt tiefes Leid aus dem Steinkrallengebirge. Die Elementargeister seiner felsigen Gipfel toben, während die Holzfäller ihre Wälder abholzen. Die Schamanen der Horde vernehmen ihre Unruhe und fürchten, dass die Verwüstung im westlichen Hochland das spirituelle Gleichgewicht Kalimdors stören wird."},{t="Industrielle Abholzung",b="Die Venture Company ist ein skrupelloses Goblinsyndikat, das im Hochwipfeltal Holz schlägt. Ihre Trupps setzen aggressive Maschinen, Sägen und Muskelkraft ein, um den uralten Wald niederzumetzeln, statt ihn nachhaltig zu bewirtschaften. Deshalb entsandte die Horde Seereth Bruchstein, eine junge Schamanin, um vom Grenzgebiet aus über den Wald zu wachen und Verteidiger gegen die Verwüster zu sammeln."}},faq={{q="Wer vergibt diese Quest und wo ist diese Person zu finden?",a="Zor Einbaum, ein Orc-Berater, bietet diese Quest in Grommash Hold in Orgrimmar an.",al={"questgeber","wo quest erhalten","zor einbaum aufenthaltsort"}},{q="Wo finde ich Seereth Bruchstein?",a="Seereth Bruchstein wartet im Steinkrallengebirge am Pfad nahe dem Hochwipfeltal, kurz hinter dem östlichen Zugang vom nördlichen Brachland aus.",al={"seereth aufenthaltsort","wo ist seereth bruchstein","lager im steinkrallengebirge"}},{q="Warum sind die Geister des Steinkrallengebirges zornig?",a="Die Goblins der Venture Company betreiben Kahlschlag in den Bergwäldern und erzürnen damit die elementaren Wächter des Landes.",al={"warum sind die geister zornig","unruhe im steinkrallengebirge","zornige geister"}},{q="Wie erreiche ich das Steinkrallengebirge von Orgrimmar aus?",a="Reist von Orgrimmar aus nach Süden durch das Brachland zum Wegekreuz. Folgt dann der Straße nach Westen durch den felsigen Pass ins Steinkrallengebirge.",al={"weg ins steinkrallengebirge","wie ins steinkrallengebirge gelangen","route ins steinkrallengebirge"}},{q="Was folgt nach dem Gespräch mit Seereth?",a="In ihrem Lager gibt Euch Seereth Bruchstein die Quest Goblin Invaders. Sie schickt Euch ins Hochwipfeltal, um Holzfäller auszuschalten und ihre Arbeit einzudämmen.",al={"nächste quest","folgequest","was folgt auf die geister des steinkrallengebirges"}},{q="Warum greift die Horde gegen die Abholzung im Steinkrallengebirge ein?",a="Die Schamanen der Tauren und Orcs verehren die Elementargeister. Der rücksichtslose Holzeinschlag der Goblins schadet der spirituellen Harmonie des Landes und bedroht die Grenzen des Brachlands.",al={"warum kümmert sich die horde darum","interesse der tauren am steinkrallengebirge"}}},fx={["4d15c2b8"]={q="Warum möchte Zor Einbaum, dass dies getan wird?",a="Als jemand, der auf die natürliche Welt hört, hat Zor Einbaum die verzweifelten Schreie des Landes selbst vernommen. Die ungezügelte Plünderung und Verbrennung durch Goblin-Entforster im Steinkrallengebirge hat die Elementargeister zutiefst aufgewühlt. Um das Land zu heilen und das Gleichgewicht zu wahren, antwortet er auf den dringenden Ruf nach Verstärkung von Seereth Bruchstein und schickt fähige Abenteurer in die Berge, bevor sich die Zerstörung weiter ausbreitet.",al={"warum sendet euch zor","beweggrund von zor einbaum","warum zor einbaum und die geister des steinkrallengebirges"}}},fp="25,197,19.324.0,24.346.0,49.72.0,36.147.0,40.107.0,55.135.0,44.144.0,59.153.0"}
P.entries["quest:1062"] = {n="Goblineindringlinge",s="An der Grenze zwischen Brachland und Steinkrallengebirge greifen Goblineindringlinge die uralten Bergwälder an. Seereth Bruchstein schickt die Horde gegen Holzfäller der Venture Company in der Scherwindklippe.",h="An der Grenze zwischen Brachland und Steinkrallengebirge greifen Goblineindringlinge die uralten Bergwälder...",kw={"goblin","hochwipfeltal","holzfäller","seereth bruchstein","geister","steinkrallengebirge","venture company","die scherwindklippe"},ang={["class:Druid"]="Als Druide seht Ihr die Zerstörung lebendiger Haine und uralter Bäume in der Scherwindklippe als Angriff auf die natürliche Ordnung, die Ihr verteidigt.",["class:Shaman"]="Als Schamane spürt Ihr, wie die örtlichen Elementare und Naturgeister aufschreien, blind vor Zorn inmitten von Rauch und der Zerstörung durch Goblinmaschinen.",["faction:Horde"]="Als Mitglied der Horde helft Ihr, die Grenzlande zwischen dem Brachland und den höher gelegenen Pässen zu sichern. Das hindert feindliche Handelssyndikate daran, sich im Zentrum Kalimdors zu verschanzen.",["race:Tauren"]="Als Tauren habt Ihr dringenden Anlass, Euch der Venture Company entgegenzustellen. Ihre Zerstörung der Wälder des Steinkrallengebirges quält die Erdgeister, die Ihr zusammen mit der Earth Mother verehrt."},sec={{t="Ein Wald in Qual",b="Holzfäller der Venture Company dringen tief ins Steinkrallengebirge vor. Sie roden die Berghänge und verbrennen das Unterholz, sodass verbrannter Boden zurückbleibt. Für die Tauren und ihre Verbündeten reicht der Schaden über die Wälder hinaus. Die an das Steinkrallengebirge gebundenen Urgeister heulen vor Qual.\n\nSeereth Bruchstein wacht an der Gebirgsgrenze. Sie sieht, dass der Angriff der Goblins die Geister vor Qual und Zorn blind gemacht hat."},{t="Die Sprache der Gewalt",b="Die Führungskräfte und Handlanger der Venture Company hören nur auf den Profit. Vernunft wird sie nicht umstimmen. Deshalb schickt Seereth Euch am Hochwipfeltal vorbei in die Scherwindklippe, um fünfzehn Holzfäller zu töten.\n\nDie Horde begegnet der Gier des Unternehmens mit Gewalt. Der Schlag soll die Abholzung aufhalten und den Ältesten der Tauren Zeit verschaffen, die aufgewühlten Geister des Landes zu besänftigen."}},faq={{q="Wer ist Seereth Bruchstein?",a="Seereth Bruchstein ist eine Orcschamanin, die nahe der südlichen Grenze zwischen dem Brachland und dem Steinkrallengebirge stationiert ist. Sie beobachtet das Vordringen feindlicher Fraktionen und arbeitet daran, das spirituelle Gleichgewicht der Region zu schützen.",al={"seereth bruchstein","questgeber","wer vergibt goblineindringlinge"}},{q="Warum holzen die Goblins das Steinkrallengebirge ab?",a="Die Venture Company strebt nach Profit, ohne Rücksicht auf die Schäden, die sie verursacht. Sie beutet die uralten Wälder und mineralreichen Hügel des Steinkrallengebirges zur Verarbeitung und zum Verkauf aus, ungeachtet der zurückbleibenden natürlichen und spirituellen Verwüstung.",al={"warum holzt die venture company ab","beweggründe der venture company im steinkrallengebirge","warum bäume fällen"}},{q="Wo liegt die Scherwindklippe?",a="Die Scherwindklippe liegt im zentralen Steinkrallengebirge. Folgt von der Grenze zum Brachland aus der Bergstraße nach Nordwesten durch das Hochwipfeltal bis zur Klippe. Dort weicht der Wald den Holzfällerlagern der Venture Company und kahl geschlagenen Hügeln.",al={"lage der scherwindklippe","wo sind die holzfäller","wo sind holzfäller der venture company zu finden"}},{q="Wie reagieren die Geister auf die Anwesenheit der Venture Company?",a="Seereth Bruchstein sagt, dass die Geister des Landes vor Zorn und Schmerz durch Abholzung und Brände beinahe dem Wahnsinn verfallen. Ihr Leiden stört das Gleichgewicht der Natur und bedroht das spirituelle Wohlergehen der Region.",al={"geister im steinkrallengebirge zornig","reaktion der geister des steinkrallengebirges"}},{q="Was geschieht nach dem Töten der Holzfäller der Venture Company?",a="Die Holzfäller zu töten ist nur der erste Schlag gegen den Betrieb. Als Nächstes schickt Seereth die Horde gegen die Maschinen des Unternehmens und empfiehlt, Älteste der Tauren aufzusuchen, die helfen können, die verwundeten Geister zu besänftigen.",al={"nach goblineindringlinge","nächste quest nach den holzfällern"}},{q="Warum kümmert sich die Horde um die Abholzung im Steinkrallengebirge?",a="Das Steinkrallengebirge liegt den Tauren wegen seiner Bedeutung für ihre Kultur und ihr spirituelles Leben am Herzen. Die Horde sieht auch die ungezügelte Aggression und den Rohstoffdiebstahl der Venture Company als Bedrohung für ihren Einfluss in der Region und die spirituelle Harmonie.",al={"interesse der horde am steinkrallengebirge","warum bekämpft die horde die venture company"}}},fx={c7723727={q="Warum möchte Seereth Bruchstein, dass die Holzfäller der Venture Company getötet werden?",a="Die Venture Company rodet rücksichtslos große Gebiete des Steinkrallengebirge und verbrennt sie. Ihre leichtfertige Zerstörung hat die lokalen Naturgeister mit qualvollen Schmerzen und Wut in den Wahnsinn getrieben. Seereth möchte, dass die Holzfäller niedergeschlagen werden, um die unerbittliche Plünderung zu stoppen und zu beweisen, dass die Horde die Schändung dieser heiligen Stätten nicht dulden wird.",al={"beweggrund von seereth bruchstein","warum die holzfäller töten","warum kümmert sich seereth um die goblins"}},["4d329e4c"]={q="Wer sind die Holzfäller der Venture Co.?",a="Die Holzfäller der Venture Co. sind angeheuerte Arbeiter und Techniker, die von dem berüchtigten Goblin-Syndikat beschäftigt werden. Allein vom Profit getrieben, sind sie über das Hochwipfeltal hinaus in Die Scherwindklippe vorgedrungen, wo sie uraltes Holz abholzen und schwere Maschinen mit völliger Missachtung für das Land oder den Zorn seiner heimischen Geister bedienen.",al={"wer sind die holzfäller","holzfäller der venture co","arbeiter der venture company"}}},fp="15,183,17.399.0,21.343.0,26.213.0,53.223.0,32.234.0,59.201.0,55.207.1,52.237.0"}
P.entries["quest:1063"] = {n="Die Ältestengreisin",s="Seereth Bruchstein schickt Nachricht aus dem Steinkrallengebirge nach Donnerfels. Abholzung und Bergbau der Goblins haben die Elemente des Gebirges erzürnt, und Seereth sucht spirituellen Rat bei Magatha Grimmtotem auf der Anhöhe der Ältesten.",h="Seereth Bruchstein schickt Nachricht aus dem Steinkrallengebirge nach Donnerfels.",kw={"ältestengreisin","die anhöhe der ältesten","grimmtotem","magatha","seereth bruchstein","geister","steinkrallengebirge","tauren","donnerfels"},ang={["class:Shaman"]="Als Schamane wisst Ihr, wie schwer die Unruhe der Elemente im Steinkrallengebirge wiegt. Dass Ihr Magathas Rat auf der Anhöhe der Ältesten sucht, spiegelt die spirituelle Krise in Kalimdors Gipfeln wider.",["faction:Horde"]="Ihr erlebt die Bande der Horde in Aktion, als die Sorgen aus dem Grenzland des Steinkrallengebirges die hohen Hallen der Führung in Donnerfels erreichen.",["race:Tauren"]="Als Tauren seht Ihr das zerbrechliche Gleichgewicht zwischen Cairnes vereinten Stämmen und den distanzierten, streng traditionsgebundenen Grimmtotem, die in Donnerfels leben."},sec={{t="Hilferuf aus dem Steinkrallengebirge",b="Im Steinkrallengebirge haben Abholzung und Bergbau der Goblins die Elementargeister erzürnt. Seereth Bruchstein erkennt, dass Gewalt allein die Qual des Landes nicht lindern kann. Daher sucht Seereth den weisen Rat älterer Schamanen. Nur wenige Stammesführer sind Seereth namentlich bekannt, doch Magatha Grimmtotem ist für ihre Weisheit und ihre gebieterische Ausstrahlung bekannt."},{t="Audienz auf der Anhöhe der Ältesten",b="Magatha Grimmtotem hält Hof auf der Anhöhe der Ältesten in Donnerfels, wo schamanische und spirituelle Angelegenheiten zusammenlaufen. Das Verhältnis ihres Stammes zur Führung unter Cairne Bluthuf ist angespannt und oft von Konfrontationen geprägt. Dennoch ist Magatha eine beeindruckende Älteste, deren Rat in der gesamten Horde großes Gewicht hat. Ihr tragt ihr die Sorgen des Steinkrallengebirges vor und sucht ihren Rat."},{t="Ein pragmatisches Bündnis",b="Magatha Grimmtotem schickt den Alchemisten der Verlassenen, die in der Stadt leben, Nachricht von den aufgewühlten Elementen. Sie verlässt sich nicht allein auf traditionelle Taurenriten. Stattdessen zieht sie die neuesten und zynischsten Verbündeten der Horde in Kalimdors spirituelle Angelegenheiten hinein. Ihre Antwort zeigt einen gerissenen und unkonventionellen Umgang mit Macht und Problemen."}},faq={{q="Wer schickt mich zu Magatha?",a="Seereth Bruchstein schickt Euch aus dem Steinkrallengebirge los, nachdem Ihr gegen die Goblins der Venture Company gekämpft habt, die die Bergwälder abholzen.",al={"questgeber","wer startet die quest","seereth bruchstein"}},{q="Wo befindet sich Magatha Grimmtotem?",a="Magatha Grimmtotem lebt oben auf der Anhöhe der Ältesten in Donnerfels. Die nordöstliche Anhöhe ist durch Holzbrücken mit dem zentralen Tafelberg verbunden.",al={"magatha standort","wo ist magatha","die anhöhe der ältesten"}},{q="Warum bittet Seereth eine Taurenälteste um Hilfe?",a="Die Industrie der Goblins hat die Geister des Steinkrallengebirges aufgewühlt. Seereth erkennt, dass Gewalt allein das Land nicht heilen kann, und sucht daher spirituellen Rat, um die Elemente zu besänftigen.",al={"warum ältestengreisin","warum magatha um rat fragen"}},{q="Wer ist Magatha Grimmtotem?",a="Magatha Grimmtotem ist die Ältestengreisin und Matriarchin des Stammes der Grimmtotem. Ihr äußerst aggressiver Stamm steht der vereinten Horde skeptisch gegenüber, während Magatha hoch oben in Donnerfels großen politischen und spirituellen Einfluss besitzt.",al={"ältestengreisin hintergrundgeschichte","wer ist die ältestengreisin","magatha hintergrund"}},{q="Was geschieht nach dem Gespräch mit Magatha?",a="Nachdem Magatha Euren Bericht über das Steinkrallengebirge gehört hat, schickt sie Euch zu Apothekerin Zamah, einer Abgesandten der Verlassenen in den Teichen der Visionen unterhalb der Anhöhe der Geister, um Hilfe zu erhalten.",al={"was kommt danach","folgequest"}},{q="Warum heißt diese Quest „Die Ältestengreisin“?",a="Der Titel bezieht sich auf Magatha Grimmtotem. Ihr Klan und das Volk der Tauren kennen sie wegen ihres hohen Alters, ihres schamanischen Wissens und ihrer Autorität als Matriarchin als die Ältestengreisin.",al={"warum greisin","ältestengreisin titel"}}},fx={["9e600b44"]={q="Warum schickt Seereth Bruchstein einen Abenteurer nach Donnerfels, anstatt selbst zu gehen?",a="Seereth Bruchstein bleibt im Steinkrallengebirge stationiert, um die unmittelbare Verteidigung und spirituelle Wiederherstellung des Landes gegen die Abholzung durch die Venture Company zu überwachen. Als Orc-Schamanin, die an die Front gebunden ist, kann sie ihren Posten nicht verlassen, um die lange Reise durch das Brachland nach Donnerfels anzutreten. Sie verlässt sich auf reisende Champions der Horde, die die Nachricht von der Gefahr im Steinkrallengebirge in ihrem Namen direkt zu den Ältesten der Tauren tragen.",al={"warum werdet ihr gesandt","warum kann seereth nicht selbst gehen","warum benötigt seereth den spieler"}}},fp="15,208,19.331.0,22.348.0,20.331.1,29.136.0,35.129.0,47.153.0,25.218.0,41.153.1,43.170.0"}
P.entries["quest:1064"] = {n="Die Hilfe der Verlassenen",s="In Donnerfels sucht Magatha Grimmtotem die Hilfe der Verlassenen für die verheerten Geister des Steinkrallengebirges. Sie wendet sich an Apothekerin Zamah in den Teichen der Visionen und hofft, dass das Wissen der Tauren und Untoten dem leidenden Land helfen kann.",h="In Donnerfels sucht Magatha Grimmtotem die Hilfe der Verlassenen für die verheerten Geister des...",kw={"apothecary zamah","die hilfe der verlassenen","magatha grimmtotem","die teiche der visionen","schlangenbote","die anhöhe der geister","steinkrallengebirge","donnerfels"},ang={["faction:Horde"]="Als Mitglied der Horde gehört Ihr einem Bündnis an, das seit dem Dritten Krieg Gestalt angenommen hat und Kalimdor mit Lordaeron verbindet.",["race:Tauren"]="Als Tauren vertraut Ihr vielleicht auf den Druidentum und die Earth Mother, um das Land zu heilen. Dass Magatha sich untoten Alchemisten zuwendet, zeigt ihren unkonventionellen Ansatz in der Stammesdiplomatie.",["race:Undead"]="Als Verlassene könnt Ihr den Tauren alchemistische Hilfe anbieten und Euren Wert beweisen. Es ist eine Gelegenheit, innerhalb einer misstrauischen Horde Vertrauen zu gewinnen."},sec={{t="Ein pragmatisches Bündnis",b="Magatha Grimmtotem sieht praktischen Nutzen im Bündnis mit den Verlassenen. Donnerfels erreichen Berichte über verdorbene Elementargeister und leidendes Land im Steinkrallengebirge, weshalb sie die Untoten um Hilfe bittet. Sie glaubt, dass jene, die Krankheiten verstehen, auch bei ihrer Heilung helfen können. Statt traditionelle druidische Heilmittel zu suchen, schickt sie Euch zur Royal Apothecary Society."},{t="Unter der Anhöhe der Geister",b="Apothekerin Zamah vertritt von den Teichen der Visionen unter der Anhöhe der Geister aus die Interessen von Unterstadt auf Kalimdor. Schamanen, Priester und Seher der Tauren nutzen die Höhle als heiligen Rückzugsort. Zamahs Anwesenheit bringt die Arbeit der Verlassenen in ihre Mitte. Magatha schickt Euch einen Schlangenboten voraus, um Zamah zu benachrichtigen, und stellt so eine direkte Verbindung zu den alchemistischen Forschern der Verlassenen her."}},faq={{q="Warum berät sich Magatha Grimmtotem mit den Verlassenen über das Steinkrallengebirge?",a="Magatha glaubt, dass das Wissen der Verlassenen über Seuchen und Krankheiten helfen kann, die Krankheit im Steinkrallengebirge zu erkennen und zu behandeln.",al={"warum die hilfe der verlassenen","magatha und die untoten","warum die verlassenen fragen"}},{q="Wo ist Apothekerin Zamah zu finden?",a="Apothekerin Zamah lebt in den Teichen der Visionen, einer unterirdischen Höhle unter der Anhöhe der Geister auf dem nordwestlichen Felsplateau von Donnerfels. Ein Höhlengang nahe dem Teich auf dem darüberliegenden Plateau führt hinein.",al={"apothecary zamah standort","wo ist zamah","teiche der visionen eingang"}},{q="Was geschieht, wenn Ihr Magathas Quest annehmt?",a="Wenn Ihr Magathas Bitte annehmt, beschwört sie einen Schlangenboten. Er schlängelt sich und fliegt durch Donnerfels zu Apothekerin Zamah, um Eure Ankunft anzukündigen.",al={"schlangenbote","magathas schlange"}},{q="Wie stehen die Verlassenen dazu, den Tauren im Steinkrallengebirge zu helfen?",a="Apothekerin Zamah bekundet Mitgefühl für die leidenden Geister des Steinkrallengebirges. Sie sagt, die Verlassenen seien begierig darauf, zu helfen und ihre Bindung zur Horde zu stärken.",al={"motive der verlassenen im steinkrallengebirge","warum zamah hilft"}},{q="Welche Questreihe folgt nach dem Gespräch mit Zamah?",a="Nach Eurer Begegnung mit Zamah wendet sich die Untersuchung der Alchemie der Verlassenen zu und führt schließlich zu Journey to Tarrens Mühle in den Östlichen Königreichen. Dort beratet Ihr Euch mit höherrangigen Apothekern.",al={"what comes next","nächste quest nach die hilfe der verlassenen"}},{q="Warum sind die Verlassenen in den heiligen Teichen der Visionen stationiert?",a="Die Teiche der Visionen beherbergen Gelehrte, Magier und Seher der Horde. Apothekerin Zamah arbeitet dort als offizielle Gesandte und Forscherin und hält ihre umstrittenen Experimente von den Hauptverkehrswegen fern.",al={"warum sind untote in den teichen der visionen","anhöhe der geister untote"}}},fx={["5f2f83c5"]={q="Warum schickt Magatha Euch, anstatt Apothekerin Zamah selbst zu konsultieren?",a="Als Älteste der Grimmtotem und eine prominente Anführerin auf Die Anhöhe der Ältesten verlässt sich Magatha Grimmtotem auf unabhängige Abenteurer, um sensible Angelegenheiten in Donnerfels zu erledigen. Einen fähigen Boten auszusenden, testet nicht nur Eure Zuverlässigkeit in Stammesangelegenheiten, sondern stellt auch den direkten Kontakt zwischen einem aktiven Horde-Agenten und Apothekerin Zamah unterhalb von Die Anhöhe der Geister her.",al={"warum ich für forsaken aid","warum sendet magatha einen abenteurer zu zamah","warum benötigt magatha mich"}}},fp="12,212,23.361.0,23.359.0,66.134.0,36.187.0,52.160.0,64.152.0,50.185.0,65.199.0"}
P.entries["quest:1065"] = {n="Reise nach Tarrens Mühle",s="Apothekerin Zamah sucht einen Weg, die Venture Company ohne offenen Krieg aus dem Steinkrallengebirge zu vertreiben. Sie schickt Euch über das Meer zu Apotheker Lydon in Tarrens Mühle, wo die Königliche Apothekervereinigung in Lordaeron arbeitet.",h="Apothekerin Zamah sucht einen Weg, die Venture Company ohne offenen Krieg aus dem Steinkrallengebirge zu...",kw={"apotheker lydon","apothecary zamah","hillsbrad","reise nach tarrens mühle","steinkrallengebirge","tarrens mühle","donnerfels","unterstadt","venture company"},ang={["faction:Horde"]="Als Mitglied der Horde reist Ihr zwischen Donnerfels und Tarrens Mühle und bringt junge Verteidiger mit Verbündeten jenseits des Meeres zusammen.",["race:Tauren"]="Als Tauren trifft Euch die Schändung des Steinkrallengebirges tief. Die Alchemie der Verlassenen anzunehmen bedeutet, bedenkliche Kompromisse einzugehen, um Euer heiliges Land zu schützen.",["race:Undead"]="Als Untoter erlebt Ihr, wie die Königliche Apothekervereinigung ihr chemisches Wissen über das Meer trägt, um fernen Verbündeten der Horde zu helfen."},sec={{t="Ein Hilferuf über das große Meer",b="In Donnerfels verbindet Apothekerin Zamah die Verlassenen mit den Kindern der Erdenmutter. Die Venture Company fällt Bäume und betreibt Bergbau auf dem heiligen Land des Steinkrallengebirges, und gewöhnliche Mittel konnten sie nicht aufhalten. Deshalb wendet sich Zamah an ihre Kollegen in der Königlichen Apothekervereinigung, um ein chemisches Abschreckungsmittel zu erhalten. Sie hofft, dass ihre Alchemie die Gesellschaft ohne langwierigen Krieg vertreiben kann."},{t="Der Weg nach Hillsbrad",b="Ihr überquert das Meer von Kalimdor aus mit dem Zeppelin in Richtung Lordaeron und Unterstadt. Von Tirisfal führt die Straße nach Süden durch den Silberwald und in das umkämpfte Vorgebirge des Hügellands. Tarrens Mühle liegt nahe menschlicher Gehöfte und Ruinen. Einst ein menschlicher Weiler, ist der Ort heute eine Festung der Verlassenen, in der die Königliche Apothekervereinigung ihre Forschungen betreibt."},{t="Apotheker Lydons Handwerk",b="Apotheker Lydon arbeitet in Tarrens Mühle mit instabilen chemischen Stoffen und biologischen Wirkstoffen. Gelegentlich testet Lydon Mixturen an lebenden Versuchsobjekten. Zamahs Notiz beschreibt die Schwierigkeiten mit der Venture Company, und Lydon nimmt sich der Sache eifrig an. Die Vereinigung begrüßt die Gelegenheit, ihre Verbindungen an einem neuen Ort zu testen, also beginnt Lydon, Reagenzien für die Goblins vorzubereiten."}},faq={{q="Warum schickt mich Apothekerin Zamah den ganzen Weg nach Tarrens Mühle?",a="Apothekerin Zamah braucht ein Gebräu, um die Venture Company ohne offenen Krieg aus dem Steinkrallengebirge zu vertreiben. Ihr Kollege Apotheker Lydon arbeitet bei der Königlichen Apothekervereinigung in Tarrens Mühle und kann die alchemistischen Verbindungen herstellen, die sie braucht.",al={"warum nach tarrens mühle reisen","warum zu lydon geschickt","reise nach tarrens mühle zweck"}},{q="Wo liegt Tarrens Mühle?",a="Tarrens Mühle liegt im nördlichen Vorgebirge des Hügellands auf Lordaeron. Nehmt von Kalimdor aus einen Zeppelin von Durotar nach Unterstadt in Tirisfal, reist dann nach Süden durch den Silberwald und nach Osten nach Hillsbrad.",al={"wo liegt tarrens mühle","tarrens mühle lage","wie nach tarrens mühle gelangen"}},{q="Wer sind Apothekerin Zamah und Apotheker Lydon?",a="Apothekerin Zamah und Apotheker Lydon gehören der Königlichen Apothekervereinigung der Verlassenen an. Zamah arbeitet in den Teichen der Visionen in Donnerfels, erforscht einheimische Pflanzen und hilft den Tauren, während Lydon in Tarrens Mühle Alchemie- und Seuchenexperimente durchführt.",al={"wer ist zamah","wer ist lydon","wer sind die apotheker"}},{q="Warum helfen die Verlassenen gegen die Venture Company im Steinkrallengebirge?",a="Die Verlassenen schlossen sich der Horde an, um zu überleben und weil es ihnen nützte, und die Tauren setzten sich für ihren Platz in der Fraktion ein. Den Tauren gegen die Venture Company zu helfen, stärkt ihr Bündnis und gibt den Alchemisten der Verlassenen einen Ort, um ihre Arbeit zu erproben.",al={"warum interessiert die verlassenen das steinkrallengebirge","untote helfen tauren im steinkrallengebirge"}},{q="Was ist die Königliche Apothekervereinigung?",a="Die Königliche Apothekervereinigung ist ein Orden von Alchemisten und Wissenschaftlern der Verlassenen mit Sitz in Unterstadt unter den Ruinen von Lordaeron. Unter der Leitung von Fürstin Sylvanas Windläufer entwickeln sie Elixiere, Gifte und Seuchenstämme, um die Verlassenen zu verteidigen und ihre Feinde zu vernichten.",al={"was ist die königliche apothekervereinigung","apotheker der verlassenen hintergrundgeschichte"}},{q="Was geschieht, nachdem die Notiz bei Lydon abgegeben wurde?",a="Nachdem Apotheker Lydon Zamahs Bitte erhalten hat, beginnt er, eine Lösung vorzubereiten. Für eine geeignete Mixtur müsst Ihr Phiolen mit unschuldigem Blut von den Schattenmagiern des Syndikats bei Burg Durnholde sammeln.",al={"nächste quest nach reise nach tarrens mühle","was braucht lydon"}}},fx={f7a71381={q="Warum benötigt Apothekerin Zamah einen Abenteurer, um die Notiz zu überbringen?",a="Apothekerin Zamah ist an Die Teiche der Visionen unterhalb von Donnerfels als Gesandte der Royal Apothecary Society stationiert. Ihre Arbeit erfordert es, ihre Präsenz unter den misstrauischen Tauren aufrechtzuerhalten und ihre laufenden alchemistischen Aufgaben in Kalimdor zu verwalten. Einen unabhängigen Boten über das Meer nach Tarrens Mühle zu schicken, ist weitaus praktischer, als ihren heiklen diplomatischen und Forschungsposten aufzugeben.",al={"warum werdet ihr gesandt","warum kann zamah nicht selbst gehen","warum benötigt zamah mich"}}},fp="22,221,27.378.0,21.355.0,24.355.1,61.246.0,29.216.0,46.256.0,68.253.0,37.277.0,48.201.1"}
P.entries["quest:1066"] = {n="Das Blut Unschuldiger",s="In Tarrens Mühle bereitet Apotheker Lydon ein Mittel gegen die Venture Company im Steinkrallengebirge vor. Die Königliche Apothekervereinigung greift auf Blut zurück, das örtliche Banditen geraubt haben, um die Kompanie zu besänftigen.",h="In Tarrens Mühle bereitet Apotheker Lydon ein Mittel gegen die Venture Company im Steinkrallengebirge vor.",kw={"apotheker lydon","das blut unschuldiger","burg durnholde","schattenmagier","steinkrallengebirge","syndikat","tarrens mühle","venture company"},ang={["faction:Horde"]="Als Mitglied der Horde erlebt Ihr ihre weitreichenden Verbindungen in Aktion. Die Alchemie der Verlassenen in Lordaeron hilft, die Gebiete der Horde in Kalimdor zu schützen.",["race:Tauren"]="Als Tauren mag Euch das Entnehmen unschuldigen Blutes beunruhigen. Das Ziel ist es, der Zerstörung der Wildnis Kalimdors durch die Venture Company ein Ende zu setzen.",["race:Undead"]="Für die Verlassenen steht Effizienz vor moralischen Bedenken. Lydons berechnendes Vorgehen zeigt, wie die Königliche Apothekervereinigung mit kalter Logik Probleme für ihre lebenden Verbündeten löst."},sec={{t="Eine chemische Lösung",b="Die Horde kämpft im Steinkrallengebirge gegen die Venture Company. Die Kompanie verwüstet die Wildnis und schadet ihren Bewohnern, weshalb Apotheker Lydon Alchemie vorschlägt, statt Armeen zu entsenden, um ihre Äxte abzustumpfen. Er will ein Mittel brauen, das die Söldner lähmt und besänftigt und sie schwach und gefügig zurücklässt."},{t="Den Frevlern geraubt",b="Apotheker Lydon braucht eine seltene und beunruhigende Zutat: unschuldiges Blut. Er will keine Agenten der Horde aussenden, um Unschuldige zu töten, also nutzt er die Verbrechen des Syndikats. Gefallene Adlige und Halsabschneider besetzen Burg Durnholde, wo abtrünnige Schattenmagier unschuldiges Blut für frevlerische Rituale gewinnen. Lydon nimmt diese Magier ins Visier, um alchemistische Vorräte zu beschaffen."}},faq={{q="Warum braucht Apotheker Lydon unschuldiges Blut?",a="Apotheker Lydon braucht unschuldiges Blut für ein experimentelles Gebräu. Er hofft, dass dessen Gift den Mitgliedern der Venture Company im Steinkrallengebirge ihren gewalttätigen Drang nimmt und sie gefügig und leichter kontrollierbar macht.",al={"wozu dient unschuldiges blut","warum das blut unschuldiger","lydon blut auftrag"}},{q="Wer hat die Phiolen mit unschuldigem Blut?",a="Schattenmagier des Syndikats tragen die Phiolen mit unschuldigem Blut bei sich. Sie lauern in den Ruinen von Burg Durnholde südöstlich von Tarrens Mühle und bewahren das Blut für ihre Zauberei auf.",al={"wer lässt das blut fallen","woher das blut unschuldiger bekommen","unschuldiges blut fundort"}},{q="Warum geht es bei einem Auftrag in Hillsbrad um das Steinkrallengebirge?",a="Anführer der Horde in Kalimdor baten die Königliche Apothekervereinigung in den Östlichen Königreichen um wissenschaftliche Hilfe. Der Konflikt mit der Venture Company spielt sich im Steinkrallengebirge ab, während Apotheker Lydon in Tarrens Mühle die dunkle Kunst beherrscht, ein besonderes Gegenmittel zu brauen.",al={"verbindung zum steinkrallengebirge","warum tarrens mühle steinkrallengebirge"}},{q="Was ist das Syndikat?",a="Das Syndikat besteht aus ehemaligen menschlichen Adligen des untergegangenen Königreichs Alterac, die heute Räuber, Meuchelmörder und Halsabschneider sind. Sie hoffen, ihre verlorenen Ländereien zurückzugewinnen, und nutzen Erpressung und dunkle Magie, während sie Reisenden in Hillsbrad und Alterac auflauern.",al={"wer ist das syndikat","syndikat hintergrundgeschichte"}},{q="Wo liegt Burg Durnholde?",a="Burg Durnholde liegt südöstlich von Tarrens Mühle im Vorgebirge des Hügellands. Einst eine menschliche Festung und ein Internierungslager für Orcs, liegt sie heute halb in Trümmern und ist ein wichtiger Stützpunkt des Syndikats.",al={"burg durnholde finden","wo ist durnholde"}},{q="Begeht die Horde Morde, um an dieses Blut zu gelangen?",a="Nein. Die Königliche Apothekervereinigung nimmt grausige Methoden in Kauf, doch Lydon weist Agenten an, Blut zu beschaffen, das die Schattenmagier des Syndikats ihren Opfern bereits abgenommen haben.",al={"hat die horde unschuldige getötet","unschuldiges blut herkunft"}}},fx={b5439bfd={q="Wofür ist die Phiole mit unschuldigem Blut gut?",a="Apotheker Lydon benötigt die Phiole mit unschuldigem Blut, um ein spezielles Gebräu für die Royal Apothecary Society zu brauen. Anstatt direkt zu töten, ist sein geplantes Gift so formuliert, dass es die aggressive Venture Company im Steinkrallengebirge befriedet, ihren Kampfwillen entzieht und sie gefügig macht.",al={"nutzen der phiole mit unschuldigem blut","was bewirkt unschuldiges blut","zweck von unschuldigem blut"}}},fp="18,189,19.351.0,22.331.0,46.204.0,36.168.0,60.251.0,22.247.0,32.177.0,49.165.0"}
P.entries["quest:1067"] = {n="Rückkehr nach Donnerfels",s="In Donnerfels erwartet Zamah das von Lydon hergestellte Toxin. Sie braucht seine Formel, um ein Gerät zu bauen, das es gegen die Venture Company verbreiten kann.",h="In Donnerfels erwartet Zamah das von Lydon hergestellte Toxin.",kw={"apotheker lydon","apothecary zamah","lydons toxin","die teiche der visionen","rückkehr nach donnerfels","königliche apothekervereinigung","tarrens mühle","toxinvernebler","venture company"},ang={["faction:Horde"]="Als Mitglied der Horde seht Ihr, wie Alchemisten der Verlassenen gemeinsam gegen die zerstörerischen Unternehmungen der Venture Company vorgehen.",["race:Tauren"]="Als Tauren wisst Ihr, dass Magatha Grimmtotem und die Ältesten die Verlassenen in Donnerfels willkommen hießen, in der Hoffnung, sie würden Erlösung oder Heilung finden. Die Apotheker unter der Anhöhe der Geister stellen stattdessen ansteckende Waffen her.",["race:Undead"]="Als Untoter könnt Ihr sehen, wie die Königliche Apothekervereinigung die Forschung in Lordaeron mit Außenposten auf Kalimdor verbindet."},sec={{t="Eine transkontinentale Lieferung",b="Apotheker Lydon hat das Toxin aus Zutaten hergestellt, die im Vorgebirge des Hügellands gesammelt wurden. Er will es an lebenden Versuchsobjekten testen, doch zuerst braucht er eine Möglichkeit, es zu verbreiten. Ihr tragt die Phiole über das große Meer nach Mulgore, wo Apothekerin Zamah wartet."},{t="Zamahs Apparat",b="Unter der Anhöhe der Geister in Donnerfels arbeitet Apothekerin Zamah als Botschafterin und Forscherin für die Königliche Apothekervereinigung. Lydons Formel ermöglicht ihr den Bau eines Aerosolgeräts namens Toxinvernebler. Sie will es gegen die Goblins der Venture Company einsetzen."}},faq={{q="Warum wird das Toxin nach Donnerfels gebracht?",a="Lydon hat das flüssige Toxin hergestellt, doch es braucht eine Möglichkeit, sich über eine große Fläche zu verbreiten. Zamah kann mit der Formel ein Aerosolgerät namens Toxinvernebler herstellen.",al={"warum donnerfels","was macht zamah mit dem toxin","verwendung von lydons toxin"}},{q="Gegen wen richtet sich dieses Gebräu?",a="Das Toxin ist für die Venture Company bestimmt, ein Bergbausyndikat der Goblins, dessen Unternehmungen bis ins Steinkrallengebirge und darüber hinaus reichen.",al={"wer wird vergiftet","ziel von lydons toxin","gegen wen kämpfen wir"}},{q="Wo befindet sich Apothekerin Zamah?",a="Apothekerin Zamah befindet sich in den Teichen der Visionen, unter der Anhöhe der Geister in Donnerfels.",al={"zamah finden","wo ist apothecary zamah","zamahs standort"}},{q="Warum arbeiten Apotheker aus Unterstadt in einer Stadt der Tauren?",a="Die Tauren gewährten den Verlassenen Asyl und halfen ihnen, der Horde beizutreten, in der Hoffnung, sie könnten ein Heilmittel für ihr Leiden finden. Zamah vertritt die Königliche Apothekervereinigung, deren Arbeit sich hier Seuchen und Waffen statt der Heilung zuwendet.",al={"verlassene in donnerfels","warum sind untote in donnerfels","apotheker in mulgore"}},{q="Was geschieht nach der Übergabe des Toxins?",a="Nachdem Zamah die Phiole erhalten hat, stellt sie den Toxinvernebler her. Dann schickt sie Euch los, um ihn in einer Anlage der Venture Company im Steinkrallengebirge einzusetzen.",al={"nächste quest","was kommt nach rückkehr nach donnerfels","toxinvernebler quest"}},{q="Wer hat die ursprüngliche Formel entwickelt?",a="Apotheker Lydon, ein Forscher der Königlichen Apothekervereinigung in Tarrens Mühle, hat das Gift hergestellt.",al={"wer hat das gift hergestellt","wer ist lydon","geschichte von apotheker lydon"}}},fx={["4bd277bc"]={q="Warum möchte Apotheker Lydon, dass dies getan wird?",a="Apotheker Lydon brennt darauf zu sehen, wie seine Gebräue im Feld praktisch eingesetzt werden. Sein Toxin soll der Venture Company die Gewalttätigkeit austreiben und sie schwach und gefügig machen, doch es kann allein nicht wirksam eingesetzt werden. Es zurück zu Apothekerin Zamah in Donnerfels zu schicken, ermöglicht es ihr, eine geeignete Verabreichungsmethode zu entwickeln, die seine Wirkung maximiert – mit günstigen, vielleicht sogar ansteckenden Ergebnissen.",al={"warum will lydon das","lydon motiv","apotheker lydon grund"}}},fp="23,140,27.243.0,17.257.1,59.155.0,37.129.0,34.81.0,56.239.0,40.146.1,33.88.0"}
P.entries["quest:1068"] = {n="Schreddermaschinen",s="In der Scherwindklippe verwunden Schredder der Venture Company die Geister des Steinkrallengebirges. Seereth Bruchstein hört ihre Schreie, während XT:4 und XT:9 durch den Wald schneiden.",h="In der Scherwindklippe verwunden Schredder der Venture Company die Geister des Steinkrallengebirges.",kw={"abholzung","seereth bruchstein","schredder","schreddermaschinen","steinkrallengebirge","venture company","die scherwindklippe","xt:4","xt:9"},ang={["class:Shaman"]="Seereth verweist auf die enge Verbindung zwischen spiritueller Magie und Natur. Das Gleichgewicht der Elemente hängt davon ab, dass die Geister verteidigt werden, die im Land wohnen.",["faction:Horde"]="Während die Horde überall in Kalimdor Stützpunkte errichtet, hilft das Eindämmen der ungezügelten Gier der Venture Company, das Land zu bewahren und Reisen durch das Steinkrallengebirge sicher zu halten.",["profession:Engineering"]="Die Holzfällermechs der XT-Serie zeigen fortschrittliche Schreddertechnik der Goblins, die mechanische Hydrauliksägen mit dampfbetriebener Fortbewegung verbindet.",["race:Tauren"]="Die Entweihung der uralten Wälder des Steinkrallengebirges durch seelenlose Goblinmaschinen verstößt gegen die Verehrung der Earth Mother."},sec={{t="Eine Vision der Abholzung",b="Die Orcschamanin Seereth Bruchstein wacht an der staubigen Grenze zwischen dem Brachland und dem Steinkrallengebirge. Sie lauscht dem unsichtbaren Reich, doch das Chaos übertönt einen Großteil der spirituellen Stimme des Steinkrallengebirges. Eine Vision drang klar zu ihr durch: menschengestaltige Apparaturen, die sich mit unnatürlicher Geschwindigkeit durch uralte Wälder fraßen. Die von Goblins konstruierten Schredder mit den Kennzeichnungen XT:4 und XT:9 holzen die Wälder der Scherwindklippe ab und erschüttern die umgebenden Naturgeister mit Wellen der Qual."},{t="Die Sägen zum Schweigen bringen",b="Die Venture Company arbeitet in der Scherwindklippe, nordwestlich des Hochwipfeltals. Um den Schaden einzudämmen, ziehen Champions der Horde dorthin und machen Jagd auf die Holzfällerkonstrukte. Die Zerstörung von XT:4 und XT:9 trifft die kommerzielle Abholzung des Gebirges und lässt die unmittelbaren Schreie der verwundeten Baumgeister verstummen. Seereth warnt, dass dem Land weit finsterere Gräueltaten bevorstehen, wenn die Venture Company das Steinkrallengebirge nicht vollständig verlässt."}},faq={{q="Wer ist Seereth Bruchstein?",a="Seereth Bruchstein ist eine Orcschamanin, die an der südlichen Grenze zwischen dem Brachland und dem Steinkrallengebirge stationiert ist. Mit den elementaren und spirituellen Kräften des Landes verbunden, trägt sie die Klagen der Waldgeister weiter, die unter der raschen Ausbreitung der Venture Company leiden.",al={"wer ist seereth","questgeberin seereth","seერeth bruchstein geschichte"}},{q="Was sind XT:4 und XT:9?",a="XT:4 und XT:9 sind spezialisierte Holzfällerschredder, die von der Venture Company in der Scherwindklippe eingesetzt werden. Goblins steuern diese dampfbetriebenen Schreitmaschinen, die uralte Bäume weit schneller fällen als Arbeiter von Hand.",al={"was sind die schredder","xt4 und xt9","schredder ziele"}},{q="Wo liegt die Scherwindklippe?",a="Die Scherwindklippe liegt im nördlichen Steinkrallengebirge, nordwestlich des Hochwipfeltals. Die Venture Company hat sie in einen gewaltigen Talkessel für die industrielle Abholzung verwandelt.",al={"scherwindklippe lage","wo sind die schredder zu finden","wo sind die maschinen"}},{q="Warum kümmert sich eine Schamanin um Bäume und druidische Magie?",a="Seereth erklärt, dass die schamanische Zwiesprache mit Geistern eng mit der druidischen Naturmagie verbunden ist. Schäden an lebenden Wäldern hallen im Geisterreich wider, wo feinfühlige Schamanen neben elementarer Unruhe auch die hingeschlachteten Baumgeister hören.",al={"warum kümmern sich schamanen um bäume","verbindung schamanen druiden","naturgeister schamanen"}},{q="Wem gehören diese Schredder und wer betreibt sie?",a="Die Schredder gehören der Venture Company. Dieses von Goblins geführte Handelskonglomerat ist in ganz Azeroth dafür berüchtigt, wertvolle natürliche Ressourcen ohne Rücksicht auf örtliche Ökosysteme oder angestammte Bewohner auszubeuten.",al={"wer hat xt4 gebaut","wer betreibt die schredder","venture company schredder"}},{q="Vertreibt die Zerstörung von XT:4 und XT:9 die Venture Company?",a="Nein. Die Zerstörung dieser Maschinen beruhigt die weinenden Baumgeister und wirft die örtliche Abholzung zurück, doch die Venture Company behält eine ausgedehnte industrielle Präsenz in der Scherwindklippe. Die Verteidiger der Wildnis müssen sich ihrer Anwesenheit weiterhin widersetzen.",al={"verlässt die venture company das gebiet","nach schreddermaschinen","questausgang"}}},fx={["0171bd6f"]={q="Warum möchte Seereth Bruchstein, dass XT:4 und XT:9 zerstört werden?",a="Als eine auf die Geisterwelt eingestimmte Schamanin hört Seereth die qualvollen Schreie des geschundenen Landes im Steinkrallengebirge. Die natürliche Verbindung zwischen schamanischer Spiritualität und dem Gleichgewicht der Natur erlaubt es ihr, das Wehklagen der Baumgeister wahrzunehmen, während die Venture Company sich durch die Berge frisst. In einer klaren spirituellen Vision sah sie, wie diese beiden spezifischen mechanischen Schrecken das uralte Holz in unnatürlichem Tempo fällten. Für sie ist ihre Zerstörung eine lebenswichtige spirituelle Pflicht; wenn diese Maschinen ihr ungebremstes Abschlachten des Waldes fortsetzen, werden die Wunden des Landes vielleicht niemals heilen.",al={"warum die schredder zerstören","beweggrund von seereth bruchstein","warum xt4 und xt9 zerstören"}}},fp="18,155,25.465.0,18.400.0,26.268.0,23.219.0,24.173.0,53.240.0,38.209.0,61.232.0"}
P.entries["quest:1069"] = {n="Eier der Kluftmoosspinnen",s="In Ratschet sieht Mebok Mizzyrix eine Gelegenheit, Eier der Kluftmoosspinnen nach Beutebucht zu verkaufen. Spinnenei-Omelettes sind dort zum großen Trend geworden, also schickt er Reisende ins Steinkrallengebirge, um frische Gelege für den Handel über das Meer zu sammeln.",h="In Ratschet sieht Mebok Mizzyrix eine Gelegenheit, Eier der Kluftmoosspinnen nach Beutebucht zu verkaufen.",kw={"beutebucht","kluftmoos","dizzywig","mebok mizzyrix","omelette","ratschet","sishircanyon","spinneneier","die scherwindklippe"},ang={["faction:Alliance"]="Als Späher der Allianz zwischen dem Brachland und den Nachtelfenenklaven im Steinkrallengebirge könnt Ihr die Neutralität von Ratschets Goblins nutzen, um Eure Reisekasse aufzubessern.",["faction:Horde"]="Als Reisender der Horde, der das Brachland in Richtung Steinkrallengebirge durchquert, könnt Ihr in Ratschet schnell Münzen verdienen, um den Kampf gegen die örtlichen Harpyien und die Holzfäller der Venture Company zu finanzieren.",["profession:Cooking"]="Als Koch könnt Ihr sehen, wie Gäste in Hafenstädten ungewöhnliche, gewagte Speisen wie Eier der Kluftmoosspinnen zu Statussymbolen machen."},sec={{t="Ein Hang zum Luxus",b="Wohlhabende Gäste und exzentrische Piraten in Beutebucht haben Gefallen an Spinnenei-Omelettes gefunden. Ihr Geschmack hat die Nachfrage nach seltenen Zutaten über das große Meer hinweg angeheizt. Mebok Mizzyrix, ein Händler aus Ratschet, sieht eine Gelegenheit, mit der Versorgung des südlichen Hafens ein Vermögen zu machen. In den Östlichen Königreichen gibt es keine Spinnen, die diese Eier liefern, also richtet Mebok seinen Blick auf Kalimdors Wildnis."},{t="Nester in den Bergen",b="Eier der Kluftmoosspinnen liegen im Steinkrallengebirge, wo die Venture Company Holz geschlagen hat. Sucht Gelege unter den noch stehenden Bäumen an der Scherwindklippe oder weiter im Landesinneren, in den von Spinnweben überzogenen Tiefen des Sishircanyons. Beim Sammeln erwarten Euch giftige Bisse und dichte Spinnenplagen. Selbst erfahrenen Plünderern können die Schwärme auf den Magen schlagen."},{t="Der Muscheldampfer-Express",b="Frische Eier müssen das Meer überqueren, bevor sie verderben oder die Spinnen schlüpfen. Mebok arbeitet mit Werftmeister Dizzywig aus Ratschet zusammen, um Frachtraum auf Goblinhandelsschiffen zu buchen, die zu den Docks im Schlingendorntal fahren. Sobald die Eier in Kisten verpackt sind, verdient Mebok mit dem Überseehandel mit feinen Speisen einen ansehnlichen Gewinn."}},faq={{q="Warum will Mebok Mizzyrix Spinneneier?",a="Beutebucht hat Gefallen an Spinnenei-Omelettes gefunden, doch vor Ort gibt es keine Bezugsquelle für die Eier. Mebok Mizzyrix sieht eine Gelegenheit für Ratschets Goblinhändler, an der Versorgung des Hafens zu verdienen.",al={"warum spinneneier","mebok spinneneier","wofür sind die eier"}},{q="Wo findet man die Eier der Kluftmoosspinnen?",a="Eier der Kluftmoosspinnen findet Ihr im Steinkrallengebirge, nordwestlich des Brachlands. Sammelt sie unter den verbliebenen Bäumen an der Scherwindklippe oder tiefer im Sishircanyon.",al={"wo sind kluftmooseier","fundorte der eier","spinneneier fundorte steinkrallengebirge"}},{q="Warum warnt Mebok vor dem Sishircanyon?",a="Im Sishircanyon gibt es gewaltige Spinnenschwärme, dichte Spinnweben und teilweise verdaute Beute. Mebok rät jedem mit empfindlichem Magen, die Eier stattdessen unter den Bäumen an der Scherwindklippe zu sammeln.",al={"sishircanyon warnung","empfindlicher magen sishir"}},{q="Wer verschifft die gesammelten Eier?",a="Mebok arbeitet mit Werftmeister Dizzywig an den Docks von Ratschet zusammen, um die Eier per Handelsschiff über das Meer nach Beutebucht zu schicken.",al={"wer verschifft die eier","werftmeister verschiffung","dizzywig eier"}},{q="Werden die Eier roh oder gekocht gegessen?",a="Die Eier werden zu Omelettes verarbeitet, einem exzentrischen Luxusgericht für wohlhabende Gäste und Abenteurer, die Beutebuchts Tavernen besuchen.",al={"wie werden spinneneier gegessen","spinnenei-omelettes"}},{q="Können Spieler beider Fraktionen diese Aufgabe erfüllen?",a="Ja. Ratschet ist ein offener Hafen unter der Leitung des Steamwheedle Cartel, und Mebok Mizzyrix bietet Reisenden der Allianz und der Horde diese Arbeit an.",al={"ist diese quest neutral","horde oder allianz spinneneier"}}},fp="20,234,18.360.0,22.352.0,24.298.0,41.187.0,44.178.0,42.185.0,34.121.0,33.126.0,48.128.0"}
P.entries["quest:107"] = {n="Nachricht an William",s="Im Süden von Elwynn bittet Mildred William Pestle, zwei jungen Liebenden zu helfen. Ihre Nachricht gelangt zu dem Apotheker in Goldhain, von dem sie hofft, dass er Maybell und Tommy Joe trotz der Familienfehde zusammenbringen kann.",h="Im Süden von Elwynn bittet Mildred William Pestle, zwei jungen Liebenden zu helfen.",kw={"wald von elwynn","goldhain","oma steinfeld","gasthaus \"zur höhle des löwen\"","maybell maclure","mildred steinfeld","nachricht an william","tommy joe steinfeld","william pestle"},ang={["faction:Alliance"]="Als Abenteurer der Allianz im Wald von Elwynn könnt Ihr den örtlichen Bauernfamilien bei persönlichen Schwierigkeiten helfen, während sich die Wachen auf militärische Bedrohungen konzentrieren.",["race:Human"]="Als Mensch in Elwynn seht Ihr, wie die Fehde zwischen den Familien Steinfeld und Maclure Nachbarn entzweit. Mitfühlende Ältere verlassen sich auf diskrete Boten."},sec={{t="Unglückliche Liebe in Elwynn",b="Tommy Joe Steinfeld und Maybell Maclure verbergen ihre Liebe vor ihren verfeindeten Familien. Die Familien Steinfeld und Maclure leben seit Jahren als Nachbarn im südlichen Wald von Elwynn. Doch ihre erbitterte Rivalität erschwert selbst den gewöhnlichen Umgang miteinander. Oma Mildred Steinfeld hat Mitleid mit den jungen Liebenden und sucht nach einem anderen Weg, sie zusammenzubringen."},{t="Ein Hilferuf nach Goldhain",b="Mildred schickt einen Boten nach Norden zum Gasthaus \"Zur Höhle des Löwen\" in Goldhain, wo William Pestle als Alchemist und Apotheker arbeitet. Sie kennt ihn seit vielen Jahren und glaubt, dass Überredung allein die verfeindeten Familien nicht umstimmen kann. In ihrer Nachricht bittet sie ihn um Hilfe. Als William sie erhält, berührt ihn die Not von Maybell und Tommy Joe, und er beschließt, sein alchemistisches Wissen für sie einzusetzen."}},faq={{q="Wer ist William Pestle?",a="William Pestle ist Alchemist und Apotheker im Gasthaus \"Zur Höhle des Löwen\" in Goldhain. Er kennt Oma Mildred Steinfeld seit vielen Jahren und stellt pflanzliche Heilmittel und besondere Tränke her.",al={"wer ist william pestle","william pestle goldhain","alchemist goldhain"}},{q="Wer hat die Nachricht an William geschickt?",a="Oma Mildred Steinfeld hat die Nachricht geschrieben und an William Pestle geschickt. Sie hofft, dass er einen Weg findet, Maybell Maclure und Tommy Joe Steinfeld zu helfen.",al={"wer hat die nachricht geschickt","oma steinfeld nachricht","mildred steinfeld"}},{q="Warum können Maybell und Tommy Joe nicht offen zusammen sein?",a="Maybell Maclure und Tommy Joe Steinfeld lieben einander, doch ihre Familien verbindet eine erbitterte Rivalität, die seit Jahren andauert. Oma Steinfeld hofft, dass William Pestle einen Trank oder einen Plan findet, damit sie trotz dieser Feindschaft zusammen sein können.",al={"warum maybell und tommy joe helfen","junge liebende quest elwynn","steinfeld maclure fehde"}},{q="Wo ist William Pestle zu finden?",a="William Pestle hält sich im Gasthaus \"Zur Höhle des Löwen\" in Goldhain auf, einem Ort im Wald von Elwynn.",al={"wo ist william pestle","pestle aufenthaltsort","gasthaus \"zur höhle des löwen\" alchemist"}},{q="Wie heißt Oma Steinfeld wirklich?",a="Ihr Vorname ist Mildred. Als William Pestle ihren Brief erhält, sagt er, dass er Mildred seit Jahren nicht gesehen hat.",al={"wie lautet oma steinfelds vorname","oma steinfeld name"}},{q="Wie reagiert William Pestle auf die Nachricht?",a="William sagt, dass er Mildred seit Jahren nicht gesehen hat, und fragt sich dann, was in ihrer Nachricht steht. Sie hofft, dass seine alchemistische Kunst den jungen Liebenden helfen kann.",al={"was macht william mit der nachricht","william pestle reaktion"}}},fp="15,210,22.337.0,22.388.0,22.189.0,29.149.0,59.248.0,34.83.0,38.108.0,42.143.0"}
P.entries["quest:1070"] = {n="Wache halten im Steinkrallengebirge",s="In Eschental bittet Schildwache Thenysil Reisende, nach Kaela Schattenspeer zu sehen. Kaela zog mit einem Gnommagier ins Steinkrallengebirge, um die Vorstöße der Venture Company zu beobachten, doch es kam keine Nachricht von ihr.",h="In Eschental bittet Schildwache Thenysil Reisende, nach Kaela Schattenspeer zu sehen.",kw={"eschental","kaela schattenspeer","wache halten im steinkrallengebirge","schildwache thenysil","steinkrallengebirge","venture company","die scherwindklippe"},ang={["faction:Alliance"]="Dies markiert die Ausweitung der Grenzsicherung der Allianz nach Süden, von Eschentals Verteidigungsposten bis zu abgelegenen Spähposten im Steinkrallengebirge.",["race:Gnome"]="Als Gnom empfindet Ihr die tiefe Skepsis der Schildwachen gegenüber gnomischer Magie und Apparaturen womöglich als schroffen Empfang. Sie betrachten einen Gnommagier in Kalimdors Wildnis als sonderbare, unberechenbare Erscheinung.",["race:NightElf"]="Als Nachtelf seht Ihr die Spannungen zwischen traditionellen Schildwachen und den arkanen und mechanischen Methoden ihrer Verbündeten aus Eastern Kingdom, besonders der Gnome."},sec={{t="Eine Späherin nach Süden entsandt",b="In Astranaar hält Schildwache Thenysil nach Bedrohungen nahe dem uralten Wald Ausschau. Ihre Freundin Kaela Schattenspeer zog auf Befehl von Schildwache Wolfrunner ins Steinkrallengebirge, um Unruhen in den Höhen zu erkunden. Thenysil bittet vorbeikommende Champions der Allianz, Kaela zu finden. Es kam keine Nachricht, und sie fürchtet um die Sicherheit ihrer Freundin."},{t="Unbehagliche Bündnisse in den Klippen",b="Ein von der Führung der Allianz zugeteilter Gnommagier begleitet Kaela. Die Nachtelfen schlossen sich der Großen Allianz aus strategischen Gründen an, doch viele Schildwachen misstrauen arkanen Zauberkundigen und gnomischen Tüftlern in der Wildnis. Kaela unterhält einen Außenposten auf den Klippen über der Scherwindklippe. Von dort beobachtet sie die weitreichenden Verwüstungen durch die Venture Company."}},faq={{q="Wer vergibt diese Quest?",a="Schildwache Thenysil, eine nachtelfische Schildwache in Astranaar in Eschental, vergibt sie.",al={"questgeber","wo beginnen","wer startet wache halten im steinkrallengebirge"}},{q="Wo kann ich Kaela Schattenspeer finden?",a="Kaela Schattenspeer lagert auf einem felsigen Grat über dem Taleingang zur Scherwindklippe im Steinkrallengebirge.",al={"kaelas standort","kaela finden","kaela schattenspeer fundort"}},{q="Warum sorgt sich Schildwache Thenysil um Kaela?",a="Kaela zog los, um gefährliche feindliche Vorstöße im Steinkrallengebirge zu untersuchen, und hat keine Nachricht zurückgeschickt. Thenysil misstraut auch dem Gnommagier, der Kaela begleiten soll, und sieht in dieser Paarung ein böses Omen.",al={"warum sorgen","thenysils sorge"}},{q="Welche Bedrohungen gibt es im Steinkrallengebirge?",a="Die skrupellose Venture Company, ein Bergbau- und Holzfällerkartell der Goblins, verwüstet die Wildnis. Aggressive einheimische Bestien und rivalisierende Streitkräfte der Horde drängen ebenfalls von Süden her vor.",al={"feinde im steinkrallengebirge","wer ist im steinkrallengebirge"}},{q="Wer ist Tara?",a="Tara ist der Vorname von Schildwache Thenysil. Wenn Ihr Kaela trefft, nennt sie ihre alte Freundin liebevoll Tara und ist stolz darauf, wie diese Späher und Abenteurer koordiniert.",al={"wer ist tara","tara erwähnt"}},{q="Was geschieht, nachdem Kaela Schattenspeer gefunden wurde?",a="Mit dem Erreichen von Kaela endet die Reise, und weitere Aufgaben folgen, bei denen Ihr ihr und ihrem gnomischen Partner helft, die zur Scherwindklippe vordringenden Bedrohungen zu beobachten.",al={"nächste quest","what comes next"}}},fx={["96da069b"]={q="Warum benötigt Schildwache Thenysil einen Abenteurer, um Kaela zu finden?",a="Schildwache Thenysil ist im Eschental im Dienst stationiert und kann ihren Posten nicht einfach verlassen, um in die Nachbarländer zu reiten. Wenn sie einen fähigen Reisenden mit Abenteuerlust sieht, ergreift sie die Gelegenheit, einen unabhängigen Kundschafter anzuwerben, der über die Grenze in das Steinkrallengebirge schlüpfen kann, ohne die Verteidigung der Wächter vor Ort zu stören.",al={"warum werdet ihr gesandt","warum geht thenysil nicht selbst","warum ein abenteurer"}}},fp="22,195,18.321.0,32.342.0,21.75.0,35.125.0,45.204.0,52.184.0,12.164.0,45.145.0"}
P.entries["quest:1071"] = {n="Der Aufschub des Gnoms",s="An der Scherwindklippe dringt die Venture Company in den Wald vor, während Gaxim Rostknirsch ihren Vormarsch zu bremsen versucht. Er bittet Reisende, ihre Arbeiter zurückzudrängen, damit er neue Verteidigungsmaßnahmen vorbereiten kann.",h="An der Scherwindklippe dringt die Venture Company in den Wald vor, während Gaxim Rostknirsch ihren Vormarsch...",kw={"waldarbeiter","sprengstoff","gaxim rostknirsch","gnom","holzfäller","steinkrallengebirge","venture co","die scherwindklippe"},ang={["profession:Engineering"]="Als Ingenieur wisst Ihr vielleicht Gaxims Vertrauen in Mechanik und Chemie zur Bewältigung von Umweltkrisen zu schätzen, ebenso wie seine Vorliebe für Hochexplosivstoffe.",["race:Gnome"]="Als Gnom erkennt Ihr Gaxims Ehrgeiz: Er will dem Konflikt zwischen Natur und Zivilisation mit Einfallsreichtum und Hochexplosivstoffen begegnen.",["race:NightElf"]="Als Nachtelf wisst Ihr, dass gnomische Maschinen bei den Schildwachen der Kaldorei tiefes Misstrauen wecken. Im Steinkrallengebirge macht der Vormarsch der Venture Company jedes wirksame Abschreckungsmittel willkommen."},sec={{t="Eine Allianz im Widerstreit",b="Gaxim Rostknirsch vertritt die Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences. In den uralten Hainen des Steinkrallengebirges hofft er, den naturverehrenden Nachtelfen zu zeigen, dass gnomischer Erfindergeist ihre bedrohten Länder verteidigen kann. Er vereint Magie, chemische Gebräue und Mechanik, doch das unerbittliche Tempo der Venture Company lässt ihm wenig Zeit, Verteidigungsanlagen zu bauen."},{t="Zeitgewinn an der Scherwindklippe",b="An der Scherwindklippe schickt Gaxim Reisende in die rauchenden Betriebe, um die Holzfäller und Waldarbeiter der Venture Co. zurückzudrängen. Wenn sie sich zurückziehen, hat er Zeit, seine Werkstatt zu ordnen und seine nächste Verteidigungsmaßnahme auszutüfteln: kontrollierte, strategisch eingesetzte Hochexplosivstoffe."}},faq={{q="Wer ist Gaxim Rostknirsch?",a="Gaxim Rostknirsch ist ein gnomischer Magier und Tüftler der Allianz im Steinkrallengebirge. Er arbeitet für die Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences und will den Nachtelfen gegen industrielle Eindringlinge helfen.",al={"gaxim","wer ist gaxim rostknirsch","questgeber gaxim"}},{q="Warum versucht ein Gnom, die Wälder der Nachtelfen zu schützen?",a="Gaxim glaubt, den skeptischen Nachtelfen beweisen zu müssen, dass gnomische Wissenschaften im Einklang mit der Natur bestehen und ihre Wildnis verteidigen können. Er setzt Arkanologie, Alchemie und Ingenieurskunst gegen die ungezügelte industrielle Ausbeutung ein.",al={"warum gnom im steinkrallengebirge","warum nachtelfen helfen","gnomische ökologie"}},{q="Wer ist die Venture Company an der Scherwindklippe?",a="Die Venture Company ist ein von Goblins geführtes Handelssyndikat, das an der Scherwindklippe Holz schlägt und Tagebau betreibt. Ihre Holzfäller, Waldarbeiter und schweren Maschinen haben auf der Jagd nach Profit das Tal überrannt.",al={"venture co steinkrallengebirge","wer ist die venture co","scherwindklippe goblins"}},{q="Wo sind die Holzfäller und Waldarbeiter zu finden?",a="Die Holzfäller und Waldarbeiter sind überall an der Scherwindklippe tätig, dem Industriebecken direkt östlich von Gaxims Standort an der Hauptstraße im Steinkrallengebirge.",al={"wo sind holzfäller","wo waldarbeiter finden","scherwindklippe lage"}},{q="Was plant Gaxim, sobald er Zeit zum Nachdenken hat?",a="Sobald die Goblinarbeiter zurückgedrängt sind, will Gaxim seine Hochexplosivstoffe aufstocken. Mit gezielten Sprengungen am Berg will er die Venture Company von den Hainen wegtreiben und abschrecken.",al={"gaxims plan","der aufschub des gnoms fortsetzung","sprengstoffplan"}},{q="Was ist die Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences?",a="Die Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences ist eine gnomische Gelehrtengesellschaft. Sie erforscht, wie arkane Zauberkunst, chemische Gemische und Maschinenbau praktische Probleme in ganz Azeroth lösen können.",al={"gnomische versammlung","arkanologie versammlung","was ist die enlightened assembly"}}},fx={["8136de5d"]={q="Warum möchte Gaxim Rostknirsch, dass die Venture Company dezimiert wird?",a="Gaxim Rostknirsch fühlt es als seine Pflicht als Mitglied der Aufgeklärten Versammlung für Arkanologie, Alchemie und Ingenieurswissenschaften, zu beweisen, dass gnomischer Einfallsreichtum die heiligen Wälder der Nachtelfen schützen kann. Die unerbittlich schnelle Entwaldung durch die Venture Company überfordert ihn ständig und lässt ihm keinen Freiraum, um die erfinderischen Geräte und Sprengstoffe zu entwickeln, zu organisieren und zusammenzubauen, die er benötigt, um das Blatt zu wenden.",al={"warum die holzfäller töten","beweggrund von gaxim","warum venture co dezimieren"}},["7aed6e2a"]={q="Warum benötigt Gaxim Rostknirsch Euch, um gegen die Goblins zu kämpfen?",a="Gaxim ist eher Erfinder und Forscher als eine Ein-Mann-Armee, und er arbeitet ohne nennenswerte militärische Unterstützung der Allianz im Steinkrallengebirge. Zwischen der Sicherung seines Lagers und dem Versuch, neue mechanische Schaltpläne zu entwerfen, kann er die endlos schwärmenden Holzfäller der Venture Company einfach nicht alleine abwehren. Er verlässt sich auf fähige Abenteurer wie Euch, um ihre Reihen zu lichten, damit er sich auf den Bau seiner Gegenmaßnahmen konzentrieren kann.",al={"warum ich für gaxim","warum benötigt gaxim hilfe","warum einen abenteurer senden"}}},fp="17,192,19.373.0,29.245.0,24.232.0,51.221.0,46.193.0,47.163.0,54.192.0,81.228.0"}
P.entries["quest:1072"] = {n="Ein alter Kollege",s="Im Steinkrallengebirge sucht Gaxim Rostknirsch Brennstoff für eine mächtige Vorrichtung. Er schickt Euch über das Meer nach Eisenschmiede, wo sein alter Bekannter Lomac Ritzeldreh den gefährlichen Sprengstoff Nitromirglyceronium herstellen kann.",h="Im Steinkrallengebirge sucht Gaxim Rostknirsch Brennstoff für eine mächtige Vorrichtung.",kw={"sprengstoffe","gaxim rostknirsch","eisenschmiede","lomac ritzeldreh","ng-5","nitromirglyceronium","steinkrallengebirge","tüftlerstadt"},ang={["faction:Alliance"]="Als Abenteurer der Allianz reist Ihr quer über einen Kontinent, von Kalimdors umkämpften Felsklippen in die Sicherheit von Eisenschmiede.",["profession:Engineering"]="Als Ingenieur könnt Ihr Gaxims und Lomacs Streben nach maximaler Feuerkraft trotz der gefährlichen Logistik nachvollziehen.",["race:Gnome"]="Als Gnom kennt Ihr die weitreichenden Auswirkungen gelehrter Verbindungen, exzentrischer Rivalitäten und explosiver Gemische, die gefährlich instabil werden können."},sec={{t="Eine hochexplosive Rezeptur",b="Gaxim Rostknirsch plant im Steinkrallengebirge sein bisher kühnstes Ingenieursprojekt. Ein Mechanismus dieser Größenordnung braucht stärkeren Brennstoff als gewöhnliches Schießpulver oder Rohöl. Er benötigt Nitromirglyceronium, auch NG-5 genannt. Dieses explosive Gemisch ist stark genug, um Zerstörung zu garantieren, wenn alles nach Plan verläuft."},{t="Verbindungen nach Tüftlerstadt",b="Lomac Ritzeldreh ist der Einzige, den Gaxim kennt, der NG-5 veredeln kann. Sein alter Bekannter lebt weit im Osten in Tüftlerstadt, dem Gnomenviertel tief im Inneren von Eisenschmiede. Als Gaxims Bote tretet Ihr die lange Reise an. Lomac empfängt Euch mit Misstrauen und paranoiden Fragen."}},faq={{q="Wer vergibt die Quest Ein alter Kollege?",a="Gaxim Rostknirsch, ein Gnomeningenieur im Steinkrallengebirge, schickt Euch nach Eisenschmiede.",al={"questgeber","wer startet ein alter kollege","gaxim quest"}},{q="Wo finde ich Lomac Ritzeldreh?",a="Lomac Ritzeldreh lebt in Tüftlerstadt, dem Gnomenviertel im Osten von Eisenschmiede.",al={"wo ist lomac","lomac ritzeldreh fundort","eisenschmiede lomac"}},{q="Was ist Nitromirglyceronium?",a="Nitromirglyceronium, oder NG-5, ist ein äußerst instabiler chemischer Sprengstoff, den Lomac Ritzeldreh herstellen kann. Gaxim Rostknirsch will ihn für seine mächtigen Vorrichtungen.",al={"was ist ng-5","nitromirglyceronium","ng 5"}},{q="Warum schickt mich Gaxim den ganzen Weg nach Eisenschmiede?",a="Gaxim sagt, Lomac Ritzeldreh sei der Einzige, der die spezielle NG-5-Verbindung herstellen kann, die seine experimentelle Vorrichtung als Brennstoff benötigt.",al={"warum nach eisenschmiede reisen","warum lomac","warum nach tüftlerstadt gehen"}},{q="Was geschieht, nachdem ich Lomac Ritzeldreh gefunden habe?",a="Nachdem Ihr Gaxims Bitte bestätigt habt, gibt Euch der misstrauische Lomac die Quest Ineptitude + Chemicals = Fun. Dafür werden gefährliche Reagenzien benötigt, um das Gemisch anzurühren.",al={"nächste quest","was kommt nach ein alter kollege","folgequest"}},{q="Welche Fraktion kann diese Aufgabe übernehmen?",a="Nur Abenteurer der Allianz können diese Arbeit übernehmen. Sie beginnt beim Allianzgnom Gaxim im Steinkrallengebirge und führt nach Eisenschmiede, der Hauptstadt der Allianz.",al={"nur für die allianz","hordenversion","kann die horde das machen"}}},fx={bce9e2b8={q="Warum benötigt Gaxim Rostknirsch Euch, anstatt selbst nach Eisenschmiede zu gehen?",a="Gaxim Rostknirsch ist im Steinkrallengebirge damit beschäftigt, die taktische Platzierung für seine experimentellen Geräte zu erkunden und vorzubereiten. Da die Herstellung des hochwertigen Sprengstoffs Nitromirglyceronium einen langen Rückweg über das Meer zur Tüftlerstadt in Eisenschmiede erfordert, verlässt er sich auf einen fähigen Reisenden, der die Laufarbeit erledigt, während er vor Ort bleibt, um den Einsatz vorzubereiten.",al={"warum benötigt gaxim mich","warum einen abenteurer nach eisenschmiede senden","warum kann gaxim nicht selbst nach lomac gehen"}}},fp="16,218,17.312.0,22.269.0,37.87.0,33.77.0,28.151.0,48.125.0,43.145.0,38.150.0"}
P.entries["quest:1073"] = {n="Stümperhaftigkeit + Chemikalien = Riesenspaß!",s="Im Steinkrallengebirge sucht Gaxim Rostknirsch nach einem mächtigen Mittel gegen die Venture Company. Er bittet Euch, über das Meer nach Eisenschmiede zu reisen, wo Lomac Ritzeldreh Nitromirglyceronium brauen wird, wenn Ihr die nötigen alchemistischen Reagenzien mitbringt.",h="Im Steinkrallengebirge sucht Gaxim Rostknirsch nach einem mächtigen Mittel gegen die Venture Company.",kw={"elixier der geringen seelenstärke","gaxim rostknirsch","eisenschmiede","lomac ritzeldreh","manatrank","nitromirglyceronium","steinkrallengebirge","venture company"},ang={["faction:Alliance"]="Als Reisender der Allianz wisst Ihr, wie der lange Weg vom Steinkrallengebirge nach Eisenschmiede die Versorgung abgelegener Außenposten im feindseligen Kalimdor belastet.",["profession:Engineering"]="Als Ingenieur wisst Ihr, dass Alchemie in Verbindung mit Ingenieurskunst größere Zerstörung anrichten kann, wenn gewöhnliches Sprengpulver am Stahl der Venture Company scheitert.",["race:Gnome"]="Als Gnom erkennt Ihr in Lomac die wilde Seite gnomischen Erfindungsgeistes. Chemische Ausbeute und Theorie sind ihm wichtiger als Sicherheit oder diplomatische Vorsicht."},sec={{t="Eine instabile Lösung",b="Gaxim Rostknirsch braucht starke Sprengstoffe für seine beste Vorrichtung gegen die Venture Company. Er ist hoch oben in den zerklüfteten Pässen des Steinkrallengebirges stationiert, weit entfernt von seinem ehemaligen Kollegen Lomac Ritzeldreh in Eisenschmiede. Lomac erschuf Nitromirglyceronium, ein Gebräu von solcher Instabilität und Zerstörungskraft, dass ihn der Gedanke an seine Verwendung zum Lachen bringt, ganz gleich, wen es zerreißt."},{t="Tränke für die Pyrotechnik",b="Lomac will goblinische Maschinen in Stücke fliegen sehen, und vielleicht auch Euch. Doch in seiner Werkstatt in Eisenschmiede ist das Nitromirglyceronium ausgegangen. Bevor er eine weitere Ladung braut, bittet er Euch um Geringe Manatränke und Elixiere der geringen Seelenstärke. Diese Tränke liefern die Rohreagenzien für sein Gemisch, und beim Beschaffen kann Lomac beurteilen, ob Ihr überhaupt Respekt vor der Alchemie habt."}},faq={{q="Wer ist Lomac Ritzeldreh?",a="Lomac Ritzeldreh ist ein exzentrischer gnomischer Alchemist und Tüftler in Eisenschmiede, der Hauptstadt der Zwerge. Er arbeitete einst mit Gaxim Rostknirsch zusammen und erschuf den instabilen Sprengstoff Nitromirglyceronium.",al={"lomac ritzeldreh","wer ist lomac","gnom in eisenschmiede"}},{q="Warum will Lomac Tränke statt gewöhnlicher Ingenieursbauteile?",a="Lomac verbindet Alchemie mit seinem mechanischen Wissen, um instabile Reaktionen hervorzurufen. Geringe Manatränke liefern magische Energie, während Elixiere der geringen Seelenstärke stabilisierende Körpersäfte beisteuern. Beide sind Grundreagenzien für sein Nitromirglyceronium-Gemisch.",al={"warum tränke","alchemistische zutaten","warum manatränke"}},{q="Warum schickt man dafür einen Abenteurer den ganzen Weg nach Eisenschmiede?",a="Gaxim Rostknirsch ist in der Wildnis des Steinkrallengebirges abgeschnitten, ohne große Industrieanlagen oder chemische Werkstätten in der Nähe. Lomac Ritzeldreh in Eisenschmiede ist der einzige Bekannte, dem Gaxim genug vertraut oder den er genug fürchtet, um Sprengstoff für seine beste Vorrichtung zu liefern.",al={"warum eisenschmiede","warum so weit reisen","gaxim nach eisenschmiede"}},{q="Was ist Nitromirglyceronium?",a="Nitromirglyceronium ist Lomac Ritzeldrehs explosives chemisches Gebräu, bekannt für seine Instabilität. Lomac nennt es seine größte Schöpfung.",al={"nitromirglyceronium","was ist der sprengstoff","gnomenbombensaft"}},{q="Sorgt sich Lomac um die Venture Company oder den Wald?",a="Lomac kümmert sich weder um die Venture Company noch um den Wald. Er lacht über die Vorstellung, mit Sprengstoff Bäume zu retten, und will entweder Goblins oder den Boten in Stücke fliegen sehen.",al={"kümmert sich lomac um die natur","lomacs beweggründe"}},{q="Müsst Ihr Alchemist sein, um diese Aufgabe zu erfüllen?",a="Nein. Lomac spricht davon, Eure alchemistischen Fähigkeiten zu prüfen, doch er nimmt auch Reagenzien aus Tauschgeschäften, von Händlern oder anderen Handwerkern an, solange Ihr die Tränke bringt, die sein Rezept verlangt.",al={"alchemie nötig","alchemie erforderlich"}}},fx={["04ca68af"]={q="Warum möchte Lomac Ritzeldreh, dass dies erledigt wird?",a="Lomac schert sich wenig um die Venture Company, das Schicksal der Wälder im Steinkrallengebirge oder seinen alten Bekannten Gaxim Rostknirsch. Was ihn erfreut, ist das pure Chaos und explosives Potenzial. Er willigt ein, sein flüchtiges Nitromirglyceronium zu brauen, einfach nur aus dem perversen Vergnügen heraus, dabei zuzusehen, wie entweder Ihr oder die Goblins in winzige Stücke explodieren, vorausgesetzt, Ihr liefert die Reagenzien, um seinen Vorrat aufzufüllen.",al={"motiv von lomac ritzeldreh","warum lomac helfen","warum nitromirglyceronium herstellen"}},["23e9865b"]={q="Wozu dient der Schwache Manatrank?",a="Die Schwachen Manatränke sind essenzielle flüssige Reagenzien in Lomacs instabiler Mixtur. Zusammen mit den Stärkungselixieren dient ihre magische Energie als lebenswichtiger Katalysator, der benötigt wird, um eine frische Charge Nitromirglyceronium zu synthetisieren, seine flüchtige und stolze alchemistische Erfindung.",al={"verwendung von schwachem manatrank","warum schwacher manatrank","manatrank nitromirglyceronium"}},["2bdc95b5"]={q="Wozu dient das Elixier der schwachen Seelenstärke?",a="Lomac benötigt die Elixiere der schwachen Seelenstärke als Schlüsselkomponenten für das Brauen von Nitromirglyceronium. In seinem exzentrischen chemischen Rezept bildet die stärkende Mischung einen Teil der reaktiven Basis, die zur Herstellung der explosiven Verbindung erforderlich ist.",al={"verwendung von elixier der schwachen seelenstärke","warum elixier der schwachen seelenstärke","stärkungselixier nitromirglyceronium"}},ba2add0a={q="Warum muss Lomac, dass Ihr die Tränke holt, anstatt sie selbst zu besorgen?",a="Lomac hat keine Vorräte mehr und verspürt keine Dringlichkeit, Euch oder Gaxim auf eigene Kosten zu helfen. Indem er Euch dazu bringt, die Zutaten selbst zu besorgen oder zu brauen, zwingt er Euch dazu, Euren Einfallsreichtum und Eure alchemistische Kompetenz zu beweisen, bevor er Euch seine geschätzte, gefährliche Kreation anvertraut.",al={"warum braucht mich lomac","warum muss ich die tränke holen","warum kann lomac seine tränke nicht selbst holen"}}},fp="28,241,19.370.0,24.369.0,23.190.0,66.247.0,57.250.0,28.129.0,57.181.0,53.182.0"}
P.entries["quest:1074"] = {n="Stümperhaftigkeit + Chemikalien = Riesenspaß!",s="Im Steinkrallengebirge schickt Lomac Ritzeldreh flüchtiges NG-5 zu Gaxim Rostknirsch. Die Chemikalie kann mit Dynamit beladene Wagen entzünden und Feinde weglocken, während Streitkräfte der Allianz ihre Ziele in den umkämpften Felsklüften verfolgen.",h="Im Steinkrallengebirge schickt Lomac Ritzeldreh flüchtiges NG-5 zu Gaxim Rostknirsch.",kw={"dynamit","ingenieurskunst","gaxim rostknirsch","gnom","lomac ritzeldreh","ng-5","nitromirglyceronium","steinkrallengebirge"},ang={["faction:Alliance"]="Das Steinkrallengebirge ist umkämpft, und eine gewaltige Explosion verschafft den Einsatzkräften der Allianz Spielraum, um ihre Ziele zu verfolgen.",["profession:Engineering"]="Der Umgang mit NG-5 erfordert Vorsicht mit flüchtigen Chemikalien, um eine vorzeitige Detonation zu vermeiden.",["race:Gnome"]="Gnomischer Ehrgeiz setzt Nitromirglyceronium ein, um zur Ablenkung Wagen voller Sprengstoff zu entzünden."},sec={{t="Eine flüchtige Lieferung",b="Lomac Ritzeldreh gibt Euch Nitromirglyceronium, auch NG-5 genannt, eine instabile Verbindung aus gnomischer Ingenieurskunst. Er warnt Euch, vorsichtig damit umzugehen. Bei unsachgemäßer Handhabung könnte es Euch auf dem Rückweg zu Gaxim Rostknirsch in Stücke reißen."},{t="Ein Rezept für Ablenkung",b="Sobald Gaxim Rostknirsch den Kanister unversehrt erhält, erklärt er seinen Plan. NG-5 kann ganze Wagen voller Dynamit entzünden. Gaxim will eine gewaltige Explosion auslösen und Chaos im Steinkrallengebirge stiften, um Feinde wegzulocken, während die Allianz ihre Ziele in der Region verfolgt."}},faq={{q="Was ist NG-5?",a="NG-5, kurz für Nitromirglyceronium, ist eine flüchtige chemische Verbindung, die Lomac Ritzeldreh herstellt. Sie wird benötigt, um schwere Sprengladungen zu zünden.",al={"was ist nitromirglyceronium","ng-5","lomacs übergabe"}},{q="Wer ist Gaxim Rostknirsch?",a="Gaxim Rostknirsch ist ein gnomischer Magier im Steinkrallengebirge. Er leitet die Sprengarbeiten der Allianz und nutzt Explosionen, um Bedrohungen in der Region abzulenken.",al={"gaxim","wer ist gaxim rostknirsch"}},{q="Wer ist Lomac Ritzeldreh?",a="Lomac Ritzeldreh ist ein Ingenieur und Mitarbeiter von Gaxim Rostknirsch. Er stellt die gefährliche Verbindung NG-5 her und übergibt sie Kurieren.",al={"lomac","wer ist lomac ritzeldreh"}},{q="Warum braucht Gaxim so viel Sprengkraft?",a="Gaxim hat mehrere mit Dynamit beladene Wagen bereitgestellt. NG-5 kann sie mit einer einzigen Explosion zünden und so ein wirkungsvolles Ablenkungsmanöver schaffen.",al={"warum wagen voller dynamit","gaxims plan","warum die explosion"}},{q="Ist der Transport der Chemikalie gefährlich?",a="Ja. Lomac warnt, dass NG-5 instabil ist und bei unsachgemäßer Handhabung detonieren könnte. Geht auf dem Weg zu Gaxim vorsichtig damit um.",al={"explodiert ng5","ist ng-5 sicher"}},{q="Wohin führt diese Lieferung?",a="Die Lieferung endet an Gaxim Rostknirschs Posten in den Pässen des Steinkrallengebirges.",al={"wo ist gaxim","lage des steinkrallengebirges"}}},fx={cbbf8960={q="Warum gibt Euch Lomac Ritzeldreh den NG-5?",a="Lomac erfüllt eine Anfrage seines Mitarbeiters Gaxim Rostknirsch und stellt das flüchtige Nitromirglyceronium wie verlangt zur Verfügung. Er stellt keine neugierigen Fragen – wenn Ihr wirklich ein Verbündeter von Gaxim seid, sendet er seine Grüße, und wenn Ihr ein Betrüger seid, ist er zufrieden damit, Euch von der explosiven Verbindung in Stücke sprengen zu lassen.",al={"warum hilft lomac","motiv von lomac ritzeldreh","warum ng-5 geben"}}},fp="28,223,19.225.0,24.266.1,13.134.0,24.150.0,23.131.0,44.124.0,39.113.0,36.87.0"}
P.entries["quest:1075"] = {n="Eine Rolle von Mauren",s="Gaxim Rostknirsch sucht einen Zauber von Collin Mauren in Sturmwinds Magierviertel. Er braucht arkane Hilfe, um seine NG-5-Sprengstoffe aus der Ferne zu zünden.",h="Gaxim Rostknirsch sucht einen Zauber von Collin Mauren in Sturmwinds Magierviertel.",kw={"collin mauren","devils in westfall","sprengstoffe","gaxim rostknirsch","das magierviertel","ng-5","fernzünder","sturmwind"},ang={["class:Mage"]="Als Magier wisst Ihr, dass die Kirin Tor und Sturmwinds arkane Zauberwirker mit Ingenieuren zusammenarbeiten. Sie wenden Hervorrufung und Transmutation auf mechanische Probleme an.",["faction:Alliance"]="Als Mitglied der Allianz seht Ihr gnomische Tüftler mit den menschlichen Zauberern zusammenarbeiten, die in Sturmwinds Magierviertel studieren.",["profession:Engineering"]="Als Ingenieur wisst Ihr, dass instabiles Schwarzpulver und arkane Katalysatoren Probleme wie die Fernzündung lösen können.",["race:Gnome"]="Als Gnom scheut Ihr Euch nie, Technik mit Zauberei zu verbinden, wenn dies eine noch verheerendere Explosion aus bequemer Entfernung verspricht."},sec={{t="Ein Funke über die Ferne",b="Mechanische Zünder geben Gaxim nicht die Kontrolle, die er braucht. Er will die Ladungen auf Knopfdruck zünden und dabei außerhalb der Explosion bleiben. Arkane Magie könnte einen Befehl von seiner Hand zu den Sprengstoffen tragen."},{t="Verbindung zum Magierviertel",b="Collin Mauren ist ein menschlicher Zauberwirker mit praktischen Kenntnissen der arkanen Magie. Er überlegt, wie sich die Zündung einer Sprengladung an einen Befehl aus der Ferne binden lässt. Dann beginnt er mit der Beschwörung, die Gaxim für sein gefährliches Projekt braucht."}},faq={{q="Wer schickt mich zu Collin Mauren?",a="Gaxim Rostknirsch schickt Euch zu Collin Mauren. Er braucht eine arkane Formel von seinem menschlichen Bekannten, um einen Fernzünder fertigzustellen.",al={"questgeber","wer vergibt eine rolle von mauren","gaxims quest"}},{q="Wo ist Collin Mauren zu finden?",a="Collin Mauren befindet sich im Magierviertel von Sturmwind. Sucht ihn unter den Lehrern, Lehrlingen und arkanen Forschern bei den Türmen und Läden des Viertels.",al={"collin maurens standort","wo ist collin mauren","mauren finden"}},{q="Warum braucht Gaxim einen Zauber für einen Sprengsatz?",a="Gaxim will seine NG-5-Sprengstoffe auf Knopfdruck aus sicherer Entfernung zünden. Er sucht Maurens arkanes Wissen für eine sofortige Fernzündung, da mechanische Mittel über große Entfernungen umständlich oder unzuverlässig sein können.",al={"warum magie für bomben","hintergrund zur fernzündung","warum einen magier aufsuchen"}},{q="Was ist NG-5?",a="NG-5, auch Nitromirglyceronium genannt, ist ein instabiler Sprengstoff, den Gaxims alter Kollege Lomac Ritzeldreh in Eisenschmiede zusammenbraut. Gaxim braucht ein Fernzündsystem, damit die Person, die es auslöst, weit außerhalb des Explosionsradius bleiben kann.",al={"ng-5","was ist ng5","gaxims sprengstoff"}},{q="Was folgt nach dem Gespräch mit Collin Mauren?",a="Nachdem Collin Mauren über die Bitte um einen Fernzündzauber nachgedacht hat, bittet er Euch in „Devils in Westfall“, ihm in Westfall zu helfen.",al={"nächste quest","was folgt auf eine rolle von mauren","collin maurens folgequest"}},{q="Ist Collin Mauren ein Gnom oder ein Mensch?",a="Collin Mauren ist ein menschlicher Magier. Gaxim sagt, Mauren sollte in Sturmwinds Menschenmengen leicht zu erkennen sein, weil er ein Mensch ist.",al={"collin maurens volk","welchem volk gehört mauren an","ist mauren ein mensch"}}},fp="20,141,24.202.0,27.215.0,30.129.0,33.162.0,52.219.0,17.222.0,50.132.0,36.114.0"}
P.entries["quest:1076"] = {n="Teufel in Westfall",s="Staubteufel durchstreifen Westfall, und Collin Mauren braucht ihre Überreste für einen Zauber. Der Magier aus dem Magierviertel hilft Gaxim Rostknirsch bei einem ungewöhnlichen Experiment. Ihre Arbeit erfordert eine Nachrichtenrolle, und der Staub enthält, was Mauren braucht, um sie zu verzaubern.",h="Staubteufel durchstreifen Westfall, und Collin Mauren braucht ihre Überreste für einen Zauber.",kw={"collin mauren","staubteufel","staubteufeltrümmer","gaxim rostknirsch","das magierviertel","verständigungszauber","schriftrolle","sturmwind","westfall"},ang={["class:Mage"]="Als Magier seht Ihr, wie Verzauberkunst wilde Elementarresonanz nutzen kann, um einen komplexen Verständigungszauber in eine Schriftrolle zu binden.",["faction:Alliance"]="Als Reisender der Allianz zieht Ihr von Sturmwinds Türmen zu Westfalls vernachlässigten Feldern, wo das Grenzland des Königreichs in Trümmern liegt.",["profession:Engineering"]="Als Ingenieur seht Ihr, wie Gaxim Rostknirsch bei seiner Arbeit auf arkane Schriftrollenkunst zurückgreift, um ein Verständigungsproblem zu lösen."},sec={{t="Die Komponenten eines Boten",b="Collin Mauren bereitet eine Nachrichtenrolle für Gaxim Rostknirsch vor. Der Magier hilft dem Tüftler bei einem ungewöhnlichen Vorhaben, doch der Zauber braucht mehr als Tinte und Pergament. Staubteufel durchstreifen Westfall, und in ihrem Inneren wirbelt Elementarmagie. Ihre Überreste liefern das flüchtige Medium, das Mauren braucht, um Gaxims Zauber an Pergament zu binden."},{t="Die elementare Ödnis",b="Westfall war einst die fruchtbare Kornkammer von Sturmwind. Dürre, Banditentum und Vernachlässigung haben seine Felder ausgedörrt und verwildert zurückgelassen. Staubteufel durchstreifen das Land und bedrohen Reisende und einsame Siedler. Ihre Rückstände enthalten die gebündelte Elementaressenz, die Mauren braucht, um die Verzauberung zu vollenden."}},faq={{q="Wer ist Collin Mauren?",a="Collin Mauren ist ein menschlicher Magier im Magierviertel von Sturmwind. Er arbeitet mit Zauberwirkern in der Stadt zusammen und hilft gelegentlich auswärtigen Forschern wie Gaxim Rostknirsch, verzauberte Schriftrollen und arkane Komponenten vorzubereiten.",al={"collin mauren","wer ist der questgeber","magier in sturmwind"}},{q="Warum braucht Collin Mauren Staubteufeltrümmer?",a="Collin Mauren braucht Staubteufeltrümmer, um eine Nachrichtenrolle für Gaxim Rostknirsch zu verzaubern. Die Überreste enthalten Elementarenergie, die dabei hilft, den Zauber an Pergament zu binden.",al={"warum staubteufeltrümmer","wozu dienen staubteufeltrümmer","warum nach westfall"}},{q="Wo findet man Staubteufel?",a="Staubteufel durchstreifen Westfalls trockene Ebenen und karge Felder, besonders die staubigen Landstriche zwischen vernachlässigten Gehöften südlich der Straße zur Späherkuppe.",al={"fundort der staubteufel","wo sind staubteufel","staubteufel in westfall"}},{q="Wer ist Gaxim Rostknirsch?",a="Gaxim Rostknirsch ist ein ehrgeiziger gnomischer Erfinder, der an esoterischen Ingenieursprojekten arbeitet. Collin Mauren hilft ihm, verzauberte Schriftrollen für seine Experimente vorzubereiten.",al={"gaxim","gaxim rostknirsch","wer ist gaxim"}},{q="Was geschieht, nachdem die Trümmer zu Mauren gebracht wurden?",a="Mit den Trümmern vollendet Collin Mauren die Nachrichtenrolle und bittet Euch, sie zu Gaxim Rostknirsch zu bringen, damit der Erfinder seine Experimente fortsetzen kann.",al={"questbelohnung","what comes next","nach teufel in westfall"}},{q="Sind Staubteufel magische oder natürliche Wesen?",a="Staubteufel sind niedere Luftelementare, die als lebende Wirbelwinde aus Sand und Staub erscheinen. Sie gedeihen in Westfalls trockener, ungezähmter Landschaft.",al={"sind staubteufel elementare","geschichte der staubteufel"}}},fx={b0d4cd5a={q="Wofür werden Staubteufeltrümmer verwendet?",a="Collin Mauren benötigt die Überreste von Staubteufeltrümmern als entscheidendes Reagenz, um eine spezielle Schriftrolle zu verzaubern. Gaxim Rostknirsch benötigt einen Nachrichten-Zauber für seine seltsamen Experimente, und das aus der Wirbelsturmkreatur gewonnene Elementarmaterial ermöglicht es Mauren, die magische Verzauberung auf das Pergament zu bannen.",al={"verwendung von staubteufeltrümmern","wofür sind trümmer","warum staubteufeltrümmer"}},["9b2ec5a3"]={q="Was sind die Staubteufel, die Ihr jagt?",a="Staubteufel sind chaotische Luftelementare, die durch die kargen Ebenen und das Ackerland von Westfall streifen. Aufgewirbelt durch die turbulenten Winde und die wilde Magie in der gesamten Region, stürzen sich diese Miniaturwirbelstürme auf jeden Reisenden, der ihren Weg kreuzt, was sie zu einer tödlichen Gefahr für die örtlichen Bauern und Wanderer gleichermaßen macht.",al={"was sind staubteufel","ziele der staubteufel","wer sind die staubteufel"}}},fp="18,250,24.333.0,20.278.0,21.211.0,46.163.0,28.150.0,24.160.0,49.152.0,45.139.0"}
P.entries["quest:1077"] = {n="Speziallieferung für Gaxim",s="Gaxim Rostknirsch wartet im Steinkrallengebirge auf eine verzauberte Schriftrolle aus Sturmwind. Ihre Magie könnte ihm ermöglichen, Sprengstoff aus der Ferne zu zünden und die Abholzung durch die Venture Company zu behindern.",h="Gaxim Rostknirsch wartet im Steinkrallengebirge auf eine verzauberte Schriftrolle aus Sturmwind.",kw={"collin mauren","gaxim rostknirsch","ng-5","ferngezündeter sprengstoff","rolle der nachrichtenübermittlung","steinkrallengebirge","venture co"},ang={["class:Mage"]="Collin Mauren zeigt, wie findige Tüftler eine einfache Pergamentverzauberung in ein funktionierendes arkanes Relais verwandeln können.",["faction:Alliance"]="Als Mitglied der Allianz erlebt Ihr die Verbindungen zwischen Sturmwind und entlegenen Außenposten, die sich der industriellen Ausbeutung in Kalimdor widersetzen.",["profession:Engineering"]="Gaxims Plan verbindet gnomische Ingenieurskunst mit Zauberei. Hochexplosiver NG-5-Sprengstoff trifft auf arkane Zünder."},sec={{t="Arkane Lieferungen",b="Gaxim Rostknirsch versucht, die zerstörerischen Arbeiten der Venture Company im Steinkrallengebirge zu behindern. Er hat ein explosives Gemisch namens NG-5 hergestellt, kann es aber nicht zuverlässig aus der Ferne zünden. Also suchte er Hilfe jenseits des großen Meeres. Im Magierviertel von Sturmwind hat Collin Mauren eine verzauberte Rolle der Nachrichtenübermittlung für ihn angefertigt."},{t="Ablenkung aus der Ferne",b="Gaxim Rostknirsch plant, die Magie der Rolle der Nachrichtenübermittlung an sein instabiles NG-5-Gemisch zu binden. Die Rolle kann Nachrichten über weite Entfernungen übermitteln, und diese Kraft kann den Sprengstoff aus der Ferne zünden. Gaxim will mit der Explosion ein verheerendes Ablenkungsmanöver auslösen. Dann könnten Einsatzkräfte unbemerkt in das Lager der Venture Company eindringen."}},faq={{q="Wofür wird die Rolle der Nachrichtenübermittlung verwendet?",a="Die Rolle der Nachrichtenübermittlung trägt Worte über weite Entfernungen. Gaxim Rostknirsch kann ihre Magie an NG-5 binden und sie als Fernzünder nutzen, um Sprengstoff aus sicherer Entfernung zu zünden.",al={"warum rolle der nachrichtenübermittlung","was bewirkt die schriftrolle","zweck der rolle der nachrichtenübermittlung"}},{q="Wer ist Collin Mauren?",a="Collin Mauren ist ein Zauberer der Allianz im Magierviertel von Sturmwind. Er kümmert sich um arkane Angelegenheiten und fertigt die verzauberte Schriftrolle an, die Gaxim im Steinkrallengebirge benötigt.",al={"collin maurens geschichte","wer ist collin"}},{q="Warum sabotiert Gaxim Rostknirsch die Venture Company?",a="Die Venture Company holzt die unberührten Wälder des Steinkrallengebirges rücksichtslos ab. Gaxim will die Abholzung verlangsamen, indem er Chaos stiftet, ihre Anlagen zerstört und ihre Konstruktionspläne und Korrespondenz stiehlt.",al={"warum venture co angreifen","gaxims beweggründe","venture co steinkrallengebirge"}},{q="Wohin führt diese Lieferung den Abenteurer?",a="Ihr reist von Sturmwind über das Meer zum Lager der Allianz zwischen den schroffen Felsen des Steinkrallengebirges auf Kalimdor.",al={"lieferziel","wo ist gaxim","lage des steinkrallengebirges"}},{q="Was geschieht nach der Übergabe der Schriftrolle?",a="Mit der Schriftrolle und NG-5 bereitet Gaxim ein ferngezündetes explosives Ablenkungsmanöver vor. Es macht den Weg frei, damit eine Einsatzkraft in die Anlagen an der Scherwindklippe eindringen und Schreiben zur Abholzung sowie Baupläne beschaffen kann.",al={"nächste quest","was nach der lieferung","venture co ablenkung"}}},fx={["89640f85"]={q="Warum möchte Collin Mauren, dass dies erledigt wird?",a="Collin Mauren agiert als hilfreicher arkaner Kollege und Freund von Gaxim Rostknirsch. Während Collin sicher in Sturmwind bleibt und seine magischen Studien betreibt, ist er von Gaxims gewagtem Plan gegen die Venture Company in Kalimdor fasziniert und stellt gerne den notwendigen Zauber zur Verfügung, da er sich darauf freut, alles über das Abenteuer zu hören, sobald es abgeschlossen ist.",al={"collin mauren beweggrund","warum hilft collin gaxim","collin mauren warum schriftrolle senden"}}},fp="26,177,17.330.0,20.321.1,41.181.0,21.154.0,55.232.0,45.120.0,43.197.1"}
P.entries["quest:1078"] = {n="Suche für Mauren",s="In Sturmwind bittet Collin Mauren Reisende auf dem Weg nach Kalimdor, seltene Basiliskenschuppen mitzubringen. Er will Schuppen aus dem Verbrannten Tal im Steinkrallengebirge, zu Staub zermahlen für seine Zauberkunst.",h="In Sturmwind bittet Collin Mauren Reisende auf dem Weg nach Kalimdor, seltene Basiliskenschuppen mitzubringen.",kw={"basiliskenschuppen","das verbrannte tal","collin mauren","kristallisierte schuppen","das magierviertel","suche für mauren","steinkrallengebirge","sturmwind"},ang={["class:Mage"]="Als Magier wisst Ihr, dass das Sammeln seltener Reagenzien für andere Zauberer die arkane Forschung unterstützt. Exotische magische Wildtiere können liefern, was zur Entwicklung neuer Zauberformeln benötigt wird.",["faction:Alliance"]="Als Reisender der Allianz seht Ihr, wie weit Sturmwinds Interessen und Versorgungslinien in Kalimdors wilde Gebiete hineinreichen."},sec={{t="Die sonderbaren Reagenzien eines Magiers",b="Im Magierviertel von Sturmwind lauscht der Zauberer Collin Mauren den Geschichten umherziehender Abenteurer. Er hat gehört, dass Reisende tief nach Kalimdor vordringen, wo das Steinkrallengebirge jene anzieht, die wilde Wyvern, widerspenstige Elementare oder Geschäfte und Auseinandersetzungen mit der Venture Company suchen. Mauren sucht weder Reichtum noch Ruhm. Er will erfahren, welche seltenen Naturwunder in den unwirtlichsten Winkeln der Region überleben."},{t="Die gläsernen Bestien des Tals",b="Tief im Steinkrallengebirge liegt das Verbrannte Tal, ein von Asche ersticktes Becken, gezeichnet von den Verwüstungen der Venture Company. Maurens Studien zufolge lebte dort einst eine eigentümliche Basiliskenart. Zu feinem Pulver zermahlen, können ihre Schuppen als Katalysator für spezielle arkane Zauber dienen, die er entwickelt hat. Mauren weiß nicht, ob die Basilisken die drastische Verwandlung des Tals überlebt haben. Also bittet er Entdecker, frische kristallisierte Schuppen mitzubringen und herauszufinden, ob die Art fortbesteht."}},faq={{q="Wer ist Collin Mauren?",a="Collin Mauren ist ein Zauberer im Magierviertel von Sturmwind, der arkane Zauberkunst erforscht und seltene Reagenzien aus fernen Ländern sucht.",al={"collin mauren","wer vergibt suche für mauren","mauren sturmwind"}},{q="Warum braucht Collin Mauren Basiliskenschuppen?",a="Mauren zermahlt kristallisierte Basiliskenschuppen zu feinem Staub, der als Katalysator für die von ihm entwickelten Zauber dient.",al={"warum schuppen","wofür sind schuppen","verwendung kristallisierter schuppen"}},{q="Wo liegt das Verbrannte Tal?",a="Das Verbrannte Tal ist ein verwüstetes Becken im Südwesten des Steinkrallengebirges auf Kalimdor.",al={"wo ist das verbrannte tal","verbranntes tal finden","lage des verbrannten tals"}},{q="Warum ist das Verbrannte Tal verbrannt?",a="Die Goblins der Venture Company verwüsteten das Verbrannte Tal. Ihre Zerstörung erzürnte die Geister des Tals und setzte Elementare frei. Der Boden liegt geschwärzt und schwelend da, und widerstandsfähige, entstellte Bestien streifen darüber.",al={"was geschah mit dem verbrannten tal","feuer im verbrannten tal","zerstörung des verbrannten tals"}},{q="Welche Kreaturen lassen die für diese Aufgabe benötigten Schuppen fallen?",a="Basilisken im Verbrannten Tal im Steinkrallengebirge haben die Schuppen, die Mauren sucht.",al={"welche basilisken","wer lässt kristallisierte schuppen fallen","gegner mit schuppen"}},{q="Warum dafür einen Abenteurer den ganzen Weg über das Meer schicken?",a="Mauren braucht die kristallinen Eigenschaften der Basilisken, die im Verbrannten Tal heimisch sind. Die Überquerung des großen Meeres ist gefährlich, also bittet er erfahrene Reisende, die ohnehin nach Kalimdor unterwegs sind.",al={"warum kalimdor","warum schuppen aus dem steinkrallengebirge"}}},fx={ae0c8dc0={q="Warum benötigt Collin Mauren die Basilisken-Schuppen?",a="Collin Mauren ist ein erfinderischer Magier aus Sturmwind, der seine eigenen, originellen Zauber entwickelt. Er hat herausgefunden, dass die kristallisierten Schuppen von Basilisken aus dem verbrannten Tal im Steinkrallengebirge, wenn sie zu feinem Staub zermahlen werden, ein ideales magisches Reagenz darstellen. Da er in der Stadt bleibt, um arkane Studien zu betreiben, ist er auf reisende Abenteurer angewiesen, um seinen seltenen Vorrat aufzustocken.",al={"collin mauren beweggrund","warum benötigt mauren schuppen","warum schuppen für mauren sammeln"}},c10c105c={q="Welche Kreaturen jagt Ihr im verbrannten Tal?",a="Ihr werdet in die versengten Tiefen des verbrannten Tals geschickt, um die dort heimischen Basilisken aufzuspüren, die inmitten der Asche und der elementaren Ruinen hausen. Mauren erinnert sich aus früheren Berichten an ihre einzigartigen, mit Kristallen überzogenen Häute, ist sich jedoch unsicher, ob die widerstandsfähigen Bestien das katastrophale Verbrennen des Tals überlebt haben.",al={"welche basilisken im verbrannten tal","gegen wen kämpfe ich für mauren","ziele im steinkrallengebirge basilisken"}}},fp="20,180,25.395.0,29.447.0,21.127.0,44.92.0,34.85.0,32.207.0,52.83.0,59.174.0"}
P.entries["quest:1079"] = {n="Geheimoperation Alpha",s="Agenten der Allianz gehen im Steinkrallengebirge gegen die Venture Company vor. Unter Gaxim Rostknirsch dringen sie in das Sägewerk an der Scherwindklippe ein, um dessen technische Baupläne zu bergen.",h="Agenten der Allianz gehen im Steinkrallengebirge gegen die Venture Company vor.",kw={"alpha","geheimoperation","felskesselsee","technische baupläne","gaxim rostknirsch","sägewerk","steinkrallengebirge","venture co","die scherwindklippe"},ang={["faction:Alliance"]="Als Mitglied der Allianz helft Ihr, in ganz Kalimdor Stützpunkte zu sichern und die industrielle Rohstoffgewinnung einzudämmen, um das taktische Gleichgewicht gegenüber rivalisierenden Mächten zu wahren, die in umkämpfte Wildnis vordringen.",["profession:Engineering"]="Die Baupläne enthüllen die grobschlächtigen Mechanismen mit hoher Verbrennungsleistung der Venture Company und geben Einblicke in industrielle Motorentechnik.",["race:Gnome"]="Als gnomischer Tüftler könnt Ihr Goblinbaupläne untersuchen, Schwächen in ihren Konstruktionen erkennen und Euch ihre gewinnbringenden mechanischen Kniffe aneignen.",["race:NightElf"]="Als Nachtelf seht Ihr, wie der Holzeinschlag der Venture Company an der Scherwindklippe die uralten Wälder des Steinkrallengebirges verwundet. Ihre Holzfällanlagen zu sabotieren, ist dringend notwendig."},sec={{t="Sabotage und Spionage",b="Von der Scherwindklippe aus leitet Gaxim Rostknirsch einen verdeckten Einsatz gegen den aggressiven Holzeinschlag der Venture Company. Goblinholzfäller schlagen südlich des Felskesselsees Holz. Zerstörung allein kann sie nicht aufhalten, also schickt Plan Alpha Agenten an den Holzfällern und Aufsehern vorbei, um die technischen Baupläne des Sägewerks zu entwenden."},{t="Konstruktionen entschlüsseln",b="Die Baupläne der Venture Company interessieren die Gnome aus Gründen, die über die Wälder der Nachtelfen hinausgehen. Sie zeigen, wie Goblinholzfäller, mechanische Schneidemaschinen und mechanisierte Transporter funktionieren. Ingenieure der Allianz können ihre Konstruktionsschwächen untersuchen, um künftige Unternehmungen zu zerschlagen. Sie können Goblinkonstruktionen auch für ihre eigenen Projekte in Eisenschmiede anpassen."}},faq={{q="Was ist das Hauptziel von Geheimoperation Alpha?",a="Bergt die technischen Baupläne der Venture Company aus ihrem Sägewerk an der Scherwindklippe, südlich des Felskesselsees. Sprengstoff gehört zum umfassenderen verdeckten Einsatz, doch der Erfolg hängt davon ab, die Baupläne zurückzubringen.",al={"was ist geheimoperation alpha","ziel der mission alpha","was will gaxim"}},{q="Wer vergibt die Quest Geheimoperation Alpha?",a="Gaxim Rostknirsch, ein gnomischer Tüftler der Allianz im Steinkrallengebirge, leitet die Sabotage gegen die Goblinindustrie.",al={"wer startet geheimoperation alpha","gaxim rostknirsch quest","questgeber geheimoperation"}},{q="Wo befinden sich die technischen Baupläne?",a="Die Venture Company Engineering Plans befinden sich im laufenden Sägewerk an der Scherwindklippe, südlich des Felskesselsees, bewacht von Goblinholzfällern.",al={"wo sind die pläne der venture co","fundort der technischen baupläne","scherwindklippe sägewerk baupläne"}},{q="Warum will Gaxim Rostknirsch die Baupläne der Venture Co.?",a="Gaxim will die Konstruktionsschwächen der goblinischen Holzfällmaschinen untersuchen. Ihre Schwächen können helfen, künftige Maschinen wirksamer zu sabotieren, und ihre nützlichen Konstruktionen können Geräte der Allianz verbessern.",al={"warum pläne der venture co stehlen","was macht gaxim mit den plänen","grund für geheimoperation alpha"}},{q="Geht es bei der Mission um bloße Zerstörung?",a="Nein. Gaxim sagt, der Erfolg hängt davon ab, die Baupläne unversehrt zu bergen, und nicht davon, wie viel Zerstörung die Agenten anrichten.",al={"sägewerk sprengen","maschinen zerstören","zerstörung als missionsziel"}},{q="Warum kämpft die Allianz hier gegen die Venture Company?",a="Die Venture Company rodet Wälder und verschmutzt das Land im Steinkrallengebirge. Agenten der Allianz stören ihre Industrie und schützen strategisch wichtiges Gebiet in Kalimdor.",al={"warum venture company im steinkrallengebirge bekämpfen","konflikt allianz venture co","krieg um holzeinschlag im steinkrallengebirge"}}},fx={f4c6420b={q="Wozu dienen die Ingenieurspläne der Venture Company?",a="Diese detaillierten Blaupausen umreißen die internen Mechanismen und den Aufbau der schweren Abholzungsmaschinen der Venture Company in der Scherwindklippe. Durch ihre Wiederbeschaffung zielt Gaxim Rostknirsch darauf ab, kritische Konstruktionsfehler in deren Ausrüstung aufzuspüren, um zukünftige Operationen zu sabotieren, während er gleichzeitig deren beste Konzepte stiehlt, um die Ingenieursinnovationen der Allianz zu verbessern.",al={"verwendung von ingenieursplänen der venture company","wofür sind die blaupausen","zweck der ingenieurspläne"}}},fp="18,185,22.296.0,19.326.0,47.212.0,39.113.0,40.146.0,58.196.0,46.113.0,54.151.0"}
P.entries["quest:1080"] = {n="Geheimoperation Beta",s="Im Steinkrallengebirge schickt Gaxim Rostknirsch einen Agenten in die Mine der Venture Company. Sprengstoff lockt die Goblins fort, während der Agent Briefe erbeutet, die Pläne des Unternehmens enthüllen und helfen, die Ländereien der Wächterinnen zu verteidigen.",h="Im Steinkrallengebirge schickt Gaxim Rostknirsch einen Agenten in die Mine der Venture Company.",kw={"geheimoperation beta","gaxim rostknirsch","wächterinnen","steinkrallengebirge","venture co.","briefe der venture co.","die scherwindklippe","scherwindmine"},ang={["faction:Alliance"]="Als Mitglied der Allianz seht Ihr, wie gnomische Geräte den Nachtelfen helfen, ihre Ländereien im Herzen Kalimdors zu verteidigen.",["profession:Engineering"]="Als Ingenieur seht Ihr, wie Gaxims Geheimdienstpack mit einer raffinierten explosiven Ablenkung einen Weg durch bewachtes Gelände öffnet.",["race:Gnome"]="Als Gnom seht Ihr, wie Ingenieurskunst und sorgfältige Planung in Gaxim Rostknirschs Sprengsätzen und verdeckten Einsätzen militärische Anwendung finden.",["race:NightElf"]="Als Nachtelf wisst Ihr, dass die Venture Company die uralten Wälder abholzt. Gaxims Operationen liefern den Kommandantinnen der Wächterinnen Informationen, die bei der Verteidigung des Berges helfen."},sec={{t="Sabotage in der Tiefe",b="Nach den ersten Schlägen gegen den Holzeinschlag der Venture Company an der Scherwindklippe nimmt Gaxim Rostknirsch das Herz ihrer Versorgung ins Visier. Wie zuvor soll Sprengstoff die Goblinarbeiter und Söldner auseinanderjagen. Dann durchsucht ein Agent die Mine nach schriftlichen Befehlen und Aufzeichnungen."},{t="Die Scherwindmine im Blick",b="Am östlichen Rand der Scherwindklippe liegt die Scherwindmine, der Stützpunkt der Venture Company unter dem Berg. Goblins graben dort nach Gestein und schlagen Holz, wobei sie Versorgungswege und Befehle ihrer Anführer aufzeichnen. Ein Agent schleicht hinein, platziert Gaxims Sprengladungen und erbeutet die Briefe der Venture Co. Die Explosion bringt die Minenwache durcheinander, und die Briefe enthüllen mehr über die Pläne des Unternehmens in Kalimdor."},{t="Eine pragmatische Partnerschaft",b="Gaxim hat Freude an raffinierten Geräten und Explosionen. Seine Arbeit ist auch für die Nachtelfen von Bedeutung. Im Steinkrallengebirge stehen die Wächterinnen der Horde und den Unternehmen gegenüber, die ihre Ländereien abholzen und durchgraben. Briefe aus der Mine liefern Kommandantinnen wie Kaela Schattenspeer Informationen, um Bedrohungen für die heiligen Wälder vorauszusehen."}},faq={{q="Was ist das Ziel von Geheimoperation Beta?",a="Ein Agent betritt die Scherwindmine am östlichen Ende der Scherwindklippe, platziert Gaxim Rostknirschs Sprengladung als Ablenkung und erbeutet die Briefe der Venture Co. über die Unternehmungen der Firma.",al={"geheimoperation beta ziel","was ist bei geheimoperation beta zu tun","plan beta ziel"}},{q="Wer ist Gaxim Rostknirsch?",a="Gaxim Rostknirsch ist ein Gnomeningenieur im Steinkrallengebirge. Mit Ingenieurskunst und Sprengstoff hilft er den Wächterinnen der Nachtelfen im Kampf gegen den Holzeinschlag und Bergbau der Venture Company.",al={"gaxim rostknirsch","wer vergibt geheimoperation beta"}},{q="Wo liegt die Scherwindmine?",a="Die Scherwindmine liegt am östlichen Ende der Scherwindklippe, in den abgeholzten Ländereien der Venture Company.",al={"scherwindmine lage","wo ist die mine"}},{q="Warum will Gaxim die Briefe der Venture Co.?",a="Die Briefe der Venture Co. beschreiben Versorgungswege, Befehle der Anführer und Pläne für die Region im Detail. Sie helfen der Allianz und den Wächterinnen, die Schritte des Unternehmens vorauszusehen und seine Arbeit im Wald zu behindern.",al={"warum briefe stehlen","was sind die briefe der venture co."}},{q="Wie hilft diese Mission den Nachtelfen?",a="Die Wächterinnen haben zu wenige Streitkräfte, um das gesamte Steinkrallengebirge zu überwachen. Gaxims Explosionen verzögern den Holzeinschlag, und die Briefe liefern Kommandantinnen wie Kaela Schattenspeer nützliche Informationen über ihre Feinde.",al={"warum ist das den nachtelfen wichtig","wächterinnen geheimoperationen"}},{q="Was war Plan Alpha?",a="Plan Alpha war Gaxims frühere Operation im Sägewerk der Venture Company südlich des Felskesselsees. Ein Agent nutzte eine explosive Ablenkung, um die Konstruktionspläne des Unternehmens zu stehlen. Plan Beta nutzt dieselbe Vorgehensweise in der Scherwindmine.",al={"plan alpha","covert ops alpha","vorherige mission"}}},fx={c7fb3974={q="Wozu dienen die Briefe der Venture Company?",a="Diese Dokumente enthalten wichtige Kommunikationen und Pläne der Führung der Venture Company innerhalb der Scherwindmine. Indem sie diese sicherstellen, hoffen Gaxim Rostknirsch und die örtlichen Nachtelf-Wächterinnen, die Operationen der Schänder aufzudecken, ihre aggressiven Abholzungs- und Bergbauarbeiten im gesamten Steinkrallengebirge zu stören und Kaela's Verteidigern einen entscheidenden taktischen Vorteil zurückzugeben.",al={"verwendung von briefen der venture company","warum briefe der venture company","was sind das für briefe"}},["2e3cb5f9"]={q="Wen infiltriert Ihr in der Scherwindmine?",a="Ihr schlagt gegen die Venture Company zu, ein skrupelloses, von Goblins geführtes kommerzielles Kartell, das für rücksichtslose Ressourcenausbeutung berüchtigt ist. Sie haben sich in der Scherwindklippe verschanzt, graben die Erde um, ernten die heiligen Wälder und ignorieren die heiligen Landansprüche der Nachtelfen, wodurch sie die gesamte Region in einen industriellen Schandfleck verwandeln.",al={"feinde in der scherwindmine","wer ist in der scherwindklippe","venture company steinkrallengebirge"}}},fp="17,202,22.255.0,22.409.0,23.318.0,38.193.0,24.183.0,32.102.0,44.201.0,46.193.0,20.234.0"}
P.entries["quest:1081"] = {n="Tyrandes Empfang",s="Im Tempel des Mondes empfängt Euch Tyrande Wisperwind nach Eurer Hilfe im Steinkrallengebirge. Schildwache Thenysil schickt Euch von Astranaar nach Darnassus zu einer Audienz bei der Hohepriesterin.",h="Im Tempel des Mondes empfängt Euch Tyrande Wisperwind nach Eurer Hilfe im Steinkrallengebirge.",kw={"darnassus","kaldorei","tyrandes empfang","schildwache thenysil","steinkrallengebirge","teldrassil","tempel des mondes","tyrande wisperwind"},ang={["faction:Alliance"]="Eine Audienz bei Tyrande Wisperwind verbindet die Nachtelfen Kalimdors mit der übrigen Allianz. In Darnassus erhaltet Ihr Anerkennung für Eure Dienste in der Wildnis.",["race:NightElf"]="Als Nachtelf ist es für Euch eine Heimkehr, Hohepriesterin Tyrande Wisperwind im Tempel des Mondes Bericht zu erstatten. Es zeigt Eure Hingabe an die Verteidigung Eurer angestammten Gebiete."},sec={{t="Ein Stützpunkt im Steinkrallengebirge",b="Die Venture Company bedrängt die Außenposten der Nachtelfen im gesamten Steinkrallengebirge. Schildwache Thenysil leitet ihre Verteidigung von Astranaar aus, doch die entlegenen Stützpunkte sind schwer zu versorgen. Nachschub und Aufklärungsberichte helfen den Schildwachen, die Präsenz der Allianz im Landesinneren von Kalimdor aufrechtzuerhalten. Eure Hilfe stärkt ihre Stellung."},{t="Audienz bei der Hohepriesterin",b="Nachdem Eure Hilfe die Schildwachen im Steinkrallengebirge gestärkt hat, schickt Euch Schildwache Thenysil zurück nach Teldrassil. Tyrande Wisperwind, die Hohepriesterin, empfängt Euch im Tempel des Mondes in Darnassus. Sie würdigt Eure Taten in ganz Kalimdor und heißt Euch als Verbündete willkommen, die an der Seite der Kaldorei kämpfen."}},faq={{q="Wo beginnt diese Quest?",a="Schildwache Thenysil schickt Euch von Astranaar im Eschental aus los, nachdem Ihr 'Neuigkeiten für Schildwache Thenysil' abgeschlossen habt.",al={"wo beginnt tyrandes empfang","questgeber","schildwache thenysil standort"}},{q="Wo kann ich Tyrande Wisperwind finden?",a="Tyrande Wisperwind befindet sich im Tempel des Mondes, im zentralen Bezirk von Darnassus auf Teldrassil.",al={"wo ist tyrande","tyrande finden","tempel des mondes standort"}},{q="Warum will Tyrande mich sehen?",a="Eure Bemühungen im Steinkrallengebirge helfen, den Stützpunkt der Kaldorei im umkämpften Bergland zu halten. Schildwache Thenysil glaubt, dass Eure Dienste die Anerkennung der geistlichen und militärischen Anführerin der Nachtelfen verdienen.",al={"warum tyrande sprechen will","zweck der audienz"}},{q="Welchen strategischen Wert hat das Steinkrallengebirge?",a="Das Steinkrallengebirge bildet einen zerklüfteten Puffer zwischen dem Eschental und den südlichen Ebenen Kalimdors. Die Außenposten dort zu halten hilft den Nachtelfen, Bewegungen der Horde aus dem Brachland zu beobachten und heilige Gebiete zu schützen.",al={"warum das steinkrallengebirge wichtig ist","geschichte des steinkrallengebirges"}},{q="Werden hier auch andere Völker der Allianz anerkannt?",a="Ja. Jeder Abenteurer der Allianz, der Schildwache Thenysil hilft, kann nach Darnassus reisen. Die Audienz spiegelt die wachsenden gemeinsamen Verteidigungsbemühungen der Nachtelfen und der übrigen Allianz wider.",al={"auch für andere völker als nachtelfen","ist das für menschen"}},{q="Gibt es nach dem Treffen mit Tyrande eine Folgequest?",a="Das Treffen mit Tyrande schließt Eure Kurierdienste und Unterstützungsarbeit für Schildwache Thenysil im Steinkrallengebirge ab. In Darnassus könnt Ihr nach weiteren Befehlen suchen.",al={"what comes next","nächste quest der reihe"}}},fx={e0e9e6b4={q="Warum schickt Euch Schildwache Thenysil nach Darnassus?",a="Schildwache Thenysil glaubt, dass Eure Bemühungen den Grundstein dafür gelegt haben, den Stützpunkt der Nachtelfen im umkämpften Steinkrallengebirge zu sichern. Da sie Euer Engagement im Kampf gegen die Gräueltaten in den Gipfeln erkannt hat, möchte sie, dass Ihr formelle Anerkennung und Dankbarkeit direkt von der Anführerin der Nachtelfen, Hohepriesterin Tyrande Wisperwind, erhaltet.",al={"warum schickt mich thenysil","thenysil grund tyrande","warum zu tyrande gehen"}}},fp="22,186,24.318.0,32.294.0,28.106.0,37.96.0,32.207.0,56.190.0,44.173.0,49.127.0"}
P.entries["quest:1082"] = {n="Neuigkeiten für Schildwache Thenysil",s="In Astranaar erwartet Schildwache Tara Thenysil Nachricht aus dem Steinkrallengebirge. Nachdem Ihr Kaela Schattenspeer und Gaxim Rostknirsch gegen die Venture Company geholfen habt, überbringt Ihr die Nachricht, dass ihr Außenposten noch standhält.",h="In Astranaar erwartet Schildwache Tara Thenysil Nachricht aus dem Steinkrallengebirge.",kw={"eschental","astranaar","gaxim rostknirsch","kaela schattenspeer","schildwache thenysil","steinkrallengebirge","neuigkeiten für schildwache thenysil","venture co"},ang={["faction:Alliance"]="Als Mitglied der Allianz helft Ihr, die Verbindung zwischen den Grenzposten im Steinkrallengebirge und den Festungen in Eschental aufrechtzuerhalten, und sichert so die Präsenz der Allianz im Herzen Kalimdors.",["race:Gnome"]="Als Gnom könnt Ihr stolz darauf sein, dass Schildwache Thenysil über Gaxim Rostknirschs Sicherheit erleichtert ist. Gnomischer Erfindergeist kann unter traditionsbewussten Elfen Respekt gewinnen.",["race:NightElf"]="Als Nachtelf könnt Ihr den Sentinels versichern, dass Kaela überlebt hat und ihre Kontrolle über Kalimdors Grenzlande dem Druck der Industrie standgehalten hat."},sec={{t="Eine Depesche von den Gipfeln",b="Die zerklüfteten Pässe des Steinkrallengebirges lassen das Grenzgebiet der Nachtelfen isoliert und schutzlos zurück. Die Venture Company gräbt sich in die Felsen und verschmutzt die Gewässer, wodurch sie den Außenposten von Kaela Schattenspeer und dem gnomischen Tüftler Gaxim Rostknirsch bedroht. Da die unmittelbare Gefahr eingedämmt ist, schickt Kaela Euch nach Nordosten über die Grenze nach Eschental. Ihr sollt berichten, dass sie weiterhin in Sicherheit sind."},{t="Erleichterung in Astranaar",b="In Astranaar wacht Schildwache Tara Thenysil über die Straßen im Inneren von Eschental und sorgt sich um Späher, die in rauere Gefilde entsandt wurden. Die Nachricht, dass Kaela und ihr Ingenieurspartner leben und daran arbeiten, das Land zu heilen, bringt Erleichterung. Obwohl ihre Streitkräfte schwinden und Bedrohungen an mehreren Fronten drängen, kann die Zusammenarbeit mit Verbündeten der Allianz die Zerstörung verlangsamen."}},faq={{q="Wer ist Schildwache Thenysil?",a="Tara Thenysil ist eine Offizierin der nachtelfischen Sentinels und in Astranaar stationiert, dem wichtigsten Stützpunkt der Allianz in Eschental. Sie wacht über Späher und Patrouillen, die in die umliegende Wildnis und benachbarte Regionen entsandt werden.",al={"schildwache thenysil","tara thenysil","thenysil astranaar"}},{q="Warum ist Kaela Schattenspeer im Steinkrallengebirge?",a="Kaela Schattenspeer wurde ins Steinkrallengebirge geschickt, um sich der zerstörerischen Ausbeutung des Landes durch die Venture Company entgegenzustellen. Sie arbeitet mit dem Gnom Gaxim Rostknirsch zusammen, um Goblinmaschinen zu sabotieren und das Land wiederherzustellen.",al={"kaela schattenspeer","kaelas mission","warum ist kaela im steinkrallengebirge"}},{q="Wer ist Gaxim?",a="Gaxim Rostknirsch ist ein gnomischer Ingenieur der Allianz, der gemeinsam mit Kaela Schattenspeer im Steinkrallengebirge stationiert ist. Sein lärmendes Handwerk steht im Widerspruch zu traditionellen elfischen Lebensweisen, doch sein Können hilft, die Holzfällmaschinen der Goblins lahmzulegen.",al={"gaxim","gaxim rostknirsch","der gnom bei kaela"}},{q="Wo finde ich Schildwache Thenysil?",a="Schildwache Thenysil befindet sich in Astranaar an der Hauptstraße durch Eschental, nordöstlich des Pfades, der aus dem Steinkrallengebirge hinabführt.",al={"wo ist thenysil","thenysils standort","wo ist astranaar"}},{q="Was geschieht nach der Rückmeldung bei Schildwache Thenysil?",a="Wenn Ihr Schildwache Thenysil vom Erfolg im Steinkrallengebirge berichtet, eröffnet dies weitere Möglichkeiten im Militär der Nachtelfen und führt zu Kontakten mit höheren Führungskreisen in Darnassus.",al={"nächste quest nach thenysil","wohin geht es als nächstes","reception from tyrande"}},{q="Warum ist die Venture Company eine Bedrohung im Steinkrallengebirge?",a="Die Venture Company rodet heilige Haine, betreibt gewaltige Holzfällmaschinen und vergiftet die Gewässer des Steinkrallengebirges. Ihre Arbeit bedroht das natürliche Gleichgewicht, das die Nachtelfen bewahren.",al={"venture co steinkrallengebirge","warum venture co bekämpfen"}}},fx={be49c188={q="Warum möchte Kaela Schattenspeer, dass dieses Update übermittelt wird?",a="Da sie tief im umkämpften Steinkrallengebirge operieren, waren Kaela und Gaxim abgeschnitten, während sie daran arbeiteten, die Umweltzerstörung der Venture Company zu stoppen. Kaela muss diese Nachricht nach Astranaar zurückschicken, damit die Führung der Wächterinnen weiß, dass ihre Mission noch läuft und erfolgreich ist, anstatt in der Wildnis oder durch Goblin-Maschinerie verloren zu gehen.",al={"warum update an thenysil senden","motiv von kaela schattenspeer","warum bericht an astranaar erstatten"}},["9e9209a2"]={q="Warum schickt Kaela Euch, anstatt selbst zu gehen?",a="Kaela und Gaxim können ihren Posten nicht verlassen. Die Abholzungs- und Bergbauarbeiten der Venture Company stellen eine aktive und unmittelbare Bedrohung für die Klippe und die umliegenden Gipfel dar. Jetzt zu gehen, würde den schwer erkämpften Boden aufgeben, den Ihr gerade geholfen habt zu sichern, also verlassen sie sich auf einen fähigen Reisenden wie Euch, um die Nachricht nach Norden zu tragen.",al={"warum keine wächterin schicken","warum kann kaela nicht selbst bericht erstatten","warum braucht mich kaela"}}},fp="28,194,25.376.0,19.342.0,25.197.0,49.203.0,13.201.0,34.124.0,55.178.0,50.180.0"}
P.entries["quest:1083"] = {n="Wütende Geister",s="Im Verbrannten Tal überrennen Wütende Geister das ausgebrannte Becken. Feuer und schwere Maschinen haben das Land verwüstet, und die befreiten Elementare wüten nun dort. Recken der Allianz werden gebeten, sie zu bezwingen, damit das verwundete Land unter Elunes Gnade heilen kann.",h="Im Verbrannten Tal überrennen Wütende Geister das ausgebrannte Becken.",kw={"das verbrannte tal","elune","wütende geister","feuerelementare","kaela schattenspeer","glimmende überreste","steinkrallengebirge","venture company"},ang={["class:Druid"]="Als Druide seht Ihr in den wütenden Feuerelementaren eine schwere Störung des natürlichen Gleichgewichts. Es muss gehandelt werden, bevor das Leben in den Boden zurückkehren kann.",["class:Shaman"]="Als Schamane wisst Ihr, dass der Zorn der Elementare eine qualvolle Reaktion auf sterbliche Bergleute und Holzfäller ist, die die Erde rücksichtslos ausbeuten.",["faction:Alliance"]="Als Mitglied der Allianz arbeitet Ihr mit Nachtelfen-Schildwachen im Steinkrallengebirge zusammen, um das Chaos der Goblinkartelle einzudämmen und die Gebirgspässe wieder sicher zu machen.",["race:NightElf"]="Als Nachtelf seht Ihr die Verwüstung des Verbrannten Tals als herzzerreißende Wunde in Kalimdors heiliger Wildnis, geschlagen durch ungezügelte industrielle Gier."},sec={{t="Eine verbrannte Tragödie",b="Das Verbrannte Tal war einst ein üppiger Zufluchtsort im Steinkrallengebirge. Die Gier der Venture Company verwandelte es in Asche, als Goblins den Wald abholzen und seine Ressourcen ausbeuten wollten. Sie setzten Brandvorrichtungen und schwere Maschinen ein und steckten das Blätterdach in Brand. Die Bäume fielen, und das empfindliche elementare Gleichgewicht unter der Erde wurde zerstört."},{t="Entfesselter Zorn",b="Die Arbeiten der Venture Company weckten uralte Geister des Feuers, des Steins und des Zorns aus den Tiefen. Der Zorn der Elementare traf die Goblins und trieb sie zurück, während die Geister den schwelenden Krater für sich beanspruchten. Kaela Schattenspeer sagt, die Natur könne sich erst erholen, wenn diese chaotischen Elementare verschwunden seien."}},faq={{q="Wer vergibt die Quest Wütende Geister?",a="Kaela Schattenspeer, eine Nachtelfen-Schildwache im Steinkrallengebirge, erteilt diesen Auftrag Abenteurern der Allianz, die dem Land helfen wollen.",al={"questgeber","wo gibt es wütende geister","wer startet wütende geister"}},{q="Warum wüten die Feuerelementare im Verbrannten Tal?",a="Die Venture Company rodete den Wald und brannte ihn mit zerstörerischen Maschinen nieder. Ihre Arbeiten erschütterten die Erde und befreiten schlummernde Geister der Flamme, des Steins und des Zorns, die das Gebiet überrannten.",al={"warum gibt es hier elementare","was hat die feuerelementare hervorgerufen","verbranntes tal feuergeister"}},{q="Was geschah mit der Venture Company im Verbrannten Tal?",a="Die Goblins steckten den Wald in Brand und entfesselten dadurch Elementare, die gefährlicher waren als erwartet. Die zornigen Wesen überrannten ihre Anlagen und hinterließen zerstörte Lager und lodernde Trümmer.",al={"schicksal der venture company","starben goblins im verbrannten tal","venture company verbranntes tal"}},{q="Was sind Glimmende Überreste?",a="Glimmende Überreste sind brennende Rückstände, die von vernichteten Feuerelementaren im Verbrannten Tal gesammelt werden. Sie werden Kaela Schattenspeer als Beweis gebracht, dass die Elementare dezimiert wurden.",al={"geschichte der glimmenden überreste","wozu dienen die überreste","überreste der wütenden geister"}},{q="Kann sich das Verbrannte Tal jemals erholen?",a="Kaela Schattenspeer glaubt, dass das Land sich weder erholen noch Elunes Segen spüren kann, solange feindselige Elementare durch die Asche streifen. Sie zu beseitigen ist der erste Schritt zur Heilung.",al={"wird das verbrannte tal heilen","heilung des verbrannten tals","kann das tal gerettet werden"}},{q="Wo liegt das Verbrannte Tal?",a="Das Verbrannte Tal liegt im Südwesten des Steinkrallengebirges, inmitten geschwärzter Erde, verbrannten Holzes und umherstreifender Elementargeister.",al={"lage des verbrannten tals","wie findet man das verbrannte tal","wo sind die elementare"}}},fx={db30736e={q="Warum möchte Kaela Schattenspeer, dass die Enraged Spirits dezimiert werden?",a="Die Verwüstung des Verbrannten Tals bricht Kaela Schattenspeers Herz. Die rücksichtslose Schändung entfesselte gewalttätige brennende Geister aus Feuer, Stein und Zorn über das Land. Als Nachtelfin glaubt sie, dass die vernarbte Erde keine Hoffnung hat, Elune's Grace zu empfangen oder mit der Heilung zu beginnen, solange diese chaotischen Elementarkräfte frei herumlaufen. Sie zu dezimieren ist der erste Schritt, um den Frieden im verwundeten Tal wiederherzustellen.",al={"warum die geister dezimieren","motiv von kaela schattenspeer","warum will kaela, dass dies erledigt wird"}},["3905caa9"]={q="Gegen welche Kreaturen kämpft Ihr im Verbrannten Tal?",a="Ihr jagt die brennenden Geister – Elementare, die aus Feuer, geschmolzenem Stein und roher Wut geboren wurden – die nun das versengte Ödland des Verbrannten Tals heimsuchen. Diese feindseligen Wesen, die geweckt und aufgewühlt wurden, als die Venture Company die Wälder in Brand steckte und die Erde mit Maschinen aufriss, überrennen gewaltsam die Ruinen und greifen jeden an, der sich ihnen zu nähern wagt.",al={"elementare im verbrannten tal","was sind die brennenden geister","gegen wen kämpfe ich bei enraged spirits"}}},fp="15,247,18.321.0,14.297.0,36.136.0,58.187.0,57.200.0,27.184.0,34.166.0,34.131.0"}
P.entries["quest:1084"] = {n="Verletzte Urtume",s="Goblinwaffen vergiften womöglich die Treants im Steinkrallengebirge. Kaela Schattenspeer bittet Euch, Schrapnell aus den wahnsinnigen Hütern zu bergen, damit Gaxim Rostknirsch es untersuchen kann.",h="Goblinwaffen vergiften womöglich die Treants im Steinkrallengebirge.",kw={"zerfressenes schrapnell","verderbnis","gaxim rostknirsch","kaela schattenspeer","steinkrallengebirge","treants","venture company","verletzte urtume"},ang={["class:Druid"]="Treants tragen das Leben der Natur in sich. Das fremde Metall zu entfernen, das ihr Fleisch vergiftet, ist eine düstere Arbeit angesichts der Zerstörung durch die Venture Company.",["profession:Engineering"]="Das zerfressene Metall in den Treants offenbart die nachlässige Arbeit hinter der Munition der Venture Company. Gnomische Handwerkskunst zeigt ein anderes Maß an Präzision.",["race:Gnome"]="Gaxim Rostknirsch zeigt, wie mechanisches Geschick den Schaden aufdecken und erklären kann, den rücksichtslose Ingenieure anrichten.",["race:NightElf"]="Als Kaldorei, der geschworen hat, Kalimdors Wildnis zu schützen, seht Ihr, wie die Goblinindustrie uralte Hüter des Waldes entstellt. Es ist ein Frevel."},sec={{t="Verseuchte Beschützer",b="Die Treants bewachten einst die Haine des Steinkrallengebirges, erbittert in ihrer Verteidigung und mit dem Wohlergehen des Landes verbunden. Als die Venture Company mit Kreissägen, Sprengstoff und Tagebau kam, schlug der Wald zurück. Die Treants vertrieben die Eindringlinge aus Teilen des Tals, kehrten aber nicht zu ihrer friedlichen Wacht zurück. Nun sind sie feindselig und wahnsinnig."},{t="Gnomische Ermittlungen",b="Kaela Schattenspeer, eine Späherin der Allianz im Gebirge, glaubt, dass keine natürliche Krankheit die Treants befällt. Gaxim Rostknirsch, ein Gnomeningenieur, vermutet, dass Goblinwaffen und Chemikalien ihnen während des chaotischen Rückzugs der Venture Company geschadet haben. Er hofft, zerfressenes Schrapnell aus den verwundeten Treants werde zeigen, ob die Kampfmittel der Venture Company die uralten Beschützer des Steinkrallengebirges vergiften."}},faq={{q="Wer vergibt die Quest Verletzte Urtume?",a="Kaela Schattenspeer, eine Späherin der Allianz im Steinkrallengebirge, bittet Euch um Hilfe. Sie beobachtet den wachsenden Konflikt und den Schaden, den er dem Land zufügt.",al={"verletzte urtume questgeber","wer vergibt verletzte urtume","kaela schattenspeer quest"}},{q="Warum sind die Treants verderbt?",a="Gaxim Rostknirsch vermutet, dass sich während des chaotischen Rückzugs der Goblins Munition der Venture Company in die Treants bohrte. Er glaubt, dass die Waffen die Hüter des Waldes vergiften und in den Wahnsinn treiben.",al={"warum sind treants wahnsinnig","steinkrallengebirge treants verderbt","ursprung der verderbnis der treants"}},{q="Welcher Gegenstand muss für diese Aufgabe geborgen werden?",a="Bergt ein Stück Zerfressenes Schrapnell aus der Rinde und dem Fleisch der verwundeten Treants, die in der Gegend umherstreifen.",al={"verletzte urtume gegenstand","zerfressenes schrapnell quest"}},{q="Wer ist Gaxim Rostknirsch?",a="Gaxim Rostknirsch ist ein mit der Allianz verbündeter Gnomeningenieur, der Kaela Schattenspeer hilft. Er nutzt sein mechanisches Geschick, um die Waffen der Venture Company und ihre schädlichen Auswirkungen auf das Leben in der Natur zu untersuchen.",al={"gaxim","gnom im steinkrallengebirge","gaxim rostknirsch rolle"}},{q="Wie ist die Venture Company im Steinkrallengebirge vertreten?",a="Die Venture Company ist ein goblinisches Holzfäller- und Bergbausyndikat, das ins Steinkrallengebirge eingedrungen ist. Sie holzt heilige Wälder ab und plündert Erzvorkommen, ohne Rücksicht auf das Gleichgewicht des Landes.",al={"venture company steinkrallengebirge","warum sind goblins im steinkrallengebirge"}},{q="Heilt das Sammeln des Schrapnells die Treants?",a="Nein. Gaxim braucht das Schrapnell als Probe, um die Art und Herkunft des Giftstoffs zu ermitteln. Das Sammeln heilt die verderbten Hüter nicht sofort.",al={"kann man treants heilen","erholen sich treants"}}},fx={["6c6333aa"]={q="Warum möchte Kaela Schattenspeer das Zerfressene Schrapnell haben?",a="Kaela ist zutiefst beunruhigt über die Verderbnis, die die Beschützer des Verbrannten Tals verzerrt. Nachdem die Venture Company zurückgeschlagen wurde, blieben die uralten Treants gewalttätig und wahnsinnig zurück. Sie versprach Gaxim Rostknirsch, dass sie eine Probe der Munition der Goblins beschaffen würde, die in den Wounded Ancients steckt, in der Hoffnung, dass der Gnom sie untersuchen und bestätigen kann, ob die grausame Bewaffnung der Eindringlinge wirklich für die Vergiftung der Beschützer des Landes verantwortlich ist.",al={"motiv von kaela schattenspeer","warum treants im steinkrallengebirge helfen","warum will kaela schrapnell"}},["4feb3a85"]={q="Was ist das Zerfressene Schrapnell?",a="Zerfressenes Schrapnell besteht aus gezackten Metallfragmenten, die von der sich zurückziehenden Venture Company in die Treants geschossen wurden. Gaxim Rostknirsch vermutet, dass die giftigen oder explosiven Rückstände, die am Eisen haften, den tragischen Abstieg der Wounded Ancients in den Wahnsinn verursacht haben. Kaela muss das Exemplar zurückbringen, damit Gaxim dessen chemische Zusammensetzung untersuchen und einen Weg nach vorne entwickeln kann.",al={"was ist zerfressenes schrapnell","zerfressenes schrapnell steinkrallengebirge","schrapnell-hintergrund"}},["2aa0bc4f"]={q="Warum werdet Ihr gegen die verwundeten Treants geschickt?",a="Die verwundeten Treants waren einst friedliche Beschützer des Verbrannten Tals, bevor die Abholzungs- und Kriegsarbeiten der Venture Company das Tal verwüsteten. Während ihres Rückzugs trafen die Goblins die Verteidiger mit übler Munition, was sie vernarbt, wahnsinnig und feindselig gegenüber jedem machte, der sich nähert. Um das Schrapnell zu bergen, das in ihrer Rinde steckt, müsst Ihr Euch diesen qualvoll verdorbenen Kreaturen stellen.",al={"warum verwundete treants töten","wer sind die wounded ancients","treants im verbrannten tal"}}},fp="16,177,19.333.0,21.378.0,38.154.0,30.184.0,42.103.0,24.184.0,53.179.0,46.145.0"}
P.entries["quest:1085"] = {n="Wache halten im Steinkrallengebirge",s="In einem Lager nahe der Scherwindklippe schickt Kaela Schattenspeer Reisende der Allianz zu Gaxim Rostknirsch, um Hilfe gegen die Venture Company zu erhalten. Gemeinsam schützen die vorsichtige Nachtelfen-Schildwache und der exzentrische Gnomentüftler den Gebirgspass vor der hemmungslosen Verwüstung durch das Unternehmen.",h="In einem Lager nahe der Scherwindklippe schickt Kaela Schattenspeer Reisende der Allianz zu Gaxim...",kw={"ingenieurskunst","gaxim rostknirsch","gnom","kaela schattenspeer","nachtelf","steinkrallengebirge","der steinkrallengipfel","venture company"},ang={["faction:Alliance"]="Als Mitglied der Allianz erlebt Ihr, wie Fachwissen aus den Östlichen Königreichen die Schildwachen Kalimdors im Kampf gegen gemeinsame Bedrohungen im Grenzland unterstützt.",["profession:Engineering"]="Als Ingenieur seht Ihr, wie Ingenieurskunst bei der Aufklärung an der Front und beim Schutz der Natur hilft. Zahnräder können dem Naturschutz dienen, wenn sie gegen ungezügelte Ausbeutung eingesetzt werden.",["race:Gnome"]="Als Gnom erlebt Ihr, wie Gaxim Rostknirsch gnomischen Erfindungsgeist in Kalimdor einsetzt, wo Wissenschaft, Ingenieurskunst und Magie den Herausforderungen der Region begegnen können.",["race:NightElf"]="Als Nachtelf spürt Ihr vielleicht, wie Euer Stolz nachgibt, wenn Schildwachen der Kaldorei einem Gnomentüftler vertrauen, der auf Ingenieurskunst und Magie setzt. Die Abholzung durch die Venture Company hat verheerende Ausmaße angenommen."},sec={{t="Ein ungleiches Bündnis",b="Die Venture Company dringt in die Wildnis des Steinkrallengebirges ein und fällt seine uralten Bäume. Kaela Schattenspeer, eine Nachtelfen-Schildwache, weiß, dass Kampfgeschick allein solche industriellen Plünderungen nicht aufhalten kann. Deshalb setzt sie auf gnomischen Erfindungsgeist, obwohl Nachtelfen und Gnome bei Technologie und Natur selten einer Meinung sind. Ihr Bündnis zeigt, wie prekär der Kampf geworden ist."},{t="Gnomische Philosophie",b="Gaxim Rostknirsch bringt den exzentrischen Pragmatismus der kleineren Verbündeten der Allianz mit. Die Gesellschaft der Nachtelfen wandte sich vor Jahrtausenden von arkanen Ausschweifungen ab, doch Gaxim glaubt, dass die Ablehnung von Magie und technischen Neuerungen die Nachtelfen verwundbar macht. Er hofft, seinen Gastgebern unter den Kaldorei zu zeigen, dass praktische Wissenschaft die Natur neben Bogen und Gleve verteidigen kann."}},faq={{q="Warum arbeiten hier eine Nachtelfe und ein Gnom zusammen?",a="Die Waldzerstörung und der Rohstoffabbau durch die Venture Company im Steinkrallengebirge haben schwere Ausmaße angenommen, weshalb Kaela Schattenspeer Hilfe von außen annimmt. Gaxim bringt Kenntnisse in Ingenieurskunst und Alchemie mit, die Nachtelfen gewöhnlich fehlen, und bietet technische Hilfe gegen moderne Industriemaschinen.",al={"warum ist gaxim bei kaela","kaela und gaxim","bündnis zwischen gnom und nachtelf"}},{q="Wer ist Gaxim Rostknirsch?",a="Gaxim Rostknirsch ist ein abenteuerlustiger Gnomeningenieur und Tüftler in einem Lager nahe der Scherwindklippe. Er glaubt, dass die Ablehnung arkaner Magie die Nachtelfen benachteiligt. Er will beweisen, dass Ingenieurskunst, Alchemie und kontrollierte Magie gemeinsam eine Antwort auf ernste Bedrohungen bieten können.",al={"gaxim rostknirsch hintergrundgeschichte","wer ist gaxim","gnom am steinkrallengipfel"}},{q="Wer ist Kaela Schattenspeer?",a="Kaela Schattenspeer ist eine Nachtelfen-Schildwache, die über das Steinkrallengebirge wacht und es verteidigt. Als regionale Befehlshaberin koordiniert sie den Widerstand gegen die Venture Company.",al={"kaela schattenspeer","wer ist kaela"}},{q="Welche Bedrohung stellt die Venture Company im Steinkrallengebirge dar?",a="Die Venture Company ist ein skrupelloses Handelssyndikat, das heilige Wälder abholzt, zerstörerische Bohranlagen betreibt und die unberührten Landstriche des Steinkrallengebirges für schnellen Profit verschmutzt.",al={"venture company steinkrallengebirge","warum gegen die venture company kämpfen"}},{q="Wer ist Tara, die Kaela erwähnt?",a="Tara ist die Schildwache Tara Thenysil, Kaelas Freundin in Astranaar, die Euch geschickt hat, um nach ihr zu sehen. Kaela ist stolz darauf, dass Tara unter den Sentinels so erfolgreich ist, dass sie Abenteurer mit Besorgungen beauftragen kann.",al={"tara steinkrallengebirge","zurück zu tara geschickt werden"}},{q="Wohin führt diese Aufgabe als Nächstes?",a="Nachdem Ihr mit Gaxim Rostknirsch gesprochen habt, bietet er Euch 'A Gnome's Respite' an und bittet Euch, die Holzfäller der Venture Company in der Scherwindklippe zurückzuhalten, während er seine nächsten Erfindungen plant.",al={"quest nach wache halten im steinkrallengebirge","nächste quest nach gaxim"}}},fx={["6de32c22"]={q="Warum möchte Kaela Schattenspeer, dass Ihr mit Gaxim sprecht?",a="Die Venture Company hat das Steinkrallengebirge schwer verwüstet und fast Kaelas gesamte Zeit und Aufmerksamkeit darauf verwendet, ihre Zerstörung einzudämmen. Verzweifelt auf der Suche nach Unterstützung hat sie die traditionelle Zurückhaltung der Nachtelfen abgelegt, sich mit dem Gnom-Ingenieur Gaxim Rostknirsch zu verbünden. Um einen effektiven Widerstand aufzubauen und die Berge zu schützen, benötigt sie, dass Ihr Euch direkt mit Gaxim abstimmt und Eure Stärke ihren gemeinsamen Bemühungen beisteuert.",al={"warum mit gaxim sprechen","motiv von kaela schattenspeer","warum schickt kaela dich zu gaxim"}}},fp="22,265,20.379.0,18.339.0,54.287.0,24.265.0,25.189.0,56.187.0,32.188.0,31.183.0"}
P.entries["quest:1086"] = {n="Der Flugapparathafen",s="Apothekerin Zamah schickt Euch, um den Flugapparathafen über dem Steinkrallengebirge zum Schweigen zu bringen. Tragt ihren Toxinvernebler in die Holzfällergebiete der Venture Company und trefft die Verbindung des Kartells zur Außenwelt.",h="Apothekerin Zamah schickt Euch, um den Flugapparathafen über dem Steinkrallengebirge zum Schweigen zu bringen.",kw={"flugapparathafen","apothecary zamah","hubschrauberlandeplatz","felskesselsee","flugapparat","steinkrallengebirge","donnerfels","toxinvernebler","venture co"},ang={["faction:Horde"]="Als Mitglied der Horde helft Ihr, die Venture Company von Unterstützung von außen abzuschneiden. Der Angriff auf ihren Luftverkehr versetzt ihren Versorgungslinien einen entscheidenden Schlag.",["profession:Engineering"]="Als Ingenieur erkennt Ihr die grobe, zweckmäßige Bauweise des Goblinhubschrauberlandeplatzes, der für die schnellen Reisen der Venture Company durch zerklüftete Berge errichtet wurde.",["race:Tauren"]="Als Tauren verabscheut Ihr die Zerstörung des Steinkrallengebirges durch die Venture Company. Auf Drängen einer Apothekerin der Verlassenen Toxine einzusetzen, stellt das Gleichgewicht zwischen Ehrfurcht vor der earth-mother und Pragmatismus auf dem Schlachtfeld auf die Probe.",["race:Undead"]="Als Verlassener ist Euch der Umgang mit dem Toxinvernebler vertraut. Die alchemistische Kunst von Unterstadt kann Probleme lösen, an denen rohe Gewalt scheitert."},sec={{t="Eine lautlose Lieferung",b="Apothekerin Zamah bereitet das Toxin von Apotheker Lydon für die Venture Company vor. Die Tauren wollen das Steinkrallengebirge vor Entwaldung und verheerenden Maschinen schützen, während die Verlassenen einen anderen Weg einschlagen. Zamah nimmt die Verbindung des Kartells über die Berge hinaus ins Visier, nicht seine Fußsoldaten oder Holzfäller. Gerüchte sprechen von einem Hubschrauberlandeplatz, über den leichte Fracht und Nachrichten zwischen dem Steinkrallengebirge und fernen Firmenbüros befördert werden."},{t="Cragpools Lufthafen",b="Der Hubschrauberlandeplatz der Venture Company liegt hoch oben im Gebiet des Felskesselsees, südlich des großen Wasserrads. Eine kleine Plattform dort dient leichten Flugapparaten, nicht gewaltigen Zeppelinen. Ihr werdet entsandt, um den Toxinvernebler auszulösen und den Landeplatz mit giftigem Dunst zu füllen, bevor ein Pilot, Kurier oder Mechaniker die Befehlshaber der Firma warnen kann."},{t="Pragmatismus der Verlassenen",b="Apothekerin Zamah entschuldigt sich keineswegs für die chemische Kriegsführung gegen die Goblins. Sie glaubt, dass die Venture Company für das, was sie dem Land antut, Schlimmeres verdient. Die Doktrin von Unterstadt hat sie eine einfache Lektion gelehrt: Die Horde darf dunkle Pfade nicht scheuen, wenn sie zum Sieg führen."}},faq={{q="Wo liegt der Flugapparathafen?",a="Der Hubschrauberlandeplatz der Venture Company liegt im Gebiet des Felskesselsees im Steinkrallengebirge, südlich des gewaltigen industriellen Wasserrads. Seine erhöhte Holzplattform überblickt die südliche Biegung des Sees.",al={"wo liegt der flugapparathafen","hubschrauberlandeplatz lage","wo liegt der lufthafen","venture co landeplatz"}},{q="Warum will Apothekerin Zamah diesen Ort vergiften?",a="Zamah will die Kommunikationswege und leichten Versorgungslinien der Venture Company zwischen dem Steinkrallengebirge und ihrer fernen Zentrale unterbrechen. Sie hofft, durch die Vergiftung des Landeplatzes die Flugbesatzungen der Goblins lahmzulegen und das Toxin zu ihren Firmenführern zurückzutragen.",al={"warum den flugapparathafen bombardieren","warum toxinvernebler","zamahs beweggrund"}},{q="Wer ist Apothekerin Zamah?",a="Apothekerin Zamah ist eine Gesandte der Königlichen Apothekervereinigung, die in den Teichen der Visionen unter Donnerfels stationiert ist. Sie erforscht Kalimdors Pflanzen- und Tierwelt und entwickelt alchemistische Waffen für die Verlassenen und die Horde.",al={"zamahs identität","wer ist zamah","untote in donnerfels"}},{q="Warum setzt die Horde hier chemische Waffen ein?",a="Die Verlassenen setzen chemische Waffen mit rücksichtslosem Pragmatismus ein. Zamah glaubt, dass die zerstörerische Gier der Venture Company erbarmungslose Taktiken rechtfertigt, während ihre taurenischen Verbündeten spirituelle Heilung und die direkte Verteidigung der Erde bevorzugen. Für sie zählt der Sieg mehr als Zurückhaltung.",al={"horde setzt seuche ein","warum goblins vergiften","ist das eine seuche"}},{q="Welche Art von Fluggeräten nutzt die Venture Company hier?",a="Die Venture Company nutzt kleine Goblinflugapparate und Gyrokopter, keine ausgewachsenen Zeppeline. Diese wendigen Maschinen befördern Nachrichten und Fracht höchster Priorität über die zerklüfteten Gebirgspässe des Steinkrallengebirges.",al={"venture co hubschrauber","welcher flugapparat","goblinfluggeräte steinkrallengebirge"}},{q="Was geschieht nach dem Einsatz des Verneblers?",a="Nachdem Ihr den Vernebler oben auf dem Landeplatz ausgelöst habt, flieht Ihr, bevor Euch die Dämpfe einholen. Zamah betrachtet den Einsatz als Erfolg und erwartet, dass das Gift die Logistik der Goblins stört.",al={"vernebler ergebnis","nach dem aufstellen des verneblers"}}},fx={ee15b44c={q="Wen visiert Ihr am Flughafen an und warum sind sie hier?",a="Ihr visiert die Venture Company an, ein skrupelloses Goblin-Kartell, das das Steinkrallengebirge für Profit abgräbt und kahl schlägt. Sie betreiben einen geheimen Flugplatz, um Nachrichten und leichte Fracht zu ihrem entfernten Hauptquartier zu befördern. Indem die Horde ihre Landeplattform mit dem Toxinvernebler von Apothekerin Zamah angreift, zielt sie darauf ab, ihre logistische Lebensader abzuschneiden und das Gift direkt zu ihrer Führung zu verbreiten.",al={"ziel am flughafen der venture company","wen greifen wir im steinkrallengebirge an","warum ist die venture company hier"}}},fp="26,206,17.405.0,19.334.0,19.275.1,44.203.0,50.244.0,24.225.0,45.270.0,56.198.0,42.176.1"}
P.entries["quest:1087"] = {n="Cenarius' Vermächtnis",s="Nahe Sonnenfels macht Cenarius' Vermächtnis aus Braelyn Feuerhands Groll einen Ruf zu den Waffen. Die Blutelfenmagierin sagt, die Nachtelfen und Cenarius' Kinder unterdrückten die Magie des Landes. Sie will ihre Reihen auf dem Steinkrallengipfel lichten, damit rohe arkane Macht frei fließen kann, während ihre Niederlage die Präsenz der Allianz im Gebirge schwächt.",h="Nahe Sonnenfels macht Cenarius' Vermächtnis aus Braelyn Feuerhands Groll einen Ruf zu den Waffen.",kw={"braelyn feuerhand","cenarion botanist","cenarius' vermächtnis","daughter of cenarius","jaedenar","ordanus","son of cenarius","der steinkrallengipfel","sonnenfels"},ang={["class:Druid"]="Als Taurendruide bedeutet das Töten von Cenarius' Nachkommen und Botanikern des Zirkels des Cenarius für Euch einen schmerzhaften Zwiespalt zwischen Fraktionstreue und den heiligen Wegen der Natur.",["class:Mage"]="Als Magier versteht Ihr vielleicht die Spannung zwischen uralten Schutzbannungen der Kaldorei und frei fließenden Leyenergien. Braelyns rücksichtsloser Eifer grenzt an Besessenheit.",["faction:Horde"]="Als Mitglied der Horde wisst Ihr, dass der Steinkrallengipfel die größte Bastion der Allianz und der Kaldorei in diesem Gebirgszug ist. Seine Verteidiger zu beseitigen hilft, Sonnenfels und das Hochwipfeltal zu schützen."},sec={{t="Gehemmte Strömungen",b="Braelyn Feuerhand lebt in den Hügeln nahe Sonnenfels, frustriert über die natürlichen Schutzbannungen des Steinkrallengebirges. Sie sagt, die Druiden des Zirkels des Cenarius und die Nachkommen des Halbgottes Cenarius erstickten die arkanen Strömungen des Landes. Für Braelyn ist das Kanalisieren von Macht hier, als würde man Wasser mit einem durchlöcherten Eimer schöpfen. Sie will diese Schutzbannungen beseitigen und rohe magische Energie wieder ungehindert strömen lassen."},{t="Angriff auf den Steinkrallengipfel",b="Braelyn schickt Champions der Horde nach Norden zum Steinkrallengipfel, um die Macht der Wächter zu brechen. Dort patrouillieren Cenarion Botanists und die stolzen Sons and Daughters of Cenarius durch uralte Haine und Tempelstätten der Kaldorei. Sie niederzustrecken würde die Bannungen schwächen, die Braelyns Zauberei dämpfen. Es würde auch der Nachtelfenenklave einen blutigen Schlag versetzen, die den Stützpunkt der Horde im Gebirge bedroht."},{t="Verbindungen zum Schattenrat",b="Braelyn Feuerhand sehnt sich danach, nach Jaedenar zurückzukehren, einer verderbten Festung des Schattenrats, die im Teufelswald im Norden verborgen liegt. Ihr ungesehener Meister verbietet ihr die Rückkehr, bis ihr Werk im Steinkrallengebirge vollendet ist. Die Horde unterstützt sie, um Gebietsansprüche zu sichern, oft ohne von dem finsteren Kult zu wissen, der sie lenkt."}},faq={{q="Wer ist Braelyn Feuerhand?",a="Braelyn Feuerhand ist eine Blutelfenzauberin in den zerklüfteten Höhen nahe Sonnenfels. Sie nimmt die Hilfe der Horde an, um die Nachtelfen aus dem Steinkrallengebirge zu vertreiben.",al={"braelyn feuerhand hintergrundgeschichte","wer ist der questgeber","braelyn"}},{q="Warum will Braelyn Cenarius' Kinder tot sehen?",a="Braelyn sagt, die druidische Magie der Kaldorei-Botaniker und Cenarius' Nachkommen unterdrücke rohe arkane Macht im gesamten Gebirge. Sie will sie beseitigen, damit die Schutzbannungen des Hains schwächer werden und die befreite Magie in ihre Hände fließt.",al={"warum sons of cenarius töten","warum cenarion botanists hassen","warum hasst braelyn sie"}},{q="Wo befinden sich die Ziele?",a="Die Sons of Cenarius, Daughters of Cenarius und Cenarion Botanists befinden sich weit im Norden auf dem Steinkrallengipfel. Sie bewachen die uralten Ruinen, Haine und Mondbrunnen, die von den Nachtelfen gepflegt werden.",al={"wo sind sons of cenarius","gegnerstandorte steinkrallengipfel","wo cenarion botanists finden"}},{q="Was ist Jaedenar, das Braelyn erwähnt?",a="Jaedenar ist eine tiefe Schlucht mit einem Höhlenkomplex im Teufelswald, stark von der Brennenden Legion verderbt. Es ist die zentrale Operationsbasis des Schattenrats in Kalimdor.",al={"was ist jaedenar","braelyn meister jaedenar","verbindung zu jaedenar"}},{q="Warum hilft die Horde Braelyn beim Angriff auf cenarische Verteidiger?",a="Die Nachtelfen auf dem Steinkrallengipfel sind mit der Allianz verbündet und stellen sich der Ausbreitung der Horde im Gebirge entgegen. Ihren Hain zu schwächen hilft, die Region für die Horde zu sichern, unabhängig von Braelyns persönlichen Beweggründen.",al={"warum tötet die horde den zirkel des cenarius","horde konflikt steinkrallengipfel"}},{q="Was geschieht nach dem Abschluss von Cenarius' Vermächtnis?",a="Danach ist Braelyns nächstes Ziel Ordanus, ein Hüter des Hains in Rajenbaum im Eschental. Er befindet sich oben auf dem großen Baum dort.",al={"quest nach cenarius' vermächtnis","was kommt als nächstes in der questreihe","ordanus questreihe"}}},fx={["9bca5a54"]={q="Wen sollt Ihr für Cenarius' Legacy töten?",a="Braelyn schickt Euch gegen die Söhne und Töchter von Cenarius sowie die Cenarion-Botaniker, die auf dem Steinkrallengipfel stationiert sind. Diese Hüter, Dryaden und Nachtelfen-Pfleger kümmern sich um den heiligen Hain und arbeiten unermüdlich daran, das Land zu kultivieren, und schirmen die Region vor der chaotischen, brennenden arkanen Magie ab, die Braelyn zu nutzen versucht.",al={"ziele von cenarius' legacy","wen tötet man für cenarius' legacy","wer sind die söhne und töchter von cenarius"}}},fp="16,331,16.387.0,27.401.0,26.293.1,24.152.1,52.229.0,30.193.0,41.162.0,67.219.0,47.134.1"}
P.entries["quest:1088"] = {n="Ordanus",s="In der Zuflucht der Felsspitze jagt Braelyn Feuerhand Hüter Ordanus, einen älteren Sohn von Cenarius, der vom Steinkrallengipfel floh. Sie glaubt, sein Volk habe uralte Ruinen der Hochgeborenen entweiht, und schickt daher Champions der Horde über die Grenze nach Eschental, um seinen Kopf zu holen.",h="In der Zuflucht der Felsspitze jagt Braelyn Feuerhand Hüter Ordanus, einen älteren Sohn von Cenarius, der vom...",kw={"eschental","braelyn feuerhand","cenarius","hochgeborene","ordanus","rajenbaum","steinkrallengebirge","zuflucht der felsspitze"},ang={["class:Druid"]="Als Druide der Horde steht Ihr vor einer düsteren Wahl: einem direkten Sohn von Cenarius das Leben zu nehmen, um die uralte Fehde einer Blutelfe auszufechten.",["class:Mage"]="Als Magier seht Ihr in Braelyn Feuerhand vielleicht den unbeugsamen arkanen Stolz der Hochgeborenen und ihren Glauben an die Überlegenheit arkaner Meisterschaft über die Naturphilosophie des Cenarion.",["faction:Horde"]="Als Mitglied der Horde schwächt Ihr die Autorität der Nachtelfen entlang der Grenze zwischen Eschental und dem Steinkrallengebirge, indem Ihr einen älteren Sohn von Cenarius erschlagt. Dies fördert die Ausbreitung der Horde in umkämpfte Waldgebiete."},sec={{t="Jagd aus uraltem Groll",b="Braelyn Feuerhand kam auf Befehl ihres Meisters ins Steinkrallengebirge. Sie sollte die heiligen Ruinen von Azsharas uralten Tempeln zurückfordern. Auf dem Gipfel fand sie Nachtelfen vor, die Relikte ihrer hochgeborenen Vorfahren wie Wildnis behandelten, die es einzugrenzen galt. Hüter Ordanus entkam ihr und floh über die Grenze nach Eschental. Mithilfe arkaner Sicht fand Braelyn ihn hoch oben in einem hölzernen Zufluchtsort in Rajenbaum und warb dann die Horde an, um die Jagd zu vollenden."},{t="Spross des Waldgottes",b="Hüter Ordanus zählt zu den ältesten Söhnen von Cenarius und ist tief mit den wilden Magien Kalimdors verbunden. Nachtelfische Wächter brachten ihn vom Steinkrallengipfel nach Rajenbaum, um ihn vor arkanen Kräften zu schützen, die in heilige Haine vordrangen. Treue Cenarion Vindicators und herbeigerufene Wald-Treants verteidigen ihn. Für Braelyn trägt Ordanus die uralte Autorität des Waldhalbgottes und steht ihrer Rache im Weg."},{t="Rache der Hochgeborenen",b="Braelyn Feuerhand fordert Ordanus' Kopf sowohl aus persönlichem Groll als auch für ihre Sache. Sie erinnert sich daran, ihn vor Jahrhunderten gekannt zu haben, als Cenarius' Nachkommen auf die Hochgeborenen und ihre Beherrschung des Arkanen herabblickten. Sein Kopf würde jene alten Kränkungen rächen und den Weg für die tiefergehenden Pläne ihres Meisters in Kalimdors Wildnis ebnen."}},faq={{q="Wer ist Hüter Ordanus?",a="Hüter Ordanus ist ein Hüter des Hains und einer der ältesten Söhne von Cenarius. Einst nahe dem Steinkrallengipfel stationiert, floh er nach Eschental, um der Rache der Hochgeborenen zu entgehen.",al={"ordanus hintergrund","wer ist ordanus","wer ist hüter ordanus"}},{q="Wo ist Hüter Ordanus zu finden?",a="Hüter Ordanus lebt ganz oben in einem gewaltigen hohlen Baumgebilde in Rajenbaum, an der Straße durch das zentrale Eschental.",al={"ordanus aufenthaltsort","wo ist ordanus","rajenbaum baum"}},{q="Warum will Braelyn Feuerhand Ordanus tot sehen?",a="Braelyn betrachtet die Anwesenheit der Nachtelfen im Steinkrallengebirge als Entweihung uralter Tempelruinen der Hochgeborenen. Außerdem hasst sie Ordanus wegen der Arroganz und Verachtung, an die sie sich aus längst vergangenen Zeiten erinnert.",al={"warum ordanus töten","braelyns groll","warum will braelyn ordanus"}},{q="Wer ist Braelyn Feuerhands Meister?",a="Braelyn sagt, ihr Meister habe sie zum Steinkrallengipfel geschickt, um Azsharas uralte Tempelruinen zurückzufordern, doch seine genaue Identität hält sie geheim.",al={"braelyn meister","wer schickte braelyn","braelyns meister"}},{q="Wie fügt sich dieser Konflikt in die Präsenz der Horde im Steinkrallengebirge ein?",a="Hordentruppen in der Zuflucht der Felsspitze kämpfen im Steinkrallengebirge und in Eschental häufig mit nachtelfischen Schildwachen und Cenarion-Beschützern um Gebiete und Ressourcen. Braelyns Schlag gegen einen Anführer des Cenarion dient den Zielen beider Seiten.",al={"warum hilft die horde braelyn","steinkrallengebirge horde beweggründe"}},{q="Was geschieht nach Ordanus' Tod?",a="Nach Ordanus' Tod belohnt Braelyn Euch und verweist Euch an den Bau, wo Bedrohungen auf den Gipfeln des Steinkrallengebirges warten.",al={"wie weiter nach ordanus","quest nach ordanus","als nächstes der bau"}}},fx={ec9312c1={q="Wozu dient Ordanus' Kopf?",a="Braelyn Feuerhand verlangt den Kopf des Hüters Ordanus als absoluten Beweis für dessen Ableben und um einen An Ancient Grudge zu begleichen. Da Braelyn Ordanus einst vor langer Zeit kannte, verachtet er die Arroganz des Hüters und dessen Glauben, dass seine Art sogar über den Hochgeborenen stünde. Seinen abgetrennten Kopf zu bringen bestätigt nicht nur, dass die Verteidigung der Nachtelfen im Eschental einen kritischen Schlag erlitten hat, sondern demütigt auch den Sohn des Cenarius genau so, wie Braelyn es sich vorgestellt hat.",al={"warum ordanus' kopf","ordanus' kopf zweck","was macht braelyn mit ordanus' kopf"}}},fp="7,249,32.433.0,27.415.0,19.335.1,22.166.0,34.121.0,44.188.0,33.138.0,67.222.0,36.119.1"}
P.entries["quest:1089"] = {n="Der Bau",s="Beim Krallenbau schickt Braelyn Feuerhand Champions der Horde in verborgene Grabhügelkammern, um die Relikte der Druiden zu rauben. Unter dem Steinkrallengipfel stellen sie sich Schutzvorrichtungen, die diese Schätze sichern sollen.",h="Beim Krallenbau schickt Braelyn Feuerhand Champions der Horde in verborgene Grabhügelkammern, um die Relikte...",kw={"grabhügelschlüssel","braelyn feuerhand","cenarius' legacy","klauenschlüssel","torhüterschlüssel","ordanus","schlüssel des schläfers","der steinkrallengipfel","krallenbau","talon den hoard"},ang={["class:Druid"]="Als Taurendruide der Horde steht Ihr vor einer bitteren Ironie. Schlüssel, die nach Schläfern, Klauen und Grabhügeln benannt sind, wenden die Schutzvorrichtungen des Grabhügels gegen andere Cenarion-Wächter.",["class:Rogue"]="Als Schurke verlasst Ihr Euch auf geschicktes Einschleichen und Täuschung, um die schattigen Hallen zu durchqueren und Schlüssel aus verborgenen Laternen und Fackelhalterungen zu entwenden.",["faction:Horde"]="Der Überfall auf den Krallenbau schwächt die Verteidigung der Nachtelfen auf dem Steinkrallengipfel, sichert die Bergzugänge und bringt mächtige magische Relikte in die Hände der Horde.",["race:NightElf"]="Als Nachtelf erlebt Ihr die Entweihung des Krallenbaus. Der uralte Schlaf der Cenarion-Wächter wird gestört, und ihre durch Schutzzauber versiegelten Relikte werden geplündert."},sec={{t="Unterirdische Geheimnisse",b="Der Krallenbau liegt hoch im Steinkrallengebirge, wo Nachtelfendruiden in Hallen tief im lebendigen Fels Zuflucht finden. Seine Grabhügelkammern schützen meditierende Wächter und heilige Schätze. Braelyn Feuerhand weiß, was darin liegt, und verhört einen gefangenen Druiden, um zu erfahren, wie die Schutzvorrichtungen funktionieren."},{t="Die gestaffelten Schlösser",b="Nachtelfendruiden schützen ihre Relikte mit einer Reihe von Schlössern. Eine Laterne am Grabhügeleingang verbirgt den Torhüterschlüssel, der drei Verstecke tiefer im Inneren öffnet. Diese Verstecke enthalten den Schlüssel des Schläfers, den Klauenschlüssel und den Grabhügelschlüssel. Dreht alle drei behauenen Steine im zentralen Hort, und die druidischen Siegel brechen, sodass die uralten Gegenstände in die Hände der Horde fallen."}},faq={{q="Was ist der Krallenbau?",a="Der Krallenbau ist ein Grabhügelkomplex der Nachtelfen, der in die Höhen des Steinkrallengipfels gehauen wurde. Seine Hallen beherbergen ruhende Druiden und schützen ihre heiligen Relikte.",al={"wo ist der krallenbau","was ist der bau","grabhügelbau im steinkrallengebirge"}},{q="Wer befiehlt die Infiltration des Krallenbaus?",a="Braelyn Feuerhand leitet die Infiltration, eine Agentin der Sin'dorei, die im Steinkrallengebirge mit der Horde zusammenarbeitet. Nachdem sie einen gefangenen Druiden über die Schutzvorrichtungen des Heiligtums verhört hat, schickt sie Agenten der Horde zu dessen Hort.",al={"wer vergibt die quest der bau","braelyn feuerhands absicht","wer schickte mich zum bau"}},{q="Wie funktionieren die Schlüssel im Bau?",a="Der Torhüterschlüssel liegt in einer Laterne nahe dem Eingang. Er öffnet drei Verstecke im Grabhügel, die den Schlüssel des Schläfers, den Klauenschlüssel und den Grabhügelschlüssel enthalten. Dreht alle drei behauenen Steine im Hort, um seine Schutzzauber aufzulösen.",al={"wie den talon den hoard öffnen","verwendung des torhüterschlüssels","drei schlüssel im steinkrallengebirge"}},{q="Warum werden die Druiden auf dem Steinkrallengipfel angegriffen?",a="Braelyn Feuerhand will den Magiefluss der Gegend wiederherstellen und beschuldigt die Druiden des Steinkrallengipfels und die Söhne von Cenarius, ihn zu blockieren. Sie lässt die Druiden töten, darunter ihren Anführer Keeper Ordanus, den sie nach eigenen Angaben einst kannte. Dann schickt sie Euch los, um den Bau seiner mächtigen Gegenstände zu berauben.",al={"warum die druiden im steinkrallengebirge angreifen","grund der horde für ordanus' tötung","warum den bau plündern"}},{q="Was befindet sich im Talon Den Hoard?",a="Der Talon Den Hoard birgt mächtige Relikte und Schätze, die von den Nachtelfendruiden zusammengetragen wurden. Seine Schutzzauber bewahrten sie vor fremden Eindringlingen, bis Braelyn die Abfolge zur Überwindung der Schutzvorrichtungen durch Zwang erfuhr.",al={"hintergrund zur beute im talon den hoard","was ist im hort","was versteckten die druiden"}},{q="Was geschah unmittelbar vor dieser Quest?",a="Bevor Ihr in den Bau eindringt, werden Abenteurer der Horde ausgesandt, um die Präsenz der Nachtelfen in Cenarius' Legacy zu untersuchen und Keeper Ordanus zu ermorden. Das schwächt die Führung der Verteidiger.",al={"questreihe der bau","was führt zum bau","voraussetzungen für der bau"}}},fx={["48aeb852"]={q="Warum will Braelyn Feuerhand, dass der Hort geplündert wird?",a="Braelyn Feuerhand möchte den magischen Fluss um den Steinkrallengipfel wiederherstellen und sie beschuldigt die Druiden und die Söhne des Cenarius, ihn zu blockieren. Nachdem sie sah, wie Wächter Ordanus erschlagen wurde, und einem der Druiden die Geheimnisse der Schutzzauber des Baus entlockt hat, schickt sie Euch aus, um den Krallenbau von den mächtigen Gegenständen zu befreien, die sie dort verborgen halten.",al={"braelyns motiv","warum den bau ausrauben","warum den krallenbau bestehlen"}},["6c65008b"]={q="Wozu dient der Schlüssel des Schläfers?",a="Der Schlüssel des Schläfers ist einer von drei Schlüsseln, die die Nachtelfendruiden versteckten, um ihre wertvollsten Relikte zu schützen. Er liegt in einem Versteck tief im Krallenbau und muss zusammen mit seinen Schwesterschlüsseln in den alten Steinverriegelungsmechanismus eingefügt werden, um den Hort des Krallenbaus zu entsiegeln.",al={"nutzung schlüssel des schläfers","zweck schlüssel des schläfers","was öffnet der schlüssel des schläfers"}},["1086853e"]={q="Wozu dient der Klauenschlüssel?",a="Der Klauenschlüssel ist einer der drei Schlüssel, die die Druiden des Steinkrallengebirges rund um den Bau versteckt haben. Er wird in einem fackelartigen Behältnis aufbewahrt, das nur mit dem Torhüterschlüssel geöffnet werden kann. Er dient als zweite Komponente des dreifachen Schlosses, das den zentralen Hort des Krallenbaus sichert.",al={"nutzung klauenschlüssel","zweck klauenschlüssel","was öffnet der klauenschlüssel"}},["6ca48c55"]={q="Wozu dient der Grabhügelschlüssel?",a="Der Grabhügelschlüssel ist das dritte Teil des komplexen Sicherheitssystems, das von den Druiden des Steinkrallengebirges entwickelt wurde. Er ist in einem Fackelversteck zwischen den tiefen Wurzeln und Grabhügeln verborgen und wirkt zusammen mit dem Klauen- und dem Schlüssel des Schläfers, um die schützenden Verzauberungen um die Truhe des Horts aufzuheben.",al={"nutzung grabhügelschlüssel","zweck grabhügelschlüssel","was öffnet der grabhügelschlüssel"}}},fp="7,192,20.301.0,17.352.1,22.151.0,45.229.0,36.224.0,53.292.0,35.182.0,38.184.0"}
P.entries["quest:109"] = {n="Meldung bei Gryan Starkmantel",s="Auf der Späherkuppe sammelt Gryan Starkmantel Westfalls Verteidiger gegen die Bedrohungen der Bauernhöfe.",h="Auf der Späherkuppe sammelt Gryan Starkmantel Westfalls Verteidiger gegen die Bedrohungen der Bauernhöfe.",kw={"defias","elwynn","gryan starkmantel","marschall dughan","volksmiliz","späherkuppe","sturmwind","westfall"},ang={["class:Warrior"]="Als Krieger bringt Ihr die bewährte Disziplin mit, die Gryan Starkmantel schätzt, und seid damit ein wichtiger Kämpfer für die zahlenmäßig unterlegene Volksmiliz.",["faction:Alliance"]="Als Mitglied der Allianz seht Ihr, wie einfache Bürger Milizen gründen, um zu überleben, während der königliche Hof in Sturmwind über Politik streitet.",["race:Human"]="Als Mensch aus dem Königreich seht Ihr die Kluft zwischen den sicheren Marmorstraßen Sturmwinds und dem rauen, vernachlässigten Farmland jenseits der Stadt."},sec={{t="Ein Hilferuf über den Fluss",b="Wachen entlang der Grenze zu Elwynn und nach Westen vertriebene Bauern schicken fähige Reisende zur Späherkuppe. Wer dem Ruf folgt, schließt sich einer Verteidigung aus örtlichen Freiwilligen an. Keine königlichen Bataillone kommen ihnen zu Hilfe."},{t="Späherkuppe und die Miliz",b="Vom Steinturm auf der Späherkuppe aus vereint Gryan Starkmantel Bauern, Veteranen im Ruhestand und Söldner zur Volksmiliz. Ihr schließt Euch ihrem erbitterten Guerillakrieg an, um Westfalls Farmland vor der Gesetzlosigkeit zu bewahren."}},faq={{q="Wer ist Gryan Starkmantel?",a="Gryan Starkmantel ist ein kampferprobter Veteran, der die Volksmiliz befehligt. Vom Turm auf der Späherkuppe aus organisiert er Westfalls Verteidigung und sammelt Kämpfer, um die Bauern vor Banditen und wilden Tieren zu schützen.",al={"gryan starkmantel","wer ist starkmantel","anführer der späherkuppe"}},{q="Warum wird die Volksmiliz gebraucht?",a="Die Volksmiliz wird gebraucht, weil sich Sturmwinds Armee der Hauptstadt zugewandt hat und Westfall kaum Unterstützung von der Krone erhält. Die Bewohner gründeten die Miliz, um sich gegen Banditen, außer Kontrolle geratene Ernteautomaten und marodierende Riverpaw-Gnolle zu verteidigen.",al={"warum miliz","warum keine armee aus sturmwind","warum ist westfall verlassen"}},{q="Wo liegt die Späherkuppe?",a="Die Späherkuppe liegt nahe der Mitte Westfalls an der Hauptstraße. Ihr mächtiger steinerner Wachturm und das befestigte Lager sind Sammelplätze der Volksmiliz.",al={"späherkuppe finden","lage der späherkuppe","wo ist starkmantel zu finden"}},{q="Wer schickt Abenteurer auf diesen Auftrag?",a="Marschall Dughan in Goldhain, Grenzwachen wie Wache Thomas und Stellvertreter Rainer sowie vertriebene Bauern wie Bauer Brauenwirbel und Bauer Saldean schicken fähige Kämpfer zu Gryan.",al={"wer vergibt die quest","questgeber","meldung bei gryan questgeber"}},{q="Was geschieht nach der Meldung bei Gryan?",a="Wenn Ihr Euch bei Starkmantel meldet, setzt er Euer Kampfgeschick für die Volksmiliz ein. Eure ersten Aufträge richten sich gegen die Defias-Briganten und Gnolle, die Westfall bedrohen.",al={"was kommt als nächstes","starkmantel folgequest","miliz questreihe"}},{q="Gehört Westfall formell noch zur Allianz?",a="Ja. Westfall bleibt Gebiet der Allianz unter der nominellen Herrschaft des Königreichs Sturmwind. Die Garnison der Krone vernachlässigt die Provinz und überlässt ihre Verteidigung bewaffneten Bürgern.",al={"gehört westfall zur allianz","gehört westfall zu sturmwind"}}},fx={a1beb42d={q="Warum werdet Ihr gebeten, den Auftrag Report to Gryan Stoutmantle zu erfüllen?",a="Da sich Sturmwind militärisch nach innen konzentriert und Westfall weitgehend Banditen und Plünderern überlässt, sind die Leute, die dort die Stellung halten, dünn gesät. Gryan Starkmantel und seine Volksmiliz brauchen dringend erfahrene Kämpfer, um das, was vom Ackerland übrig ist, zu verteidigen. Diejenigen, die Euch von Elwynn aus schicken, erkennen, dass Eure Kampfkraft bei der Patrouille friedlicher Obstgärten kläglich verschwendet ist, während das benachbarte Westfall vollständig im Chaos versinkt.",al={"warum bericht an starkmantel erstatten","warum westfall","warum dughan westfall starkmantel"}},e97846b7={q="Warum benötigt Gryan Starkmantel unabhängige Abenteurer anstelle von Wachen aus Sturmwind?",a="Die Monarchie von Sturmwind hat sich geweigert, reguläre Armeeverstärkungen nach Westfall zu schicken, wodurch die Provinz faktisch von der Krone verlassen wurde. Die örtlichen Wachen und Milizen können mit der schieren Menge an Banditen, Gnollen und Gesetzlosen, die die Farmen überrennen, nicht fertig werden. Gryan Starkmantel muss sich auf fähige reisende Mercenaries und Abenteurer wie Euch verlassen, die echte Kampferfahrung bewiesen haben und bereit sind, für ihre Sache zu den Waffen zu greifen.",al={"warum ich westfall","warum abenteurer anstatt armee","warum braucht die volksmiliz hilfe"}}},fp="27,94,23.204.0,29.234.0,25.210.0,35.272.0,31.162.0,41.179.0,38.176.0,51.175.0"}
P.entries["quest:1090"] = {n="Gerenzos Befehle",s="An der Ausgrabungsstätte der Venture Company im Steinkrallengebirge arbeitet Piznik gegen seinen neuen Boss Gerenzo. Der entmachtete Goblin gräbt eine Probe aus, um die Erzförderung aufzudecken, während ein Verbündeter ihn vor Patrouillen im Lager schützt.",h="An der Ausgrabungsstätte der Venture Company im Steinkrallengebirge arbeitet Piznik gegen seinen neuen Boss...",kw={"gerenzo","goldgrünes erz","geheimnisvolles erz","piznik","steinkrallengebirge","venture company","die scherwindklippe","ziz fizziks"},ang={["faction:Horde"]="Der rücksichtslose, tief in die Natur eingreifende Bergbau der Venture Company verwüstet die Landschaft des Steinkrallengebirges. Ihre Betriebe zu überwachen, zu stören oder auszunutzen, kann den Streitkräften der Horde in der Nähe helfen.",["profession:Mining"]="Das seltsame goldgrüne Erz, das Bergleute der Venture Company im Steinkrallengebirge gefunden haben, entspricht weder Eisen- noch Zinnadern. Das weckt das Interesse von Erzsuchern, die neugierig auf seltene Mineralien sind."},sec={{t="Verrat an der Scherwindklippe",b="An der Scherwindklippe belohnt die Venture Company Rücksichtslosigkeit mehr als Loyalität. Piznik war einst der stellvertretende Leiter der Ausgrabung. Dann riss Gerenzo die Macht an sich, entließ Aufseher Ziz Fizziks und schickte Piznik mit einer Spitzhacke zurück in die Minen. Doch Piznik blieb. Auf Ziz' Anweisung wurde er zum Informanten, beobachtete jeden Schritt Gerenzos und wartete auf eine Gelegenheit, gegen den Aufseher zurückzuschlagen, der ihn verdrängt hatte."},{t="Die goldgrüne Ader freilegen",b="Gerenzos Machtübernahme begann mit einer Obsession: seltsames goldgrünes Erz im Gestein des Steinkrallengebirges. Er glaubt, das Mineral sei eine außergewöhnliche Summe wert, und befahl den Bergleuten, es in riesigen Mengen aus der Erde zu reißen. Ziz Fizziks hat nun einen geheimnisvollen Arbeitgeber, der für Neuigkeiten über das Vorhaben womöglich gut bezahlt. Deshalb riskiert Piznik, entdeckt zu werden, um eine Probe auszugraben. Ein Verbündeter hält aggressive Schürfer, Ungeziefer und Aufseher ab, die den Betrieb überwachen."}},faq={{q="Wer ist Piznik?",a="Piznik ist ein Goblinarbeiter im Betrieb an der Scherwindklippe im Steinkrallengebirge. Einst stand er im Rang direkt unter Ziz Fizziks. Dann übernahm Gerenzo die Kontrolle und degradierte ihn zum Minenarbeiter.",al={"piznik","wer ist der goblinbergmann","piznik steinkrallengebirge"}},{q="Warum baut Piznik dieses Erz heimlich ab?",a="Piznik sammelt heimlich eine Probe des seltsamen goldgrünen Erzes, dessen Abbau Gerenzo in riesigen Mengen angeordnet hat. Sein früherer Boss Ziz Fizziks sagt, ein neuer Arbeitgeber werde für Informationen über Gerenzos wertvollen Betrieb gut bezahlen.",al={"warum erz abbauen","geheimnisvolles erz","goldgrünes erz"}},{q="Wer ist Gerenzo?",a="Gerenzo ist der rücksichtslose Aufseher der Venture Company, der durch die Entlassung von Ziz Fizziks die Kontrolle über die Ausgrabung im Steinkrallengebirge übernahm. Er setzte die Mittel der Firma für den Abbau eines unbekannten goldgrünen Erzes ein, das überall an der Klippe vorkommt.",al={"gerenzo","wer ist gerenzo","gerenzo venture company"}},{q="Für wen arbeitet Ziz Fizziks jetzt?",a="Nachdem Gerenzo Ziz Fizziks entlassen hatte, verbündete sich Ziz mit neuen Geldgebern, die die Aktivitäten der Venture Company in der Region überwachen wollen. Ziz bezahlt Agenten und Informanten wie Piznik dafür, Gerenzo zu sabotieren und herauszufinden, was die Firma ausgräbt.",al={"ziz neuer boss","wer hat ziz angeheuert","ziz arbeitgeber"}},{q="Was greift Piznik beim Graben an?",a="Arbeiter der Venture Company greifen Piznik beim Graben an. Dazu gehören Windshear Tunnel Rats, Windshear Vermin, Schürfer, Geomanten, Steinmetze und Aufseher.",al={"piznik hinterhalt","wer greift piznik an","scherwindklippe patrouillen"}},{q="Was geschieht, sobald die Probe abgebaut ist?",a="Nachdem Piznik die Erzprobe gewonnen hat, gibt er sie seinem Beschützer, damit dieser sie direkt zu Ziz Fizziks bringt. Er hofft, dass die Probe Ziz ein Druckmittel verschafft, um Gerenzos Pläne zu vereiteln.",al={"wohin das erz bringen","was mit der probe tun"}}},fx={["0d43f256"]={q="Warum braucht Piznik Eure Hilfe, anstatt das Erz selbst abzubauen?",a="Piznik wird von Arbeitern der Venture Company an der Grabungsstätte beobachtet. Er braucht einen Verbündeten, der die Patrouillen aufhält, während er eine Erzprobe für Ziz Fizziks extrahiert.",al={"warum braucht piznik mich","warum piznik helfen","warum kann piznik nicht allein minern"}}},fp="16,201,30.408.0,30.427.0,14.187.0,39.220.0,15.218.0,34.234.0,34.153.0,38.172.0"}
P.entries["quest:1091"] = {n="Kaelas Update",s="Gaxim Rostknirsch schickt Euch mit erbeuteten Briefen der Venture Company zu Kaela Schattenspeer zurück. Ihr Inhalt hilft den Schildwachen, die Arbeit des Goblinkartells im Steinkrallengebirge zu verfolgen.",h="Gaxim Rostknirsch schickt Euch mit erbeuteten Briefen der Venture Company zu Kaela Schattenspeer zurück.",kw={"gaxim rostknirsch","kaela schattenspeer","kaelas update","briefe","schildwachen","der steinkrallengipfel","venture company"},ang={["faction:Alliance"]="Die Überbringung abgefangener Briefe der Venture Company stärkt den unsicheren Stützpunkt der Allianz im Steinkrallengebirge gegen die Plünderungen des Kartells.",["race:Gnome"]="Als Gnom könnt Ihr stolz auf Gaxim Rostknirschs arkane Fähigkeiten sein. Er sorgt dafür, dass seine nachtelfischen Verbündeten den Wert der Gnomenmagie erkennen.",["race:NightElf"]="Als Nachtelf helft Ihr mit jeder Information über die Venture Company den Schildwachen, Kalimdors gezeichnete Wildnis vor industriellen Schäden zu schützen."},sec={{t="Ein Bote im Gebirge",b="Gaxim Rostknirsch schickt Euch mit erbeuteten Briefen zu Kaela Schattenspeer zurück. Ihr habt dem Gnommagier geholfen, die Bewegungen der Venture Company aufzudecken, und er hat Korrespondenz über die Unternehmungen des Kartells gesammelt. Kaela, eine nachtelfische Koordinatorin der Schildwachen nahe der Scherwindklippe, wartet auf die Briefe. Gaxim bittet Euch außerdem, ihr zu erzählen, wie seine Magie bei den Ermittlungen geholfen hat."},{t="Augen der Schildwachen",b="Die Schildwachen beobachten die Klippen des Steinkrallengebirges mit Sorge. Streitkräfte der Horde kämpfen um die unteren Pfade, während die Venture Company Bäume fällt und Bodenschätze abbaut. Ihre Briefe zeigen Kaela, wie das Kartell kommuniziert, und helfen der Allianz, die Verteidigung entlang der Gebirgskämme zu planen."}},faq={{q="Wer ist Kaela Schattenspeer?",a="Kaela Schattenspeer ist eine nachtelfische Offizierin der Schildwachen in einem Lager nahe der Scherwindklippe. Sie beaufsichtigt die Aufklärung und die Verteidigung gegen die Horde und die Bergbauunternehmen der Goblins im Gebirge.",al={"kaela schattenspeer","wer ist kaela","kaela steinkrallengebirge"}},{q="Wer ist Gaxim Rostknirsch?",a="Gaxim Rostknirsch ist ein Gnommagier im Steinkrallengebirge. Er setzt Magie ein, um die Unternehmungen der Venture Company zu untersuchen und zu stören, und arbeitet dabei mit den örtlichen Schildwachen der Nachtelfen zusammen.",al={"gaxim","gaxim rostknirsch","gnommagier steinkrallengebirge"}},{q="Was steht in den Briefen der Venture Company?",a="Die Briefe enthalten Mitteilungen der Venture Company, die bei Einsätzen gegen ihre Lager abgefangen wurden. Sie geben Kaela Schattenspeer und den Schildwachen Auskunft über die örtliche Logistik, die Ausgrabungen und die Ausbeutung der Rohstoffe durch das Kartell.",al={"venture company briefe","was sind die briefe","briefe für kaela"}},{q="Warum bereitet die Venture Company den Schildwachen Sorgen?",a="Die Venture Company holzt heilige Wälder ab und gräbt mit schweren Maschinen im Erdreich. Die Schildwachen sehen ihre industrielle Arbeit als Bedrohung für die Natur und die Heiligkeit des Steinkrallengebirges.",al={"warum sind goblins wichtig","schildwachen venture company","venture company steinkrallengebirge"}},{q="Wo beginnt und endet diese Quest?",a="Ihr beginnt bei Gaxim Rostknirsch an den Gebirgspfaden und endet bei Kaela Schattenspeer in ihrem Lager nahe der Scherwindklippe.",al={"questort","kaelas update abgeben","wo ist kaela"}},{q="Führt diese Quest zu weiteren Ermittlungen?",a="Die Zustellung der Briefe hält die Schildwachen über die Aktivitäten des Kartells auf dem Laufenden. Kaela kann dieses Wissen nutzen, um weitere militärische Gegenmaßnahmen und Erkundungen im gesamten Steinkrallengebirge zu planen.",al={"nächste quest","was kommt nach kaelas update","folgequest"}}},fx={["94a820b1"]={q="Warum möchte Gaxim Rostknirsch, dass Ihr die Briefe überbringt?",a="Gaxim möchte sicherstellen, dass die Nachtelf-Wächterinnen über die Pläne der Venture Company informiert sind, aber er ist ebenso bestrebt, sich den Erfolg zuzuschreiben. Er drängt Euch, Kaela Schattenspeer zu sagen, dass die Mission dank seiner magischen Tüfteleien erfolgreich war.",al={"warum briefe ausliefern","gaxim rostknirsch motiv","warum briefe an kaela schicken"}}},fp="14,177,28.368.0,21.253.0,25.179.0,24.174.0,39.218.0,58.168.0,36.126.0,47.176.0"}
P.entries["quest:1092"] = {n="Gerenzos Befehle",s="An der Scherwindklippe schickt Piznik eine Erzprobe aus den Abbaustätten der Venture Company an Ziz Fizziks, seinen Kontaktmann außerhalb der Ausgrabungsstätte. Die Lieferung beendet einen gefährlichen Akt der Spionage.",h="An der Scherwindklippe schickt Piznik eine Erzprobe aus den Abbaustätten der Venture Company an Ziz Fizziks...",kw={"gerenzos befehle","piznik","steinkrallengebirge","undermine","nicht identifiziertes erz","venture company","die scherwindklippe","ziz fizziks"},ang={["profession:Engineering"]="Gobliningenieure in Undermine zahlen gut für unverhüttete exotische Erze, die unberechenbare neue Mechanismen und Prototypen antreiben können.",["profession:Mining"]="Das auf Gerenzos Befehl abgebaute Nicht identifizierte Erz zeigt, dass die Arbeit der Venture Company an der Scherwindklippe über die Abholzung hinausgeht. Sie durchsucht die Berge auch nach unbekannten unterirdischen Reichtümern."},sec={{t="Ein Weg hinaus",b="Pizniks Tarnung an der Scherwindklippe ist aufgeflogen, und er kann nicht länger bei der Mannschaft der Venture Company bleiben. Die Unternehmensleitung in Undermine bestraft Sabotage in den eigenen Reihen, also plant der nervöse Goblin, sich davonzumachen und einen anderen Arbeitgeber zu finden.\n\nBevor er aufbricht, übergibt Piznik einem Außenstehenden das Nicht identifizierte Erz, das auf Gerenzos Befehl abgebaut wurde. Die Probe muss ihr Ziel erreichen, ohne Verdacht auf ihn zu lenken."},{t="Kuriositäten des Konzerns",b="Ziz Fizziks wartet an einem geheimen Außenposten am westlichen Rand der Scherwindklippe. Er erkennt den Wert des Minerals und plant, es nach Süden zu Ingenieuren in Undermine zu schicken, während er heimlich einen wertvollen Teil für sich behält.\n\nSein Plan spiegelt die erbitterten Handels- und Ingenieursstreitigkeiten wider, die unter dem Steinkrallengebirge schwelen."}},faq={{q="Warum muss Piznik von der Scherwindklippe fliehen?",a="Pizniks Tarnung flog auf, als die Aufseher der Ausgrabungsstätte ihn dabei ertappten, wie er heimlich eine Erzprobe für Ziz abbaute. Er fürchtet rasche Vergeltung, sobald die Vorgesetzten der Venture Company davon erfahren, also muss er sich davonmachen und eine neue Anstellung finden.",al={"warum geht piznik fort","piznik auf der flucht","warum hat piznik angst"}},{q="Wer ist Ziz Fizziks?",a="Ziz Fizziks ist ein goblinischer Drahtzieher, der auf dem westlichen Höhenzug der Scherwindklippe lagert. Er schleuste Piznik in die Venture Company ein, um Firmengeheimnisse und seltene Mineralproben zu stehlen.",al={"wer ist ziz","ziz fizziks rolle","wo ist ziz"}},{q="Was ist das Nicht identifizierte Erz?",a="Das Nicht identifizierte Erz ist eine Probe des geheimnisvollen goldgrünen Erzes, dessen Abbau in großen Mengen Chefingenieur Gerenzo angeordnet hat. Ziz plant, es an Ingenieure und Forscher in Undermine zu schicken, damit sie seine industriellen Verwendungsmöglichkeiten untersuchen.",al={"nicht identifiziertes erz hintergrund","was ist das erz","gerenzo erz"}},{q="Wo ist Ziz Fizziks zu finden?",a="Ziz Fizziks befindet sich in einem kleinen Lager am westlichen Rand mit Blick auf die Scherwindklippe im Steinkrallengebirge.",al={"ziz fizziks aufenthaltsort","ziz finden","wo gerenzos befehle abgeben"}},{q="Was geschieht mit dem Erz, sobald Ziz es erhält?",a="Ziz plant, den Großteil der Erzprobe an Ingenieure in Undermine zu schicken, während er heimlich einen kleinen Splitter für sich behält.",al={"was macht ziz mit dem erz","behält ziz das erz"}},{q="Ist Piznik der Venture Company treu ergeben?",a="Piznik arbeitete nur für die Venture Company, um Ziz' Interessen zu dienen. Er hegt keinerlei Treue zum Syndikat und fürchtet Vergeltung durch dessen Führung.",al={"piznik fraktion","gehört piznik zur venture company","für wen arbeitet piznik"}}},fx={["692a35ea"]={q="Warum lässt Piznik Euch das Erz ausliefern, anstatt es selbst zu nehmen?",a="Piznik kann nicht sofort gehen, da er Zeit braucht, um seine Spuren zu verwischen und das Chaos zu beseitigen, das er hinterlassen hat, bevor er sich von der Venture Company davonschleicht. Da sich die Nachricht von dem Vorfall schnell bis zu seinen Vorgesetzten verbreiten wird, vertraut er Euch das Nicht identifizierte Erz an, damit es sicher und ohne Verzögerung Ziz Fizziks erreicht.",al={"warum schickt piznik mich","warum kann piznik das erz nicht ausliefern","warum ich piznik"}}},fp="16,176,12.394.0,21.309.1,44.228.0,19.176.0,29.210.0,31.112.0,45.114.0,39.146.0"}
P.entries["quest:1093"] = {n="Superschnitter 6000",s="In der Scherwindklippe hofft Ziz Fizziks, die Gunst seines neuen Chefs Stotterspritter zu gewinnen. Er will die Pläne der Venture Company für eine gewaltige Holzfällermaschine, die sein Rivale Gerenzo Pfeifzang entworfen hat.",h="In der Scherwindklippe hofft Ziz Fizziks, die Gunst seines neuen Chefs Stotterspritter zu gewinnen.",kw={"baupläne","gerenzo wrenchwhistle","stotterspritter","steinkrallengebirge","superschnitter 6000","venture company","die scherwindklippe","ziz fizziks"},ang={["profession:Engineering"]="Gobliningenieurskunst setzt auf Geschwindigkeit und groben Pragmatismus. Gnomische Konstruktionen legen Wert auf Präzision und Komplexität, und die Rivalität zwischen beiden sitzt tief.",["race:Gnome"]="Als Gnom versteht Ihr vielleicht, warum Ziz bezweifelt, dass ein Goblinsyndikat einem Euresgleichen seine bedeutendsten Maschinen anvertrauen würde. Gerenzos technische Entwürfe lassen ihn ratlos zurück.",["race:NightElf"]="Als Nachtelf seht Ihr, wie der Superschnitter 6000 im Steinkrallengebirge uralte Bäume für industriellen Profit fällt. Er ist ein deutliches Zeichen der Missachtung der Natur durch die Sterblichen."},sec={{t="Industriespionage in der Scherwindklippe",b="In der Scherwindklippe trägt die Venture Trading Company Teile des Steinkrallengebirges ab, um ihren Holzfällerbetrieb zu versorgen. Ziz Fizziks, ein aus dem Unternehmen verstoßener Gobliningenieur, arbeitet nun für Stotterspritter. Er hofft, seinen Wert zu beweisen, indem er die Pläne für die gewaltige automatische Holzfällermaschine des Unternehmens stiehlt, den Superschnitter 6000."},{t="Goblintechnik gegen Gnomeningenieurskunst",b="Gerenzo Wrenchwhistles Ernennung zum örtlichen Leiter der Ingenieure der Venture Company wurmt Ziz. Das Unternehmen wird größtenteils von Goblins geführt, doch es hat einem Gnom die Leitung seiner Ingenieursabteilung übertragen. Als die Konstruktionszeichnungen der Maschinenbediener Ziz erreichen, frustriert ihn ihr komplizierter Aufbau. Er bevorzugt rohe Gewalt, billige Teile und unberechenbare Verbrennung. Gerenzos sorgfältige Pläne sind für ihn schwer zu verstehen."}},faq={{q="Wer ist Ziz Fizziks?",a="Ziz Fizziks ist ein Gobliningenieur im Steinkrallengebirge. Die Venture Company hat ihn vor Kurzem entlassen, und Stotterspritter stellte ihn bald darauf ein. Nun will sich Ziz an seinen früheren Arbeitgebern rächen.",al={"ziz fizziks","wer ist der questgeber","ziz"}},{q="Was ist der Superschnitter 6000?",a="Der Superschnitter 6000 ist eine riesige mechanische Holzfällermaschine, die für den Holzfällerbetrieb der Venture Company in der Scherwindklippe entworfen wurde.",al={"superschnitter 6000","was ist der superschnitter","was ist das für eine maschine"}},{q="Wer hat den Superschnitter 6000 entworfen?",a="Gerenzo Pfeifzang, ein von der Venture Company angeheuerter Gnomtüftler, hat den Superschnitter 6000 entworfen. Seine Ernennung kränkt die Gobliningenieure zutiefst, die einst den Betrieb leiteten.",al={"wer hat den superschnitter erschaffen","wer hat die maschine gebaut","gerenzo wrenchwhistle"}},{q="Warum will Stotterspritter die Baupläne?",a="Stotterspritter will die schwere Holzfällertechnik der Venture Company. Ziz hofft, ihm die Pläne zu bringen und seinem neuen Arbeitgeber seinen Wert zu beweisen.",al={"warum die pläne stehlen","stotterspritter baupläne"}},{q="Wo sind die Baupläne zu finden?",a="Maschinenbediener der Venture Company tragen die Konstruktionszeichnungen bei sich, während sie die Holzfällermaschinen in der Scherwindklippe beaufsichtigen.",al={"wo sind die pläne zu finden","wer lässt die baupläne fallen"}},{q="Warum fällt es Ziz schwer, die beschafften Baupläne zu lesen?",a="Ziz hat Schwierigkeiten mit den Plänen, weil sich die Ingenieurskunst der Goblins und Gnome unterscheidet. Gerenzo Wrenchwhistles akribische Zeichnungen sind für Ziz zu verwirrend, um sie auf einen Blick zu entschlüsseln.",al={"warum kann ziz die pläne nicht lesen","gnom baupläne goblin"}}},fx={["1ca65bff"]={q="Warum möchte Ziz Fizziks, dass dies erledigt wird?",a="Ziz wurde kürzlich aus der Venture Company rausgeschmissen, aber Stotterspritter stellte ihn kurz darauf ein. Indem er die Baupläne für die massive neue Holzfällermaschine der Venture Company sichert, hofft Ziz, seine Loyalität gegenüber seinem neuen Arbeitgeber zu beweisen und Stotterspritter davon zu überzeugen, sein technisches Genie endlich einzusetzen.",al={"warum will ziz die baupläne","ziz fizziks motiv","warum stotterspritter helfen"}},f1f026be={q="Wozu dienen die Superschnitter-6000-Blaupause?",a="Die Baupläne beschreiben die inneren Abläufe und das Design des Super Reaper 6000, einer riesigen Holzfällermaschine, die für die Abholzungsarbeiten der Venture Company entwickelt wurde. Stotterspritter möchte, dass sie gestohlen werden, um die Technologie zu verstehen, und Ziz muss sie studieren, um diesen Vertrag zu erfüllen.",al={"wofür sind die baupläne","superschnitter-6000-bauplan zweck","warum die baupläne stehlen"}},c62989dc={q="Warum kann Ziz Fizziks die Baupläne nicht selbst stehlen?",a="Ziz ist auf dem Holzfällergelände der Venture Company eine Persona non grata. Ihr Chefingenieur, ein Gnom namens Gerenzo Pfeifzang, hat befohlen, ihn bei Sichtung zu töten. Das Lager selbst zu betreten, würde seine sofortige Hinrichtung bedeuten, was einen fähigen Abenteurer zur einzigen praktikablen Option für den Raub macht.",al={"warum stiehlt ziz sie nicht","warum braucht ziz mich","warum kann ziz nicht gehen"}},["6f0e6bcb"]={q="Wer trägt die Baupläne des Super Reaper bei sich?",a="Die Arbeiter der Venture Company, die den Holzfällereibetrieb beaufsichtigen, tragen die Schaltpläne bei sich. Diese Arbeiter bedienen die Maschinen und leiten die Kahlschlagarbeiten im Bereich des Felskesselsee unter der Leitung von Gerenzo Pfeifzang, wobei sie die Pläne stets griffbereit haben, um die Schnitter zu verwalten und zu warten.",al={"wer hat die baupläne","gegen wen kämpfe ich für die baupläne","wer trägt die super reaper pläne"}}},fp="17,199,38.328.0,31.393.1,19.186.0,30.136.0,35.176.0,42.142.0,31.116.0,60.172.1"}
P.entries["quest:1094"] = {n="Weitere Instruktionen",s="Ziz Fizziks schickt gestohlene Pläne der Venture Company von der Scherwindklippe nach Ratschet. Sie könnten seinem Rivalen Stotterspritter einen Vorteil verschaffen.",h="Ziz Fizziks schickt gestohlene Pläne der Venture Company von der Scherwindklippe nach Ratschet.",kw={"brachland","weitere instruktionen","ratschet","stotterspritter","steinkrallengebirge","super reaper 6000","venture company","ziz fizziks"},ang={["faction:Horde"]="Der Transport gestohlener Pläne der Venture Company nach Ratschet schürt Handelsrivalitäten, die der industriellen Expansion nahe dem Gebiet der Horde entgegenwirken.",["profession:Engineering"]="Der Umschlag trägt die Spuren der Goblinindustrie: Wirtschaftsspionage, Patentdiebstahl und der Nachbau komplexer Holzerntemaschinen."},sec={{t="Wirtschaftsspionage",b="Ziz Fizziks trägt die Geheimnisse der Venture Company von der Scherwindklippe fort. Das Unternehmen schloss ihn aus seinem Holzfällerbetrieb aus, und er nahm vertrauliche Dokumente mit. Er versiegelte interne Handbücher und technische Zeichnungen in einem Umschlag, der für Ratschet bestimmt war. Darunter sind Baupläne für den experimentellen Super Reaper 6000. Verbittert über seine Entlassung hofft Fizziks, einen Käufer oder Verbündeten zu finden, der das Diebesgut nutzen will."},{t="Die Verbindung nach Ratschet",b="In Ratschet, dem neutralen Hafen im Brachland, wartet der Ingenieur Stotterspritter. Er hegt wenig Vertrauen oder Zuneigung für Fizziks, doch ihr gemeinsamer Rivale macht es schwer, das Angebot abzulehnen. Die mit Steamwheedle verbündeten Goblins suchen nach Wegen, die rücksichtslose Venture Company zu schwächen. Überlegene mechanische Erfindungen, auf die sie stoßen, bauen sie mit Begeisterung nach."}},faq={{q="Was steckt im Versiegelten Umschlag?",a="Der Umschlag enthält Dokumente der Venture Company, technische Handbücher und Baupläne für den Super Reaper 6000. Ziz Fizziks stahl sie, als das Unternehmen ihn aus seinem Holzfällerbetrieb vertrieb.",al={"inhalt des umschlags","was verschickt fizziks","gestohlene dokumente"}},{q="Wer ist Stotterspritter?",a="Stotterspritter ist ein Gobliningenieur in Ratschet im Brachland. Er misstraut Ziz Fizziks, will aber die Venture Company schwächen und ihre Maschinen studieren.",al={"stotterspritters identität","wer ist der empfänger","ingenieur in ratschet"}},{q="Warum arbeitet Ziz Fizziks gegen die Venture Company?",a="Die Venture Company verstieß Fizziks im Steinkrallengebirge aus ihren Reihen. Verbittert und auf Rache aus, begann er, ihre Betriebsgeheimnisse an Rivalen weiterzugeben.",al={"warum fizziks die venture company verriet","fizziks' beweggrund"}},{q="Wo ist Stotterspritter zu finden?",a="Stotterspritter befindet sich in Ratschet, einer neutralen Hafenstadt an der Ostküste des Brachlands.",al={"wo ist stotterspritter","stotterspritters aufenthaltsort","stotterspritter finden"}},{q="Vertraut Stotterspritter Ziz Fizziks?",a="Nein. Stotterspritter misstraut Fizziks, doch die Handbücher und Baupläne sind ihm wichtiger als seine Vorbehalte gegenüber dem Boten.",al={"vertraut stotterspritter fizziks","beziehung zwischen fizziks und stotterspritter"}},{q="Was ist der Super Reaper 6000?",a="Der Super Reaper 6000 ist ein fortschrittlicher Industrieschredder, den die Venture Company entwickelte, um Wälder zu roden und Holz schnell zu verarbeiten. Seine Baupläne sind heiß begehrt.",al={"super reaper 6000","was ist die maschine","venture company reaper"}}},fx={["98641ea6"]={q="Warum braucht Ziz Fizziks einen Abenteurer, um den Umschlag zu überbringen?",a="Ziz Fizziks versteckt sich im Steinkrallengebirge, nachdem er von der Venture Company verstoßen wurde. Seiner Position beraubt und umgeben von feindseligen ehemaligen Kollegen und den Gefahren der Schlucht, kann er die Reise quer durch Kalimdor nach Ratschet nicht sicher antreten. Die sensiblen Baupläne und gestohlenen Dokumente einem fähigen Reisenden anzuvertrauen, stellt sicher, dass die Informationen Stotterspritter erreichen, ohne sein eigenes Leben zu riskieren.",al={"warum ich weitere anweisungen","warum braucht ziz mich","warum kann ziz den umschlag nicht ausliefern"}}},fp="20,124,19.413.0,22.336.0,35.184.0,20.151.0,55.137.0,32.84.0,36.121.0,30.166.0"}
P.entries["quest:1095"] = {n="Weitere Instruktionen",s="Im Steinkrallengebirge überbringt Stotterspritter Ziz Fizziks einen Befehl aus Undermine. Gerenzo Pfeifzang, den Mogul Razdunk angeheuert hat, muss beseitigt werden.",h="Im Steinkrallengebirge überbringt Stotterspritter Ziz Fizziks einen Befehl aus Undermine.",kw={"weitere instruktionen","gerenzo wrenchwhistle","gnomeregan","razdunk","riddlevox","stotterspritter","steinkrallengebirge","undermine","venture company","ziz fizziks"},ang={["profession:Engineering"]="Als Ingenieur erlebt Ihr, wie die Rivalität zwischen gnomischer und goblinischer Ingenieurskunst vom Streit um Konstruktionspatente zum Mord im Unternehmensauftrag führt.",["race:Gnome"]="Als Gnom erfahrt Ihr, dass Gerenzo ein leitender Ingenieur in Gnomeregan war. Sein geheimes Experiment endete in einer katastrophalen Explosion, die die beteiligten Ingenieure traf."},sec={{t="Missbilligung der Konzernspitze",b="Die Handelsprinzen haben erfahren, dass Mogul Razdunk Gerenzo Pfeifzang angeheuert hat, und die Nachricht hat in Undermine für Unruhe gesorgt. Direktor Riddlevox weist Stotterspritter an, diskret einzugreifen. Im Glauben, der Befehl stamme von den höchsten Handelsautoritäten, überträgt Stotterspritter die Arbeit an Ziz Fizziks, den Agenten vor Ort."},{t="Geheimnisse von Dun Morogh",b="Ziz Fizziks begrüßt den Befehl, Gerenzo Pfeifzang zu töten. Gobliningenieure verachten ihre gnomischen Rivalen, und Gerenzos Vergangenheit macht ihn besonders unberechenbar. Bevor er sich der Venture Company anschloss, war er ein leitender Ingenieur in Gnomeregan. Dort arbeitete er an einem streng geheimen Projekt, das die Spione von Undermine nicht vollständig aufdecken konnten. Berichten zufolge endete das Projekt in einer Katastrophe und explodierte den Ingenieuren ins Gesicht. Nun verkauft Gerenzo sein gefährliches Fachwissen an die Venture Company in Kalimdor."}},faq={{q="Wer ist Stotterspritter?",a="Stotterspritter ist ein Goblinagent unter Direktor Riddlevox. Er überbringt Anweisungen aus Undermine und gibt Aufträge an Agenten im Außendienst wie Ziz Fizziks weiter.",al={"stotterspritter","wer gibt die quest","questgeber stotterspritter"}},{q="Warum interessieren sich die Handelsprinzen für Gerenzo?",a="Die Handelsprinzen von Undermine missbilligen, dass Mogul Razdunk einen gnomischen Ingenieur von außerhalb angeheuert hat. Sie sehen die Anstellung als Bedrohung für die industrielle Vorherrschaft der Goblins und als Anlass für unerwünschte Nachforschungen.",al={"warum interessiert es die handelsprinzen","ärger in undermine","gerenzo handelsprinzen"}},{q="An welchem geheimen Projekt arbeitete Gerenzo?",a="Gerenzo arbeitete als leitender Ingenieur an einem geheimen Projekt in Gnomeregan. Goblinspione konnten seinen Zweck nicht aufdecken, und Berichten zufolge endete es in einer Katastrophe und explodierte den Ingenieuren ins Gesicht.",al={"gerenzos geheimes projekt","gnomeregan explosion","gerenzos vergangenheit"}},{q="Wo befindet sich Ziz Fizziks?",a="Ziz Fizziks befindet sich im Steinkrallengebirge, wo er die örtlichen Holzfäll- und Bergbauarbeiten der Venture Company beobachtet und zugleich Konzernaufträge ausführt.",al={"ziz fizziks aufenthaltsort","wo ist ziz","wo befehle abliefern"}},{q="Warum will Ziz Fizziks Gerenzo unbedingt töten?",a="Ziz Fizziks teilt den beruflichen Hass der Goblins auf Gnome und sieht Gerenzo als gefährlichen Rivalen. Gerenzos Experimente in Dun Morogh endeten in einer Katastrophe.",al={"warum hasst ziz gerenzo","fizziks reaktion","warum gerenzo töten"}},{q="Wer ist Mogul Razdunk?",a="Mogul Razdunk führt die Venture Company. Er heuerte Gerenzo an, setzte sich damit über die Handelsetikette in Undermine hinweg und veranlasste die Handelsprinzen, auf Gerenzos Beseitigung zu drängen.",al={"mogul razdunk","wer ist razdunk","venture company chef"}}},fx={["36e39e8c"]={q="Warum möchte Stotterspritter, dass dies erledigt wird?",a="Stotterspritter erhielt Anweisungen direkt von Direktor Riddlevox, der auf den Druck der Handelsprinzen von Undermine reagiert. Mogul Razdunks Entscheidung, den Gnom Gerenzo Pfeifzang einzustellen, hat die Goblinführung empört. Um seine eigene Stellung zu schützen und die Forderungen seiner Vorgesetzten zu erfüllen, muss Stotterspritter Gerenzo eliminieren sehen, und er betrachtet die Weitergabe der Befehle an Ziz Fizziks als den idealen Weg, den Willen von Undermine auszuführen und gleichzeitig die Fähigkeiten von Fizziks zu testen.",al={"warum befehle senden","stotterspritter motiv","warum gerenzo töten"}}},fp="20,156,21.323.0,21.476.1,20.152.0,44.189.0,40.188.0,29.147.0,41.155.0,21.162.0"}
P.entries["quest:1096"] = {n="Gerenzo Pfeifzang",s="Über dem Felskesselsee wartet Gerenzo Pfeifzang im Steinkrallengebirge auf ein Kopfgeld. Der abtrünnige Gnomenaufseher hat einen Großteil seines verrottenden Fleisches durch Zahnräder, Uhrwerkmechanik und künstliche Gliedmaßen ersetzt. Ziz Fizziks will seinen mechanischen Arm als Beweis für seinen Tod und hofft, damit eine Beförderung zu erlangen.",h="Über dem Felskesselsee wartet Gerenzo Pfeifzang im Steinkrallengebirge auf ein Kopfgeld.",kw={"felskesselsee","cyborg","gerenzo","mechanischer arm","stotterspritter","steinkrallengebirge","pfeifzang","ziz fizziks"},ang={["faction:Horde"]="Als Mitglied der Horde könnt Ihr goblinischen Auftragnehmern im Steinkrallengebirge helfen, Ressourcen und Gebiete zu sichern und dabei gefährlichen abtrünnigen Ingenieuren in den Felsen das Handwerk zu legen.",["profession:Engineering"]="Gerenzos mechanischer Arm zeigt, wie weit die gnomische Bionik gehen kann, und unterscheidet sich deutlich von der praktischen Bauweise der Goblins.",["race:Gnome"]="Als Gnom greift Gerenzo zu exzentrischen und makabren Maßnahmen, um seinen versagenden Körper durch radikale Selbstaufrüstung zu erhalten."},sec={{t="Ein monströses Mischwesen",b="Gerenzos Körper trägt die Spuren seiner Verwandlungen. Wer ihn gesehen hat, berichtet, dass sein natürliches Fleisch unter aufgepfropften Zahnrädern, Eisenplatten und surrenden Uhrwerkgliedmaßen verfault. Nahe dem großen Wasserrad über dem Felskesselsee überwacht er die Arbeiten. Sein versagendes Fleisch kümmert ihn nicht."},{t="Goblinische Ambitionen",b="Ziz Fizziks arbeitet für Stotterspritter und hofft, dass Gerenzos Tod ihm einen Weg aus dem Steinkrallengebirge eröffnet. Ziz kann die Klippen nicht allein erklimmen und den aufgerüsteten Aufseher bezwingen, also bittet er Euch, Gerenzos mechanischen Arm zurückzubringen. Er hofft, mit dem Arm seinen Wert zu beweisen und eine Versetzung in die Werkstätten der Tüftler-Union in Gadgetzan oder Undermine zu erlangen."},{t="Widerstreitende Philosophien",b="Gerenzos mechanischer Arm spiegelt eine tiefe Kluft zwischen gnomischer und goblinischer Ingenieurskunst wider. Er schnitt versagendes Fleisch weg, um Platz für komplexe Prothesen zu schaffen, eine Entscheidung, die Goblins unbegreiflich finden. Ziz glaubt, goblinischer Erfindungsgeist würde den natürlichen Arm erhalten und daneben einen explosiven dritten Arm anbringen."}},faq={{q="Wer ist Gerenzo Pfeifzang?",a="Im Steinkrallengebirge ist Gerenzo Pfeifzang ein abtrünniger Gnomenaufseher. Er ersetzt Teile seines verfallenden Körpers durch Zahnräder und mechanische Gliedmaßen und überwacht die Arbeiten hoch über dem Felskesselsee.",al={"gerenzo","wer ist gerenzo","gerenzo hintergrundgeschichte"}},{q="Wo ist Gerenzo Pfeifzang zu finden?",a="Gerenzo befindet sich nordöstlich von Ziz Fizziks, hoch über dem Felskesselsee nahe einem großen industriellen Wasserrad.",al={"gerenzo standort","gerenzo finden","wo ist gerenzo"}},{q="Warum will Ziz Fizziks Gerenzo tot sehen?",a="Stotterspritter hat Ziz Fizziks befohlen, Gerenzo zu beseitigen. Ziz hofft, dass ihm der Beweis seiner Fähigkeiten eine Versetzung in eine Werkstatt der Tüftler-Union in Gadgetzan oder Undermine einbringt.",al={"warum gerenzo töten","ziz beweggrund","ziz fizziks ziel"}},{q="Welchen Beweis verlangt Ziz?",a="Ziz will Gerenzos mechanischen Arm als Beweis dafür, dass der Aufseher tot ist.",al={"welcher beweis","gerenzo beweis","questziel gegenstand"}},{q="Warum ist Gerenzo teilweise mechanisch?",a="Gerenzos Fleisch verfaulte, also pfropfte er Zahnräder, Eisenplatten und mechanische Gliedmaßen auf seinen Körper, um sich am Leben zu erhalten und aufzurüsten.",al={"warum ist gerenzo ein cyborg","gerenzo roboter","gerenzo körper"}},{q="Wer ist Stotterspritter?",a="Stotterspritter ist ein Goblinaufseher, der von einem anderen Ort in Kalimdor aus die Arbeiten überwacht und Untergebene wie Ziz Fizziks anweist.",al={"stotterspritter","wer ist stotterspritter"}}},fx={["94dcbf90"]={q="Warum braucht Ziz Fizziks Euch, um sich um Gerenzo zu kümmern?",a="Ziz Fizziks ist Ingenieur, kein Frontkämpfer. Gerenzo Pfeifzang verschanzt sich hoch über dem Felskesselsee, umgeben von den Holzfällereibetrieben und Maschinen der Venture Company. Ziz gibt zu, dass er keine Chance hat, sich alleine durch das feindselige Holzfällergelände zu kämpfen, geschweige denn den stark aufgerüsteten Gnom oben auf der Anlage zu besiegen. Er braucht einen fähigen Abenteurer, der die Verteidigungsanlagen durchbricht und die Aufgabe beendet.",al={"warum ich gerenzo","warum tötet ziz gerenzo nicht","warum einen abenteurer anheuern"}}},fp="21,302,18.289.0,16.345.0,21.284.0,29.201.0,41.98.0,39.171.0,28.72.0,33.131.0,20.127.0"}
P.entries["quest:1097"] = {n="Elmores Aufgabe",s="Schmied Argus schickt Euch von Goldhain nach Sturmwind, wo Grimand Elmore Hilfe bei einer Lieferung erwartet. Der Waffenschmied braucht jemanden, der sie zu seinen Verwandten in Khaz Modan bringt, und Argus vertraut Euch den bevorstehenden Weg an.",h="Schmied Argus schickt Euch von Goldhain nach Sturmwind, wo Grimand Elmore Hilfe bei einer Lieferung erwartet.",kw={"schmied","lieferung","der zwergendistrikt","elmore","goldhain","grimand elmore","schmied argus","sturmwind"},ang={["faction:Alliance"]="Als Reisender der Allianz helft Ihr, den Handel und das Vertrauen zwischen Sturmwind und den Zwergenklans von Khaz Modan zu stärken.",["profession:Blacksmithing"]="Als Schmied seht Ihr zwei Schmiede, die ihr Handwerk verbindet: Schmied Argus in Goldhain und Grimand Elmore in Sturmwind.",["race:Dwarf"]="Als Zwerg erkennt Ihr vielleicht, wie menschliche Schmiede die Handwerkskunst Eisenschmiedes ehren und helfen, Vorräte nach Norden in die Berge zu schicken."},sec={{t="Ein Wort aus der Schmiede",b="Schmied Argus hält Ausschau nach Reisenden, denen er Aufgaben jenseits von Wölfen und Kobolden anvertrauen kann. Grimand Elmore hat aus Sturmwind Nachricht geschickt und bittet um Hilfe bei einer Lieferung an seine Verwandten in Khaz Modan. Die Stadttore öffnen den Weg zu Elmores Ruf."},{t="Bande, die verbinden",b="Sturmwind und Eisenschmiede sind auf offenen Handel und gegenseitiges Wohlwollen angewiesen, damit beide Reiche versorgt und vereint bleiben. Argus sagt, der Wald von Elwynn brauche Verteidiger, doch auch Versprechen gegenüber den Zwergen zählen. Im Nordosten von Sturmwind führt Euch der Zwergendistrikt zu Elmores Laden. Dort beginnt eine Reise über den Wald hinaus."}},faq={{q="Bei wem beginnt die Quest Elmores Aufgabe?",a="Schmied Argus, der Schmied in Goldhain, schickt Euch zu Grimand Elmore, um ihm zu helfen.",al={"wo gibt es elmores aufgabe","wer vergibt elmores aufgabe","elmores aufgabe questgeber"}},{q="Wo ist Grimand Elmore zu finden?",a="Grimand Elmore arbeitet in einem Waffenladen im Zwergendistrikt im Nordosten von Sturmwind.",al={"grimand elmore standort","wo ist grimand elmore","elmore in sturmwind finden"}},{q="Welchen Zweck hat diese Aufgabe?",a="Argus schickt Euch zu Elmore, der einen vertrauenswürdigen Kurier braucht, um eine Lieferung nach Norden in seine Heimat zu bringen. Die Reise führt über Elwynn hinaus und durch die Lande der Allianz.",al={"warum zu elmore geschickt","elmores aufgabe zweck","was will elmore"}},{q="Welche Quest folgt auf Elmores Aufgabe?",a="Ein Gespräch mit Grimand Elmore schließt den Botengang ab und eröffnet Stormpike's Delivery. Ihr werdet gebeten, seine Lieferung nach Norden nach Loch Modan zu bringen.",al={"elmores aufgabe nächste quest","folgequest von elmores aufgabe","was folgt auf elmores aufgabe"}},{q="Warum kümmert sich Schmied Argus um Lieferungen an die Zwerge?",a="Argus sagt, enge Handelsbeziehungen zu den Zwergen von Khaz Modan helfen, Sturmwind zu schützen und die Versorgung aufrechtzuerhalten, auch wenn Elwynn Verteidiger braucht.",al={"warum hilft argus den zwergen","schmied argus beziehungen zu zwergen"}},{q="Müsst Ihr Schmied sein, um diese Quest anzunehmen?",a="Nein. Jeder Reisende der Allianz, der bereit ist, nach Sturmwind zu gehen, kann die Lieferung übernehmen, ob er das Schmiedehandwerk beherrscht oder nicht.",al={"elmores aufgabe nur für schmiede","schmiedekunst für elmores aufgabe erforderlich"}}},fx={["4799d1e0"]={q="Warum schickt Schmied Argus Euch, statt selbst zu gehen?",a="Schmied Argus ist an seine Esse in Goldhain gebunden, wo er die Verteidiger und Reisenden des Waldes von Elwynn bewaffnet und ihre Ausrüstung instand hält. Obwohl er vor Ort weitere helfende Hände gebrauchen könnte, erkennt er in Euch einen robusten Reisenden, der die Laufwege zwischen dem Wald von Elwynn und Sturmwind bewältigen kann. Indem er einen Abenteurer empfiehlt, kann er seinen zwergischen Kollegen unterstützen, ohne seine eigene unentbehrliche Schmiedearbeit in Goldhain aufzugeben.",al={"warum mich schicken elmores task","warum liefert argus es nicht","schmied argus warum ich"}}},fp="13,201,21.237.0,18.297.0,35.75.0,34.83.0,33.161.0,33.138.0,51.140.0,50.114.0"}
P.entries["quest:1098"] = {n="Todespirscher in Burg Schattenfang",s="In Burg Shadowfang werden die Todespirscher Adamant und Vincent vermisst. Hochexekutor Hadrec schickt Champions der Horde hinein, um die Aufklärer zu finden und ihre Berichte zu bergen. Ihre Erkenntnisse werden benötigt, bevor die Verlassenen gegen Erzmagier Arugal und seine Worgenrudel vorgehen können.",h="In Burg Shadowfang werden die Todespirscher Adamant und Vincent vermisst.",kw={"adamant","arugal","todespirscher in burg schattenfang","hadrec","das grabmal","burg shadowfang","silberwald","vincent"},ang={["class:Rogue"]="Das Verschwinden der Todespirscher zeigt die Gefahren der Aufklärung hinter befestigten feindlichen Linien.",["faction:Horde"]="Hochexekutor Hadrec verlässt sich auf Champions der Horde, um Einsätze der Verlassenen zu unterstützen, wenn reguläre Truppen nicht in Arugals verfluchte Festung eindringen können.",["race:Undead"]="Für die Verlassenen ist es entscheidend, den Silberwald von Arugals Bestien zurückzuerobern, um Lordaeron zu sichern. Die vermissten Aufklärer zeigen die Gefahr dieses Kampfes."},sec={{t="In den Worgenbau",b="Der Silberwald ist noch immer umkämpft, und Erzmagier Arugals Worgen halten Burg Shadowfang. Am Grabmal wollen die Verlassenen seine Belagerung ihrer südlichen Grenzen brechen. Hochexekutor Hadrec schickte die Todespirscher Adamant und Vincent in die Festung, um ihre Verteidigungsanlagen auszukundschaften. Tage vergehen ohne Nachricht, und Hadrec wartet immer verzweifelter auf ihre Berichte. Also schickt er Champions der Horde hinein, um die Agenten zu finden und die Operation zu retten."},{t="Eine bittere Entdeckung",b="Die unteren Wehrmauern offenbaren, was aus den Agenten geworden ist. Todespirscher Adamant überlebt in Gefangenschaft und hilft dabei, die Tore des Innenhofs zu entriegeln. Vincent fand ein brutales Ende. Sein zerschundener Leichnam liegt reglos in der Burg, und seine gesammelten Informationen sind in ihren dunklen Hallen verloren. Ein kleines Schmuckstück bleibt fest in seinen Fingern umklammert, das letzte Zeichen eines Spions, der sein Leben für die Eroberung der Dunklen Fürstin gab."}},faq={{q="Warum wurden Todespirscher nach Burg Shadowfang geschickt?",a="Hochexekutor Hadrec befahl die Infiltration, um taktische Informationen über Erzmagier Arugals Streitkräfte und Befestigungen zu sammeln, bevor die Verlassenen Truppen für einen Angriff auf Burg Shadowfang einsetzen.",al={"warum spione nach shadowfang schicken","hadrecs missionsziel","ziel der todespirscher in shadowfang"}},{q="Wer sind die Todespirscher Adamant und Vincent?",a="Adamant und Vincent sind Eliteagenten und Vorhutspäher der Verlassenen. Sie gehören zu den Todespirschern, der Spionage- und Meuchelmordabteilung von Unterstadt. Hadrec schickte sie los, um Burg Shadowfang zu kartieren und ihre Worgenverteidigung zu beobachten.",al={"wer sind adamant und vincent","geschichte von adamant und vincent"}},{q="Was ist mit Todespirscher Vincent geschehen?",a="Vincent hat sich aus Burg Shadowfang nicht zurückgemeldet. Hadrec braucht jemanden, der die Festung betritt und herausfindet, was ihm zugestoßen ist.",al={"ist vincent gestorben","wo ist vincent","vincents schicksal"}},{q="Welche Rolle spielt Todespirscher Adamant in der Burg?",a="Adamant ist einer der vermissten Todespirscher, die Informationen in Burg Shadowfang sammeln sollten. Seine Lage wird im Laufe der Suche deutlich.",al={"was macht adamant","rolle von todespirscher adamant"}},{q="Wo beginnt diese Mission?",a="Hochexekutor Hadrec erteilt den Auftrag am Grabmal im Silberwald. Er ist dort als militärischer Befehlshaber der Verlassenen stationiert.",al={"wo gibt es todespirscher in burg schattenfang","questgeber für todespirscher in burg schattenfang"}},{q="Warum will die Führung der Verlassenen Burg Shadowfang säubern lassen?",a="Erzmagier Arugal lässt von Burg Shadowfang aus gewalttätige Worgenrudel auf den Silberwald los. Sie bedrohen ständig die Besitzungen und Nachschublinien der Verlassenen sowie die Sicherheit Lordaerons.",al={"warum shadowfang angreifen","streit der verlassenen mit arugal"}}},fx={["7d643f75"]={q="Warum braucht Hochexekutor Hadrec Euch, um die The Todespirscher zu finden?",a="Hochexekutor Hadrec bereitet einen großen Angriff der Verlassenen gegen Burg Shadowfang vor, aber seine gesamte Strategie hängt von vitalen Informationen ab. Er hat die Todespirscher Adamant und Vincent vorausgeschickt, um die Festung auszuspähen, aber es sind Tage ohne Nachricht vergangen. Ohne ihre Aufklärung über die Stärke und Verteidigung des Feindes würde jeder direkte Angriff blind in ein Gemetzel laufen.",al={"warum will hadrec das erledigt haben","hadrec motiv burg shadowfang","warum nach den todespirschern suchen"}},cc510862={q="Warum schickt Hochexekutor Hadrec Euch anstatt seine eigenen Truppen?",a="Die Streitkräfte am Grabmal sind dünn gesät, um die Front im Silberwald zu halten, und eine Armee zur Infiltration von Burg Shadowfang ohne Informationen zu entsenden, wäre eine Katastrophe. Hadrec braucht einen einfallsreichen, fähigen Abenteurer, der an der äußeren Begrenzung der Burg vorbeischlüpfen, seine vermissten Elite-Späher aufspüren und ihnen jede Hilfe leisten kann, die sie zur Rettung der Mission benötigen.",al={"warum schickt ihr mich burg shadowfang","warum nicht todespirscher oder wachen benutzen","warum ich hadrec"}}},fp="27,263,19.422.0,18.377.1,47.192.0,42.226.0,38.129.1,57.142.1,30.138.0,62.181.0"}
P.entries["quest:1099"] = {n="Goblins Win!",s="In Tausend Nadeln entscheidet das Goblinrennen, wer eine Goblin-Preiskiste gewinnt. Goblins Win! bezeichnet das Ergebnis für denjenigen, der das Gewinnerticket besitzt.",h="In Tausend Nadeln entscheidet das Goblinrennen, wer eine Goblin-Preiskiste gewinnt.",kw={"goblin","goblin-preiskiste","rennticket","tausend nadeln"},sec={{t="Das Goblin-Rennticket",b="Ihr haltet das Goblin-Rennticket, während sich entscheidet, ob die Goblins gewinnen. Wenn sie gewinnen, bringt Euch das Ticket eine Goblin-Preiskiste ein. Das Gnom-Ticket zählt für die andere Seite."}},faq={{q="Was ist das Goblin-Rennticket?",a="Das Goblin-Rennticket zählt für die Goblinseite des Rennens in Tausend Nadeln. Wenn die Goblins gewinnen, ist es das Gewinnerticket.",al={"rennticket","was ist das goblin-rennticket"}},{q="Was bekommt Ihr, wenn die Goblins gewinnen?",a="Wer das Goblin-Rennticket besitzt, wenn die Goblins gewinnen, erhält eine Goblin-Preiskiste.",al={"goblin-preiskiste","preis bei goblinsieg"}},{q="Was passiert, wenn stattdessen die Gnome gewinnen?",a="Wenn die Gnome gewinnen, zählt das Gnom-Ticket. Dieses Ergebnis heißt Gnomes Win!, das Gegenstück zu Goblins Win!.",al={"gnome gewinnen","gnom-rennticket"}}},fp="12,141,17.165.0,31.128.0,37.86.0,39.111.0"}
P.entries["quest:11"] = {n="Kopfgeld auf die Flusspfotengnolle",s="Im Westen Elwynns ruft „Kopfgeld auf die Flusspfotengnolle“ zur Hilfe gegen Gnolle auf, die an die Grenze drängen. Stellvertreter Rainer bietet in der Weststromgarnison eine Belohnung für bemalte Armbänder, die den Flusspfotenrudeln in den Wäldern und am Wasser abgenommen werden.",h="Im Westen Elwynns ruft „Kopfgeld auf die Flusspfotengnolle“ zur Hilfe gegen Gnolle auf, die an die Grenze...",kw={"kopfgeld","stellvertreter rainer","elwynn","gnoll","bemalte gnollarmbinde","flusspfoten","der steinhügelsee","weststromgarnison"},ang={["faction:Alliance"]="Als Mitglied der Allianz steigert Ihr Euer Ansehen bei der Armee von Sturmwind, indem Ihr Kopfgeldaufträge an der Grenze annehmt, und helft, Handelswege durch das Herz des Königreichs zu sichern.",["race:Human"]="Als Mensch helft Ihr, Elwynns Grenzen zu schützen, indem Ihr Flusspfoten jagt und die überlasteten Wachen der Krone unterstützt."},sec={{t="Gefahr an der Grenze",b="Die Weststromgarnison bewacht die Grenze zwischen dem Wald von Elwynn und Westfall. Ihre geschwächten Truppen können die wachsende Zahl der Flusspfoten kaum in Schach halten. Die Gnolle lagern südlich des Wachturms und weiter östlich um den Steinhügelsee. Von diesen Lagern aus bedrohen sie Reisende und nahe gelegene Gehöfte."},{t="Der Preis der Ordnung",b="Stellvertreter Rainer kann keine reguläre Infanterie entbehren, um die Wälder zu durchkämmen, und setzt deshalb ein Kopfgeld auf die Plünderer aus. Als Beweis für jede Tötung verlangt er bemalte Armbänder von erschlagenen Gnollen. Umherziehende Abenteurer und Rekruten werden angeheuert, um das Rudel zu dezimieren, bevor die Flusspfoten die westlichen Grenzmarken überrennen."}},faq={{q="Wo sind Flusspfotengnolle im Wald von Elwynn zu finden?",a="Flusspfotengnolle sammeln sich in zwei Gebieten Elwynns. Sucht in den Wäldern südlich der Weststromgarnison nahe den Flussufern und weiter östlich um den Steinhügelsee.",al={"fundorte der gnolle","wo sind die gnolle","fundorte der flusspfoten"}},{q="Warum bittet die Garnison Abenteurer um Hilfe gegen die Gnolle?",a="Die Weststromgarnison ist unterbesetzt und steht entlang der Grenzen Elwynns unter Druck. Da es zu wenige Wachen für Patrouillen und das Durchkämmen der Wälder gibt, bittet Stellvertreter Rainer unabhängige Streiter, die Gnolle zu jagen.",al={"warum stellvertreter rainer hilfe braucht","warum die garnison söldner anheuert"}},{q="Welchen Beweis verlangt Stellvertreter Rainer?",a="Stellvertreter Rainer verlangt acht bemalte Gnollarmbänder als Beweis dafür, dass die Gnolle getötet wurden.",al={"beweis für das kopfgeld","was für rainer sammeln"}},{q="Wer sind die Flusspfotengnolle?",a="Die Flusspfoten sind ein grausamer Stamm hyänenartiger Humanoider, die Flusstäler und Grenzgebiete in den Landen der Menschen heimsuchen. Sie überfallen Siedlungen, Reisende und Bauernhöfe auf der Suche nach Nahrung und Beute.",al={"was sind flusspfotengnolle","geschichte des flusspfotenstamms"}},{q="Steht dieser Auftrag mit anderen Bedrohungen in Elwynn in Verbindung?",a="Der Kopfgeldauftrag schließt die kurze Auftragsreihe zur Alarmierung der Weststromgarnison ab. Stellvertreter Rainer und die Garnison halten auch nach anderen gesetzlosen Bedrohungen in der Gegend Ausschau, darunter dem Gesetzlosen Hogger.",al={"fortsetzung des auftrags","was folgt auf das flusspfoten-kopfgeld"}},{q="Wer zahlt das Kopfgeld für diese Gnolle?",a="Die Armee von Sturmwind unterstützt und genehmigt das Kopfgeld. Sie erlaubt örtlichen Garnisonen, jene auszuzeichnen und zu entlohnen, die bei der Befriedung der königlichen Gebiete helfen.",al={"wer finanziert das kopfgeld","herkunft der kopfgeldbelohnung"}}},fx={["139c22ee"]={q="Warum möchte Stellvertreter Rainer, dass die Gnolle dezimiert werden?",a="Stellvertreter Rainer betrachtet die Riverpaw-Gnolle als brutale Eindringlinge, die an den Grenzen von Elwynn nichts zu suchen haben. Da sich große Rudel südlich des Wachturms und östlich in der Nähe des Steinhügelsees festsetzen, bedrohen sie direkt den Umfang der Weststromgarnison und die umliegenden Siedler. Rainer will sie dezimiert sehen, um ihren schleichenden Befall zu stoppen, bevor der Außenposten vollständig überrannt wird.",al={"warum gnolle dezimieren","stellvertreter rainer motiv","warum will rainer die riverpaws tot sehen"}}},fp="21,221,22.282.0,18.283.0,52.155.0,60.182.0,38.94.0,28.185.0,55.172.0,37.144.0"}
P.entries["quest:110"] = {n="Insektenteil-Analyse",s="In Gadgetzan braucht Rutenwünschels Nachricht über die Insektenteile, die an Alchimist Pestlezugg geschickt wurden. Seit Scrimshank verschollen ist, ordnet der Leitende Feldmesser dessen Vermessungsausrüstung und persönliche Habseligkeiten.",h="In Gadgetzan braucht Rutenwünschels Nachricht über die Insektenteile, die an Alchimist Pestlezugg geschickt...",kw={"rutenwünschels","gadgetzan","insektenteil-analyse","pestlezugg","scrimshank","tanaris"},sec={{t="Nachfrage in Gadgetzan",b="Leitender Feldmesser Rutenwünschels ordnet Scrimshanks Vermessungsausrüstung und persönliche Habseligkeiten. Er fürchtet, dass die Insekten weitere Leben fordern werden, und schickt Euch deshalb zu Alchimist Pestlezugg in Gadgetzan. Findet heraus, ob Pestlezugg die Verarbeitung der Insektenteile abgeschlossen hat, die die Feldmesser geschickt haben. Wenn sie fertig sind, bringt sie zu Rutenwünschels zurück."},{t="Was Pestlezugg herausfand",b="Alchimist Pestlezugg hat seine Arbeit abgeschlossen, und die Ergebnisse beunruhigen ihn. Er glaubt, dass der erste Verdacht richtig war: Eine äußere Macht kontrolliert die Insekten. Das deutet auf eine mächtige Kraft hin, unbekannt und bösartig. Pestlezugg hat noch nie zuvor gesehen, wie Insekten in reine Verwüster verwandelt wurden."}},faq={{q="Wer schickt Euch zu Alchimist Pestlezugg?",a="Leitender Feldmesser Rutenwünschels schickt Euch, während er Scrimshanks Vermessungsausrüstung und persönliche Habseligkeiten durchgeht.",al={"questgeber","wer startet insektenteil-analyse","rutenwünschels standort"}},{q="Wo befindet sich Alchimist Pestlezugg?",a="Alchimist Pestlezugg ist in Gadgetzan, wohin Ihr geschickt werdet, um nach den Insektenteilen zu fragen.",al={"wo ist pestlezugg","pestlezugg standort","pestlezugg stadt"}},{q="Was kam unmittelbar vor diesem Schritt?",a="The Scrimshank Redemption kommt unmittelbar vor diesem Schritt.",al={"vorausgesetzte quest","welche quest kommt zuerst","vorheriger schritt"}},{q="Was sollt Ihr herausfinden?",a="Ihr sollt herausfinden, ob Pestlezugg die Verarbeitung der Insektenteile abgeschlossen hat, die die Feldmesser geschickt haben. Wenn sie fertig sind, bringt sie zu Rutenwünschels zurück.",al={"was hat pestlezugg"}}},fp="20,181,23.331.0,21.273.1,46.110.0,38.86.0,36.58.0,30.153.0"}
P.entries["quest:1100"] = {n="Einbraues Tagebuch",s="Am Großen Aufzug in Tausend Nadeln liegt Henrig Lonebrow tot, mit Einbraues Tagebuch in der Hand. Die Seiten schildern seine letzte Reise und bitten Euch, das Buch nach Westen zu einem Nachtelfendruiden an der Grenze zu Feralas zu bringen.",h="Am Großen Aufzug in Tausend Nadeln liegt Henrig Lonebrow tot, mit Einbraues Tagebuch in der Hand.",kw={"falfindel","feralas","der große aufzug","henrig","tagebuch","lonebrow","kral der klingenhauer","thalanaar","tausend nadeln","wegeshut"},ang={["class:Druid"]="Als Druide versteht Ihr, warum Falfindel Wegeshut in Thalanaar auf unnatürliche Veränderungen im örtlichen Ökosystem achtet. Lonebrows Notizen über die Borstennacken in Razorfen sind für den Zirkel des Cenarius von Bedeutung.",["faction:Alliance"]="Als Mitglied der Allianz wisst Ihr, dass es zwischen Theramore und Thalanaar nur wenige Außenposten gibt. Bergt Lonebrows Tagebuch, um Verbündeten der Allianz wichtige Informationen zu überbringen, bevor die Schlucht es verschlingt.",["race:Dwarf"]="Als Zwerg erinnert Euch Henrig Lonebrows Tod an die Gefahren, denen zwergische Forscher fern von Eisenschmiede in Kalimdors wilden Winkeln begegnen."},sec={{t="Ein gefallener Forscher",b="Henrig Lonebrow liegt nahe dem Großen Aufzug, der gewaltigen Maschine, die Reisende aus dem Brachland auf den Grund von Tausend Nadeln befördert. Sein Tagebuch liegt noch in seiner Hand, voller Notizen über seine Reisen durch die Schlucht. Zentauren und Tauren beherrschen dieses raue Land. Sein Tod zeigt, wie gefährlich es ist, hier allein zu reisen."},{t="Ein letzter Wunsch",b="Henrigs Tagebuch beschreibt seinen geplanten Weg und seinen letzten Wunsch. Er hoffte, seine Aufzeichnungen würden in befreundete Hände gelangen, statt in der Schlucht zu verrotten. Folgt der Straße nach Westen durch Tausend Nadeln, aus den trockenen Rinnen hinaus in Richtung Thalanaar. Der Nachtelfenaußenposten bewacht die Grenze zu Feralas, wo sein Druide, Falfindel Wegeshut, auf Neuigkeiten von Euch wartet."},{t="Enthüllungen über den Kral",b="Falfindel Wegeshut findet in Lonebrows Notizen Anzeichen für eine größere Bedrohung im südlichen Kalimdor. Henrigs Beobachtungen weisen nach Norden zu den dornenüberwucherten Bauen des Krals der Klingenhauer. Eine gefährliche Hexe führt die Borstennacken an, die dort hausen."}},faq={{q="Wo finde ich Henrig Lonebrows Leichnam?",a="Henrig Lonebrows Leichnam liegt am Fuße des Großen Aufzugs in Tausend Nadeln. Geht vom unteren Ende der westlichen Aufzugsrampe etwa fünfundzwanzig Fuß auf einen niedrigen Felsvorsprung zu. Dort liegt sein Leichnam mit dem Tagebuch in der Hand.",al={"henrig lonebrow fundort","wo ist einbraues tagebuch","lonebrows leichnam","lonebrow finden"}},{q="Wem soll ich das Tagebuch bringen?",a="Bringt das Tagebuch zu Falfindel Wegeshut, einem Nachtelfendruiden, der in Thalanaar stationiert ist. Der Außenposten liegt an der Hauptstraße nach Westen, an der Grenze zwischen Tausend Nadeln und Feralas.",al={"wer bekommt einbraues tagebuch","wo lonebrow abgeben","lonebrow abgeben","falfindel standort"}},{q="Wer war Henrig Lonebrow?",a="Henrig Lonebrow war ein zwergischer Reisender, der das zentrale Kalimdor durchquerte. Er starb nahe dem Fuß des Großen Aufzugs und hinterließ ein verwittertes Tagebuch mit Beobachtungen über die umliegenden Lande und gefährliche Bewegungen der Borstennacken.",al={"wer ist henrig lonebrow","lonebrows hintergrundgeschichte","wer ist lonebrow"}},{q="Wozu führt diese Quest?",a="Bringt das Tagebuch zu Falfindel Wegeshut, und der Weg zu Crone of the Kraul öffnet sich. Diese Quest schickt Abenteurer der Allianz in den Kral der Klingenhauer.",al={"lonebrow folgequest","quest nach einbraues tagebuch","lonebrow questreihe"}},{q="Können Spieler der Horde das Tagebuch aufheben?",a="Nein. Nur Spieler der Allianz können das Tagebuch nehmen und der Questreihe folgen, die damit beginnt. Die Questreihe führt zum Grenzposten der Allianz in Thalanaar.",al={"einbraues tagebuch nur für allianz","kann die horde einbraues tagebuch abschließen","horde lonebrow"}},{q="Warum war Lonebrow auf dem Weg nach Thalanaar?",a="Lonebrow war auf dem Weg nach Thalanaar, dem nächsten Außenposten der Allianz in der Region und einem Zufluchtsort zwischen Tausend Nadeln und der Wildnis von Feralas. Er wollte seine Beobachtungen über die Region mit den dort stationierten Nachtelfen teilen.",al={"warum thalanaar","warum das buch zum druiden bringen","lonebrows absicht"}}},fx={["0173d93a"]={q="Warum bittet das Tagebuch, nach Thalanaar gebracht zu werden?",a="Henrig Lonebrow wusste, dass seine Reise in einer Tragödie unterhalb von Der große Aufzug enden würde. Sein letzter Wunsch, der auf den verwitterten Seiten festgehalten wurde, war, dass seine Erkenntnisse Falfindel Wegeshut am Grenzposten von Thalanaar erreichen. Indem Ihr die Zustellung des Tagebuchs sicherstellt, sorgt Ihr dafür, dass die kritischen Informationen oder Entdeckungen, die den Zwerg das Leben kosteten, nicht im Sand von Tausend Nadeln verloren gehen.",al={"warum tagebuch ausliefern","tagebuch zweck","henrig lonebrow tagebuch motiv"}}},fp="18,213,17.315.0,15.353.0,20.231.1,39.222.0,32.177.0,24.211.0,29.140.1,38.136.0,42.231.0"}
P.entries["quest:1101"] = {n="Die Greisin des Krals",s="In Thalanaar, zwischen Feralas und Tausend Nadeln, sucht Falfindel Wegeshut Hilfe gegen Charlga Klingenflanke. Henrig Lonebrows geborgenes Tagebuch warnt vor einer wachsenden Gefahr im Kral der Klingenhauer.",h="In Thalanaar, zwischen Feralas und Tausend Nadeln, sucht Falfindel Wegeshut Hilfe gegen Charlga Klingenflanke.",kw={"agamaggan","charlga klingenflanke","greisin","falfindel wegeshut","lonebrow","medaillon","kral der klingenhauer","thalanaar"},ang={["class:Druid"]="Als Druide schätzt Ihr Agamaggan als verehrten Urahn der Natur und wollt den dunklen Makel läutern, der sein dornenbedecktes Vermächtnis entstellt.",["faction:Alliance"]="Die Hauptanstrengungen der Allianz gegen die Bedrohung durch die Borstennacken im südlichen Brachland beginnen in Thalanaar.",["race:Dwarf"]="Die Rache für den Forscher Henrig Lonebrow gibt Zwergen einen persönlichen Grund, die Festung der Borstennacken zu stürmen.",["race:NightElf"]="Die Nachtelfen trauern um die Entweihung von Agamaggans Ruhestätte. Der Eber-Urahn fiel während des Kriegs der Ahnen als Verbündeter der Nachtelfen."},sec={{t="Eine Bitte an der Grenze",b="Im abgelegenen Nachtelfenposten Thalanaar trauert Falfindel Wegeshut um den Druiden Heralath und den Zwerg Henrig Lonebrow. Lonebrow reiste mit der Forscherliga, bevor die Borstennacken ihn gefangen nahmen. Er entkam aus dem Kral der Klingenhauer, starb jedoch auf der Straße. Sein zerfleddertes Tagebuch berichtet von der wachsenden Bedrohung darin.\n\nEs bleibt keine Zeit, einen Läufer nach Darnassus zu schicken, um militärische Hilfe zu erbitten. Also wendet sich Falfindel an vorbeiziehende Abenteurer und schickt sie in die Dornenbaue, um der Gefahr in deren Herzen entgegenzutreten."},{t="Ein Schlag gegen die Häuptlingin",b="Charlga Klingenflanke ist eine uralte Geomantin und skrupellose Matriarchin. Sie hat die zerstrittenen Borstennacken der Klingenhauer unter ihrer eisernen Herrschaft vereint. Tief im Kral sammelt sie eine stachelbewehrte Armee, die benachbarte Länder bedroht.\n\nDichte Dornenlabyrinthe, Wehrmauern und Scharen fanatischer Borstennackenkrieger bewachen den Weg zu Charlga. Ihr Medaillon, ihrem leblosen Körper abgenommen, wird ihren Untergang bezeugen."},{t="Tieferes Verderben",b="Charlgas Tod mindert die unmittelbare Bedrohung durch die Borstennacken, doch den Nachtelfen bleiben tiefere Sorgen. Das lebendige Dornengestrüpp des Krals spross dort empor, wo Agamaggan, der Eber-Urahn, während des Kriegs der Ahnen fiel. Nach Charlgas Tod können Nachtelfengelehrte das Verderben der Gegend genauer untersuchen.\n\nAls Falfindel das Medaillon erhält, ahnt er, dass heimtückischer Verrat hinter der plötzlichen Fäulnis stecken könnte, die Agamaggans heilige Überreste heimsucht."}},faq={{q="Wer vergibt die Quest Die Greisin des Krals?",a="Falfindel Wegeshut, ein in Thalanaar stationierter Nachtelf, vergibt sie. Thalanaar ist ein Außenposten der Allianz auf dem hohen Gebirgspass zwischen Feralas und Tausend Nadeln.",al={"questgeber die greisin des krals","wo gibt es die greisin des krals","falfindel wegeshut quest"}},{q="Welche Voraussetzung muss vor Beginn dieser Quest erfüllt werden?",a="Schließt zuerst Einbraues Tagebuch ab. Bergt Henrig Einbraues Tagebuch von seinen sterblichen Überresten nahe dem Großen Aufzug in Tausend Nadeln und bringt es dann zu Falfindel in Thalanaar.",al={"voraussetzung für die greisin des krals","die greisin des krals freischalten","einbraues tagebuch voraussetzung"}},{q="Wer ist Charlga Klingenflanke?",a="Charlga Klingenflanke ist die oberste Greisin und Matriarchin der Borstennacken der Klingenhauer. Als mächtige Geomantin hat sie die verfeindeten Stämme im Kral der Klingenhauer vereint und lenkt ihre Angriffslust gegen benachbarte Gebiete.",al={"wer ist die greisin","charlgas geschichte","charlga klingenflanke"}},{q="Wo ist Charlga Klingenflanke zu finden?",a="Charlga Klingenflanke wartet ganz am Ende des Krals der Klingenhauer, im äußersten Süden des Brachlands nahe dem Großen Aufzug. Sie wartet auf einem Altar tief im Inneren des Dungeons.",al={"wo ist charlga","charlgas standort","wo ist die greisin im kral der klingenhauer"}},{q="Warum braucht Falfindel Abenteurer, statt die Armee von Darnassus zu rufen?",a="Thalanaar ist ein entlegener Grenzposten, weit vom nördlichen Kalimdor entfernt. Charlga zieht bereits ihre Streitkräfte zusammen, und eine Nachricht nach Darnassus würde zu lange brauchen, als dass eine entsandte Armee die wachsende Gefahr rechtzeitig abwenden könnte.",al={"warum nicht darnassus rufen","warum abenteurer anheuern"}},{q="Welchen Beweis verlangt Falfindel für den Tod der Greisin?",a="Falfindel verlangt Klingenflankes Medaillon, das Amulett, das Charlga trägt, als Beweis dafür, dass sie erschlagen wurde.",al={"welcher gegenstand wird fallen gelassen","proof of demise gegenstand","klingenflankes medaillon"}}},fx={["8858b532"]={q="Warum möchte Falfindel Wegeshut, dass Charlga Klingenflanke getötet wird?",a="Falfindel Wegeshut weigert sich, die Opfer von Heralath und Henrig Lonebrow umsonst sein zu lassen. Charlga Klingenflanke versammelt aktiv eine gefährliche Streitmacht tief im Kral der Klingenhauer und bedroht alle umliegenden Ländereien. Sie zu eliminieren, stoppt diese wachsende Stacheleber-Bedrohung und ermöglicht es den Nachtelfen in Thalanaar, sicher zu untersuchen, wie die heiligen Ruhestätten des Urahns Agamaggan korrumpiert wurden.",al={"warum charlga klingenflanke töten","falfindel motiv","kral-hexe warum"}}},fp="22,197,20.484.0,22.401.0,19.452.1,43.167.0,63.178.0,26.219.0,38.171.0,74.215.0,54.102.0"}
P.entries["quest:1103"] = {n="Ruf des Wassers",s="An der Küste des Silberwalds wartet Tiev Mordune, um Schamanen zu helfen, deren Geistersicht zu früh verblasst. Ein frisches Water Sapta lässt sie zum Schrein zurückkehren und mit dem gereinigten Wassergeist sprechen.",h="An der Küste des Silberwalds wartet Tiev Mordune, um Schamanen zu helfen, deren Geistersicht zu früh...",kw={"ruf des wassers","islen wasserdeuter","schwache wassermanifestation","schamane","silberwald","tiev mordune","water sapta"},ang={["class:Shaman"]="Als Schamane beschreitet Ihr einen beschwerlichen Weg, um Euch Euer Wassertotem zu verdienen. Dieser Ritus zeigt, wie Schamanen einander helfen, damit kein Anwärter zurückbleibt, wenn eine Trance nachlässt.",["faction:Horde"]="Als Mitglied der Horde folgt Ihr schamanischen Traditionen gegenseitiger Hilfe und Achtung vor Naturgeistern, selbst in Lordaerons heimgesuchten Landen."},sec={{t="Eine Helfende Hand im Mist",b="Schamanen trinken ein Water Sapta, um Geister nahe den Elementarschreinen zu sehen. Wenn seine Magie verblasst, bevor sie mit der Schwachen Wassermanifestation sprechen, können sie das Geisterreich nicht mehr betreten, um die Prüfung abzuschließen. Am nebelverhangenen Ufer des Silberwalds hilft ihr Schamanengefährte Tiev Mordune jenen, deren Visionen zu früh enden."},{t="Das Ritual erneuern",b="Tiev Mordune hat den verdorbenen Wassergeist vor der Küste besiegt und wartet mit den Ritualüberresten, die er gesammelt hat. Um Eure Bereitschaft zu zeigen, bringt ein frisches Water Sapta von Islen Wasserdeuter im Brachland. Tiev wirft seine gesammelten Armschienen und Tröpfchen in das Kohlenbecken des Schreins. Die reine Manifestation erscheint erneut, damit Ihr mit ihr sprechen und Euer Band mit dem Element besiegeln könnt."}},faq={{q="Wer ist Tiev Mordune?",a="Tiev Mordune ist ein Schamanengefährte der Horde an der Küste des Silberwalds. Er hat dort den verdorbenen Wassergeist besiegt und bleibt am Ufer, um Schamanen zu helfen, deren Geistersicht vor dem Ende ihrer Zwiesprache verblasst.",al={"tiev mordune","wer ist tiev","tiev silberwald"}},{q="Warum brauche ich für diese Quest ein Water Sapta?",a="Ein Water Sapta lässt Euren Geist in die Geisterwelt hinübertreten. Tiev braucht einen frischen Trank von Islen Wasserdeuter, damit Ihr den Elementar sehen könnt, wenn er ihn erneut beschwört.",al={"warum sapta nötig","water sapta tiev","wo sapta bekommen"}},{q="Was geschieht, wenn ich versäumt habe, mit dem Wassergeist zu sprechen?",a="Wenn die Wirkung des Water Sapta nachlässt oder die Schwache Wassermanifestation verschwindet, bevor Ihr mit ihr sprecht, könnt Ihr die Prüfung nicht allein abschließen. Tiev Mordune entfacht das Kohlenbecken mit seinen gesammelten Trophäen erneut, damit Ihr mit dem Geist Zwiesprache halten könnt.",al={"wassergeist verpasst","wassermanifestation fehlgeschlagen","manifestation verschwunden"}},{q="Wo findet dieses Ritual statt?",a="Die Prüfung findet an der Westküste des Silberwalds statt, bei einem Elementarschrein, der dem großen Meer zugewandt ist.",al={"wo ist der wasserschrein","wasserschrein silberwald standort"}},{q="Wer hat die Schamanen auf diese Pilgerreise geschickt?",a="Islen Wasserdeuter, eine Taurenschamanin, führt Anwärter durch ihre Prüfungen zum Ruf des Wassers und braut die benötigten Saptas. Sie lebt bei einer Fischerhütte an der Ostküste des Brachlands.",al={"wer gab den ruf des wassers","islen waterstrider"}},{q="Was ist die Schwache Wassermanifestation?",a="Die Schwache Wassermanifestation ist ein gereinigter Elementargeist, der am Schrein beschworen wird, nachdem die Verderbnis in den örtlichen Gewässern beseitigt wurde. Die Zwiesprache mit ihm schließt diesen Teil der Elementarprüfungen eines Schamanen ab.",al={"was ist der wassergeist","schwache manifestation"}}},fx={["890785ae"]={q="Warum hilft Tiev Mordune anderen Schamanen hier?",a="Tiev Mordune ist ein Mit-Schamane, der den korrupten Wassergeist bereits besiegt und seine Opfergaben vorbereitet hat. Nachdem er gesehen hat, wie andere Pilger ihre Chance verloren, weil das Geisterreich zu schnell verblasste, entschied er sich, sein eigenes Ritual zu verzögern, damit er jedem Bruder oder jeder Schwester helfen kann, der während der Prüfung stolperte. Indem er seine Ritualgegenstände und sein Wissen über Sapta-Magie anbietet, stellt er sicher, dass kein würdiger Schamane auf seinem Weg zum Verständnis zurückgelassen wird.",al={"warum hilft tiev","tiev mordune motiv","warum wartet tiev"}}},fp="13,195,26.319.0,19.370.0,20.210.0,43.160.0,54.232.0,34.104.0,36.172.0,41.216.0"}
P.entries["quest:1104"] = {n="Salziges Gift",s="An der Illusionenrennbahn sucht Fizzel Kupferbolz heißeren Treibstoff für seinen Raketenwagen. Er glaubt, dass Skorpidgift aus der Schimmernden Ebene ihm die nötige heftige Verbrennung liefern kann.",h="An der Illusionenrennbahn sucht Fizzel Kupferbolz heißeren Treibstoff für seinen Raketenwagen.",kw={"fizzel kupferbolz","treibstoff","illusionenrennbahn","raketenwagen","salziges skorpidgift","die schimmernde ebene","tausend nadeln"},ang={["profession:Engineering"]="Als Ingenieur könnt Ihr erkennen, wie organische Gifte und Katalysatoren wie skipper-otomers die kreativen, explosiven Experimente im hart umkämpften Fahrzeugbau antreiben.",["race:Gnome"]="Als Gnom erkennt Ihr vielleicht Fizzels vertrauten Ehrgeiz wieder: unermüdliches Tüfteln, riskante Chemie, verlegte Notizen und den Drang, Goblinmechaniker zu übertrumpfen."},sec={{t="Ein explosives Rezept",b="An der Illusionenrennbahn trifft gnomische Präzision in Wettkämpfen um Geschwindigkeit und Erfindungsgeist auf die Kühnheit der Goblins. Fizzel Kupferbolz verlangt mehr von Treibstoff und Uhrwerkteilen. Er sucht ein Gemisch, das heißer brennt als gewöhnliche Treibmittel und Raketenwagen mit rasender Geschwindigkeit über den trockenen Salzsee jagt."},{t="Salzhaltiges Gift der Salzebenen",b="Skorpiden in der Schimmernden Ebene könnten den Schlüssel zu Fizzels neuem Treibstoff liefern. Sie überleben in einem trockenen, salzverkrusteten Ödland, und ihr Gift enthält ungewöhnlich viel Salz. Fizzel sieht in ihrem tödlichen Stachel eine nützliche chemische Ladung. Er glaubt, dass sich durch Kochen, Raffinieren und anschließende Behandlung des Gifts mit exotischen Katalysatoren die heftige Verbrennung erzielen lässt, um die Goblin-Boxencrews abzuhängen."}},faq={{q="Warum will Fizzel Kupferbolz Skorpidgift?",a="Fizzel Kupferbolz will Skorpidgift für einen extrem heiß brennenden Raketenwagentreibstoff. Er glaubt, dass der ungewöhnliche Salzgehalt im Gift der Skorpiden aus der Schimmernden Ebene entscheidend für sein explosives Gemisch ist.",al={"warum skorpidgift","wofür ist das gift","fizzels treibstoffrezept"}},{q="Wo findet man die benötigten Skorpiden?",a="Skorpiden durchstreifen die offene Schimmernde Ebene, besonders die westlichen Ebenen und den Wüstensand abseits der zentralen Rennstrecke.",al={"skorpidenfundort","wo sind skorpiden","salziges gift gegner"}},{q="Was wird Fizzel mit dem gesammelten Gift tun?",a="Fizzel plant, das Gift einzukochen, mit einem skipper-otomer zu behandeln und mit einem nega-catalyst zu Raketentreibstoff zu vermischen. Er hat seine Notizen verlegt.",al={"wie wird gift zu treibstoff","treibstoffherstellung"}},{q="Können Angehörige der Allianz und der Horde Fizzel helfen?",a="Ja. Gnome und Goblins betreiben die Illusionenrennbahn unter einem neutralen Waffenstillstand, sodass Abenteurer beider Fraktionen den Boxencrews ohne politische Einmischung helfen können.",al={"ist diese quest neutral","horde oder allianz"}},{q="Warum veranstalten Gnome und Goblins Rennen in Tausend Nadeln?",a="Die Schimmernde Ebene bietet eine weite, ebene Fläche aus festem Salz ohne Hindernisse. Das macht sie zum Erprobungsgelände für experimentelle Hochgeschwindigkeitsraketenwagen und Dragster.",al={"warum eine rennbahn hier","warum die illusionenrennbahn"}},{q="Lässt der Treibstoff den Wagen tatsächlich fliegen?",a="Fizzel behauptet voller Begeisterung, der Wagen werde „fliegen“, doch gnomische Raketenfahrzeuge auf den Salzebenen sind dafür gebaut, mit halsbrecherischer Geschwindigkeit über den Boden zu rasen. Katastrophales Abheben und Unfälle bleiben möglich.",al={"fliegt der wagen","fizzels raketenwagen ergebnis"}}},fp="15,168,17.294.0,30.392.0,46.191.0,42.119.0,50.151.0,55.162.0,54.178.0,40.189.0"}
P.entries["quest:1105"] = {n="Gehärtete Schalen",s="Auf der Illusionenrennbahn fürchtet Wizzel Kupferbolz, dass der Treibstoff seines Bruders ihren Rennwagen zerfrisst. Er sucht Schildkrötenschalen, um die Tanks zu schützen.",h="Auf der Illusionenrennbahn fürchtet Wizzel Kupferbolz, dass der Treibstoff seines Bruders ihren Rennwagen...",kw={"gehärtete schalen","illusionenrennbahn","raketenwagen","die schimmernde ebene","tausend nadeln","landschildkröte","wizzel kupferbolz"},ang={["profession:Engineering"]="Organische Panzerplatten als Behälter für instabile Verbindungen zu verwenden, ist eine unkonventionelle Wahl. Sie zeigt, wie sehr sich gnomische Tüftler unter Druck auf Versuch und Irrtum verlassen.",["race:Gnome"]="Brüderlicher Erfindungsgeist und rücksichtsloser wissenschaftlicher Ehrgeiz treffen hier aufeinander. Die Arbeit verkörpert den gnomischen Drang, trotz aller logistischen Hürden die Goblinrivalen mit neuen Erfindungen zu übertreffen."},sec={{t="Explosive Innovationen",b="Auf der Illusionenrennbahn wetteifern Wizzel Kupferbolz und sein Bruder darum, Gobliningenieure zu übertreffen. Ihr maßgefertigter Raketenwagen fährt mit einer experimentellen Treibstoffmischung, die sein Bruder entwickelt hat. Die Mischung ist so stark, dass Wizzel fürchtet, sie werde das übliche Fahrgestell und die Tanks des Wagens zerfressen. Er braucht einen Behälter, der robust genug ist, um sie über die Schimmernde Ebene zu transportieren."},{t="Gepanzerte Lösungen der Wüste",b="Wizzel wendet sich den Schildkröten zu, die in Tausend Nadeln heimisch sind. Ihre Schalen widerstehen rauen Umwelteinflüssen und mechanischem Verschleiß, könnten also dort standhalten, wo veredeltes Metall versagt. Er hofft, die gehärteten Schalen zu sammeln und daraus Treibstofftanks zu formen. Sie müssen die instabile Mischung aufnehmen und verhindern, dass der Raketenwagen in Stücke fliegt."}},faq={{q="Warum braucht Wizzel Schildkrötenschalen statt Metall?",a="Wizzels Bruder braut experimentellen Raketentreibstoff, der Metall auflösen kann. Wizzel hofft, dass die Schalen der heimischen Schildkröten der chemischen Belastung besser standhalten als gewöhnliche Tanks.",al={"warum schildkrötenschalen","warum landschildkrötenschalen","treibstofftank schale"}},{q="Wer ist Wizzel Kupferbolz?",a="Wizzel Kupferbolz ist ein Gnomeningenieur auf der Illusionenrennbahn in der Schimmernden Ebene. Er und sein Bruder bauen einen Raketenwagen und stimmen ihn fein ab, um ihre Goblinkonkurrenten abzuhängen.",al={"wizzel","wer ist wizzel"}},{q="Wo sind die Schildkröten zu finden?",a="Schildkröten durchstreifen die Salzpfanne der Schimmernden Ebene und sammeln sich besonders zahlreich beim alten Schiffswrack im Nordosten.",al={"landschildkröten fundort","wo sind die schildkröten","wo gibt es gehärtete schalen"}},{q="Ist dies eine Quest für die Allianz oder die Horde?",a="Die Illusionenrennbahn hält sich aus dem Krieg der Fraktionen heraus und konzentriert sich auf Ingenieurswettbewerbe. Abenteurer beider Fraktionen können Wizzel helfen.",al={"ist gehärtete schalen neutral","allianz oder horde"}},{q="Was geschieht, sobald die Schalen geliefert sind?",a="Sobald die Schalen eintreffen, beginnt Wizzel, daraus verstärkte Treibstofftanks zu formen. Sie sind so widerstandsfähig, dass er damit rechnet, beim Bearbeiten einen ganzen Werkzeugkasten zu ruinieren.",al={"wizzel schalen ergebnis","was macht wizzel mit schalen"}},{q="Warum ist ein Versagen der Treibstofftanks auf der Ebene so besorgniserregend?",a="Raketenwagen rasen mit beängstigender Geschwindigkeit über das Salz. Wizzel fürchtet, dass der Treibstoff seines Bruders das Fahrgestell des Wagens zerfressen könnte, deshalb will er verstärkte Tanks, bevor das geschieht.",al={"raketenwagen gefahr","warum sorge um treibstoff"}}},fx={["201b3417"]={q="Warum möchte Wizzel Kupferbolz, dass dies erledigt wird?",a="Wizzels Bruder entwickelt einen extrem flüchtigen neuen Treibstoff für ihr Raketenauto auf der Illusionenrennbahn. Obwohl Wizzel die Genialität seines Bruders bewundert, hat er große Angst, dass die Mixtur ätzend genug ist, um während der Tests direkt durch das bestehende Chassis des Autos zu schmelzen. Um eine katastrophale Katastrophe auf den Salzebenen zu verhindern, muss Wizzel stabilere Ersatztanks herstellen, bevor sein Bruder die Mischung fertigstellt.",al={"wizzle motiv","warum wizzle helfen","warum will wizzle schalen"}},["5a3ddfa8"]={q="Was sind die Schildkröten der Schimmernden Ebene?",a="Funkelschalen-Schildkröten durchstreifen die sonnenverbrannten Weiten der Schimmernden Ebene. Über Generationen hinweg sind ihre Panzer in dem rauen, trockenen Becken bemerkenswert hart und widerstandsfähig geworden. Zwischen den Salzkrusten bleiben sie meist für sich und sind damit ein ideales, robustes Naturmaterial für gnomische Tüftler, die dringend nicht reaktive, hitzebeständige Panzerplatten benötigen.",al={"salzschildkröten","schildkröten der schimmernden ebene","warum gibt es hier schildkröten?"}}},fp="15,143,20.346.0,24.315.0,54.174.0,25.172.0,33.108.0,35.139.0,43.146.1,53.177.0"}
P.entries["quest:1106"] = {n="Martek der Verbannte",s="An der Illusionenrennbahn sucht Fizzel Kupferbolz Kolben, die stark genug für den Motor sind, der seinen Wagen in die Luft tragen soll. Er schickt Euch mit einem Brief zu Martek dem Verbannten, der im Ödland lagert.",h="An der Illusionenrennbahn sucht Fizzel Kupferbolz Kolben, die stark genug für den Motor sind, der seinen...",kw={"ödland","fizzel kupferbolz","gath'ilzogg","martek der verbannte","illusionenrennbahn","kolben","tausend nadeln"},sec={{t="Ein Brief für den Schmied",b="Nach Salt Flat Venom erzählt Euch Fizzel, sein neuer Motor solle seinen Wagen so schnell machen, dass er fliegen könnte. Seine Versuche sind gescheitert, weil er keine Kolben schmieden kann, die der Belastung standhalten. Er kennt einen Schmied, der helfen könnte: Martek den Verbannten, der mehr über Metall weiß als jeder andere. Martek lagert weit entfernt im Ödland mit einem Goblin, und Ihr überbringt ihm Fizzels Brief."},{t="Im Lager",b="Im Lager begrüßt Martek Euch misstrauisch. Er fragt, ob Ihr wegen einer für Gath'Ilzogg gefertigten Axt gekommen seid oder um die Ehre von Duchess Pamay wiederherzustellen. Wenn Ihr einen Kampf sucht, sagt er, könne er genauso gut jetzt beginnen."},{t="Marteks Antwort",b="Als Martek erfährt, dass Fizzel Euch geschickt hat, ändert sich sein Verhalten. Fizzel und sein Bruder gehören zu den wenigen, die Martek nicht tot sehen wollen. Also erklärt sich Martek bereit, bei der Herstellung von Kolben zu helfen, die der von Fizzel vorgesehenen Belastung standhalten. Für Martek klingt der neue Wagen wie ein Vulkan auf Rädern."}},faq={{q="Warum braucht Fizzel Kupferbolz Marteks Hilfe?",a="Fizzels neuer Motor soll seinen Wagen schnell genug zum Fliegen machen, doch seine Versuche sind gescheitert, weil er keine Kolben herstellen kann, die der Belastung standhalten. Martek weiß mehr über Metall als jeder andere und könnte helfen.",al={"warum martek besuchen","fizzel kupferbolz kolbenproblem","warum martek der verbannte"}},{q="Wo befindet sich Martek der Verbannte?",a="Martek lagert mit einem Goblin im Ödland.",al={"wo ist martek","martek der verbannte standort","wie martek finden"}},{q="Was ging dieser Reise voraus?",a="Salt Flat Venom geht dieser Reise in der Questreihe voraus, und Indurium folgt darauf.",al={"voraussetzungen für martek den verbannten","welche quest kommt vor martek dem verbannten"}}},fp="17,198,22.364.0,11.206.1,14.268.1,46.214.0,35.47.0,30.80.0"}
P.entries["quest:1107"] = {n="Verkrustete Schwanzflossen",s="An der Illusionenrennbahn fürchtet Wizzel Kupferbolz, dass die Geschwindigkeit den Raketenwagen zerreißen wird. Schwanzflossen der Saltscale-Murlocs vom Finsteren Riff vor dem Schlingendorntal könnten ihn schützen.",h="An der Illusionenrennbahn fürchtet Wizzel Kupferbolz, dass die Geschwindigkeit den Raketenwagen zerreißen...",kw={"verkrustete schwanzflossen","illusionenrennbahn","raketenwagen","saltscale-murlocs","die schimmernde ebene","schlingendorntal","das finstere riff","wizzel kupferbolz"},sec={{t="Eine Beschichtung für den Wagen",b="Wizzel nennt den Raketenwagen das schnellste Ding auf der Schimmernden Ebene. Doch die Reibung könnte ihn zerreißen. Seine beweglichen Teile brauchen eine Beschichtung, die hart ist, ohne spröde zu sein, und Salzkorrosion widersteht. Andernfalls wird die Ebene den Wagen zerfressen. Die Hauptzutat sind zehn Schwanzflossen der Saltscale-Murlocs am Finsteren Riff vor dem Schlingendorntal."},{t="Der fertige Verbundstoff",b="Wizzel zermahlt die Flossen zu Pulver und vermischt sie mit ein paar anderen Zutaten. Der fertige Verbundstoff sollte den Wagen vor seiner eigenen Geschwindigkeit schützen, solange er nirgends gegenfährt."}},faq={{q="Warum braucht Wizzel Kupferbolz verkrustete Schwanzflossen?",a="Wizzel fürchtet, dass der Raketenwagen so schnell ist, dass die Reibung ihn zerreißen wird. Die Flossen sind eine Hauptzutat für einen Verbundstoff für seine beweglichen Teile, der hart ist, ohne spröde zu sein, und Salzkorrosion widersteht.",al={"warum schwanzflossen","wizzel schwanzflossen zweck","warum murlocflossen"}},{q="Wo sind die Saltscale-Murlocs zu finden?",a="Die Saltscale-Murlocs leben am Finsteren Riff vor der Küste des Schlingendorntals, fast genau westlich vom Basislager Grom'gol.",al={"finsteres riff lage","wo sind saltscale-murlocs","wo verkrustete flossen finden"}},{q="Was kam für Wizzel davor?",a="Hardened Shells kommt in der Questreihe vor Verkrustete Schwanzflossen.",al={"welche quest kommt zuerst","wizzel questreihe vorherige quest","voraussetzung für verkrustete schwanzflossen"}},{q="Wer ist Wizzel Kupferbolz?",a="Wizzel Kupferbolz ist an der Illusionenrennbahn. Aus Sorge, dass die Reibung den Raketenwagen zerreißen wird, bittet er Euch, ihm die Flossen zu bringen.",al={"wer ist wizzel","wer vergibt verkrustete schwanzflossen"}}},fp="19,176,21.351.0,22.180.1,52.199.0,41.119.0,33.62.0,25.132.0"}
P.entries["quest:1108"] = {n="Indurium",s="Im Ödland sucht Martek the Exiled Metallproben für Fizzels Wagen. Indurium soll Hitze und Belastung standhalten, und Stonevault-Troggs tragen manchmal Flocken davon bei sich.",h="Im Ödland sucht Martek the Exiled Metallproben für Fizzels Wagen.",kw={"agmondkuppe","ödland","fizzel kupferbolz","indurium","induriumflocken","martek the exiled","illusionenrennbahn","stonevault-troggs","uldaman"},sec={{t="Ein Metall auf dem Prüfstand",b="Martek the Exiled bleibt nicht nur der Einsamkeit wegen im Ödland. Er glaubt, dass Indurium für Fizzels Wagen taugen könnte, weil es Hitze und Belastung standhalten soll. Er möchte Proben für einen Test, und die Schmiede steht bereit."},{t="Flocken von den Troggs",b="Echtes Induriumerz liegt tief in Uldaman, doch Stonevault-Troggs im Ödland tragen manchmal Flocken davon bei sich. Martek bittet um zehn. Die Troggs durchstreifen den Südosthang einer Felsformation an der Agmondkuppe, gleich südlich des Fangzahntals."},{t="Die Schmiedeprobe",b="Martek erhitzt die Flocken in seiner Schmiede und steigert die Hitze stufenweise. Sie halten stand, und er schwört bei Orgrim, dass Indurium enormer Hitze trotzen kann. Der Test gelingt. Martek nennt das Metall erstaunliches Zeug."}},faq={{q="Wer schickt Euch auf die Suche nach Indurium?",a="Martek the Exiled bittet im zentralen Ödland um Induriumproben. Die Questreihe, die zu ihm führt, beginnt bei Fizzel Kupferbolz an der Illusionenrennbahn in Tausend Nadeln.",al={"wer gibt die induriumquest","wo gibt es indurium"}},{q="Warum braucht Martek Indurium?",a="Martek glaubt, dass Indurium für Fizzels Wagen taugen könnte, weil es Hitze und Belastung standhalten soll. Er möchte Proben, um sie in seiner Schmiede zu testen.",al={"wofür wird indurium verwendet","warum indurium"}},{q="Wo sind die Induriumflocken zu finden?",a="Stonevault-Troggs im Ödland tragen manchmal Induriumflocken bei sich. Sie durchstreifen den Südosthang einer Felsformation an der Agmondkuppe, gleich südlich des Fangzahntals.",al={"wo sind induriumflocken","wie bekommt man flocken","wer lässt induriumflocken fallen"}},{q="Woher stammt echtes Induriumerz?",a="Martek sagt, dass echtes Induriumerz tief in Uldaman liegt.",al={"wo ist induriumerz","wo wird indurium abgebaut"}},{q="Was kommt davor?",a="Martek the Exiled kommt in der Questreihe zuerst, die bei Fizzel Kupferbolz an der Illusionenrennbahn beginnt.",al={"vorherige quest indurium","wie beginnt indurium"}},{q="Was folgt nach der Abgabe der Flocken?",a="Die Questreihe geht mit News for Fizzle weiter.",al={"nächste quest nach indurium","was passiert als nächstes"}}},fp="8,162,21.203.0,22.228.0,14.204.1,33.160.0,30.131.0,39.166.0,39.51.0,23.102.0,42.41.0"}
P.entries["quest:1109"] = {n="Going, Going, Guano!",s="Apothekermeister Faranell sucht Guano von den Kraul Bats im Kral der Klingenhauer. Die Royal Apothecary Society benötigt ihn für ihre Experimente.",h="Apothekermeister Faranell sucht Guano von den Kraul Bats im Kral der Klingenhauer.",kw={"going going guano","kraul bats","kraul guano","apothekermeister faranell","kral der klingenhauer","royal apothecary society","unterstadt"},sec={{t="Eine seltene Substanz",b="Apothekermeister Faranell beaufsichtigt die alchemistischen Arbeiten der Royal Apothecary Society in Unterstadt. Er benötigt Guano von Kraul Bats, einer seltenen Art, die im Kral der Klingenhauer vorkommt. Ihr sollt ihm einen Haufen bringen, damit die Gesellschaft mit ihrer Arbeit beginnen kann."}},faq={{q="Wer benötigt Kraul Guano?",a="Apothekermeister Faranell von der Royal Apothecary Society benötigt ihn für die Arbeit der Gesellschaft.",al={"wer will guano","faranell guano","apotheker kerl"}},{q="Wo leben Kraul Bats?",a="Kraul Bats sind im Kral der Klingenhauer zu finden.",al={"kraul bats fundort","wo fledermäuse","fledermausguano"}},{q="Wozu dient Kraul Guano?",a="Faranell benötigt ihn, damit die Royal Apothecary Society mit ihrer alchemistischen Arbeit beginnen kann.",al={"warum guano","wozu dient guano","apothekerexperimente"}},{q="Wohin bringe ich den Guano?",a="Bringt den Haufen Kraul Guano zu Apothekermeister Faranell in Unterstadt.",al={"wohin guano bringen","guano abliefern","faranell standort"}}},fp="20,136,16.243.0,22.93.0,25.39.0,24.80.0,27.77.0"}
P.entries["quest:111"] = {n="Gespräch mit Oma",s="Tommy Joe Steinfeld bittet Oma Steinfeld um einen Weg, Maybell Maclure zu erreichen. Ihre Familien halten sie auseinander, und er hofft, sie zu treffen, ohne ihre Verwandten in einen Konflikt zu verwickeln.",h="Tommy Joe Steinfeld bittet Oma Steinfeld um einen Weg, Maybell Maclure zu erreichen.",kw={"wald von elwynn","oma steinfeld","weinberge der maclures","maybell maclure","gespräch mit oma","hof der steinfelds","tommy joe steinfeld","junge liebende"},ang={["faction:Alliance"]="Während Sturmwind mit Unruhen der Defias und Angriffen wilder Tiere kämpft, müsst Ihr womöglich Streit zwischen benachbarten Bauern schlichten.",["race:Human"]="Als Mensch in Elwynn erlebt Ihr, wie tief örtlicher Groll im Kernland von Sturmwind verwurzelt ist, selbst inmitten der Schwierigkeiten im ganzen Königreich."},sec={{t="Fehde und verbotene Liebe",b="Tommy Joe und Maybell verbergen ihre Liebe vor ihren Familien. Er wendet sich an Oma Steinfeld und hofft, dass sie ihnen eine Gelegenheit für ein heimliches Treffen verschaffen kann. Ihre Verwandten dürfen die Romanze nicht entdecken und alte Feindseligkeit in Gewalt umschlagen lassen."},{t="Omas List",b="Oma Steinfeld weiß, dass die Familien nicht wirklich zusammenfinden können, solange der Groll zwischen ihnen fortbesteht. Dennoch will sie die Hoffnungen des jungen Paares daran nicht scheitern lassen. Sie beginnt, nach kleinen Gelegenheiten zu suchen, Tommy Joe und Maybell zusammenzubringen."}},faq={{q="Warum möchte Tommy Joe, dass ich mit seiner Oma spreche?",a="Tommy Joe liebt Maybell Maclure, doch die Fehde ihrer Familien hält sie auseinander. Er hofft, dass seine Großmutter heimliche Treffen ermöglichen kann, ohne Aufruhr zu verursachen.",al={"warum oma","tommy joe oma","gespräch mit oma zweck"}},{q="Wo ist Oma Steinfeld zu finden?",a="Oma Steinfeld hält sich im Haupthaus des Steinfeld-Hofs auf, südlich von Goldhain und östlich des Flussufers, an dem Tommy Joe sich versteckt.",al={"oma steinfeld aufenthaltsort","wo ist oma","oma steinfeld finden"}},{q="Was steckt hinter der Fehde zwischen den Steinfelds und den Maclures?",a="Die benachbarten Bauernfamilien hegen seit Langem persönlichen Groll gegeneinander und streiten um Land. Sie beschuldigen einander des Diebstahls und wetteifern um Ernteerträge, während Misstrauen beide Familien an den Rand der Gewalt treibt. Ihre Kinder müssen jeden Kontakt geheim halten.",al={"steinfeld maclure fehde","warum streiten sie","familienfehde elwynn"}},{q="Ist Oma Steinfeld gegen Tommy Joes Beziehung?",a="Nein. Oma weiß, dass die Fehde eine dauerhafte gemeinsame Zukunft erschwert, doch die jungen Liebenden liegen ihr am Herzen, und sie wird Wege für ihre Treffen ersinnen.",al={"ist oma gegen maybell","unterstützt oma die liebenden"}},{q="Was geschieht nach dem Gespräch mit Oma?",a="Oma beginnt zu planen, wie sie Tommy Joe und Maybell heimlich zusammenbringen kann. Sie schickt Euch los, um die Zutaten für einen Unsichtbarkeitsschnaps zu sammeln, mit dem sie an ihren wachsamen Familien vorbeikommen.",al={"was folgt auf gespräch mit oma","oma folgequest"}},{q="Wer ist Maybell Maclure?",a="Maybell Maclure ist die Tochter der verfeindeten Familie, die auf der anderen Straßenseite gegenüber den Steinfelds lebt. Sie unterhält eine heimliche Liebesbeziehung mit Tommy Joe Steinfeld.",al={"wer ist maybell","maybell maclure"}}},fx={ba5df8a9={q="Warum braucht Tommy Joe einen Außenstehenden, der mit seiner Großmutter spricht?",a="Tommy Joe versteckt sich am Flussufer nahe dem Hof der Steinfelds, um sich heimlich mit Maybell Maclure zu treffen. Würde er selbst zum Bauernhaus seiner Familie zurückkehren, könnte das Aufmerksamkeit auf seine verbotene Liebe lenken, besonders angesichts der großen Spannungen zwischen den beiden verfeindeten Familien. Als durchreisender Fremder könnt Ihr Euch unauffällig an Oma Steinfeld wenden, ohne den übrigen Haushalt aufzuschrecken.",al={"warum ich tommy joe","warum spieler zu oma schicken","warum kann tommy nicht mit oma sprechen"}}},fp="17,177,25.220.0,16.219.0,52.156.0,37.129.0,58.231.0,55.133.0,38.176.1,23.144.0"}
P.entries["quest:1110"] = {n="Raketenwagenteile",s="An der Illusionenrennbahn liegen nach Rennunfällen Raketenwagenteile über die Schimmernde Ebene verstreut. Kravel Kohlebart bezahlt Reisende dafür, die Wrackteile zu sammeln und sie an rivalisierende Teams zurückzuverkaufen.",h="An der Illusionenrennbahn liegen nach Rennunfällen Raketenwagenteile über die Schimmernde Ebene verstreut.",kw={"unfälle","gnom","goblin","kravel kohlebart","illusionenrennbahn","raketenwagenteile","bergung","schrott","die schimmernde ebene","tausend nadeln"},ang={["profession:Engineering"]="Die Salzflächen zeugen vom waghalsigen Erfindungsreichtum der Goblin- und Gnomenkonstrukteure. Instabile Raketenantriebe und improvisierte Fahrgestelle versagen oft mit einem Knall.",["race:Dwarf"]="Als Zwerg erkennt Ihr in Kravel Kohlebart womöglich einen Hang zur Geschäftemacherei. Viele Zwerge aus Eisenschmiede interessieren sich für technische Neuerungen oder Ausgrabungen an der Rennbahn, doch ihn lockt nur das Geld aus der Schrottbergung.",["race:Gnome"]="Als Gnom erkennt Ihr den unermüdlichen Drang, die Goblinkonkurrenz auf der offenen Rennstrecke durch Tempo und Erfindergeist zu übertreffen. Manchmal endet dieses Streben in einer Katastrophe."},sec={{t="Trümmer auf den Salzflächen",b="Goblin- und Gnomeningenieure wetteifern auf der Schimmernden Ebene darum, einander zu übertreffen. Ihre experimentellen Raketenwagen versagen oft bei hohem Tempo. Verbogene Zahnräder, Zylinder und scharfkantige Metallstücke verteilen sich über die weiße Wüste. Während die Boxencrews ihre nächsten Maschinen bauen und abstimmen, sammeln sich auf den Salzflächen die Überreste der Rennen."},{t="Kohlebarts Bergungsgeschäft",b="Kravel Kohlebart verdient sein Geld als Zwischenhändler an der Illusionenrennbahn, statt auf der Strecke anzutreten. Gnomen- und Goblinmechaniker verbrauchen schnell Teile und haben ständig zu wenige Ersatzmechanismen für ihre Fahrzeuge. Deshalb bezahlt Kohlebart Reisende dafür, dreißig Bündel zertrümmerter Teile zu sammeln. Er macht jeden Unfall zu einem Warenvorrat, den er an die Teams zurückverkaufen kann."}},faq={{q="Wer ist Kravel Kohlebart?",a="Kravel Kohlebart ist ein zwergischer Händler an der Illusionenrennbahn auf der Schimmernden Ebene. Er verfolgt rund um die Strecke mehrere Geschäfte, sammelt Schrott und übernimmt Gelegenheitsarbeiten, während er von der Rivalität zwischen Gnomen und Goblins profitiert.",al={"kravel kohlebart","wer vergibt raketenwagenteile","zwerg an der rennbahn"}},{q="Warum liegen so viele Raketenwagenteile auf dem Boden verstreut?",a="Goblin- und Gnomeningenieure treiben ihre experimentellen Raketenfahrzeuge an der Illusionenrennbahn bis an die Grenzen. Ihre Unfälle und plötzlichen Explosionen verstreuen Bauteile, Zahnräder und Zylinder über die Salzpfannen.",al={"warum liegen wagenteile in der wüste","trümmer auf der schimmernden ebene","kaputte raketenwagen"}},{q="Was macht Kravel mit den Wrackteilen?",a="Kohlebart sammelt den Schrott und verkauft ihn an die Rennteams der Gnome und Goblins zurück. Ihre Mannschaften verbrauchen schnell Material und kaufen bereitwillig Teile für ihre nächsten Prototypen.",al={"was will kravel mit den teilen","warum wagenteile sammeln"}},{q="Wo liegen diese Teile?",a="Die Teile liegen auf dem offenen Wüstenboden der Schimmernden Ebene rund um das zentrale Rennlager. In den Haufen finden sich mechanischer Schrott, verbogene Zahnräder, Zylinder und plattgedrückte Metallplatten.",al={"wo raketenwagenteile finden","fundorte der teile","wagenteile auf der schimmernden ebene"}},{q="Hängt diese Quest mit anderen Aufgaben rund um die Rennbahn zusammen?",a="Ja. Reisende können Teile sammeln, während sie für andere Auftraggeber an der Rennbahn die örtlichen Tierbestände dezimieren. Dazu gehören das Sammeln von Gift aus Skorpidstacheln und von Schildkrötenpanzern sowie das Ausdünnen der Bussard- und Basiliskenbestände auf den Salzpfannen.",al={"quests an der rennbahn","jagdquests auf der schimmernden ebene","quests zusammen mit raketenwagenteile"}},{q="Was geschieht mit den Fahrern bei diesen Unfällen?",a="Raketenwagenrennen sind lebensgefährlich, und viele Piloten sterben bei ihren Testfahrten. Beim Sortieren von Schrott findet Kohlebart ein abgetrenntes Ohr, das zwischen Metallplatten zerquetscht wurde.",al={"überleben fahrer die unfälle","zerquetschtes ohr","tote piloten an der rennbahn"}}},fx={["16d6be49"]={q="Wofür werden die Raketenwagenteile verwendet?",a="Es handelt sich um verbogenen Schrott – Zahnräder, Zylinder und Metallreste, die bei Hochgeschwindigkeitskollisionen auf den Salzebenen weggeschleudert wurden. Anstatt sie in der Salzlauge verrotten zu lassen, sammelt Kravel Kohlebart sie ein, um sie direkt an die hektischen Gnom- und Goblin-Boxencrews weiterzuverkaufen. In ihrer Verzweiflung, ihre zerstörten Rennwagen wieder aufzubauen und ihre Rivalen technisch zu übertrumpfen, kaufen beide Seiten den Schrott gerne zurück, um ihn an ihre nächste waghalsige Konstruktion zu schweißen.",al={"nutzung von raketenwagenteilen","wofür sind raketenwagenteile","warum raketenwagenteile sammeln"}}},fp="16,189,24.310.0,30.347.0,24.208.0,63.199.0,43.169.0,30.191.0,56.226.0,53.149.0"}
P.entries["quest:1111"] = {n="Werftmeister Dizzywig",s="An der Illusionenrennbahn schickt Kravel Kohlebart Euch nach Ratschet, um Teile zu holen, auf die die Gnome warten.",h="An der Illusionenrennbahn schickt Kravel Kohlebart Euch nach Ratschet, um Teile zu holen, auf die die Gnome...",kw={"kravel kohlebart","illusionenrennbahn","teilebestellung","ratschet","tausend nadeln","wharfmaster dizzywig"},sec={{t="Laufarbeit für Kravel",b="Kravel Kohlebart kümmert sich um die Belange der Illusionenrennbahn. Eine Lieferung mit Teilen ist vor einer Woche in Ratschet eingetroffen, und die Gnome warten darauf. Da Kravel die Reise nicht selbst antreten kann, bittet er Euch, seine Bestellung zu überbringen. Wenn Ihr das tut, verspricht er Euch weitere Arbeit mit Aussicht auf beträchtlichen Gewinn."},{t="Die Docks von Ratschet",b="Ratschet liegt im Brachland, wo Kravel Werftmeister Dizzywig an den Docks vermutet. Der Goblin ist derjenige, den Ihr aufsuchen müsst. Ihr bringt Kravels Teilebestellung dorthin."}},faq={{q="Wer schickt Euch zu Werftmeister Dizzywig?",a="Kravel Kohlebart, ein Zwerg auf der Illusionenrennbahn in Tausend Nadeln, gibt Euch seine Teilebestellung und schickt Euch nach Ratschet.",al={"wer vergibt wharfmaster dizzywig","kravel kohlebart quest"}},{q="Wo ist Werftmeister Dizzywig zu finden?",a="Werftmeister Dizzywig, ein Goblin, wird vermutlich an den Docks von Ratschet im Brachland sein.",al={"dizzywig aufenthaltsort","wo ist dizzywig","wo man dizzywig findet"}},{q="Was ist der Zweck von Kravels Bestellung?",a="Die Gnome der Illusionenrennbahn warten auf Teile, die vor einer Woche in Ratschet eingetroffen sind. Kravel kann nicht selbst gehen, also bittet er Euch, seine Bestellung zu den dortigen Docks zu bringen.",al={"wofür sind die teile","warum nach ratschet reisen"}},{q="Was kommt nach Werftmeister Dizzywig?",a="Der nächste Schritt in der Reihe ist Parts for Kravel.",al={"folgequest nach dizzywig","what comes next"}}},fp="20,97,18.273.0,20.167.0,38.120.0,40.88.0,38.167.0,38.47.0"}
P.entries["quest:1112"] = {n="Teile für Kravel",s="An der Illusionenrennbahn erwartet Kravel Kohlebart das Paket, das Ihr von Werftmeister Dizzywig bringt. Dizzywig schickt eine Warnung mit: Kravel muss seine Zeche bezahlen, bevor er weitere Sonderbestellungen erhalten kann.",h="An der Illusionenrennbahn erwartet Kravel Kohlebart das Paket, das Ihr von Werftmeister Dizzywig bringt.",kw={"kravel kohlebart","illusionenrennbahn","teile für kravel","die schimmernde ebene","tausend nadeln","wharfmaster dizzywig"},sec={{t="Ein Paket und eine Zeche",b="Werftmeister Dizzywig gibt Euch ein Paket für Kravel Kohlebart an der Illusionenrennbahn. Die Rennbahn liegt auf der Schimmernden Ebene in Tausend Nadeln. Dizzywig bittet Euch, mit dem Paket eine Warnung zu überbringen: Kravel muss seine Schulden begleichen, bevor er weitere Sonderbestellungen erhalten kann."},{t="Kravels Empfang",b="Kravel freut sich über das Paket und sagt, dass es noch zu den Gnomen gelangen muss. Bevor es weiterreist, stellt er die Kiste ab, nimmt einen kleinen Gegenstand heraus und steckt ihn in seine Tasche."}},faq={{q="Wer gibt Euch das Paket für Kravel?",a="Werftmeister Dizzywig in Ratschet gibt Euch Kravels Paket und bittet Euch, es zu Kravel Kohlebart zu bringen.",al={"wer startet teile für kravel","woher kommen die teile","teile für kravel questgeber"}},{q="Wo erwartet Kravel Kohlebart die Lieferung?",a="Kravel Kohlebart erwartet die Lieferung an der Illusionenrennbahn auf der Schimmernden Ebene in Tausend Nadeln.",al={"kravel kohlebart standort","wo ist kravel","wo teile für kravel abgeben"}},{q="Welche Nachricht möchte Dizzywig zusammen mit den Teilen überbringen lassen?",a="Dizzywig bittet Euch, Kravel auszurichten, dass er seine Zeche bezahlen muss, bevor er weitere Sonderbestellungen erhalten kann.",al={"was sagt dizzywig","dizzywigs nachricht an kravel","kravels zeche"}},{q="Was geschah vor dieser Lieferung?",a="Bevor Ihr dieses Paket zurückgebracht habt, habt Ihr Kravels Teilebestellung zu Werftmeister Dizzywig in Ratschet gebracht.",al={"teile für kravel voraussetzung","vorherige quest teile für kravel"}}},fp="16,196,19.273.0,16.181.1,37.104.0,47.103.0,62.100.0,31.103.0"}
P.entries["quest:1113"] = {n="Hearts of Zeal",s="Apothekermeister Faranell braucht Hearts of Zeal für ein gefährliches Experiment. Er bittet Euch, sie von Jüngern des Scharlachroten Kreuzzugs im Scharlachroten Kloster zu sammeln.",h="Apothekermeister Faranell braucht Hearts of Zeal für ein gefährliches Experiment.",kw={"experiment","hearts of zeal","apothekermeister faranell","scharlachroter kreuzzug","das scharlachrote kloster","tirisfal","unterstadt"},sec={{t="Faranells Experiment",b="Faranell sucht eine seltene Art von Guano für sein Experiment in Unterstadt. Er plant, gegensätzlich wirkende chemische Substanzen mit einem Giftstoff zu verbinden. Im Scharlachroten Kloster im Nordosten von Tirisfal sollt Ihr ihm die eifernden Herzen der Jünger des Scharlachroten Kreuzzugs bringen."}},faq={{q="Wer will die Hearts of Zeal?",a="Apothekermeister Faranell in Unterstadt will die Hearts of Zeal für ein Experiment.",al={"wer will herzen","faranell herzen"}},{q="Wo sind die Jünger des Scharlachroten Kreuzzugs?",a="Die Jünger versammeln sich im Scharlachroten Kloster auf den nordöstlichen Gipfeln von Tirisfal.",al={"wo jünger finden","scharlachrotes kloster herzen"}},{q="Was hat Faranell mit den Herzen vor?",a="Faranell führt ein Experiment mit gegensätzlich wirkenden chemischen Substanzen und einem Giftstoff durch und will die eifernden Herzen.",al={"warum hearts of zeal","was stellt faranell her"}},{q="Wie viele Hearts of Zeal braucht Faranell?",a="Faranell bittet um zwanzig Hearts of Zeal.",al={"wie viele herzen","anzahl der herzen"}}},fp="14,159,21.275.0,29.87.0,40.91.0,46.119.0,43.40.0"}
P.entries["quest:1114"] = {n="Lieferung für die Gnome",s="Kravel Kohlebart schickt Empfindliche Autoteile von der Illusionenrennbahn zu Fizzel Kupferbolz in der Schimmernden Ebene. Fizzel wartet schon lange darauf, und Kravel bittet Euch, ein kleines Teil zu verschweigen, das er herausgenommen hat.",h="Kravel Kohlebart schickt Empfindliche Autoteile von der Illusionenrennbahn zu Fizzel Kupferbolz in der...",kw={"empfindliche autoteile","lieferung für die gnome","fizzel kupferbolz","hydroratschen","kravel kohlebart","illusionenrennbahn","repetierbolzen","die schimmernde ebene","tausend nadeln"},sec={{t="Ein Teil fehlt",b="Kravel Kohlebart schickt die Teile zu Fizzel Kupferbolz, der schon lange darauf wartet. Kravel gibt zu, ein kleines Teil aus Fizzels Bestellung herausgenommen zu haben. Er sagt, es sei klein und wertlos und Fizzel werde es nicht vermissen. Dann bittet er Euch, ihm zu vertrauen und es unerwähnt zu lassen."},{t="Fizzels Urteil",b="Fizzel Kupferbolz nimmt das Paket erfreut entgegen. Seine Hydroratschen und Repetierbolzen sind endlich angekommen. Sie werden ihren Zweck schon erfüllen."}},faq={{q="Wer schickt die Teile zu Fizzel Kupferbolz?",a="Kravel Kohlebart schickt die Teile von der Illusionenrennbahn und bittet Euch, sie zu Fizzel Kupferbolz zu bringen.",al={"wer vergibt lieferung für die gnome","questgeber lieferung für die gnome","wer schickt die teile"}},{q="Was hat Kravel Kohlebart aus dem Paket genommen?",a="Kravel sagt, er habe ein kleines Teil aus Fizzels Bestellung herausgenommen. Er nennt es klein und wertlos und bittet Euch dann, Fizzel gegenüber nichts davon zu erwähnen.",al={"was hat kravel genommen","was fehlt bei den teilen","kravel hat teile gestohlen"}},{q="Wohin geht diese Lieferung?",a="Die Teile gehen an Fizzel Kupferbolz in der Schimmernden Ebene. Auch die Illusionenrennbahn liegt auf dieser Ebene, wo Kravel Kohlebart zu finden ist.",al={"lieferung für die gnome ort","wo ist fizzel kupferbolz","schimmernde ebene lieferung"}},{q="Was kam vor dieser Lieferung?",a="Vor dieser Lieferung habt Ihr Kravels Paket in „Parts for Kravel“ aus Ratschet zurückgebracht.",al={"vorherige quest lieferung für die gnome","was führt zu lieferung für die gnome"}}},fp="22,219,16.279.0,16.124.1,41.105.0,48.136.0,28.134.0,31.89.0"}
P.entries["quest:1115"] = {n="Der Gerüchteverbreiter",s="An der Illusionenrennbahn hat Kravel Kohlebart nun eine Frage zu Nazz Steamboil. Der Goblin-Rennpilot trug einst einen anderen Namen, und Kravel fragt sich, ob das Geheimnis Gewinn bringen könnte. Er schickt Euch zu Krazek in Beutebucht, der vielleicht mehr weiß.",h="An der Illusionenrennbahn hat Kravel Kohlebart nun eine Frage zu Nazz Steamboil.",kw={"beutebucht","kravel kohlebart","krazek","illusionenrennbahn","nazz steamboil","salty sailor tavern","die schimmernde ebene","schlingendorntal","tausend nadeln"},sec={{t="Ein Name zum Nachfragen",b="Kravel Kohlebart sagt, die Goblins seien als Nächste mit einem Gefallen an der Reihe. Er hat gehört, dass Nazz Steamboil, der Goblin-Rennpilot, einst einen anderen Namen trug. Warum wurde er geändert? Hütet Nazz womöglich ein Geheimnis? Kravel glaubt, dass Krazek die Wahrheit kennt. Ihr findet Krazek in der Salty Sailor Tavern in Beutebucht, an der Südspitze des Schlingendorntals. Nützliche Informationen könnten Gewinn bringen."},{t="Krazeks Antwort",b="Krazek kennt Nazz Steamboil als Rennpiloten auf der Schimmernden Ebene. Er sagt, die Wahrheit ließe sich vielleicht aufdecken, doch das werde Mühe, Zeit und Geld kosten."}},faq={{q="Wer schickt Euch zu Krazek?",a="Kravel Kohlebart, ein Zwerg an der Illusionenrennbahn auf der Schimmernden Ebene, schickt Euch zu Krazek.",al={"wer vergibt den gerüchteverbreiter","gerüchteverbreiter questgeber","wer startet die quest"}},{q="Warum interessiert sich Kravel für Nazz Steamboil?",a="Kravel hat gehört, dass Nazz Steamboil, der Goblin-Rennpilot, einst einen anderen Namen trug. Er fragt sich, ob sich dahinter ein Geheimnis verbirgt, das Nazz bewahren möchte, und ob dieses Geheimnis Gewinn bringen könnte.",al={"warum nazz steamboil","kravels motiv nazz","was ist das gerücht"}},{q="Wo ist Krazek zu finden?",a="Krazek ist in der Salty Sailor Tavern in Beutebucht, an der Südspitze des Schlingendorntals.",al={"krazek standort","wo ist krazek","wie krazek finden"}},{q="Was kommt davor?",a="Dies folgt auf „Lieferung für die Gnome“, nachdem Ihr den Gnomen einen Dienst erwiesen habt.",al={"voraussetzung für den gerüchteverbreiter","gerüchteverbreiter vorherige quest","welche quest kommt zuerst"}}},fp="15,236,25.370.0,15.147.1,24.93.0,43.179.0,26.88.0,23.80.0"}
P.entries["quest:1116"] = {n="Traumstaub im Sumpf",s="In den Sümpfen des Elends bittet Euch Krazek, zehn Körnchen Traumstaub von Drachenwelpen zu sammeln. Er kontaktiert Quellen wegen Nazz und sucht zugleich Staub für seinen Schnupftabakbeutel. Bringt ihn ihm zurück, um die gesuchten Informationen zu erhalten.",h="In den Sümpfen des Elends bittet Euch Krazek, zehn Körnchen Traumstaub von Drachenwelpen zu sammeln.",kw={"beutebucht","traumstaub","kravel kohlebart","krazek","illusionenrennbahn","nazz","sümpfe des elends","welpen"},sec={{t="Ein Gefallen für einen Gefallen",b="Krazek sagt, dass es ein beträchtlicher Gefallen sei, etwas über Nazz in Erfahrung zu bringen, und Ihr seid dafür weit von der Schimmernden Ebene angereist. Während er Quellen kontaktiert, bittet er Euch, zehn Körnchen Traumstaub von Drachenwelpen in den Sümpfen des Elends zu sammeln. Der Staub ist für seinen Schnupftabakbeutel bestimmt. Bringt ihn zurück, und Krazek wird Euch die gesuchten Informationen geben."},{t="Wo der Staub liegt",b="Grüne Drachen in den Sümpfen des Elends tragen Traumstaub bei sich. Heranwachsende Welpen und träumende Welpen sind in der südwestlichen Ecke des Sumpfes zu finden."}},faq={{q="Wer bittet um den Traumstaub?",a="Krazek aus Beutebucht bittet Euch um Traumstaub im Austausch für Informationen über Nazz.",al={"wer gibt die traumstaubquest","wer schickt mich in die sümpfe des elends","traumstaub questgeber"}},{q="Warum will Krazek Traumstaub?",a="Krazek will den Staub für einen Schnupftabakbeutel. Er bittet darum, während er Quellen wegen Nazz kontaktiert.",al={"wofür ist traumstaub","warum will krazek staub","traumstaub schnupftabak"}},{q="Wo ist der Traumstaub zu finden?",a="Ihr könnt Drachenwelpen in den Sümpfen des Elends Traumstaub abnehmen. Heranwachsende und träumende Welpen leben in der südwestlichen Ecke des Sumpfes.",al={"wo traumstaub finden","wo ist traumstaub in den sümpfen des elends","traumstaub fundort"}},{q="Wie hängt das mit Kravel Kohlebart zusammen?",a="Kravel Kohlebart von der Illusionenrennbahn hat Euch zu Krazek geschickt, um nach dem Goblinrennfahrer Nazz Steamboil zu fragen. Ihr seid von der Schimmernden Ebene gekommen, um eine Antwort zu finden.",al={"warum bin ich in beutebucht","wie hängt das mit kravel zusammen","verbindung zur schimmernden ebene"}},{q="Was kommt als Nächstes?",a="Als Nächstes folgt Rumors for Kravel.",al={"was folgt auf traumstaub im sumpf","nächste quest traumstaub","rumors for kravel als nächstes"}}},fp="23,217,19.345.0,23.145.0,33.83.0,32.93.0,30.142.0,47.163.0,16.29.0"}
P.entries["quest:1117"] = {n="Gerüchte für Kravel",s="Endlich hat Krazek einen Brief über Nazz Steamboil für Euch, den Ihr Kravel Kohlebart an der Illusionenrennbahn auf der Schimmernden Ebene bringen sollt. Haltet seine Herkunft geheim.",h="Endlich hat Krazek einen Brief über Nazz Steamboil für Euch, den Ihr Kravel Kohlebart an der...",kw={"beutebucht","goblingerüchte","kravel kohlebart","krazek","illusionenrennbahn","nazz steamboil","gerüchte für kravel","die schimmernde ebene","tausend nadeln"},sec={{t="Ein Brief von Krazek",b="Krazek setzte Gefälligkeiten, eine seltene Flasche Elfenwein und stundenlanges Schlussfolgern ein, um etwas über Nazz Steamboil zu erfahren. Sein Brief enthält sehr interessante Einzelheiten über den Goblinrennfahrer. Krazek hält den Brief für zu gefährlich, um ihn zu nutzen, und überlässt ihn Euch, sofern niemand erfährt, woher er stammt. Bringt ihn zu Kravel Kohlebart auf der Schimmernden Ebene."},{t="Kravels Urteil",b="Kravel Kohlebart findet den Brief sehr interessant. Er fragt sich, ob er sich beim nächsten Treffen vor dem Goblinpiloten verbeugen sollte. Er erwartet, dass Nazz Steamboil ein kleines Vermögen zahlt, damit das Geheimnis begraben bleibt."}},faq={{q="Wo beginnt das Ganze?",a="Krazek gibt Euch den Brief in Beutebucht, nachdem Ihr ihm den Traumstaub gebracht habt.",al={"wer vergibt gerüchte für kravel","gerüchte für kravel questgeber","wo gibt es die gerüchte"}},{q="Wem soll der Brief gebracht werden?",a="Bringt den Brief zu Kravel Kohlebart an der Illusionenrennbahn auf der Schimmernden Ebene in Tausend Nadeln.",al={"wo gerüchte für kravel abgeben","wer erhält die goblingerüchte","wo ist kravel kohlebart"}},{q="Um wen geht es in Krazeks Erkenntnissen?",a="Krazeks Erkenntnisse betreffen Nazz Steamboil, den Goblinrennfahrer. Sein Brief enthält sehr interessante Einzelheiten über Nazz.",al={"wer ist nazz steamboil","worum geht es in dem gerücht","über wen gibt es gerüchte"}},{q="Wie hat Krazek die Informationen aufgedeckt?",a="Krazek setzte Gefälligkeiten, stundenlanges Schlussfolgern und eine seltene Flasche Elfenwein ein, um die Informationen aufzudecken.",al={"wie kam krazek an die informationen","krazek gefälligkeiten"}},{q="Was kommt als Nächstes?",a="Als Nächstes kehrt Ihr nach Beutebucht zurück.",al={"nächste quest nach gerüchte für kravel","gerüchte für kravel folgequest"}}},fp="17,157,20.339.0,16.200.1,22.76.0,37.103.0,40.116.0,39.96.0,16.30.0"}
P.entries["quest:1118"] = {n="Zurück nach Beutebucht",s="An der Illusionenrennbahn schickt Euch Kravel Kohlebart mit einem Brief zurück nach Beutebucht und bittet Euch, seinen Plan geheim zu halten. Er ist riskant, doch bei Erfolg könntet Ihr beide einen hübschen Batzen verdienen. Dies folgt auf Rumors for Kravel.",h="An der Illusionenrennbahn schickt Euch Kravel Kohlebart mit einem Brief zurück nach Beutebucht und bittet...",kw={"beutebucht","crank fizzlebub","kravel kohlebart","kravels plan","illusionenrennbahn","salty sailor tavern","die schimmernde ebene","tausend nadeln"},sec={{t="Ein Brief für Beutebucht",b="An der Illusionenrennbahn vertraut Kravel Kohlebart darauf, dass Ihr einen Auftrag abschließt und Stillschweigen bewahrt. Sein neuer Plan ist riskant, doch bei Erfolg könntet Ihr beide einen hübschen Batzen verdienen. Er schickt Euch zurück nach Beutebucht, wohin Euch sein letzter Auftrag geführt hat, um Crank Fizzlebub zu finden und einen Brief zu überbringen. Falls Crank Hilfe braucht, gebt Euer Bestes. Kravel sagt, die Mühe werde sich lohnen."},{t="Crank liest den Plan",b="Crank Fizzlebub liest Kravels Brief und erfährt von dem Plan. Er bewundert Kravels finsteren Verstand. Der Plan erfordert etwas Mächtiges, das den Verstand verwirrt, und Crank fragt sich, ob Zanzils Mixtur für dessen Zombies dafür geeignet wäre."}},faq={{q="Wo beginnt und endet diese Reise?",a="Ihr beginnt bei Kravel Kohlebart an der Illusionenrennbahn in Tausend Nadeln. Dann bringt Ihr seinen Brief zu Crank Fizzlebub in der Salty Sailor Tavern in Beutebucht im Schlingendorntal.",al={"wohin gehen","wer vergibt zurück nach beutebucht","wo ist crank fizzlebub"}},{q="Was ging dem voraus?",a="Rumors for Kravel ging dem voraus und führte Euch nach Beutebucht.",al={"voraussetzungen","vorherige quest","welche quest kommt zuerst"}},{q="Was ist Kravels Plan?",a="Kravels Plan ist das Vorhaben in dem Brief, den Ihr zu Crank Fizzlebub bringt. Kravel nennt ihn riskant und sagt, Ihr könntet beide einen hübschen Batzen verdienen, wenn er aufgeht.",al={"was ist kravels plan","kravels plan brief"}},{q="Was solltet Ihr tun, wenn Crank Fizzlebub Hilfe braucht?",a="Kravel bittet Euch, Euer Bestes zu geben, um Crank Fizzlebub zu helfen, und sagt, die Mühe werde sich lohnen.",al={"crank helfen","braucht crank hilfe"}},{q="Was folgt darauf?",a="Die Reihe geht mit Zanzils Mixtur und einem Fool's Stout weiter.",al={"nächste quest","was folgt auf zurück nach beutebucht"}}},fp="17,208,22.334.0,22.219.1,38.180.0,22.61.0,24.147.0,49.92.0,22.61.0"}
P.entries["quest:1119"] = {n="Zanzils Mixtur und Fools Starkbier",s="An der Illusionenrennbahn erwartet Kravel Kohlebart ein mit Zanzils Mixtur versetztes Starkbier. Crank Fizzlebub nennt es Narrenbier und glaubt, dass Kravel es braucht, also bringt Ihr es ihm auf die Schimmernde Ebene, bevor es verdirbt.",h="An der Illusionenrennbahn erwartet Kravel Kohlebart ein mit Zanzils Mixtur versetztes Starkbier.",kw={"beutebucht","fizzlebub","kravel","mixtur","rennbahn","die schimmernde ebene","starkbier","zanzil"},sec={{t="Ein Trunk für Kravel",b="Crank Fizzlebub hat Zanzils Mixtur in Starkbier gemischt und daraus ein kräftiges Getränk gemacht, das er Narrenbier nennt. Er glaubt, dass Kravel es braucht, und möchte erfahren, wie es wirkt. Also bringt Ihr das Getränk zu Kravel Kohlebart an der Illusionenrennbahn auf der Schimmernden Ebene."},{t="Nicht lange stehen lassen",b="Crank warnt Euch davor, das Starkbier lange aufzubewahren. Die Mixtur bringt die Hefe auf Hochtouren, und das Getränk bleibt nicht ewig frisch."}},faq={{q="Wer schickt Euch mit dieser Lieferung los?",a="Crank Fizzlebub in Beutebucht gibt Euch Narrenbier zum Überbringen.",al={"wer startet zanzils mixtur und fools starkbier","questgeber"}},{q="Wer erhält das Narrenbier?",a="Kravel Kohlebart erhält das Narrenbier an der Illusionenrennbahn auf der Schimmernden Ebene in Tausend Nadeln.",al={"wer bekommt das starkbier","wo abgeben","kravels standort"}},{q="Warum muss das Getränk schnell geliefert werden?",a="Die Mixtur bringt die Hefe auf Hochtouren, sodass das Starkbier verdirbt, wenn es zu lange steht.",al={"verdirbt narrenbier","warum gibt es ein zeitlimit","gärungswirkung"}},{q="Was ging dem voraus?",a="Dem gehen Back to Beutebucht und Zanzil's Secret voraus.",al={"vorausgesetzte quests","vorheriger schritt"}},{q="Was folgt auf die Lieferung des Starkbiers?",a="Die Questreihe geht mit Narrenbier, Get the Gnomes Drunk und Get the Goblins Drunk weiter.",al={"nächste quest","was passiert danach"}}},fp="35,218,21.251.0,17.131.0,31.61.0,30.105.0,48.72.0,22.49.0,38.86.0"}
P.entries["quest:112"] = {n="Die Suche nach dem Tang",s="In Goldhain möchte Maybell Maclure Tommy Joe Steinfeld ungesehen besuchen. William Pestle braucht seltenen Kristalltang, um ihr einen Unsichtbarkeitsschnaps zu brauen.",h="In Goldhain möchte Maybell Maclure Tommy Joe Steinfeld ungesehen besuchen.",kw={"die suche nach dem tang","kristalltang","kristallsee","goldhain","unsichtbarkeitsschnaps","maybell maclure","murloc","tommy joe steinfeld","william pestle"},ang={["faction:Alliance"]="Für die Allianz hilft das Räumen der Murloc-Lager rund um den Kristallsee im Auftrag von Pestle, die aggressive Bedrohung nahe Goldhains östlicher Straße einzudämmen.",["profession:Herbalism"]="Für Euch als Sammler ist Kristalltang ein seltsamer Fund: ein Meereskraut aus den Beuteln von Süßwassermurlocs, weder aus der Erde noch vom Meeresgrund."},sec={{t="Ein Mittel für verbotene Liebe",b="Die Fehde zwischen den Familien Steinfeld und Maclure hindert Maybell Maclure und Tommy Joe Steinfeld daran, sich offen zu treffen. Maybell möchte ihren Geliebten sehen, ohne einen bewaffneten Zusammenstoß zwischen ihren Verwandten auszulösen. Also sucht sie einen Weg, das Tal ungesehen zu durchqueren. William Pestle, ein Kräuterkundiger und Apotheker im Gasthaus \"Zur Höhle des Löwen\" in Goldhain, will einen Unsichtbarkeitsschnaps brauen, doch dessen seltene Zutaten fehlen in den Schränken des Gasthauses."},{t="Die Plünderer des Kristallsees",b="William Pestle braucht Kristalltang als Katalysator für sein Gebräu. Seine Wedel wachsen gewöhnlich weit draußen in salzigen Meeren, doch Murloc-Stämme haben Vorräte landeinwärts in ihre primitiven Lager am Kristallsee gebracht, gleich östlich von Goldhain. Ihre eigenartigen Instinkte treiben sie dazu, die Meerespflanzen ans Süßwasserufer zu schleppen. Ihr müsst den Murlocs genügend Wedel abnehmen, bevor Ihr damit nach Goldhain zurückkehrt."}},faq={{q="Warum braucht William Pestle Kristalltang?",a="William Pestle braucht Kristalltang, um einen Unsichtbarkeitsschnaps für Maybell Maclure zu brauen. Das Getränk soll ihr helfen, den Weinberg ihrer Familie ungesehen zu verlassen und Tommy Joe Steinfeld zu besuchen.",al={"warum kristalltang","wozu dient tang","william pestle zutaten"}},{q="Warum findet man Meerestang am Süßwasser des Kristallsees?",a="Kristalltang wächst im Meer, doch Murloc-Stämme rund um den Kristallsee sammeln die Wedel und tragen sie landeinwärts. Sie horten den Tang in Lagern am Seeufer, der einzigen Quelle in der Umgebung von Goldhain.",al={"warum tang am kristallsee","tang im süßwasser","murloc tang hintergrund"}},{q="Wer sind Maybell Maclure und Tommy Joe Steinfeld?",a="Maybell Maclure und Tommy Joe Steinfeld sind junge Liebende aus verfeindeten Bauernfamilien im südlichen Wald von Elwynn. Ihre Familien verabscheuen einander, also setzt das Paar auf Heimlichkeit und alchemistische Tricks, um sich zu treffen.",al={"wer ist maybell","wer ist tommy joe","maclure steinfeld fehde"}},{q="Wo liegt der Kristallsee?",a="Der Kristallsee liegt gleich östlich von Goldhain im Herzen des Waldes von Elwynn. Feindselige Murlocs bevölkern seine Gewässer und Ufer.",al={"wo ist der kristallsee","kristallsee lage","kristallsee finden"}},{q="Was geschieht nach dem Sammeln des Tangs?",a="Nachdem Ihr vier Wedel Kristalltang abgeliefert habt, destilliert William Pestle daraus einen Unsichtbarkeitsschnaps. Dann bittet er Euch, ihn zu Maybell Maclure zu bringen, damit sie sich ungesehen davonschleichen kann.",al={"nächste quest nach dem tang","was stellt pestle her"}},{q="Wer ist William Pestle?",a="William Pestle ist Apotheker und Hobbyalchemist im Gasthaus \"Zur Höhle des Löwen\" in Goldhain. Er hilft den Einheimischen mit Hausmitteln, seltsamen Tränken und vertraulichen Gefälligkeiten.",al={"wer ist william pestle","pestle goldhain"}}},fx={ff0f7883={q="Warum möchte William Pestle Maybell und Tommy Joe helfen?",a="William Pestle ist der örtliche Apotheker und Alchemist von Goldhain, und er ist bereit, sein Handwerk einzusetzen, um den jungen Liebenden zu helfen. Maybell Maclure und Tommy Joe Steinfeld stecken auf entgegengesetzten Seiten der erbitterten, langjährigen Familienfehde fest. Ein geheimer Unsichtbarkeitsschnaps bietet Maybell eine kluge Möglichkeit, sich den wachsamen Augen ihrer Familie in den Weinbergen der Maclures zu entziehen, ohne weiteren Streit zwischen den Clans zu provozieren.",al={"warum maybell helfen","beweggrund von william pestle","warum kümmert sich william"}},cc419076={q="Warum sammeln sich Murlocs am Kristallsee?",a="Murlocs sind von den Küsten landeinwärts gekrochen und haben Lager entlang der Süßwassergewässer des Waldes von Elwynn wie dem Kristallsee und dem Stonecairn Lake errichtet. Da die Streitkräfte von Sturmwind damit beschäftigt sind, die Grenzen an anderer Stelle zu verteidigen, sind diese aggressiven Amphibien kühn geworden; sie dringen in örtliche Siedlungen ein und sammeln Materialien – darunter Seetang, den sie landeinwärts mit sich führen.",al={"warum sind murlocs am kristallsee","murlocs im kristallsee","murlocs im wald von elwynn"}}},fp="15,148,27.431.0,30.406.0,42.183.0,53.191.0,49.206.0,30.112.0,39.178.0,22.170.0"}
P.entries["quest:1120"] = {n="Die Gnome betrunken machen",s="Auf der Illusionenrennbahn beginnt Die Gnome betrunken machen mit einem Test von Fool's Stout an einer Boxencrew. Kravel Kohlebart gibt Euch das Starkbier für den Gnomen-Boxenboss in der Nähe und warnt, dass es irgendwann schlecht wird.",h="Auf der Illusionenrennbahn beginnt Die Gnome betrunken machen mit einem Test von Fool's Stout an einer...",kw={"fool's stout","gnomen-boxenboss","kravel kohlebart","illusionenrennbahn","tausend nadeln","zanzil"},sec={{t="Ein Test an den Boxencrews",b="Kravel Kohlebart bittet Euch, Fool's Stout an einer der Boxencrews zu testen. Wählt Ihr die Gnome, gibt er Euch das Starkbier für den Gnomen-Boxenboss in der Nähe auf der Illusionenrennbahn. Diese Wahl verschafft den Goblins einen Vorteil bei den Rennen. Kravel warnt Euch, nicht zu lange zu warten, da das Starkbier irgendwann schlecht wird."},{t="Ein Schluck vor dem Rennen",b="Der Gnomen-Boxenboss freut sich über Euer Geschenk und nennt es aufmerksam. Ein Rennen steht bevor, daher ist es vielleicht nicht klug, jetzt zu trinken. Dennoch kann die Crew wohl ein wenig vertragen. So stark kann das Starkbier nicht sein."}},faq={{q="Wer bittet Euch, das Starkbier zu überbringen?",a="Kravel Kohlebart, der Zwerg auf der Illusionenrennbahn in Tausend Nadeln, gibt Euch das Starkbier zum Überbringen.",al={"wer vergibt die gnome betrunken machen","questgeber die gnome betrunken machen","kravel kohlebart quest"}},{q="Wem soll Fool's Stout überbracht werden?",a="Bringt Fool's Stout zum Gnomen-Boxenboss in der Nähe auf der Illusionenrennbahn.",al={"wohin mit dem starkbier","wer bekommt fool's stout","gnomen-boxenboss standort"}},{q="Was geschieht, wenn Ihr zu lange braucht, um das Starkbier zu überbringen?",a="Das Starkbier wird irgendwann schlecht, daher sagt Kravel Euch, nicht zu lange zu warten.",al={"verdirbt fool's stout","starkbier zeitlimit","fool's stout wird schlecht"}},{q="Könnt Ihr stattdessen die Goblins als Ziel wählen?",a="Ja. Kravel lässt Euch wählen, an welcher Boxencrew Ihr das Starkbier testen wollt. Die andere Wahl ist Get the Goblins Drunk.",al={"get the goblins drunk auswahl","stattdessen goblins betrunken machen möglich","gnome oder goblins rennbahn"}},{q="Was kommt davor?",a="Die Quest folgt auf Zanzils Mixtur und ein Fool's Stout.",al={"vorherige quest","voraussetzung für die gnome betrunken machen"}},{q="Was kommt nach der Übergabe des Starkbiers?",a="Nachdem Ihr das Starkbier überbracht habt, geht die Questreihe mit Report Back to Fizzlebub weiter.",al={"nächste quest","was kommt nach die gnome betrunken machen"}}},fp="20,202,23.296.0,30.192.1,34.102.0,45.74.0,55.75.0,45.107.0,23.47.0,40.79.0"}
P.entries["quest:1121"] = {n="Die Goblins betrunken machen",s="Auf der Illusionenrennbahn bittet Euch Kravel Kohlebart, Fool's Stout an einer Boxencrew zu testen. Wählt die Goblins und bringt das Stout zum nahen Goblin-Boxenboss, bevor es schlecht wird.",h="Auf der Illusionenrennbahn bittet Euch Kravel Kohlebart, Fool's Stout an einer Boxencrew zu testen.",kw={"fool's stout","gnom","goblin","goblin-boxenboss","kravel kohlebart","illusionenrennbahn","tausend nadeln"},sec={{t="Ein Test an den Boxencrews",b="Kravel Kohlebart gibt Euch Fool's Stout, um es an einer der Boxencrews zu testen. Wenn Ihr die Goblins wählt, bringt es zum nahen Goblin-Boxenboss auf der Illusionenrennbahn. Diese Wahl verschafft den Gnomen einen Vorteil bei den Rennen. Das Stout wird irgendwann schlecht, daher warnt Kravel Euch davor, zu trödeln."},{t="Ein Schlückchen schadet nicht",b="Der Goblin-Boxenboss sieht den Alkohol, den Ihr ihm anbietet, und willigt ein, ein wenig zu trinken."}},faq={{q="Wer bietet das an?",a="Kravel Kohlebart, ein Zwerg auf der Illusionenrennbahn in Tausend Nadeln, bietet Euch das Stout an.",al={"questgeber","wer vergibt die goblins betrunken machen","kravel kohlebart"}},{q="Wohin muss das Stout gebracht werden?",a="Bringt das Stout zum Goblin-Boxenboss, der sich ganz in der Nähe auf der Illusionenrennbahn befindet.",al={"wohin das stout bringen","goblin-boxenboss standort"}},{q="Was passiert, wenn Ihr zu lange wartet?",a="Das Stout wird irgendwann schlecht, daher warnt Kravel Euch davor, zu lange zu warten.",al={"verdirbt das stout","fool's stout haltbarkeit","stout wird schlecht"}},{q="Welche Alternative gibt es dazu?",a="Kravel lässt Euch wählen, an welcher Boxencrew Ihr das Stout testen wollt. Die Alternative ist Get the Gnomes Drunk mit der Gnomencrew.",al={"get the gnomes drunk auswahl","gnome oder goblins ill usionenrennbahn"}},{q="Was kommt davor?",a="Davor kommt Zanzils Mixtur und ein Fool's Stout.",al={"vorherige quest","voraussetzung für die goblins betrunken machen"}},{q="Was folgt nach der Ablieferung des Stouts?",a="Die Questreihe geht mit Report Back to Fizzlebub weiter.",al={"nächste quest","was folgt auf die goblins betrunken machen"}}},fp="21,173,23.275.0,19.73.1,16.90.0,30.75.0,34.75.0,32.121.0,23.47.0,40.50.0"}
P.entries["quest:1122"] = {n="Meldet Euch bei Fizzlebub",s="Kravel Kohlebart berichtet, dass das Fool's Stout gewirkt hat, und schickt Euch mit Neuigkeiten für Crank Fizzlebub nach Beutebucht. Er hat auf das nächste Rennen gewettet und hofft, dass die Boxencrew, die Ihr betrunken gemacht habt, ihren eigenen Wagen geschrottet hat. Dies folgt auf Eure Entscheidung, eine der Boxencrews betrunken zu machen.",h="Kravel Kohlebart berichtet, dass das Fool's Stout gewirkt hat, und schickt Euch mit Neuigkeiten für Crank...",kw={"beutebucht","crank fizzlebub","fool's stout","kravel kohlebart","illusionenrennbahn","die schimmernde ebene","tausend nadeln"},sec={{t="Eine Notiz für Crank",b="Kravel Kohlebart sagt, das Fool's Stout habe gut gewirkt. Er hat auf das nächste Rennen gewettet und hofft, dass die Boxencrew, die Ihr betrunken gemacht habt, ihren eigenen Wagen geschrottet hat. Bringt seine Notiz über den erfolgreichen Test zu Crank Fizzlebub in Beutebucht. Crank wird die Neuigkeiten hören wollen, und Kravel hofft, für künftige Rennen mehr von dem Stout zu bekommen."},{t="Cranks Antwort",b="Crank Fizzlebub liest Kravels Notiz und nennt den Test einen Erfolg. Crank freut sich darüber und sagt, Ihr sollt einfach fragen, wann immer Ihr mehr Stout wollt. Dann seid Ihr bereit, mehr von Zanzils Mixtur zu sammeln."}},faq={{q="Wer beginnt diese Aufgabe?",a="Kravel Kohlebart, der Zwerg an der Illusionenrennbahn auf der Schimmernden Ebene in Tausend Nadeln, gibt Euch die Notiz.",al={"questgeber","wer vergibt meldet euch bei fizzlebub"}},{q="Wo befindet sich Crank Fizzlebub?",a="Crank Fizzlebub ist in Beutebucht.",al={"fizzlebub standort","wo ist crank fizzlebub","abgabeort"}},{q="Was kommt davor?",a="Zuvor habt Ihr Get the Gnomes Drunk abgeschlossen oder, falls Ihr die andere Crew gewählt habt, Get the Goblins Drunk.",al={"voraussetzungen","vorherige quest"}},{q="Was soll Fizzlebub von Kravel Kohlebart erfahren?",a="Kravel Kohlebart möchte Fizzlebub wissen lassen, dass der Test erfolgreich war.",al={"was wird berichtet","inhalt des berichts"}}},fp="24,253,16.290.0,14.186.1,16.114.0,33.32.0,23.103.0,50.60.0"}
P.entries["quest:1127"] = {n="Fools Starkbier",s="In Beutebucht suchen Reisende nach mehr Fools Starkbier für die Rennbahn in der Schimmernden Ebene. Crank Fizzlebub braucht zwölf Fläschchen Zanzils Mixtur, um eine weitere Portion zu brauen.",h="In Beutebucht suchen Reisende nach mehr Fools Starkbier für die Rennbahn in der Schimmernden Ebene.",kw={"beutebucht","crank fizzlebub","fools starkbier","rennbahn","schlingendorntal","zanzils mixtur"},sec={{t="Eine zweite Portion",b="Reisende auf dem Weg zu den Gnomen an der Rennbahn stellen womöglich fest, dass ihr Fools Starkbier vor der Ankunft abgelaufen ist. In Beutebucht kann Crank Fizzlebub Ersatz brauen. Der Goblin braucht zwölf Fläschchen Zanzils Mixtur und bietet eine Entlohnung für deren Beschaffung, mit einem kleinen Extra für Diskretion."}},faq={{q="Wer bietet an, Fools Starkbier zu brauen?",a="In Beutebucht im südlichen Schlingendorntal bietet Crank Fizzlebub an, Fools Starkbier zu brauen.",al={"wer gibt fools starkbier","fools starkbier questgeber","crank fizzlebub"}},{q="Welche Zutaten braucht Crank Fizzlebub?",a="Crank Fizzlebub braucht zwölf Fläschchen Zanzils Mixtur, um eine weitere Portion Fools Starkbier zu brauen.",al={"welche gegenstände für fools starkbier","fools starkbier zutaten","benötigte menge zanzils mixtur"}},{q="Warum braucht jemand eine weitere Portion Fools Starkbier?",a="Fools Starkbier verdunstet nach zwei Stunden, weshalb Reisende, die diese Frist verpassen, frische Zutaten für Ersatz brauchen.",al={"warum fools starkbier erneut","fools starkbier abgelaufen","fools starkbier haltbarkeit"}},{q="Wohin soll das Gebräu gelangen?",a="Das Gebräu ist für die Gnome an der Rennbahn bestimmt.",al={"wohin geht fools starkbier","wer trinkt fools starkbier","fools starkbier ziel"}}},fp="12,159,14.290.0,32.89.0,43.94.0,53.116.0,33.48.0"}
P.entries["quest:113"] = {n="Insektenteil-Analyse",s="Aus Tanaris schickt Alchimist Pestlezugg eine dringende Warnung nach Gadgetzan. Die Gefahr bedroht beide Orte und könnte sich über das südliche Kalimdor ausbreiten.",h="Aus Tanaris schickt Alchimist Pestlezugg eine dringende Warnung nach Gadgetzan.",kw={"rutenwünschels","gadgetzan","gadgetzan water company","insektenanalyse","pestlezugg","bericht","tanaris"},sec={{t="Eine ernste Warnung",b="Alchimist Pestlezugg bittet Euch, den Bericht zum Leitenden Feldmesser Rutenwünschels in Gadgetzan zu bringen. Die Gefahr bedroht Tanaris und Gadgetzan und könnte sich über das südliche Kalimdor ausbreiten. Sie könnte ganz Azeroth erreichen, und nichts deutet darauf hin, dass sie nachlassen wird. Pestlezugg will, dass jeder, der lesen kann, davon erfährt.\n\nRutenwünschels soll Euch ein Duplikat anfertigen, damit Ihr es frei mit Euren Verbündeten teilen könnt."},{t="Eine Frage des Goldes",b="Leitender Feldmesser Rutenwünschels dankt Euch dafür, dass Ihr den Bericht gebracht habt, und für Eure harte Arbeit für die Gadgetzan Water Company. Das Unternehmen besitzt wertvolle Informationen, und Rutenwünschels würde normalerweise erwarten, dass die Leute gut dafür bezahlen.\n\nDoch Rutenwünschels kennt Alchimist Pestlezugg schon lange. Pestlezugg empfiehlt, den Bericht mit allen zu teilen, also stimmt Rutenwünschels zu und fertigt Euch eine Kopie an."}},faq={{q="Wer schickt den Bericht und wer erhält ihn?",a="Alchimist Pestlezugg gibt Euch den Bericht, damit Ihr ihn zum Leitenden Feldmesser Rutenwünschels in Gadgetzan bringt.",al={"wer vergibt insektenteil-analyse","bei wem insektenteil-analyse abgeben","wo den bericht abliefern"}},{q="Warum ist Alchimist Pestlezugg so beunruhigt?",a="Pestlezugg warnt, dass die Bedrohung Tanaris und Gadgetzan betrifft und dann das gesamte südliche Kalimdor und vielleicht ganz Azeroth erreichen könnte. Nichts deutet darauf hin, dass sie nachlassen wird.",al={"pestlezuggs warnung","was steht im insektenbericht","warum ist die insektenbedrohung ernst"}},{q="Warum braucht Ihr eine Kopie des Berichts?",a="Pestlezugg will, dass alle von der Bedrohung erfahren. Rutenwünschels soll Euch ein Duplikat anfertigen, das Ihr frei mit Euren Verbündeten teilen könnt.",al={"warum den bericht kopieren","rutenwünschels berichtskopie","warum den bericht teilen"}},{q="Was kommt unmittelbar vor dieser Lieferung?",a="Diese Lieferung folgt auf einen früheren Schritt mit demselben Namen.",al={"vorherige quest","welche quest kommt davor"}}},fp="20,146,15.392.0,16.395.1,41.95.0,39.163.0,37.133.0,41.57.0"}
P.entries["quest:1130"] = {n="Melor schickt Kunde",s="Im Brachland überbringt Jorn Himmelsdeuter vielversprechenden Jägern Melor Steinhufs Ruf. Jäger, die ihre Zähigkeit in ganz Kalimdor bewiesen haben, werden für eine härtere Prüfung zur Hunter's Rise in Donnerfels gerufen.",h="Im Brachland überbringt Jorn Himmelsdeuter vielversprechenden Jägern Melor Steinhufs Ruf.",kw={"brachland","camp taurajo","hunter's rise","jorn himmelsdeuter","melor schickt kunde","melor steinhuf","steelsnap","donnerfels"},ang={["class:Hunter"]="Als Jäger erkennt Ihr in Melor Steinhuf die Kunst der Tauren im Umgang mit Bestien. Er verlangt Präzision, Geduld und Respekt vor gefährlicher Beute.",["faction:Horde"]="Als Mitglied der Horde wisst Ihr, dass Camp Taurajo und Donnerfels auf geschickte Kundschafter angewiesen sind, um gefährliche Raubtiere nahe Versorgungswegen und Außenposten einzudämmen.",["race:Tauren"]="Als Tauren folgt Ihr mit Melors Ruf einem traditionellen Ritus, der Euch als Erwachsene anerkennt und Euer Ansehen festigt. Ihr beweist Eure Meisterschaft in der Jagd und bringt der Hunter's Rise Ehre."},sec={{t="Ein Ruf nach Donnerfels",b="Jorn Himmelsdeuter wacht über die Kreuzungen und Lager des Brachlands. Er überbringt Jägern und Kriegern, die sich in den umliegenden Landen hervorgetan haben, Kunde von den Ältesten der Hunter's Rise. Melor Steinhuf, ein verehrter Mentor der Tauren, hat einen Weg für sie vorgesehen."},{t="Der Weg zur Jagd",b="Auf der Hunter's Rise in Donnerfels begegnet Ihr Melor Steinhuf. Der alte Jäger fragt, ob Ihr die Entschlossenheit besitzt, Euch in eine ferne und gefährliche Wildnis zu wagen. Sein Ruf führt zu Prüfungen weit jenseits der sicheren Gefilde von Mulgore, wo Jäger den wildesten Raubtieren des Kontinents gegenübertreten."}},faq={{q="Wer ist Melor Steinhuf?",a="Melor Steinhuf ist ein erfahrener Jäger der Tauren auf der Hunter's Rise in Donnerfels. Er beurteilt aufstrebende Fährtenleser und Krieger der Horde und entsendet würdige Anwärter quer durch Kalimdor, um berüchtigte Bestien aufzuspüren und zu jagen.",al={"melor","wer ist melor","melor steinhuf hintergrundgeschichte"}},{q="Wer überbringt diesen Ruf?",a="Jorn Himmelsdeuter, ein Bestienmeister der Tauren in Camp Taurajo im Brachland, überbringt die Nachricht. Er wacht über Reisende und schickt jene, die Mut bewiesen haben, nach Donnerfels, um mit Melor zu sprechen.",al={"wer vergibt die quest","jorn himmelsdeuter","wer hat nach mir geschickt"}},{q="Wo finde ich Melor Steinhuf?",a="Melor befindet sich auf der Hunter's Rise, dem südlichen Tafelberg von Donnerfels, der den Jägern, Fährtenlesern und Bestienmeistern der Tauren gewidmet ist.",al={"melors standort","wo ist melor","jäger donnerfels"}},{q="Welchen Weg hat Melor für mich vorgesehen?",a="Melor prüft Eure Ausdauer und Euren Jagdinstinkt mit schwierigen Fährtensuchexpeditionen. Die erste führt Euch durch Tausend Nadeln, um Steelsnap zu jagen, einen grausamen Hyänentyrannen.",al={"was will melor","nächste quest nach melor schickt kunde","melors questreihe"}},{q="Warum wirbt Melor Abenteurer aus dem Brachland an?",a="Wer die gefährlichen Raubtiere, Stacheleber und Zentauren des Brachlands überlebt, beweist den nötigen Instinkt für anspruchsvollste Jagden. Melor sucht jene, die schwer fassbare, tödliche Beute in fremden Landen aufspüren können.",al={"warum ich","warum interessiert sich melor"}},{q="Ist diese Prüfung Jägern vorbehalten?",a="Melors Prüfung steht jedem Abenteurer der Horde offen, der in der Wildnis Stärke und Einfallsreichtum bewiesen hat. Sie beginnt auf der Hunter's Rise und prüft die Tugenden eines Jägers beim Fährtenlesen.",al={"ist das eine jägerquest","können andere klassen das machen"}}},fx={["2189d60f"]={q="Warum schickt Jorn Himmelsdeuter Euch zu Melor Steinhuf?",a="Jorn Himmelsdeuter fungiert als Bote und Mentor im Brachland und hält Ausschau nach fähigen Abenteurern, die ihre Stärke unter Beweis stellen. Nachdem er Eure Taten auf den Ebenen beobachtet hat, erkennt er, dass Ihr den örtlichen Aufgaben entwachsen seid, und verweist Euch an die Anhöhe der Jäger in Donnerfels, wo Melor Steinhuf würdige Jäger auf weitaus größere Prüfungen in ganz Kalimdor vorbereitet.",al={"warum schickt jorn die botschaft","warum soll ich zu melor gehen laut jorn","beweggrund von jorn himmelsdeuter"}},e1bd22c0={q="Warum wählt Jorn Himmelsdeuter ausgerechnet Euch aus?",a="Die Kunde von Euren Leistungen im Brachland hat die Ältesten erreicht. Melor Steinhuf ruft keine gewöhnlichen Späher oder Stadtwachen zusammen; er sucht nach erprobten Wanderern, die das Geschick und die Ausdauer bewiesen haben, die nötig sind, um die wildesten Bestien in fernen Ländern aufzuspüren. Jorn wählt Euch aus, weil Euer Ruf beweist, dass Ihr für Melors Pfad bereit seid.",al={"warum melor sendet wort an mich","warum wählt mich jorn himmelsdeuter","warum ruft mich melor"}}},fp="16,200,26.262.0,20.265.0,23.211.0,26.190.0,33.116.0,35.172.0,52.181.0,36.160.0"}
P.entries["quest:1131"] = {n="Stahlbiss",s="In Tausend Nadeln schickt Euch Melor Steinhuf auf die Jagd nach Steelsnap und seinem Rudel, die die Tierwelt terrorisieren. Diese Jagd dient einem anderen Zweck als den üblichen Gründen, aus denen Tauren ein Leben nehmen.",h="In Tausend Nadeln schickt Euch Melor Steinhuf auf die Jagd nach Steelsnap und seinem Rudel, die die Tierwelt...",kw={"camp e'thok","erdenmutter","die anhöhe der jäger","hyäne","melor steinhuf","steelsnap","tausend nadeln","donnerfels"},ang={["class:Hunter"]="Die Jagd auf Steelsnap prüft Euer Geschick darin, einen wilden Rudelführer unter den Hyänen aufzuspüren, die den Schluchtboden durchstreifen.",["faction:Horde"]="Einen sichereren Weg durch Tausend Nadeln zu bahnen, schützt Versorgungslinien und Reisende, die vom Brachland zur Schimmernden Ebene ziehen.",["race:Tauren"]="Für die Shu'halo hat das Töten eines Tieres spirituelles Gewicht. Die Jagd auf Steelsnap lehrt Euch, ein Wesen zu erlegen, dessen Grausamkeit außerhalb der Gnade der Erdenmutter liegt."},sec={{t="Eine Jagd ohne Segen",b="Taurenjäger nehmen Leben, um Nahrung, Ehre oder Weisheit von der Erdenmutter zu erlangen. Melor Steinhuf schickt Euch aus einem anderen Grund auf die Jagd nach Steelsnap. Die Hyäne bedroht das Gleichgewicht der Natur durch sinnlose Gewalt und Furcht, statt den Kreislauf des Lebens zu bewahren."},{t="Die Geißel der Nadeln",b="Steelsnap durchstreift die Schluchten im Norden von Tausend Nadeln, südlich der Zentaurenenklave bei Camp E'thok. Grimmige Hyänen folgen ihm, und gemeinsam greifen sie die friedlicheren Wildtiere auf dem Schluchtboden an. Erlegt Steelsnap und bringt seine Rippe zurück, um seine Herrschaft über die Nadeln zu beenden."}},faq={{q="Warum will Melor Steinhuf Steelsnap töten lassen?",a="Melor Steinhuf will Steelsnap töten lassen, weil er das Gleichgewicht der Natur durch sinnlose Gewalt bedroht. Tauren jagen gewöhnlich, um Nahrung, Ehre oder Weisheit von der Erdenmutter zu erlangen; diese Jagd soll seine Angriffe auf die Tierwelt beenden.",al={"warum steelsnap töten","melor steinhuf grund","steelsnap motiv"}},{q="Wo ist Steelsnap zu finden?",a="Steelsnap durchstreift den Norden von Tausend Nadeln, südlich der Zentaurenenklave Camp E'thok.",al={"steelsnap aufenthaltsort","wo ist steelsnap","steelsnap finden"}},{q="Welcher Beweis muss nach Donnerfels zurückgebracht werden?",a="Bringt Stahlbiss' Rippe zu Melor Steinhuf auf der Anhöhe der Jäger in Donnerfels.",al={"steelsnap trophäe","steelsnap ziel","was erbeuten"}},{q="Kämpft Steelsnap allein?",a="Nein. Andere Hyänen folgen Steelsnap und kämpfen an seiner Seite.",al={"ist steelsnap allein","steelsnap rudel","steelsnap begleiter"}},{q="Wie unterscheidet sich diese Jagd von traditionellen Jagden der Tauren?",a="Tauren jagen gewöhnlich, um Nahrung, Ehre oder Weisheit von der Erdenmutter zu erlangen. Diese Jagd soll ein Raubtier aufhalten, das das Gleichgewicht der Natur stört.",al={"jagdphilosophie der tauren","erdenmutter jagd","lehre der jagd"}},{q="Wo lebt Melor Steinhuf?",a="Melor Steinhuf lebt auf der Anhöhe der Jäger in Donnerfels, wo er Jäger unterweist und erfahrene Fährtenleser auf die Probe stellt.",al={"melor steinhuf aufenthaltsort","wo ist melor","melor koordinaten"}}},fx={["1c130f9f"]={q="Was für eine Bestie ist Steelsnap?",a="Steelsnap ist eine bösartige, tyrannische Hyäne, die den Talboden von Tausend Nadeln durchstreift. Im Gegensatz zu gewöhnlichen Wildtieren führt er ein Rudel von Aasfressern bei sinnlosem Blutvergießen an, terrorisiert sanftere Kreaturen und stört das natürliche Gleichgewicht. Melor Steinhuf hält ihn für eine niederträchtige Kreatur, die vollständig außerhalb des Segens der Erdenmutter steht.",al={"wer ist steelsnap","was ist steelsnap","steelsnap die hyäne"}}},fp="9,186,27.247.0,26.267.0,47.223.0,29.85.0,49.73.0,27.56.0,56.139.0,33.110.0"}
P.entries["quest:1132"] = {n="Fiora Langohr",s="Vom Hafen von Menethil segelt Ihr westwärts über das große Meer, um Fiora Langohr in Theramore zu treffen. Jack 'Blutgeld' Flint schickt Euch zu seiner hochelfischen Kontaktperson im Gasthaus der Stadt.",h="Vom Hafen von Menethil segelt Ihr westwärts über das große Meer, um Fiora Langohr in Theramore zu treffen.",kw={"theramore","boot","düstermarschen","fiora langohr","kalimdor","hafen von menethil","jack 'blutgeld' flint","sumpfland"},ang={["faction:Alliance"]="Für die Allianz verbindet diese Reise die Östlichen Königreiche mit den nachtelfischen Gebieten Kalimdors und vereint die östlichen und westlichen Grenzlande.",["race:NightElf"]="Als Nachtelf erlebt Ihr, wie Fiora Langohr in Theramore östliche Verbündete willkommen heißt und sie auf die uralte Wildnis im Norden Kalimdors vorbereitet."},sec={{t="Ein Ruf nach Westen",b="Viele Menschen, Zwerge und Gnome blicken auf die Östlichen Königreiche und sehen alte Konflikte und verwüstetes Land. Im Hafen von Menethil drängt der Seemann Jack 'Blutgeld' Flint Reisende, ein Schiff über das große Meer zu besteigen. Er beschreibt Kalimdor als ein unerforschtes Land voller Reichtümer und Möglichkeiten. Dann schickt er Euch nach Theramore, um seine Gefährtin, die Elfe Fiora Langohr, zu treffen."},{t="Ankunft in Theramore",b="Eure Seereise endet in Theramore, einem Hafen der Allianz an der Küste der Düstermarschen. Fiora Langohr wartet im Gasthaus der Stadt auf Reisende, die Flint geschickt hat. Sie vertraut seiner Menschenkenntnis und heißt die gerade eingetroffenen Helden der Allianz willkommen. Von dort aus bereitet sie sich darauf vor, Euch landeinwärts zu den uralten Wäldern des Eschentals zu führen."}},faq={{q="Wer ist Fiora Langohr?",a="Fiora Langohr ist eine Hochelfe, die im Gasthaus von Theramore in den Düstermarschen wartet. Als Kontaktperson von Jack 'Blutgeld' Flint begrüßt sie Reisende der Allianz, die aus den Östlichen Königreichen eintreffen.",al={"fiora langohr","wer ist fiora"}},{q="Wer vergibt diese Quest?",a="Jack 'Blutgeld' Flint, ein tatkräftiger menschlicher Seemann, bietet die Reise nach Westen vom Hafen von Menethil an der Küste des Sumpflands an.",al={"questgeber","wo gibt es die quest von fiora langohr","wer vergibt die quest"}},{q="Wie erreiche ich Fiora Langohr vom Hafen von Menethil aus?",a="Besteigt das Passagierschiff im Hafen von Menethil und segelt westwärts über das große Meer nach Theramore in den Düstermarschen.",al={"wie nach theramore gelangen","schiff nach theramore","boot von menethil"}},{q="Was geschieht nach dem Treffen mit Fiora Langohr?",a="Fiora heißt Euch in Theramore willkommen und lobt Flints Empfehlung. Für den nächsten Teil Eurer Reise schickt sie Euch landeinwärts nach Astranaar im Eschental.",al={"what comes next","folgequest","quest journey to astranaar"}},{q="In welcher Beziehung stehen Jack 'Blutgeld' Flint und Fiora Langohr zueinander?",a="Flint nennt Fiora seine Partnerin jenseits des Meeres. Er sucht in den Östlichen Königreichen nach eifrigen Abenteurern, während Fiora sie in Kalimdor empfängt und bei Unternehmungen der Allianz und Reisen ins Landesinnere hilft.",al={"sind flint und fiora partner","verbindung zwischen jack 'blutgeld' flint und fiora"}},{q="Warum wirbt die Allianz Reisende für Kalimdor an?",a="Kalimdor bietet der Allianz riesige neue Gebiete und Ressourcen. Die nachtelfischen Verbündeten dort brauchen Hilfe, um ihre angestammten Lande gegen Bedrohungen wie die Horde und verbliebene Dämonen zu verteidigen.",al={"warum nach kalimdor reisen","warum theramore"}}},fx={["869cd7aa"]={q="Warum möchte Jack 'Blutgeld' Flint Euch nach Kalimdor schicken?",a="Jack 'Blutgeld' Flint sieht sich selbst als Vermittler, der damit beauftragt ist, vielversprechende Abenteurer im Hafen von Menethil dazu zu inspirieren, das große Meer zu überqueren. Da er selbst an die Docks gebunden ist und sich nach Seereisen sehnt, besteht seine Rolle darin, hartgesottene Seelen auszumachen und sie an seine Hochelfen-Partnerin Fiora Longears zu verweisen, die Neuankömmlingen dabei hilft, Fuß zu fassen und die aufkeimenden Bemühungen der Allianz in ganz Kalimdor zu unterstützen.",al={"beweggrund von jack 'blutgeld' flint","warum zu fiora schicken","warum will jack flint das erledigt haben"}}},fp="14,159,18.349.0,20.321.0,22.174.0,22.117.0,51.112.0,42.149.0,67.190.0,53.182.0"}
P.entries["quest:1133"] = {n="Reise nach Astranaar",s="Von Theramore schickt Fiora Longears Reisende der Allianz nordwärts nach Astranaar. Dort melden sie sich bei Shindrell Feuerflink, während Krieg und Unruhen Eschental zusetzen.",h="Von Theramore schickt Fiora Longears Reisende der Allianz nordwärts nach Astranaar.",kw={"eschental","astranaar","theramore","düstermarschen","fiora longears","reise nach astranaar","hafen von menethil","shindrell feuerflink"},ang={["faction:Alliance"]="Als Rekrut der Allianz reist Ihr von den vergleichsweise sicheren Häfen der Düstermarschen in die umkämpfte Wildnis von Eschental.",["race:Human"]="Als Mensch, der vom Hafen von Menethil anreist, macht Ihr Eure ersten Schritte ins Landesinnere von Kalimdor und erfüllt das Versprechen der Allianz, den Nachtelfen beizustehen.",["race:NightElf"]="Als Nachtelf kehrt Ihr in Eure belagerte Heimat zurück und verteidigt die heiligen Baumkronen von Eschental an der Seite fremder Verbündeter."},sec={{t="Von der Küste in die Wälder",b="Reisende der Allianz erreichen die Düstermarschen mit der Fähre vom Hafen von Menethil und suchen oft nach einer Aufgabe im nördlichen Kalimdor. In Theramore schickt Fiora Longears fähige Helfer ins Landesinnere nach Astranaar, der wichtigsten Siedlung der Nachtelfen in Eschental. Die Straße verläuft unter uralten, schattigen Baumkronen und führt in einen von Krieg und Unruhen geplagten Wald."},{t="Eine unausgesprochene Empfehlung",b="Fiora bittet Reisende, ihren Namen in Astranaar nicht zu erwähnen, weil Shindrell Feuerflink sie nicht kennt. Fiora schickt neue Talente der Allianz dorthin, wo Hilfe gebraucht wird, und Shindrell heißt wehrhafte Verteidiger bei ihrer Ankunft willkommen. Eschental bleibt atemberaubend, doch es ist nicht mehr der friedliche Zufluchtsort, der es einst war."}},faq={{q="Wo beginnt die Quest „Reise nach Astranaar“?",a="Fiora Longears schickt Reisende der Allianz von Theramore an der Küste der Düstermarschen aus auf den Weg. Sie heißt jene willkommen, die aus den Östlichen Königreichen anreisen und in Kalimdor helfen wollen.",al={"wer vergibt reise nach astranaar","reise nach astranaar start","wo reise nach astranaar annehmen"}},{q="Mit wem muss ich in Astranaar sprechen?",a="Sprecht mit Shindrell Feuerflink, einer Nachtelfin in Astranaar, der zentralen Stadt der Allianz in Eschental.",al={"wo reise nach astranaar abgeben","reise nach astranaar abgabe-npc","wer ist shindrell feuerflink"}},{q="Warum soll Fioras Name nicht erwähnt werden?",a="Fiora bittet Euch, sie nicht zu erwähnen, weil Shindrell sie nicht persönlich kennt. Sie schickt eifrige Neuankömmlinge zu einem Außenposten, der Hilfe braucht.",al={"warum fiora nicht erwähnen","fiora longears verbindung zu shindrell"}},{q="Welchen Zweck hat diese Quest?",a="Die Reise führt Reisende der Allianz aus den Düstermarschen nach Eschental und bringt sie nach Astranaar, ihrem wichtigsten Stützpunkt im Wald.",al={"warum reise nach astranaar machen","reise nach astranaar hintergrund und zweck"}},{q="Welche Schwierigkeiten gibt es in Eschental?",a="In Eschental herrscht keine Ruhe mehr. Vorstöße der Horde, vom Dritten Krieg hinterlassene dämonische Verderbnis und durch jüngste Konflikte aufgescheuchte Wildtiere setzen dem Wald zu.",al={"warum braucht astranaar hilfe","eschental schwierigkeiten hintergrund"}},{q="Welche Quest führt zu „Reise nach Astranaar“?",a="Eine kurze Einführungsquest namens „Fiora Longears“ schickt Reisende, die in den Düstermarschen ankommen, zu ihr nach Theramore, um mit ihr zu sprechen.",al={"reise nach astranaar voraussetzung","fiora longears questreihe"}}},fx={["5f2da217"]={q="Warum schickt Fiora Longears Euch nach Astranaar?",a="Fiora sieht, wie neue Reisende der Allianz in Theramore eintreffen, und schickt fähige Abenteurer dorthin, wo sie am dringendsten gebraucht werden. Astranaar ist die zentrale Nachtelfensiedlung im Eschental, einer Region, die derzeit von eskalierenden Gefahren und feindlichen Übergriffen geplagt wird. Sie verweist Euch an Shindrell Feuerflink, damit Eure Fähigkeiten sofort die angespannte Verteidigung des uralten Waldes durch die Allianz unterstützen können.",al={"warum nach astranaar schicken","beweggrund von fiora longears","warum schickt fiora euch"}},["432055d5"]={q="Warum bittet Fiora Euch, zu gehen, anstatt selbst zu gehen?",a="Fiora bleibt im Gasthaus von Theramore in den Düstermarschen und verweist willige Reisende an Shindrell Feuerflink in Astranaar, wo ihre Hilfe benötigt wird.",al={"warum ich für journey to astranaar","warum geht fiora nicht nach astranaar","warum nicht fiora"}}},fp="20,154,29.326.0,26.327.0,48.173.0,38.92.0,43.140.0,34.134.0,47.159.0,43.119.0"}
P.entries["quest:1134"] = {n="Prachtschwingen des Steinkrallengebirges",s="Im Steinkrallengebirge hört Shindrell, dass Prachtschwingengift den brüchigen Frieden bedrohen könnte. Theramore meldet die unbestätigte Behauptung, dass Orc-Attentäter das Gift für verdeckte Überfälle sammeln. Astranaars Schildwachen schicken Späher nach Süden, um die Giftbeutel zuerst zu erbeuten.",h="Im Steinkrallengebirge hört Shindrell, dass Prachtschwingengift den brüchigen Frieden bedrohen könnte.",kw={"attentäter","astranaar","mirkfallonsee","prachtschwingen","shindrell feuerflink","steinkrallengebirge","theramore","gift"},ang={["class:Druid"]="Als Druide trauert Ihr womöglich um die unschuldigen Geschöpfe, die getötet werden, um ihr Gift von Kriegstreibern fernzuhalten.",["class:Rogue"]="Als Schurke wisst Ihr, wie tödlich Prachtschwingengift eine bestrichene Klinge bei einem heimlichen Hinterhalt machen kann.",["faction:Alliance"]="Als Verbündeter der Allianz seht Ihr, wie Theramores geheimes Informationsnetz die Außenposten der Schildwachen im Eschental gegen Angriffe der Horde unterstützt.",["race:NightElf"]="Als Nachtelf steht Ihr trotz Eurer Fürsorge für die Natur vor der schweren Entscheidung, wilde Prachtschwingen zu töten, um ihr Gift dem Feind vorzuenthalten."},sec={{t="Ein brüchiger Waffenstillstand",b="Die Allianz und die Horde haben im nördlichen Kalimdor keinen offenen Krieg erklärt. Doch ihr Frieden ist brüchig. Unter dem Blätterdach brechen Scharmützel aus, und heimliche Angriffe treten an die Stelle ganzer Heere. In Astranaar beobachten die Kommandanten der Schildwachen die Bewegungen des Feindes. Ein unachtsamer Moment könnte ihre Zuflucht gefährden."},{t="Gift aus den Klüften",b="Shindrell hat von Kontakten in Theramore einen unbestätigten Bericht über Aktivitäten in den Klüften des Steinkrallengebirges erhalten. Orcische Pirscher sollen Gift von wilden Prachtschwingen am Mirkfallonsee sammeln und damit ihre Klingen für tödliche Hinterhalte gegen Streitkräfte der Allianz bestreichen.\n\nDeshalb schickt Shindrell Feuerflink Champions los, um die Bestien zu töten und ihre Giftbeutel zu erbeuten, bevor Agenten der Horde sie erreichen können."},{t="Eine schmerzliche Pflicht",b="Shindrell Feuerflink bedauert es, den Tod einheimischer Bestien anzuordnen. Nachtelfen verehren Kalimdors Wildnis, und diese Geschöpfe hatten keinen Anteil an der Entscheidung für den Krieg. Doch Astranaars Verteidiger dürfen nicht zulassen, dass ein Feind Gift für tödliche Angriffe sammelt. Die Bestien bezahlen diese Verteidigung mit ihrem Leben."}},faq={{q="Was sind Prachtschwingen?",a="Prachtschwingen sind gefährliche, giftige Flugbestien, die mit Wyvern verwandt sind. Sie nisten in hohen Klüften, besonders rund um den Mirkfallonsee im Steinkrallengebirge. Ihr Gift macht sie zu tödlichen Jägern und ist als Waffengift begehrt.",al={"was sind prachtschwingen","geschichte der prachtschwingen","prachtschwingen im steinkrallengebirge"}},{q="Warum jagt die Allianz sie?",a="Shindrell berichtet von einer unbestätigten Behauptung, dass Attentäter der Horde Prachtschwingengift sammeln, um Waffen für verdeckte Angriffe auf Stellungen der Allianz zu bestreichen. Die Allianz jagt die Bestien, um ihre Giftbeutel zuerst zu erbeuten und der Horde dieses Gift vorzuenthalten.",al={"warum prachtschwingen töten","zweck der quest","allianz prachtschwingengift"}},{q="Wer lieferte die Informationen über die Orc-Attentäter?",a="Geheime Informanten der Allianz in Theramore überbrachten die Warnung. Sie beobachten die Bewegungen und Nachschubwege der Horde im gesamten Südlichen Brachland und im Steinkrallengebirge.",al={"wer warnte die allianz","spionageinformationen aus theramore","shindrells informationsquelle"}},{q="Wo liegt der Mirkfallonsee?",a="Der Mirkfallonsee liegt im nördlichen Steinkrallengebirge, unmittelbar südlich des Grenzpfads aus dem Eschental.",al={"lage des mirkfallonsees","wo sind die prachtschwingen","prachtschwingen finden"}},{q="Befinden sich die Allianz und die Horde im Eschental im offenen Krieg?",a="Zwischen der Allianz und der Horde herrscht im Eschental kein erklärter offener Krieg. Doch unter dem Blätterdach gehen heimliche Tötungen, Scharmützel um Ressourcen und Grenzgefechte weiter.",al={"sind horde und allianz im krieg","kriegszustand im eschental","friedensvertrag im eschental"}},{q="Wie empfindet Shindrell Feuerflink das Töten der Bestien?",a="Shindrell Feuerflink schmerzt es, dass sie den Tod von Bestien anordnen muss, die im Konflikt keine Seite gewählt haben. Als Offizierin, die Astranaar verteidigt, sieht sie die Jagd als schmerzliche Notwendigkeit, um ihr Volk zu schützen.",al={"shindrells reaktion","druidische schuldgefühle","nachtelf tötet bestien"}}},fx={["9b2e4c3f"]={q="Wofür ist der Prachtschwingengiftbeutel?",a="Shindrell Feuerflink lässt Euch die Giftbeutel ernten, um zu beweisen, dass die Bestien erlegt wurden, und um der Horde eine tödliche Versorgung zu verweigern. Unbestätigte Informationen aus Theramore warnen davor, dass Orc-Attentäter Gift von den Prachtschwingen des Mirkfallonsees ernten, um ihre Waffen für heimliche Überfälle gegen die Allianz zu beschichten. Indem Ihr die Beutel selbst sammelt, stellt Ihr sicher, dass das Gift niemals feindliche Klingen erreicht.",al={"nutzung von prachtschwingengiftbeutel","warum giftbeutel sammeln","was macht shindrell mit den giftbeuteln"}}},fp="24,261,15.312.0,21.387.0,14.290.0,20.223.0,33.234.0,54.153.0,33.105.0,52.159.0,59.203.0"}
P.entries["quest:1135"] = {n="Steilhanggift",s="Von Theramore aus schickt Fiora Longears Jäger nach Westen, um Wyverngift zu beschaffen. Am Steilhang in Tausend Nadeln tragen die Wyvern Giftbeutel, die Käufer in ganz Kalimdor schätzen.",h="Von Theramore aus schickt Fiora Longears Jäger nach Westen, um Wyverngift zu beschaffen.",kw={"düstermarschen","fiora","der steilhang","longears","theramore","tausend nadeln","gift","wyvern"},ang={["class:Rogue"]="Als Schurke versteht Ihr die Anziehungskraft exotischer Gifte. Der Umgang mit reinem Wyverngift gewährt Euch einen genauen Einblick in die tödlichsten natürlichen Gifte Kalimdors.",["faction:Alliance"]="Als Reisender der Allianz dringt Ihr in Tausend Nadeln tief in das Gebiet der Horde vor, unter den wachsamen Augen von Tauren- und Orcpatrouillen.",["race:NightElf"]="Als Kaldorei seht Ihr, wie Handel und Neugier auf seltene Reagenzien über das Eschental und die Dunkelküste hinaus bis tief in die trockenen Einöden von Tausend Nadeln reichen."},sec={{t="Eine einträgliche Expedition",b="In Theramore sucht Fiora Longears Jäger, die für einen Handel jenseits der Nutzung von Wyvern als Flugreittiere durch die Horde weite Wege auf sich nehmen. Käufer in ganz Kalimdor schätzen das tödliche Gift dieser Kreaturen, oft mehr als die Bestien selbst. Die Reise führt in gefährliche Höhen und auf die Jagd nach frischen Giftbeuteln."},{t="Die Klippen des Steilhangs",b="Der Steilhang liegt westlich der Düstermarschen, zwischen den Sandsteintafelbergen von Tausend Nadeln. Seine Wyvern tragen ungewöhnlich konzentriertes Gift, doch um ihre Nester zu erreichen, müsst Ihr Hordegebiet durchqueren und tückisches Gelände erklimmen. Ihr müsst die Wyvern töten und ihre Giftbeutel unversehrt entnehmen, um sie dann nach Theramore zurückzubringen."}},faq={{q="Wo finde ich die Wyvern für diese Quest?",a="Die Wyvern nisten am Steilhang, einem hohen Tafelberg im Westen von Tausend Nadeln, westlich von Theramore.",al={"steilhang lage","wo ist der steilhang","wyvern fundort"}},{q="Wer ist Fiora Longears?",a="Fiora Longears ist eine Kontaktperson der Allianz in Theramore, vor der Küste der Düstermarschen. Sie wirbt Abenteurer an, die seltene und wertvolle natürliche Reagenzien aus ganz Kalimdor sammeln sollen.",al={"fiora longears","wer vergibt steilhanggift"}},{q="Warum ist Wyverngift so wertvoll?",a="Wyverngift ist hochwirksam und wird von bestimmten Untergrundkreisen, Apothekern und Händlern geschätzt. Die Horde schätzt Wyvern als Flugreittiere, während Alchemisten und Giftmischer gut für ihre Giftdrüsen zahlen.",al={"warum wyverngift","wyverngift verwendung"}},{q="Warum schickt mich eine Quest aus Theramore so weit nach Westen?",a="Fiora sucht exotische Exemplare, die in den Sümpfen um Theramore nicht vorkommen. Der Steilhang in Tausend Nadeln beherbergt eine besondere Wyvernart mit konzentriertem Gift.",al={"warum tausend nadeln","warum nach tausend nadeln schicken"}},{q="Was geschieht, wenn Ihr die Giftbeutel zurückbringt?",a="Fiora untersucht die Beutel und sagt, dass sie voller Gift sind. Sie bemerkt, dass eine solche Qualität gewöhnlich von jungen Wyvern oder fruchtbaren Weibchen stammt, und gratuliert Euch dann zur Jagd.",al={"fioras reaktion","questabschluss steilhanggift"}},{q="Ist der Steilhang für Reisende der Allianz sicher?",a="Nein. In Tausend Nadeln sind zahlreiche Streitkräfte der Horde stationiert, mit nahe gelegenen Siedlungen wie dem Freiwindposten. Wilde Raubtiere und feindliche Späher der Horde bedrohen Euch am Steilhang gleichermaßen.",al={"ist der steilhang gefährlich","allianz in tausend nadeln"}}},fx={["9e43b6cb"]={q="Warum möchte Fiora Longears, dass dies erledigt wird?",a="Fiora hat ein Auge für lukrativen Handel und seltene Reagenzien. Während die meisten Wyvern nur als Lasttiere kennen, die von der Horde gezähmt wurden, weiß sie, dass bestimmte Kreise für starkes Gift teuer bezahlen. Das Ernten der Beutel am Steilhang ermöglicht es ihr, auf diesen spezialisierten Märkten einen hübschen Gewinn zu erzielen.",al={"warum will fiora gift","beweggrund von fiora longears","warum wyverngift ernten"}},ef763353={q="Wofür ist der Steilhanggiftbeutel?",a="Die Giftbeutel enthalten das tödliche, starke Toxin der wilden Wyvern, die auf den Höhen von Tausend Nadeln nisten. Diese prallen Beutel, die bei ausgewählten Alchemisten, Giftmischern und exotischen Händlern sehr begehrt sind, erzielen auf Märkten, die mit seltenen und gefährlichen Bestien handeln, einen enormen Preis.",al={"wofür sind steilhanggiftbeutel","nutzung von giftbeuteln","warum giftbeutel sammeln"}},f9186ab4={q="Welche Kreaturen nisten am Steilhang?",a="Der Steilhang ist ein hoch aufragender Tafelberg in Tausend Nadeln, der als wilder Nistplatz für einheimische Wyvern dient. Diese geflügelten Raubtiere sind ungezähmt und äußerst territorial; sie gleiten durch die Wüstenschluchten und nutzen ihre giftigen Stachel, um Beute zu erlegen, bevor sie die Mahlzeiten zu ihren felsigen Horsten schleppen.",al={"was sind steilhangwyvern","wen jagt ihr am steilhang","was lebt am steilhang"}}},fp="15,160,22.298.0,22.319.0,43.91.0,22.178.0,32.202.0,48.161.0,44.175.0,41.169.0"}
P.entries["quest:1136"] = {n="Frostrachen",s="Im Alteracgebirge ruft Euch die Jagd auf einen seltenen Yeti weit fort von zu Hause. Melor Steinhuf schickt Euch auf die Jagd nach Frostrachen und erwartet dessen Mähne in Donnerfels.",h="Im Alteracgebirge ruft Euch die Jagd auf einen seltenen Yeti weit fort von zu Hause.",kw={"alteracgebirge","frostrachen","mähne","melor steinhuf","schriftrolle","donnerfels","yeti"},sec={{t="Eine ferne Jagd",b="Melor Steinhuf schickt Euch weit fort von zu Hause, um Frostrachen im Alteracgebirge zu jagen. Das weiße Fell des Yetis verschmilzt mit dem Schnee der Berge, und er zeigt sich nur selten. Melor gibt Euch eine Schriftrolle, die erklärt, wie Ihr ihn anlockt. Bringt Frostrachens Mähne zu Melor nach Donnerfels zurück, und Eure Reise wird vollendet sein."}},faq={{q="Wer ist Frostrachen?",a="Frostrachen ist ein Yeti im Alteracgebirge. Sein weißes Fell verschmilzt mit dem Schnee, und er zeigt sich nur selten.",al={"frostrachen wer","was ist frostrachen"}},{q="Wo kann ich Frostrachen finden?",a="Ihr könnt Frostrachen im Alteracgebirge finden, wo sein weißes Fell mit dem Schnee verschmilzt.",al={"frostrachen fundort","wo ist frostrachen"}},{q="Wie locke ich Frostrachen an?",a="Melor Steinhuf gibt Euch eine Schriftrolle mit Anweisungen, wie Ihr Frostrachen anlockt.",al={"frostrachen anlocken","frostrachen schriftrolle"}},{q="Was will Melor von Frostrachen?",a="Melor Steinhuf bittet Euch, ihm Frostrachens Mähne nach Donnerfels zu bringen.",al={"melor frostrachen","frostrachen mähne"}}},fp="8,146,14.310.0,16.104.0,26.90.0,23.73.0,35.76.0"}
P.entries["quest:1137"] = {n="Neuigkeiten für Fizzle",s="Im Ödland hat Martek the Exiled Neuigkeiten über Indurium für Fizzel Kupferbolz. Ihr überbringt seine Nachricht zur Illusionenrennbahn auf der Schimmernden Ebene in Tausend Nadeln.",h="Im Ödland hat Martek the Exiled Neuigkeiten über Indurium für Fizzel Kupferbolz.",kw={"ödland","fizzel kupferbolz","indurium","induriumerz","martek the exiled","illusionenrennbahn","die schimmernde ebene","tausend nadeln","uldaman"},sec={{t="Marteks Worte über Indurium",b="Martek sagt, dass Indurium Hitze bemerkenswert gut standhält und sich daher für Fizzels Kolben eignen könnte. Flocken reichen nicht aus; Fizzel braucht echtes Induriumerz, das tief in Uldaman am nördlichen Rand des Ödlands abgebaut wird. Martek nennt Uldaman als die wahre Quelle von Indurium. Er lässt grüßen und bittet Euch, Fizzel Kupferbolz alles zu wiederholen, was er Euch erzählt hat."},{t="Fizzel hört die Neuigkeiten",b="Fizzel Kupferbolz brennt darauf, Marteks Worte zu hören und zu erfahren, ob dieser helfen kann. Als Ihr Fizzel von Euren Reisen im Ödland erzählt, erklärt er Indurium zum Schlüssel."}},faq={{q="Wo beginnt und endet diese Reise?",a="Martek the Exiled im Ödland gibt Euch eine Nachricht für Fizzel Kupferbolz an der Illusionenrennbahn auf der Schimmernden Ebene in Tausend Nadeln.",al={"wer vergibt neuigkeiten für fizzle","wo neuigkeiten für fizzle abgeben","von martek zu fizzel"}},{q="Welche Neuigkeiten schickt Martek an Fizzel?",a="Martek sagt, dass Indurium Hitze bemerkenswert gut standhält und sich für Fizzels Kolben eignen könnte. Fizzel braucht echtes Erz statt Flocken, abgebaut tief in Uldaman.",al={"was sagt martek","neuigkeiten über indurium","marteks nachricht"}},{q="Woher stammt Induriumerz?",a="Martek sagt, dass Induriumerz tief in Uldaman am nördlichen Rand des Ödlands abgebaut wird. Er nennt Uldaman die wahre Quelle von Indurium.",al={"wo ist induriumerz","quelle von induriumerz"}},{q="Wo gehört dieser Schritt in die Handlung?",a="Dieser Schritt folgt auf Indurium in der Questreihe, die begann, als Fizzel Kupferbolz Euch zu Martek the Exiled schickte.",al={"questreihe neuigkeiten für fizzle","vorherige quest neuigkeiten für fizzle"}}},fp="15,170,25.333.0,21.164.1,38.142.0,37.150.0,34.135.0,42.99.0"}
P.entries["quest:1138"] = {n="Meeresfrüchte",s="An der Dunkelküste bittet Euch Gubber Blump, ein Fischer aus Auberdine, Krebsfleisch zu sammeln. Er bleibt an den Docks und träumt von Gerichten aus seinem Fang.",h="An der Dunkelküste bittet Euch Gubber Blump, ein Fischer aus Auberdine, Krebsfleisch zu sammeln.",kw={"auberdine","dunkelküste","verkrustete gezeitenkriecher","feine krebsbrocken","meeresfrüchte","gubber blump","riffkriecher"},ang={["faction:Alliance"]="Als Reisender der Allianz könnt Ihr Kalimdor über Auberdine erreichen, einen Anlaufpunkt für Entdecker der Allianz, und örtlichen Fischern helfen, sich einzuleben.",["profession:Cooking"]="Gubbers begeisterte Aufzählung von Krebsgerichten könnte Euch dazu anregen, das Beste aus den Fängen der örtlichen Küste zu machen.",["race:Dwarf"]="Als Zwerg hört Ihr vielleicht einen vertrauten Klang der Heimat, wenn ein Außenstehender im Norden Kalimdors von Eisenschmiede-Überraschungskrebs träumt. Ihr reist als Gebirgsjäger aus Khaz Modan."},sec={{t="Eine Leidenschaft für Krustentiere",b="Gubber Blump angelt von Auberdines langen Holzstegen aus und denkt dabei an Krebsfleisch. Er nennt Krebse den wahren Reichtum des Ozeans und stellt sie sich gebacken, gegrillt oder gekocht vor. Zu seinen Rezepten gehören Peitscherwurzel-Krebs und Eisenschmiede-Überraschungskrebs."},{t="Die Gezeitentümpel durchkämmen",b="Gubber kann seine Angelrute nicht verlassen und bittet Euch deshalb, an den Stränden der Dunkelküste Zutaten zu sammeln. Riffkriecher und verkrustete Gezeitenkriecher bewegen sich durch die Brandung und liefern Fleisch für einen Koch an der Küste. Nehmt Euch beim Sammeln der Feinen Krebsbrocken vor ihren Scheren in Acht."}},faq={{q="Wer vergibt die Quest Meeresfrüchte?",a="Gubber Blump, ein Fischer der Allianz an den Docks von Auberdine an der Dunkelküste, bittet Euch darum.",al={"meeresfrüchte questgeber","wer vergibt meeresfrüchte","gubber blump quest"}},{q="Welche Kreaturen lassen Feine Krebsbrocken fallen?",a="Riffkriecher und verkrustete Gezeitenkriecher an den Ufern der Dunkelküste und in der flachen Brandung liefern Feine Krebsbrocken.",al={"wo fallen feine krebsbrocken","was lässt krebsbrocken fallen","welche krebse lassen feine krebsbrocken fallen"}},{q="Warum sammelt Gubber das Krebsfleisch nicht selbst?",a="Gubber ist mit dem Angeln von Auberdines Stegen aus beschäftigt und kann seine Angelschnur nicht verlassen, um am Strand Krebse zu jagen.",al={"warum besorgt gubber seine krebse nicht selbst","warum braucht gubber hilfe"}},{q="Welche Gerichte möchte Gubber zubereiten?",a="Gubber nennt Krebssalat, Krebssuppe, Krebseintopf, Pfefferkrebs, Zitronenkrebs, Peitscherwurzel-Krebs und ein regionales Gericht, das er Eisenschmiede-Überraschungskrebs nennt.",al={"gubber krebsrezepte","welche rezepte erwähnt gubber","krebsgerichte"}},{q="Spielt Gubber Blumps Rede auf etwas an?",a="Ja. Gubbers Aufzählung von Krebsgerichten erinnert an Benjamin Buford 'Bubba' Blue aus dem Film Forrest Gump, dessen Rede über Garnelen als identisch beschrieben wird.",al={"gubber blump popkulturelle anspielung","forrest gump bubba anspielung"}},{q="Wo spielt diese Quest?",a="Sie beginnt und endet im Hafendorf Auberdine, während Ihr an den Ufern der Dunkelküste im Norden Kalimdors auf die Jagd geht.",al={"wo ist meeresfrüchte","in welchem gebiet ist meeresfrüchte"}}},fx={cf4b2535={q="Wofür sind die Feinen Krebsbrocken?",a="Gubber Blump beabsichtigt, sie für eine endlose Vielfalt an kulinarischen Gerichten zu verwenden. Für ihn sind Krebse die Fruit of the Sea, perfekt zum Backen, Grillen, Kochen, Braten, Frittieren und zum Mischen in Suppen, Eintöpfen und Salaten.",al={"nutzung von feinen krebsbrocken","warum feine krebsbrocken","was macht gubber mit den krebsbrocken"}},["82492fa1"]={q="Was sind die Kriecher entlang der Küste der Dunkelküste?",a="Riffkriecher und Verkrustete Gezeitenkriecher sind einheimische Krebstiere, die die langen, nebligen Küsten und flachen Gezeitentümpel der Dunkelküste absuchen. Obwohl sie für unvorsichtige Strandgänger gefährlich sind, wird ihr Fleisch von Fischern und Köchen wie Gubber Blump für reichhaltige Küstenfestmähler geschätzt.",al={"was sind riffkriecher","verkrustete gezeitenkriecher dunkelküste","krebse der dunkelküste"}}},fp="16,137,25.231.0,21.253.0,37.80.0,41.107.0,48.99.0,37.134.0,47.150.0,33.115.0"}
P.entries["quest:114"] = {n="Die Flucht",s="Maybell Maclure sucht einen Weg, ihre Familie zu verlassen und Tommy Joe Steinfeld zu treffen. Ihr bringt ihr William Pestles Unsichtbarkeitsschnaps, gebraut mit Kristalltang, der in der ganzen Region gesammelt wurde.",h="Maybell Maclure sucht einen Weg, ihre Familie zu verlassen und Tommy Joe Steinfeld zu treffen.",kw={"wald von elwynn","unsichtbarkeitsschnaps","weinberge der maclures","maybell maclure","hof der steinfelds","die flucht","tommy joe steinfeld","william pestle"},ang={["faction:Alliance"]="Als Abenteurer der Allianz, der im Wald von Elwynn beginnt, bietet Euch die Hilfe für Tommy Joe und Maybell eine unbeschwerte Pause vom Kampf gegen Defias-Banditen und Gnolle. Selbst nahe Sturmwind halten sich die alten Zwistigkeiten auf dem Land.",["race:Human"]="Als Mensch in Elwynn wisst Ihr, wie tief hartnäckiger Groll zwischen Familien sitzt. Kleine, heimliche Hilfeleistungen unter Nachbarn können dazu beitragen, den Frieden zu wahren."},sec={{t="Ein Gebräu für wahre Liebe",b="Die Maclures und die Steinfelds liegen seit Generationen in Fehde, sodass für Liebeswerben kein Raum bleibt. Oma Steinfeld bittet William Pestle, einen Alchemisten im Gasthaus \"Zur Höhle des Löwen\" in Goldhain, um Hilfe. Kristalltang aus den nahegelegenen Seen liefert Pestle, was er braucht, um Unsichtbarkeitsschnaps zu brauen. Das Gebräu kann Maybells Flucht vom Gehöft der Maclures verbergen."},{t="Im Wald verschwunden",b="Maybell Maclure nimmt die Flasche und schlüpft zwischen die Bäume, Tommy Joe entgegen. Schuldgefühle wegen der Täuschung ihrer Verwandten plagen sie, doch ihre Liebe wiegt schwerer als ihre Angst vor Entdeckung. Sie trinkt den Schnaps und verschwindet vor Euren Augen. Nun hat sie ein paar Augenblicke mit Tommy Joe, fern der wachsamen Blicke ihrer zerstrittenen älteren Verwandten."}},faq={{q="Wer vergibt die Quest Die Flucht?",a="William Pestle, ein Apotheker und Alchemiegehilfe im Gasthaus \"Zur Höhle des Löwen\" in Goldhain, gibt Euch Unsichtbarkeitsschnaps, nachdem Ihr ihm Kristalltang gebracht habt.",al={"questgeber die flucht","wer startet die flucht","wo die flucht annehmen"}},{q="Wofür wird der Unsichtbarkeitsschnaps verwendet?",a="Der Unsichtbarkeitsschnaps macht Maybell Maclure lange genug unsichtbar, um den Hof ihrer Familie zu verlassen und Tommy Joe Steinfeld zu besuchen, ohne ihre Verwandten aufzubringen.",al={"warum unsichtbarkeitsschnaps","was bewirkt der trank","unsichtbarkeitsschnaps zweck"}},{q="Warum müssen Maybell und Tommy Joe ihre Beziehung verbergen?",a="Die Familien Maclure und Steinfeld sind erbitterte Rivalen, und ihre tiefe Feindschaft verbietet ein offenes Liebeswerben zwischen ihren Kindern.",al={"warum verstecken sie sich","steinfeld maclure fehde","warum können maybell und tommy joe nicht zusammen sein"}},{q="Was geschieht, wenn Ihr Maybell den Trank überbringt?",a="Maybell dankt Euch, hin- und hergerissen zwischen Schuldgefühlen und Aufregung, und trinkt dann das Gebräu. Sie verschwindet vor Euren Augen und schleicht sich zu Tommy Joe davon.",al={"was geschieht am ende","verschwindet maybell","die flucht questabschluss"}},{q="Welche Quest führt unmittelbar zu Die Flucht?",a="Die Flucht folgt auf Collecting Kelp. Dort sammelt Ihr Kristalltang von Murlocs am Kristallsee, damit William Pestle den Unsichtbarkeitstrank brauen kann.",al={"voraussetzung für die flucht","quest vor die flucht","was führt zu die flucht"}},{q="Beendet diese Quest die Fehde zwischen den Familien?",a="Nein. Der Trank ermöglicht den Liebenden nur ein kurzes, heimliches Treffen. Die Fehde zwischen Oma Steinfeld und den Maclures bleibt erbittert und ungelöst.",al={"schließen die familien frieden","ist die fehde vorbei","endet die fehde"}}},fx={["53ceb805"]={q="Warum schickt William Pestle Euch, um den Schnaps zu liefern, anstatt es selbst zu tun?",a="William betreibt seinen geschäftigen Laden im Gasthaus \"Zur Höhle des Löwen\" in Goldhain und kann sein Handwerk nicht einfach verlassen, um Besorgungen im Wald zu erledigen. Wichtiger ist jedoch, dass das Herumwandern auf den Weinbergen der Maclures mit verdächtigen alchemistischen Tränken sofort den Verdacht von Maybells beschützerischen Verwandten erregen würde. Ihr, als wandernder Abenteurer, der bereits als Kurier zwischen den Liebenden fungierte und die Zutaten gesammelt hat, könnt unbemerkt auf die Farm schlüpfen, um ihr den Trank zu übergeben.",al={"warum schickt euch william","warum liefere ich den unsichtbarkeitsschnaps","warum kann william den trank nicht liefern"}},["245b9158"]={q="Warum hilft William Pestle Tommy Joe und Maybell?",a="William Pestle ist ein Apotheker, der bereit ist, der jungen Liebe mitfühlend beizustehen. Nachdem Oma Steinfeld ihm eine Nachricht geschickt und um einen Ausweg aus der erbitterten Fehde zwischen den Familien Stonefield und Maclure gebeten hatte, erklärte William sich bereit, Unsichtbarkeitsschnaps zu brauen, sobald er Kristalltang erhält. Er hat dabei nichts für sich selbst zu gewinnen, außer den beiden vom Schicksal getrennten Liebenden ein heimliches Treffen zu ermöglichen, ohne eine weitere Schlägerei zwischen ihren verfeindeten Angehörigen auszulösen.",al={"warum hilft william","william pestle beweggrund","warum maybell bei der flucht helfen"}}},fp="10,183,26.338.0,24.305.1,31.151.0,41.162.0,61.129.0,52.139.1,42.147.0,54.144.1"}
P.entries["quest:1140"] = {n="Der Turm von Althalaxx",s="Von Maestras Posten aus erreicht Delgrens Kreuzzug sein sechstes Kapitel. Er entziffert orkische Schriften, die den Gesandten des Kults abgenommen wurden, und erfährt, dass Athrikus Narassin zwei Seelensteine mit gefangenen Hochgeborenen in Satyrhochburgen tief in Eschental versteckt hat. Champions werden nach Nachtflucht und Satyrnaar entsandt, um die Gefäße zu zerschmettern, die gequälten Geister zu befreien und Athrikus' Macht zu schwächen.",h="Von Maestras Posten aus erreicht Delgrens Kreuzzug sein sechstes Kapitel.",kw={"althalaxx","eschental","athrikus","delgren","hochgeborene","maestras posten","nachtflucht","satyrnaar","seelensteine"},ang={["class:Paladin"]="Delgren der Läuterer ist ein pragmatischer heiliger Kreuzfahrer, der die Sprache seiner Feinde studiert, um dämonische Verderbnis aufzudecken und die gequälten Toten zu läutern.",["class:Priest"]="Die Gefängniskreise zu zerschmettern, bringt Geistern Frieden, die seit Jahrhunderten dämonische Qualen erleiden.",["race:NightElf"]="Als Nachtelf habt Ihr die feierliche Pflicht, die Ahnen der Hochgeborenen von der Schändung durch die Satyrn zu befreien. Diese Aufgabe stellt Euch den tragischen Überresten der uralten Vergangenheit Eures Volkes gegenüber."},sec={{t="Die Kritzeleien entziffern",b="Nachdem Ilkrud Magthrull, ein orkischer Bote, niedergestreckt wurde, setzt Delgren der Läuterer seine Kenntnisse der orkischen Sprache ein. Seine Glaubensbrüder im Heiligen Licht spotteten oft darüber, die Sprache eines Widersachers zu lernen. Doch Delgrens praktische Weisheit lässt ihn Notizen entziffern, die den Gesandten des Kults abgenommen wurden. Sie enthüllen, dass Athrikus Narassin zwei mächtige Seelensteine mit den Essenzen uralter Hochgeborener weit im Nordosten in den geschändeten Hainen von Nachtflucht und Satyrnaar versteckt hat."},{t="Unheilige Bündnisse",b="Die Seelensteine in den Satyrlagern offenbaren ein ruchloses Bündnis zwischen Athrikus' Zirkel und der dämonischen Brut der Brennenden Legion. Über Gefängniskreisen gebunden, erdulden uralte Geister endlose Qualen, um dunkle Zauberei zu nähren. Blutgetränkte Satyraltäre bergen wilde dämonische Verderbnis. Verborgene Satyrschleicher, die geschworen haben, diese arkanen Leitungen zu bewachen, warten in den Schatten."},{t="Athrikus schwächen",b="Die karmesinroten Steine zu zerschmettern und die Seelen der Hochgeborenen aus ihren Kreisen der Qual zu befreien, versetzt Athrikus' mystischer Stärke einen verheerenden Schlag. Delgren sagt, der Anführer des Althalaxx-Kults sei ohne die Seelensteine stark geschwächt. Doch nach der Tat beunruhigt den heiligen Kreuzfahrer das stille Unbehagen der Nachtelfen angesichts der Satyrn. Er beschließt, den Anführern von Auberdine von der fortbestehenden dämonischen Plage zu berichten."}},faq={{q="Warum kann Delgren Orkisch lesen?",a="Delgren ergriff die Initiative und lernte Orkisch, obwohl andere in seinem heiligen Orden ihn verspotteten. Er glaubte, die Sprache eines Feindes könne taktische Einblicke gewähren, und dieses Wissen erlaubte ihm, die bei Ilkrud Magthrull gefundenen Notizen zu übersetzen.",al={"delgren liest orkisch","warum kann delgren orkisch","delgrens übersetzung"}},{q="Was sind die Seelensteine, und warum befinden sie sich bei den Satyrn?",a="Die Seelensteine sind karmesinrote Fokussteine, die uralte Geister der Hochgeborenen über rituellen Gefängniskreisen binden. Athrikus Narassin handelte sie aus oder brachte sie in Heiligtümern wie Nachtflucht und Satyrnaar unter, wo das Leid der Geister die arkane Macht des Kults nährt.",al={"althalaxx seelensteine","warum haben satyrn die steine","gefangene seelen der hochgeborenen"}},{q="Wo liegen Nachtflucht und Satyrnaar?",a="Nachtflucht und Satyrnaar sind Satyrhochburgen in den bewaldeten Höhen im Nordosten des Eschentals, östlich von Maestras Posten.",al={"wo liegt nachtflucht","wo liegt satyrnaar","standorte der satyrlager"}},{q="Warum sprechen die Nachtelfen nur ungern über die Satyrn?",a="Delgren bemerkt, dass seine elfischen Gastgeber Gespräche über die Satyrn meiden, weil diese einst Nachtelfen waren. Während des uralten War of the Ancients gaben sie sich dämonischer Verderbnis hin und wurden zu Scheusalen mit Ziegenbeinen verformt, einer anhaltenden Quelle von Trauer und Scham für die Kaldorei.",al={"warum geheimniskrämerei um satyrn","verbindung zwischen nachtelfen und satyrn","elfische geschichte der satyrn"}},{q="Wie hilft die Befreiung dieser Seelen dabei, den Kult des Turms von Althalaxx aufzuhalten?",a="Athrikus Narassin schöpft aus der spirituellen Energie in den Seelensteinen der Hochgeborenen, um seine Rituale zu speisen. Die Steine zu zerschmettern, befreit die gefangenen Seelen und entzieht diesen Ritualen ihre Kraft, wodurch er für einen Angriff auf den Turm verwundbar wird.",al={"warum seelensteine zerschmettern","athrikus' machtquelle","athrikus schwächen"}},{q="Wer ist Elissa, mit der Delgren sprechen will?",a="Elissa Starbreeze ist eine bedeutende nachtelfische Sentinel, die in Auberdine stationiert ist und dort die örtliche Verteidigung der Dunkelküste koordiniert. Delgren plant, mit ihr über die fest verwurzelte Bedrohung des nördlichen Kalimdors durch die Satyrn zu beraten.",al={"elissa auberdine","wer ist elissa","delgren elissa"}}},fx={["866ee2a4"]={q="Gegen wen werdet Ihr geschickt, um die Seelen der Hochgeborenen zu befreien?",a="Ihr werdet tief in die korrumpierten Ruinen von Nachtflucht und Satyrnaar geschickt, gegen die Satyrn, die die Seelenjuwelen halten. Diese dämonischen Diener der Brennenden Legion haben sich mit Athrikus Narassin und seinem dunklen Kult verbündet und halten die uralten Seelen der Hochgeborenen in schwebenden roten Juwelen über ihren dunklen Kreisen der Gefangenschaft gefangen.",al={"gegen wen kämpft ihr","wer bewacht die seelenjuwelen","satyrn in nachtflucht und satyrnaar"}},["706f1be3"]={q="Warum schickt Delgren der Läuterer Euch, anstatt selbst zu gehen?",a="Delgren der Läuterer ist in Maestras Posten stationiert und koordiniert die Verteidigung und den Nachrichtendienst gegen die Einfälle von Kultisten und Dämonen jenseits der Grenze. Das Eindringen tief in befestigte Satyr-Festungen wie Nachtflucht und Satyrnaar erfordert einen erfahrenen Abenteurer, der an feindlichen Linien vorbeischlüpfen und die Juwelen zertrümmern kann, ohne eine ganze Garnison vom Außenposten abzuziehen.",al={"warum braucht delgren mich","warum kann delgren nicht gehen","warum einen abenteurer schicken"}}},fp="22,362,27.448.0,16.354.1,18.407.1,41.227.0,54.268.0,42.115.0,59.276.0,67.226.0,48.215.0"}
P.entries["quest:1141"] = {n="Die Familie und die Angelrute",s="An Auberdines Docks wartet Gubber Blump mit seiner geerbten Angel auf einen Fang. Feindselige Murlocs halten die kleinen Fischerboote des Ortes an Land, also sucht er Hilfe beim Fang einheimischer Dunkelküstenbarsche an der Küste.",h="An Auberdines Docks wartet Gubber Blump mit seiner geerbten Angel auf einen Fang.",kw={"auberdine","angel der familie blump","dunkelküstenbarsch","angeln","graun blump","gubber blump","murloc","verhülltes meer"},ang={["faction:Alliance"]="Als Mitglied der Allianz erlebt Ihr, wie Auberdines Hafen die Völker des Festlands und die Nachtelfen gegen Küstengefahren wie Murlocs zusammenbringt.",["profession:Cooking"]="Der Dunkelküstenbarsch ist ein verlässlicher, nahrhafter Fang an der Küste des nördlichen Kalimdor und ein Grundnahrungsmittel in den Lagern an der Grenze.",["race:Dwarf"]="Als Zwerg erinnert Euch die Begegnung mit einem Volksgenossen, der sich dem Angeln statt dem unterirdischen Schmieden oder Brauen widmet, daran, wie vielfältig zwergische Beschäftigungen sein können."},sec={{t="Ein Zwerg fern von Eisenschmiede",b="Gubber Blump ist stolz auf das Geschick seiner Familie im Umgang mit der Angelschnur. Nachtelfen stellen den Großteil der Bevölkerung Auberdines, doch auch Zwerge und Gnome haben sich an den Docks und am Hafen niedergelassen. Gubber verbringt seine Tage damit, über das verhüllte Meer zu blicken, statt sich in den Stein zu graben. Er hofft, die heimischen Fische an Land zu ziehen."},{t="Murlocplagen und Dunkelküstenbarsche",b="Dunkelküstenbarsche gedeihen entlang der Küste und lassen sich vielseitig zubereiten. An der Angel wehren sie sich lebhaft. Einheimische Fischer rudern gewöhnlich mit kleinen Booten in tiefere Gewässer, um sie zu fangen, doch nun streifen aggressive Murlocs an der Küste umher. Die Boote bleiben an Land, und Gubber fürchtet, dass die Kreaturen die heimischen Fische fressen. Also bittet er Reisende, vom Ufer aus zu angeln."},{t="Das Vermächtnis der Blumps",b="Gubber gibt jedem eine Angel der Familie Blump, der ihm einen stattlichen Fang bringt. Er glaubt, wer mehrere wehrhafte Barsche an Land zieht, erweist sich der legendären Fischer seiner Familie als würdig, darunter seine Cousine Graun Blump. Für Gubber ist die Übergabe einer Familienangel das höchste Zeichen des Respekts."}},faq={{q="Wer ist Gubber Blump?",a="Gubber Blump ist ein zwergischer Fischer an Auberdines Docks in der Dunkelküste. Er stammt aus einer stolzen Anglerfamilie, lehrt grundlegende Angeltechniken und gibt vielversprechenden Fischern die charakteristischen Angeln seiner Familie.",al={"wer ist gubber","gubber blump hintergrundgeschichte","auberdine zwergischer fischer"}},{q="Warum fahren von Auberdine keine Boote zum Fischen hinaus?",a="Feindselige Murlocs durchstreifen weite Teile der Dunkelküste und machen es zu gefährlich, kleine Fischerboote zu Wasser zu lassen. Die einheimischen Angler bleiben an den Anlegestegen und im seichten Wasser.",al={"warum keine boote","dunkelküste fischerboote","auberdine bootsprobleme"}},{q="Was ist ein Dunkelküstenbarsch?",a="Ein Dunkelküstenbarsch ist ein einheimischer Salzwasserfisch, der vor der Dunkelküste vorkommt. Angler schätzen seine lebhafte Gegenwehr und seine Verwendung in herzhaften Küstenrezepten.",al={"dunkelküstenbarsch"}},{q="Wer ist Graun Blump?",a="Graun Blump ist Gubbers Cousine. Gubber sagt, sie habe einen Vollbart und einen strengen Geruch, und zählt sie zu den besten Anglern, die ihre Familie hervorgebracht hat.",al={"graun blump","gubbers cousine"}},{q="Warum gibt es Zwerge in einer Nachtelfenstadt wie Auberdine?",a="Nach dem Dritten Krieg und der Gründung der Allianz überquerten Zwerge und Gnome aus Eisenschmiede das Meer nach Kalimdor. Sie kamen, um Handel zu treiben, Seeverbindungen aufzubauen und ihren neuen nachtelfischen Verbündeten mit der Hafeninfrastruktur zu helfen.",al={"warum zwerge in auberdine","zwerge in der dunkelküste"}},{q="Was ist die Angel der Familie Blump?",a="Die Angel der Familie Blump ist eine robuste Angel, die der Blump-Clan verwendet. Gubber gibt diese geschätzten Angeln an Reisende weiter, die ihr Angelgeschick in den Gewässern der Dunkelküste beweisen.",al={"blump angel","angel der familie blump","gubber belohnung angel"}}},fx={["60ad423d"]={q="Wozu dient der Dunkelküstenbarsch?",a="Dunkelküstenbarsche eignen sich hervorragend als Mahlzeit und können in einer Vielzahl lokaler Rezepte zubereitet werden. Obwohl Gubber zugibt, dass sie viele leckere Gerichte ergeben, interessiert er sich persönlich viel mehr für den Nervenkitzel, sie anzuhaken und einzuholen, als sie zu essen.",al={"wozu dienen dunkelküstenbarsche","dunkelküstenbarsch verwendung","zweck barsch"}},["27b30f0f"]={q="Warum möchte Gubber Blump Dunkelküstenbarsch?",a="Gubber stammt aus einer stolzen Ahnenreihe von Zwergenfischern und liebt das Handwerk aufrichtig. Normalerweise segelt er hinaus in die Bucht, um Dunkelküstenbarsch zu fangen, aber die kürzliche Ankunft aggressiver Murlocs hat den Bootsverkehr vollständig zum Erliegen gebracht. Gubber ist besorgt, dass die Murlocs sich am lokalen Bestand gütlich tun, und ist begierig darauf, sich etwas Barsch zu sichern und zu sehen, wie ein anderer vielversprechender Angler gute Angelpraktiken fortsetzt.",al={"beweggrund von gubber blump","warum möchte gubber fisch","warum barsch fangen"}}},fp="31,211,26.291.0,41.345.0,16.296.0,20.203.0,50.162.0,28.156.0,19.152.0,57.221.0,38.170.0"}
P.entries["quest:1142"] = {n="Die Sterblichkeit schwindet",s="Im Kral der Klingenhauer hat Heralath Bachquell eine letzte Bitte an die Lebenden. Er bittet Euch, den gestohlenen Anhänger seiner Frau nach Darnassus zu bringen und ihr zu sagen, dass er gestorben ist.",h="Im Kral der Klingenhauer hat Heralath Bachquell eine letzte Bitte an die Lebenden.",kw={"darnassus","falfindel","heralath bachquell","lonebrow","die sterblichkeit schwindet","anhänger des bundes","kral der klingenhauer","treshala bachquell"},ang={["faction:Alliance"]="Als Champion der Allianz in den von der Horde beherrschten Barrens tragt Ihr Heralaths letztes Andenken heim nach Darnassus und erfüllt eine traurige Ehrenpflicht.",["race:Dwarf"]="Als Zwerg hört Ihr, wie Heralath Lonebrows Tapferkeit würdigt, mit der er eine dringende Warnung aus der Festung der Borstennacken hinaustrug.",["race:NightElf"]="Als Nachtelf schmerzt es Euch, einen Eures Volkes allein und vergessen im Südlichen Brachland sterben zu sehen."},sec={{t="Ein letzter Atemzug in den Dornen",b="Heralath Bachquell liegt tödlich verwundet im Dornengestrüpp des Krals der Klingenhauer. Wilde Borstennacken und dunkle Magie haben die Festung überrannt, fernab der Lande der Allianz. Seine Kräfte schwinden, und er vermag nur noch abgehackt zu flüstern.\n\nEr spricht von Lonebrow, einem tapferen Zwerg, der vorausgeschickt wurde, um Falfindel zu warnen. Heralath weiß, dass er den Kral nicht lebend verlassen wird."},{t="Der Anhänger des Bundes",b="Heralath bittet Euch, den Anhänger zu bergen, der seine Ehe mit Treshala Bachquell bezeugt. Einer der Angreifer in diesem Bau hat ihn ihm entrissen. Er bittet jeden Reisenden, der bei ihm innehält, ihn quer durch Kalimdor nach Darnassus zu tragen, damit Treshala von seinem Tod erfährt und nicht vergeblich wartet."},{t="Trauer in Darnassus",b="Treshala Bachquell nimmt den geborgenen Anhänger ihres Mannes in Darnassus entgegen und erfährt, dass er gestorben ist. Am Boden zerstört schwört sie, dass Heralaths Werk nicht mit ihm untergehen wird. Allein mit ihrer Trauer bleibt ihr, um ihn zu trauern und sein Vermächtnis weiterzutragen."}},faq={{q="Wer ist Heralath Bachquell?",a="Heralath Bachquell ist ein Nachtelf der Allianz, der tödlich verwundet im Kral der Klingenhauer liegt. Während seine Kräfte schwinden, vertraut er vorbeikommenden Reisenden an, den gestohlenen Anhänger seiner Frau zu bergen und die Nachricht seines Todes nach Darnassus zu tragen.",al={"heralath bachquell","wer ist heralath","sterbender elf razorfen"}},{q="Wo befindet sich Heralath Bachquell?",a="Heralath Bachquell liegt im Kral der Klingenhauer, der dornenüberwucherten Festung der Borstennacken im Südlichen Brachland.",al={"heralaths standort","wo ist heralath","wo ist heralath zu finden"}},{q="Wer war Lonebrow?",a="Lonebrow ist ein tapferer Zwerg, den Heralath in seinen letzten Augenblicken erwähnt. Heralath sagt, Lonebrow sei aus dem Dornengestrüpp hinausgeschickt worden, um Falfindel vor den Gefahren im Kral zu warnen.",al={"zwerg lonebrow","wer ist lonebrow","lonebrows warnung"}},{q="Wer ist Treshala Bachquell?",a="Treshala Bachquell ist Heralaths Frau und lebt in Darnassus. Sie nimmt den geborgenen Anhänger entgegen und erfährt vom Tod ihres Mannes.",al={"treshala bachquell","wer ist treshala","heralaths frau"}},{q="Was ist der Anhänger des Bundes?",a="Der Anhänger des Bundes steht für die Ehe von Heralath und Treshala Bachquell. Angreifende Borstennacken stahlen ihn Heralath, bevor er im Kral der Klingenhauer starb.",al={"treshalas anhänger","was ist der anhänger","anhänger des bundes"}},{q="Wie reagiert Treshala auf die Nachricht?",a="Treshala ist untröstlich und beklagt die Grausamkeit der Welt. In ihrer Trauer beschließt sie, dass Heralaths Werk durch sie fortbestehen muss, und bittet dann darum, zum Trauern allein gelassen zu werden.",al={"treshalas reaktion","was geschieht bei der übergabe des anhängers"}}},fx={aa8861aa={q="Warum will Heralath Bachquell, dass dies erledigt wird?",a="Heralath weiß, dass er tief in den feindseligen Dornen von Kral der Klingenhauer stirbt. Sein letzter Wunsch in diesem Leben ist nicht sein eigenes Überleben, sondern sicherzustellen, dass seine geliebte Frau Treshala von seinem Schicksal erfährt und den geschätzten Anhänger der Bindung erhält, der ihm von den Stachelebern gestohlen wurde, bevor er seinen letzten Atemzug tut.",al={"warum heralath helfen","heralath bachquell motiv","warum den anhänger senden"}},["170253dc"]={q="Warum kann Heralath Bachquell den Anhänger nicht selbst zurückholen?",a="Heralath ist tödlich verwundet und schwindet schnell dahin, vollkommen hilflos inmitten der bösartigen Stacheleber des Krals. Er hat kaum noch Kraft, seine letzte Bitte zu flüstern, was ihn völlig unfähig macht, seine Angreifer zu bekämpfen oder die Reise zurück nach To Darnassus alleine zu überleben.",al={"warum braucht mich heralath","warum kann heralath das nicht tun","warum ich sterblichkeit schwindet"}}},fp="15,159,28.347.0,22.279.0,18.229.1,28.227.0,38.110.0,17.165.0,28.133.0,31.160.0,36.168.1"}
P.entries["quest:1143"] = {n="Der Turm von Althalaxx",s="Dunkle Riten im Turm von Althalaxx bedrohen die nördliche Dunkelküste. Balthule Schattenhieb führt einen Angriff der Allianz auf Athrikus Narassin an, den uralten Zauberer, der den Kult von der Turmspitze aus befehligt.",h="Dunkle Riten im Turm von Althalaxx bedrohen die nördliche Dunkelküste.",kw={"althalaxx","athrikus","balthule","dunkelküste","dämonisch","narassin","schattenhieb","hexenmeister"},ang={["class:Warlock"]="Als Hexenmeister erkennt Ihr in Athrikus’ mächtiger dämonischer Magie auf der Spitze von Althalaxx die Gefahr einer ungezügelten Verehrung der Teufelsmagie.",["faction:Alliance"]="Als Mitglied der Allianz helft Ihr, die nördliche Dunkelküste zu sichern, und schützt damit die Reisewege zwischen Auberdine und den dahinterliegenden Landen.",["race:NightElf"]="Als Nachtelf erinnert Euch die Konfrontation mit Athrikus Narassin an die arkane und dämonische Verderbnis, die einst Euer Volk verheerte."},sec={{t="Die Spitze erstürmen",b="In der nördlichen Dunkelküste bietet der verfallene Turm von Althalaxx dämonischen Riten Schutz. Balthule Schattenhieb hält in der Nähe Wache und erkennt, dass der Gefahr jetzt begegnet werden muss. Athrikus Narassin, ein uralter nachtelfischer Hexenmeister, haust an der Spitze. Unter dem zertrümmerten Dach leitet er die dunklen Rituale."},{t="Ein entscheidender Schlag",b="Athrikus Narassin wird von treuen Hexenmeistern und Magie bewacht, die gefährlicher ist als die der Kultisten an den Hängen. Ihr müsst Euch durch seinen inneren Zirkel kämpfen und seinen abgetrennten Kopf als Beweis mitnehmen. Balthule warnt, dass sich die dämonischen Streitkräfte erneut sammeln könnten. Doch Athrikus’ Tod beraubt den Kult seines Anführers und bringt der Dunkelküste ein gewisses Maß an Sicherheit."}},faq={{q="Wer ist Athrikus Narassin?",a="Athrikus Narassin ist ein uralter nachtelfischer Hexenmeister, der die Kultisten am Turm von Althalaxx befehligt. Er leitet dunkle Beschwörungen und dämonische Riten in den Ruinen der nördlichen Dunkelküste.",al={"athrikus","wer ist athrikus","boss von althalaxx"}},{q="Wo ist Athrikus Narassin zu finden?",a="Athrikus Narassin haust an der Spitze des Turms von Althalaxx. Erfahrene Hexenmeister und beschworene Diener bewachen ihn.",al={"wo ist athrikus","athrikus fundort","spitze von althalaxx"}},{q="Wer vergibt diese Quest?",a="Balthule Schattenhieb, ein Späher der Allianz, der nahe dem Fuß des Turms von Althalaxx lagert, bittet Euch, Athrikus zu töten.",al={"questgeber","balthule","balthule schattenhieb"}},{q="Wer ist der in der Quest erwähnte Delgren?",a="Delgren der Läuterer ist ein Verbündeter der Allianz in der Nähe. Er hat Euch geschickt, um Euch mit Balthule im Kampf gegen die dämonische Kabale abzustimmen.",al={"delgren","delgren der läuterer"}},{q="Was geschieht nach Athrikus’ Niederlage?",a="Athrikus Narassins Tod versetzt den dämonischen Aktivitäten in der Gegend einen schweren Schlag. Balthule warnt, dass sich die dunklen Streitkräfte erneut sammeln könnten.",al={"nach athrikus","turm von althalaxx ende"}},{q="Warum ist der Turm von Althalaxx eine Gefahr für die Dunkelküste?",a="Kultisten und Hexenmeister im Turm wirken Teufelsmagie und beschwören Dämonen in die Lande der Nachtelfen. Sie bedrohen die Wildnis und die nahe gelegenen Siedlungen.",al={"warum den turm säubern","althalaxx bedrohung"}}},fx={["95b2d6f7"]={q="Warum will Balthule Schattenhieb, dass Athrikus Narassins Kopf fällt?",a="Balthule Schattenhieb weiß, dass Athrikus Narassins die Kabale aus Kultisten und Hexenmeistern anführt, die den zerstörten Turm von Althalaxx besetzt hält. Indem er direkt Athrikus auf der Spitze des Turms angreift, hofft Balthule, deren Führung zu zerschlagen und die dämonischen Mächte zurückzudrängen, die durch die nördliche Dunkelküste kriechen, bevor sich ihre korrupten Riten weiter ausbreiten.",al={"warum athrikus töten","balthule motiv","balthule schattenhieb grund für die quest"}},["6015f725"]={q="Wozu dient Athrikus Narassins Kopf?",a="Athrikus Narassins Kopf dient als unwiderlegbarer Beweis dafür, dass der uralte Hexenmeister tatsächlich erschlagen wurde. Ihn zu Balthule Schattenhieb zurückzubringen, versichert ihm und seinen Verbündeten, dass der dunkle Meister des Turms nicht länger seine Anhänger befehligen oder dämonische Mächte an die Dunkelküste beschwören kann.",al={"verwendung athrikus narassins kopf","warum athrikus kopf bringen","athrikus kopf questgegenstand"}},["9e544083"]={q="Warum schickt Balthule Euch, um Athrikus gegenüberzutreten, anstatt selbst zu gehen?",a="Athrikus residiert auf dem Gipfel des Turms, umgeben von seinen tödlichsten Hexenmeistern. Während Balthule in Erwägung zieht, auf die Verstärkung von Delgren der Läuterer zu warten, setzte Delgren sein absolutes Vertrauen in Eure bewährte Kampfkraft, indem er Euch überhaupt erst schickte, was Euch zu ihrer besten Chance macht, schnell zuzuschlagen, bevor die Kultisten Verstärkung erhalten.",al={"warum ich balthule","warum kämpft balthule nicht gegen athrikus","warum schickt man mich allein"}}},fp="22,203,20.285.0,17.341.1,25.186.0,37.115.0,21.115.0,38.114.0,40.138.1,53.150.0"}
P.entries["quest:1147"] = {n="Der Schwarm wächst",s="Im Eisensteinlager sagt Moktar Krin, Belgrom wolle die Silithiden wieder unter die Erde treiben. Sein Kriegstrupp ist zu geschwächt, um zu kämpfen, also werdet Ihr zur Grabungsstätte südlich des Lagers geschickt, um Euch ihnen zu stellen.",h="Im Eisensteinlager sagt Moktar Krin, Belgrom wolle die Silithiden wieder unter die Erde treiben.",kw={"belgrom","forscherliga","eisensteinlager","moktar krin","die rustmaul-grabungsstätte","die schimmernde ebene","silithiden","tausend nadeln"},sec={{t="Ein halbtoter Kriegstrupp",b="Moktar Krin sagt, Belgrom halte die Silithiden für eine Bedrohung und wolle sie zurück in die Tiefen treiben, aus denen sie kamen. Moktars Kriegstrupp hat bereits die von der Forscherliga entsandten Zwerge getötet, doch die Kämpfer sind in keiner Verfassung für eine weitere Schlacht.\n\nDie Grabungsstätte liegt südlich des Eisensteinlagers, und Moktar erwartet dort keine weiteren Zwerge. Ihr sollt die Sucher, Schwarmdrohnen und Invasoren der Silithiden töten. Moktars Trupp kann erst abreisen, wenn die Arbeit getan ist."},{t="Moktars Dank",b="Moktar scherzt, dass der Ichor, der Euch bedeckt, Euer Aussehen verbessert, obwohl Ihr danach stinkt. Er warnt Euch, Euch von den Kodos fernzuhalten. Der Geruch allein beweist, dass Ihr Euren Teil gegen die Silithiden geleistet habt."}},faq={{q="Wo befindet sich der Silithidenbefall?",a="Der Befall befindet sich an der Rustmaul-Grabungsstätte, südlich des Eisensteinlagers.",al={"silithiden standort","wo sind die insekten","wo ist die grabungsstätte"}},{q="Warum kann Moktar Krins Trupp die Insekten nicht selbst bekämpfen?",a="Moktars Kriegstrupp ist nach dem Töten der von der Forscherliga entsandten Zwerge halbtot und kann in diesem Zustand keine weitere Schlacht schlagen.",al={"warum moktar helfen","warum ist der kriegstrupp verletzt","moktar trupp zustand"}},{q="Wer will die Silithiden zurücktreiben?",a="Belgrom, der die Silithiden als Bedrohung ansieht und sie zurück in die Tiefen drängen will, aus denen sie kamen.",al={"wer will die silithiden tot sehen","belgrom silithiden befehl"}},{q="Welche Arten von Silithiden müssen besiegt werden?",a="Ihr müsst Sucher, Schwarmdrohnen und Invasoren der Silithiden besiegen, jeweils fünf.",al={"welche silithiden töten","silithiden ziele"}},{q="Sind noch Zwerge an der Grabungsstätte?",a="Moktar erwartet keine weiteren Zwerge an der Grabungsstätte.",al={"sind zwerge bei rustmaul","forscherliga an der grabungsstätte"}}},fp="15,187,21.453.0,15.194.1,42.69.0,60.139.0,35.101.0,40.93.0,40.47.0"}
P.entries["quest:1148"] = {n="Teile des Schwarms",s="In Tausend Nadeln findet Ihr einen rissigen Silithidpanzer und seht, wie eng seine Panzerung verwoben ist. Korran am Wegekreuz möchte mehr dieser Kreaturen untersuchen.",h="In Tausend Nadeln findet Ihr einen rissigen Silithidpanzer und seht, wie eng seine Panzerung verwoben ist.",kw={"panzer","das wegekreuz","feld der riesen","herz","korran","silithiden","krallen","tausend nadeln"},ang={["faction:Horde"]="Als Mitglied der Horde bringt Ihr die Exemplare zu Korran am Wegekreuz."},sec={{t="Ein seltsamer Panzer",b="Ihr findet Silithidenchitin, das enger verwoben ist als alles, was Ihr je gesehen habt. Der Körper der Kreatur zeugt von großer Stärke und fortgeschrittener Entwicklung. Korran am Wegekreuz möchte mehr über die Kreaturen und ihren Ursprung erfahren. Er bittet um ein Silithidenherz, fünf Silithidenkrallen und drei intakte Silithidpanzer."},{t="Exemplare für Korran",b="Korran nimmt die Exemplare erfreut entgegen. Zusammen mit den im Feld der Riesen gefundenen Eiern geben sie ihm einen ersten Einblick, was für Kreaturen diese Insekten sind und was sie suchen."}},faq={{q="Wer möchte diese Silithidenteile haben?",a="Korran am Wegekreuz möchte die Silithidenteile haben, damit er mehr dieser Kreaturen untersuchen kann.",al={"wer ist korran","teile des schwarms abgeben","wer untersucht die silithiden"}},{q="Wo beginnt das?",a="Es beginnt damit, dass Ihr in Tausend Nadeln einen rissigen Silithidpanzer untersucht.",al={"teile des schwarms beginnen","rissiger silithidpanzer beginn","wo den panzer finden"}},{q="Welche Exemplare möchte Korran haben?",a="Korran möchte ein Silithidenherz, fünf Silithidenkrallen und drei intakte Silithidpanzer haben.",al={"welche gegenstände werden benötigt","liste der silithidenteile","was sammeln"}},{q="Warum möchte Korran Silithiden untersuchen?",a="Die Untersuchung weiterer Silithiden könnte das Wesen und den Ursprung der Kreaturen offenbaren.",al={"warum silithiden untersuchen","was korran erfährt"}}},fp="18,164,18.308.0,20.179.1,31.90.0,22.75.0,32.90.0,40.70.0"}
P.entries["quest:1149"] = {n="Test des Glaubens",s="In Dorn Ebenenpirschers Lager über Tausend Nadeln stellen sich Abenteurer der Horde einem Test des Glaubens. Der Einsiedler bittet sie, von einer Holzplanke in die Schlucht zu treten und auf ihre Entschlossenheit zu vertrauen.",h="In Dorn Ebenenpirschers Lager über Tausend Nadeln stellen sich Abenteurer der Horde einem Test des Glaubens.",kw={"dorn ebenenpirscher","horde","sprung des glaubens","planken","test of endurance","test des glaubens","tausend nadeln"},ang={["class:Priest"]="Als Priester pflegt Ihr Euren Glauben an höhere Mächte. Dorns Prüfung fordert Euch auf, diese Überzeugungen in die Tat umzusetzen.",["faction:Horde"]="Als Mitglied der Horde stellt Ihr Euch Prüfungen der Überzeugung, der Widerstandskraft in feindseligen Landen und des unbeugsamen Willens. Diese Werte halten die junge Horde in Kalimdor zusammen.",["race:Tauren"]="Für die Shu'halo haben Übergangsriten an den heiligen Stätten Kalimdors eine uralte Tradition. Dorns Prüfung fordert Euch auf, Vertrauen in das Unsichtbare zu zeigen."},sec={{t="Ein Maß des Geistes",b="Hoch über Tausend Nadeln sinnt Dorn Ebenenpirscher über Geist, Körper und Seele nach. Er stellt Prüfungen, um das Innere eines Abenteurers zu ergründen, statt sich auf einfache Stammestraditionen zu verlassen. Überzeugung kann viele Formen annehmen, glaubt er. In ihrem Kern liegt ein Glaube, der stark genug ist, das eigene Leben zu riskieren."},{t="Der Sprung ins Leere",b="Auf einer Felsnadel steht Ihr auf verwitterten Planken über dem leeren Abgrund. Um zu bestehen, tretet Ihr in die Tiefe, ohne die sichere Zusage, dass Ihr überleben werdet. Arkane oder spirituelle Kräfte bremsen Euren Fall und tragen Euch zurück in Sicherheit. Dann seid Ihr bereit für kommende Prüfungen."}},faq={{q="Wer ist Dorn Ebenenpirscher?",a="Dorn Ebenenpirscher ist ein Taurene, der als Einsiedler in einem abgelegenen Lager an den Klippen über Tausend Nadeln lebt. Er prüft Abenteurer der Horde auf Glauben, Ausdauer und Stärke.",al={"dorn ebenenpirscher hintergrund","wer vergibt test des glaubens","questgeber tausend nadeln"}},{q="Sterbe ich, wenn ich von der Planke springe?",a="Nein. Obwohl der Sturz von der Felsnadel tödlich wirkt, fängt Euch ein magischer Schutz auf und teleportiert Euch unversehrt in Dorn Ebenenpirschers Höhle.",al={"sterbe ich beim springen","tödlicher fallschaden beim test des glaubens","ist test des glaubens gefährlich"}},{q="Was geschieht nach dem Bestehen des Tests des Glaubens?",a="Sobald Dorn Euren Geist für empfänglich hält, fordert er Eure körperliche Belastbarkeit im Test of Endurance heraus.",al={"was folgt auf test des glaubens","test des glaubens questreihe","dorn ebenenpirscher nächste quest"}},{q="Warum sagt Dorn, dass Scheitern bedeutet, die Weite des Nether zu erkennen?",a="Dorns Worte sind eine düstere Mahnung an die Sterblichkeit. Er glaubt, dass jene ohne das innere Feuer zur völligen Hingabe riskieren, Leben und Seele an die endlose Leere jenseits der Welt der Lebenden zu verlieren.",al={"weite des nether bedeutung","dorn ebenenpirscher nether zitat"}},{q="Können Abenteurer der Allianz diese Prüfung ablegen?",a="Nein. Dorn Ebenenpirscher bietet seine Weisheit und spirituelle Führung nur Streitern der Horde an, die durch die gefährlichen Schluchten des südlichen Kalimdor reisen.",al={"test des glaubens nur für die horde","kann die allianz test des glaubens machen"}},{q="Wo findet der Test des Glaubens statt?",a="Die Prüfung beginnt in Dorns Lager in den Schluchtwänden von Tausend Nadeln. Magie verbindet das Lager mit einer einsamen Felsnadel über dem Schluchtboden.",al={"test des glaubens ort","wo ist die planke in tausend nadeln"}}},fx={f9bf32d9={q="Warum prüft Dorn Ebenenpirscher Euren Glauben?",a="Dorn Ebenenpirscher glaubt, dass jedes Wesen vom Geist, dem Körper und dem Verstand geformt wird. Während einige Eigenschaften durch kulturelle Traditionen geprägt sind, können andere nur tief im Inneren entdeckt werden. Indem er diese Prüfungen anbietet, zielt Dorn darauf ab, Eure innere Stärke zu messen und Euren Geist auf Härten vorzubereiten. Er verlangt einen blinden Sprung in die Canyonwinde, um zu beweisen, dass Ihr Glauben und Vertrauen besitzt, ohne eine Garantie auf Überleben, und stellt so sicher, dass Euer Geist offen für die größeren Herausforderungen ist, die vor Euch liegen.",al={"warum will dorn dass das erledigt wird","dorn ebenenpirscher motiv","warum prüfung des glaubenssprungs"}}},fp="13,180,23.284.0,22.250.1,25.149.0,35.138.1,45.104.1,69.182.0,40.144.0,40.143.0"}
P.entries["quest:115"] = {n="Schattenmagie",s="Marschall Marris braucht die Mitternachtskugeln, die den Schattenzauberern des Schwarzfels im Rotkammgebirge abgenommen werden sollen. Ihre dunkle Macht bedroht Seenhains Verteidiger und die Verteidigungslinie der Stadt.",h="Marschall Marris braucht die Mitternachtskugeln, die den Schattenzauberern des Schwarzfels im Rotkammgebirge...",kw={"schwarzfelsorcs","dämonisch verderbt","seenhain","marschall marris","mitternachtskugel","rotkammgebirge","schattenmagie","schattenzauberer"},ang={["class:Paladin"]="Als Paladin erfüllt Ihr Eure heilige Pflicht, das Reich der Sterblichen von dämonischer Verderbnis zu reinigen, indem Ihr Schattenzauberern entgegentretet und dämonisch verderbte Relikte sicherstellt.",["class:Warlock"]="Als Hexenmeister erkennt Ihr die fortbestehenden teuflischen Wurzeln des Schwarzfelsklans in den Mitternachtskugeln und der rohen dämonischen Energie, die orkische Zauberwirker kanalisieren.",["faction:Alliance"]="Seenhain steht kurz davor, überrannt zu werden, und erhält so gut wie keine Verstärkung aus Sturmwind. Dem Schwarzfelsklan seine dunkle Artillerie zu nehmen, ist entscheidend für das Überleben der Region."},sec={{t="Ein finsteres Arsenal",b="Der Schwarzfelsklan verlässt sich seit Langem auf rohe Gewalt. Jetzt bringen seine Überfälle im Rotkammgebirge eine dunklere Bedrohung mit sich. Schattenzauberer gebieten über dunkle Mächte und kanalisieren Teufels- und Schattenenergien durch dämonisch verderbte Mitternachtskugeln. Diese Relikte haben der örtlichen Miliz schreckliche Verluste zugefügt, und der Krieg wendet sich gegen die Verteidiger."},{t="Die Verderbnis eindämmen",b="Marschall Marris leitet Seenhains bedrängte Verteidigung vom Stadtzentrum aus. Er weiß, dass gewöhnlicher Stahl dunkle Relikte nicht leicht bezwingen kann. Wenn die Schwarzfelsorcs ihre Mitternachtskugeln behalten, könnten die östlichen Grenzen des Rotkammgebirges zusammenbrechen. Marris befiehlt, die Schattenzauberer zu erschlagen und die Kugeln sicherzustellen, damit die dämonischen Relikte zerstört werden, statt zum Einsatz zu kommen."}},faq={{q="Was sind Mitternachtskugeln?",a="Mitternachtskugeln sind dämonisch verderbte Energieleiter, die von Schattenzauberern des Schwarzfels getragen werden. Sie bündeln dunkle Magie zu verheerenden Schlägen gegen die sterblichen Verteidiger des Rotkammgebirges.",al={"mitternachtskugel","was ist eine mitternachtskugel","was bewirken mitternachtskugeln"}},{q="Warum will Marschall Marris diese Kugeln?",a="Marschall Marris will die Kugeln vom Schlachtfeld entfernen lassen, um die Angriffskraft der Schattenzauberer des Schwarzfels zu schwächen. Er plant, die dämonischen Relikte gefahrlos beseitigen und zerstören zu lassen.",al={"warum mitternachtskugeln sammeln","marris kugeln","marris plan für die kugeln"}},{q="Wer sind die Schattenzauberer des Schwarzfels?",a="Schattenzauberer des Schwarzfels sind orkische Zauberwirker, die Schattenmagie und teuflisch verderbte Magie einsetzen. Sie unterstützen die brutalen Krieger des Klans mit magischer Artillerie und Flüchen.",al={"schattenzauberer des schwarzfels","wer nutzt schattenmagie","zauberwirker des schwarzfels"}},{q="Wo sind die Schattenzauberer zu finden?",a="Schattenzauberer des Schwarzfels halten überall im nordöstlichen Rotkammgebirge Lager und befestigte Stellungen.",al={"wo sind schattenzauberer","standort der schattenzauberer","lager der schattenzauberer des schwarzfels"}},{q="Wird Seenhain die Kugeln untersuchen oder einsetzen?",a="Nein. Marschall Marris hält die Kugeln für gefährlich und dämonisch verderbt und sagt, die Welt wäre ohne sie besser dran. Er will sie sofort zerstören lassen.",al={"wird seenhain die kugeln einsetzen","kann die allianz die kugeln einsetzen","sind kugeln nützlich"}},{q="Warum taucht dämonische Magie im Rotkammgebirge auf?",a="Der Schwarzfelsklan hat sich seit den Tagen der Old Horde mit dunklen und teuflischen Wesen eingelassen. Seine Zauberwirker nutzen noch immer dämonische Relikte und Schattenmagie, um die Eroberungen des Klans voranzutreiben.",al={"warum dämonen im rotkammgebirge","dämonische verderbnis des schwarzfelsklans","teufelsmagie im rotkammgebirge"}}},fx={["809c126b"]={q="Warum braucht Marschall Marris einen Abenteurer anstelle seiner eigenen Wachen?",a="Die lokale Garnison von Seenhain ist bis zum Äußersten angespannt. Da Sturmwind die Verstärkung verweigert, kann Marschall Marris kaum genügend Soldaten aufbringen, um die Stadtbrücke zu verteidigen und die Straßen von Gnollen und Spähtrupps der Orcs freizuhalten. Das Eindringen in feindliche Hochburgen, um die Schattenzauberer der Schwarzfels zu Fall zu bringen, erfordert einen unabhängigen Abenteurer, der fähig ist, hinter den feindlichen Linien zuzuschlagen, wo keine regulären Stadtwachen entbehrt werden können.",al={"warum ich schattenmagie","warum braucht mich marris","warum nicht die wachen von seenhain schicken"}}},fp="12,156,18.326.0,20.339.0,23.158.0,40.183.0,36.161.0,34.106.0,37.152.0,43.184.0"}
P.entries["quest:1150"] = {n="Test der Belastbarkeit",s="In Tausend Nadeln stellen sich Prüflinge dem zweiten Ritus von Dorn Ebenenpirschers spirituellen Prüfungen. Nachdem sie ihren geistigen Mut bewiesen haben, betreten sie den Bau der Wildfedern, um ihre körperliche Ausdauer zu prüfen und dessen wilde Anführerin Grenka Bloodscreech hervorzulocken.",h="In Tausend Nadeln stellen sich Prüflinge dem zweiten Ritus von Dorn Ebenenpirschers spirituellen Prüfungen.",kw={"dorn ebenenpirscher","freiwindposten","grenka bloodscreech","bau der wildfedern","screeching canyon","test der belastbarkeit","tausend nadeln","der wetterwinkel"},ang={["faction:Horde"]="Dorn bietet diese Herausforderungen jedem Volk der Horde an. Er glaubt, dass junge Krieger aus jedem Stamm durch Entbehrungen abgehärtet werden müssen, bevor sie sich Kalimdors Gefahren stellen.",["race:Tauren"]="Als Tauren könnt Ihr Dorn Ebenenpirschers Prüfungen als Übergangsriten betrachten. Sie prüfen, ob Eure körperliche Ausdauer der spirituellen Führung der Earth Mother entspricht."},sec={{t="Den Körper prüfen",b="Im Wetterwinkel bereitet Dorn Ebenenpirscher junge Krieger auf eine weite, rauere Welt vor. Diese Prüfung stellt die Kraft des Körpers auf die Probe. Dorn glaubt, dass Einsatzbereitschaft spirituelle Hingabe, geistige Disziplin und die Ausdauer erfordert, anhaltende Brutalität zu ertragen."},{t="Vorstoß in den Bau der Wildfedern",b="Der Bau der Wildfedern liegt im Screeching Canyon, westlich des Freiwindpostens. Feindselige Harpyien bevölkern die Höhle, weshalb es gefährlich ist, sie allein zu betreten. Die Prüflinge kämpfen sich tief in den Nistplatz vor und verwüsten die gesammelten Vorräte der Harpyien. Dann überstehen sie die heftigen Vergeltungsangriffe des Schwarms, bis dessen Matriarchin Grenka Bloodscreech in den Kampf eingreift."}},faq={{q="Wer vergibt den Test der Belastbarkeit?",a="Dorn Ebenenpirscher, ein Taurenältester, vergibt den Test der Belastbarkeit im Wetterwinkel an den Schluchtklippen von Tausend Nadeln.",al={"questgeber test der belastbarkeit","wer startet den test der belastbarkeit","dorn ebenenpirscher quest"}},{q="Wo liegt der Bau der Wildfedern?",a="Der Bau der Wildfedern liegt hoch an den südlichen Schluchtwänden von Tausend Nadeln, westlich des Freiwindpostens. Ein gewundener Pfad durch den Screeching Canyon führt hinauf zur Rampe, die zum Höhleneingang führt.",al={"bau der wildfedern standort","wo ist die harpyienhöhle","screeching canyon rampe"}},{q="Wie lockt Ihr Grenka Bloodscreech hervor?",a="Ihr lockt Grenka Bloodscreech hervor, indem Ihr Euch bis in die tiefsten Kammern des Baus der Wildfedern vorkämpft und die gelagerten Lebensmittel und Vorräte der Harpyien verwüstet. Sie erscheint, um ihren Nistplatz zu verteidigen.",al={"grenka hervorlocken","wie grenka bloodscreech hervorlocken","grenka finden"}},{q="Was kommt nach dem Test der Belastbarkeit?",a="Wenn Ihr Grenkas abgetrennte Klaue zu Dorn Ebenenpirscher zurückbringt, nimmt er sie als Beweis Eurer körperlichen Ausdauer an und schickt Euch zum Test of Strength.",al={"nächste quest nach belastbarkeit","was folgt auf den test der belastbarkeit","dorn ebenenpirscher nächste prüfung"}},{q="Warum prüft Dorn Abenteurer, die keine Tauren sind?",a="Dorn sieht seine Berufung darin, die gesamte Jugend der Horde anzuleiten, unabhängig von Volk oder Stamm. Für ihn ist unerprobter Stolz ein Todesurteil in der weiten Welt, und er besteht darauf, dass jeder Krieger seine Bereitschaft an Körper, Geist und Seele beweist.",al={"warum hilft dorn der horde","dorn ebenenpirscher philosophie","taurenprüfungen für andere völker"}},{q="Welche Prüfung ging dieser voraus?",a="Der Test of Faith kommt vor dem Test der Belastbarkeit. Bei diesem gefährlichen Sprung der Hingabe prüft Dorn, ob der Geist eines Prüflings angesichts der Furcht wankt.",al={"vorherige quest","prüfung vor belastbarkeit","erste prüfung"}}},fx={["8999be4f"]={q="Warum will Dorn Ebenenpirscher, dass dies erledigt wird?",a="Dorn Ebenenpirscher sieht es als seine heilige Pflicht an, junge Abenteurer auf die tödlichen Gefahren der weiten Welt vorzubereiten. Nachdem er sichergestellt hat, dass Euer Geist und Euer Glaube intakt sind, besteht er darauf, Euren physischen Körper zu prüfen. Indem er Euch zwingt, Welle um Welle wütender Harpyien tief in ihrem eigenen Gebiet zu überstehen, stellt er sicher, dass Ihr über die Ausdauer und Entschlossenheit verfügt, die erforderlich sind, um außerhalb der Sicherheit Eures Zuhauses zu überleben.",al={"warum prüft dorn die ausdauer","dorn ebenenpirscher motiv","zweck der ausdauerprüfung"}},b2efd71b={q="Wozu dient Grenkas Klaue?",a="Die Klaue dient als unbestreitbarer Beweis dafür, dass Ihr im Herzen vom Bau der Wildfedern standgehalten, den anhaltenden Ansturm der Harpyien überlebt und ihre wilde Matriarchin, Grenka Blutschrei, niedergestreckt habt. Dorn benötigt sie, um zu bestätigen, dass Eure Ausdauer unter unerbittlichem Angriff standgehalten hat, bevor er Euch Eure nächste Prüfung präsentiert.",al={"verwendung grenkas klaue","warum brauche ich grenkas klaue","grenkas klaue zweck"}},["28ecd26a"]={q="Wer ist Grenka Blutschrei?",a="Grenka Blutschrei ist eine furchterregende Anführerin unter den Harpyien vom Bau der Wildfedern, die die Canyonhöhlen westlich vom Freiwindposten befallen. Bösartig und sehr territorial herrscht sie über das innere Heiligtum des Schwarms. Wenn Ihr tief in den Bau der Wildfedern stürmt und ihre gehorteten Vorräte zerschlagt, lockt ihr Zorn sie vom Horst herab, um Euch selbst zu erschlagen.",al={"wer ist grenka","grenka blutschrei lore","anführerin der wildfederharpyien"}}},fp="17,247,16.250.0,31.336.0,32.123.0,34.186.0,38.171.0,39.146.0,49.216.0,35.162.0"}
P.entries["quest:1151"] = {n="Test der Kraft",s="In Tausend Nadeln fordert Dorn Ebenenpirscher Euch auf, Eure Stärke zu beweisen. Eure Prüfung führt Euch gegen Rok'Alim the Pounder, einen uralten Felselementar, und verlangt Stücke seiner zerschmetterten Gestalt.",h="In Tausend Nadeln fordert Dorn Ebenenpirscher Euch auf, Eure Stärke zu beweisen.",kw={"dorn ebenenpirscher","alte götter","felselementar","rok'alim","test der kraft","the pounder","tausend nadeln","der wetterwinkel"},ang={["class:Shaman"]="Als Schamane erkennt Ihr in Rok'Alim einen gefährlichen, ungebundenen Erdgeist. Seine Weigerung nachzugeben stört das örtliche Gleichgewicht der Geister.",["faction:Horde"]="Als Mitglied der Horde verdient Ihr Euch den Respekt der Ältesten von Donnerfels, indem Ihr die Riten des Wetterwinkels vollendet. Ihr mehrt Euer Ansehen in ganz Kalimdor.",["race:Tauren"]="Als Taurenpilger stellt Ihr Euch einem ungezähmten Steingeist in einer traditionellen Prüfung der Harmonie und körperlichen Willenskraft. Ihr zeigt, dass Ihr den härtesten Kräften der Earth Mother standhalten und sie überwinden könnt."},sec={{t="Überreste des Zeitalters der Alten Götter",b="Vor langer Zeit bedeckten urzeitliche Elementare die Welt und dienten den Alten Göttern. Als jene Mächte gestürzt und unter der Erde versiegelt wurden, verloren die Geister ihren Halt in dieser Welt. Die meisten schwanden aus der physischen Welt, sofern moderne Zauberkunst sie nicht band und beschwor. Einige wenige waren stark genug, um ohne solche Magie auf Azeroth zu bleiben. Rok'Alim the Pounder ist einer von ihnen und wandert als Echo jenes Zeitalters durch die trockenen Schluchten von Tausend Nadeln."},{t="The Pounder von Tausend Nadeln",b="Die Zentaurenklans benannten Rok'Alim nach dem ohrenbetäubenden Krachen seiner Steinfäuste auf dem Schluchtboden. Wer seinen Weg kreuzt, läuft Gefahr, zu Staub zerschlagen zu werden. Dorn Ebenenpirscher schickt Initianden aus, um sich dieser rohen Macht zu stellen und ihren Kriegergeist zu beweisen. Als Beweis ihres Sieges kehren sie mit Fragmenten des steinernen Herzens des Elementars zurück."}},faq={{q="Wo beginnt und endet diese Quest?",a="Dorn Ebenenpirscher vergibt die Prüfung im Wetterwinkel und nimmt sie dort ab, in einem abgeschiedenen Schluchtenlager hoch zwischen den Felsspitzen von Tausend Nadeln.",al={"questgeber","wo abgeben","dorns standort"}},{q="Was ist Rok'Alim the Pounder?",a="Rok'Alim ist ein uralter Felselementar, der seit dem Zeitalter der Alten Götter in Kalimdor überdauert hat. Seine angeborene Macht lässt ihn ohne Beschwörung körperlich auf Azeroth verweilen.",al={"wer ist rokalim","welche art gegner ist rokalim","geschichte der elementare"}},{q="Warum nennen die Zentauren ihn „the Pounder“?",a="Die Zentaurenstämme nennen Rok'Alim the Pounder wegen der donnernden Druckwellen, die seine Steinfäuste entfesseln, wenn sie alles auf seinem Weg zerschmettern.",al={"beiname the pounder","zentaurenname für rokalim"}},{q="Wo in der Schlucht ist Rok'Alim zu finden?",a="Rok'Alim durchstreift die nordwestlichen Gebiete von Tausend Nadeln und patrouilliert meist auf offenem Gelände südlich der Hauptstraße über den Schluchtboden.",al={"rokalims erscheinungsort","wo ist rokalim"}},{q="Welchen Platz nimmt diese Quest in der gesamten Prüfungsreihe ein?",a="Dies ist die dritte Prüfung der Reihe, nach Test of Faith und Test of Endurance. Sie kommt vor der letzten Prüfung, Test of Lore.",al={"reihenfolge der questreihe","what comes next","was kommt davor"}},{q="Warum verlangt Dorn, einen Elementar statt eines Wildtiers oder Feindes zu töten?",a="Dorn wählt Rok'Alim, weil der Elementar lebender Stein und eine unnachgiebige, urzeitliche Kraft ist. Ihn zu überwinden, beweist Eure körperliche Stärke gegenüber der rohen, unbeugsamen Erde selbst.",al={"warum einen elementar töten","zweck des tests der kraft"}}},fx={d3b1c16f={q="Warum will Dorn Ebenenpirscher, dass dies erledigt wird?",a="Dorn Ebenenpirscher unterzieht Euch einem uralten Ritual der Tauren, um Euer Können zu beweisen, bevor Ihr zu den letzten Prüfungen voranschreitet. Sich einem bloßen Tier oder Soldaten zu stellen, würde Eure Macht nicht wirklich messen, also verlangt er, dass Ihr einen fortdauernden Überrest von urzeitlichem Stein herausfordert. Rok'Alim zu erschlagen beweist, dass Eure innere und physische Stärke sogar uralte Elementarkräfte überwinden kann.",al={"dorn ebenenpirscher motiv","warum will dorn dass rokalim getötet wird","warum den test of strength ablegen"}},["67dd1d0a"]={q="Wozu dienen die Fragmente von Rok'Alim?",a="Die Fragmente dienen als unwiderlegbarer Beweis dafür, dass Ihr vor Rok'Alim der Schmetterer standet und das uralte Elementar zu Schutt reduziert habt. Dorn Ebenenpirscher benötigt einen physischen Beweis Eures Sieges, um anzuerkennen, dass Ihr den Test of Strength erfüllt und den Durchgang zur nächsten Prüfung verdient habt.",al={"verwendung fragmente von rokalim","wozu sind die fragmente","warum fragmente von rokalim sammeln"}}},fp="16,194,29.440.0,31.340.0,36.133.0,29.183.0,42.136.0,42.143.0,59.139.0,75.182.0"}
P.entries["quest:1152"] = {n="Test der Lehre",s="In Tausend Nadeln schickt Dorn Ebenenpirscher Champions der Horde nach Norden zu einer Prüfung über die Geschichte der Welt. Braug Dimspirit wartet im Steinkrallengebirge, um ihr Wissen über Azeroth und das Leid seiner Völker zu prüfen.",h="In Tausend Nadeln schickt Dorn Ebenenpirscher Champions der Horde nach Norden zu einer Prüfung über die...",kw={"braug dimspirit","dorn ebenenpirscher","steinkrallengebirge","der steinkrallenpfad","test der lehre","tausend nadeln","der wetterwinkel","die scherwindklippe"},ang={["class:Shaman"]="Als Schamane könnt Ihr das Leid des Landes an rücksichtslosen Taten ablesen, von der Ausbeutung durch Goblins bis zur uralten Abschottung der Elfen.",["faction:Horde"]="Als Mitglied der Horde müsst Ihr Euch mit dem Ruf Eurer Verbündeten auseinandersetzen. Orcs und Verlassene tragen gemeinsam mit anderen Verantwortung für die Not des Landes.",["race:Tauren"]="Als Tauren stellt Ihr Euch Prüfungen, die geistige Harmonie und Geschichtswissen höher schätzen als rohe Blutgier."},sec={{t="Vom Glauben zur Lehre",b="Im Wetterwinkel prüft Dorn Ebenenpirscher den Glauben, die Ausdauer und das Kampfgeschick der Eingeweihten. Doch Stärke und Glaube allein machen noch keinen wahren Champion der Horde aus. Dorn kennt die Grenzen dessen, was er lehren kann, und schickt jene, die sich bewährt haben, ins Steinkrallengebirge. Dort wird ein älterer Schamane ihren Verstand und ihr Wissen über die Welt prüfen."},{t="Der Weg ins Steinkrallengebirge",b="Der Weg führt nach Norden durch das trockene Buschland des Brachlands und in die schroffen Felsen des Steinkrallengebirges. Hoch in den Bergen, nahe dem Eingang zum Steinkrallenpfad, liegt Braug Dimspirits Einsiedelei. Die Höhle führt durch den Fels nach Eschental. Von dort blickt Braug auf ein umkämpftes Grenzland: Holzfällerunternehmen der Goblins verwüsten die Wälder, während feindselige Nachtelfen ihre angestammten Grenzen erbittert verteidigen."},{t="Ein weiterer Blick",b="Braug Dimspirit fordert Champions auf, über den Stolz auf ihre Fraktion hinauszublicken. Er spricht vom tragischen Zustand Azeroths und davon, wie Orcs und Verlassenen die Schuld an Krieg und Verderbnis gegeben wird. Doch fast jede Zivilisation trägt Mitverantwortung für die Not des Landes. Goblins fällen uralte Bäume, und Nachtelfen misstrauen den jüngeren Völkern. Um die Prüfung zu bestehen, muss ein Champion über diese Feindschaften hinausblicken und die Geschichte einer verwundeten Welt verstehen."}},faq={{q="Was ist der Test der Lehre?",a="Der Test der Lehre ist eine Prüfung innerhalb eines Übergangsritus, den die Ältesten der Tauren geprägt haben. Eingeweihte beweisen körperliche Stärke und Glauben sowie Wissen über die Geschichte und die gemeinsame Vergangenheit Azeroths.",al={"test der lehre bedeutung","was ist diese quest"}},{q="Wo kann ich Braug Dimspirit finden?",a="Braug Dimspirit lebt hoch im Steinkrallengebirge, nahe der Scherwindklippe und dem Eingang zum Steinkrallenpfad. Die Höhle verbindet das Steinkrallengebirge mit Eschental.",al={"braug dimspirit standort","wo ist braug"}},{q="Warum schickt Dorn Ebenenpirscher Euch fort?",a="Dorn Ebenenpirscher leitet die Prüfungen des Glaubens, der Ausdauer und der Stärke in Tausend Nadeln. Das Wissen über die Welt reicht über das hinaus, was er lehren kann, also schickt er würdige Eingeweihte zu Braug, einem Schamanen mit der Weisheit, ihren Verstand zu prüfen.",al={"warum steinkrallengebirge","warum dorn jemanden fortschickt"}},{q="Vor welchen Gefahren sollten sich Reisende unterwegs hüten?",a="Dorn warnt, dass Nachtelfen durch das Grenzland nahe Eschental und dem Steinkrallengebirge streifen, wo sie die Horde als Eindringling betrachten. Auch die Holzfällerbetriebe der Goblins sorgen rund um die Scherwindklippe für eine unberechenbare Lage.",al={"gefahren auf dem weg zu braug","steinkrallenpfad gefahr"}},{q="Wie sieht Braug Dimspirit die Konflikte der Welt?",a="Braug Dimspirit glaubt, dass alle sterblichen Völker eine Mitschuld am Leid der Welt tragen. Orcs und Verlassene werden oft von ihren Rivalen beschuldigt, während auch die Gier der Goblins und der Hochmut der Nachtelfen Kalimdor und Lordaeron geschadet haben.",al={"braug dimspirit philosophie","was glaubt braug"}},{q="Was ist der Steinkrallenpfad?",a="Der Steinkrallenpfad ist ein Gebirgstunnel, der die Scherwindklippe im Steinkrallengebirge mit den Grenzen der uralten Wälder im Süden Eschentals verbindet.",al={"was ist der steinkrallenpfad","steinkrallenpfad höhle"}}},fp="12,212,18.340.0,22.389.0,21.423.1,25.175.0,33.151.0,41.221.0,54.198.0,56.220.0,27.143.0"}
P.entries["quest:1153"] = {n="Eine neue Erzprobe",s="In Camp Taurajo sucht Tatternack Stahlformer nach Erz in Tausend Nadeln, um die Waffen der Horde zu stärken. Er schickt Euch nach Süden, um eine Probe zur Prüfung zu beschaffen.",h="In Camp Taurajo sucht Tatternack Stahlformer nach Erz in Tausend Nadeln, um die Waffen der Horde zu stärken.",kw={"camp taurajo","kobold","tatternack stahlformer","tausend nadeln","thrall","unbearbeitete erzprobe","weapons of choice"},ang={["faction:Horde"]="In Camp Taurajo könnt Ihr von der südlichen Bastion der Horde aus Materialien für die militärischen Vorbereitungen des Kriegshäuptlings liefern.",["profession:Blacksmithing"]="Als Schmied der Horde helft Ihr, neue Metallvorkommen zu sichern, damit die Grenze gegen nahe Bedrohungen gewappnet bleibt.",["profession:Mining"]="Als Prospektor kennt Ihr den Wert roher Erzadern, die grabende Kreaturen in den unerforschten südlichen Schluchten freilegen."},sec={{t="Der Ehrgeiz eines Schmieds",b="Tatternack Stahlformer ist ein Schmied in Camp Taurajo, den Orgrimmar genau im Auge behält. Er hat bereits Waffen aus dem Kriegsgerät der örtlichen Zentauren gefertigt. Doch er hofft noch immer, Kriegshäuptling Thrall sein Können zu beweisen. Durchreisende zeigten ihm seltsames Erz, das sie einem Kobold im Süden abgenommen hatten. Als sie sich weigerten, es zu verkaufen, empfand er ihre Weigerung als Beleidigung seines Handwerks und der Horde."},{t="Vorstoß nach Tausend Nadeln",b="Ihr verlasst die flachen Ebenen des südlichen Brachlands und zieht in das hoch aufragende Schluchtenlabyrinth von Tausend Nadeln. Koboldgräber treiben Tunnel durch seine Felsen und Klippen. Bringt unraffinierte Erzbrocken zurück, die Ihr ihnen direkt abnehmt. Dann kann Tatternack beurteilen, ob sich das rohe Mineral zu Waffen für Thralls Kriegsanstrengungen schmieden lässt."}},faq={{q="Wer ist Tatternack Stahlformer?",a="Tatternack Stahlformer ist ein orkischer Waffenschmied in Camp Taurajo im südlichen Brachland. Er fertigt Waffen für die Grenzverteidigung der Horde und sucht neue Materialien, um Kriegshäuptling Thrall zu beeindrucken.",al={"tatternack","schmied in camp taurajo","wer ist tatternack"}},{q="Woher stammt diese Erzprobe?",a="Kobolde tragen das unraffinierte Erz durch die gewundenen Schluchten von Tausend Nadeln, südlich des Großen Aufzugs an der Grenze des Brachlands.",al={"wo ist das erz","erzfundort","erz in tausend nadeln"}},{q="Warum ist Tatternack auf die Durchreisenden wütend?",a="Reisende aus dem Süden zeigten Tatternack einen seltsamen Mineralbrocken, den sie einem erschlagenen Kobold abgenommen hatten, weigerten sich dann aber, ihn zu verkaufen. Er empfand ihre Weigerung, lebenswichtige Materialien zu teilen, als unpatriotische Beleidigung des Kriegshäuptlings und beschimpfte sie als Feiglinge.",al={"warum ist tatternack wütend","reisende erz","tatternack reisende"}},{q="Was wird Tatternack mit dem Erz tun?",a="Tatternack will das Metall im Erz untersuchen und seine Festigkeit prüfen. Erweist es sich als widerstandsfähig genug, will er einen Waffenprototyp schmieden und ihn Kriegshäuptling Thrall in Orgrimmar vorlegen.",al={"was geschieht mit dem erz","warum will er erz"}},{q="Welche Voraussetzung muss vor dieser Aufgabe erfüllt werden?",a="Zuerst schließt Ihr Weapons of Choice ab, indem Ihr bestimmte Waffen von den Zentaurenstämmen sammelt, die Camp Taurajo bedrohen. Damit beweist Ihr, dass sich das örtliche Kriegsgerät weiterverarbeiten lässt.",al={"vorausgesetzte quest","vorherige quest","weapons of choice"}},{q="Warum tragen Kobolde in Tausend Nadeln dieses Erz bei sich?",a="Kobolde graben und schürfen, wobei sie Tunnel durch Felsen und unterirdische Erzadern treiben. In Tausend Nadeln haben ihre Grabungen ungewöhnliche Vorkommen freigelegt, die von den Bewohnern der Oberfläche nur selten angerührt werden.",al={"bergbau der kobolde","kobolde in tausend nadeln"}}},fx={ecf3b4be={q="Warum braucht Tatternack Euch, um die Erzprobe zu sammeln?",a="Tatternack ist im Camp Taurajo stationiert, kümmert sich um seine Schmiede und stellt auf direkten Befehl des Kriegshäuptlings Rüstungen für die Horde her. An seine Pflichten am Amboss gebunden und beleidigt von durchreisenden Mercenaries, die sich weigerten, ihren Fund zu teilen, wendet er sich an einen Abenteurer, der bereits sein Vertrauen gewonnen und sich im Kampf bewährt hat.",al={"warum ich eine neue erzprobe","warum braucht mich tatternack","warum kann tatternack das erz nicht holen"}}},fp="16,143,18.374.0,29.312.0,29.189.0,37.126.0,49.233.0,37.182.0,53.169.0,54.184.0"}
P.entries["quest:1154"] = {n="Test der Lehre",s="Am Steinkrallenpfad stellen sich Suchende der Horde dem Test der Lehre. Braug Dimspirit verlangt, dass sie einen Wälzer zur Drachengeschichte finden und studieren, bevor er ihr Wissen abfragt.",h="Am Steinkrallenpfad stellen sich Suchende der Horde dem Test der Lehre.",kw={"eschental","braug dimspirit","camp taurajo","deathwing","der dor'danil-grabhügel","dorn ebenenpirscher","vermächtnis der aspekte","der steinkrallenpfad","test der lehre"},ang={["class:Druid"]="Als Druide begegnet Ihr im Dor'danil-Grabhügel der Tragödie erschlagener und korrumpierter Nachtelfenverwandter. Einst schliefen sie dort in Verbundenheit mit dem Smaragdgrünen Traum.",["faction:Horde"]="Als Mitglied der Horde stellt Ihr Euch einer Prüfung, die Euch auf Kalimdors tiefe Vergangenheit und die gefährlichen Elfenruinen des Eschentals vorbereiten soll. Unwissenheit kann Euch dort zum Verhängnis werden."},sec={{t="Ein Wandel der Prüfungen",b="Nach Prüfungen in den Salzebenen und auf den Hochebenen von Tausend Nadeln reisen Dorn Ebenenpirschers Prüflinge nach Norden zu Braug Dimspirit im Steinkrallengebirge. Er wartet nahe dem Eingang zum Steinkrallenpfad. Braug betrachtet jene früheren Prüfungen als Proben für Körper und Glauben. Doch die Horde braucht auch einen disziplinierten Verstand und Wissen über die uralte Geschichte, nicht nur Geschick im Kampf gegen Bestien."},{t="Die Schatten von Dor'Danil",b="Braug schickt Suchende durch den Steinkrallenpfad ins südliche Eschental. Unter den Bäumen südlich des Splitterholzpostens liegt der Dor'danil-Grabhügel, eine gefährliche Ruine, heimgesucht von gefallenen Nachtelfendruiden und den Kreaturen, die sie abschlachteten. Tief in seinen unteren Kammern liegt auf einem steinernen Podest das „Vermächtnis der Aspekte“. Das seltene Manuskript erzählt von der uralten Erschaffung und dem Verderben der großen Drachenaspekte."},{t="Lernen oder leiden",b="Braugs Prüfung verlangt von Euch, die Lehren des Wälzers zu lernen, bevor Ihr ihn übergebt. Er nimmt das Buch und prüft Euer Wissen über die von den Titanen ermächtigten Beschützer und den Verrat, der Deathwing hervorbrachte. Versagt Ihr oder ratet schlecht, werdet Ihr quer durch Kalimdor nach Camp Taurajo im Südlichen Brachland verbannt. Dann müsst Ihr in Schande ins Steinkrallengebirge zurückreisen."}},faq={{q="Wer ist Braug Dimspirit?",a="Braug Dimspirit ist ein betagter Taurenschamane nahe dem Eingang zum Steinkrallenpfad im Steinkrallengebirge. Nach Dorn Ebenenpirschers früheren Prüfungen prüft Braug, ob die Streiter der Horde ihre Kampfkraft mit Wissen und Verstand verbinden.",al={"braug dimspirit","wer vergibt test der lehre","questgeber im steinkrallengebirge"}},{q="Wo befindet sich das Buch Vermächtnis der Aspekte?",a="Das „Vermächtnis der Aspekte“ liegt im Dor'danil-Grabhügel im südlichen Eschental, fast genau südlich des Splitterholzpostens. Tief unter den Grabhügeln liegt es auf einem steinernen Podest auf einer zentralen Plattform.",al={"vermächtnis der aspekte fundort","wo ist das buch","dor'danil buchfundort"}},{q="Was lauert im Dor'danil-Grabhügel?",a="Der Dor'danil-Grabhügel war einst eine Zuflucht für Nachtelfendruiden. Rastlose Geister der toten Druiden und die tödlichen Kreaturen, die sie abschlachteten, suchen seine Höhlen heim und machen den Weg durch die Ruine gefährlich.",al={"dor'danil gegner","wer bewacht das buch","eschental grabhügel"}},{q="Warum lässt Braug mich das Buch vor der Abgabe lesen?",a="Braug nimmt das Buch bei Eurer Rückkehr an sich und prüft Euer Gedächtnis. Er erwartet, dass Ihr es zuvor studiert, denn er prüft Euer Wissen ebenso wie Eure Fähigkeit, den Band zu bergen.",al={"warum vermächtnis der aspekte lesen","wissensfragen test der lehre","was passiert bei falscher antwort"}},{q="Wie fügt sich diese Quest in die gesamte Prüfungsreihe ein?",a="Diese Prüfung folgt auf den Test of Faith, den Dorn Ebenenpirscher am Wetterwinkel in Tausend Nadeln begann. Dorn prüfte Euren Mut und Euer Überleben unter tödlichen Bedingungen. Braug prüft Euer Wissen über Überlieferungen und Geschichte.",al={"test of faith questreihe","was kommt vor test der lehre","dorn ebenenpirschers prüfungen"}},{q="Wovon handelt das Vermächtnis der Aspekte?",a="Das „Vermächtnis der Aspekte“ erzählt, wie die Titanen die fünf großen Drachenaspekte ermächtigten, Azeroth zu beschützen. Es erzählt auch vom Fall von Neltharion the Earth-Warder und seiner Verwandlung in den als Deathwing bekannten Zerstörer.",al={"vermächtnis der aspekte geschichte","buch überlieferungen","wovon handelt das buch"}}},fx={["0efda427"]={q="Warum verlangt Braug Dimspirit von mir, das Vermächtnis der Aspekte zu finden?",a="Braug Dimspirit prüft Euren Verstand anstelle Eurer Stärke. Nachdem Ihr bereits die physischen Prüfungen von Dorn Ebenenpirscher überstanden habt, werdet Ihr nun nach Eurem Intellekt, Eurem Einfallsreichtum und Eurer Lernbereitschaft beurteilt. Indem er Euch allein in gefährliches Gebiet schickt, um uraltes Wissen zurückzugewinnen und aufzunehmen, bestimmt Braug, ob Ihr die Weisheit besitzt, die es wert ist, die Prüfungsreihe abzuschließen.",al={"warum prüft mich braug","warum das vermächtnis der aspekte","warum prüfung durch braug dimspirit"}}},fp="12,160,21.367.0,24.400.0,15.353.1,23.232.0,48.201.0,39.199.0,58.171.1,54.213.0,56.212.0"}
P.entries["quest:1159"] = {n="Test der Lehre",s="Über das große Meer tragen Suchende der Horde den Test der Lehre nun zu den Ruinen von Lordaeron. Ihr habt Braug Dimspirits erstes Rätsel im Steinkrallengebirge gelöst. Nun schickt er Euch zu einem ehemaligen menschlichen Gelehrten unter den Verlassenen in Unterstadt.",h="Über das große Meer tragen Suchende der Horde den Test der Lehre nun zu den Ruinen von Lordaeron.",kw={"das apothekarium","braug dimspirit","dorn ebenenpirscher","lordaeron","parqual fintallas","test der lehre","tausend nadeln","unterstadt","der wetterwinkel"},ang={["faction:Horde"]="Der Test der Lehre offenbart die Bande zwischen den Völkern der neu geschmiedeten Horde. Er bringt suchende Tauren mit Lordaerons grimmigen Archivaren zusammen.",["race:Tauren"]="Als Initiand der Tauren verlasst Ihr Kalimdors weite Ebenen und hohe Tafelberge und reist in Unterstadts giftige, enge Abwasserkanäle. Die Reise prüft Euer Verständnis einer anderen Kultur ebenso wie Euer Geschichtswissen.",["race:Undead"]="Die Begegnung mit Parqual zeigt, wie Gelehrte der Verlassenen wie er trotz Verwesung und Untod die akademischen Traditionen und Aufzeichnungen des gefallenen Lordaeron bewahrten."},sec={{t="Eine gelehrte Allianz",b="Nachdem Ihr Eure Fähigkeiten bewiesen und im Vermächtnis der Aspekte die Geschichte der Drachenaspekte kennengelernt habt, gesteht Braug Dimspirit, dass sein Wissen Grenzen hat. Die Prüfung reicht nun über Kalimdor hinaus und zeigt die weitreichenden Bande der Horde. Also schickt Braug Euch zur untoten Hauptstadt unter den Ruinen von Lordaeron."},{t="Der skeptische Historiker",b="Parqual Fintallas lebt in den feuchten Korridoren des Apothekariums. Einst ein angesehener menschlicher Chronist der nördlichen Königreiche, suchte er trotz der Geißel und seiner Verwandlung in einen der Verlassenen weiter nach Wissen. Ihr kommt als Außenstehender und behauptet, die spirituellen und körperlichen Prüfungen von Tausend Nadeln bestanden zu haben. Parqual bezweifelt, dass Ihr mehr als ein opportunistischer Söldner seid, und erwartet, dass Ihr ihm Euren Wert beweist."}},faq={{q="Warum schickt mich eine Prüfung der Tauren bis nach Unterstadt?",a="Braug Dimspirit weiß, dass die Beherrschung der Lehre mehr verlangt als Kenntnisse über Kalimdors Geschichte. Er schickt Euch zu Parqual Fintallas, einem berühmten menschlichen Gelehrten, dessen Wissen Lordaerons Fall und seine Verwandlung in einen Untoten überdauerte. Parqual wird Euer Verständnis der Weltgeschichte prüfen.",al={"warum nach unterstadt","warum lordaeron","braug schickt zu untoten"}},{q="Wo genau befindet sich Parqual Fintallas?",a="Parqual Fintallas befindet sich in Unterstadt, an der südlichen Brücke im Viertel des Apothekariums.",al={"wo ist parqual","parquals standort","fintallas finden"}},{q="Wer war Parqual Fintallas zu Lebzeiten?",a="Zu Lebzeiten war Parqual Fintallas ein versierter menschlicher Historiker im Königreich Lordaeron. Die Plague of Undeath ereilte ihn, und er schloss sich Sylvanas' Verlassenen an. Er setzte seine Studien fort und wandte seinen Verstand finstereren Forschungen zu.",al={"parqual fintallas geschichte","wer ist parqual","fintallas vorgeschichte"}},{q="Warum glaubt Parqual nicht, dass Braug mich geschickt hat?",a="Parqual misstraut Außenstehenden. Er kann nicht glauben, dass ein gewöhnlicher Abenteurer von den Felsnadeln von Tausend Nadeln springen, urzeitliche Elementare besiegen und uralte Relikte bergen konnte. Er vermutet, dass Ihr nur Gerüchte in einer Schenke aufgeschnappt habt.",al={"warum ist parqual unhöflich","parquals reaktion","parqual glaubt mir nicht"}},{q="Zu welcher größeren Prüfung gehört diese Quest?",a="Der Test der Lehre entstand aus der Prüfung, die Dorn Ebenenpirscher am Wetterwinkel begann, und hier ist ihre Mitte erreicht. Sie prüft Kampfkraft, Mut, Verstand und Geschichtswissen, wie sie eines Champions der Horde würdig sind.",al={"welche questreihe ist das","test of faith questreihe","was ist test der lehre"}},{q="Was folgt, nachdem ich Parqual erreicht habe?",a="Parqual wird Euch sein eigenes geschichtliches Rätsel erst stellen, nachdem Ihr einen Botengang für ihn in den Östlichen Königreichen übernommen habt. Er will einen Beweis, dass Ihr der fähige Held seid, für den Braug Euch hält.",al={"was folgt nach parqual","nächste quest nach unterstadt","nach dem gespräch mit fintallas"}}},fx={["670eb265"]={q="Warum schickt Euch Braug Dimspirit in die Unterstadt?",a="Braug Dimspirit hat Euer anfängliches Wissen geprüft, aber seine Rolle besteht nur darin, Euch durch die erste Phase vom Test of Lore zu führen. Um Euer Verständnis der Welt wirklich herauszufordern, erkennt er, dass die nächste Frage eine Perspektive jenseits seiner eigenen erfordert. Er schickt Euch zu Parqual Fintallas – einem berühmten Historiker aus Lordaeron, der nun unter den Verlassenen weilt –, damit Eure Hingabe an Geschichte und Wahrheit von einem Gelehrten beurteilt werden kann, der Erleuchtung einer gänzlich anderen Art anstrebt.",al={"warum schickt mich braug","braug dimspirit motiv","warum in die unterstadt braug"}}},fp="12,243,20.300.0,23.435.0,57.275.0,43.89.0,34.222.0,42.214.0,40.207.0,39.179.0"}
P.entries["quest:116"] = {n="Trockene Zeiten",s="Im Gasthaus von Seenhain werden die Getränke knapp, während Schwarzfelsorcs die Stadt belagern. Die Straßen sind unsicher, und die üblichen Lieferungen bleiben aus.",h="Im Gasthaus von Seenhain werden die Getränke knapp, während Schwarzfelsorcs die Stadt belagern.",kw={"barkeeper daniels","trockene zeiten","schnapsbart donnerbräu","seenhain","merlot","mondschein","rotkammgebirge","süßer rum","donnerbräu lagerbier"},ang={["faction:Alliance"]="Als Kurier der Allianz seht Ihr, wie unsichere Straßen im Rotkammgebirge den Alltag beeinträchtigen. Ihr helft, den Handel zwischen Sturmwind, Elwynn, Westfall, dem Dämmerwald und dem Rotkammgebirge wiederherzustellen.",["race:Dwarf"]="Als Zwerg wisst Ihr, dass menschliche Schenken selbst während einer Orcinvasion auf zwergische Braukunst angewiesen sind. Kuriere reisen für Schnapsbart Donnerbräus berühmtes Lagerbier nach Westfall."},sec={{t="Eine Stadt unter Belagerung",b="Schwarzfelsorcs rücken von Burg Steinwacht herab und setzen Seenhain schwer zu. Da die Versorgungswege abgeschnitten und die Straßen unsicher sind, werden im Gasthaus die Getränke knapp. Barkeeper Daniels wendet sich an Reisende, die die blockierten Straßen überwinden und Vorräte für die verängstigten Dorfbewohner und die Stadtwachen zurückbringen können."},{t="Eine Rundreise durchs Königreich",b="Daniels braucht Getränke aus allen Landen von Sturmwind. Merlot findet Ihr in der Hauptstadt und süßen Rum im Gasthaus \"Zur Höhle des Löwen\" in Goldhain. Mondschein kommt aus Dunkelhain im Dämmerwald, und Schnapsbart Donnerbräu braut Donnerbräu Lagerbier in den Hügeln von Westfall."}},faq={{q="Warum geht Seenhain der Alkohol aus?",a="Schwarzfelsorcs haben den Handel im Rotkammgebirge gestört und die Versorgungskarawanen aufgehalten. Daniels' übliche Lieferungen sind überfällig, und seinem Gasthaus gehen die Getränke aus, während Seenhain unter der Last des Krieges leidet.",al={"warum trockene zeiten","warum kein alkohol in seenhain","barkeeper daniels problem"}},{q="Wo finde ich alle Getränke, die Barkeeper Daniels braucht?",a="Merlot findet Ihr in Sturmwind und süßen Rum in Goldhain im Wald von Elwynn. Mondschein kommt aus Dunkelhain im Dämmerwald, und Schnapsbart Donnerbräu braut Donnerbräu Lagerbier in den Hügeln von Westfall.",al={"trockene zeiten getränkefundorte","wo merlot mondschein rum kaufen","wo getränke für daniels besorgen"}},{q="Wer ist Schnapsbart Donnerbräu?",a="Schnapsbart Donnerbräu ist ein zwergischer Brauer in den Hügeln von Westfall. Daniels möchte sein Lagerbier, und Ihr müsst zuerst ein frisches Fass für Grimbooze beschaffen.",al={"grimbooze aufenthaltsort","wo ist schnapsbart donnerbräu","westfall thunderbrew"}},{q="Wer ist Barkeeper Daniels?",a="Barkeeper Daniels führt das Gasthaus in Seenhain. Da Schwarzfelsorcs die Stadt bedrohen, heuert er Reisende an, die Vorräte über die gefährlichen Straßen bringen.",al={"barkeeper daniels","seenhain gastwirt","wer vergibt trockene zeiten"}},{q="Warum braucht Daniels Getränke aus so vielen verschiedenen Regionen?",a="Daniels bewirtet Flüchtlinge, örtliche Milizionäre und durchreisende Abenteurer. Er braucht zwergisches Lagerbier, edlen Wein aus der Hauptstadt und Spirituosen aus dem Dämmerwald und Elwynn.",al={"warum so viele getränke","warum dämmerwald und westfall besuchen"}},{q="Welche Belohnung gibt Barkeeper Daniels für den Botengang?",a="Daniels erstattet Eure Reisekosten mit Münzen und gibt Euch einen von seiner Frau handgenähten Umhang dafür, dass Ihr Euch auf die umkämpften Straßen wagt.",al={"trockene zeiten belohnung","was gibt daniels"}}},fx={["266c2dd6"]={q="Warum braucht Barkeeper Daniels Eure Hilfe beim Besorgen von Getränken?",a="Daniels kann seine Taverne nicht unbeaufsichtigt lassen, besonders während Seenhain angespannt ist und Gäste verzweifelt nach einem Getränk suchen, um ihre Sorgen zu vergessen. Währenddessen sind die lokalen Gardisten und die Miliz der Stadt vollständig damit beschäftigt, die Invasion der Schwarzfels-Orcs abzuwehren, die aus dem Norden drückt. Nur ein umherziehender Abenteurer hat die Freiheit, sicher über die gefährlichen Hauptstraßen des Königreichs zu reisen, um Vorräte zu sammeln.",al={"warum ich dry times","warum braucht daniels einen abenteurer","warum schickt man mich für getränke"}},["8f4cd8c5"]={q="Wozu dient das Fass von Thunderbrew?",a="Das Fass enthält starkes Thunderbrew-Lagerbier, das von Schnapsbart Donnerbräu draußen in den Hügeln von Westfall gebraut wurde. Barkeeper Daniels braucht es, um die schwindenden Vorräte von Seenhain aufzufüllen und den verängstigten Stadtbewohnern und bedrängten Verteidigern ein kräftiges Zwergenbier zu geben, um ihre Stimmung angesichts der Bedrohung durch die Schwarzfels hochzuhalten.",al={"fass von thunderbrew dry times","warum fass von thunderbrew","wozu dient thunderbrew lager"}},["0ca5cd6a"]={q="Wozu dient der Schlauch mit süßem Rum?",a="Dieser Schlauch mit süßem Rum kommt direkt aus dem Gasthaus \"Zur Höhle des Löwen\" unten in Goldhain. Daniels nimmt ihn in seine Notfall-Spirituosenlieferung auf, um den Geschmack seiner Gäste nach süßeren Spirituosen zu befriedigen, während die Standardversorgungsleitungen der Stadt durch die Orcs weiterhin unterbrochen bleiben.",al={"schlauch mit süßem rum dry times","warum süßer rum","wozu dient süßer rum"}},["41f763cb"]={q="Wozu dient das Fässlein mit Merlot?",a="Dieses Fässlein mit feinem Rotwein stammt aus dem Herzen von Sturmwind und bietet einen Hauch von zivilisiertem Komfort inmitten des düsteren Grenzkrieges. Daniels braucht es, um sicherzustellen, dass sein Tavernenkeller nicht vollständig austrocknet, während die Straßen weiterhin belagert sind.",al={"fässlein mit merlot dry times","warum fässlein mit merlot","wozu dient merlot"}},["88b6ac2e"]={q="Wozu dient die Flasche mit Fusel?",a="Diese Flasche mit beißendem Fusel, der im schattigen Weiler Dunkelhain gebraut wurde, verleiht einen starken, ungeschliffenen Kick. Barkeeper Daniels führt sie im Angebot, um Gäste zu bedienen, die etwas außergewöhnlich Starkes brauchen, um ihre Nerven gegen die ständige Bedrohung durch eine Invasion zu stählen.",al={"flasche mit fusel dry times","warum flasche mit fusel","wozu dient der fusel"}}},fp="9,152,18.279.0,27.257.0,40.183.0,53.202.0,29.148.0,23.148.0,60.157.0,57.135.0"}
P.entries["quest:1160"] = {n="Test of Lore",s="Parqual Fintallas in der Unterstadt bittet Euch, *Anfänge der Bedrohung durch die Untoten* zu finden. Das Buch ist Gegenstand seiner Bitte.",h="Parqual Fintallas in der Unterstadt bittet Euch, *Anfänge der Bedrohung durch die Untoten* zu finden.",kw={"buch","parqual fintallas","test of lore","anfänge der bedrohung durch die untoten","unterstadt"},sec={{t="Parquals Bitte",b="Der Name *Anfänge der Bedrohung durch die Untoten* ist das, wonach Ihr für Parqual Fintallas in der Unterstadt sucht. Ihr sollt ihm das Buch zurückbringen."}},faq={{q="Was möchte Parqual?",a="Parqual Fintallas bittet Euch, *Anfänge der Bedrohung durch die Untoten* zu finden und es ihm in der Unterstadt zurückzubringen.",al={"parquals bitte","welches buch möchte er"}},{q="Wo soll ich das Buch zurückbringen?",a="Bringt *Anfänge der Bedrohung durch die Untoten* zu Parqual Fintallas in der Unterstadt zurück.",al={"wohin das buch zurückbringen","parquals ort"}},{q="Wie heißt das Buch?",a="Das Buch heißt *Anfänge der Bedrohung durch die Untoten*.",al={"anfänge-buch","buch über die bedrohung durch die untoten"}}},fp="12,126,17.138.0,23.107.0,27.79.0,24.57.0"}
P.entries["quest:1164"] = {n="Von Dieben stehlen",s="Genavie Callow in der Unterstadt fordert Euch auf, die Familie Dabyrie auf ihrem Hof in Arathi zur Rede zu stellen. Ihr Groll macht aus einem Streit um gestohlene Besitztümer eine Forderung nach Vergeltung.",h="Genavie Callow in der Unterstadt fordert Euch auf, die Familie Dabyrie auf ihrem Hof in Arathi zur Rede zu...",kw={"arathi","dabyrie farmstead","fardel","genavie callow","kenata","marcel dabyrie","refuge point","bei dieben stehlen"},sec={{t="Ein bitterer Groll",b="Genavie Callow sagt, die Seuche habe ihre Familie dahingerafft und der Krieg ihr Anwesen geplündert und niedergebrannt. Sie beschuldigt Kenata und ihre Kinder, die wenigen Besitztümer genommen zu haben, an denen sie noch hing. Nun verlangt sie, dass Ihr ihr die Köpfe von Kenata, Fardel und Marcel Dabyrie vom Dabyrie Farmstead in Arathi bringt."}},faq={{q="Wer bittet um Hilfe?",a="Genavie Callow in der Unterstadt bittet Euch, ihr die Köpfe von Kenata, Fardel und Marcel Dabyrie zu bringen.",al={"wer hat das gegeben","wer will das","genavie"}},{q="Warum ist Genavie den Dabyries böse?",a="Genavie sagt, die Seuche habe ihre Familie dahingerafft, der Krieg habe sie ihr Anwesen gekostet und die Dabyries hätten ihr die verbliebenen Besitztümer gestohlen.",al={"warum ist sie ihnen böse","genavies groll","ärger mit dabyrie"}},{q="Wo liegt Dabyrie Farmstead?",a="Dabyrie Farmstead liegt in Arathi, nordöstlich von Refuge Point.",al={"lage des dabyrie-hofs","wo liegt der hof","hof"}},{q="Wer sind Kenata, Fardel und Marcel Dabyrie?",a="Sie sind die drei Personen, die Genavie in ihrer Forderung nennt: Kenata, Fardel und Marcel Dabyrie.",al={"wer sind die dabyries","kenatas familie","dabyrie-namen"}}},fp="21,179,18.295.0,23.98.0,37.117.0,31.62.0,43.90.0"}
P.entries["quest:1166"] = {n="Oberanführer Mok'Morokks Sorgen",s="Oberanführer Mok'Morokk schickt Euch von Brackenwall nach Süden, um zu holen, was er in der alten Heimat des Clans der Stonemaul zurückgelassen hat. Er will seinen Grog, seinen Schnupftabak und seine Geldkassette zurück.",h="Oberanführer Mok'Morokk schickt Euch von Brackenwall nach Süden, um zu holen, was er in der alten Heimat des...",kw={"brackenwall","der flammenbau","dustwallow","grog","mok'morokk","rexxar","schnupftabak","stonemaul","geldkassette"},sec={{t="Die Geschichte des Oberanführers",b="Mok'Morokk sagt, Rexxar habe ihn zum mächtigen Anführer des Clans der Stonemaul gemacht. Er sagt, er sorge für die Sicherheit seines Volkes. Als große Drachen zur alten Heimat des Clans kamen und Feuer brachten, fand er seinem Volk hier in Dustwallow eine neue Heimat."},{t="Zurückgelassene Dinge",b="Mok'Morokk verließ die alte Heimat in solcher Eile, dass er seinen Grog, seinen Schnupftabak und seine Geldkassette vergaß. Er weist Euch nach Süden zum Flammenbau und zu den Stonemaul Ruinen, sicher, dass seine Sachen dort sind. Er sagt, er sei zu beschäftigt damit, die Oger anzuführen, um selbst hinzugehen."}},faq={{q="Wer ist Oberanführer Mok'Morokk?",a="Oberanführer Mok'Morokk führt den Clan der Stonemaul von Brackenwall aus an. Er sagt, Rexxar habe ihn zu dessen mächtigem Anführer gemacht.",al={"mok'morokk","ogeranführer","wer ist der oberanführer"}},{q="Was geschah mit der alten Heimat des Clans der Stonemaul?",a="Mok'Morokk sagt, große Drachen seien zur alten Heimat des Clans der Stonemaul gekommen und hätten Feuer gebracht. Also fand er dem Clan in Brackenwall eine neue Heimat.",al={"warum gingen die oger fort","stonemaul zerstört","drachen greifen oger an"}},{q="Was will Mok'Morokk zurück?",a="Mok'Morokk will seinen Grog, seinen Schnupftabak und seine Geldkassette zurück. Er vergaß sie, als er die alte Heimat in Eile verließ.",al={"mok'morokks gegenstände","welche sachen will er","grog schnupftabak geldkassette"}},{q="Wo sind Mok'Morokks Habseligkeiten?",a="Mok'Morokk schickt Euch nach Süden, sicher, dass seine Habseligkeiten im Flammenbau und in den Stonemaul Ruinen sind.",al={"wo sind die gegenstände","fundorte der gegenstände","grog und schnupftabak finden"}},{q="Warum holt Mok'Morokk seine Sachen nicht selbst?",a="Mok'Morokk sagt, er sei zu beschäftigt damit, die Oger anzuführen, um seine Sachen selbst zu holen.",al={"warum geht mok'morokk nicht","warum mich schicken"}}},fp="29,163,20.214.0,18.241.0,27.113.0,47.139.0,31.105.0,34.99.0,48.77.0"}
P.entries["quest:1167"] = {n="Der Turm von Althalaxx",s="Bevor Ihr Athrikus Narassin gegenübersteht, schickt Euch Delgren nach Norden, um mit Balthule Schattenhieb zu sprechen. Der Späher hat den Turm von Althalaxx beobachtet und kann Euch sagen, was sich dort verändert hat.",h="Bevor Ihr Athrikus Narassin gegenübersteht, schickt Euch Delgren nach Norden, um mit Balthule Schattenhieb zu...",kw={"althalaxx","athrikus","balthule","kultisten","dunkelküste","delgren","turm"},ang={["class:Paladin"]="Delgren untersucht die Gefahr, bevor er handelt. Das ist die Disziplin, die von einem Krieger des Lichts erwartet wird.",["faction:Alliance"]="Delgren und Balthule arbeiten zusammen, um den Norden Kalimdors zu schützen. Menschliche Paladine und nachtelfische Späher stehen dort Seite an Seite.",["race:NightElf"]="Balthule Schattenhieb verteidigt das Land seiner Ahnen gegen Zauberei. Sie erinnert an die leichtfertigen arkanen Exzesse, die vor zehntausend Jahren die Zivilisation der Nachtelfen zugrunde richteten."},sec={{t="Der Bericht eines Spähers",b="Delgren der Läuterer schickt Euch nach Norden zu Balthule Schattenhieb, seinem Partner von den Schildwachen. Ihr habt verderbte Relikte gereinigt und den Einfluss des Kults entlang der Grenze der Dunkelküste geschwächt. Bevor Ihr Athrikus entgegentretet, will Delgren neue Informationen von Balthule. Die Schildwache hat von den Ruinen aus Wache gehalten, die den Turm überblicken."},{t="Unruhen im Turm",b="Balthule Schattenhieb berichtet von seltsamen Störungen im oberen Sanktum des Turms. Blendende Lichtblitze und qualvolle Schreie erschüttern nun den uralten Elfenturm, während unberechenbare Blitze durch seine Hallen zucken. Die Vorgänge im Inneren drohen den Weg zu Athrikus noch gefährlicher zu machen."}},faq={{q="Warum schickt mich Delgren zurück zu Balthule?",a="Delgren schickt Euch zu Balthule, um neue Informationen einzuholen, bevor Ihr Athrikus entgegentretet. Balthule hat den Turm von Althalaxx beobachtet und kann berichten, was er dort gesehen hat.",al={"warum balthule aufsuchen","mit balthule sprechen","delgrens befehle"}},{q="Wo befindet sich Balthule Schattenhieb?",a="Balthule Schattenhieb unterhält ein Beobachtungslager auf den Hügeln unmittelbar westlich des Turms von Althalaxx. Von dort aus beobachtet er die Ruinen im Norden der Dunkelküste.",al={"balthules standort","balthule finden","wo ist balthule"}},{q="Welche jüngsten Ereignisse hat Balthule am Turm beobachtet?",a="Balthule sah einen blendenden Lichtblitz aus der höchsten Kammer des Turms. Dann hörte er erbärmliche Schreie über die Küste hallen und sah unberechenbare Blitze in den Boden einschlagen.",al={"was geschah am turm","balthule schreie","turm lichtblitz"}},{q="Wer ist Athrikus?",a="Athrikus Narassin ist der dunkle Zauberer, der die Kultisten am Turm von Althalaxx anführt. Delgren und Balthule sind entschlossen, seine unheilvollen Rituale zu unterbinden.",al={"wer ist athrikus","athrikus narassin","turm boss"}},{q="Ist Delgren der Läuterer ein einheimischer Nachtelf?",a="Nein. Delgren ist ein menschlicher Paladin und Krieger des Heiligen Lichts, der an der Grenze zwischen der Dunkelküste und dem Eschental stationiert ist. Er hat sich mit nachtelfischen Spähern zusammengetan, um die dämonische Verderbnis zu tilgen.",al={"wer ist delgren","delgrens volk","ist delgren ein elf"}},{q="Was für eine Ruine ist der Turm von Althalaxx?",a="Der Turm von Althalaxx ist ein uralter Nachtelfenturm an den zerklüfteten Klippen im Norden der Dunkelküste. Er war verlassen, bevor abtrünnige Arkanisten und dämonische Kultisten ihn für verbotene Riten in Besitz nahmen.",al={"althalaxx hintergrund","was ist der turm","turm geschichte"}}},fx={cf915580={q="Warum will Delgren der Läuterer, dass dies erledigt wird?",a="Delgren der Läuterer hat es sich zur Aufgabe gemacht, dunkle, verderbliche Magie und dämonischen Einfluss auszurotten. Die Kultisten, die The Tower of Althalaxx besetzt halten, bedrohen mit ihren finsteren Ritualen die Heiligkeit der Dunkelküste. Delgren will, dass Athrikus aufgehalten wird, bevor der Hexenmeister die Schrecken entfesseln kann, die er gerade vorbereitet, aber er weiß, dass ein rücksichtsloser Angriff ohne Informationen über die neuesten Verteidigungsanlagen des Turms tödlich sein könnte.",al={"delgrens beweggrund","warum kümmert sich delgren darum","delgrens zweck turm"}}},fp="22,181,16.323.0,25.275.1,42.164.0,39.157.0,53.168.0,16.148.0,42.178.0,44.188.0"}
P.entries["quest:1168"] = {n="Armee des schwarzen Großdrachen",s="In Brackenwall trauert Tharg wegen der Armee des schwarzen Großdrachen und dürstet nach Rache. Er wirft Oberanführer Mok'Morokk vor, den Ogern die Flucht befohlen zu haben.",h="In Brackenwall trauert Tharg wegen der Armee des schwarzen Großdrachen und dürstet nach Rache.",kw={"brackenwall","dustwallow","firemane","mok'morokk","rexxar","stonemaul","tharg"},sec={{t="Ein blutiger Groll",b="Schwarze Drachen töteten Thargs Frau und viele Oger. Nachdem Rexxar Mok'Morokk zum Oberanführer gemacht hatte, befahl der neue Anführer den Überlebenden, zu laufen, bis sie Brackenwall erreichten. Tharg sagt, Oger seien schlecht im Weglaufen und sollten stattdessen kämpfen. Er glaubt, Mok'Morokk denke nur an sich selbst, obwohl Mok'Morokk nun allen Ogern befiehlt, zu bleiben und Brackenwall zu beschützen."},{t="Heimat im Süden",b="Tharg nennt die Stonemaul Ruinen seine Heimat und mag den Süden. Brackenwall ist für ihn kein Zuhause. Er will Rache an der Armee des schwarzen Drachen und in die Ruinen zurückkehren, daher bittet er Euch, Firemane Scouts und Firemane Ash Tails in ihren Reihen niederzustrecken."}},faq={{q="Wer ist Tharg?",a="Tharg ist ein Oger, der in Brackenwall lebt. Schwarze Drachen töteten seine Frau, und er sucht Rache und will in die Stonemaul Ruinen zurückkehren.",al={"tharg hintergrundgeschichte","wer ist tharg","tharg dustwallow"}},{q="Warum mag Tharg Oberanführer Mok'Morokk nicht?",a="Rexxar machte Mok'Morokk zum Oberanführer, doch Tharg glaubt, dass ihm mehr an sich selbst liegt als an den Ogern. Als schwarze Drachen viele Oger töteten, befahl Mok'Morokk den Überlebenden zu fliehen. Tharg glaubt, Oger sollten kämpfen.",al={"warum hasst tharg mok morokk","mok'morokk feigling","tharg und mok morokk"}},{q="Was ist mit Thargs Frau geschehen?",a="Schwarze Drachen töteten Thargs Frau und viele andere Oger. Ihr Tod schürt seinen Wunsch nach Rache.",al={"thargs frau","was geschah mit thargs frau","thargs frau tot"}},{q="Wo liegt die alte Heimat der Oger?",a="Tharg nennt die Stonemaul Ruinen seine Heimat und mag den Süden. Brackenwall ist für ihn kein Zuhause, und er will in die Ruinen zurückkehren.",al={"stonemaul ogerheimat","woher kamen die oger","stonemaul ruinen geschichte"}},{q="Welche Feinde bilden die Armee des schwarzen Drachen?",a="Tharg verweist Euch auf die Firemane, darunter Firemane Scouts und Firemane Ash Tails.",al={"firemane drachkin","wen für die armee des schwarzen drachen töten","firemane feinde"}}},fp="24,167,20.374.0,17.252.0,13.136.0,43.211.0,30.100.0,29.138.0,51.87.0"}
P.entries["quest:1169"] = {n="Die Brut identifizieren",s="In Brackenwall sucht Draz'Zilb die Bestie, die die alte Heimat des Clans angegriffen hat. Draz'Zilb sagt, Mok'Morokk klammere sich an die Macht, während Tharg mit Kummer und Rache ringe, und bittet Euch um fünfzehn sengende Zungen und fünfzehn sengende Herzen.",h="In Brackenwall sucht Draz'Zilb die Bestie, die die alte Heimat des Clans angegriffen hat.",kw={"schwarzer drache","brackenwall","draz'zilb","düstermarschen","mok'morokk","sengende herzen","sengende zungen","stonemaul","tharg"},sec={{t="Eine Stimme der Vernunft",b="Draz'Zilb sagt, Mok'Morokk sei von Macht zerfressen, während Tharg mit Kummer und Rachedurst ringe. Nach Draz'Zilbs Ansicht versucht sonst niemand herauszufinden, wer die alte Heimat des Clans angegriffen hat. Der Oger spricht mit Bedacht, obwohl Ihr vielleicht die Worte eines Grobians erwartet hättet."},{t="Herzen und Zungen",b="Draz'Zilb bittet Euch, den Welpen und Schlüpflingen fünfzehn Zungen und fünfzehn Herzen zu entnehmen. Die verbrannten Jungtiere gehören zur schwarzen Drachenarmee, und Draz'Zilb hofft, ihre Überreste werden offenbaren, welche Bestie ihre Jungen in die Heimat der Oger geschickt hat.\n\nWenn die Oger erfahren, mit was für einer Bestie sie es zu tun haben, können sie ihren Feind vielleicht endgültig vernichten und Stonemaul Village aus den Trümmern zurückgewinnen. Draz'Zilb sagt, Mok'Morokk dazu zu bringen, den Sumpf zu verlassen, werde ein großes Unterfangen für sich sein."}},faq={{q="Wer ist Draz'Zilb?",a="Draz'Zilb ist ein Oger in Brackenwall, der sich förmlich ausdrückt, statt wie ein Grobian zu sprechen. Draz'Zilb will herausfinden, wer die alte Heimat des Clans angegriffen hat.",al={"drazzilb","ogermagier brackenwall","kluger oger"}},{q="Was will Draz'Zilb von den Welpen und Schlüpflingen?",a="Draz'Zilb bittet um fünfzehn sengende Zungen und fünfzehn sengende Herzen von den Welpen und Schlüpflingen. Ihre Überreste könnten offenbaren, welche Bestie ihre Jungen in die alte Heimat geschickt hat.",al={"sengende herzen verwendung","warum zungen und herzen","die brut identifizieren zweck"}},{q="Was hält Draz'Zilb von den Anführern des Clans?",a="Draz'Zilb hat wenig Respekt vor Mok'Morokk, den der Oger einen feigen, von Macht zerfressenen Narren nennt. Draz'Zilb sieht Tharg als gefangen in Kummer und Rachedurst.",al={"mokmorokk problem","tharg und mokmorokk","stonemaul anführer"}}},fp="21,244,17.268.0,18.454.0,17.148.0,56.172.0,48.164.0"}
P.entries["quest:117"] = {n="Donnerbräu",s="In Westfall sammelt Schnapsbart Donnerbräu frischen Hopfen für seinen nächsten Sud. Ohne ihn könnte sein Bier dick wie Eintopf werden, also teilt er Fässer mit jenen, die ihm das Nötige bringen.",h="In Westfall sammelt Schnapsbart Donnerbräu frischen Hopfen für seinen nächsten Sud.",kw={"bier","brauen","zwerg","grimbooze","hopfen","fass","lagerbier","thunderbrew","westfall"},ang={["profession:Cooking"]="Als Koch wisst Ihr, dass Gerste, Malz und Hopfen im richtigen Verhältnis stehen müssen, ganz wie die Zutaten der traditionellen zwergischen Braukunst.",["race:Dwarf"]="Als Zwerg freut Ihr Euch vielleicht, einen Verwandten die Brautraditionen von Kharanos im rauen Grenzland von Westfall lebendig halten zu sehen, besonders wenn Fässer im Spiel sind."},sec={{t="Zwergische Leidenschaft in Westfall",b="Fern von Dun Morogh hält Grimbooze die Brautradition seiner Familie lebendig. Er besteht auf dem richtigen Hopfen für seinen aktuellen Sud, sonst könnte daraus dicker Eintopf statt erfrischendem Bier werden."},{t="Die Kunst des Fasses",b="Grimbooze preist Hopfen, Gerste, Hefe und Malz in fröhlichen Reimen. Mit frischem Hopfen kann er die Gärung an Ort und Stelle abschließen. Im Gegenzug teilt er ganze Fässer Donnerbräu-Lagerbier, das für seinen kräftigen Geschmack bekannt ist."}},faq={{q="Wer ist Schnapsbart Donnerbräu?",a="Schnapsbart Donnerbräu ist ein zwergischer Brauer, der durch Westfall zieht. Wo immer er lagert, hält er die Brautradition seines Clans lebendig und singt fröhliche Reime.",al={"grimbooze","wer ist grimbooze","grimboozes geschichte"}},{q="Warum braucht Grimbooze Hopfen?",a="Ohne frischen Hopfen könnte Grimboozes neuester Sud dick und schwer wie Eintopf werden, statt ein spritziges Lagerbier zu ergeben. Hopfen verleiht dem Gebräu Bitterkeit und Ausgewogenheit.",al={"warum hopfen","grimbooze hopfen","wozu dient hopfen"}},{q="Was ist Donnerbräu-Lagerbier?",a="Donnerbräu-Lagerbier ist ein starkes zwergisches Getränk, das von der Familie Thunderbrew gebraut wird. Grimbooze teilt es fassweise aus, und sein kräftiger Geschmack trifft den Gaumen mit voller Wucht.",al={"thunderbrew bier","fass thunderbrew","was ist thunderbrew"}},{q="Könnt Ihr Grimbooze mehr als einmal Hopfen bringen?",a="Ja. Grimbooze freut sich über weiteren Hopfen und bietet dafür weitere Fässer seines Gebräus an.",al={"wiederholbare quest","ist thunderbrew wiederholbar","mehr fässer"}},{q="Wo findet diese Aufgabe statt?",a="Die Arbeit findet in Westfall statt, wo Grimbooze zwischen den Feldern lagert und Vorräte sammelt.",al={"thunderbrew standort","wo ist grimbooze","questgebiet"}},{q="Ist Grimbooze mit den Thunderbrews in Dun Morogh verwandt?",a="Ja. Grimbooze teilt seinen Nachnamen und sein Brauhandwerk mit der Familie Thunderbrew aus Kharanos in Dun Morogh.",al={"brauerei donnerbräu","grimboozes clan","familie thunderbrew"}}},fp="11,173,29.178.0,18.203.0,29.155.0,29.150.0,26.150.0,44.77.0,32.97.0,55.106.0"}
P.entries["quest:1170"] = {n="Die Brut von Onyxia",s="Draz'Zilb fürchtet, Onyxias Brut sei wegen mehr als nur einer Belagerung einiger Oger gekommen.",h="Draz'Zilb fürchtet, Onyxias Brut sei wegen mehr als nur einer Belagerung einiger Oger gekommen.",kw={"brackenwall","deathwing","draz'zilb","düstermarschen","mok'morokk","onyxia","stonemaul"},sec={{t="Eine beunruhigende Präsenz",b="Draz'Zilb berichtet, dass Onyxias Brut in Stonemaul Village eingefallen ist. Onyxia ist Deathwings Tochter, und ihre Ankunft beunruhigt ihn. Er ist sicher, dass die Brut mehr im Sinn hat als eine Belagerung einiger Oger. Also überbringt Ihr Oberanführer Mok'Morokk in Brackenwall die Nachricht, damit er handeln kann."},{t="Nachricht in Brackenwall",b="Oberanführer Mok'Morokk nimmt die Nachricht von der Brut in Stonemaul Village nicht gerne auf. Er mag keine Drachen, weshalb er Brackenwall vorzieht und darauf besteht, dass es hier keine Drachen gibt."}},faq={{q="Wer schickt Euch zu Oberanführer Mok'Morokk?",a="Draz'Zilb schickt Euch zu Oberanführer Mok'Morokk, nachdem Onyxias Brut in Stonemaul Village eingefallen ist.",al={"wer startet die brut von onyxia","die brut von onyxia questgeber"}},{q="Wo ist Oberanführer Mok'Morokk zu finden?",a="Oberanführer Mok'Morokk ist in Brackenwall zu finden.",al={"mok'morokk standort","wo ist mok'morokk","oberanführer mok'morokk dustwallow"}},{q="Warum ist Draz'Zilb wegen Onyxias Brut besorgt?",a="Draz'Zilb fragt sich, warum Deathwings Tochter in diese Lande gekommen ist. Er ist sicher, dass sie wegen mehr als nur einer Belagerung einer kleinen Gruppe von Ogern gekommen ist.",al={"warum interessieren draz'zilb drachen","draz'zilb onyxia sorge"}}},fp="19,82,20.290.0,19.170.1,48.90.0,39.56.0,48.139.0"}
P.entries["quest:1171"] = {n="Die Brut von Onyxia",s="In Brackenwall streitet Oberanführer Mok'Morokk die Existenz der Brut von Onyxia ab. Er sagt, hier seien keine schwarzen Drachen, und schickt Euch mit der Nachricht zurück zu Draz'Zilb, dass die Oger bleiben werden.",h="In Brackenwall streitet Oberanführer Mok'Morokk die Existenz der Brut von Onyxia ab.",kw={"brackenwall","brut von onyxia","draz'zilb","düstermarschen","mok'morokk","rexxar"},sec={{t="Lasst mich in Ruhe",b="Oberanführer Mok'Morokk will in Ruhe gelassen werden, nachdem Draz'Zilb von der Brut von Onyxia berichtet hat. Er sagt, die Oger werden bleiben, wo sie sind, und bestreitet, dass hier irgendein schwarzer Drache sei. Überbringt Draz'Zilb in Brackenwall seine Antwort."},{t="Was Draz'Zilb sagt",b="Draz'Zilb nennt Oberanführer Mok'Morokk einen faulen Feigling und sagt, dass etwas getan werden müsse. Mok'Morokk zeigte Stärke, als Rexxar die Oger anführte. Nachdem Rexxar fortgegangen war, lockte ihn die Macht. Nun verlangt Mok'Morokk von den Ogern, ihm zu dienen, statt sie anzuführen."}},faq={{q="Warum weigert sich Oberanführer Mok'Morokk zu handeln?",a="Oberanführer Mok'Morokk weigert sich zu handeln, weil er sagt, hier gebe es keine schwarzen Drachen, und in Ruhe gelassen werden will. Er schickt Euch los, um Draz'Zilb zu sagen, dass die Oger bleiben werden.",al={"warum hilft mok'morokk nicht","mok'morokks reaktion","warum keine schwarzen drachen"}},{q="Was kommt in der Geschichte davor?",a="Dies folgt auf den früheren Bericht über die Brut von Onyxia, als Draz'Zilb Euch schickte, um Mok'Morokk Nachricht von der Brut zu bringen.",al={"was kommt vor dieser quest","reihenfolge der questreihe"}},{q="Wo spielt sich das ab?",a="Oberanführer Mok'Morokk und Draz'Zilb sind beide in Brackenwall.",al={"wo ist diese quest","ort"}}},fp="19,181,14.226.0,19.250.1,43.167.0,40.122.0,27.66.0"}
P.entries["quest:1172"] = {n="Die Brut von Onyxia",s="Im Süden des Morasts schickt Draz'Zilb Euch gegen Onyxias Eier aus. Keine weiteren ihrer Welpen sollen schlüpfen.",h="Im Süden des Morasts schickt Draz'Zilb Euch gegen Onyxias Eier aus.",kw={"brackenwall","die brut von onyxia","das drachendüster","draz'zilb","mok'morokk","onyxia","stonemaul","der drachensumpf"},sec={{t="Die Eier im Drachensumpf",b="Onyxias Brut liegt über das Drachendüster verstreut. Draz'Zilb drängt Euch nach Süden zum Drachensumpf, wo Onyxia nach Überzeugung des Ogers ihren Hort errichtet und ihre Eier verstreut hat. Drachen nisten im Land um Stonemaul Village und hindern die Oger daran, es zurückzuerobern. Deshalb werdet Ihr ausgesandt, um die Eier zu finden und zu zerstören."},{t="Ein letzter Dienst",b="Wenn die Eier zerstört sind, erklärt Draz'Zilb, dass Onyxia einige Zeit brauchen wird, bevor sie weitere legen kann. Der Oger dankt Euch im Namen des Stonemaul-Klans. Dann bittet Draz'Zilb um einen letzten Dienst. Mok'Morokk ist als Anführer ungeeignet, doch Tharg, der ein hervorragender Anführer wäre, wird durch Verletzungen und Alter zurückgehalten. Vertreibt Mok'Morokk mit Gewalt, und ein neuer Anführer kann den Klan in seine rechtmäßige Heimat im Süden zurückbringen."}},faq={{q="Wer vergibt diese Quest?",a="Draz'Zilb in Brackenwall schickt Euch aus, um Onyxias Eier zu zerstören.",al={"wer vergibt die brut von onyxia","questgeber die brut von onyxia","drazzilb quest"}},{q="Warum müssen die Dracheneier zerstört werden?",a="Draz'Zilb will verhindern, dass weitere Welpen von Onyxia schlüpfen. Solange Drachen im Land um Stonemaul Village nisten, können die Oger es nicht zurückerobern.",al={"warum onyxias eier zerstören","warum eier zerschlagen","stonemaul village dracheneier"}},{q="Wo befinden sich die Eier?",a="Die Eier liegen rund um den Drachensumpf im Süden des Morasts. Draz'Zilb ist sich sicher, dass Onyxia dort ihren Hort errichtet hat.",al={"wo sind onyxias eier","ei von onyxia fundort","wo ist der drachensumpf"}},{q="Wo steht dieser Schritt in der gesamten Questreihe?",a="Dies folgt auf Mok'Morokks Weigerung, auf die Nachricht über die Brut zu reagieren. Ihr habt seine Antwort zu Draz'Zilb zurückgebracht.",al={"die brut von onyxia questreihe","vorherige quest die brut von onyxia","was kommt vor die brut von onyxia drei"}}},fp="19,100,23.299.0,16.401.1,21.68.0,38.140.0,27.99.0,46.104.0"}
P.entries["quest:1173"] = {n="Fordert Oberanführer Mok'Morokk heraus",s="In Brackenwall lacht Oberanführer Mok'Morokk über Eure Herausforderung und schwört, Euch zu zerschmettern. Draz'Zilb hatte erwartet, dass Ihr ihn aus dem Dorf vertreibt.",h="In Brackenwall lacht Oberanführer Mok'Morokk über Eure Herausforderung und schwört, Euch zu zerschmettern.",kw={"brackenwall","oberanführer mok'morokk herausfordern","draz'zilb","düstermarschen","mok'morokk","stonemaul"},sec={{t="Eine Herausforderung an den Oberanführer",b="Nach The Brood of Onyxia tretet Ihr Oberanführer Mok'Morokk gegenüber. Er lacht über Eure Dreistigkeit und verspricht, Euch zu zerschmettern. Dann fordert er Euch auf, Bescheid zu sagen, wenn Ihr bereit für eine Tracht Prügel seid. Draz'Zilb in Brackenwall hatte erwartet, dass Ihr Mok'Morokk aus dem Dorf jagt. Warum seid Ihr nur zum Reden zurückgekehrt?"},{t="Nachricht für Draz'Zilb",b="Draz'Zilb sagt, Mok'Morokk sei wie ein Feigling geflohen, nachdem Ihr den Kampf gewonnen habt. Er dankt Euch für einen großen Dienst. Da Mok'Morokk fort ist, können die Oger einen neuen Anführer wählen, der ihnen hilft, ihre alte Heimat endgültig zurückzuerobern."}},faq={{q="Wen fordert Ihr heraus?",a="Ihr fordert Oberanführer Mok'Morokk in Brackenwall heraus. Er lacht und prahlt damit, dass er Euch zerschmettern wird.",al={"gegen wen kämpfen","ziel der herausforderung","wer ist mok'morokk"}},{q="Was kommt vor dieser Herausforderung?",a="The Brood of Onyxia kommt vor Eurer Herausforderung.",al={"welche quest kommt davor","vorausgesetzte quest","vorherige quest"}},{q="Wem erstattet Ihr nach dem Kampf Bericht?",a="Nach dem Kampf erstattet Ihr Draz'Zilb in Brackenwall Bericht.",al={"bei wem abgeben","abgabe-nsc","wohin nach dem sieg über mok'morokk"}},{q="Was erwartet Draz'Zilb von Euch?",a="Draz'Zilb erwartet, dass Ihr Mok'Morokk aus dem Dorf jagt. Er fragt sich, warum Ihr nur zum Reden zurückgekehrt seid.",al={"warum gegen mok'morokk kämpfen","warum den oberanführer herausfordern","grund für den kampf"}}},fp="29,145,27.288.0,18.208.1,21.102.0,33.48.0,37.64.0,34.101.0"}
P.entries["quest:1174"] = {n="Gnomes Win!",s="In Tausend Nadeln entscheidet der Sieg der Gnome, welches Ticket einen Gewinn bringt. Der Besitzer des Gewinnertickets erhält eine Preisbox.",h="In Tausend Nadeln entscheidet der Sieg der Gnome, welches Ticket einen Gewinn bringt.",kw={"gnom-rennticket","gnom-preisbox","gnome gewinnen","rennen","tausend nadeln"},sec={{t="Das Gnom-Ticket",b="Wenn die Gnome gewinnen, erhält der Besitzer des Gnom-Renntickets die Preisbox. Das Goblin-Ticket zählt für die andere Seite des Rennens."}},faq={{q="Was ist das Gnom-Rennticket?",a="Das Gnom-Rennticket setzt auf die Gnome beim Rennen in Tausend Nadeln. Es zählt, wenn die Gnome gewinnen.",al={"gnom-ticket","was ist das gnom-rennticket","zweck des renntickets"}},{q="Was bekommt Ihr, wenn die Gnome gewinnen?",a="Wer das Gnom-Rennticket besitzt, wenn die Gnome gewinnen, erhält eine Gnom-Preisbox.",al={"gnom-preisbox","preis bei sieg der gnome"}},{q="Wer kann an dieser Wette teilnehmen?",a="Die Wette gehört zu keiner der beiden Fraktionen. Reisende der Allianz und der Horde sind gleichgestellt.",al={"kann die horde wetten","kann die allianz wetten","neutrales ticket"}},{q="Was passiert, wenn stattdessen die Goblins gewinnen?",a="Wenn die Goblins gewinnen, zählt das Goblin-Ticket. Dieses Ergebnis heißt Goblins Win!, das Gegenstück zu diesem hier.",al={"goblins gewinnen","goblin-rennticket"}}},fp="11,122,16.133.0,30.107.0,36.79.0,32.90.0,40.111.0"}
P.entries["quest:1175"] = {n="Eine Straßenunebenheit",s="An der Illusionenrennbahn muss Rennstreckenleiter Zherin die immer größer werdenden Tiere von der Strecke fernhalten. Ihr werdet gebeten, die Zahl der Saltstone Basilisks, Crystalhides und Gazers zu verringern, bevor sie darauf herumwandern.",h="An der Illusionenrennbahn muss Rennstreckenleiter Zherin die immer größer werdenden Tiere von der Strecke...",kw={"crystalhide","gazer","illusionenrennbahn","red thunder","saltstone basilisk","die schimmernde ebene","ruinen von tahonda","rennstreckenleiter zherin","weazels krater"},sec={{t="Die Strecke freihalten",b="Ein Basilisk rammte einst den Rennwagen der Goblins, die Red Thunder. Nach dem Unfall stellte Kronkrider Zherin ein, um die Strecke der Illusionenrennbahn zu beaufsichtigen. Zherin weiß nicht, was die Tiere auf der Schimmernden Ebene fressen. Er weiß nur, dass sie zu groß geworden sind.\n\nIhre Zahl muss gering gehalten werden, bevor sich eines während eines Rennens auf die Strecke verirrt. Wrackteile wegzuräumen ist schon schlimm genug. Zherin möchte nicht auch noch verbrannte Tierteile daraus klauben."}},faq={{q="Wer ist Rennstreckenleiter Zherin?",a="Rennstreckenleiter Zherin kümmert sich um die Strecke der Illusionenrennbahn auf der Schimmernden Ebene. Kronkrider hat ihn für diese Arbeit eingestellt.",al={"wer ist zherin","rennstreckenleiter zherin","zherins geschichte"}},{q="Warum werden die Basilisken gejagt?",a="Die Tiere auf der Ebene sind groß geworden, und eines könnte einen Unfall verursachen, wenn es während eines Rennens auf die Strecke gerät. Ein Basilisk ist bereits mit der Red Thunder der Goblins zusammengestoßen.",al={"warum basilisken töten","warum basilisken sterben müssen","basiliskenproblem"}},{q="Was ist die Red Thunder?",a="Die Red Thunder ist ein Rennwagen der Goblins. Ein Zusammenstoß mit einem Basilisken hat sie zerstört.",al={"red thunder","red thunder unfall","red thunder der goblins"}},{q="Wo sind die Basilisken auf der Ebene gewöhnlich zu finden?",a="Basilisken streifen überall auf der Schimmernden Ebene umher, sammeln sich aber in größerer Zahl bei Weazels Krater und in den Ruinen von Tahonda.",al={"basilisken fundorte","wo sind die basilisken","wo saltstone finden"}}},fp="18,186,23.439.0,26.115.0,35.165.0,24.85.0,51.119.0"}
P.entries["quest:1176"] = {n="Gewicht reduzieren",s="An der Illusionenrennbahn sucht Pozziks Goblincrew leichtere Teile für ihre Rennwagen. Hohle Geierknochen könnten Lenkung und Rahmen verstärken, ohne schweres Metall hinzuzufügen.",h="An der Illusionenrennbahn sucht Pozziks Goblincrew leichtere Teile für ihre Rennwagen.",kw={"knochen","gewicht reduzieren","illusionenrennbahn","pozzik","raketenwagen","die schimmernde ebene","tausend nadeln","geier"},ang={["profession:Engineering"]="Pozziks Einsatz von Vogelknochen zeigt den Erfindungsreichtum der Goblins: praktisch, improvisiert und wirksam, um das Gewicht eines Rennwagens zu senken.",["race:Gnome"]="Ein klassisch ausgebildeter Ingenieur aus Tüftlerstadt wäre womöglich entsetzt, wenn er sähe, wie Goblins aufgelesene Vogelkadaver in Lenkgestänge schnüren."},sec={{t="Jede Unze zählt",b="Auf der Schimmernden Ebene kämpfen Goblin- und Gnomeningenieure um Sekundenbruchteile. Reiner Triebwerksschub bringt wenig, wenn ein Wagen zu viel Gewicht trägt. Gnomenteams bevorzugen ausgeklügelte Zahnräder und Messingbeschläge. Pozziks Goblins entfernen schwere Eisenrahmen und ersetzen sie durch leichtere, hohle Teile, wo immer sie können."},{t="Wüstenfundstücke für mehr Tempo",b="Pozzik sucht in den Salzwüsten rund um Tausend Nadeln, statt teure Verbundwerkstoffe einzuführen. Geier der Salzwüste gibt es reichlich, und ihre Knochen sind hohl, wabenartig, belastbar und leicht. Seine Mechaniker bauen sie in die Lenkgestänge und kleineren Verstrebungen der Rennwagen ein. Sie hoffen, dass die Maschinen die Gnome ausmanövrieren können, ohne bei Höchstgeschwindigkeit auseinanderzubrechen."}},faq={{q="Warum will Pozzik Geierknochen für einen Rennwagen?",a="Gobliningenieure verwenden Geierknochen, weil sie hohl und leicht sind. In filigrane Bauteile wie das Lenkgestänge eingearbeitet, sorgen sie für mehr Stabilität, ohne den Rennwagen zu beschweren.",al={"zweck der geierknochen","warum knochen","pozzik knochen"}},{q="Wer ist Pozzik?",a="Pozzik führt die Goblinrenncrew an der Illusionenrennbahn auf der Schimmernden Ebene. Er leitet die Goblinboxen im Wettstreit mit ihren Gnomenrivalen.",al={"pozzik","pozzik hintergrundgeschichte","wer ist der gobliningenieur"}},{q="Wo findet man diese Geier?",a="Geier kreisen über der offenen Schimmernden Ebene, besonders nahe den riesigen Skelettresten, die über das nordöstliche Salzbecken verstreut liegen.",al={"geier fundort","wo hohle knochen finden","aasfresser der schimmernden ebene"}},{q="Was ist die Illusionenrennbahn?",a="Die Illusionenrennbahn ist ein neutrales Renngelände auf dem ausgetrockneten Salzsee von Tausend Nadeln. Goblins und Gnome fahren dort Rennen mit gefährlichen experimentellen Raketenwagen.",al={"rennbahn hintergrundgeschichte","was ist die illusionenrennbahn","rennstrecke der schimmernden ebene"}},{q="Machen die Gnome dasselbe?",a="Auch die Gnome streben nach leichteren Rennwagen, doch traditionell bevorzugen sie präzise Uhrwerke und komplexe Metalle. Goblinmechaniker setzen stärker auf geborgene Materialien und improvisierte Teile.",al={"gnomenrennwagen","gnom gegen goblin","verwenden gnome knochen"}},{q="Hilft diese Arbeit Pozzik bei seinen weiteren Rennvorhaben?",a="Ja. Wer den Rennwagen leichter macht, gewinnt Pozziks Vertrauen und erhält weitere Arbeit inmitten der Rivalitäten und des Goblinsponsorings auf der Ebene.",al={"questfortsetzung","what comes next","goblinsponsoring"}}},fx={a8fc0189={q="Warum ist Pozzik so darauf fixiert, sein Rennfahrzeug zu erleichtern?",a="Auf der Illusionenrennbahn ist Geschwindigkeit alles, und Rennen werden oft durch winzige Bruchteile eines Vorteils entschieden. Pozzik konkurriert direkt mit der Gnomentechnik, bei der jedes überschüssige Gewicht ihn einen Sieg auf den Salzwüsten kosten kann. Wenn er jedes überflüssige Gramm vom Rahmen und der Lenkvorrichtung entfernt, kann sein Raketenauto die maximale Beschleunigung erreichen, ohne die strukturelle Integrität zu opfern.",al={"pozziks beweggrund","warum rennwagen erleichtern","warum braucht pozzik leichte teile"}},["8208273d"]={q="Warum gibt es so viele Geier in der Schimmernden Ebene?",a="Die Schimmernde Ebene ist eine erbarmungslose, sonnenverbrannte Weite, übersät mit den Überresten gewaltiger uralter Bestien und gefallener Wanderer. Salzfresser gedeihen hier, indem sie über den Köpfen kreisen und sich von den Kadavern ernähren, die das raue Wüstenklima und die gewalttätigen Basilisken- und Skorpidpopulationen der Ebene zurücklassen.",al={"warum gibt es geier in der schimmernden ebene?","geier in den salzeinöden: hintergrund","geier in tausend nadeln"}}},fp="15,168,18.323.0,27.366.0,50.173.0,14.137.0,31.130.0,27.149.0,36.163.0,55.127.0"}
P.entries["quest:1177"] = {n="Hunger!",s="Mudcrush Durtfeet ist in den nördlichen Düstermarschen hungrig und will von Euch etwas zu fressen. Verprügelt die fischigen Mirefin und bringt ihre Köpfe zurück, sonst frisst Mud Euch.",h="Mudcrush Durtfeet ist in den nördlichen Düstermarschen hungrig und will von Euch etwas zu fressen.",kw={"düstermarschen","fischig","hunger!","mirefin köpfe","mudcrush durtfeet","oger"},sec={{t="Ein hungriger Oger",b="Mudcrush Durtfeet, ein Oger namens Mud, bietet einen einfachen Handel an. Verprügelt die fischigen Mirefin und bringt ihm ihre Köpfe als Nahrung. Füttert Mud, sonst frisst er Euch."}},faq={{q="Wer ist Mudcrush Durtfeet?",a="Mudcrush Durtfeet ist ein großer Oger in den nördlichen Düstermarschen und nennt sich Mud. Er ist hungrig und will etwas zu fressen.",al={"mudcrush durtfeet","wer ist mudcrush","oger in den düstermarschen"}},{q="Was will Mudcrush Durtfeet fressen?",a="Mud will die Köpfe der fischigen Mirefin, die Ihr verprügeln sollt.",al={"mudcrush nahrung","was will der oger","hunger quest nahrung"}},{q="Was passiert, wenn Ihr Euch weigert, ihn zu füttern?",a="Mud stellt Euch vor eine klare Wahl: Füttert ihn, sonst frisst er Euch.",al={"mudcrush drohung","frisst mudcrush mich"}}},fp="7,153,13.150.0,25.110.0,40.60.0,39.57.0"}
P.entries["quest:1178"] = {n="Goblin-Sponsoring",s="Die Goblinrennfahrer warten auf ein versprochenes Teil, während die Gnome aufholen. Pozzik schickt Euch nach Ratschet, um Gazlowe zu fragen, was geschehen ist.",h="Die Goblinrennfahrer warten auf ein versprochenes Teil, während die Gnome aufholen.",kw={"treibstoffregler","gazlowe","illusionenrennbahn","pozzik","ratschet","die schimmernde ebene","tinkers' union","undermine"},sec={{t="Ein versprochenes Teil",b="Pozzik nennt das Rennteam den Stolz der Goblins. Viele Leute unterstützen es auf die eine oder andere Weise. Gazlowe sucht auf der ganzen Welt nach Teilen und kam einst vorbei, um an einem seiner Rennwagen zu arbeiten.\n\nVor Wochen versprach Gazlowe einen neuen Prototyp eines Treibstoffreglers, doch er ist nicht eingetroffen. Er ist gewöhnlich pünktlich, also bittet Pozzik Euch, nach Ratschet zu reisen und herauszufinden, was geschehen ist. Die Gnome holen auf."},{t="Worte über Pozzik",b="Bevor Pozzik sich zurückzog, um mit den Rennfahrern zu arbeiten, war er einer der angesehensten Tüftler Undermines, erinnert sich Gazlowe. Seine erste Tat nach dem Beitritt zum Team war der Entwurf seiner zweimotorigen Rennwagenmodelle.\n\nGazlowe räumt ein, dass die Tinkers' Union ohne Pozzik leiden könnte. Dennoch sagt er, dass nichts über die Rennen geht."}},faq={{q="Warum sollt Ihr für Pozzik nach Ratschet reisen?",a="Vor Wochen versprach Gazlowe einen Prototyp eines Treibstoffreglers, doch er ist nicht eingetroffen. Pozzik bittet Euch, nach Ratschet zu reisen und zu fragen, was geschehen ist.",al={"warum ratschet","pozziks auftrag","goblin-sponsoring ziel"}},{q="Was tut Gazlowe für das Rennteam?",a="Gazlowe sucht auf der ganzen Welt nach Teilen für das Team. Er kam einst vorbei, um an einem seiner Rennwagen zu arbeiten.",al={"gazlowes beteiligung","gazlowe rennbahn sponsor","ist gazlowe ein sponsor"}},{q="Was kommt davor?",a="Davor kommt Load Lightening, ebenfalls von Pozzik vergeben.",al={"goblin-sponsoring vorquest","welche quest kommt vor goblin-sponsoring"}},{q="Warum hat es das Goblinteam eilig?",a="Pozzik sagt, dass die Gnome gegenüber dem Goblinteam aufholen.",al={"warum eilt der treibstoffregler","goblins gegen gnome rennen"}}},fp="18,133,15.364.0,18.292.1,42.135.0,41.91.0,23.49.0,34.54.0"}
P.entries["quest:1179"] = {n="Die Brüder Kupferbolz",s="Pilot Langbart in Eisenschmiede sucht einen Reisenden, der den Brüdern Kupferbolz Helme bringt. Ihre Testfahrer bauen auf der Schimmernden Ebene ständig Unfälle mit Raketenwagen, weshalb die Gnome Kopfschutz brauchen.",h="Pilot Langbart in Eisenschmiede sucht einen Reisenden, der den Brüdern Kupferbolz Helme bringt.",kw={"kupferbolz","eisenschmiede","illusionenrennbahn","pilot langbart","raketenwagen","die schimmernde ebene","tausend nadeln","wizzel kupferbolz"},ang={["profession:Engineering"]="Als Ingenieur wisst Ihr zu schätzen, wie dieser Versorgungstransport zwergische Schmiedekunst für schwere Rüstungen mit gnomischen Hochgeschwindigkeitsexperimenten verbindet.",["race:Dwarf"]="Als Zwerg wisst Ihr, dass robuste zwergische Belagerungsmaschinenpanzerung dick genug ist, um einen Zusammenstoß bei Vollgas auf den Salzflächen zu überstehen.",["race:Gnome"]="Als Gnom erkennt Ihr, dass die Brüder Kupferbolz mechanische Innovation höher schätzen als Einzelheiten wie Bremsen und die Lebenserwartung ihrer Fahrer."},sec={{t="Ein Gefallen über weite Entfernung",b="Pilot Langbart, ein zwergischer Flieger in Eisenschmiede, hat eine dringende Bitte von der Schimmernden Ebene im südlichen Kalimdor erhalten. Seine Freunde, die erfinderischen Gnomenbrüder Kupferbolz, haben sich auf ihren gewaltigen Salzflächen niedergelassen, um mit experimentellen Maschinen Rennen zu fahren. Langbarts militärische und fliegerische Pflichten halten ihn auf Trab, weshalb er ihre Vorräte nicht selbst bringen kann."},{t="Sicherheit bei Höchstgeschwindigkeit",b="Der Raketenwagen der Brüder Kupferbolz rast mit außergewöhnlicher Geschwindigkeit über die Salzflächen. Doch seine Testfahrer bauen ständig Unfälle und erleiden schwere Gehirnerschütterungen. Langbart hat eine Kiste mit strapazierfähigen zwergischen Belagerungsmaschinenhelmen zusammengestellt, um sie zu schützen. Ihr bringt die Kiste über das Meer nach Kalimdor und gebt den Gnomen den nötigen Schutz, um zögerliche Piloten wieder hinters Steuer zu bringen."}},faq={{q="Wer ist Pilot Langbart?",a="Pilot Langbart ist ein zwergischer Belagerungsmaschinenpilot in Eisenschmiede. Er ist ein Freund der Brüder Kupferbolz und ihr Versorgungskontakt in den Östlichen Königreichen, wo er schwere zwergische Ausrüstung beschaffen kann, die sie vor Ort nur schwer herstellen können.",al={"pilot langbart","questgeber","wer gibt diese quest"}},{q="Wer sind die Brüder Kupferbolz?",a="Die Brüder Kupferbolz sind ehrgeizige gnomische Ingenieure, darunter Wizzel Kupferbolz. An der Illusionenrennbahn auf der Schimmernden Ebene entwerfen und optimieren sie Raketenwagen, um ihre goblinischen Konkurrenten abzuhängen.",al={"brüder kupferbolz","wizzel kupferbolz","gnomenbrüder"}},{q="Wo liegt die Schimmernde Ebene?",a="Die Schimmernde Ebene ist eine gewaltige, sonnenverbrannte Salzebene im südlichen Kalimdor, jenseits der hohen Felssäulen der Schluchten von Tausend Nadeln. Ihre weite, hindernisfreie Fläche eignet sich zum Testen schneller experimenteller Fahrzeuge.",al={"lage der schimmernden ebene","wo abliefern","wo ist die rennbahn"}},{q="Warum brauchen die Gnome Belagerungsmaschinenhelme?",a="Die Brüder Kupferbolz brauchen Belagerungsmaschinenhelme, weil ihr Raketenwagen extrem schnell ist, sich aber schlecht lenken lässt und wenig Stabilität bietet. Unfälle und Gehirnerschütterungen wurden so häufig, dass kein Testpilot mehr ohne massiven zwergischen Kopfschutz fahren wollte.",al={"warum helme","sturzhelme","raketenwagenunfälle"}},{q="Warum liefert Langbart sie nicht selbst?",a="Pilot Langbart ist mit militärischen Pflichten in Eisenschmiede beschäftigt. Für die lange Reise über das große Meer ins südliche Kalimdor müsste er seinen Posten verlassen, weshalb er Reisende mit dem Transport der schweren Kiste betraut.",al={"warum nicht langbart","langbarts pflichten"}},{q="Können Spieler der Horde diese Aufgabe erledigen?",a="Nein. Pilot Langbart bietet diese Arbeit in Eisenschmiede an, der Hauptstadt der Allianz, weshalb nur Kuriere der Allianz sie übernehmen können. Die Illusionenrennbahn selbst heißt beide Fraktionen willkommen.",al={"nur für die allianz","hordenversion","fraktion"}}},fp="23,196,21.337.0,23.377.0,23.225.0,32.195.0,30.208.0,44.245.0,43.204.0,37.161.0"}
P.entries["quest:118"] = {n="Der Preis für Hufeisen",s="Verner Gutmark hat in Seenhain kein Eisen mehr, und die Wachen brauchen ständig Reparaturen. Er schickt Euch nach Westen durch den Wald von Elwynn, um Schmied Argus in Goldhain um Hufeisen zu bitten.",h="Verner Gutmark hat in Seenhain kein Eisen mehr, und die Wachen brauchen ständig Reparaturen.",kw={"elwynn","goldhain","hufeisen","eisen","seenhain","rotkammgebirge","schmied argus","verner gutmark"},ang={["faction:Alliance"]="Seenhain ist bei der Versorgung auf Goldhain angewiesen, was zeigt, wie sehr die Logistik des Königreichs unter Sturmwinds Regentschaft überlastet ist.",["profession:Blacksmithing"]="Ein Schmied im Grenzland muss knappe Materialien dafür aufwenden, Soldaten am Leben zu halten, sodass wenig für gewöhnliche Bauernhöfe übrig bleibt."},sec={{t="Das Grenzland am Limit",b="Seenhain sieht sich Gnollen, Orcs und Murlocs gegenüber, während Sturmwind kaum Hilfe schickt. Die Garnison kämpft jeden Tag darum, die Stadt zu halten, und die Kämpfe verschleißen ihre Ausrüstung. Verner Gutmark verbringt nahezu jede wache Stunde damit, verbeulte Brustpanzer auszubessern, stumpfe Schwerter neu zu formen und die Wachen in Eisen zu kleiden. Nun sind seine Rohstoffe aufgebraucht."},{t="Versorgungswege nach Elwynn",b="Ohne Eisen kann selbst die alltägliche Arbeit in einer Grenzstadt zum Erliegen kommen. Unbeschlagene Pferde können weder Boten schnell befördern noch Vorräte über die steinigen Pfade des Rotkammgebirges ziehen. Verner schluckt seinen Stolz hinunter und schickt Euch nach Westen über die Straße bei Drei Ecken nach Goldhain. Schmied Argus hat dort regelmäßigen Zugang zu den Erzvorräten des Königreichs."}},faq={{q="Warum hat Verner kein Eisen mehr?",a="Seenhains Wachen sind ständigen Angriffen durch feindselige Wildtiere, Gnolle und Schwarzfelsorcs ausgesetzt. Verner hat sein Eisen für die Reparatur ihrer ramponierten Rüstungen und Waffen verbraucht, sodass nichts für den zivilen Bedarf übrig bleibt.",al={"warum kein eisen","verner ohne metall","eisenmangel in seenhain"}},{q="Wer ist Schmied Argus?",a="Schmied Argus ist der Schmied in Goldhain im Wald von Elwynn. Seine Schmiede hat leichteren Zugang zu Rohmetallbarren und Vorräten als Grenzstädte wie Seenhain.",al={"argus goldhain","wer ist argus","schmied in goldhain"}},{q="Warum erhält Seenhain zu wenig Vorräte aus Sturmwind?",a="Sturmwinds Herrscher verharren in politischer Untätigkeit, während König Varian Wrynn vermisst wird. Das House of Nobles hält Truppen und Gelder zurück, sodass Grenzstädte wie Seenhain mit dem regionalen Handel auskommen müssen, den sie aufrechterhalten können.",al={"warum keine hilfe aus sturmwind","seenhain ignoriert","vernachlässigung durch sturmwind"}},{q="Warum sind Hufeisen im Rotkammgebirge so wichtig?",a="Das felsige Gelände des Rotkammgebirges nutzt unbeschlagene Hufe schnell ab. Ohne Hufeisen können die Pferde der Kuriere, Versorgungswagen und Patrouillen lahm werden und Seenhain so vom Rest des Königreichs abschneiden.",al={"warum hufeisen nötig","warum hufeisen wichtig sind"}},{q="Was geschieht, nachdem Ihr Schmied Argus erreicht habt?",a="Argus nimmt Verners Notiz entgegen und gibt Euch Hufeisen, die Ihr nach Seenhain zurückbringen sollt. Der Kampf der Stadt ums Durchhalten geht weiter.",al={"nächste quest","was kommt nach argus"}},{q="Wo in Goldhain befindet sich Schmied Argus?",a="Schmied Argus arbeitet an der Schmiede unter freiem Himmel nahe dem Gasthaus \"Zur Höhle des Löwen\" in Goldhain, unweit der Hauptstraße durch den Wald von Elwynn.",al={"wo ist argus","argus standort"}}},fx={["24418d93"]={q="Warum schickt Verner Euch, anstatt selbst zu gehen oder eine Wache zu schicken?",a="Verner ist der Hauptschmied von Seenhain und kann seine Esse nicht verlassen, während die Verteidigung der Stadt bis zum Äußersten angespannt ist. Rotkammgebirge wird bereits von Gnollen und Orcs belagert, weshalb jede örtliche Wache auf den Wällen und entlang der Brücke gebraucht wird. Da die lokalen Versorgungswege völlig überlastet sind, fällt die Reise durch den Wald von Elwynn an fähige reisende Abenteurer wie Euch.",al={"warum schickt man mich","warum geht verner nicht selbst","warum keine wache schicken"}}},fp="18,170,32.336.0,22.319.0,26.195.0,19.155.0,48.244.0,43.186.0,40.123.0,42.114.0"}
P.entries["quest:1180"] = {n="Goblin-Sponsoring",s="Gazlowe in Ratschet wartet noch immer auf den Treibstoffregler, den er Pozzik versprochen hat. Revilgaz in Beutebucht sagte, er würde ihn verschicken, doch er ist nicht angekommen. Deshalb schickt Gazlowe Euch zu Werftmeister Lozgil am äußersten nordwestlichen Ende der Docks von Beutebucht, um die Frachtaufzeichnungen zu prüfen.",h="Gazlowe in Ratschet wartet noch immer auf den Treibstoffregler, den er Pozzik versprochen hat.",kw={"beutebucht","treibstoffregler","gazlowe","goblin-sponsoring","illusionenrennbahn","pozzik","ratschet","revilgaz","werftmeister lozgil"},sec={{t="Ein nie angekommenes Teil",b="Gazlowe hat Pozzik einen neuen Treibstoffregler versprochen, doch er ist nicht in Ratschet angekommen. Revilgaz in Beutebucht sagte, er würde ihn herüberschicken. Vielleicht ist das Teil in Vergessenheit geraten. Falls es nie verschickt wurde, lässt sich womöglich wenig tun. Dennoch könnt Ihr herausfinden, ob es Beutebucht verlassen hat. Werftmeister Lozgil am äußersten nordwestlichen Ende der Docks kann die Frachtaufzeichnungen durchsehen."},{t="Die Aufzeichnungen des Werftmeisters",b="Werftmeister Lozgil prüft die Logbücher auf Lieferungen nach Ratschet. Der jüngste Eintrag verzeichnet Stiefel von Drizzlik. Frühere Lieferungen enthielten Baumaterialien und Werkzeuge. In den Aufzeichnungen tauchen keine Rennteile auf."}},faq={{q="Welches Teil fehlt?",a="Gazlowe hat Pozzik einen neuen Treibstoffregler versprochen, doch er ist nicht bei Gazlowe in Ratschet angekommen.",al={"pozzik teil","warum treibstoffregler","pozzik lieferung"}},{q="Wer sagte, er würde den Regler nach Ratschet schicken?",a="Revilgaz in Beutebucht sagte, er würde den Regler an Gazlowe in Ratschet schicken.",al={"wer schickt das teil","revilgaz teil","wer hat den treibstoffregler"}},{q="Wer führt die Versandaufzeichnungen in Beutebucht?",a="Werftmeister Lozgil führt die Versandaufzeichnungen in Beutebucht. Er befindet sich am äußersten nordwestlichen Ende der Docks von Beutebucht.",al={"beutebucht frachtmeister","wer ist werftmeister lozgil","wo ist lozgil"}},{q="Wo gehört dieser Schritt in die Questreihe?",a="Dies folgt auf das erste Goblin-Sponsoring, bei dem Pozzik Euch zu Gazlowe geschickt hat. Der nächste Schritt ist Goblin-Sponsoring drei.",al={"goblin-sponsoring questreihe","questfortschritt","was kommt davor"}}},fp="18,264,22.364.0,25.197.1,21.88.0,50.77.0,44.117.0,38.114.0"}
P.entries["quest:1181"] = {n="Goblin-Sponsoring",s="An der Illusionenrennbahn brauchen die Goblinrennfahrer noch immer ihren fehlenden Treibstoffregler. Werftmeister Lozgil schickt Euch zu Baron Revilgaz in Beutebucht, um Hilfe zu erhalten.",h="An der Illusionenrennbahn brauchen die Goblinrennfahrer noch immer ihren fehlenden Treibstoffregler.",kw={"baron revilgaz","beutebucht","treibstoffregler","goblin-sponsoring","illusionenrennbahn","ratschet","werftmeister lozgil"},sec={{t="Den Baron fragen",b="Werftmeister Lozgil kann kaum mehr tun, um die fehlende, für Ratschet bestimmte Lieferung aufzuspüren. Er schickt Euch zu Baron Revilgaz, da der Baron seine eigenen Geschäfte am besten kennt. Ihr findet ihn im obersten Stockwerk der Taverne auf der anderen Seite des Hafens in Beutebucht."},{t="Die Antwort des Barons",b="Baron Revilgaz weiß von dem fehlenden Treibstoffregler, kann aber nicht helfen. Einige seiner Männer machten sich auf die Suche nach dessen Bauplänen und kehrten mit leeren Händen zurück."}},faq={{q="Wo kann ich Baron Revilgaz finden?",a="Baron Revilgaz befindet sich im obersten Stockwerk der Taverne auf der anderen Seite des Hafens in Beutebucht.",al={"baron revilgaz standort","wo ist revilgaz","revilgaz in beutebucht finden"}},{q="Warum schickt Euch Werftmeister Lozgil zu Revilgaz?",a="Werftmeister Lozgil kann kaum noch weiterhelfen und sagt, der Baron kenne seine eigenen Geschäfte am besten.",al={"warum mit revilgaz sprechen","lozgil schickt zum baron","warum baron revilgaz aufsuchen"}},{q="Nach welcher Lieferung wird gesucht?",a="Die Lieferung ist ein neuer Treibstoffregler für die Goblinrennfahrer der Illusionenrennbahn, der für Ratschet bestimmt ist.",al={"welche lieferung fehlt","wonach suchen wir","fehlende fracht für ratschet"}},{q="Wo steht dieser Schritt in der Questreihe?",a="Dies folgt auf Euer Gespräch mit Werftmeister Lozgil in Goblin-Sponsoring zwei. Der nächste Schritt ist Goblin-Sponsoring vier.",al={"was kam vor goblin-sponsoring 3","fortschritt der questreihe goblin-sponsoring"}}},fp="18,151,16.244.0,18.141.1,32.80.0,49.94.0,36.100.0,38.115.0"}
P.entries["quest:1182"] = {n="Goblin-Sponsoring",s="Baron Revilgaz sucht für Pozzik die neuen Treibstoffreglerpläne der Venture Company am Nazferitisee. Foreman Cozzle hat ihn überlistet, also schickt der Baron Euch los, um die Blaupausen zu holen.",h="Baron Revilgaz sucht für Pozzik die neuen Treibstoffreglerpläne der Venture Company am Nazferitisee.",kw={"baron revilgaz","blaupausen","foreman cozzle","treibstoffregler","goblin-sponsoring","der nazferitisee","illusionenrennbahn","pozzik","venture company"},ang={["class:Rogue"]="Als Schurke könnt Ihr das Schloss der Blaupausenkiste ohne Cozzles Schlüssel knacken."},sec={{t="Die Blaupausen des Vorarbeiters",b="Baron Revilgaz sagt, die Schredder der Venture Company am Nazferitisee im nördlichen Schlingendorntal hätten ein neues Treibstoffreglermodell. Pozzik könnte die Einzelheiten gebrauchen, doch Foreman Cozzle hat sich als gewitzter erwiesen, als der Baron erwartet hatte. Deshalb glaubt Revilgaz, dass Ihr bei der Suche nach den Plänen mehr Glück haben könntet.\n\nDie Blaupausen werden in Cozzles Haus aufbewahrt, mit ziemlicher Sicherheit unter Verschluss. Der Stützpunkt der Venture Company liegt rund um den Nazferitisee, im Nordosten des Tals. Cozzle bewahrt den Schlüssel in seiner Hütte oben auf dem Ölturm auf. Die Kiste mit den Blaupausen steht im kleinen Haus nahe dem Fuß des Turms. Revilgaz räumt ein, dass das Gnomenteam dort gut ist und sein Team jeden Vorteil braucht, den es finden kann."},{t="Eine Kopie für den Baron",b="Revilgaz will eine Kopie der Blaupausen für seine eigenen Unterlagen. Dann schickt er Euch zu Pozzik, damit der Goblin nicht glaubt, einer seiner Sponsoren hätte ihn im Stich gelassen."}},faq={{q="Warum will Baron Revilgaz die Treibstoffreglerblaupausen?",a="Die Schredder der Venture Company am Nazferitisee haben ein neues Treibstoffreglermodell. Revilgaz glaubt, dass Pozzik die Einzelheiten gebrauchen könnte.",al={"warum blaupausen stehlen","warum treibstoffregler","revilgaz beweggrund"}},{q="Wo werden die Blaupausen aufbewahrt?",a="Die Blaupausen liegen in einer Kiste im kleinen Haus am Fuß des Ölturms, im Stützpunkt der Venture Company am Nazferitisee im nördlichen Schlingendorntal.",al={"wo sind die blaupausen","treibstoffreglerblaupausen fundort","cozzles haus"}},{q="Wer hat den Schlüssel?",a="Foreman Cozzle trägt den Schlüssel bei sich und arbeitet in der Hütte oben auf dem Ölturm.",al={"cozzles schlüssel","wo ist der schlüssel","wie die truhe öffnen"}},{q="Wo steht dieser Schritt in der Questreihe?",a="Werftmeister Lozgil hat Euch im vorherigen Schritt, Goblin-Sponsoring Nummer drei, zu Baron Revilgaz geschickt. Als Nächstes folgt Goblin-Sponsoring Nummer fünf.",al={"was kommt davor","welche quest kommt als nächstes","goblin-sponsoring questreihe"}}},fp="18,184,24.688.0,20.155.1,55.136.0,30.155.0,18.73.0,38.143.0"}
P.entries["quest:1183"] = {n="Goblin-Sponsoring",s="Auf der Schimmernden Ebene erreichen Baron Revilgaz' Grüße Pozzik zusammen mit den Treibstoffreglerblaupausen. Der Baron lädt Pozzik ein, um alles zu bitten, was er braucht.",h="Auf der Schimmernden Ebene erreichen Baron Revilgaz' Grüße Pozzik zusammen mit den Treibstoffreglerblaupausen.",kw={"baron revilgaz","treibstoffreglerblaupausen","goblin-sponsoring","illusionenrennbahn","pozzik","die schimmernde ebene","tausend nadeln"},sec={{t="Grüße für Pozzik",b="Baron Revilgaz schickt Euch mit den Treibstoffreglerblaupausen und seinen Grüßen für Pozzik auf die Schimmernde Ebene. Der Baron sagt, Pozzik solle fragen, falls er jemals etwas braucht. Revilgaz wartet auf die Nachricht, dass Pozzik den Streckenrekord bricht."},{t="Den Entwurf verbessern",b="Pozzik hatte gehofft, der Regler wäre bereits zusammengebaut. Stattdessen sieht er eine Chance, dessen Entwurf von Grund auf zu verbessern. Er plant, neue Schemata zu zeichnen, das Bauteil anzufertigen und es bald einbauen zu lassen."}},faq={{q="Wer schickt Euch mit den Blaupausen los?",a="Baron Revilgaz schickt Euch mit seinen Grüßen für Pozzik von Beutebucht aus los.",al={"wer vergibt goblin-sponsoring 5","questgeber","revilgaz quest"}},{q="Wer erhält die Treibstoffreglerblaupausen?",a="Pozzik erhält die Treibstoffreglerblaupausen auf der Schimmernden Ebene.",al={"wohin die blaupausen bringen","wer bekommt die schemata","pozzik standort"}},{q="Was hofft Baron Revilgaz zu hören?",a="Baron Revilgaz wartet auf die Nachricht, dass Pozzik den Streckenrekord bricht.",al={"revilgaz beweggründe","baron revilgaz sponsor"}},{q="Was kommt vor dieser Lieferung?",a="Vor dieser Lieferung habt Ihr die Blaupausen für Revilgaz geholt. Der nächste Schritt ist The Eighteenth Pilot.",al={"vorherige quest","was führte dazu","goblin-sponsoring questreihe"}}},fp="18,153,18.231.0,20.204.1,34.68.0,43.70.0,38.66.0,32.101.0"}
P.entries["quest:1184"] = {n="Teile des Schwarms",s="Aus Tausend Nadeln schickt Korran Nachricht nach Orgrimmar über Moktar und seine Studien.",h="Aus Tausend Nadeln schickt Korran Nachricht nach Orgrimmar über Moktar und seine Studien.",kw={"belgrom rockmaul","korran","moktar","orgrimmar","teile des schwarms","rustmaul digsite","silithid","tausend nadeln"},sec={{t="Nachricht für Orgrimmar",b="Korran schickt Euch mit einer Nachricht aus Tausend Nadeln zu Belgrom Rockmaul in Orgrimmar. Die rissigen Panzer stammen von silithid an der Rustmaul Digsite. Sagt Belgrom, dass Moktar seine Aufträge gut erfüllt und Korrans Studien voranschreiten. Korran hofft, bald mehr zu erfahren."},{t="Belgroms Antwort",b="Belgrom Rockmaul dankt Euch und sagt, der Kriegshäuptling werde sich freuen, von Eurer Hartnäckigkeit zu hören. Er verspricht, Euren Namen zu erwähnen. Thrall spricht oft mit Belgrom und schätzt seine Meinung. Belgrom hält die silithid für eine ernste Bedrohung und will davon hören, wenn Korran mehr über sie erfährt."}},faq={{q="Wer schickt Euch nach Orgrimmar?",a="Korran, der die silithid erforscht, bittet Euch, Belgrom Rockmaul in Orgrimmar eine Nachricht zu überbringen.",al={"questgeber","wer beginnt das","wer gab teile des schwarms"}},{q="Wem sollt Ihr die Nachricht überbringen?",a="Belgrom Rockmaul in Orgrimmar.",al={"wen aufsuchen","wohin führt das","belgrom rockmaul standort"}},{q="Welche Nachricht möchte Korran überbringen lassen?",a="Sagt Belgrom, dass Moktar seine Aufträge in Tausend Nadeln gut erfüllt und Korrans Studien voranschreiten. Korran hofft, bald mehr zu erfahren.",al={"was lautet die nachricht","korrans bericht"}},{q="Was sind das für Kreaturen, die Korran erforscht?",a="Es sind silithid. Die rissigen Panzer, mit denen diese Arbeit begann, stammen von silithid an der Rustmaul Digsite in Tausend Nadeln.",al={"was sind das für kreaturen","warum den schwarm erforschen"}}},fp="18,83,18.275.0,15.280.1,27.90.0,47.31.0,40.146.0,42.125.0"}
P.entries["quest:1186"] = {n="Der achtzehnte Rennfahrer",s="Auf der Schimmernden Ebene schickt Pozzik Euch zu Razzeric, während er an den Flitzern arbeitet. Razzeric ist der achtzehnte Pilot des Teams und nimmt gerne Modifikationen an den Flitzern vor.",h="Auf der Schimmernden Ebene schickt Pozzik Euch zu Razzeric, während er an den Flitzern arbeitet.",kw={"goblin","pilot","pozzik","rennstrecke","razzeric","die schimmernde ebene","tausend nadeln"},sec={{t="Lernt den Piloten kennen",b="Pozzik passt einen neuen Treibstoffregler in die Konstruktionen der Flitzer ein. Er schickt Euch zu Razzeric auf der Schimmernden Ebene, dem achtzehnten Piloten des Teams. Razzeric nimmt gerne Modifikationen an den Flitzern vor. Pozzik sagt, dass er nicht ganz richtig im Kopf ist, also versucht, nicht allzu überrascht zu wirken."},{t="Ein Pilot erinnert sich",b="Razzeric weiß, dass Ihr Pozzik geholfen habt. Er erinnert sich daran, wie er im Boxenbereich herumrannte und bei jeder Arbeit mit anpackte, an die ihn die Mechaniker heranließen. Jetzt ist er der außergewöhnliche Pilot des Goblin-Rennteams."}},faq={{q="Wer ist Razzeric?",a="Razzeric ist ein Goblin, der als Pilot für das Goblin-Rennteam auf der Schimmernden Ebene fährt. Pozzik nennt ihn den achtzehnten Piloten des Teams.",al={"wer ist der achtzehnte pilot","razzeric hintergrundgeschichte","goblinpilot"}},{q="Warum schickt Pozzik Euch zu Razzeric?",a="Pozzik passt einen neuen Treibstoffregler in die Konstruktionen der Flitzer ein, also schickt er Euch zu Razzeric, um mit ihm zu sprechen und dem Team weiterzuhelfen.",al={"warum mit razzeric sprechen","pozzik achtzehnter pilot"}},{q="Wie ist Razzeric so?",a="Pozzik sagt, dass Razzeric gerne kleine Änderungen an den Flitzern vornimmt und nicht ganz richtig im Kopf ist.",al={"razzeric persönlichkeit","ist razzeric verrückt"}},{q="Was geschah zuvor?",a="Zuvor habt Ihr Pozzik in Goblin Sponsorship die Treibstoffreglerblaupausen gebracht.",al={"achtzehnter pilot voraussetzung","questreihe vor razzeric"}}},fp="20,165,14.255.0,17.197.1,16.125.0,37.128.0,22.94.0,22.89.0"}
P.entries["quest:1187"] = {n="Razzerics Basteln",s="Auf der Schimmernden Ebene verleiht Razzerics Basteln Rennwagen mehr Leistung, sobald Pozzik mit ihnen fertig ist. Ein bei Shreev in Gadgetzan bestellter Seaforium-Booster wurde per Zeppelin transportiert, der laut Razzeric in den Düstermarschen abgestürzt ist. Er will den Booster zurückhaben.",h="Auf der Schimmernden Ebene verleiht Razzerics Basteln Rennwagen mehr Leistung, sobald Pozzik mit ihnen fertig...",kw={"düstermarschen","gadgetzan","gizmorium","pozzik","razzeric","seaforium-booster","die schimmernde ebene","shreev","tausend nadeln"},sec={{t="Mehr Schub",b="Pozzik ist ein guter Mechaniker, sagt Razzeric, aber zu vorsichtig mit der Feuerkraft und allzu bereit, sich zurückzuhalten. Sobald Pozzik mit einem Rennwagen fertig ist, lockert Razzeric dessen Steuerung, entfernt Teile des Rahmens und erhöht die Leistung. Er hat bei Shreev im Gizmorium in Gadgetzan einen Seaforium-Booster bestellt. Razzeric sagt, der Zeppelin mit dem Booster sei in den Düstermarschen abgestürzt. Der Booster gehört zurück auf die Schimmernde Ebene. Ohne diesen zusätzlichen Kick auf der Rennstrecke anzutreten, wäre eine Farce."},{t="Am Rennwagen festgeschnallt",b="Razzeric schwärmt von dem Booster, der ganze fünfzehn Pfund Seaforium enthält. An der Seite eines Rennwagens festgeschnallt, sollte er ihn so schnell durch den Rundkurs tragen, dass er die Gnome gleich zweimal schlägt."}},faq={{q="Wer ist Razzeric?",a="Razzeric fährt auf der Schimmernden Ebene Rennen und verändert die Rennwagen selbst, nachdem Pozzik mit ihnen fertig ist.",al={"razzeric","wer vergibt razzerics basteln","razzeric schimmernde ebene"}},{q="Woher stammt der Booster?",a="Razzeric hat den Booster bei Shreev im Gizmorium in Gadgetzan bestellt.",al={"woher stammt der booster","wer hat den seaforium-booster gebaut","gadgetzan gizmorium"}},{q="Wo ist der Seaforium-Booster jetzt?",a="Razzeric sagt, der Zeppelin mit dem Booster sei in den Düstermarschen abgestürzt.",al={"wo ist der seaforium-booster","fundort des boosters","absturzort des zeppelins"}},{q="Warum will Razzeric den Booster?",a="Razzeric will mehr Leistung, als Pozzik einzubauen bereit ist, und hält es für eine Farce, ohne diesen zusätzlichen Kick auf der Rennstrecke anzutreten.",al={"warum will er seaforium","warum seaforium-booster"}},{q="Was kam vor diesem Schritt?",a="The Eighteenth Pilot kam zuerst.",al={"vorherige quest","voraussetzung","was führt zu razzerics basteln"}}},fp="19,258,10.465.0,21.188.1,16.98.0,32.71.0,35.76.0,35.130.0,27.32.0"}
P.entries["quest:1188"] = {n="Sicherheit zuerst",s="Razzeric schickt Euch mit einem seaforium booster nach Süden zu Shreev in Gadgetzan. Seine Sicherung ist noch aktiv, obwohl Razzeric darum gebeten hatte, sie zu entfernen.",h="Razzeric schickt Euch mit einem seaforium booster nach Süden zu Shreev in Gadgetzan.",kw={"gadgetzan gizmorium","razzeric","sicherheit zuerst","seaforium booster","die schimmernde ebene","shreev","tanaris"},sec={{t="Eine ungewollte Sicherung",b="Razzeric stellt fest, dass die Sicherung an seinem seaforium booster noch aktiv ist. Sie begrenzt die Leistung des Boosters, obwohl er Shreev gebeten hatte, sie zu entfernen. Also gibt er Euch den Booster und schickt Euch südlich der Schimmernden Ebene in die Wüste von Tanaris. Shreev kann die Sicherung im Gadgetzan Gizmorium entfernen."},{t="Shreevs Antwort",b="Im Gizmorium bestreitet Shreev, eine Sicherungssperre am Booster angebracht zu haben. Er sagt, dieser bestehe fast ausschließlich aus seaforium explosive und sei bereits so verändert worden, dass beim Einsatz mehr seiner Sprengladung freigesetzt wird. Razzeric, so Shreev, sei nie zufrieden, wenn er nicht bis auf elf aufdrehe."}},faq={{q="Wer schickt Euch nach Gadgetzan?",a="Razzeric, der Goblinpilot, schickt Euch mit seinem seaforium booster nach Gadgetzan.",al={"questgeber","wer startet sicherheit zuerst","razzerics quest"}},{q="Warum ist Razzeric mit dem Booster unzufrieden?",a="Die Sicherung, die Shreev am Booster gelassen hat, begrenzt dessen Leistung, obwohl Razzeric darum gebeten hatte, sie zu entfernen.",al={"warum beschwert sich razzeric","problem mit dem booster","was stimmt mit dem booster nicht"}},{q="Wo ist Shreev zu finden?",a="Shreev ist im Gizmorium in Gadgetzan, in der Wüste von Tanaris südlich der Schimmernden Ebene.",al={"shreevs standort","wo ist shreev","standort des gadgetzan gizmorium"}},{q="Welchen Gegenstand bringt Ihr nach Gadgetzan?",a="Ihr tragt Razzerics seaforium booster, den er Euch gibt, damit Ihr ihn zu Shreev bringt.",al={"welcher gegenstand","booster-gegenstand","was wird zu shreev gebracht"}},{q="Was folgt auf diese Lieferung?",a="Es folgt ein zweiter Teil der Questreihe, der ebenfalls Sicherheit zuerst heißt.",al={"nächste quest","was folgt auf sicherheit zuerst","sicherheit zuerst fortsetzung"}}},fp="12,149,22.298.0,15.256.1,27.78.0,41.99.0,26.93.0,40.78.0,31.61.0"}
P.entries["quest:1189"] = {n="Sicherheit zuerst",s="Auf der Schimmernden Ebene bringt Ihr Shreevs modifizierten Seaforium-Booster zurück zu Razzeric. Shreev warnt, dass ein Ausrutscher beim Zünden von Razzeric nur einen Brandfleck auf der Rennstrecke übrig lassen könnte.",h="Auf der Schimmernden Ebene bringt Ihr Shreevs modifizierten Seaforium-Booster zurück zu Razzeric.",kw={"gadgetzan","pozzik","razzeric","sicherheit zuerst","seaforium-booster","die schimmernde ebene","shreev","tausend nadeln"},sec={{t="Eine Warnung von Shreev",b="Shreev übergibt Euch den modifizierten Booster, vorbereitet nach Razzerics Wünschen. Er warnt, dass Razzeric beim Zünden vorsichtig sein muss. Ein Ausrutscher, und Razzeric wird zum Brandfleck auf der Rennstrecke, statt nach vorne zu rasen. Shreev sagt, das wäre schade. Dann fragt er sich, ob der neunzehnte Fahrer wohl etwas getaugt hätte."},{t="Sand unter dem Sitz",b="Zurück auf der Schimmernden Ebene murrt Razzeric, dass Pozzik einen Eimer Sand auf seinen Flitzer geladen hat. Wie soll er mit Sand unter dem Sitz die Höchstgeschwindigkeit erreichen?"},{t="Der Booster ist zurück",b="Razzeric freut sich über den modifizierten Booster. Er wünscht sich, er könnte die Gesichter der Gnome sehen, wenn er ihn zündet. Doch er rechnet damit, zu sehr damit beschäftigt zu sein, einen neuen Streckenrekord aufzustellen."}},faq={{q="Wer schickt den modifizierten Booster zurück auf die Ebene?",a="In Gadgetzan stellt Shreev die Änderungen am Seaforium-Booster nach Razzerics Wünschen fertig. Dann gibt er ihn Euch, damit Ihr ihn zu Razzeric auf der Schimmernden Ebene zurückbringt.",al={"wer vergibt sicherheit zuerst 2","shreev questgeber","wer modifiziert den booster"}},{q="Wovor warnt Shreev?",a="Shreev warnt Razzeric, beim Zünden des Boosters vorsichtig zu sein. Ein Ausrutscher, und Razzeric wird zum Brandfleck auf der Rennstrecke, statt nach vorne zu rasen.",al={"ist der booster gefährlich","shreevs warnung","booster risiko"}},{q="Warum ärgert sich Razzeric über sein Fahrzeug?",a="Pozzik hat einen Eimer Sand auf Razzerics Flitzer geladen. Razzeric fragt sich, wie er mit Sand unter dem Sitz die Höchstgeschwindigkeit erreichen soll.",al={"warum ist razzeric wütend","pozzik eimer sand","razzerics beschwerde"}}},fp="12,187,21.315.0,19.154.0,20.169.1,49.156.0,28.147.0,40.127.0"}
P.entries["quest:119"] = {n="Zurück zu Verner",s="Schmied Argus hat fünfzig Hufeisen fertiggestellt, und Ihr bringt sie von Goldhain zu Verner Gutmark in Seenhain. Das Rotkammgebirge braucht sie für seine schwer beanspruchten Reittiere.",h="Schmied Argus hat fünfzig Hufeisen fertiggestellt, und Ihr bringt sie von Goldhain zu Verner Gutmark in...",kw={"kiste mit hufeisen","wald von elwynn","goldhain","seenhain","rotkammgebirge","schmied argus","the price of shoes","verner gutmark"},ang={["faction:Alliance"]="Als Mitglied der Allianz helft Ihr, abgelegene Siedlungen wie Seenhain durch Versorgungslinien zwischen dem Wald von Elwynn und dem Rotkammgebirge mit dem Herzen des Königreichs zu verbinden.",["profession:Blacksmithing"]="Als Schmied wisst Ihr, dass Reittiere im Grenzland stetigen Nachschub an Hufeisen brauchen, wenn die örtlichen Schmieden durch den Krieg überlastet sind."},sec={{t="Ein Bote über die Grenze",b="Ihr tragt die Kiste nach Osten über die Grenze ins Rotkammgebirge. Dort bedrohen Versorgungsengpässe und Gnollangriffe die Stadt. Die fünfzig eisernen Hufeisen halten Pferde und Zugtiere auf unwegsamen Bergstraßen einsatzfähig, die das Rotkammgebirge braucht, um diesen Gefahren zu begegnen."},{t="Der Zettel an der Kiste",b="Verner Gutmark ist erleichtert, als die Hufeisen eintreffen. Dann findet er die Rechnung, die Schmied Argus an der Kiste befestigt hat. Verner ärgert sich darüber, dass der Schmied aus Goldhain Bezahlung erwartet. Angesichts der Gefahren, die das Rotkammgebirge bedrängen, bleibt wenig Zeit, über den Rechnungsbetrag zu streiten."}},faq={{q="Wohin bringe ich die Kiste mit Hufeisen?",a="Bringt die Kiste zu Verner Gutmark in Seenhain im Rotkammgebirge, gleich östlich der Brücke und der Anlegestellen am See.",al={"wo ist verner","abgabeort","wer bekommt die hufeisen"}},{q="Wer hat diese Lieferung zurück ins Rotkammgebirge geschickt?",a="Schmied Argus, der Schmied vor dem Gasthaus \"Zur Höhle des Löwen\" in Goldhain, schickt die Kiste, nachdem er die Hufeisen fertiggestellt hat.",al={"wer gab die quest","schmied argus","questgeber"}},{q="Warum ist Verner verärgert, als er die Kiste erhält?",a="Schmied Argus hat eine Rechnung beigefügt, die Bezahlung für alle fünfzig Hufeisen verlangt, und Verner ist verärgert. Offenbar hatte er auf einen kostenlosen Gefallen oder günstigere Bedingungen gehofft.",al={"warum ist verner wütend","argus' zettel","verners reaktion"}},{q="Welche Quests werden nach Abschluss dieser Lieferung verfügbar?",a="Nach dieser Lieferung bietet Verner Aufgaben gegen örtliche Bedrohungen an: Jagt die Gnolle im Rotkammgebirge in 'A Baying of Gnolls' und beschafft 'Underbelly Scales'.",al={"nächste quest","folgequests","was wird freigeschaltet"}},{q="Warum braucht Seenhain Versorgungsgüter aus Goldhain?",a="Gnolle und Schwarzfelsorcs belagern Seenhain und bringen die örtlichen Handwerker an ihre Grenzen. Die Stadt braucht oft Alltagswaren wie eiserne Hufeisen in großen Mengen aus ruhigeren Orten wie Goldhain.",al={"warum hufeisen aus elwynn","warum hufeisen importieren","versorgung im rotkammgebirge"}},{q="Begleitet Euch Schmied Argus zurück ins Rotkammgebirge?",a="Nein. Schmied Argus bleibt an seiner Schmiede in Goldhain, während Ihr die Kiste ins Rotkammgebirge tragt.",al={"kommt argus mit","schmied argus eskortieren"}}},fx={a0846e84={q="Warum will Schmied Argus, dass diese Kiste an Verner geliefert wird?",a="Schmied Argus kommt der dringenden Bitte von Verner Gutmark um fünfzig Hufeisen nach, aber nicht aus reiner Güte. Er hat sie verpackt und eine gepfefferte Rechnung für seine Arbeit und Materialien beigelegt. Die Übergabe der Lieferung an Euch stellt sicher, dass Rotkammgebirge seine Vorräte erhält, während gleichzeitig sichergestellt wird, dass Verner weiß, dass die Eisenwaren in Goldhain nicht umsonst sind.",al={"warum schickt schmied argus hufeisen","schmied argus beweggrund","argus hufeisen für verner warum"}},f67540ab={q="Warum bittet Schmied Argus Euch, die Hufeisen zu tragen, anstatt sie selbst auszuliefern?",a="Argus ist der ansässige Schmied von Goldhain, der an seinen Amboss und seine Esse gebunden ist, um Reisende und örtliche Wachen auszurüsten. Eine schwere Kiste mit fünfzig Eisenhufeisen über die Grenze durch die Pässe von Rotkammgebirge zu schleppen, kostet Zeit bei seiner Arbeit und setzt einen einzelnen Handwerker den Gnollen und Wegelagerern entlang der Straße aus. Ihr seid ein fähiger Abenteurer, der ohnehin nach Osten reist.",al={"warum liefert argus die schuhe nicht selbst","warum ich return to verner","warum spieler nach seenhain schicken"}}},fp="16,156,27.247.0,21.257.0,40.115.0,40.118.0,47.154.0,51.142.0,57.178.0,48.86.0"}
P.entries["quest:1190"] = {n="Tempo halten",s="Pozzik vermutet, dass die Brassbolts Brothers einen neuen Werkstoff für ihre Wagen gefunden haben. Ihre Konstruktionen und Fahrdaten sind unverändert, doch die Wagen fahren schneller. Rizzle Brassbolts behält seine Pläne stets bei sich, und Zamek kann ihn ablenken, damit Ihr sie stehlen könnt. Dies folgt auf News for Fizzle.",h="Pozzik vermutet, dass die Brassbolts Brothers einen neuen Werkstoff für ihre Wagen gefunden haben.",kw={"brassbolts","ablenkungsmanöver","pozzik","rennwagen","rizzle brassbolts","baupläne","die schimmernde ebene","tausend nadeln","zamek"},sec={{t="Schneller, als die Zahlen sagen",b="Die Wagen der Brassbolts Brothers sind schneller geworden, und Pozzik sieht nur eine Erklärung: einen neuen Baustoff. Ihre Konstruktionen und die Daten ihrer Fahrten sind unverändert. Rizzle Brassbolts ist fast ununterbrochen in Pläne für diese Entdeckung vertieft."},{t="Ein Ablenkungsmanöver von Zamek",b="Zamek kann Rizzle ablenken, während Ihr seine Pläne stehlt. Pozzik wartet auf der Schimmernden Ebene darauf."},{t="Die gestohlene Schriftrolle",b="Rizzles Pläne sind eine Schriftrolle voller hastiger Notizen und Entwürfe. Sie betreffen die Veredelung eines Rohstoffs."}},faq={{q="Warum will Pozzik Rizzles Pläne?",a="Die Wagen der Brassbolts Brothers fahren schneller, obwohl ihre Konstruktionen und Fahrdaten unverändert sind. Pozzik vermutet, dass sie einen neuen Baustoff gefunden haben, und will die Pläne, in die Rizzle vertieft ist.",al={"pozziks beweggrund","warum die pläne der brassbolts brothers stehlen","grund für tempo halten"}},{q="Wer hilft dabei, Rizzle Brassbolts abzulenken?",a="Zamek kann Rizzle Brassbolts ablenken und Euch so die Gelegenheit geben, seine Pläne zu stehlen.",al={"wer sorgt für ablenkung","zameks rolle","wie rizzle ablenken"}},{q="Für wen werden die Pläne gestohlen?",a="Pozzik will die Pläne. Er befindet sich auf der Schimmernden Ebene in Tausend Nadeln.",al={"wo ist tempo halten","tempo halten ort"}},{q="Was kommt vor diesem Schritt?",a="Tempo halten folgt direkt auf News for Fizzle.",al={"tempo halten voraussetzung","welche quest kommt vor tempo halten"}},{q="Was folgt, nachdem die Pläne gesichert sind?",a="Die Questreihe geht mit Rizzle's Schematics weiter.",al={"welche quest kommt als nächstes","nach tempo halten"}}},fp="12,270,27.259.0,22.103.0,17.105.1,36.193.0,37.76.0,29.74.0,28.47.0,38.45.0"}
P.entries["quest:1191"] = {n="Zameks Ablenkungsmanöver",s="In Tausend Nadeln kann Zameks Ablenkungsmanöver Rizzle fortlocken, während Ihr an Keeping Pace arbeitet. Ohne dieses Ablenkungsmanöver könnt Ihr Keeping Pace nicht abschließen.",h="In Tausend Nadeln kann Zameks Ablenkungsmanöver Rizzle fortlocken, während Ihr an Keeping Pace arbeitet.",kw={"ablenkung","keeping pace","tausend nadeln","zamek"},sec={{t="Eine rechtzeitige Ablenkung",b="Während Ihr an Keeping Pace arbeitet, lockt Zamek Rizzle aus seiner Hütte. Die Indurium-Baupläne bleiben zurück."}},faq={{q="Wer vergibt Zameks Ablenkungsmanöver?",a="Zamek vergibt die Quest in Tausend Nadeln.",al={"wer startet zameks ablenkungsmanöver","zamek questgeber","wo gibt es zameks ablenkungsmanöver"}},{q="Wie hängt das mit Keeping Pace zusammen?",a="Ihr erhaltet die Quest, während Ihr mitten in Keeping Pace steckt, und ohne sie könnt Ihr diesen Schritt nicht abschließen.",al={"für keeping pace erforderlich","keeping pace zamek","verbindung zu keeping pace"}},{q="Was bewirkt die Ablenkung?",a="Rizzle verlässt seine Hütte, und seine Baupläne bleiben zurück.",al={"was passiert wenn zamek ablenkt","rizzle verlässt hütte"}},{q="Können Abenteurer der Allianz und der Horde mit Zamek zusammenarbeiten?",a="Ja. Zamek ist neutral und arbeitet mit beiden Fraktionen zusammen.",al={"ist zamek neutral","allianz oder horde zamek","wer kann zameks ablenkungsmanöver machen"}}},fp="19,141,18.103.0,30.35.0,37.97.0,27.53.0,56.52.0"}
P.entries["quest:1192"] = {n="Induriumerz",s="Pozzik braucht Induriumerz, um mehrere Teile für die Rennwagen zu bauen. Das Erz liegt bei der Uldaman-Ausgrabung im Ödland, jenseits des Meeres in Khaz Modan. Die Gnome sammeln bereits ihren eigenen Vorrat, und Pozzik möchte Schritt halten.",h="Pozzik braucht Induriumerz, um mehrere Teile für die Rennwagen zu bauen.",kw={"ödland","indurium","induriumerz","pozzik","rennwagen","tausend nadeln","uldaman"},sec={{t="Erz aus Uldaman",b="Pozzik bittet Euch, ihm vier Stücke rohes Induriumerz zu bringen. Ihr findet es bei der Uldaman-Ausgrabung im Ödland, jenseits des Meeres in Khaz Modan. Die Gnome sammeln bereits ihren eigenen Vorrat, und Pozzik möchte auch etwas davon. Dies folgt auf Rizzle's Schematics."}},faq={{q="Warum will Pozzik Induriumerz?",a="Pozzik braucht eine große Menge rohes Induriumerz für mehrere Teile der Rennwagen.",al={"wofür ist das indurium","warum induriumerz","pozzik indurium zweck"}},{q="Wo findet man Induriumerz?",a="Induriumerz stammt von der Uldaman-Ausgrabungsstätte im Ödland, jenseits des Meeres in Khaz Modan.",al={"wo induriumerz finden","indurium fundort","wo bekommt man induriumerz"}},{q="Warum ist es wichtig, das Erz zu beschaffen?",a="Die Gnome sammeln bereits ihr eigenes Induriumerz, und Pozzik möchte Schritt halten.",al={"warum eile beim indurium","gnome konkurrenz indurium"}},{q="Was kam davor?",a="Rizzle's Schematics kommt davor, und Keeping Pace kommt vor Rizzle's Schematics.",al={"voraussetzung für induriumerz","indurium questreihe vorherige quest"}}},fp="12,221,16.255.0,34.78.0,32.89.0,34.83.0,22.89.0"}
P.entries["quest:1194"] = {n="Rizzles Baupläne",s="Nach Keeping Pace bringt Ihr eine rohe Induriumprobe zu Pozzik auf der Schimmernden Ebene. Rizzles Pläne liegen unter dem Erz, und seine Notizen verweisen auf die Ausgrabung der Zwerge bei Uldaman im Ödland als dessen Herkunftsort. Sie beschreiben auch, wie gut Indurium Hitze widersteht.",h="Nach Keeping Pace bringt Ihr eine rohe Induriumprobe zu Pozzik auf der Schimmernden Ebene.",kw={"ödland","indurium","pozzik","rizzle","baupläne","die schimmernde ebene","uldaman"},sec={{t="Notizen zu Indurium",b="Rizzles Pläne erklären, wie man Induriumerz veredelt. Hingekritzelte Notizen verweisen auf die Ausgrabung der Zwerge bei Uldaman im Ödland als dessen Herkunftsort. Andere Notizen beschreiben die Hitzebeständigkeit des Erzes. Ein Klumpen rohes Indurium beschwert die Pläne, und Ihr bringt die Probe zu Pozzik."},{t="Pozziks Urteil",b="Pozzik findet Indurium interessant. Wenn es Hitze so gut widersteht, wie Ihr sagt, könnte das erklären, wie sehr sich die Gnome in letzter Zeit verbessert haben. Die Probe wird für Tests von unschätzbarem Wert sein, doch Pozzik braucht mehr davon, bevor sie von echtem Nutzen sein kann."}},faq={{q="Woher bekommt Rizzle sein Induriumerz?",a="Rizzles Gekritzel verweist auf die Ausgrabung der Zwerge bei Uldaman im Ödland als Herkunftsort seines Induriumerzes.",al={"woher stammt indurium","herkunft von induriumerz","rizzle indurium fundort"}},{q="Was sagen Rizzles Notizen über Indurium?",a="Rizzles Notizen beschreiben, wie man Indurium veredelt, und viele weitere befassen sich mit seiner Hitzebeständigkeit.",al={"was bewirkt indurium","warum indurium","indurium eigenschaften"}},{q="Wer erhält die Induriumprobe?",a="Ihr bringt die Probe zu Pozzik auf der Schimmernden Ebene.",al={"bei wem abgeben","wer will die induriumprobe","pozzik abgabe"}},{q="Woher stammt diese Probe?",a="Ein Klumpen rohes Induriumerz beschwerte Rizzles Pläne als Briefbeschwerer.",al={"wo wurde die probe gefunden","rizzle briefbeschwerer"}}},fp="19,244,17.261.0,16.229.1,39.104.0,42.95.0,33.55.0,32.69.0"}
P.entries["quest:1195"] = {n="Die heilige Flamme",s="Zangen Steinhuf schickt Euch auf die Suche nach einer heiligen Flamme und einem uralten Relikt. Um Rau Klippenläufer in Tausend Nadeln zu helfen, sucht Ihr in Eschental eine Phiole für Mondbrunnenwasser.",h="Zangen Steinhuf schickt Euch auf die Suche nach einer heiligen Flamme und einem uralten Relikt.",kw={"eschental","geätzte phiole","der falfarren","galak-zentauren","laughing sisters","mondbrunnen","rau klippenläufer","rajenbaum","die heilige flamme","tausend nadeln","zangen steinhuf"},ang={["class:Druid"]="Als Taurendruide steht Ihr vor einer schweren Wahl: die Töchter der Natur, die Dryaden, erschlagen, um geweihtes Wasser gegen die heiligen Flammen der Zentauren zu sammeln.",["faction:Horde"]="Unruhe um Rajenbaum könnte die Spannungen mit den Nachtelfen im Eschental verschärfen. Zentaurenrelikte in Tausend Nadeln stärken die südlichen Grenzen der Horde.",["race:Tauren"]="Die Feindseligkeit der Zentauren macht den Tauren seit Generationen zu schaffen. Ein Relikt aus den Anfängen des Zentaurenvolkes könnte Mulg ores Stämmen Einblicke in ihre Feinde und einen Vorteil gegen sie verschaffen."},sec={{t="Zentaurenrelikte und Elfenwasser",b="Die Galak-Zentauren bewachen ein uraltes Relikt in Tausend Nadeln. Das Artefakt stammt aus den Anfängen ihres Volkes, und heilige Flammen schützen es. Zangen Steinhuf braucht vom Mond gesegnetes Wasser, um diese Flammen zu löschen. Er schickt Euch nach Norden ins Eschental, wo die alten Wälder das gesuchte Mondbrunnenwasser bergen."},{t="Unerlaubter Zutritt im Eschental",b="Reines Mondbrunnenwasser braucht ein Gefäß, das es nicht verunreinigt. Ihr sucht eine Geätzte Phiole, die von den Laughing Sisters getragen wird, Dryaden nahe Rajenbaum. Taucht die Phiole in einen Mondbrunnen am westlichen Ufer des Falfarren und bringt sie dann nach Mulgore zurück."}},faq={{q="Warum braucht Zangen Steinhuf Mondbrunnenwasser?",a="Zangen braucht Mondbrunnenwasser für Rau Klippenläufer, seinen Gefährten in Tausend Nadeln. Rau will mit dessen Magie die heilige Flamme löschen, die von den feindseligen Galak-Zentauren bewacht wird, damit die Horde ein uraltes Relikt bergen kann.",al={"warum mondbrunnenwasser","zweck des mondbrunnenwassers","warum wasser aus eschental holen"}},{q="Wo ist die Geätzte Phiole zu finden?",a="Die Laughing Sisters tragen die Geätzte Phiole bei sich. Diese Dryaden durchstreifen die Wälder um Rajenbaum im mittleren Eschental, unweit der nördlichen Straße, die vom Splitterholzposten nach Westen führt.",al={"wo ist die geätzte phiole","wie die geätzte phiole bekommen","fundort der phiole"}},{q="An welchem Mondbrunnen soll die Phiole gefüllt werden?",a="Nutzt den Mondbrunnen nahe dem westlichen Ufer des Falfarren, südlich der Hauptstraße durch das mittlere Eschental.",al={"welcher mondbrunnen","standort des mondbrunnens","wo die phiole füllen"}},{q="Wer sind die Galak-Zentauren?",a="Die Galak sind ein angriffslustiger Zentaurenstamm in den staubigen Weiten von Tausend Nadeln. Sie bewachen ein uraltes Relikt aus den Anfängen ihres Volkes, umgeben von einem heiligen Freudenfeuer, das Zangen und Rau löschen wollen.",al={"galak-stamm","galak-zentauren","wer sind die galak"}},{q="Wer erhält die gefüllte Phiole nach Zangen?",a="Nachdem Zangen die gefüllte Phiole in Donnerfels untersucht hat, schickt er Euch nach Süden nach Tausend Nadeln. Dort übergebt Ihr sie Rau Klippenläufer, der darum gebeten hat.",al={"wer ist rau","wohin kommt das wasser als nächstes","nächster schritt nach zangen"}},{q="Warum Dryaden für ihre Phiolen töten?",a="Die Gefäße der Dryaden sind dafür gemacht, reine, verzauberte Flüssigkeiten aufzunehmen, ohne sie zu verunreinigen. Gewöhnliche Flaschen können Wasser, das von der himmlischen Macht eines Nachtelfenmondbrunnens durchdrungen ist, nicht sicher fassen.",al={"warum dryaden angreifen","warum laughing sisters","gefäße der dryaden"}}},fx={["47d9b30a"]={q="Wozu dient die Gefüllte geätzte Phiole?",a="Die Phiole enthält heiliges Wasser, das aus einem Mondbrunnen der Nachtelfen im Eschental geschöpft und in einem Gefäß aufbewahrt wird, das den Dryaden abgenommen wurde. Zangen Steinhufs Verbündeter, Rau Klippenläufer in Tausend Nadeln, benötigt dieses geweihte Wasser, um die heilige Flamme der Galak-Zentauren auszulöschen, damit die Horde ein uraltes Relikt aus der Frühzeit der Zentauren bergen kann.",al={"nutzen gefüllte geätzte phiole","warum gefüllte geätzte phiole","was bewirkt die phiole"}},["9c32d271"]={q="Wer sind die Laughing Sisters?",a="Die Laughing Sisters sind Dryaden, Töchter des Halbgottes Cenarius, die die verzauberten Haine um Rajenbaum im Eschental bewachen. Sie sind tief mit der Natur und den Nachtelfen verbunden, bewohnen heilige Stätten und tragen spezielle geätzte Phiolen, die sich zum Aufbewahren von reinem Mondbrunnenwasser eignen. Da sie Außenstehenden und der Horde gegenüber äußerst feindselig sind, müsst Ihr ihnen die Phiole mit Gewalt entreißen.",al={"warum dryaden töten","wer sind dryaden in rajenbaum","laughing sisters eschental"}}},fp="16,153,31.304.0,24.259.0,46.235.0,36.185.0,48.111.0,26.206.0,43.155.0,33.177.0"}
P.entries["quest:1196"] = {n="Die heilige Flamme",s="Eine Phiole Mondbrunnenwasser reist von Eschental nach Süden zum Freiwindposten. Rau Klippenläufer braucht sie, um die ewige Flamme zu brechen, die ein uraltes Zentaurenrelikt in Tausend Nadeln bewacht.",h="Eine Phiole Mondbrunnenwasser reist von Eschental nach Süden zum Freiwindposten.",kw={"zentaurenrelikt","geätzte phiole","freiwindposten","der große aufzug","rau klippenläufer","die heilige flamme","tausend nadeln","zangen steinhuf"},ang={["class:Druid"]="Rau Klippenläufer nutzt sein tiefes Wissen über die Cenarion-Blutlinien, um die magische Resonanz zwischen Dryaden und Zentauren zu verstehen.",["faction:Horde"]="Die Übergabe dieser Phiole stärkt den Freiwindposten, den hochgelegenen Außenposten der Horde zwischen den gefährlichen Pässen von Tausend Nadeln.",["race:Tauren"]="Jeder Schlag gegen die Zentauren hilft, Mulgore und die neu gesicherten Grenzen Eurer Heimat zu schützen."},sec={{t="Eine weite Reise südwärts",b="Zangen Steinhuf schickt Euch mit einer geätzten Phiole gereinigten Mondbrunnenwassers durch das zentrale Kalimdor nach Süden. Ihr durchquert das sonnenverbrannte Brachland, fahrt mit dem Großen Aufzug hinab und zieht weiter zum Freiwindposten. Rau Klippenläufer wartet auf dem hohen Tafelberg über dem Grund des Canyons. Von dort aus beobachtet er die Zentaurenclans unter ihm."},{t="Gemeinsames Blut und uralte Schutzzauber",b="Rau Klippenläufer erklärt, wie Mondbrunnenwasser ihm im Kampf gegen die Zentauren helfen kann. Dryaden und Zentauren haben gemeinsame Vorfahren durch Cenarius, dessen Sohn Zaetar die Zentauren zeugte. Diese Verwandtschaft verleiht heiligem Mondbrunnenwasser eine arkane Resonanz. Sie ist die einzige Macht, die die ewige Flamme durchdringen kann, die ein bewachtes Zentaurenartefakt schützt."}},faq={{q="Wo befindet sich Rau Klippenläufer?",a="Rau Klippenläufer lebt hoch oben auf dem Freiwindposten in Tausend Nadeln. Reist nach Süden durch das Brachland, fahrt mit dem Großen Aufzug zum Grund des Canyons hinab und folgt dann dem südöstlichen Pfad zum Aufzug hoch an der steilen Felsnadel.",al={"wo ist rau","rau klippenläufer standort","rau klippenläufer finden","freiwindposten abgabe"}},{q="Warum braucht Rau Mondbrunnenwasser im Kampf gegen Zentauren?",a="Zentauren und Dryaden haben durch Cenarius eine gemeinsame Abstammung. Ihre Verwandtschaft verleiht dem Mondbrunnenwasser der Nachtelfen den magischen Einklang, der nötig ist, um die ewige Flamme zu brechen, die das Zentaurenrelikt schützt.",al={"warum mondbrunnenwasser","verbindung zwischen mondbrunnen und zentauren","verwandtschaft zwischen dryaden und zentauren"}},{q="Wer hat mich mit der Phiole geschickt?",a="Zangen Steinhuf hat Euch mit der Gefüllten geätzten Phiole geschickt, nachdem Ihr Wasser aus dem bewachten Mondbrunnen in Eschental gesammelt hattet.",al={"wer gab diese quest","zangen steinhuf","questgeber die heilige flamme zwei"}},{q="Was geschieht, nachdem ich Rau die Phiole gegeben habe?",a="Nachdem Rau bestätigt hat, dass das Wasser unversehrt ist, bittet er Euch, mit der Phiole die Flamme zu löschen und das Zentaurenrelikt aus dem nahen Canyon zu holen.",al={"nächste quest","was kommt nach rau","die heilige flamme teil drei"}},{q="Wie gelange ich hinab nach Tausend Nadeln?",a="Folgt der Hauptstraße nach Süden durch das Brachland bis zum Rand der Klippe. Dort wartet der Große Aufzug mit zwei hölzernen Fahrstühlen, die Reisende mit taurischen Seilzügen zum Grund des Canyons hinabbefördern.",al={"wie nach tausend nadeln gelangen","die klippe im brachland überwinden","weg zum großen aufzug"}},{q="Warum suchen die Tauren ein Zentaurenrelikt?",a="Tauren und Zentauren führen seit Generationen einen brutalen Krieg in ganz Kalimdor. Die Tauren stören Zentaurenriten und beschlagnahmen heilige Artefakte, um die kriegerischen Clans zu schwächen, die sich im Canyon von Tausend Nadeln verschanzt haben.",al={"krieg zwischen tauren und zentauren","warum das zentaurenrelikt stehlen"}}},fx={["070b3297"]={q="Warum will Zangen Steinhuf, dass dies erledigt wird?",a="Zangen Steinhuf koordiniert die Bemühungen, Rau Klippenläufer und die Tauren in Tausend Nadeln zu unterstützen. Indem er das gesegnete Mondbrunnenwasser sichert und sicherstellt, dass es den Freiwindposten erreicht, verschafft er Rau die Mittel, der magischen Flamme entgegenzuwirken, die ein wichtiges Zentaurenrelikt schützt.",al={"warum phiole schicken","zangens beweggrund","zangens zweck"}}},fp="16,179,20.304.0,30.327.1,33.221.0,51.181.0,27.119.0,43.145.1,40.196.0,43.215.0"}
P.entries["quest:1197"] = {n="Die heilige Flamme",s="In der Spalthufhöhle will Rau Klippenläufer das heilige Feuer der Galak-Zentauren zum Erlöschen bringen. Ihr tragt gesegnetes Wasser in ihre Festung, löscht das Kohlebecken und nehmt den Gespaltenen Huf an Euch.",h="In der Spalthufhöhle will Rau Klippenläufer das heilige Feuer der Galak-Zentauren zum Erlöschen bringen.",kw={"zentauren","gespaltener huf","freiwindposten","galak","rau klippenläufer","heilige flamme","spalthufklippe","spalthufhöhle","tausend nadeln"},ang={["class:Shaman"]="Als Schamane könnt Ihr die seltsamen Energien spüren, die vom Gespaltenen Huf ausgehen. Sie zeigen, dass die Zentauren auf mystische Kräfte zurückgreifen, die über rohe Wildheit hinausgehen.",["race:Tauren"]="Als Tauren ist Euer Vorstoß in einen Zentaurenunterschlupf und die Wegnahme seines heiligen Kultbilds eine Antwort auf Generationen von Überfällen. Das Relikt ist auch eine wertvolle Beute für die Gelehrten am Freiwindposten."},sec={{t="Angriff auf die Feuerstelle",b="Nördlich vom Freiwindposten liegt die Spalthufklippe im Herzen des Galak-Territoriums in Tausend Nadeln. Tief in ihrer Höhle birgt die Spalthufhöhle ein Feuer, das den Zentauren heilig ist. Rau Klippenläufer bereitet für seine Verbündeten eine geätzte Phiole mit gereinigtem Wasser vor. Ihr betretet die Zuflucht und löscht mit dem Wasser die Flamme für einen Moment. Dann nehmt Ihr das darin bewachte Relikt, den Gespaltenen Huf, an Euch."},{t="Geheimnisse des Hufs",b="Als Rau Klippenläufer den Gespaltenen Huf sieht, regt dessen seltsame Macht seine mystischen Sinne an. Taurengelehrte kämpfen schon lange gegen die marodierenden Zentaurenstämme in ganz Kalimdor. Das Relikt deutet auf tiefere, noch kaum verstandene Kräfte hin, die den Eifer und den Zusammenhalt der Zentaurenstämme nähren."}},faq={{q="Wo befindet sich die heilige Flamme?",a="Die Flamme brennt tief in der Spalthufhöhle, einer Höhle im Galak-Lager an der Spalthufklippe, nördlich vom Freiwindposten in Tausend Nadeln.",al={"spalthufhöhle standort","wo ist die heilige flamme","flammenhöhle tausend nadeln"}},{q="Wer bittet Euch, die Flamme zu löschen?",a="Rau Klippenläufer, ein Ältester hoch oben auf dem Freiwindposten, bittet Euch, die Flamme zu löschen, nachdem Ihr die Galak-Zentauren untersucht habt.",al={"questgeber heilige flamme","rau klippenläufer standort","wer gibt die quest"}},{q="Wie löscht Ihr die Flamme?",a="Benutzt die Gefüllte geätzte Phiole, die Rau Klippenläufer Euch gibt. Sie enthält Wasser, das zuvor in der Questreihe gesammelt wurde, und löscht kurzzeitig das Kohlebecken.",al={"wie bekommt man den gespaltenen huf","gegenstand zum flammenlöschen","heilige flamme löschen"}},{q="Was ist der Gespaltene Huf?",a="Der Gespaltene Huf ist ein verehrtes Stammesrelikt, das die Galak-Zentauren in der Flamme aufbewahren. Rau Klippenläufer spürt seine ungewöhnliche magische Energie und hofft, mehr über die Kultur und Macht der Zentauren zu erfahren.",al={"gespaltener huf hintergrund","zentaurenrelikt","was haben wir gestohlen"}},{q="Warum wollen die Tauren dieses Relikt?",a="Seit Generationen vertreiben Zentaurenstämme die Tauren aus ihren angestammten Jagdgründen. Ein heiliges Erbstück zu entwenden, stört die Unternehmungen der Galak, während die Tauren die arkanen oder spirituellen Kräfte hinter der Wildheit ihrer Feinde ergründen wollen.",al={"warum den gespaltenen huf stehlen","tauren zentauren krieg"}},{q="Welcher Zentaurenklan bewacht die Spalthufhöhle?",a="Der Stamm der Galak kontrolliert die Spalthufklippe und ihre Höhlenzuflucht. Er ist der vorherrschende Zentaurenklan auf dem Grund der Schlucht von Tausend Nadeln.",al={"tausend nadeln zentaurenstamm","galak-zentauren"}}},fp="16,177,19.370.0,19.272.1,34.133.0,32.129.0,29.132.0,24.191.0,34.237.0,41.133.0"}
P.entries["quest:1198"] = {n="Auf der Suche nach Thaelrid",s="Dämmerungsbehüter Shaedlass schickt Euch in die Tiefschwarze Grotte, um einen vermissten Späher zu finden. Die Argentumdämmerung fürchtet, dass sich Naga und Kultisten des Twilight's Hammer in den überfluteten Ruinen verbündet haben.",h="Dämmerungsbehüter Shaedlass schickt Euch in die Tiefschwarze Grotte, um einen vermissten Späher zu finden.",kw={"argentumdämmerung","eschental","tiefschwarze grotte","darnassus","naga","shaedlass","thaelrid","twilight's hammer"},ang={["class:Paladin"]="Als Paladin im Bund mit der Argentumdämmerung erkennt Ihr in Thaelrids einsamer Wacht die feierliche Pflicht, die Welt vor Schatten und Verderbnis zu schützen.",["faction:Alliance"]="Als Abenteurer der Allianz könnt Ihr beginnen, an der Seite der Argentumdämmerung zu dienen und ihr Wohlwollen zu gewinnen.",["race:NightElf"]="Als Nachtelf wisst Ihr, dass der uralte Temple of Elune in der Tiefschwarzen Grotte entweiht wurde. Der Argentumdämmerung zu helfen bedeutet, heiliges Erbe der Nachtelfen zurückzugewinnen."},sec={{t="Augen in Darnassus",b="Die Argentumdämmerung hält in ganz Kalimdor nach Bedrohungen Ausschau, ebenso wie nach der Geißel in Lordaeron. In Darnassus sammelt Dämmerungsbehüter Shaedlass Berichte über Gefahren jenseits der natürlichen Welt. Ihn erreicht die Nachricht, dass Naga in der Tiefschwarzen Grotte einen Pakt mit den Weltuntergangsfanatikern des Twilight's Hammer geschlossen haben. Die überfluteten Ruinen liegen an der Küste von Eschental, und der Orden fürchtet, was dieses Bündnis bringen könnte."},{t="Der vermisste Späher",b="Argentumwache Thaelrid betrat die Höhlen, um Gerüchten von der Küste nachzugehen. Wochen sind ohne Nachricht vergangen, und Shaedlass' andere Späher sind auf anderen Einsätzen unterwegs. Er fürchtet, Thaelrid sei gefallen oder von den dunklen Mächten unter den Wellen gefangen genommen worden. Deshalb schickt er Euch in die Tiefschwarze Grotte, um den vermissten Späher lebend zurückzubringen."}},faq={{q="Warum interessiert sich die Argentumdämmerung für die Tiefschwarze Grotte?",a="Die Argentumdämmerung hält in ganz Azeroth nach Bedrohungen Ausschau, auch nach Gefahren jenseits der Untoten der Östlichen Königreiche. Dass sich Naga in Kalimdor mit Kultisten des Twilight's Hammer verbünden, verlangt die Aufmerksamkeit des Ordens.",al={"warum argentumdämmerung hier","argentumdämmerung tiefschwarze grotte","argentumdämmerung naga"}},{q="Wer ist Dämmerungsbehüter Shaedlass?",a="Dämmerungsbehüter Shaedlass ist ein Agent der Argentumdämmerung in Darnassus, der Hauptstadt der Nachtelfen. Er sammelt Informationen, ermittelt, wo die Hilfe des Ordens benötigt wird, und entsendet Ermittler, um regionale Krisen einzuschätzen.",al={"wer ist shaedlass","questgeber shaedlass","dämmerungsbehüter shaedlass aufgabe"}},{q="Wer ist Argentumwache Thaelrid?",a="Argentumwache Thaelrid ist ein Agent der Argentumdämmerung, der zur Untersuchung der Tiefschwarzen Grotte entsandt wurde. Er brach auf, um die Stärke und die Absichten der Naga und Kultisten in den überfluteten Höhlen zu erkunden.",al={"wer ist thaelrid","thaelrid hintergrund","vermisster späher thaelrid"}},{q="Wo ist Thaelrid zu finden?",a="Argentumwache Thaelrid befindet sich tief in der Tiefschwarzen Grotte am Zoramstrand in Eschental. Er hat die Höhlen unterwandert und wartet dort allein auf Verstärkung.",al={"thaelrid aufenthaltsort","wo ist thaelrid","thaelrid finden bfd"}},{q="Was geschieht, nachdem Thaelrid gefunden wurde?",a="Wenn Ihr Thaelrid findet, enthüllt er die wahre Natur des Rituals in den Ruinen und weist Euch in Blackfathom Villainy den Weg zu den Anführern des Kults.",al={"what comes next","folgequest zu thaelrid","nächste quest nach thaelrid"}},{q="Können Spieler der Horde diese Mission annehmen?",a="Dämmerungsbehüter Shaedlass erteilt den Auftrag in Darnassus, und er richtet sich an Abenteurer der Allianz. Abenteurer der Horde können ihn annehmen, wenn sie Shaedlass erreichen.",al={"horde auf der suche nach thaelrid","kann die horde diese quest machen","horde thaelrid"}}},fx={["4b9c6d96"]={q="Warum will Dämmerungsbehüter Shaedlass, dass Ihr Thaelrid findet?",a="Shaedlass sammelt Informationen für die Argentumdämmerung, um wachsende Übel in ganz Kalimdor zu überwachen. Vor Wochen entsandte er Argentumwache Thaelrid, um beunruhigende Gerüchte bezüglich einer Allianz zwischen den Naga und dem Schattenhammer in der Tiefschwarzen Grotte zu untersuchen. Da er keine Nachricht von ihm erhalten hat, befürchtet er das Schlimmste und muss sowohl den Status des Spähers als auch die Wahrheit hinter der finsteren Verschwörung, die an der Küste des Eschentals Wurzeln schlägt, bestätigen.",al={"warum thaelrid finden","shaedlass' beweggrund","warum in die tiefschwarze grotte schicken"}},["3832a285"]={q="Warum schickt Shaedlass einen Abenteurer anstelle seiner eigenen Späher?",a="Die Präsenz der Argentumdämmerung in Darnassus ist gering, und Shaedlass merkt an, dass alle seine anderen Späher mit ihren eigenen dringenden Missionen im ganzen Land vollauf beschäftigt sind. Da Thaelrid vermisst wird und keine Agenten mehr verfügbar sind, muss er sich auf fähige und willige Abenteurer verlassen, die in seinem Namen in die tückischen Tiefen vordringen.",al={"warum ich in search of thaelrid","warum keine argentumdämmerung-späher schicken"}}},fp="21,178,17.390.0,17.332.0,55.207.0,29.200.0,29.178.0,28.165.0,36.143.1,36.148.0"}
P.entries["quest:1199"] = {n="Die Stunde der Finsternis",s="In der Tiefschwarzen Grotte haben sich Kultisten des Schattenhammerklans unter der Küste des Eschentals mit den Naga verbündet. Argentumwache Manados in Darnassus ruft Champions der Allianz auf, Anhänger von gefallenen Kultisten zu sammeln und ihre Pläne zur Erweckung uralter Übel zu vereiteln.",h="In der Tiefschwarzen Grotte haben sich Kultisten des Schattenhammerklans unter der Küste des Eschentals mit...",kw={"argentumdämmerung","argentumwache manados","eschental","tiefschwarze grotte","darnassus","manados","naga","alte götter","die stunde der finsternis","anhänger des schattenhammerklans","schattenhammerklan"},ang={["class:Paladin"]="Als Paladin, der mit Orden wie der Argentumdämmerung verbunden ist, seht Ihr die Verehrung der Alten Götter durch den Schattenhammerklan als Gräuel, das rechtschaffene Läuterung verlangt.",["class:Priest"]="Als Priester spürt Ihr die Verderbnis des einst heiligen Mondbrunnens im Tempel und das unheilvolle, wahnsinnbringende Flüstern, das die Kultisten tiefer in den Wahnsinn treibt.",["faction:Alliance"]="Der Schattenhammerklan bedroht die Allianz unmittelbar südlich der Dunkelküste. Die Säuberung der Tiefschwarzen Grotte hilft, das nördliche Kalimdor zu sichern.",["race:NightElf"]="Als Nachtelf ist Euch die Entweihung eines heiligen Tempels und Mondbrunnens durch Kultisten der Alten Götter und Naga ein Frevel an Elune und den angestammten Landen des Eschentals."},sec={{t="Ein entweihtes Heiligtum",b="Unter dem Zoramstrand im Eschental liegt die Tiefschwarze Grotte in Trümmern. Einst war sie ein heiliger Nachtelfentempel der Elune und beherbergte einen mächtigen Mondbrunnen. Die Zerschlagung zertrümmerte den Tempel und ließ ihn im Meer versinken. Heute bevölkern Naga und Kultisten seine Hallen. Das Wasser ist verdorben, und die Kultisten verehren Mächte, die finsterer sind als das Meer."},{t="Flüstern der Alten Götter",b="Der Schattenhammerklan verehrt die chaotischen Alten Götter und strebt nach ihrer Rückkehr. Seine Anhänger hoffen, Wahnsinn und Verwüstung über die Welt zu bringen. Berichten in Darnassus zufolge haben sich die Kultisten mit den Naga in der Tiefschwarzen Grotte verbündet. Dort vollziehen sie Rituale in den versunkenen Hallen und nutzen das verdorbene Tempelwasser, um das Wiedererstarken ihrer dunklen Meister zu nähren."},{t="Die Wacht der Argentumdämmerung",b="Argentumwache Manados hält von Darnassus aus im Auftrag der Argentumdämmerung nach Bedrohungen für Azeroth Ausschau. Er sieht Gefahr in der Tiefschwarzen Grotte, deren Schrecken jedes zivilisierte Volk erreichen könnten. Der Orden bietet Helden Hilfe und Anerkennung, wenn sie das überflutete Labyrinth betreten, die Kultisten dezimieren und deren Anhänger des Schattenhammerklans als Beweis ihrer Niederlage zurückbringen."}},faq={{q="Wer ist Argentumwache Manados?",a="Argentumwache Manados ist ein Gesandter der Argentumdämmerung, der in Darnassus stationiert ist. Er hält nach Kulten und dunklen Mächten Ausschau, die Kalimdor bedrohen, und wirbt Abenteurer an, um sie zu vernichten.",al={"manados","wer vergibt die stunde der finsternis","argentumwache manados standort"}},{q="Warum sorgt sich die Argentumdämmerung um die Tiefschwarze Grotte?",a="Die Argentumdämmerung bekämpft die Geißel in Lordaeron, doch ihr Auftrag umfasst auch unnatürliche Übel, die die Welt bedrohen. Die Verehrung der Alten Götter und das Bündnis zwischen Kultisten und Naga in Kalimdor könnten ungehindert eine Katastrophe heraufbeschwören.",al={"warum argentumdämmerung darnassus","argentumdämmerung tiefschwarze grotte"}},{q="Was ist der Schattenhammerklan?",a="Der Schattenhammerklan ist ein Weltuntergangskult, der den chaotischen Alten Göttern dient, urzeitlichen Wesen, die vor langer Zeit unter der Erde eingesperrt wurden. Seine Anhänger streben ein apokalyptisches Ende an, das ihre Meister aufsteigen und die Welt in Schrecken und Wahnsinn neu erschaffen ließe.",al={"schattenhammerklan kult","wer ist der schattenhammerklan","schattenhammerklan"}},{q="Wozu dienten die Anhänger des Schattenhammerklans?",a="Anhänger des Schattenhammerklans sind dunkle Talismane, die Mitglieder des Schattenhammerklans tragen, um ihre Treue zu den von ihnen verehrten Wesen zu zeigen. Die Argentumdämmerung sammelt sie als Beweis dafür, dass ein Kultist getötet wurde und keine Bedrohung mehr darstellt.",al={"anhänger des schattenhammerklans hintergrund","was sind anhänger des schattenhammerklans"}},{q="Was war die Tiefschwarze Grotte ursprünglich?",a="Die Tiefschwarze Grotte war ein Elune geweihter Nachtelfentempel, berühmt für seinen mächtigen Mondbrunnen. Die Große Zerschlagung riss die Erde auf und ließ seine Hallen im Meer versinken.",al={"tiefschwarze grotte geschichte","bfd tempel geschichte","tiefschwarze grotte mondbrunnen"}},{q="Warum arbeitet der Schattenhammerklan mit den Naga zusammen?",a="Die Gründe für das Bündnis sind nicht vollständig bekannt. Beide Gruppen zieht die dunkle Macht an, die sich im versunkenen Tempel regt. Die Kultisten erhalten sicheren Zugang zu uralten versunkenen Kammern, während die Naga von ihrer Zauberei und ihren Opferriten profitieren.",al={"naga kultisten bündnis","bfd naga bündnis"}}},fp="14,248,17.322.0,24.342.0,28.355.0,28.170.0,57.231.0,30.242.0,41.210.0,38.170.0,52.245.0"}
P.entries["quest:12"] = {n="Die Volksmiliz",s="Auf der Späherkuppe stellt Gryan Starkmantel die Volksmiliz gegen Gesetzlose auf Westfalls nördlichen Feldern und in den Minen auf die Probe. Örtliche Freiwillige verteidigen die Region gegen die Bruderschaft der Defias, während Sturmwinds Thron abgelenkt und seine Armee abwesend ist.",h="Auf der Späherkuppe stellt Gryan Starkmantel die Volksmiliz gegen Gesetzlose auf Westfalls nördlichen Feldern...",kw={"schmuggler der defias","fallensteller der defias","furlbrow","gryan starkmantel","jangolode","molsens hof","volksmiliz","späherkuppe","westfall"},ang={["class:Paladin"]="Als Paladin beschützt Ihr die Wehrlosen und richtet über Gesetzlose, die sich an den Schutzbedürftigen vergreifen.",["faction:Alliance"]="Als Abenteurer der Allianz seht Ihr die Kluft im Königreich: Sturmwinds Adel bleibt hinter den Mauern der Hauptstadt, während einfache Siedler Westfall vor dem Untergang bewahren.",["race:Human"]="Als Mensch des Königreichs seht Ihr, wie arbeitende Familien und Generationen von Bauern unter Banditenangriffen leiden, während die königliche Obrigkeit wegsieht."},sec={{t="Der Preis des Friedens",b="Gryan Starkmantel gründete die Volksmiliz, und er nimmt nicht jeden auf. Wer ihr Abzeichen tragen will, muss beweisen, dass er kämpfen und unschuldige Siedler beschützen kann. Er fordert entschlossenes Handeln, um Westfall von den Gesetzlosen, Landstreichern und Dieben zurückzuerobern, die die Region überrennen."},{t="Die Kornkammer befreien",b="Bevor Gryan Starkmantel neuen Rekruten weiterführende Einsätze anvertraut, schickt er sie gegen die Defias nahe den nördlichen Gehöften. Fallensteller und Schmuggler der Defias operieren offen nahe dem Jangoschacht, Molsens Hof und Furlbrows Kürbishof. Sie plündern Vorräte und überfallen Reisende aus dem Hinterhalt. Sie zu vertreiben stört ihre Nahrungsbeschaffung und zeigt Starkmantels Spähern, dass Ihr die nötige Zähigkeit für einen langen Kampf gegen das Verbrechen besitzt."}},faq={{q="Was ist die Volksmiliz?",a="Die Volksmiliz ist eine Freiwilligenarmee, die Gryan Starkmantel auf der Späherkuppe organisiert hat. Örtliche Bauern, Veteranen und einfache Bürger bildeten ihre Reihen, um Westfall gegen die Bruderschaft der Defias zu verteidigen, während Sturmwinds königliche Armee eine Stationierung in der Region verweigert hat oder daran gescheitert ist.",al={"volksmiliz","wer ist die miliz","was ist die volksmiliz"}},{q="Warum schickt Sturmwind seine königliche Armee nicht?",a="Seit König Varian Wrynn verschwunden ist, haben Sturmwinds adeliges House of Nobles und die Ratsführung die Mittel des Königreichs auf andere Gebiete konzentriert. Abgelegene ländliche Gebiete wie Westfall müssen sich selbst gegen die erstarkenden Banden von Gesetzlosen behaupten.",al={"wo ist die armee","warum keine wachen in westfall","sturmwinds garnison"}},{q="Wo finde ich Fallensteller und Schmuggler der Defias?",a="Fallensteller und Schmuggler der Defias operieren im gesamten nördlichen Westfall, besonders rund um Brauenwirbels Kürbishof, Molsens Hof und den Eingang zum Jangoschacht.",al={"fallensteller fundort","schmuggler fundort","wo sind fallensteller"}},{q="Wer ist Gryan Starkmantel?",a="Gryan Starkmantel ist ein erfahrener Veteran, der die Volksmiliz auf der Späherkuppe befehligt. Er schart Freiwillige um sich, um Westfalls Siedler zu verteidigen, die Bruderschaft der Defias zu vertreiben und auf dem Land wieder Ordnung herzustellen.",al={"wer ist starkmantel","gryan starkmantel geschichte","anführer der miliz"}},{q="Führt diese Quest zu weiteren Milizaufträgen?",a="Ja. Diese erste Prüfung führt erfolgreiche Freiwillige zu weiteren Aufgaben, bei denen sie sich auf Westfalls Ebenen immer gefährlicheren Mitgliedern der Bruderschaft der Defias stellen.",al={"ist das eine questreihe","nächste quest","fortschritt bei der miliz"}},{q="Was geschieht auf Brauenwirbels Kürbishof?",a="Die Bruderschaft der Defias vertrieb die Furlbrows von ihrem Gehöft und übernahm ihr Ackerland. Gesetzlose und Plünderer plündern nun die Felder und terrorisieren die nördlichen Straßen.",al={"furlbrows hof","was geschah mit den furlbrows","kürbishof"}}},fx={b0313ac5={q="Warum will Gryan Starkmantel, dass dies erledigt wird?",a="Gryan Starkmantel führt die Bürgerwehr mit einem einzigen Ziel: Westfall zu verteidigen und den Frieden von dem kriminellen Syndikat zurückzugewinnen, das seine Ackerflächen überrennt. Banden von Defias-Gesetzlosen plündern Gehöfte wie die Molsen- und Furlbrow-Farmen. Indem er deren Fallensteller und Schmuggler beseitigt, will Gryan deren Vordringen zurückdrängen und testen, ob Ihr die Entschlossenheit habt, für die Menschen von Westfall zu kämpfen.",al={"warum fallensteller und schmuggler töten","gryan starkmantels beweggrund","zweck der quest die bürgerwehr"}},["1cf2b131"]={q="Wer sind die Defias-Fallensteller und Schmuggler?",a="Sie sind einfache Handlanger der Defias-Bruderschaft, eines skrupellosen Syndikats aus Dieben und Gesetzlosen, die die Bauern von ihrem Land vertrieben haben. Die Fallensteller und Schmuggler lauern in der Nähe beschlagnahmter Ländereien wie Molsens Hof und dem Jangoschacht, sichern das Gebiet und lagern illegale Waren, um den Würgegriff der Bruderschaft über das Land zu unterstützen.",al={"defias-fallensteller","defias-schmuggler","wer sind die defias-gesetzlosen"}},b416da40={q="Warum braucht Gryan Starkmantel Euch, um gegen die Defias zu kämpfen?",a="Die Bürgerwehr ist eine Freiwilligentruppe, die bis an ihre Belastungsgrenze gespannt ist und von der königlichen Armee von Sturmwind völlig im Stich gelassen wurde. Gryan kann es sich nicht leisten, seine wenigen verbliebenen Verteidiger auf riskante Scharmützel zu schicken, ohne die Wache auf der Späherkuppe auszudünnen. Er verlässt sich auf fähige Freiwillige und Söldner und bittet Euch, Euren Wert und Euer Engagement unter Beweis zu stellen, bevor er Euch offiziell in die Ränge der Bürgerwehr aufnimmt.",al={"warum kämpft die bürgerwehr nicht gegen sie","warum ich gryan","warum außenstehende anwerben"}}},fp="20,253,18.276.0,24.404.0,29.267.0,43.238.0,47.152.0,25.216.0,49.167.0,45.179.0"}
P.entries["quest:120"] = {n="Botschaft nach Sturmwind",s="In Seenhain schickt Magistrat Solomon einen dringenden Hilferuf nach Sturmwind. Gnolle und Schwarzfelsorcs bedrängen die Stadt, und er kann keine Garnisonstruppen für die Reise entbehren. Er vertraut Euch „Die Situation von Seenhain“ für General Marcus Jonathan in Sturmwind an.",h="In Seenhain schickt Magistrat Solomon einen dringenden Hilferuf nach Sturmwind.",kw={"general marcus jonathan","seenhain","magistrat solomon","botschaft nach sturmwind","rotkammgebirge","verstärkung","stormwind army","die situation von seenhain"},ang={["class:Paladin"]="Als Paladin tragt Ihr die Bitten der Verzweifelten zu Anführern, denen die Politik am Hof die Hände bindet. Eure Pflicht, andere zu schützen und rechtschaffen zu handeln, wird auf die Probe gestellt.",["faction:Alliance"]="Für die Allianz offenbart Seenhains Hilferuf die Spannungen zwischen der wohlhabenden Hauptstadt und den Grenzsiedlungen, die an den Rändern des Königreichs ums Überleben kämpfen.",["race:Human"]="Als Mensch wisst Ihr, dass das Rotkammgebirge seit alters her zu Sturmwind gehört. Zu sehen, wie andere Menschen durch bürokratische Hürden im Stich gelassen werden, kann Euren Vaterlandsstolz verletzen."},sec={{t="Ein Ruf über die Berge",b="Gnolle machen jede Straße von Seenhain unsicher, während Schwarzfelsorcs von Norden her Überfälle verüben. Die Stadtwachen sind bis an ihre Grenzen beansprucht. Magistrat Solomon kann keine Kämpfer für den mehrtägigen Ritt in die Hauptstadt entbehren, also tragt Ihr seine offizielle Bitte um reguläre Truppen zu den Stadttoren."},{t="Bürokratie und High Seat",b="General Marcus Jonathan befehligt die Verteidigung von Sturmwind. Solomons Bericht erreicht ihn, und er schätzt die Führung des Magistrats und erkennt die Dringlichkeit. Doch das Armeeprotokoll verbietet ihm, ohne königliche Weisung Truppen zu mobilisieren. Die Verteidigung des Rotkammgebirges muss warten, während er sich mit dem jungen König Anduin und dem Regentschaftsrat berät."}},faq={{q="Warum braucht Magistrat Solomon einen Boten?",a="Gnolle und Schwarzfelsorcs bedrohen Seenhain, und jeder örtliche Wachmann wird gebraucht, um die Stadt zu verteidigen und die Brücke zu halten. Magistrat Solomon vertraut Reisenden seine dringenden Hilfsgesuche an.",al={"warum mich schicken","warum ein bote","solomons bote"}},{q="Was steht im Bericht „Die Situation von Seenhain“?",a="„Die Situation von Seenhain“ ist ein offizieller Bericht über die Krise im Rotkammgebirge. Er dokumentiert wachsende Feindzahlen, Verluste und den drohenden Fall der Stadt, sollten reguläre Soldaten aus der Hauptstadt ausbleiben.",al={"die situation von seenhain","solomons bericht","was ist der brief"}},{q="Wer ist General Marcus Jonathan?",a="General Marcus Jonathan befehligt die Sturmwind City Guard und ist ein hochrangiger Anführer der Sturmwind Army. Er wacht über die Stadttore und untersteht unmittelbar Hochlord Bolvar Fordragon und der Krone.",al={"marcus jonathan","wer ist der general","general von sturmwind"}},{q="Warum schickt General Jonathan nicht sofort Soldaten?",a="General Marcus Jonathan kann die Armee nicht aus eigener Vollmacht einsetzen. Er muss Solomons Bericht dem König und dem Regentschaftsrat vorlegen, um einen offiziellen königlichen Auftrag zu erhalten, bevor Truppen ausrücken können.",al={"warum keine truppen","wo bleibt die verstärkung","jonathans antwort"}},{q="Ist die Straße zwischen Seenhain und Sturmwind sicher?",a="Nein. Aggressive Gnollbanden und Wegelagerer der Defias suchen die Wege durch das Rotkammgebirge und nach Elwynn heim und machen die Reise für alleinreisende Boten gefährlich.",al={"straße nach sturmwind","sichere reise","straße im rotkammgebirge"}},{q="Schickt Sturmwind schließlich Hilfe?",a="Politische Unruhen und Verzögerungen in der Hauptstadt verhindern ein wirksames Eingreifen der Armee. Seenhain und Magistrat Solomon bleiben fast vollständig auf Söldner und Freiwillige angewiesen.",al={"trifft verstärkung ein","hilfe für seenhain"}}},fx={["3f8e995f"]={q="Warum schickt Magistrat Solomon einen Abenteurer anstelle einer Stadtwache?",a="Seenhain ist bis an seine absolute Belastungsgrenze angespannt. Die Stadt steht unter ständigem Druck von Gnollen und Schwarzfelsorcs, die aus den umliegenden Hügeln vordringen. Magistrat Solomon kann einfach keinen einzigen vereidigten Verteidiger oder Stadtwächter von seinen Kampflinien entbehren, ohne die Verteidigung der Stadt kritisch zu gefährden. Wenn man einen fähigen Abenteurer damit betraut, das Gesuch nach Sturmwind zu tragen, kann jeder örtliche Posten auf seinem Platz bleiben.",al={"warum schickt man mich","warum liefern seenhain-wachen nicht","warum abenteurer als bote"}}},fp="22,260,26.277.0,29.320.0,45.192.0,43.203.0,31.200.0,54.190.0,49.148.0,35.173.1"}
P.entries["quest:1200"] = {n="Schurkerei in der Tiefschwarzen Grotte",s="In der Tiefschwarzen Grotte ruft Argentumwache Thaelrid die Allianz auf, Zwielichtfürst Kelris aufzuhalten. Der Kultführer opfert Gefangene an Aku'mai, und Thaelrid bittet Euch, Kelris' abgeschlagenen Kopf als Beweis zur Argentumdämmerung in Darnassus zu bringen.",h="In der Tiefschwarzen Grotte ruft Argentumwache Thaelrid die Allianz auf, Zwielichtfürst Kelris aufzuhalten.",kw={"aku'mai","argentumdämmerung","blackfathom","darnassus","tiefen","elune","kelris","mondbrunnen","selgorm","thaelrid","schattenhammerkult"},ang={["class:Paladin"]="Als Paladin übt Ihr heilige Vergeltung, wenn Ihr dem Ruf der Argentumdämmerung folgt, einen Kultisten zu erschlagen, der Unschuldige urzeitlichen Schrecken opfert.",["class:Priest"]="Als Priester beendet Ihr die gotteslästerliche Schändung von Wassern, die einst in Verehrung des Göttlichen heilig waren, indem Ihr Kelris aufhaltet.",["faction:Alliance"]="Als Mitglied der Allianz helft Ihr der Argentumdämmerung, die gefährdeten Grenzen des Eschentals vor der Unterwanderung durch den Kult zu schützen, indem Ihr sie gegen Kelris unterstützt.",["race:NightElf"]="Als Nachtelf berührt es den Kern des Erbes der Kaldorei, die Schändung eines uralten Tempels von Elune zu rächen und seinen vergifteten Mondbrunnen zu reinigen."},sec={{t="Ein geschändetes Heiligtum",b="Die Tiefschwarze Grotte war einst ein Elune geweihter Tempel der Nachtelfen. Das Verderben eines uralten Alten Gottes stieg durch das Gestein empor und vergiftete den Mondbrunnen. Aus den verseuchten Wassern unter der Grotte kroch Aku'mai hervor, ein gefräßiger Diener jener Finsternis. Nach der Schändung des Tempels verbündete sich der Schattenhammerkult mit einheimischen Naga. Seine heiligen Hallen wurden zu einem Ort rituellen Mordes."},{t="Die Bitte der gefallenen Wache",b="Argentumwache Thaelrid betrat die Tiefschwarze Grotte im Auftrag seines Ordens. Dort wurde er schwer verwundet und seiner Kräfte beraubt. Von Feinden umringt, weiß er, dass er seinen Auftrag nicht allein erfüllen kann. Deshalb fleht er tapfere Reisende der Allianz, die ihn erreichen, an, Zwielichtfürst Kelris zu töten. Kelris führt die Kultisten an, die Unschuldige an Aku'mai opfern, um dunkle Macht zu erlangen."},{t="Gerechtigkeit in Darnassus",b="Auf der Terrasse der Handwerker in Darnassus wird Kelris' abgeschlagener Kopf Dämmerungsbehüter Selgorm überreicht. Diese Gabe beendet eine lange und beunruhigende Jagd. Die Argentumdämmerung hatte befürchtet, Kelris sei tot oder an die Schatten verloren. Immer wieder war er beteiligt gewesen, wenn sich dunkle Mächte in Kalimdor regten. Sein Tod sichert einen entscheidenden Sieg gegen die Pläne des Kults im Eschental."}},faq={{q="Wer ist Argentumwache Thaelrid?",a="Thaelrid ist ein Agent der Argentumdämmerung, der ausgesandt wurde, um den wachsenden Schatten in der Tiefschwarzen Grotte zu untersuchen. Schwer verwundet und ohne Kräfte ruft er in der Tiefe vorbeikommende Reisende auf, Kelris aufzuhalten.",al={"wer ist thaelrid","thaelrids geschichte","argentumwache"}},{q="Warum wird Zwielichtfürst Kelris gejagt?",a="Kelris führt die Anhänger des Schattenhammerkults in der Tiefschwarzen Grotte an. Er opfert unschuldige Gefangene an Aku'mai, eine mit den Alten Göttern verbundene abscheuliche Bestie, um unheilvolle Macht zu erlangen.",al={"wer ist kelris","warum kelris töten","zwielichtfürst kelris"}},{q="Wer ist Dämmerungsbehüter Selgorm?",a="Dämmerungsbehüter Selgorm ist ein Vertreter der Argentumdämmerung, der auf der Terrasse der Handwerker in Darnassus stationiert ist. Er beaufsichtigt die Bemühungen des Ordens gegen das vordringende Verderben im gesamten Norden Kalimdors.",al={"selgorm darnassus","wer ist selgorm","argentumdämmerung darnassus"}},{q="Welche Geschichte hat die Tiefschwarze Grotte?",a="Bevor die Tiefschwarze Grotte zu einem versunkenen Unterschlupf wurde, bargen ihre Höhlen einen großen, Elune geweihten Tempel der Nachtelfen. Der Tempel verfiel, nachdem die Bosheit eines Alten Gottes emporgestiegen war und seinen heiligen Mondbrunnen vergiftet hatte.",al={"bfd geschichte","was war die tiefschwarze grotte","tempel von elune bfd"}},{q="Wer ist Aku'mai?",a="Aku'mai ist ein monströser, hydraähnlicher Diener eines Alten Gottes, der aus den verseuchten Wassern unter der Tiefschwarzen Grotte kroch. Der Schattenhammerkult verehrt Aku'mai und verfüttert Gefangene an ihn, um dunklen Segen zu erhalten.",al={"was ist akumai","aku'mais geschichte","akumai bestie"}},{q="Warum arbeiten der Schattenhammerkult und die Naga zusammen?",a="Der Grund für den Pakt zwischen dem Schattenhammerkult und den Naga ist nicht vollständig bekannt. In der Tiefschwarzen Grotte haben sie sich verbündet, um das verfallene Tempelgelände zu besetzen, während der Kult Gefangene an Aku'mai opfert.",al={"bündnis von naga und kultisten","warum sind naga in bfd","schattenhammerkult und naga"}}},fx={["96533b2d"]={q="Warum will Argentumwache Thaelrid, dass Zwielichtfürst Kelris erschlagen wird?",a="Thaelrid hat aufgedeckt, dass Zwielichtfürst Kelris und seine Kultisten unschuldige Gefangene an Aku'mai, einen Diener eines Alten Gottes, opfern, um dafür dunkle Macht zu erhalten. Als Agent der Argentumdämmerung hat es sich Thaelrid zur Aufgabe gemacht, solch ein Übel zu stoppen und das grausame rituelle Schlachten zu beenden, das in dem zerstörten Tempel stattfindet.",al={"thaelrids beweggrund","warum will thaelrid kelris tot sehen","warum kelris töten"}},["101c08a2"]={q="Wozu dient Kelris Kopf?",a="Der Kopf dient als unbestreitbarer Beweis für das Ableben des Kultführers. Dämmerungsbehüter Selgorm und die Argentumdämmerung glaubten, Kelris sei nach Jahren schwer fassbarer Schurkereien in ganz Kalimdor tot oder verschwunden. Dass Ihr seinen Kopf zu Selgorm nach Darnassus bringt, bestätigt, dass seine Schreckensherrschaft und die Blutopfer endlich ein Ende gefunden haben.",al={"kelris kopf","warum brauche ich kelris kopf","was tun mit kelris kopf"}},["5d00ba2b"]={q="Warum kann Argentumwache Thaelrid Kelris nicht selbst erschlagen?",a="Thaelrid befindet sich tief in den überfluteten Ruinen, verwundet und völlig erschöpft. Seine Kraft hat ihn verlassen und er kann sich nicht durch die Kultisten und Naga kämpfen, geschweige denn Kelris allein niederstrecken. Er verlässt sich darauf, dass Ihr die Mission an seiner Stelle beendet.",al={"warum kämpft thaelrid nicht gegen kelris","warum braucht thaelrid mich","kann thaelrid kelris töten"}}},fp="20,235,19.384.0,23.362.0,20.369.1,29.203.0,43.180.0,27.192.0,41.201.0,15.200.0,56.215.0"}
P.entries["quest:1201"] = {n="Theramores Spione",s="In Dustwallow halten Horde und Allianz einen brüchigen Waffenstillstand, doch Scharmützel und verdeckte Aktionen gehen weiter. Nazeer Bloodpike will, dass Infiltratoren der Allianz östlich von Brackenwall aufgespürt und getötet werden.",h="In Dustwallow halten Horde und Allianz einen brüchigen Waffenstillstand, doch Scharmützel und verdeckte...",kw={"brackenwall","dustwallow","infiltratoren","nazeer bloodpike","spione","theramore"},sec={{t="Spione östlich des Dorfes",b="Spione der Allianz beobachten Brackenwall von den östlich gelegenen Inseln aus. Sie melden Bewegungen der Horde nach Theramore.\n\nNazeer Bloodpike, der Spionagemeister des Dorfes, schickt Euch los, um sie zu finden und zu töten. Ihre Vorgesetzten müssen erfahren, dass solche Spione unerwünscht sind."}},faq={{q="Wer befiehlt den Tod der Infiltratoren aus Theramore?",a="Nazeer Bloodpike, der Spionagemeister in Brackenwall, befiehlt, die Infiltratoren zu töten.",al={"wer vergibt die quest theramores spione","nazeer bloodpike spionagequest","wer startet theramores spione"}},{q="Wo verstecken sich die Infiltratoren?",a="Die Infiltratoren verstecken sich auf den Inseln östlich von Brackenwall.",al={"theramore infiltratoren fundort","wo theramores spione finden","infiltratoren fundorte dustwallow"}},{q="Warum beobachten die Spione Brackenwall?",a="Die Spione beobachten Brackenwall und melden Bewegungen der Horde nach Theramore.",al={"warum spionieren menschen brackenwall aus","brackenwall spione motiv"}},{q="Was folgt, nachdem die Spione erledigt sind?",a="Der nächste Schritt ist The Theramore Docks.",al={"theramores spione folgequest","welche quest folgt auf theramores spione"}}},fp="15,196,25.250.0,51.87.0,34.65.0,47.87.0,40.37.0"}
P.entries["quest:1202"] = {n="Die Docks von Theramore",s="An den Docks von Theramore liegen Papiere von einem Schiff unter Wasser. Nazeer Bloodpike schickt Euch, sie zu bergen, nachdem zwei Spione entdeckt wurden und sie ins Meer warfen.",h="An den Docks von Theramore liegen Papiere von einem Schiff unter Wasser.",kw={"brackenwall","captain-dokumente","docks","düstermarschen","schatulle","nazeer bloodpike","spione","theramore"},sec={{t="Papiere im Wasser",b="Nachdem Ihr Euch um die Theramore-Spione gekümmert habt, hört Ihr erneut von Nazeer Bloodpike. Zwei Spione begaben sich zu einem Schiff an den Docks von Theramore und nahmen dessen Papiere an sich. Sie wurden entdeckt und warfen die Papiere ins Meer. Ein Spion entkam und berichtete vom Scheitern, ohne die weggeworfenen Papiere bergen zu können."},{t="Unter den Docks",b="Die Captain-Dokumente liegen in einer Schatulle unter Wasser bei den Docks von Theramore. Ihr werdet ausgesandt, um sie zu bergen und zu Nazeer Bloodpike in Brackenwall zu bringen. Er sagt, die Papiere seien für die Stabilität der Allianz von großer Bedeutung. Damit sind sie auch für die Sicherheit der Horde wichtig."}},faq={{q="Wer schickt Euch zur Insel Theramore?",a="Nazeer Bloodpike schickt Euch von Brackenwall aus los.",al={"wer vergibt die quest","wo beginnt diese quest","questgeber"}},{q="Wonach sucht Ihr unter den Docks?",a="Ihr sucht nach einer Schatulle unter den Docks von Theramore. Sie enthält die Captain-Dokumente.",al={"was muss gefunden werden","welcher gegenstand liegt im wasser","questziel an den docks"}},{q="Warum wurden die Dokumente ins Wasser geworfen?",a="Die beiden Spione nahmen Papiere von einem Schiff an den Docks an sich, wurden aber entdeckt und mussten sie ins Meer werfen. Einer entkam ohne sie.",al={"warum sind die papiere im meer","wie kam die schatulle dorthin","warum ließen die spione sie fallen"}},{q="Warum will die Horde diese Dokumente?",a="Nazeer Bloodpike sagt, die Dokumente seien für die Stabilität der Allianz und somit für die Sicherheit der Horde von großer Bedeutung.",al={"warum sind die papiere wichtig","was steht in den dokumenten","warum will bloodpike sie"}},{q="Was kommt in der Geschichte davor?",a="Davor kommt Theramore-Spione, wo Ihr die Eindringlinge östlich von Brackenwall gejagt habt.",al={"vorausgesetzte quest","vorherige quest","was führt hierher"}}},fp="19,170,19.288.0,17.292.0,32.52.0,43.95.0,45.136.0,40.118.0,40.90.0"}
P.entries["quest:1203"] = {n="Jarl braucht eine Klinge",s="In den Düstermarschen braucht Jarl dringend eine Klinge zum Schneiden. „Sumpfauge“ Jarl will ein moonsteel broadsword und warnt Euch davor, zu trödeln.",h="In den Düstermarschen braucht Jarl dringend eine Klinge zum Schneiden.",kw={"düstermarschen","jarl","moonsteel broadsword","sumpfauge jarl","schwungklinge"},sec={{t="Eine bestimmte Klinge",b="„Sumpfauge“ Jarl hat etwas zu schneiden, behält den Zweck aber für sich. Er bittet um eine bestimmte Klinge, die manche moonsteel broadsword nennen und Jarl Schwungklinge nennt. Ihr könntet eine in der Stadt finden oder einen Schmied bitten, eigens eine anzufertigen. Jarl warnt Euch davor, es auf die lange Bank zu schieben; was auch immer geschnitten werden muss, wird sich nicht ewig halten."}},faq={{q="Wer bittet um die Klinge?",a="„Sumpfauge“ Jarl bittet in den Düstermarschen um die Klinge.",al={"wer vergibt jarl braucht eine klinge","wer ist jarl","sumpfauge jarl"}},{q="Welche Waffe benötigt Jarl?",a="Jarl benötigt ein moonsteel broadsword, das Jarl eine Schwungklinge nennt.",al={"welches schwert will jarl","jarl waffe","welche klinge braucht jarl"}},{q="Warum braucht Jarl so dringend eine Klinge?",a="Jarl hat etwas zu schneiden, will aber nicht sagen, was geschnitten werden muss. Jarl warnt, dass es sich nicht ewig halten wird.",al={"warum braucht jarl eine klinge","was schneidet jarl","jarl zweck"}},{q="Wo könnte man laut Jarl das Schwert finden?",a="Jarl sagt, Ihr könntet eines in der Stadt finden oder einen Schmied bitten, eigens eines anzufertigen.",al={"wie moonsteel broadsword für jarl bekommen","wo klinge für jarl finden"}}},fp="18,138,15.320.0,28.65.0,30.69.0,39.101.0,42.77.0"}
P.entries["quest:1204"] = {n="Schlammpanzersuppe mit Käfern",s="In Theramore hofft Morgan Stern, Sturmwind mit einem neuen Gericht zu begeistern. Der Marsch durch die Düstermarschen ist zu viel für Morgan Stern, also sammelt Ihr Mudrock-Zungen für Schlammpanzersuppe mit Käfern.",h="In Theramore hofft Morgan Stern, Sturmwind mit einem neuen Gericht zu begeistern.",kw={"blue recluse","käfer","düstermarschen","gespaltene zungen","morgan stern","mudrock","suppe","theramore"},sec={{t="Ein Gericht entsteht",b="Morgan Stern sammelt in Theramore Zutaten für ein neues Gericht. Morgan Stern rechnet nicht damit, einen langen Marsch durch die Düstermarschen zu überleben, also jagt Ihr Mudrock-Schildkröten. Zuerst werden ihre Zungen benötigt."},{t="Gespaltene Zungen",b="Mudrock-Schildkröten durchstreifen die Küste der Düstermarschen, vor allem rund um die Bucht. Morgan Stern möchte besonders gespaltene Zungen, denn sie sollen dem Gericht einen unverwechselbaren Geschmack verleihen."},{t="Auf den Tisch",b="Morgan Stern wird verschiedene Zubereitungsarten für die Zungen ausprobieren, um herauszufinden, welche ihren Geschmack am besten zur Geltung bringt. Morgan Stern hofft, ein Gericht zu kreieren, das des Blue Recluse in Sturmwind würdig ist."}},faq={{q="Wer bittet um die Schildkrötenzungen?",a="Morgan Stern in Theramore bereitet ein Gericht namens Schlammpanzersuppe mit Käfern zu.",al={"wer startet schlammpanzersuppe mit käfern","morgan stern theramore"}},{q="Wo sind die Mudrock-Schildkröten zu finden?",a="Mudrock-Schildkröten durchstreifen die Küste der Düstermarschen, vor allem rund um die Bucht.",al={"mudrock-schildkröten fundort","wo sind mudrocks"}},{q="Warum möchte Morgan Stern gerade gespaltene Zungen?",a="Morgan Stern hat gehört, dass gespaltene Zungen einen unverwechselbaren Geschmack haben, der für das Gericht erwünscht ist.",al={"warum gespaltene zungen","grund für gespaltene mudrock-zungen"}},{q="Warum sammelt Morgan Stern die Zutaten nicht persönlich?",a="Morgan Stern bezweifelt, einen langen Marsch durch die Düstermarschen zu überleben.",al={"warum jagt morgan stern nicht","morgan stern düstermarschen"}},{q="Was kommt nach dieser Quest?",a="Der nächste Schritt heißt ... and Bugs.",al={"nächste quest nach schlammpanzersuppe","schlammpanzersuppe folgequest"}}},fp="21,197,20.210.0,14.178.0,16.174.1,37.74.0,39.80.0,55.81.0,56.76.0,28.37.0"}
P.entries["quest:1205"] = {n="Schlammwühler",s="In den Düstermarschen suchen Jäger Deadmire in den Wasserläufen nördlich der Stonemaul Ruinen. Melor Steinhuf bittet Euch, einen Zahn des uralten Krokilisken zurückzubringen. Die Jagd lehrt Fährtenlesen und Gnade.",h="In den Düstermarschen suchen Jäger Deadmire in den Wasserläufen nördlich der Stonemaul Ruinen.",kw={"krokilisk","deadmire","düstermarschen","die anhöhe der jäger","melor steinhuf","die stonemaul ruinen","donnerfels"},ang={["class:Hunter"]="Als Jäger bringt Ihr jagdliches Können und spirituelle Verantwortung in Einklang. Ein ehrenvoller Tod kann ein Akt der Gnade sein.",["faction:Horde"]="Als Reisender der Horde nehmt Ihr an Jagden für die Ältesten von Donnerfels teil und lernt das Land und die Traditionen Eurer Taurenverbündeten kennen.",["race:Tauren"]="Als Tauren ehrt Ihr die Geschöpfe der Earth Mother und achtet die natürlichen Kreisläufe von Leben und Tod."},sec={{t="Eine Jagd aus Gnade",b="Von der Anhöhe der Jäger in Donnerfels schickt Melor Steinhuf Euch nach Osten in die Düstermarschen. Er lehrt vielversprechende Fährtenleser die spirituellen Traditionen der Jagd. Taurenjäger suchen Ehrfurcht und Verbundenheit mit der Natur, weder Gemetzel noch Trophäen. Dort sollt Ihr Deadmire finden, einen uralten Krokilisken, dessen langes Leben zur Last geworden ist."},{t="Der Uralte des Sumpfes",b="Nördlich der Stonemaul Ruinen durchstreift Deadmire als gewaltiger, bleicher Krokilisk die Wasserläufe. Seine Kraft und sein Zorn brechen noch immer plötzlich hervor, doch das Alter hat seinen Körper geschwächt. Mahlende Knochen verursachen unerbittliche Schmerzen. Melor bittet Euch, ihm ein schnelles, ehrenvolles Ende zu bereiten und einen Zahn als Zeichen seiner Erlösung zurückzubringen."}},faq={{q="Wer ist Deadmire?",a="Deadmire ist ein gewaltiger, uralter weißer Krokilisk in den Sümpfen der Düstermarschen. Er bleibt gefährlich, obwohl sein gealterter Körper versagt und ihm Schmerzen bereitet.",al={"was ist deadmire","deadmire hintergrundgeschichte","wer ist der krokilisk"}},{q="Warum will Melor Steinhuf Deadmire töten lassen?",a="Melor Steinhuf bittet Euch, Deadmire aus Gnade zu töten. Die alternden Knochen des Krokilisken bereiten ihm wahnsinnige Schmerzen, und Melor hält es für eine heilige Pflicht, seinen Geist zu erlösen.",al={"warum deadmire töten","melor steinhuf beweggrund","zweck der jagd auf deadmire"}},{q="Wo ist Deadmire zu finden?",a="Deadmire durchstreift die Wasserläufe nördlich der Stonemaul Ruinen in den Düstermarschen.",al={"wo ist deadmire","deadmire fundort","deadmire finden"}},{q="Welchen Beweis verlangt Melor von der Jagd?",a="Melor bittet Euch, einen von Deadmires Zähnen als Beweis für die Jagd zurückzubringen.",al={"deadmire questgegenstand","was will melor","deadmire beweis"}},{q="Was lehrt diese Jagd angehende Jäger?",a="Die Jagd lehrt Euch, dass die Berufung eines Jägers mehr bedeutet als Töten. Sie bedeutet, die Natur zu ehren und zu erkennen, wann das Leben einer Kreatur zum Leiden geworden ist.",al={"jagdphilosophie","jagdlehre der tauren","bedeutung der jagd"}},{q="Wer vergibt diese Quest?",a="Melor Steinhuf, ein Taurenjäger, bietet die Jagd auf der Anhöhe der Jäger in Donnerfels an.",al={"deadmire questgeber","wer startet deadmire","melor steinhuf aufenthaltsort"}}},fp="8,201,15.337.0,24.315.0,16.156.0,46.173.0,28.79.0,44.74.0,43.155.0,21.82.0"}
P.entries["quest:1206"] = {n="Jarl braucht Augen",s="Auf dem Swamplight-Anwesen sucht Jarl vierzig unzerplatzte Graunebelaugen wegen ihres milden, salzigen Safts. Die Spinnen leben in den Graunebelhöhlen, westlich des Anwesens.",h="Auf dem Swamplight-Anwesen sucht Jarl vierzig unzerplatzte Graunebelaugen wegen ihres milden, salzigen Safts.",kw={"graunebel","graunebelhöhlen","düstermarschen","jarl","spinnenaugen","sumpfauge jarl","swamplight-anwesen"},sec={{t="Eine Vorliebe für Spinnenaugen",b="Nach Soothing Spices wendet sich Jarl dem Augensaft zu, einem Getränk, das Jarl gern trinkt. Die meisten Kreaturen haben nur zwei Augen, doch Spinnen haben viele. Jarl mag den Geschmack von Graunebelaugensaft. Die Graunebelspinnen leben in den Graunebelhöhlen, westlich des Anwesens. Jarl fragt sich, ob die Höhle ihren Namen von den Spinnen hat oder die Spinnen von der Höhle."},{t="Ein Festmahl für Jarl",b="Jarl nimmt die Augen erfreut entgegen und nennt sie lecker. Jarl sagt, man solle alle Augen, die zurückstarren, wenn man sie anstarrt, bis zum Schluss aufheben, da sie einem im Sumpf Gesellschaft leisten können. Dann begrüßt Jarl die kleinen Augen, kostet sie und sagt, sie seien wie klebriges, salziges Hühnchen."}},faq={{q="Wer bittet um die Spinnenaugen?",a="„Sumpfauge“ Jarl bittet auf dem Swamplight-Anwesen in den Düstermarschen um die Augen.",al={"wer vergibt diese quest","jarl questgeber","sumpfauge jarl"}},{q="Warum möchte Jarl Spinnenaugen?",a="Jarl trinkt gern Augensaft und mag Graunebelaugensaft wegen seines milden, salzigen Geschmacks. Die meisten Kreaturen haben nur zwei Augen, während Spinnen viele haben.",al={"warum spinnenaugen","was macht jarl mit augen","augensaft"}},{q="Wo sind die Graunebelspinnen?",a="Die Graunebelspinnen leben in den Graunebelhöhlen, westlich des Swamplight-Anwesens.",al={"graunebelhöhlen lage","wo sind graunebelspinnen","wo augen finden"}},{q="Wie viele Augen möchte Jarl?",a="Jarl möchte vierzig unzerplatzte Graunebelaugen.",al={"wie viele augen","augenanzahl"}},{q="Was kommt davor?",a="Soothing Spices kam zuerst.",al={"vorherige quest","voraussetzung","was führt hierzu"}}},fp="15,147,23.326.0,16.254.1,29.79.0,31.148.0,31.71.0,29.40.0,23.27.0"}
P.entries["quest:121"] = {n="Botschaft nach Sturmwind",s="In Sturmwind übernehmt Ihr General Marcus Jonathans Antwort für Seenhain, das Schwarzfelsorcs und Gnolle bedrohen. Die Hauptstadt schickt keine Truppen, während ihre Anführer zögern und die Siedlung schutzlos bleibt.",h="In Sturmwind übernehmt Ihr General Marcus Jonathans Antwort für Seenhain, das Schwarzfelsorcs und Gnolle...",kw={"schwarzfelsorcs","bolvar","seenhain","magistrat solomon","marcus jonathan","botschaft nach sturmwind","rotkammgebirge","sturmwind"},ang={["faction:Alliance"]="Als Mitglied der Allianz seht Ihr, wie der politische Stillstand die menschlichen Gebiete des Königreichs regionalen Bedrohungen schutzlos aussetzt.",["race:Human"]="Als Mensch des Königreichs tragt Ihr diesen Schriftwechsel zwischen dem bewachten Sturmwind und den bröckelnden Grenzen seiner Nachbarn in Elwynn hin und her."},sec={{t="Eine Depesche nach Seenhain",b="Ihr habt Magistrat Solomons Bitte um Verstärkung zu General Marcus Jonathan in Sturmwind gebracht. Nun tragt Ihr seine erste Antwort zurück ins Rotkammgebirge, während er auf die Zustimmung des Throns wartet. Ohne königliche Erlaubnis kann der General die Armee nicht einsetzen. Seenhains Bürger haben weiterhin keine Stadtwachen, und mit jedem Tag droht die Siedlung dem Schwarzfelsklan näher zum Opfer zu fallen."},{t="Unruhe im Königreich",b="Magistrat Solomon findet in Jonathans Antwort kein Versprechen, dass Bataillone entlang der Grenze von Elwynn nach Osten marschieren werden. Der Brief bietet Verfahren statt Truppen, und Solomon ahnt Schwierigkeiten am königlichen Hof. König Varian Wrynn ist verschwunden, und die Regentschaft ist blockiert. Abgelegene Städte wie Seenhain müssen sich selbst verteidigen."}},faq={{q="Was steht in General Marcus Jonathans Antwort?",a="General Marcus Jonathan schreibt, dass er die Armee von Sturmwind ohne förmliche Genehmigung des Königs oder des königlichen Hofes nicht entsenden kann. Er hat die Angelegenheit der Krone vorgetragen, und Seenhain muss warten.",al={"was steht im brief","antwort des generals","brief von marcus jonathan"}},{q="Warum kann Sturmwind nicht einfach Soldaten ins Rotkammgebirge schicken?",a="Da König Varian Wrynn verschwunden ist, liegen die Regierungsentscheidungen beim jungen König Anduin, dem Regenten Lord Bolvar Fordragon und dem House of Nobles. Uneinigkeit und Verzögerungen in der Hauptstadt hindern General Jonathan daran, ohne königliche Zustimmung auszurücken.",al={"warum keine hilfe aus sturmwind","warum hilft sturmwind seenhain nicht","sturmwinds armee rotkammgebirge"}},{q="Wer ist Magistrat Solomon?",a="Magistrat Solomon regiert Seenhain und das Rotkammgebirge. Er führt die Siedlung und koordiniert ihre spärlichen Verteidigungskräfte gegen Schwarzfelsorcs, Gnolle und örtliche Wegelagerer.",al={"magistrat solomon","wer ist solomon","magistrat von seenhain"}},{q="Wer ist General Marcus Jonathan?",a="General Marcus Jonathan befehligt die Sturmwind City Guard und die stehenden Streitkräfte der Hauptstadt. Er ist im Tal der Helden stationiert, gleich hinter den Haupttoren von Sturmwind.",al={"wer ist marcus jonathan","general jonathan","general von sturmwind"}},{q="Was tut Solomon als Nächstes, nachdem er den Brief gelesen hat?",a="Nachdem Solomon den Brief gelesen hat, sucht er Hilfe in den benachbarten Regionen und schickt Euch los, um zu erfahren, wie es Westfall ergeht.",al={"was geschieht als nächstes","quest nach botschaft nach sturmwind","wohin als nächstes"}},{q="Warum sagt Solomon, dass „etwas in unserem Königreich nicht stimmt“?",a="Solomon sieht keinen militärischen Sinn darin, einer angegriffenen Grenzstadt Hilfe zu verweigern oder sie hinauszuzögern. Die Verzögerung warnt ihn, dass Sturmwinds politische Anführer von innen heraus manipuliert oder gelähmt werden.",al={"etwas stimmt nicht","warum ist solomon besorgt","verschwörung in sturmwind"}}},fx={["64d074bd"]={q="Warum vertraut General Jonathan Euch diesen Brief anstatt eines königlichen Kuriers an?",a="Ihr wart die Person, die Solomons ursprüngliches Gesuch aus dem Rotkammgebirge in das Tal der Helden brachte. Da die Stadtwache von Sturmwind bereits vollauf damit beschäftigt ist, die Ordnung aufrechtzuerhalten und die Stadttore zu bewachen, hält es General Jonathan für weitaus praktischer, einen fähigen Abenteurer zu schicken, der den Weg nach Seenhain kennt, anstatt eine seiner stationierten Wachen von ihrem Posten abzuziehen.",al={"warum schickt marcus jonathan mich","warum kein königlicher wachenkurier","warum abenteurerlieferung seenhain"}},["53d96341"]={q="Warum schickt Euch General Marcus Jonathan zurück nach Seenhain?",a="Magistrat Solomon hat Sturmwind dringend um militärische Verstärkung gebeten, um die Gnoll- und Orc-Bedrohungen abzuwehren, die Seenhain einkreisen. Während General Jonathan den Thron um Hilfe bat, kann er keine königlichen Truppen ohne Genehmigung der Krone entsenden. Er schickt Euch mit seiner offiziellen Antwort zurück, damit die Führung von Seenhain nicht im Dunkeln gelassen wird, während die königlichen Beratungen in der Hauptstadt ins Stocken geraten.",al={"warum schickt marcus jonathan den brief","marcus jonathan seenhain antwort","warum general jonathan dies erledigt haben muss"}}},fp="22,205,23.372.0,21.320.1,46.198.0,51.229.0,26.175.0,31.180.0,51.112.1,57.192.0"}
P.entries["quest:1218"] = {n="Feine Gewürze",s="In den Düstermarschen braucht Sumpfauge Jarl drei Beruhigende Gewürze für einen Eintopf.",h="In den Düstermarschen braucht Sumpfauge Jarl drei Beruhigende Gewürze für einen Eintopf.",kw={"düstermarschen","froschschenkel","feine gewürze","eintopf","sumpfauge jarl"},sec={{t="Gewürze für den Topf",b="Sumpfauge Jarl liebt die Sumpfküche, darunter auch gebratene grüne Froschschenkel. Jetzt plant Jarl einen Eintopf und braucht beruhigende Gewürze für den Topf. Bringt drei Beruhigende Gewürze, und Jarl wird den Eintopf mit Euch teilen. Ist Eintopf nach Eurem Geschmack?"}},faq={{q="Wer möchte die beruhigenden Gewürze?",a="Sumpfauge Jarl möchte die beruhigenden Gewürze. Jarl ist in den Düstermarschen zu finden.",al={"wer vergibt feine gewürze","questgeber feine gewürze","sumpfauge jarl gewürze"}},{q="Was will Sumpfauge Jarl mit den Gewürzen kochen?",a="Jarl plant, mit den Gewürzen einen Eintopf zu kochen und ihn mit Euch zu teilen. Jarl mag die Sumpfküche, darunter auch gebratene grüne Froschschenkel.",al={"was macht jarl","welchen eintopf kocht jarl","jarl essen"}},{q="Wie viele Gewürze braucht Jarl?",a="Jarl braucht drei Beruhigende Gewürze.",al={"wie viele beruhigende gewürze","beruhigende gewürze anzahl","beruhigende gewürze bedarf"}}},fp="15,77,17.225.0,30.78.0,56.124.0,31.33.0"}
P.entries["quest:1219"] = {n="Der Orc-Bericht",s="In den Düstermarschen findet Ihr eine abgetrennte Orchand, die eine Knochenröhre umklammert. Darin liegt ein schmutzbeflecktes Pergament auf Orcisch, das für einen Lieutenant von Theramore bestimmt ist.",h="In den Düstermarschen findet Ihr eine abgetrennte Orchand, die eine Knochenröhre umklammert.",kw={"knochenröhre","düstermarschen","lockeres erdreich","orc-bericht","lieutenant von theramore"},sec={{t="Eine Hand im Erdreich",b="Im lockeren Erdreich findet Ihr eine abgetrennte Orchand, die eine aus Knochen geschnitzte Röhre umklammert. Darin liegt ein schmutzbeflecktes Pergament auf Orcisch. Es scheint von Bedeutung zu sein, und Ihr solltet es einem Lieutenant von Theramore zeigen."},{t="Das Urteil des Lieutenants",b="Der Lieutenant von Theramore räumt ein, Orcisch nur schlecht lesen zu können. Dennoch hält der Lieutenant das Pergament für den Bericht eines Orcspions."}},faq={{q="Was verbirgt sich im lockeren Erdreich?",a="Im lockeren Erdreich findet Ihr eine abgetrennte Orchand, die eine aus Knochen geschnitzte Röhre umklammert. Darin liegt ein schmutzbeflecktes Pergament.",al={"was findet sich im lockeren erdreich","gegenstand im lockeren erdreich","orchand in den düstermarschen"}},{q="Wer sollte das Pergament erhalten?",a="Ein Lieutenant von Theramore sollte das Pergament erhalten.",al={"wohin mit dem bericht","wer bekommt den spionagebericht","standort des lieutenants von theramore"}},{q="In welcher Sprache ist das Pergament verfasst?",a="Das Pergament ist auf Orcisch verfasst, und seine Schrift scheint von Bedeutung zu sein.",al={"sprache des pergaments","pergament lesbar"}}},fp="14,152,18.209.0,24.124.1,33.117.0,29.52.0,42.70.0"}
P.entries["quest:122"] = {n="Bauchschuppen",s="Im Rotkammgebirge braucht Verner Gutmark Schuppen schwarzer Drachenwelpen, um seine Schulden bei Schmied Argus aus Goldhain zu begleichen. Ihr sammelt sie von jungen Drachen südlich von Seenhain, und die Schuppen begleichen Verners Rechnung, wobei Rohleder für ein Ausrüstungsteil übrig bleibt.",h="Im Rotkammgebirge braucht Verner Gutmark Schuppen schwarzer Drachenwelpen, um seine Schulden bei Schmied...",kw={"schwarzer drachenwelpe","drachenschwarm","goldhain","seenhain","rotkammgebirge","schmied argus","bauchschuppen","verner gutmark"},ang={["faction:Alliance"]="Die wachsende Bedrohung durch den Schwarzen Drachenschwarm südlich von Seenhain belastet die ohnehin überforderte Garnison des Rotkammgebirges zusätzlich.",["profession:Blacksmithing"]="Die Forderung von Schmied Argus zeigt, wie Schmiede mit seltenen Materialien wie Drachenschuppen Tauschhandel treiben, wenn Münzen knapp sind.",["race:Human"]="Als Mensch wisst Ihr, dass Handelswege zwischen Elwynn und dem Rotkammgebirge Orte wie Seenhain versorgen. Handwerker im Grenzland zahlen den Händlern aus den Städten oft hohe Preise."},sec={{t="Schulden im Grenzland",b="Verner Gutmark betreibt eine Schmiede außerhalb von Seenhain und handelt mit Handwerkern jenseits des Rotkammgebirges. Schmied Argus aus Goldhain hat ihm Hufeisen geschickt, doch Verner fehlt das Geld zum Bezahlen. Argus verlangt stattdessen Drachenleder: die weicheren Bauchschuppen der schwarzen Drachenwelpen in der Region. Ohne sie könnten Schuldeneintreiber aus dem Wald von Elwynn kommen, um die Schulden einzufordern."},{t="Brut des Schwarzen Schwarms",b="Schwarze Drachenwelpen machen den Verteidigern des Rotkammgebirges zu schaffen. Gnolle und Orcs kämpfen um die Straßen, während der Schwarze Drachenschwarm auf den hohen Gipfeln nistet. Seine Brut durchstreift die Lüfte südlich des Immerruhsees. Die Bauchschuppen der jungen Raubtiere sind zäh und dennoch geschmeidig, begehrt bei Rüstungsschmieden, Schmieden und Lederern im ganzen Königreich, die es wagen, sie zu erbeuten."}},faq={{q="Warum braucht Verner Gutmark Drachenschuppen?",a="Verner schuldet Schmied Argus aus Goldhain Geld für eine Lieferung Hufeisen. Argus verlangt Bauchschuppen schwarzer Drachenwelpen anstelle von Münzen, und Verner braucht sie rasch, bevor Schuldeneintreiber kommen, um die Schulden einzutreiben.",al={"warum drachenschuppen","verners schulden","argus schuppen"}},{q="Wo findet man die schwarzen Drachenwelpen im Rotkammgebirge?",a="Schwarze Drachenwelpen durchstreifen die felsigen Klippen und Täler südlich von Seenhain. Sie durchqueren die südlichen Ausläufer, und Jäger patrouillieren auf den Pfaden und Bergrücken, um sie im Flug zu erspähen.",al={"welpen fundorte","wo sind welpen","drachenwelpen fundort rotkammgebirge"}},{q="Wer ist Schmied Argus?",a="Schmied Argus ist der Schmied in Goldhain im Wald von Elwynn. Er beliefert nahe gelegene Siedlungen mit Metallarbeiten und Schmiedewaren, darunter die Hufeisen, die er Verner Gutmark im Rotkammgebirge geschickt hat.",al={"argus goldhain","wer ist argus","schmied argus"}},{q="Warum gibt es schwarze Drachenwelpen im Rotkammgebirge?",a="Der Schwarze Drachenschwarm ist in der gesamten Brennenden Steppe und auf den Gipfeln rund um das Rotkammgebirge präsent. Seine Welpen jagen und ziehen nach Süden durch die Gebirgspässe in die Ausläufer des Rotkammgebirges.",al={"warum gibt es drachen im rotkammgebirge","schwarze drachen rotkammgebirge","schwarzer schwarm rotkammgebirge"}},{q="Was macht Bauchschuppen besonders?",a="Bauchschuppen sind geschmeidig und biegsam, anders als die dicken, starren Schuppen auf dem Rücken eines Drachen. Sie widerstehen Hitze und Durchstichen und eignen sich dadurch für besondere Lederarbeiten, passgenaue Verstärkungen und exotische Handelswaren.",al={"warum bauchschuppen","wert der schuppen","qualität von drachenleder"}},{q="Führt das Begleichen dieser Schulden zu weiteren Aufgaben für Verner?",a="Nachdem Ihr Verner Gutmark seine Hufeisenlieferung gebracht habt, bittet er Euch um diese Schuppen. Neben dieser freiwilligen Sammelaufgabe schickt er Abenteurer auf die Jagd nach Gnollspähern und ihren Anführern, während die Bedrohung im Rotkammgebirge wächst.",al={"what comes next","verners questreihe","gutmark folgeaufgaben"}}},fx={["43de1078"]={q="Warum bittet Verner Euch, die Drachenwelpen zu jagen, anstatt es selbst zu tun?",a="Verner Gutmark ist damit beschäftigt, die geschäftigen Ställe und die Schmiede von Seenhain zu betreiben, während die örtlichen Wachen bis an ihre Grenzen damit ausgelastet sind, die Stadt gegen die umliegenden Überfälle von Gnollen und Orcs zu verteidigen. Für den Vorstoß in den Süden in die Hügel, um dort umherstreifende schwarze Drachenwelpen zu jagen, bedarf es geschickter Abenteurer, die gefährliche Wildtiere aufspüren können und in der Wildnis zurechtkommen.",al={"warum braucht verner mich","warum kann verner welpen nicht jagen","warum fragt man mich nach underbelly scales"}}},fp="17,238,15.359.0,25.366.0,42.209.0,52.172.0,19.186.0,50.191.0,37.228.0,55.201.0"}
P.entries["quest:1220"] = {n="Captain Mumm",s="Nahe Theramore schickt Euch Lieutenant Aden mit einem Orcbericht und der Nachricht von Hordenspionen zu Captain Garran Mumm.",h="Nahe Theramore schickt Euch Lieutenant Aden mit einem Orcbericht und der Nachricht von Hordenspionen zu...",kw={"captain mumm","düstermarschen","garran mumm","lieutenant aden","orcbericht","spionbericht","theramore","die insel theramore"},sec={{t="Ein Bericht für den Captain",b="Lieutenant Aden schickt Euch mit dem gefundenen Orcbericht zu Captain Garran Mumm. Mumm liest Orcisch besser als die meisten, deshalb möchte Aden ihn wissen lassen, dass Hordenspione nahe Theramore sind. Ihr findet Mumm bei der Kaserne im Nordosten der Insel Theramore."}},faq={{q="Wer schickt Euch zu Captain Mumm?",a="Lieutenant Aden schickt Euch in der Hoffnung, dass Captain Mumm den Orcbericht liest, den Ihr gefunden habt.",al={"wer startet captain mumm","wo gibt es captain mumm"}},{q="Wo befindet sich Captain Garran Mumm?",a="Captain Garran Mumm ist bei der Kaserne im Nordosten der Insel Theramore.",al={"wo ist captain mumm","captain mumm standort","mumm kaserne"}},{q="Warum muss Captain Mumm den Bericht sehen?",a="Aden sagt, Mumm liest Orcisch besser als die meisten. Er möchte, dass Mumm erfährt, dass Hordenspione nahe Theramore sind.",al={"warum captain mumm","warum braucht mumm den bericht"}}},fp="13,109,24.264.0,31.83.0,38.80.0,46.110.0"}
P.entries["quest:1221"] = {n="Blaulaubknollen",s="Mebok Mizzyrix schickt abgerichtete Gopher in den Kral der Klingenhauer, um Blaulaubknollen zu finden. Der Händler aus Ratschet sucht die vergrabene Delikatesse für den Handel.",h="Mebok Mizzyrix schickt abgerichtete Gopher in den Kral der Klingenhauer, um Blaulaubknollen zu finden.",kw={"blaulaubknollen","leitstecken","delikatesse","mebok mizzyrix","borstennacken","ratschet","kral der klingenhauer","schnüffelnasengopher","brachland"},ang={["faction:Alliance"]="Als Reisender der Allianz könnt Ihr Mizzyrix' Handelsvertrag im neutralen Ratschet nutzen, um ein Gebiet nahe den Landen der Horde zu betreten.",["faction:Horde"]="Als Krieger der Horde, der das Brachland gegen die Vorstöße der Borstennacken verteidigt, könnt Ihr Münzen verdienen, indem Ihr Mizzyrix' abgerichtete Gopher durch den Kral führt.",["profession:Cooking"]="Als Koch wisst Ihr, dass Blaulaubknollen zu Azeroths seltensten Delikatessen zählen. Erlesene Käufer schätzen ihren erdigen Geschmack.",["profession:Herbalism"]="Als Kräuterkundiger wisst Ihr, dass Blaulaubknollen unter der Erde zwischen den Dornenwurzeln von Razorfen wachsen, fern vom Sonnenlicht."},sec={{t="Eine begehrte unterirdische Delikatesse",b="Im Südlichen Brachland liegen Blaulaubknollen tief unter den Wurzeln des Krals der Klingenhauer. Ihre Seltenheit macht sie zu einer weltweit begehrten Delikatesse. Sie wachsen fern von offenen Feldern und gewöhnlichen wilden Hainen, weshalb Sammler unter der Erde suchen müssen."},{t="Mizzyrix' Einfallsreichtum",b="Mebok Mizzyrix, ein Händler in Ratschet, hat sich eine Methode ausgedacht, um vergrabene Knollen zu finden. Er richtet Schnüffelnasengopher darauf ab, die Witterung einer Knolle aus fünfzig Schritt Entfernung aufzunehmen. Sammler erhalten einen Leitstecken, eine belüftete Kiste und eine Anleitung, um die Geschöpfe durch das Gebiet der Borstennacken zu führen."},{t="Ernte in den Dornen",b="Die Ernte liegt im Gebiet des feindseligen Borstennackenstamms der Totenköpfe. Im Kral müsst Ihr Euren abgerichteten Gopher vor wilden Bestien und dornigem Gestrüpp beschützen und ihm dann befehlen, die vergrabenen Knollen auszugraben. Die Knollen werden nach Ratschet zurückgebracht, wo Mizzyrix' ausländische Käufer warten."}},faq={{q="Wofür werden Blaulaubknollen verwendet?",a="Blaulaubknollen sind eine seltene kulinarische Delikatesse, die auf der ganzen Welt begehrt ist. Wohlhabende Käufer zahlen gut für frische Knollen, was sie für Goblins wie Mebok Mizzyrix zu gewinnbringenden Handelswaren macht.",al={"blaulaubknolle verwendung","was sind blaulaubknollen","warum blaulaubknollen sammeln"}},{q="Wo findet man Blaulaubknollen?",a="Blaulaubknollen liegen unter der Erde und den dornigen Wurzeln des Südlichen Brachlands, in der Borstennackenfestung Kral der Klingenhauer.",al={"wo blaulaubknollen finden","blaulaubknollen fundort","wo wachsen sie"}},{q="Warum braucht Ihr einen Schnüffelnasengopher, um sie zu finden?",a="Die Knollen liegen unter der Erde, wo sie mit bloßem Auge nicht zu sehen sind. Ein Schnüffelnasengopher kann sie aus bis zu fünfzig Schritt Entfernung riechen und ausgraben.",al={"warum gopher einsetzen","schnüffelnasengopher zweck","wie finden gopher knollen"}},{q="Wer ist Mebok Mizzyrix?",a="Mebok Mizzyrix ist ein Goblinhändler in Ratschet, einer neutralen Hafenstadt im Brachland. Er richtet einheimische Wildtiere ab und beschafft exotische Waren für den Außenhandel.",al={"wer vergibt die quest blaulaubknollen","mebok mizzyrix hintergrundgeschichte","ratschet goblin questgeber"}},{q="Welche Ausrüstung stellt Mizzyrix für den Auftrag bereit?",a="Mizzyrix stellt eine Kiste mit Löchern samt abgerichtetem Gopher bereit, einen Schnüffelnasenleitstecken zum Lenken seiner Grabungen und eine Schnüffelnasenbesitzeranleitung zum Umgang mit dem Tier.",al={"knollen questgegenstände","gopher leitstecken","kiste mit löchern"}},{q="Warum kann Mebok die Knollen nicht selbst sammeln?",a="Der Kral der Klingenhauer wird von angriffslustigen Borstennackenstämmen, dornigen Ranken und gefährlichen Geschöpfen unter der Erde bewacht. Mizzyrix schickt andere in die Grabhügel, statt selbst das Risiko einzugehen.",al={"warum holt mebok sie nicht selbst","warum abenteurer anheuern"}}},fx={["8175ef8b"]={q="Warum möchte Mebok Mizzyrix Blaulaubknollen haben?",a="Mebok Mizzyrix treibt der reine Goblin-Handel an: Profit. Blaulaubknollen sind eine außergewöhnlich seltene Delikatesse in der ganzen Welt und finden sich ausschließlich tief unter der Erde im Kral der Klingenhauer. Da gewöhnliche Sammler sie nicht leicht ausfindig machen können, erzielen sie einen außerordentlichen Preis. Mebok beabsichtigt, alles, was Ihr zurückbringt, an seine wohlhabenden Kontakte für eine stattliche Summe zu verkaufen, und einen bescheidenen Teil des Erlöses mit Euch zu teilen, weil Ihr für ihre Beschaffung Leib und Leben riskiert.",al={"mebok mizzyrix motiv","warum will mebok knollen","warum blueleaf tubers sammeln"}},e7d11e5c={q="Wozu dient die Kiste mit Löchern?",a="Die Kiste mit Löchern ist ein spezieller Transportbehälter, den Mebok gebaut hat, um ein trainiertes Schnüffelnasennagetier zu halten. Die Luftlöcher sorgen dafür, dass das Tier lebt und bequem atmen kann, bis Ihr die Tiefen des Krals der Klingenhauer erreicht, wo Ihr es sicher freilassen könnt, damit es beginnt, die vergrabenen Knollen zu erschnüffeln.",al={"nutzen kiste mit löchern","was ist kiste mit löchern","warum kiste mit löchern"}},["91901628"]={q="Wozu dient der Schnüffelnasenleitstecken?",a="Der Leitstecken ist ein Trainingswerkzeug, das Mebok entwickelt hat, um das Schnüffelnasennagetier zu lenken. Ihn zu schwingen signalisiert dem Tier, seine feine Nase einzusetzen, den unmittelbaren Höhlenboden abzusuchen und alle versteckten Blaulaubknollen auszugraben, die es in der Nähe vergraben wittert.",al={"zweck leitstecken","was tut der schnüffelnasenleitstecken","schnüffelnasenleitstecken"}},af9e7fb9={q="Wozu dient die Schnüffelnasenbesitzeranleitung?",a="Die Anleitung enthält Meboks schriftliche Anweisungen, die beschreiben, wie man mit dem Gopher umgeht, ihn mit dem Befehlsstab lenkt und die Knollen erfolgreich freilegt, ohne seine abgerichtete Bestie in den Tunneln der Quilboar zu verlieren.",al={"zweck der schnüffelnasenbesitzeranleitung","wozu dient die besitzeranleitung","schnüffelnasenbesitzeranleitung"}}},fp="15,139,30.240.0,20.288.0,24.273.0,34.179.0,32.129.0,50.132.0,22.160.0,49.182.0,42.184.0"}
P.entries["quest:1222"] = {n="Stinkis Flucht",s="Im Sumpf sucht Stinki Ignatz nach Bogbean-Blättern für einen Koch in Theramore. Getier hat ihn umzingelt, und er bittet Euch, ihn zu beschützen, während er nach einer Pflanze sucht. Wenn er fertig ist, wartet Morgan Stern in Theramore.",h="Im Sumpf sucht Stinki Ignatz nach Bogbean-Blättern für einen Koch in Theramore.",kw={"blue recluse","bogbean","düstermarschen","morgan stern","stinki ignatz","theramore"},sec={{t="Umzingelt",b="Stinki Ignatz ist froh, jemanden zu finden, der ihn nicht als Mahlzeit betrachtet. Morgan Stern, ein Koch in Theramore, hat ihn losgeschickt, um Bogbean-Blätter für ein neues Rezept zu sammeln. Ignatz vermutet, dass Stern sie schmackhaft findet. Nun hat Getier ihn umzingelt, und er bittet Euch, ihm den Rücken freizuhalten, während er nach einer Bogbean-Pflanze sucht."},{t="Ein wartender Koch",b="Morgan Stern, ein Koch in Theramore, ist besorgt. Ignatz ist vor einer Weile in den Sumpf aufgebrochen und noch nicht zurückgekehrt."},{t="Dank vom Koch",b="Morgan Stern sagt, Ignatz habe die Bogbean-Blätter gebracht und ihm erzählt, wie Ihr ihm aus der Not geholfen habt. Zum Dank wird Stern einen Onkel bitten, Euch bei Eurem nächsten Besuch im Blue Recluse in Sturmwind ein Festmahl zu spendieren."}},faq={{q="Wer ist Stinki Ignatz?",a="Morgan Stern, ein Koch, hat Stinki Ignatz in den Sumpf geschickt, um Bogbean-Blätter zu sammeln.",al={"stinki ignatz","wer ist stinki","ignatz dustwallow"}},{q="Warum steckt Ignatz in Schwierigkeiten?",a="Getier hat Ignatz umzingelt, während er nach einer Bogbean-Pflanze suchte.",al={"warum sitzt stinki in der falle","ignatz gestrandet","warum ist stinki in dustwallow"}},{q="Wozu dienen Bogbean-Blätter?",a="Morgan Stern arbeitet an einem neuen Rezept und hat Ignatz losgeschickt, um Bogbean-Blätter zu sammeln. Ignatz vermutet, dass Stern sie schmackhaft findet.",al={"bogbean-blätter","was sind bogbeans","bogbean-pflanze"}},{q="Wer ist Morgan Stern?",a="Morgan Stern ist ein Koch in Theramore und arbeitet an einem neuen Rezept.",al={"morgan stern theramore","wer ist morgan stern","koch morgan stern"}}},fp="15,228,10.304.0,14.107.0,20.209.1,23.83.0,25.65.0,28.120.0,20.71.0"}
P.entries["quest:123"] = {n="Der Sammler",s="Im Wald von Elwynn verlassen Goldlieferungen die verlassenen Minen im Schutz von Gnollüberfällen. Eine abgefangene Depesche nennt ihren Aufseher 'den Sammler' und deutet auf ein organisiertes Unternehmen nahe der Garnison von Sturmwind hin.",h="Im Wald von Elwynn verlassen Goldlieferungen die verlassenen Minen im Schutz von Gnollüberfällen.",kw={"brackbrunns kürbisbeet","wald von elwynn","goldabholplan","goldhain","manhunt","marschall dughan","minen","der sammler"},ang={["class:Rogue"]="Als Schurke könnt Ihr den abgefangenen Plan lesen und Schmuggelware durch die Verbrechernetzwerke in Elwynns Wildnis verfolgen.",["faction:Alliance"]="Jede aus Elwynn geschmuggelte Unze Gold entzieht der Krone Steuereinnahmen und Rohstoffe, während das Königreich darum ringt, seine Grenzen zu schützen.",["profession:Mining"]="Als Bergmann wisst Ihr, dass Elwynns stillgelegte Minen noch immer Kupfer und Edelmetalle bergen. Jemand baut diese Adern unrechtmäßig ab, während ehrliche Bergleute aus Angst zu Hause bleiben."},sec={{t="Eine Papierspur in Gnollpfoten",b="Flusspfotengnolle im westlichen Wald von Elwynn tragen ein Pergament namens Goldabholplan bei sich. Es legt Tage und Uhrzeiten für Gold aus den örtlichen Minen fest. Die abgefangene Notiz weist an, jede Lieferung einem Aufseher zu übergeben, der nur als 'der Sammler' bekannt ist."},{t="Beunruhigende Nachrichten für Goldhain",b="Im Gasthaus \"Zur Höhle des Löwen\" erfährt Marschall Dughan, dass noch immer Gold abgebaut und transportiert wird. Die offiziellen Minen in ganz Elwynn sind seit Monaten wegen Gnollangriffen, Koboldbefall und umherstreifenden Banditen geschlossen. Gnolle mit Lieferplänen deuten auf ein organisiertes Verbrechernetz hin, das den Reichtum des Königreichs stiehlt."},{t="Das Beet bei Brackwell im Blick",b="Der Plan verortet den mutmaßlichen Sammler nahe Brackbrunns Kürbisbeet im östlichen Wald von Elwynn. Marschall Dughan hat den Namen schon flüstern hören, doch ihm fehlen klare Beweise dafür, wer den Ring anführt oder wohin das Gold gelangt. Die Depesche liefert der Garnison die erste handfeste Spur bei der Suche nach dem Drahtzieher hinter den Lieferungen."}},faq={{q="Was ist der Goldabholplan?",a="Der Goldabholplan ist eine abgefangene Notiz, die Gnolle im Wald von Elwynn bei sich tragen. Sie führt Tage und Uhrzeiten auf, zu denen abgebautes Gold einer Gestalt namens 'der Sammler' übergeben werden soll.",al={"abholplan","notiz des sammlers","elwynn goldabholplan"}},{q="Wer ist 'der Sammler'?",a="'Der Sammler' ist eine verbrecherische Gestalt, die nahe Brackbrunns Kürbisbeet im östlichen Wald von Elwynn vermutet wird und einen illegalen Goldhandel koordiniert.",al={"identität des sammlers","wer ist der sammler","brackwell sammler"}},{q="Warum ist Marschall Dughan über den Plan erschüttert?",a="Marschall Dughan ist erschüttert, weil noch immer Gold abgebaut und verschickt wird, obwohl die offiziellen Minen seit Monaten geschlossen sind. Gnollangriffe, Koboldbefall und umherstreifende Banditen erzwangen die Schließungen, also enthüllt der Plan ein verborgenes Unternehmen, das die Krone bestiehlt.",al={"warum ist dughan überrascht","dughans reaktion","elwynn minen geschlossen"}},{q="Warum haben Gnolle diese Notiz?",a="Die Flusspfotengnolle im westlichen Elwynn tragen den Plan offenbar als Kuriere, Wachen oder Helfer beim Goldschmuggel bei sich und überbringen Anweisungen für die Abholungen.",al={"gnolle gold","warum lassen gnolle den plan fallen","beteiligung der gnolle"}},{q="Wohin führt diese Ermittlung als Nächstes?",a="Wenn Ihr Marschall Dughan den Plan übergebt, führt das zu Manhunt, bei dem Ihr den Sammler nahe Brackbrunns Kürbisbeet finden und ausschalten sollt.",al={"sammler folgequest","manhunt quest","nach dem sammler"}},{q="Wo liegt Brackbrunns Kürbisbeet?",a="Brackbrunns Kürbisbeet liegt im östlichen Wald von Elwynn, nördlich des Flusses und östlich der Weinberge von Maclure und Stonefield.",al={"brackwell lage","wo ist brackwell","kürbisbeet elwynn"}}},fp="13,214,35.237.0,29.314.0,27.320.1,33.177.0,23.146.0,46.268.0,29.159.0,40.141.0,45.127.0"}
P.entries["quest:1238"] = {n="Der verlorene Bericht",s="In den Düstermarschen entdeckt Ihr einen Spionagebericht, der für Brackenwall bestimmt ist. Die abgetrennte Hand eines Orcs umklammert eine Knochenröhre mit einem erdbefleckten Bericht über wochenlange Beobachtungen von Theramore.",h="In den Düstermarschen entdeckt Ihr einen Spionagebericht, der für Brackenwall bestimmt ist.",kw={"brackenwall","düstermarschen","lockere erde","nazeer bloodpike","spionagebericht","der verlorene bericht","theramore"},sec={{t="Eine Hand in der Erde",b="Ihr findet die abgetrennte Hand eines Orcs in lockerer Erde, ihre Finger um eine aus Knochen geschnitzte Röhre geschlossen. Darin liegt ein erdbeflecktes Pergament. Es berichtet nach wochenlanger Spionage über Theramore und ist für Nazeer Bloodpike bestimmt, den Spionagemeister der Orcs in Brackenwall."},{t="Worte des Spionagemeisters",b="Nazeer Bloodpike nennt Marg Nighteye als Verfasser des Berichts. Marg war ein Agent, der außerhalb von Theramore stationiert war, um die Stadt zu beobachten. Dies ist Margs neuester Bericht und vielleicht sein letzter. Nach dem, was Ihr ihm erzählt, fürchtet Bloodpike, dass Marg im Sumpf den Tod fand."}},faq={{q="Wo findet man den Bericht?",a="Ihr findet den Bericht in lockerer Erde in den Düstermarschen, umklammert von einer abgetrennten Orchand.",al={"wo ist der bericht","fundort des verlorenen berichts","wie beginnt der verlorene bericht"}},{q="Wovon handelt der Bericht?",a="Ein Orc schrieb den Bericht, nachdem er Theramore wochenlang ausspioniert hatte.",al={"was steht im bericht","was sagt der spionagebericht","inhalt des pergaments"}},{q="Wer erhält den Bericht?",a="Der Bericht geht an Nazeer Bloodpike, den Spionagemeister der Orcs in Brackenwall.",al={"bei wem den bericht abgeben","verlorenen bericht abgeben","wohin den spionagebericht bringen"}}},fp="15,184,18.259.0,23.247.1,26.86.0,25.60.0,20.80.0"}
P.entries["quest:1239"] = {n="Der abgetrennte Kopf",s="In den Düstermarschen entdeckt Ihr den abgetrennten Kopf eines männlichen Orcs. Bringt ihn zu Nazeer Bloodpike in Brackenwall.",h="In den Düstermarschen entdeckt Ihr den abgetrennten Kopf eines männlichen Orcs.",kw={"brackenwall","trotziger orckopf","düstermarschen","lockere erde","marg nighteye","nazeer bloodpike","abgetrennter kopf"},sec={{t="Ein grausiger Fund",b="Euer Graben bringt den Kopf eines männlichen Orcs zum Vorschein, zerfetzt an der Stelle, an der er vom Hals abgetrennt wurde. Seine Lippen sind zu einem Knurren verzogen, und dunkle Augen blicken trotzig drein. Bringt den Kopf zu Nazeer Bloodpike in Brackenwall."},{t="Nazeer sieht genauer hin",b="Nazeer Bloodpike erkennt Marg Nighteyes Kopf sofort, obwohl er befürchtet hatte, dass Marg tot sei. Die zerfetzte Wunde lässt ihn rätseln, ob eine Waffe den Schnitt verursachte oder eine Bestie den Agenten tötete. Nazeer will das Rätsel lösen und erfahren, ob die Allianz hinter Margs Tod steckte."}},faq={{q="Wohin bringt Ihr den abgetrennten Kopf?",a="Bringt den abgetrennten Kopf zu Nazeer Bloodpike in Brackenwall.",al={"wo abgetrennten kopf abgeben","abgetrennten kopf abgeben","wer nimmt den kopf an"}},{q="Wie sieht der Kopf aus?",a="Es ist der Kopf eines männlichen Orcs, zerfetzt an der Stelle, an der er vom Hals abgetrennt wurde, mit zu einem Knurren verzogenen Lippen und trotzig blickenden dunklen Augen.",al={"was ist in der lockeren erde","trotziger orckopf","beschreibung des abgetrennten kopfes"}},{q="Was folgt auf den abgetrennten Kopf?",a="Der nächste Schritt ist The Troll Witchdoctor.",al={"nächste quest nach dem abgetrennten kopf","folgequest zum abgetrennten kopf"}}},fp="16,112,11.195.0,19.280.1,36.66.0,29.123.0,34.39.0"}
P.entries["quest:124"] = {n="Das Bellen der Gnolle",s="Gnolle haben Verner Gutmarks Stall in Seenhain erreicht, wo Schwarzfelsorcs die Region bereits bedrohen. Verner bittet Euch, die Schläger und Mystiker zu vertreiben, die seine Pferde gefährden.",h="Gnolle haben Verner Gutmarks Stall in Seenhain erreicht, wo Schwarzfelsorcs die Region bereits bedrohen.",kw={"gnolle","pferde","seenhain","schläger des rotkammgebirges","rotkammgebirge","mystiker des rotkammgebirges","ställe","verner gutmark"},ang={["class:Hunter"]="Als Jäger steht Ihr im Rotkammgebirge wilden Bestien und verwilderten Rudeln gegenüber, die ohne gezielte Bejagung kühn geworden sind. Sie bedrohen Haustiere und Reisende.",["faction:Alliance"]="Sturmwinds Vernachlässigung belastet kleine Gemeinden im gesamten Süden des Königreichs. Gewerbetreibende wie Verner müssen private Helfer anheuern, um lebenswichtige Versorgungswege zu schützen."},sec={{t="Pferde auf dem Bergkamm",b="Die Arbeit in Verner Gutmarks Stall in Seenhain ist gefährlich geworden. Schwarzfelsorcs halten die Höhen, während Gnollrudel die Bergkämme rund um die Stadt durchstreifen. Nun haben Gnollräuber den nördlichen Rand von Verners Koppeln erreicht. Sie machen Jagd auf Pferde, die sich zu nahe an die Klippen wagen."},{t="Eine vereinte Bedrohung",b="Nördlich von Seenhain setzen Gnollrudel rohe Gewalt und primitive Zauberkunst ein. Ihre Schläger überwältigen ihre Beute, während Mystiker wilde Magie gegen Eindringlinge richten. Ihre Reihen zu lichten verschafft der Siedlung eine kurze Atempause. Doch die Angriffslust der Gnolle deutet auf eine größere Macht weiter oben in den Hügeln hin."}},faq={{q="Warum braucht Verner Gutmark Hilfe gegen die Gnolle?",a="Gnolle von den nördlichen Bergkämmen dringen inzwischen bis zu Verners Ställen vor und reißen Pferde, die sich von den Koppeln entfernen. Da auch Schwarzfelsorcs die Region bedrohen, kann er seine Tiere nicht allein schützen.",al={"verners problem","warum verner gnolle töten lassen will","seenhain stall gnolle"}},{q="Wo befinden sich diese Gnolle?",a="Schläger und Mystiker des Rotkammgebirges durchstreifen die hoch gelegenen Bergkämme und Ausläufer unmittelbar nördlich und östlich von Seenhain. Von dort überblicken sie die Stadt und die Straße zur Everstill Bridge.",al={"wo sind die schläger des rotkammgebirges","mystiker des rotkammgebirges fundort","gnolle nördlich der ställe"}},{q="Warum sind neben den Schwarzfelsorcs auch Gnolle ein Problem?",a="Schwarzfelsorcs sind die größte militärische Bedrohung im Rotkammgebirge, und die örtlichen Gnollrudel nutzen die Ablenkung aus. Seenhains Verteidiger sind überlastet, während Sturmwind nur wenig Verstärkung schickt. So dringen die Raubtiere bis an den Dorfrand vor.",al={"orcs und gnolle rotkammgebirge","warum sowohl gnolle als auch orcs"}},{q="Was folgt, nachdem diese Gnolle bekämpft wurden?",a="Selbst nachdem die Reihen der Schläger und Mystiker gelichtet wurden, ist weiter Heulen in den Hügeln zu hören. Es deutet auf eine größere Bedrohung durch ihre Anführer in den umliegenden Höhen hin.",al={"das bellen der gnolle folgequest","was folgt nach das bellen der gnolle"}},{q="Warum sind Mystiker besonders gefährlich?",a="Die Mystiker des Rotkammgebirges nutzen einfache Natur- und Elementarmagie. Ihre unberechenbaren, wilden Beschwörungen machen sie für Eindringlinge gefährlich. Ihre Anwesenheit unter den Schlägern deutet auf einen organisierten Klan hin statt auf einzelne Aasfresser.",al={"mystiker des rotkammgebirges hintergrund","gnollschamanen rotkammgebirge"}},{q="Schickt Sturmwind Soldaten, um Seenhains Ställe zu schützen?",a="Nein. Sturmwinds Königshof hat das Rotkammgebirge angesichts politischer Unruhen und Truppenmangels weitgehend seiner eigenen Verteidigung überlassen. Magistrat Solomon und Bürger wie Verner Gutmark müssen umherziehende Abenteurer anwerben.",al={"sturmwinder wache rotkammgebirge","warum keine wachen verner helfen"}}},fx={["114f5694"]={q="Wer sind die Gnolle, die Verners Pferde bedrohen?",a="Ihr werdet gegen die Rotkammbruten und Mystiker ausgesandt, die direkt nördlich von Verner Gutmarks Ställen in den Hügeln herumstreifen. Diese wilden Hyänenmenschen bewohnen die Bergrücken oberhalb von Seenhain und nutzen die Ablenkung der Stadt, um unvorsichtiges Vieh zu rauben und die örtlichen Gehöfte zu terrorisieren.",al={"rotkammgnolle","rotkammbruten und mystiker","welche gnolle greifen seenhain an"}}},fp="18,187,19.275.0,20.298.1,45.204.0,31.182.0,53.252.0,43.147.1,39.208.0,61.203.0"}
P.entries["quest:1240"] = {n="Der Troll-Hexendoktor",s="Nazeer Bloodpike sucht durch die Hexenmagie der Trolle nach der Wahrheit über Marg Nighteyes Tod. Ihr bringt Margs Kopf zu Kin'weelay ins Basislager Grom'gol im Schlingendorntal.",h="Nazeer Bloodpike sucht durch die Hexenmagie der Trolle nach der Wahrheit über Marg Nighteyes Tod.",kw={"hexendoktor der dunkelspeere","kopf eines trotzigen orcs","basislager grom'gol","kin'weelay","marg nighteye","nazeer bloodpike","schlingendorntal"},sec={{t="Hexenmagie der Trolle",b="Nazeer Bloodpike besteht darauf, dass die Wahrheit über Margs Tod ans Licht kommen muss. Er sagt, nur die Hexenmagie der Trolle könne enthüllen, was geschehen ist. Also bringt Ihr Margs Kopf zu Kin'weelay ins Basislager Grom'gol im Schlingendorntal. Kein Hexendoktor der Dunkelspeere ist mächtiger als Kin'weelay, und Nazeer glaubt, dass Kin'weelay Margs Geist erreichen kann."},{t="Worte in Grom'gol",b="In Grom'gol spürt Kin'weelay einen zornigen Geist. Der Hexendoktor untersucht den Kopf und erkennt, dass der Geist des Orcs an diese Welt gebunden bleibt. Er wütet wegen einer unerfüllten Pflicht. Kin'weelay schlägt vor, mit ihm zu sprechen."}},faq={{q="Warum muss Marg Nighteyes Kopf ins Schlingendorntal gebracht werden?",a="Nazeer Bloodpike sagt, nur die Hexenmagie der Trolle könne die Umstände von Marg Nighteyes Tod enthüllen. Kin'weelay befindet sich im Basislager Grom'gol im Schlingendorntal.",al={"warum ins schlingendorntal","warum grom'gol","warum kin'weelay"}},{q="Wer ist Kin'weelay?",a="Kin'weelay ist der mächtigste Hexendoktor unter den Dunkelspeertrollen. Kin'weelay ist im Basislager Grom'gol im Schlingendorntal zu finden.",al={"wer ist der hexendoktor","hexendoktor kin'weelay"}},{q="Was folgt auf diesen Schritt?",a="Als Nächstes folgt Marg Speaks.",al={"welche quest kommt als nächstes","nach dem troll-hexendoktor"}}},fp="21,168,25.324.0,17.212.1,61.158.0,18.136.0,27.23.0"}
P.entries["quest:1241"] = {n="Der vermisste Diplomat",s="In Sturmwind beginnen eilige Nachforschungen, als ein Diplomat nicht auf der Insel Theramore eintrifft. Bischof DeLavey vermutet ein böses Spiel der Defias und schickt vertrauenswürdige Mittelsmänner zu Jorgen, einem diskreten Kontaktmann im Tal der Helden.",h="In Sturmwind beginnen eilige Nachforschungen, als ein Diplomat nicht auf der Insel Theramore eintrifft.",kw={"defias","delavey","jaina","jorgen","vermisster diplomat","sturmwind","theramore","das tal der helden"},ang={["class:Priest"]="Bischof DeLavey nutzt kirchliche Verbindungen, um heimlich Staatsverbrechen zu untersuchen, wenn die üblichen königlichen Dienstwege möglicherweise unterwandert sind.",["class:Rogue"]="Jorgen ist ein langjähriger Kontaktmann, dessen unauffälliges Auftreten hilft, vermisste Gesandte durch die verborgene Spionagewelt unter Sturmwinds makellosen Straßen aufzuspüren.",["faction:Alliance"]="Der vermisste königliche Diplomat gefährdet heikle Verhandlungen zwischen Sturmwind und Lady Jaina Prachtmeers Außenposten in Theramore.",["race:Human"]="Die Bedrohung durch die Bruderschaft der Defias reicht über Westfall hinaus bis in die Hauptstadt und gefährdet die Stabilität des Menschenkönigreichs."},sec={{t="Verschwinden im Schatten",b="Ein hochrangiger Diplomat segelte von den Östlichen Königreichen zur Insel Theramore, um dort heikle Gespräche mit Lady Jaina Prachtmeer zu führen. Der Diplomat traf nie ein. Königliche Ermittler suchen in Sturmwind nach Hinweisen. Das Verschwinden bleibt geheim, um Panik zu verhindern und die Verschwörer nicht wissen zu lassen, dass die Krone wachsam ist."},{t="Diskrete Nachforschungen",b="Bischof DeLavey glaubt, dass die Bruderschaft der Defias den Diplomaten entführt hat, doch er verlässt sich nicht allein auf die Garde des Königs. Er wendet sich an diskrete Kontakte und sucht Jorgen auf, einen alten Bekannten, der unauffällig im Tal der Helden angelt. Jorgen befindet sich gleich hinter den Stadttoren."},{t="Ein widerwilliger Informant",b="Jorgen gibt sich schroff und hält sich an einem unscheinbaren Platz an den Gewässern der Stadt auf, doch er erfüllt alte Verpflichtungen gegenüber DeLavey. Er warnt davor, dass es tödliche Risiken birgt, den Weg des Diplomaten nachzuverfolgen. Jeder, der in die Nachforschungen hineingezogen wird, muss schweigen."}},faq={{q="Wer ist der vermisste Diplomat?",a="Die Kirche des Lichts und der Thron von Sturmwind halten die Identität des Diplomaten geheim. Sie sprechen von ihm nur als einem wichtigen Diplomaten, der über das große Meer nach Theramore entsandt wurde.",al={"identität des vermissten diplomaten","wer ist verschwunden","wer verschwand","identität des diplomaten"}},{q="Warum reiste der Diplomat nach Theramore?",a="Der Diplomat wurde zu Lady Jaina Prachtmeer geschickt, um entscheidende Gespräche über die Sicherheit und den Zustand der Allianz zwischen den Östlichen Königreichen und Kalimdor zu führen.",al={"warum theramore","auftrag des diplomaten","was tat der diplomat"}},{q="Wen verdächtigt Bischof DeLavey?",a="Bischof DeLavey vermutet, dass die Bruderschaft der Defias den Diplomaten entführt hat. Ihre Methoden und ihre Komplizen in der Stadt bleiben unbekannt.",al={"wer nahm den diplomaten mit","wen verdächtigt delavey","wer entführte den diplomaten"}},{q="Wer ist Jorgen?",a="Jorgen ist ein Mittelsmann und langjähriger persönlicher Kontakt von Bischof DeLavey. Er angelt im Tal der Helden in Sturmwind, gleich hinter den Stadttoren.",al={"wo ist jorgen","jorgens identität","wer ist der angler"}},{q="Warum wird die Angelegenheit vor der Öffentlichkeit geheim gehalten?",a="Die Behörden halten die Angelegenheit geheim, weil es Chaos auslösen könnte, wenn die Entführung eines wichtigen Gesandten direkt vor den Augen des Throns bekannt würde. Es könnte auch die Verschwörer darauf aufmerksam machen, dass königliche Agenten sie jagen.",al={"warum geheimhaltung","warum geheim halten","warum die stadt nicht informieren"}},{q="Wohin führen diese Ermittlungen?",a="Jorgen lenkt die Nachforschungen auf Sturmwinds Unterwelt und verborgene Netzwerke, um herauszufinden, wo der Diplomat abgefangen wurde.",al={"was geschieht als nächstes","wohin nach jorgen"}}},fx={["02dad4d3"]={q="Warum benötigt Bischof DeLavey einen Abenteurer anstelle der königlichen Wache?",a="Die Agenten des Königs durchkämmen bereits Sturmwind, aber Bischof DeLavey zieht es vor, seine eigenen diskreten Wege außerhalb der offiziellen königlichen Aufsicht zu gehen. Die Beauftragung eines privaten Kuriers ermöglicht es ihm, unabhängige Kontakte wie Jorgen einzubinden, ohne die Aufmerksamkeit der Öffentlichkeit zu erregen oder Verschwörer innerhalb der Stadt zu alarmieren.",al={"warum ich vermisster diplomat","warum keine stadtwachen vermisster diplomat","bischof delavey warum ich"}}},fp="20,213,26.310.0,17.285.0,21.223.1,28.163.0,44.158.0,32.127.0,14.144.0,46.205.0,35.125.0"}
P.entries["quest:1242"] = {n="Der vermisste Diplomat",s="Jorgen schickt Vertraute mit einer versiegelten Notiz für Elling Trias quer durch Sturmwind. Vom Tal der Helden bis zu Trias' Käseladen im Handelsdistrikt bringt die Zustellung die Suche nach dem vermissten Diplomaten voran.",h="Jorgen schickt Vertraute mit einer versiegelten Notiz für Elling Trias quer durch Sturmwind.",kw={"elling trias","jorgen","vermisster diplomat","versiegelte notiz","sturmwind","der handelsdistrikt","trias käseladen"},ang={["class:Rogue"]="Als Schurke vermutet Ihr vielleicht, dass Trias' Käseladen mehr ist als ein Geschäft für Milchprodukte. Sein Besitzer pflegt verschwiegene Kontakte weit über den Handelsdistrikt hinaus.",["faction:Alliance"]="Als Mitglied der Allianz könnt Ihr erkennen, wie die diskrete Suche nach dem vermissten Gesandten verborgene Schwachstellen in Sturmwinds Führung offenbart."},sec={{t="Eine diskrete Zustellung",b="Nach den ersten Nachforschungen zum Verschwinden des Diplomaten bittet Jorgen Vertraute, zu schweigen und eine versiegelte Notiz quer durch Sturmwind zu tragen. Ihr Ziel ist Trias' Käseladen im Handelsdistrikt, keine Kaserne und kein Büro eines Magistrats. Während die Sorge über den Palast hinaus um sich greift, umgeht die Übergabe die üblichen Wege der Wache."},{t="Hinter der Ladentheke",b="Elling Trias ist ein fröhlicher und fleißiger Käsehändler in Trias' Käseladen und ein angesehener Kaufmann. Seine Verbindungen zu Jorgen und seine eigenen Kontakte reichen über den Laden hinaus. Sobald Jorgens Notiz eintrifft, nimmt Trias die Suche nach dem vermissten Diplomaten stillschweigend in die Hand."}},faq={{q="Wer ist Elling Trias?",a="Elling Trias ist ein angesehener Kaufmann, der Trias' Käseladen im Handelsdistrikt von Sturmwind betreibt. Ihn verbindet eine gemeinsame Vergangenheit mit Jorgen, und er hat Kontakte für heikle Angelegenheiten.",al={"wer ist trias","käseverkäufer","elling trias identität"}},{q="Warum sagt Jorgen mir, ich solle schweigen?",a="Jorgen verlangt Schweigen, weil das Verschwinden des Diplomaten ein Staatsgeheimnis ist. Gerüchte könnten Panik auslösen oder die Drahtzieher der Entführung warnen und ihnen verraten, dass Ermittlungen laufen.",al={"warum schweigen","jorgens warnung","den mund halten"}},{q="Wo finde ich Trias' Käseladen?",a="Trias' Käseladen liegt im Handelsdistrikt von Sturmwind, an den Hauptstraßen zwischen Händlern und Handwerkern.",al={"trias standort","käseladen standort","wo ist elling trias"}},{q="Was steht in der versiegelten Notiz an Elling?",a="Jorgens versiegelte Notiz berichtet Elling Trias vom vermissten Diplomaten und bittet ihn, durch seine Kontakte und Informanten im Untergrund Spuren aufzuspüren, denen die üblichen Behörden nicht nachgehen können.",al={"inhalt der notiz","was steht in der notiz","versiegelte notiz an elling"}},{q="Wer ist der vermisste Diplomat, der in der Quest erwähnt wird?",a="Der königliche Hof hält die Identität des Diplomaten zu diesem Zeitpunkt geheim. Die Geheimhaltung und die Sorge deuten auf jemanden von immenser politischer Bedeutung für das Königreich Sturmwind hin.",al={"wer wird vermisst","wer ist der diplomat","identität der vermissten person"}},{q="Warum sollte die Ermittlung einen Käsehändler statt der Stadtwache einbeziehen?",a="Die Stadtwache ist an Vorschriften, Zuständigkeiten und politische Verbindungen gebunden. Elling Trias hat Zugang zu Gerüchten auf den Straßen und verschwiegenen Kontakten, die den Soldaten verschlossen bleiben.",al={"warum ein käsehändler","warum trias statt wachen","wachen im vergleich zu trias"}}},fx={c433039c={q="Warum möchte Jorgen, dass dieser Brief an Elling Trias überbracht wird?",a="Jorgen weiß, dass die Suche nach dem vermissten Diplomaten eine heikle, geheime Angelegenheit ist, die weit über den Aufgabenbereich eines einfachen Feldagenten hinausgeht. Elling Trias mag wie ein gewöhnlicher Käsehändler im Handelsdistrikt wirken, aber er besitzt Untergrundverbindungen und Informationen, die für die Untersuchung unerlässlich sind. Jorgen muss seine Erkenntnisse sicher in die Hände von Trias legen, ohne jemanden zu warnen, der ihn beobachtet.",al={"warum notiz an elling trias senden","jorgen motiv vermisster diplomat","warum versiegelte notiz überbringen"}}},fp="20,209,19.323.0,20.260.1,20.161.0,38.190.0,31.106.0,37.171.0,51.169.0,73.156.0"}
P.entries["quest:1243"] = {n="Der vermisste Diplomat",s="Elling Trias schickt Euch von Sturmwind nach Süden, um Neuigkeiten über den vermissten Diplomaten zu erfahren. Seine Spur führt in den Dämmerwald zu Behüter Backus, einem Kontakt nahe Dunkelhain, der von Aktivitäten der Defias wissen könnte.",h="Elling Trias schickt Euch von Sturmwind nach Süden, um Neuigkeiten über den vermissten Diplomaten zu erfahren.",kw={"dunkelhain","defias","dämmerwald","elling trias","jorgen","vermisster diplomat","night watch","behüter backus"},ang={["class:Rogue"]="Als Schurke seht Ihr, wie Elling Trias über ein Netzwerk arbeitet. Er verlässt sich auf unabhängige Helfer vor Ort, um Informationen zu sammeln, während er seine eigenen Hände sauber hält.",["faction:Alliance"]="Als Held der Allianz helft Ihr, einem Verschwinden nachzugehen, das die Interessen der Krone von Sturmwind berührt. Die Suche bringt königliche Spionagemeister, unabhängige Gauner und regionale Milizen zusammen."},sec={{t="Laufarbeit im Zwielicht",b="Nach einem frustrierenden Austausch mit Jorgen wendet sich der Käsehändler Elling Trias an seinen weiteren Informantenkreis. Um seine eigenen Münzen zu sparen, schickt er Euch zur Arbeit vor Ort, statt Agenten anzuheuern. Ihr tragt ein versiegeltes Schreiben über die Grenze in den Dämmerwald, wo Bestien und Untote das Reisen gefährlich machen."},{t="Ein offenes Ohr bei der Night Watch",b="Behüter Backus patrouilliert als Mitglied der Nachtwache am nördlichen Zugang nach Dunkelhain. Trias vertraut darauf, dass er über illegale Bewegungen durch den Dämmerwald berichtet. Zeigt Backus die versiegelte Depesche, und er kann Euch Wachaufzeichnungen und örtlichen Klatsch über Aktivitäten der Bruderschaft der Defias im Süden mitteilen."}},faq={{q="Warum schickt Elling Trias mich in den Dämmerwald?",a="Elling Trias verfolgt Spuren zum vermissten Diplomaten und zu vermuteten Aktivitäten der Bruderschaft der Defias. Um seine Kontakte zu nutzen, ohne Münzen für Agenten auszugeben, schickt er Euch zu Behüter Backus, um nach den Geschehnissen im Dämmerwald zu fragen.",al={"warum in den dämmerwald","trias auftrag im dämmerwald","warum dunkelhain"}},{q="Wo kann ich Behüter Backus finden?",a="Behüter Backus patrouilliert auf der nördlichen unbefestigten Straße direkt vor Dunkelhain im Dämmerwald, entlang der Straße zum Rotkammgebirge und zum Wald von Elwynn.",al={"behüter backus aufenthaltsort","wo ist backus","backus finden"}},{q="Wer ist Behüter Backus?",a="Behüter Backus ist ein Soldat in Dunkelhains Bürgermiliz, der Nachtwache. Er kennt Elling Trias persönlich und berichtet, was er über verdächtige Reisende und kriminelle Bewegungen beobachtet.",al={"backus hintergrund","wer ist backus"}},{q="Was steht in der versiegelten Nachricht für Backus?",a="In seiner versiegelten Nachricht bittet Elling Trias Behüter Backus um Erkenntnisse über örtliche Sichtungen oder Bewegungen der Bruderschaft der Defias durch den Dämmerwald.",al={"inhalt der versiegelten nachricht","was steht in der nachricht","versiegelte notiz an behüter backus"}},{q="Was hat der Dämmerwald mit der Bruderschaft der Defias zu tun?",a="Die Bruderschaft der Defias hat ihren Mittelpunkt in Westfall und verbirgt sich unter den Todesminen. Ihre Zellen, Kuriere und Verstecke erstrecken sich auch über die südlichen Menschenprovinzen, einschließlich der schattigen Randgebiete des Dämmerwalds.",al={"defias im dämmerwald","sind defias im dämmerwald"}},{q="Warum beklagt sich Trias über Jorgen?",a="Jorgen blockte Trias während der Ermittlungen ab oder verhandelte hart mit ihm. Trias war so verärgert, dass er Jorgen in den Twisting Nether verwünschte, bevor er sich anderen Kontakten vor Ort zuwandte.",al={"wer ist jorgen","trias und jorgen"}}},fx={["8b2965b1"]={q="Warum möchte Elling Trias, dass dies erledigt wird?",a="Elling Trias mag wie ein bescheidener Meister feiner Käsesorten aussehen, aber er unterhält ein weites Netz an Kontakten und hat zugestimmt, sich mit dem Verschwinden des vermissten Diplomaten zu befassen. Jedes Anzeichen einer Verwicklung der Bruderschaft der Defias könnte der Hinweis sein, der den Fall löst, also setzt er Euch auf die Spur in den Dämmerwald, während er seine eigenen Quellen in der Stadt bearbeitet.",al={"warum kümmert das trias","trias motivation","elling trias motiv"}},c3fdc8e2={q="Warum lässt Elling Trias Euch die Laufarbeit erledigen, anstatt es selbst zu tun?",a="Trias macht keinen Hehl aus seiner Praktikabilität: Einen Abenteurer zu schicken spart ihm beträchtliche Summen und hält ihn frei, um seine diskreten Kontakte innerhalb von Sturmwind zu nutzen. Ein prominenter Kaufmann, der in den düsteren Dämmerwald wandert, würde unnötige Aufmerksamkeit erregen, während ein reisender Ermittler im Stillen örtliche Wachen wie Behüter Backus bedrängen kann, ohne die Augen der Defias auf sich zu ziehen.",al={"warum schickt man mich","warum braucht trias mich","warum geht er nicht selbst"}}},fp="20,191,21.306.0,33.283.0,43.217.0,32.131.0,22.179.0,43.142.0,58.201.0,37.189.0"}
P.entries["quest:1244"] = {n="Der vermisste Diplomat",s="Behüter Backus hat die Suche nach Sturmwinds vermisstem Diplomaten nach Dämmerwald geführt. Eine Ansammlung von Defiasbanditen bei Addles Siedlung könnte eine Spur liefern.",h="Behüter Backus hat die Suche nach Sturmwinds vermisstem Diplomaten nach Dämmerwald geführt.",kw={"addles siedlung","liste der defias","dämmerwald","fußtruhe","night watch","der vermisste diplomat","behüter backus"},ang={["class:Rogue"]="Als Schurke müsst Ihr Euch in kriminellen Netzwerken zurechtfinden und echte Informationen von Täuschungsmanövern der Defias unterscheiden.",["faction:Alliance"]="Sturmwinds vermisster Gesandter gefährdet die Sicherheit des Königreichs. Die Intrigen der Defias reichen weit über gewöhnliche Wegelagerei in Westfall hinaus."},sec={{t="Eine Spur im Zwielicht",b="Behüter Backus von der Nachtwache führt Euch nach Dämmerwald. Vor einigen Wochen kam eine ungewöhnlich große Gruppe von Defiasbanditen nach Addles Siedlung. Für gewöhnlich bleiben sie jenseits der Grenze in Westfall unter sich, daher ist ihre Anwesenheit in den dunklen Wäldern eine beunruhigende Veränderung. Nun durchsucht Ihr das verlassene Gehöft nach den Papieren, die sie zurückgelassen haben."},{t="Die Liste der Defias",b="Auf dem überrannten Gehöft findet Ihr eine verschlossene Fußtruhe mit einer Liste der Defias darin. Die Papiere deuten auf eine Beteiligung der Bruderschaft hin. Doch Behüter Backus warnt, dass die Defias sie gefälscht haben könnten, um die Ermittler irrezuführen."}},faq={{q="Wo liegt Addles Siedlung?",a="Addles Siedlung liegt im Westen von Dämmerwald, unmittelbar südlich der Hauptstraße aus Westfall. Feindselige Agenten der Defias besetzen das heruntergekommene Bauernhaus.",al={"addles siedlung lage","wo liegt addles siedlung","addles siedlung finden"}},{q="Was ist die Liste der Defias?",a="Die Liste der Defias ist eine Sammlung offiziell wirkender Papiere in einer Fußtruhe bei Addles Siedlung. Sie beschreibt einige der jüngsten verdeckten Operationen der Bruderschaft in der Region.",al={"liste der defias","was ist die liste","addles siedlung dokument"}},{q="Wer ist Behüter Backus?",a="Behüter Backus gehört der in Dämmerwald stationierten Nachtwache an. Seine Kontakte in der Stadt und seine Wachsamkeit gegenüber Bedrohungen an der Grenze helfen ihm, ungewöhnliche Bewegungen der Defias entlang der Grenze zu Westfall zu verfolgen.",al={"behüter backus","wer ist backus","backus dämmerwald"}},{q="Warum sind die Defias in Dämmerwald aktiv?",a="Agenten der Defias dringen heimlich in den Westen von Dämmerwald ein, obwohl ihre Hochburg jenseits der Grenze in Westfall liegt. Addles Siedlung ist ein abgelegener Zwischenhalt fernab der Patrouillen aus Sturmwind.",al={"warum sind defias in dämmerwald","defias bei addles siedlung"}},{q="Kann man dem Inhalt der Liste der Defias trauen?",a="Behüter Backus warnt, dass die Defias falsche Spuren gelegt haben könnten, um die Ermittler von ihrer Fährte abzubringen. Die Liste wirkt echt, doch ihr Inhalt könnte irreführend sein.",al={"ist die liste echt","liste fälschung","ist es eine täuschung"}},{q="Wer verwies die Ermittler ursprünglich an Behüter Backus?",a="Behüter Backus sagt, Elling Trias habe die Ermittlungen zur Nachtwache in Dämmerwald gelenkt. Trias ist ein Käsehändler und heimlicher Informationsvermittler in Sturmwind.",al={"wer hat mich zu backus geschickt","trias verbindung"}}},fx={["860270d2"]={q="Warum schickt Behüter Backus Euch nach Addles Siedlung?",a="Behüter Backus betrachtet jede Präsenz der Defias im Dämmerwald als eine drohende Gefahr für die Grenzen von Dunkelhain, selbst wenn sie sich ruhig verhalten. Vor ein paar Wochen erregte eine ungewöhnliche Zusammenkunft ihrer Agenten in Addles Siedlung die Aufmerksamkeit der Nachtwache. Backus vermutete, dass dort etwas Bedeutendes geschehen war, was es zum vielversprechendsten Hinweis für Eure Untersuchung der verdeckten Bewegungen der Bruderschaft macht.",al={"warum will backus das erledigt haben","behüter backus motiv","warum addles siedlung untersuchen"}}},fp="20,151,19.342.0,17.221.1,31.137.0,26.172.0,22.179.0,41.191.0,49.163.0,59.162.0"}
P.entries["quest:1245"] = {n="Der vermisste Diplomat",s="Ihr bringt die geborgene Liste der Defias nach Sturmwind, wo die Suche nach einem vermissten Diplomaten gefährlicher wird.",h="Ihr bringt die geborgene Liste der Defias nach Sturmwind, wo die Suche nach einem vermissten Diplomaten...",kw={"liste der defias","dämmerwald","elling trias","faust","vermisster diplomat","sturmwind","behüter backus"},ang={["class:Rogue"]="Elling Trias zeigt, wie die Schurkenkunst Dolche gegen Informationsnetze eintauschen kann. Als Schurke erlebt Ihr, wie ein Spionagemeister in den Schattenkriegen der Krone verschlüsselte Botschaften der Defias entziffert.",["faction:Alliance"]="Als Mitglied der Allianz seht Ihr, wie stark Sturmwinds Sicherheit seit dem Dritten Krieg geschwunden ist. Die Pläne der Defias bedrohen das Königreich von innen."},sec={{t="Zu viel für die Night Watch",b="Behüter Backus im Dämmerwald will mit der Liste der Defias, die Ihr geborgen habt, nichts zu tun haben. Ihre Papiere beschreiben Pläne, die für bloße Banditenzüge oder ein Ablenkungsmanöver zu ausgeklügelt sind. Aus Angst vor königlicher Bestrafung und aus Misstrauen gegenüber seinen Vorgesetzten bei der Nachtwache bittet Backus Euch, seine Beteiligung geheim zu halten. Die Machenschaften könnten Karrieren beenden oder Leben kosten, also bringt Ihr die Papiere nach Sturmwind."},{t="Das wahre Geschäft eines Käsehändlers",b="Im Handelsdistrikt von Sturmwind lässt Meisterkäsehändler Elling Trias seine Ladenbesitzerfassade fallen, als Ihr zurückkehrt. Er studiert die Liste als Verbindungsmann im geheimen Nachrichtennetz des Königreichs. Die Papiere offenbaren sorgfältige Planung durch die Bruderschaft der Defias und nennen einen unheilvollen Decknamen: „Faust“. Der vermisste Diplomat wurde von einem gut vernetzten Netzwerk ins Visier genommen, dessen Einfluss tief ins Königreich reicht."}},faq={{q="Was ist die Liste der Defias?",a="Die Liste der Defias ist eine Sammlung brisanter Papiere, die Ihr im Dämmerwald geborgen habt. Sie beschreibt Pläne der Bruderschaft der Defias, deren Komplexität örtliche Wachen verängstigt, und liefert Meister Trias neue Spuren bei der Suche nach dem vermissten Diplomaten.",al={"liste der defias","was sind die papiere","inhalt der liste"}},{q="Warum hat Behüter Backus solche Angst, die Liste zu behalten?",a="Behüter Backus fürchtet, dass die Informationen in der Liste die Befugnisse eines Angehörigen der Nachtwache im Dämmerwald übersteigen. Er fürchtet, wegen Hochverrats gehängt zu werden, wenn seine Befehlshaber oder Vorgesetzten in Sturmwind erfahren, dass er solche Geheimdienstinformationen bearbeitet oder zurückgehalten hat.",al={"warum hat backus angst","angst von behüter backus"}},{q="Warum die Papiere zu einem Käseladenbesitzer in Sturmwind bringen?",a="Elling Trias gibt sich als Käsehändler aus, doch er ist ein Spionagemeister von Sturmwind und eine Schlüsselfigur im geheimen Nachrichtennetz des Königreichs. Sein Wissen und seine Verbindungen helfen ihm, die Pläne der Defias zu entschlüsseln.",al={"warum elling trias","warum trias käse"}},{q="Wer ist „Faust“, der in der Liste erwähnt wird?",a="Elling Trias erkennt „Faust“ als Decknamen einer Person, die mit der Koordination des Entführungsplans durch die Bruderschaft der Defias in Verbindung steht.",al={"wer ist faust","die faust defias","deckname faust"}},{q="Wohin führt diese Ermittlung als Nächstes?",a="Die Einzelheiten der Liste ermöglichen Trias, die Spur der Verschwörer weiterzuverfolgen. Er schickt Euch los, um Kontakte zu befragen und „Faust“ nachzuspüren, damit Ihr erfahrt, wohin der Diplomat gebracht wurde.",al={"nächster schritt","was nach der liste","wohin als nächstes"}},{q="Was hat das mit König Varian Wrynn zu tun?",a="Die Liste nennt König Varian Wrynn nicht. Ihr sucht nach einem namenlosen Diplomaten, der nie in Theramore ankam, und Trias' Auswertung der Papiere enthüllt die Identität des Ziels nicht.",al={"ist varian der diplomat","verbindung zu könig varian"}}},fx={["74ee0470"]={q="Warum benötigt Behüter Backus Euch, anstatt die Liste der Defias selbst zu nehmen?",a="Behüter Backus hat schreckliche Angst vor dem, was auf der Liste der Defias geschrieben steht. Als Mitglied der Nachtwache ist er pflichtgemäß dazu angehalten, Staatsangelegenheiten seinen Vorgesetzten zu melden, aber er weiß, dass der Umgang mit verräterischen Verschwörungsdokumenten außerhalb offizieller Kanäle ihn das Leben kosten könnte. Wenn seine Vorgesetzten herausfinden würden, dass er diese Informationen besaß und zurückhielt, fürchtet er, dass er gehängt würde. Ihr seid ein unabhängiger Ermittler, der bereits mit Trias zusammenarbeitet, was es Backus erlaubt, sich die Hände von der tödlichen Intrige zu waschen und gleichzeitig sicherzustellen, dass die Papiere jemanden erreichen, der sie entschlüsseln kann.",al={"warum ich","warum liefert backus die liste nicht","warum schickt man mich zu trias"}}},fp="20,113,29.338.0,27.390.1,26.232.0,51.225.0,56.198.0,38.125.0,40.153.0,49.190.1"}
P.entries["quest:1246"] = {n="Der vermisste Diplomat",s="In der Altstadt schickt Euch Elling Trias auf die Spur eines Namens im Fall des vermissten Diplomaten. Dashel Steinfaust weiß womöglich mehr über verdächtige Papiere, und die Suche führt in Sturmwinds raue Straßen.",h="In der Altstadt schickt Euch Elling Trias auf die Spur eines Namens im Fall des vermissten Diplomaten.",kw={"dashel steinfaust","elling trias","fist","vermisster diplomat","die altstadt","sturmwind"},ang={["class:Rogue"]="Als Schurke seid Ihr in der Altstadt zu Hause, unter Informanten wie Trias und brutalen Handlangern wie Steinfaust.",["faction:Alliance"]="Als Mitglied der Allianz wisst Ihr, dass die Aufdeckung der Verschwörung um den vermissten Diplomaten für die Stabilität der Allianz und des Königreichs in ihrem Herzen von Bedeutung ist.",["race:Human"]="Als Mensch aus Sturmwind seht Ihr beunruhigende Beweise dafür, dass der örtliche Straßengesindel Hochverrat gegen die Führung des Königreichs unterstützt."},sec={{t="Eine Spur in der Altstadt",b="Elling Trias erinnert sich an Dashel Steinfaust, bekannt als Fist, unter den Namen, die mit den verschlüsselten Notizen und Hinweisen verbunden sind. Steinfaust ist ein rauer Straßenkämpfer und hält sich in den engen Gassen der Altstadt auf. Die Suche nach ihm führt aus den prächtigen Hallen der Burg Sturmwind in die kriminellen Kreise der Stadt."},{t="Überzeugungsarbeit mit der Faust",b="Elling Trias warnt, dass Dashel Steinfaust mit neugierigen Fremden nicht offen sprechen wird, besonders wenn Verrat und Entführungen im Spiel sind. Wenn Fragen nichts bewirken, muss laut Trias Gewalt sprechen. Steinfaust betrachtet die Gassen als sein Revier. Er nimmt es Fremden übel, wenn sie in Angelegenheiten herumstochern, die ihn seinen Lebensunterhalt oder seinen Kopf kosten könnten."}},faq={{q="Wer ist Dashel Steinfaust?",a="Dashel Steinfaust ist ein berüchtigter Schläger, der sich häufig in den zentralen Gassen von Sturmwinds Altstadt aufhält. Trias bringt ihn mit belastenden Papieren in Verbindung, die bei der Suche nach dem vermissten Diplomaten gefunden wurden.",al={"dashel steinfaust","wer ist fist","dashel"}},{q="Wo kann ich Dashel Steinfaust finden?",a="Dashel Steinfaust hält sich im Freien in den Gassen nahe dem Zentrum der Altstadt auf, abseits der Hauptstraßen.",al={"dashel steinfaust aufenthaltsort","wo ist dashel","wo ist steinfaust"}},{q="Warum schickt mich Elling Trias auf seine Spur?",a="Trias bringt Dashels Namen mit Papieren über das Verschwinden des königlichen Gesandten in Verbindung. Dashel kennt womöglich Namen, Orte oder Befehle, die mit den Drahtziehern der Entführung zusammenhängen.",al={"warum gegen dashel kämpfen","trias grund"}},{q="Wird Dashel freiwillig kooperieren?",a="Nein. Steinfaust begegnet Fremden, die sich in seine Geschäfte einmischen, feindselig. Trias rechnet mit Widerstand und rät Euch, ihn mit einer Waffe oder Euren Fäusten zum Reden zu bringen.",al={"redet dashel","steinfaust freundlich"}},{q="Was geschieht, nachdem ich Dashel gefunden habe?",a="Die Konfrontation mit Dashel führt zu einer Schlägerei. Sobald Ihr ihn überwältigt habt, gibt er Euch Hinweise auf das Netzwerk hinter der Entführung des Diplomaten und verweist auf weitere Verschwörer innerhalb des Königreichs.",al={"der vermisste diplomat nächster schritt","was kommt nach dashel"}},{q="Wer ist der vermisste Diplomat, der in der Quest erwähnt wird?",a="Sturmwinds Behörden sprechen lediglich von einem namenlosen Diplomaten, der auf dem Weg nach Theramore verschwand, wo er Jaina Prachtmeer treffen sollte. Die Identität des Gesandten bleibt in diesem Stadium der Ermittlungen ein streng gehütetes Geheimnis.",al={"wer ist der vermisste diplomat","welcher diplomat"}}},fx={["8d360f6b"]={q="Warum schickt Elling Trias Euch anstelle der Stadtwachen?",a="Elling operiert mit Geheimnissen, Gerüchten und heiklen politischen Bindungen statt mit offener Autorität. Das Verschwinden eines hochrangigen Diplomaten ist eine explosive Angelegenheit, und die Einbeziehung der Stadtwache von Sturmwind würde öffentliche Panik auslösen und die Verschwörer darauf aufmerksam machen, dass ihnen jemand auf der Spur ist. Trias braucht einen unabhängigen Ermittler, der leise durch die Hintergassen der Altstadt schlüpfen, gefährliche Fragen stellen und Knochen brechen kann, ohne die harte Hand – und die laute Aufmerksamkeit – des Gesetzes auf sich zu ziehen.",al={"warum schickt man mich","warum keine stadtwachen von sturmwind","warum nicht stadtwache"}}},fp="20,198,18.280.0,22.325.1,24.189.0,34.104.0,41.163.0,32.155.0,34.175.1,51.215.2"}
P.entries["quest:1247"] = {n="Der vermisste Diplomat",s="In der Altstadt gibt Dashel Steinfaust eine Warnung für Elling Trias preis. Sein Geständnis nennt einen Ersatzplan zur Entführung und einen Kontakt im Hafen von Menethil.",h="In der Altstadt gibt Dashel Steinfaust eine Warnung für Elling Trias preis.",kw={"addles siedlung","dashel steinfaust","elling trias","menethil","vermisster diplomat","slim","sturmwind"},ang={["class:Rogue"]="Als Schurke wisst Ihr, wie eng Straßenkriminalität und Staatsgeheimnisse miteinander verbunden sein können. Dashel bringt die Schlägergewalt aus den Hintergassen ein, während Trias im Stillen Geheimdienstarbeit leistet.",["faction:Alliance"]="Als Mitglied der Allianz wisst Ihr, dass der vermisste Gesandte für die Stabilität der Allianz von Bedeutung ist. Sabotage bedroht Sturmwinds Führung.",["race:Human"]="Als Mensch seht Ihr, wie sich innerhalb von Sturmwinds Grenzen eine Verschwörung entfaltet, während der Kindkönig auf dem Thron sitzt."},sec={{t="Ein Riss in der Mauer",b="Dashel Steinfaust gibt nach, als er um seine Gesundheit fürchtet. In einer Gasse der Altstadt gesteht er, dass der erste Entführungsplan der Verschwörer für den Gesandten scheiterte und sein Anteil daran auseinanderfiel. Um die Schuld abzuwälzen, erzählt er Euch von einem geheimen Treffen vor einigen Wochen in Addles Siedlung im Dämmerwald. Er nennt auch eine Spur zu ihrem Ersatzplan: einen Insider im Hafen von Menethil, der nur als Slim bekannt ist."},{t="Bericht an den Käsemeister",b="Elling Trias sammelt hinter dem Tresen von Trias' Käse im Handelsdistrikt Geheimnisse für die Krone. Während Ihr Dashel befragt habt, untersuchte Trias abgefangene Nachrichten über die Verschwörung. Dashels Geständnis deckt sich mit den Enthüllungen der Nachrichten: Die Verschwörer hatten einen namentlich nicht genannten Diplomaten im Visier, ihr erster Hinterhalt scheiterte, und ein Ersatzplan über das Sumpfland lief an. Mit Slims Namen führt die Suche von Sturmwind nach Norden in Richtung der Sümpfe."}},faq={{q="Wer ist Dashel Steinfaust?",a="Dashel Steinfaust ist ein Mittelsmann und Schläger in Sturmwinds Altstadt. Er hat Verbindungen zur Unterwelt der Defias und half dabei, den ersten Plan zur Gefangennahme von Sturmwinds Gesandtem auszuführen. Als er zur Rede gestellt wurde, gab er Informationen preis.",al={"dashel steinfaust","wer ist dashel","steinfaust sturmwind"}},{q="Warum ist Elling Trias an dieser Untersuchung beteiligt?",a="Elling Trias sammelt Geheimnisse für Sturmwind und gibt sich dabei als Meister feiner Käsesorten aus. Sein Laden im Handelsdistrikt ermöglicht es ihm, diskrete Nachforschungen außerhalb der Reichweite der Stadtwache zu koordinieren.",al={"warum elling trias","käsehändler spion","trias geheimdienst"}},{q="Was geschah in Addles Siedlung?",a="Vor einigen Wochen trafen sich die Verschwörer in Addles Siedlung, einem verlassenen Bauernhof im westlichen Dämmerwald, um nach der Vereitelung ihres ersten Versuchs ihre Entführungen zu planen.",al={"addles siedlung treffen","addles siedlung","westfall treffen"}},{q="Wer ist der Diplomat, den sie entführen wollten?",a="Die Dokumente der Verschwörer und die Straßenschläger nennen ihr Ziel lediglich einen namentlich nicht genannten Diplomaten auf dem Weg nach Theramore. Die Identität des Gesandten bleibt zu diesem Zeitpunkt der Untersuchung streng gehütet.",al={"wer ist der vermisste diplomat","wer wurde entführt","identität des diplomaten"}},{q="Wer ist Slim?",a="Slim ist der Name, den Dashel Steinfaust für den Kontakt nennt, der den Ersatzplan vom Hafen von Menethil im Sumpfland aus abwickelt. Dieser Kontakt steht für den zweiten Weg der Verschwörer, Menschen und Vorräte zu befördern.",al={"wer ist slim","slim menethil","menethil kontakt"}},{q="Wohin führt die Spur danach?",a="Die Spur führt nach Norden zum Hafen von Menethil im Sumpfland, wo Slim sein soll. Elling Trias bestätigt Dashels Angaben.",al={"nächster schritt vermisster diplomat","wohin nach dashel","was als nächstes"}}},fx={a7b1abaf={q="Warum redet Dashel Steinfaust jetzt?",a="Dashel redet nur, weil Ihr ihn gerade zur Unterwerfung geprügelt habt. Da er erkennt, dass seine Schläger ihn nicht vor Euch schützen konnten, versucht er panisch, seine eigene Haut zu retten, indem er preisgibt, was wenig er über den Plan B der Verschwörung weiß, und Euch von sich wegweist.",al={"warum redet dashel","dashel steinfaust motiv","warum hat dashel gestanden"}}},fp="20,145,19.357.0,25.433.1,24.206.0,51.185.0,31.155.0,47.196.2,12.204.0,37.127.0"}
P.entries["quest:1248"] = {n="Der vermisste Diplomat",s="Ihr folgt der Spur eines entführten Diplomaten aus Sturmwind zum Hafen von Menethil. Eine abgefangene Akte bestätigt die Entführung, lässt jedoch die Identität des Diplomaten und das Reiseziel der Verschwörer offen.",h="Ihr folgt der Spur eines entführten Diplomaten aus Sturmwind zum Hafen von Menethil.",kw={"akte","hafen von menethil","mikhail","slim","sturmwind","the missing diplomat","trias","sumpfland"},ang={["class:Rogue"]="Als Schurke könnt Ihr Eure heimlichen Fertigkeiten nutzen, um geheime Akten zu entschlüsseln, Kontakte im Ruhestand aufzuspüren und Verdächtige in überfüllten Tavernen diskret zu befragen.",["faction:Alliance"]="Die Entführung des Diplomaten betrifft Sturmwinds Sicherheit auf höchster Ebene und die Reichweite von Verschwörern in den Gebieten der Allianz."},sec={{t="Eine Spur ins Sumpfland",b="Ihr habt eine Akte, die bestätigt, dass ein Diplomat aus Sturmwind verschleppt wurde. Sie nennt weder den Diplomaten noch das Reiseziel der Verschwörer. So führt die Spur über Sturmwinds Tore hinaus zum Hafen von Menethil im Sumpfland, wo Ihr unter den Menschenmengen und ihren geheimen Machenschaften nachforschen könnt."},{t="Diskrete Kontakte in Menethil",b="Mikhail, ein ehemaliger Gefährte von Elling Trias, zog sich vor mehreren Jahren aus Sturmwind zurück und betreibt nun die Taverne in Menethil. Ihr sucht ihn auf, um Slim zu finden, der vielleicht weiß, wohin der Gefangene gebracht wurde oder wer die Entführung veranlasst hat.\n\nIn der überfüllten Taverne ist Diskretion wichtig. Erwähnt Ihr Trias' Namen, mahnt Mikhail sofort zum Schweigen, bevor die Verschwörer Eure Nachforschungen bemerken."}},faq={{q="Wer ist Mikhail?",a="Mikhail war ein Gefährte von Elling Trias, der Sturmwind vor mehreren Jahren verließ, um sich im Hafen von Menethil zur Ruhe zu setzen. Er arbeitet dort nun als Schankwirt, und Trias empfiehlt ihn Euch als vertrauenswürdigen Kontakt, der helfen kann, Slim zu finden.",al={"wer ist mikhail","mikhail sumpfland","menethil schankwirt"}},{q="Wer ist Slim und warum wird er gesucht?",a="Slim ist eine Gestalt im Hafen von Menethil, die vermutlich etwas über den entführten Diplomaten weiß. Mikhail kann Euch helfen, Slim zu finden und zu erfahren, was er weiß.",al={"wer ist slim","slim finden","vermisster diplomat slim"}},{q="Wer ist der entführte Diplomat?",a="Die Identität des entführten Diplomaten bleibt ungewiss, selbst für die Ermittler. Die abgefangene Akte bestätigt die Entführung, verschweigt jedoch die Identität des Diplomaten und die Pläne der Verschwörer nach seiner Gefangennahme.",al={"wer wurde entführt","entführter diplomat identität","wer ist der vermisste diplomat"}},{q="Warum führt die Spur zum Hafen von Menethil?",a="Die Spur führt zum Hafen von Menethil, weil Mikhail, Elling Trias' Kontakt im Ruhestand, dort als Schankwirt arbeitet. Der Hafen ist eine Hafenstadt an der Küste des Sumpflands, und Hinweise zur Entführung führen durch diesen Ort.",al={"wo ist der hafen von menethil","warum sumpfland","warum nach menethil"}},{q="Was verrät die Akte über die Verschwörung?",a="Die abgefangene Akte bestätigt die Entführung des Diplomaten, verschweigt jedoch, wohin der Gefangene gebracht wurde und was die Entführer als Nächstes vorhaben.",al={"welche akte","trias akte","was steht in der akte"}},{q="Welche Rolle spielt Trias bei dieser Mission?",a="Elling Trias leitet die Ermittlungen von Sturmwind aus. Er schickt Euch zu Mikhail, seinem alten Gefährten, der allein auf Trias' Wort hin Hilfe versprach, ohne öffentliches Aufsehen zu erregen.",al={"wer hat uns zu mikhail geschickt","trias verbindung","warum trias erwähnen"}}},fp="20,197,23.285.0,29.369.1,15.225.0,45.149.0,30.211.0,43.201.0,43.141.0,44.179.0"}
P.entries["quest:1249"] = {n="Der vermisste Diplomat",s="Sturmwinds Gesandter wird vermisst, und Ihr folgt seiner Spur von der Hauptstadt bis zum Hafen von Menethil. Dort kreuzen sich die Nachforschungen mit Gestalten der Unterwelt und Agenten, die mit Sturmwinds Geheimdienstnetzwerk verbunden sind.",h="Sturmwinds Gesandter wird vermisst, und Ihr folgt seiner Spur von der Hauptstadt bis zum Hafen von Menethil.",kw={"elling trias","hafen von menethil","vermisster diplomat","slim","sturmwind","the missing diplomat","sumpfland"},ang={["class:Rogue"]="Als Schurke wisst Ihr, dass Agenten und ihre Führungsoffiziere wie Elling Trias auf unauffällige Nachforschungen und Straßenkontakte setzen, um jene aufzuspüren, die durchs Raster fallen.",["faction:Alliance"]="Als Abenteurer der Allianz folgt Ihr der Spur des vermissten Diplomaten in eine Unterwelt, die Sturmwinds politische Kreise mit den Docks im Sumpfland verbindet."},sec={{t="Verborgene Strömungen im Hafen von Menethil",b="Ihr folgt der Spur des vermissten Gesandten aus Sturmwind nach Norden zum Hafen von Menethil im Sumpfland. An seinen Docks und in seinen Tavernen verbergen sich zwielichtige Händler und geheime Boten, die direkt unter den Augen der örtlichen Wache arbeiten. Um den Hinweisen in diesem Hafen nachzugehen, müsst Ihr mit Leuten verkehren, die die dunkleren Seiten des Allianzgebiets kennen."},{t="Ein vertrauter Schurke",b="Slims Ergreifung bringt eine unverhoffte Antwort bei der Suche. Örtliche Informanten sind überrascht zu erfahren, dass er in die Angelegenheit verwickelt war. Seine Gefangennahme liefert Euch entscheidende Antworten, weckt aber auch alte Erinnerungen bei Agenten im Ruhestand im Sumpfland. Sie müssen abwägen, ob sie der Krone helfen und dabei riskieren, wieder in die Machenschaften von Sturmwinds Unterwelt hineingezogen zu werden."}},faq={{q="Wer ist Slim?",a="Slim ist ein zwielichtiger Kontakt im Hafen von Menethil, den Ihr bei der Suche nach dem vermissten Diplomaten ergreift. Örtliche Kontakte sind überrascht zu erfahren, dass er beteiligt war.",al={"wer ist slim","slim vermisster diplomat","slim gefasst"}},{q="Wer ist Elling?",a="Elling Trias ist eine einflussreiche Gestalt in Sturmwind, die ein geheimes Netzwerk ehemaliger Schurken und Informanten in den Gebieten der Allianz unterhält.",al={"elling trias","wer ist elling","elling sturmwind"}},{q="Wo findet dieser Teil der Ermittlungen statt?",a="Ihr führt diesen Teil der Ermittlungen im Hafen von Menethil durch, einem Hafen im Sumpfland, der Eisenschmiede mit fernen Küsten und Sturmwinds Handelsrouten verbindet.",al={"wo geschieht das","hafen von menethil vermisster diplomat","sumpfland diplomat"}},{q="Worum geht es in der Questreihe The Missing Diplomat?",a="Ihr untersucht das Verschwinden eines wichtigen Gesandten aus Sturmwind und folgt verdeckt arbeitenden Agenten, Verschwörern und Kontakten der Unterwelt durch das Königreich und darüber hinaus.",al={"was ist der vermisste diplomat","vermisster diplomat quest","wer wird vermisst"}},{q="Warum warnt der Kontakt davor, Elling davon zu erzählen?",a="Ein Kontakt im Hafen von Menethil arbeitete einst mit Elling Trias in Sturmwinds Unterweltkreisen zusammen. Er vermeidet es, Elling zu sagen, dass er das alte Leben vermisst, aus Angst, Elling könnte ihn in die Hauptstadt zurückrufen.",al={"warum wird elling erwähnt","trias käse","elling trias verbindung"}},{q="Was geschah bei den Ermittlungen im Hafen von Menethil?",a="Ihr folgt Hinweisen zum Hafen von Menethil im Sumpfland und ergreift Slim. Die Begegnung bestätigt den örtlichen Verdacht auf illegale Aktivitäten der Unterwelt in der Stadt.",al={"was geschah im hafen von menethil","menethil hinweis","slim gefasst"}}},fp="20,205,32.304.0,16.330.1,12.156.0,14.143.0,53.144.0,47.164.0,60.198.0,56.151.0"}
P.entries["quest:125"] = {n="Die verlorenen Werkzeuge",s="Beschuss des Schwarzfelsklans hat Großknecht Oslows Werkzeuge im Immerruhsee versenkt. Seenhain steht unter Druck, und seine Bauarbeiter brauchen die Lieferung aus Goldhain, um die Große Brücke zu reparieren.",h="Beschuss des Schwarzfelsklans hat Großknecht Oslows Werkzeuge im Immerruhsee versenkt.",kw={"katapult","großknecht oslow","goldhain","der immerruhsee","seenhain","murloc","rotkammgebirge","drescher","werkzeugkiste"},ang={["faction:Alliance"]="Als Reisender der Allianz helft Ihr Seenhain, die östliche Grenze gegen den Schwarzfelsklan zu halten. Zivile Bauarbeiter brauchen ihre Ausrüstung, um die Verteidigungsanlagen des Königreichs Sturmwind instand zu halten.",["profession:Blacksmithing"]="Als Schmied wisst Ihr, dass sich hochwertige Werkzeuge während einer Belagerung nur schwer schmieden lassen. Die Bergung der speziellen Schmiede- und Bauwerkzeuge aus Goldhain ist für die Stadt von Bedeutung."},sec={{t="Eine fehlgeschlagene Lieferung",b="Die Große Brücke verbindet Seenhain nicht mehr mit dem Wald von Elwynn. Eine Ersatzlieferung von Steinmetz- und Zimmermannswerkzeugen kam auf dem Landweg aus Goldhain, doch die Wagen konnten die Stadt nicht erreichen. Also verlud die Mannschaft die Vorräte in ein Ruderboot, um den Immerruhsee zu überqueren. Ein Katapult der Schwarzfelsorcs traf das Boot. Es brach auseinander, und Oslows schwere, eisenbeschlagene Werkzeugkiste sank auf den Grund des Sees."},{t="Gefahren der Tiefe",b="Unter der Oberfläche ist der Immerruhsee gefährlich. Aggressive Murlocstämme durchstreifen die seichten Gewässer, während räuberische Drescher in den trüben Tiefen jagen. Großknecht Oslow braucht seine Werkzeuge, um die Reparaturarbeiten an der Brücke wieder aufzunehmen. Ohne sie droht Seenhain noch weiter zu verfallen."}},faq={{q="Warum wurden die Werkzeuge überhaupt mit dem Boot verschickt?",a="Schwarzfelsorcs zerstörten einen großen Abschnitt der Steinbrücke über den Immerruhsee, sodass Versorgungswagen aus Goldhain Seenhain nicht mehr erreichen konnten. Die Mannschaft lud die Werkzeuge ab und versuchte, sie über das Wasser zu bringen.",al={"warum ein boot","wie sind die werkzeuge gesunken","warum transport über den see"}},{q="Wie sank das Boot?",a="Ein Katapultgeschoss traf das Transportboot, als es den Immerruhsee überquerte. Schwarzfelsorcs feuerten von den umliegenden Anhöhen aus, und das Boot sank mit seiner Ladung.",al={"wer hat das boot zerstört","wie wurde es getroffen"}},{q="Wer ist Großknecht Oslow?",a="Großknecht Oslow ist Seenhains oberster Baumeister und Aufseher. Er ist für öffentliche Bauarbeiten und die Instandhaltung der Stadt zuständig, wobei der Wiederaufbau der zerstörten Brücke seine dringendste Aufgabe ist.",al={"großknecht oslow","oslows aufgabe"}},{q="Welche Gefahren lauern im Immerruhsee?",a="Feindselige Murlocstämme patrouillieren an den Ufern und in den Ruinen. Bösartige, fleischfressende Seedrescher jagen im offenen Wasser und in den tieferen Regionen.",al={"was ist im see","seemonster","gefahren im immerruhsee"}},{q="Warum braucht Seenhain diese Werkzeuge so dringend?",a="Seenhain wird belagert und ist von rascher Verstärkung und regelmäßigen Lieferungen abgeschnitten. Ohne schweres Werkzeug kann Oslow weder die Brücke wiederaufbauen noch die Verteidigungsanlagen reparieren, die gegen angreifende Orcs und Gnolle benötigt werden.",al={"warum sind werkzeuge wichtig","werkzeuge zur brückenreparatur"}},{q="Wohin führt die nächste Quest?",a="Nachdem seine Werkzeugkiste geborgen wurde, bittet Großknecht Oslow Reisende in „The Everstill Bridge“, die nötigen Baumaterialien zur Reparatur der Großen Brücke zu sammeln.",al={"nächste quest","was kommt nach die verlorenen werkzeuge"}}},fx={fed346ea={q="Wozu wird Oslows Werkzeugkasten verwendet?",a="Oslows Werkzeugkasten enthält die schweren Eisenwerkzeuge, die benötigt werden, um die ruinierte Infrastruktur von Seenhain wieder aufzubauen. Da die Orcs des Schwarzfels die Stadt belagern und die große Brücke in Schutt und Asche gelegt haben, sind Bau und Reparaturen völlig zum Erliegen gekommen. Oslow kann die Brücke nicht reparieren oder die Verteidigungsanlagen der Stadt ohne seine Spezialausrüstung verstärken, was Seenhain verwundbar und abgeschnitten lässt, bis die Ausrüstung vom Grund des Sees geborgen wird.",al={"oslows werkzeugkasten","wofür ist der werkzeugkasten","großknecht oslow werkzeuge"}},b04d784a={q="Warum bittet Großknecht Oslow einen Abenteurer und nicht die Stadtwache?",a="Seenhain ist unter einer aktiven Belagerung bis an seine absolute Belastungsgrenze gespannt. Die wenigen verbliebenen Stadtwachen und Magistrate sind damit beschäftigt, den Umkreis gegen Orcs des Schwarzfels, Gnolle und eingehenden Katapultbeschuss zu verteidigen. Oslow selbst ist ein Baumeister, kein Kämpfer oder Taucher, und der Immerruhsee wimmelt von aggressiven Murlocs und monströsen Dreschern. Er braucht einen fähigen Reisenden, der bereit ist, feindseligen Gewässern zu trotzen, während die Verteidiger von Seenhain die Stellung halten.",al={"warum ich verlorene werkzeuge","warum holt oslow es nicht selbst","warum keine wachen aus seenhain schicken"}}},fp="14,171,20.373.0,19.263.0,51.212.0,22.162.0,21.170.0,35.128.0,45.207.0,31.156.1"}
P.entries["quest:1250"] = {n="Der vermisste Diplomat",s="Jahn sagt, die Defias hätten den König von seinem Schiff entführt, während es festgemacht war. Man schickt Euch zu Mikhail ins Sumpfland, während die Suche nach Hendel weitergeht.",h="Jahn sagt, die Defias hätten den König von seinem Schiff entführt, während es festgemacht war.",kw={"defias","hendel","jahn","jaina prachtmeer","mikhail","sturmwind könig","the missing diplomat","theramore","sumpfland"},sec={{t="Ein Zeuge spricht",b="Jahn sagt, die Defias hätten einen Mann namens Hendel an Bord des Königsschiffs gebracht, während es festgemacht war. Der König war auf dem Weg nach Theramore, um Jaina Prachtmeer zu treffen. Jahn glaubt, die Defias hätten mit jemand anderem zusammengearbeitet, weshalb Ihr mit Mikhail im Sumpfland sprechen sollt, während die Suche nach Hendel beginnt."},{t="Mikhails Antwort",b="Mikhail ist bestürzt, als er hört, dass der König vermisst wird, und schickt Elling Nachricht. Er sagt, er hätte nie erwartet, dass Jahn Sturmwind für Münzen verraten würde. Dennoch bietet Mikhail Hilfe bei der Suche nach Hendel an."}},faq={{q="Wer ist Jahn?",a="Jahn ist ein Verschwörer der Defias, der dabei half, Hendel an Bord des Königsschiffs zu bringen.",al={"jahn wer","wer ist jahn","defias jahn"}},{q="Wer ist Hendel?",a="Hendel ist der Mann, den Jahn nach eigener Aussage an Bord des Königsschiffs gebracht hat.",al={"hendel mann","wer ist hendel","könig schiff mann"}},{q="Was ist mit dem König geschehen?",a="Jahn sagt, die Defias hätten den König von seinem Schiff entführt, während es festgemacht war.",al={"wo ist der könig","sturmwind könig vermisst","könig entführt"}},{q="Warum war der König auf dem Weg nach Theramore?",a="Der König war auf dem Weg nach Theramore, um Jaina Prachtmeer zu treffen.",al={"könig theramore","jaina treffen","warum theramore"}},{q="Wer ist laut Jahn außer den Defias beteiligt?",a="Jahn glaubt, die Defias hätten mit jemand anderem zusammengearbeitet, sagt aber, er wisse nicht, mit wem.",al={"wer arbeitet mit den defias","defias partner","wer ist noch beteiligt"}},{q="Wer ist Mikhail?",a="Mikhail ist die Person, mit der Ihr im Sumpfland sprechen sollt. Er bietet Hilfe bei der Suche nach Hendel an.",al={"mikhail sumpfland","wer ist mikhail","mit mikhail sprechen"}}},fp="20,145,16.285.0,18.191.1,12.74.0,14.61.0,26.69.0,36.62.0,49.81.0,15.97.0"}
P.entries["quest:1251"] = {n="Der Schwarze Schild",s="Am ausgebrannten Gasthaus Zur süßen Ruh hängt ein schwarzer Schild am bröckelnden Kamin. Krog in Brackenwall wartet darauf, ihn zu sehen.",h="Am ausgebrannten Gasthaus Zur süßen Ruh hängt ein schwarzer Schild am bröckelnden Kamin.",kw={"schwarzer schild","geschwärzter eisenschild","brackenwall","düstermarschen","krog","gasthaus zur süßen ruh"},sec={{t="Ein Schild am Kamin",b="Feuer wütete im Gasthaus Zur süßen Ruh und ließ wenig zurück. Ein schwarz verkohlter Eisenschild ist am bröckelnden Kamin befestigt. Ihr könnt ihn aus dem Mauerwerk lösen und zu Krog in Brackenwall bringen. Er wird fragen, ob er als Beweisstück aus den Überresten des Gasthauses zählt."},{t="Was Krog davon hält",b="Krog räumt ein, dass Menschen einen seltsamen Geschmack bei Dekorationen haben. Doch er bezweifelt, dass irgendjemand einen schlichten Eisenschild über eine Feuerstelle hängen würde. Er vermutet, dass derjenige, der das Gasthaus in Brand gesteckt hat, ihn dort als Warnung oder Drohung zurückgelassen hat."}},faq={{q="Wo ist der schwarze Schild zu finden?",a="Der schwarze Schild ist am Kamin des ausgebrannten Gasthauses Zur süßen Ruh befestigt, einem der wenigen Überreste des Gebäudes.",al={"schwarzer schild fundort","wo ist der schild","gasthaus zur süßen ruh schild"}},{q="Wer bekommt den Schild?",a="Bringt den Schild zu Krog in Brackenwall.",al={"wer will den schwarzen schild","wo den schild abgeben","krog standort"}},{q="Lässt sich der Schild vom Kamin lösen?",a="Ja. Ihr könnt den Schild aus dem Mauerwerk des Kamins lösen.",al={"lässt sich der schild entfernen","schild vom kamin lösen"}}},fp="16,122,23.274.0,21.203.1,32.111.0,20.48.0,41.62.0"}
P.entries["quest:1252"] = {n="Leutnant Paval Reethe",s="Beim Gasthaus Zur süßen Ruh liegt Leutnant Paval Reethes Abzeichen unter den Trümmern, versehen mit Theramores Zeichen. Bringt es zu Captain Garran Mumm in Theramore.",h="Beim Gasthaus Zur süßen Ruh liegt Leutnant Paval Reethes Abzeichen unter den Trümmern, versehen mit...",kw={"düstermarschen","garran mumm","paval reethe","gasthaus zur süßen ruh","wachabzeichen von theramore"},sec={{t="Ein Schimmer in den Trümmern",b="Asche und Schutt begraben ein Abzeichen in den Ruinen des Gasthauses Zur süßen Ruh. Darunter steht Leutnant Paval Reethes Name unter Theramores Zeichen. Captain Garran Mumm in Theramore fragt, was Ihr gefunden habt, und das Abzeichen gehört in seine Hände."},{t="Die Antwort des Captains",b="Captain Garran Mumm sagt, das Abzeichen einer Wache bringe düstere Nachrichten. Manche Wachen fallen im Kampf, und er muss ihren trauernden Familien die Nachricht überbringen. Andere verschwinden, und ihr Schicksal bleibt unbekannt. Manchmal ist die Wahrheit noch schlimmer."}},faq={{q="Wo findet man das Abzeichen?",a="Das Abzeichen liegt unter Trümmern, Asche und Schutt in den Ruinen des Gasthauses Zur süßen Ruh. Captain Garran Mumm fragt, was Ihr dort gefunden habt.",al={"fundort des abzeichens","wo reethes abzeichen finden","abzeichen gasthaus zur süßen ruh"}},{q="Wessen Name steht auf dem Abzeichen?",a="Leutnant Paval Reethes Name ist unter dem Anker eingeprägt.",al={"wer ist paval reethe","name auf dem abzeichen","wer hat das abzeichen verloren"}},{q="Wer bekommt das Abzeichen?",a="Captain Garran Mumm in Theramore sollte das Abzeichen sehen.",al={"wem das abzeichen geben","wo das abzeichen abgeben","aufenthaltsort von captain garran mumm"}},{q="Wie sieht das Abzeichen aus?",a="Das Abzeichen trägt einen goldenen Anker auf weißer Emaille, das Zeichen Theramores.",al={"symbol von theramore","aussehen des wachabzeichens","wie sieht das abzeichen aus"}}},fp="23,156,21.219.0,19.217.1,25.123.0,27.62.0,19.55.0,30.66.0"}
P.entries["quest:1253"] = {n="Der Schwarze Schild",s="Am niedergebrannten Gasthaus Zur süßen Ruh hängt ein feuergeschwärzter Schild am baufälligen Kamin. Captain Garran Mumm in Theramore wartet auf Beweise aus den Ruinen.",h="Am niedergebrannten Gasthaus Zur süßen Ruh hängt ein feuergeschwärzter Schild am baufälligen Kamin.",kw={"schwarzer schild","kamin","düstermarschen","garran mumm","eisenschild","gasthaus zur süßen ruh","theramore"},sec={{t="Ein Schild am Kamin",b="Vom niedergebrannten Gasthaus Zur süßen Ruh ist außer einem baufälligen Kamin nur wenig übrig. Ein feuergeschwärzter Eisenschild ist noch an seinem Mauerwerk befestigt und kann abgenommen werden. Captain Garran Mumm in Theramore wartet auf Beweise vom Schauplatz des Gasthauses."},{t="Das Urteil des Captains",b="Captain Garran Mumm weiß, wie Waffen und Rüstungen verwendet werden, behauptet aber nicht, zu wissen, wie sie hergestellt werden. Abgesehen von den Brandschäden sieht der Schild für ihn gewöhnlich aus."}},faq={{q="Wo befindet sich der schwarze Schild?",a="Der schwarze Schild ist am Mauerwerk des baufälligen Kamins befestigt, einem der wenigen noch stehenden Teile des niedergebrannten Gasthauses Zur süßen Ruh.",al={"wo ist der schild","fundort schwarzer schild","schwarzen schild finden"}},{q="Wer will Beweise aus dem Gasthaus Zur süßen Ruh?",a="Captain Garran Mumm in Theramore will Beweise aus den Ruinen des Gasthauses Zur süßen Ruh.",al={"wer will den schild","ermittler zur süßen ruh","wer ist garran mumm"}}},fp="16,153,23.220.0,21.179.1,34.130.0,43.79.0"}
P.entries["quest:1258"] = {n="...und Käfer",s="Morgan Stern in Theramore entwickelt ein Rezept, das Sturmwinds nächster kulinarischer Trend werden könnte. Die Mudrock-Zungen hat er bereits, doch ihm fehlen noch makellose, narbenlose Beine einer riesigen Krabbe.",h="Morgan Stern in Theramore entwickelt ein Rezept, das Sturmwinds nächster kulinarischer Trend werden könnte.",kw={"kriecherbeine","düstermarschen","morgan stern","mudrock soup and bugs","makelloses kriecherbein","sturmwind","theramore","sümpfe des elends"},sec={{t="Beine ohne Kratzer",b="Morgan Stern braucht den Panzer jedes Krabbenbeins, um seinem Gericht das gewünschte Aussehen zu verleihen. Jedes Bein muss makellos und narbenlos sein, doch eine ausgewachsene Krabbe hat möglicherweise nur ein oder zwei Beine, die für seine Forschung taugen. Er braucht viele, und die Muckshells aus den Düstermarschen genügen nicht. Nur Krabben aus den fernen Sümpfen des Elends eignen sich für das Rezept, also steht Euch eine lange Reise bevor."}},faq={{q="Wer ist Morgan Stern?",a="Morgan Stern ist in Theramore und entwickelt ein Rezept, das Sturmwinds nächster kulinarischer Trend werden könnte.",al={"wer ist morgan stern","morgan stern theramore","wer vergibt ...und käfer"}},{q="Woher stammen die Krabbenbeine?",a="Die Beine müssen von Krabben aus den fernen Sümpfen des Elends stammen. Die Muckshells aus den Düstermarschen eignen sich nicht für Morgan Sterns Gericht.",al={"wo kriecherbeine finden","wo sind spiny rock crawlers","kriecherbeine fundort"}},{q="Warum müssen die Krabbenbeine makellos sein?",a="Die Panzer der Krabbenbeine bestimmen das Aussehen des Gerichts, deshalb braucht Morgan Stern Beine ohne Narben.",al={"warum makellose kriecherbeine","warum narbenlose beine","kriecherbein anrichtung"}},{q="Welche Quest kommt vor dieser?",a="Sie folgt auf Mudrock Soup and Bugs, den ersten Teil Eurer Arbeit an Morgan Sterns neuem Rezept.",al={"vorherige quest ...und käfer","mudrock soup and bugs voraussetzung"}}},fp="12,178,22.341.0,20.91.0,33.134.0,41.90.0,29.92.0"}
P.entries["quest:1259"] = {n="Leutnant Paval Reethe",s="In Theramore bittet Euch Captain Garran Mumm, herauszufinden, wer Leutnant Paval Reethe ist.",h="In Theramore bittet Euch Captain Garran Mumm, herauszufinden, wer Leutnant Paval Reethe ist.",kw={"adjutant tesoran","captain garran mumm","düstermarschen","paval reethe","theramore"},sec={{t="Wer ist Reethe?",b="Captain Garran Mumm kann mit dem Namen Leutnant Paval Reethe nichts anfangen. Deshalb schickt er Euch zu Adjutant Tesoran in Theramore, der die Aufzeichnungen der Wache über ihre Mitglieder und Ausrüstung führt. Mumm erwartet, dass diese Aufzeichnungen zeigen, wer Reethe ist."}},faq={{q="Wer schickt Euch los, um mehr über Reethe herauszufinden?",a="Captain Garran Mumm schickt Euch los, um herauszufinden, wer Leutnant Paval Reethe ist. Er kann mit dem Namen nichts anfangen.",al={"wer startet leutnant paval reethe","reethe questgeber","wer vergibt die reethe-quest"}},{q="Wer führt die Aufzeichnungen der Wache von Theramore?",a="Adjutant Tesoran in Theramore führt Aufzeichnungen über die Mitglieder und die Ausrüstung der Wache von Theramore.",al={"wo ist adjutant tesoran","aufzeichnungsverwalter von theramore","wer hat die wachbücher"}},{q="Was kann Adjutant Tesoran Euch sagen?",a="Mumm erwartet, dass Tesorans Aufzeichnungen zeigen, wer Leutnant Paval Reethe ist.",al={"was weiß tesoran","tesorans bücher"}}},fp="23,84,14.233.0,39.103.0,40.90.0,35.73.0"}
P.entries["quest:126"] = {n="Geheul in den Hügeln",s="Gnollrufe beunruhigen die Hügel um Seenhain, wo Verner Gutmark ein Kopfgeld auf Jauler aussetzt. Da Sturmwinds Streitkräfte durch die Schwarzfelsorcs stark gebunden sind, verlässt sich die Stadt auf Besucher, die sich den Gnollen stellen.",h="Gnollrufe beunruhigen die Hügel um Seenhain, wo Verner Gutmark ein Kopfgeld auf Jauler aussetzt.",kw={"blackrock","gnolle","seenhain","tatze","rotkammgebirge","sturmwinds heer","verner gutmark","jauler"},ang={["class:Hunter"]="Als Jäger könnt Ihr Jauler in seinem Bergversteck aufspüren, indem Ihr auf Reviermarkierungen und Anzeichen für Rudelverhalten achtet.",["class:Warrior"]="Als Krieger stellt Ihr Euch Jauler, der sein Rudel durch körperliche Überlegenheit beherrscht und einen direkten Kräftemessen fordert.",["faction:Alliance"]="Als Abenteurer der Allianz könnt Ihr erkennen, wie Seenhains Abhängigkeit von Söldnern die Belastung widerspiegelt, die Sturmwinds Königreich schwächt."},sec={{t="Die Stimme in den Höhen",b="Gnollrufe hallen noch immer durch die Hügel des Rotkammgebirges, obwohl niedere Gnolle von den Pfaden um Seenhain vertrieben wurden. Verner Gutmark, der Hufschmied der Stadt, weiß, dass das Rudel weiter auf Raubzüge gehen wird, solange sein Anführer lebt. Jauler ist ein riesiger, gerissener Gnoll, dessen Rufe das Rudel durch die Hügel lenken. Verner verlangt Jaulers Tatze als Beweis für dessen Tod und das Verstummen der Rufe."},{t="Vom Heer im Stich gelassen",b="Sturmwinds östliche Grenzstädte stehen Gefahren gegenüber und erhalten kaum Hilfe vom Heer des Königreichs. König Varian Wrynn wird vermisst, und Streitigkeiten um die Regentschaft haben das Oberkommando gelähmt. Die königlichen Soldaten konzentrieren sich auf die Schwarzfelsorclans im Norden und lassen Seenhain ohne Verteidiger gegen die Gnolle zurück. Deshalb setzen Stadtbewohner wie Verner Gutmark selbst Kopfgelder aus, damit ihre Heimat nicht überrannt wird."}},faq={{q="Wer ist Jauler?",a="Jauler führt die Gnolle des Rotkammgebirges in den Hügeln vor Seenhain an. Verner zufolge ist er stärker und gefährlicher als gewöhnliche Gnolle und lenkt das Rudel gegen Reisende und Gehöfte.",al={"jauler","wer ist der gnollanführer","jauler hintergrundgeschichte","jauler gnoll"}},{q="Warum setzt Verner Gutmark dieses Kopfgeld aus und nicht die Stadtwache?",a="Verner Gutmark setzt das Kopfgeld aus, weil Seenhains Führung und Miliz mit den Schwarzfelsorcs überfordert sind. Als örtlicher Handwerker und Stallmeister ist er für seinen Lebensunterhalt auf sichere Straßen angewiesen und heuert umherziehende Söldner an, um unmittelbaren Gefahren zu begegnen.",al={"warum verner","warum nicht magistrat solomon","warum heuert gutmark söldner an"}},{q="Wo sind die Soldaten aus Sturmwind, die Seenhain beschützen sollten?",a="Sturmwinds Soldaten sind andernorts beschäftigt. Das Heer ist im Rotkammgebirge, um die Schwarzfelsorclans weiter oben in den Bergen zu beobachten und einzudämmen, wodurch Seenhain gegen örtliche Wildtiere, Murlocs und Gnolle ohne Unterstützung bleibt.",al={"wo ist das heer","warum keine wachen aus sturmwind","sturmwind militär seenhain"}},{q="Was geschieht mit den Gnollen des Rotkammgebirges, wenn Jauler tot ist?",a="Jaulers Tod zerschlägt die Führung des Gnollrudels und schwächt seine koordinierten Überfälle an den Stadtgrenzen. Gnolle bleiben in den zerklüfteten Höhen des Rotkammgebirges eine hartnäckige Plage.",al={"sind die gnolle fort","was geschieht nach jaulers tod"}},{q="Welche Vorquests führen zu diesem Auftrag?",a="Verner schickt Euch zunächst los, um in 'The Price of Shoes' und 'Return to Verner' Pferdezubehör zu beschaffen. Nachdem Ihr Euch um Underbelly Scales gekümmert und das Rudel in 'A Baying of Gnolls' dezimiert habt, setzt er das Kopfgeld auf Jauler aus.",al={"jauler questvoraussetzungen","geheul in den hügeln freischalten","questreihe für geheul in den hügeln"}},{q="Warum braucht Verner Jaulers Tatze als Beweis?",a="Verner braucht Jaulers abgetrennte Tatze als handfesten Beweis, bevor er das Kopfgeld auszahlt. Sie zeigt ihm und Seenhains beunruhigten Bewohnern, dass die Bestie, deren Rufe durch die Hügel hallen, gefallen ist.",al={"warum jaulers tatze","jaulers tatze beweis"}}},fx={f0418674={q="Warum möchte Verner Gutmark, dass Yowler getötet wird?",a="Verner hört die Gnolle Tag und Nacht heulen, während sie auf den Bergrücken oberhalb von Seenhain umherstreifen. Da die Armee von Sturmwind vollständig damit beschäftigt ist, gegen die Orcs des Schwarzfels zu kämpfen, sind die Einheimischen wie Verner gegenüber umherstreifenden Raubtieren schutzlos. Er glaubt, dass das Erlegen von Yowler, dem wilden Rudelführer, die Moral der Gnolle brechen und die Bestien zerstreuen wird, bevor sie direkt über die Stadt herfallen.",al={"verner gutmark motiv","warum yowler töten","verner howling in the hills motiv"}}},fp="20,204,24.368.0,28.391.0,14.185.0,67.253.0,68.222.0,56.168.0,50.204.0,43.185.0"}
P.entries["quest:1260"] = {n="Morgan Stern",s="In Theramore wartet Angus Stern auf Nachricht von Morgan Stern, der Rezepte für eine neue Speisekarte sammelt.",h="In Theramore wartet Angus Stern auf Nachricht von Morgan Stern, der Rezepte für eine neue Speisekarte sammelt.",kw={"angus stern","bayou","blue recluse","düstermarschen","morgan stern","sturmwind","theramore"},sec={{t="Eine Speisekarte im Bayou-Stil",b="Angus Stern möchte, dass die Gäste im Blue Recluse ländliche Gerichte im Bayou-Stil kosten. Er schickte seinen Neffen Morgan nach Theramore, der Stadt neben den Düstermarschen, um Rezepte von den Einheimischen zu sammeln. Die Reise ist für Angus zu lang, also bittet er Euch als jungen Reisenden, mit Morgan zu sprechen."},{t="Was Morgan zu sagen hat",b="In Theramore erzählt Morgan Stern, dass seine Suche nach Rezepten einige Spuren ergeben hat. Er braucht Hilfe, um ihnen nachzugehen, und die Arbeit verlangt nach jemandem, der bereit ist, sich die Füße nass zu machen."}},faq={{q="Wer ist Morgan Stern?",a="Morgan Stern ist der Neffe von Angus Stern. Angus schickte ihn nach Theramore, um Rezepte von den Einheimischen zu sammeln.",al={"wer ist morgan stern","morgan stern geschichte","angus stern neffe"}},{q="Warum möchte Angus Stern Morgan erreichen?",a="Angus stellt für das Blue Recluse eine neue Speisekarte mit ländlichen Gerichten im Bayou-Stil zusammen. Er möchte hören, was Morgan bisher herausgefunden hat.",al={"warum nach theramore schicken","blue recluse speisekarte","angus stern quest"}},{q="Wo ist Morgan Stern zu finden?",a="Morgan ist in Theramore, der Stadt neben den Düstermarschen.",al={"wo ist morgan stern","morgan stern aufenthaltsort","theramore koch aufenthaltsort"}}},fp="12,100,12.289.0,22.175.1,20.100.0,42.134.0,32.57.0"}
P.entries["quest:1261"] = {n="Marg spricht",s="Nahe Theramore lasten Margs gestohlener Anhänger und unerfüllte Pflicht noch immer auf Marg. Marg bittet Euch, die Muckshell zu finden, die Marg getötet hat, den edelsteinbesetzten Anhänger zurückzuholen, der Soldaten der Allianz gestohlen wurde, und ihn zu Nazeer Bloodpike in Brackenwall zu bringen.",h="Nahe Theramore lasten Margs gestohlener Anhänger und unerfüllte Pflicht noch immer auf Marg.",kw={"bloodpike","brackenwall","marg","muckshell","nazeer","anhänger","sturmwind","theramore"},sec={{t="Was Marg nahe Theramore sah",b="Soldaten der Allianz hatten am Strand nahe Theramore ihr Lager aufgeschlagen. Einer trug einen Anhänger mit mehr Edelsteinen, als ein Soldat bezahlen könnte. Marg schlich sich in jener Nacht ins Lager und stahl ihn. Auf dem Rückweg zur Basis wurde Marg von einem Muckshell-Krabbenmenschen getötet. Nun bittet Marg Euch, die Muckshell zu finden, den Anhänger zurückzuholen und ihn zu Nazeer in Brackenwall zu bringen."},{t="Was Nazeer davon hält",b="Nazeer ist bestürzt, dass ein Soldat aus Sturmwind den Anhänger trug. Ihr habt erfahren, wie Marg starb, doch der Anhänger wirft eine neue Frage auf. Nazeer warnt, dass er verheerende Folgen für die Allianz und die Horde haben könnte."}},faq={{q="Wer ist Marg und wie starb Marg?",a="Marg stahl einen edelsteinbesetzten Anhänger von Soldaten der Allianz, die nahe Theramore lagerten. Ein Muckshell-Krabbenmensch tötete Marg auf dem Rückweg zur Basis.",al={"wie starb marg","wer ist marg","margs geschichte"}},{q="Woher stammte der edelsteinbesetzte Anhänger?",a="Ein Soldat der Allianz trug den Anhänger in einem Strandlager nahe Theramore. Er war mit mehr Edelsteinen besetzt, als ein Soldat bezahlen könnte, und Marg stahl ihn in jener Nacht.",al={"woher stammte der anhänger","wer hatte den anhänger","herkunft von margs anhänger"}},{q="Wer erhält den zurückgeholten Anhänger?",a="Nazeer Bloodpike erhält den zurückgeholten Anhänger in Brackenwall.",al={"wer bekommt den anhänger","wohin den anhänger bringen","nazeer bloodpike anhänger"}},{q="Was kommt unmittelbar vor dieser Quest?",a="Sie folgt auf The Troll Witchdoctor.",al={"vorherige quest","welche quest kommt vor marg spricht"}}},fp="11,247,28.348.0,23.212.1,33.132.0,40.146.0,35.71.0,38.33.0"}
P.entries["quest:1262"] = {n="Bei Zor melden",s="Nazeer Bloodpike schickt Euch mit Margs juwelenbesetztem Anhänger nach Orgrimmar. Verwundert, dass einfache Soldaten ein so edles Stück bei sich trugen, bittet er Zor Einbaum, der die Politik der Allianz kennt, dessen Geschichte einzuschätzen.",h="Nazeer Bloodpike schickt Euch mit Margs juwelenbesetztem Anhänger nach Orgrimmar.",kw={"brackenwall","juwelenbesetzter anhänger","marg speaks","nazeer bloodpike","orgrimmar","bei zor melden","sturmwind","zor einbaum"},sec={{t="Der Anhänger eines Adligen",b="Nazeer Bloodpike findet es merkwürdig, dass einfache Soldaten einen so edlen Anhänger bei sich trugen. Vielleicht war sein Besitzer verkleidet, oder vielleicht haben die Soldaten ihn selbst gestohlen. Wie dem auch sei, Nazeer hält ihn für den Anhänger eines Adligen. Sein wahrer Besitzer muss gefunden werden, um das Geheimnis zu lüften. Zor Einbaum in Orgrimmar weiß viel über die Politik der Allianz und kann sagen, ob der Anhänger einst dem Adel von Sturmwind gehörte."},{t="Zors Urteil",b="Zor Einbaum bewundert die große Kunstfertigkeit, mit der der Anhänger gefertigt wurde. Orcs hätten keine Verwendung für ein solches Juwel, sagt er, doch viele Menschen schon. Zor wird ihn untersuchen lassen und hofft, dass seine Geheimnisse mit der Zeit ans Licht kommen."}},faq={{q="Warum wird der Anhänger nach Orgrimmar gebracht?",a="Nazeer Bloodpike hält ihn für den Anhänger eines Adligen. Zor Einbaum in Orgrimmar weiß viel über die Politik der Allianz und kann sagen, ob er eine Vergangenheit unter den Adligen von Sturmwind hat.",al={"warum anhänger nach orgrimmar schicken","warum nach orgrimmar gehen","warum zor einbaum aufsuchen"}},{q="Wer hatte den juwelenbesetzten Anhänger zuvor?",a="Marg hat den Anhänger von Soldaten in einem Lager der Allianz nahe Theramore gestohlen. Nazeer findet es merkwürdig, dass einfache Soldaten ihn bei sich trugen, und fragt sich, ob sein Besitzer verkleidet war oder die Soldaten ihn gestohlen haben.",al={"wer hatte den anhänger","woher kam der anhänger"}},{q="Was geschah vor dieser Quest?",a="Zuvor erzählte Euch Marg in Marg Speaks, dass er den Anhänger von Soldaten gestohlen hat, die nahe Theramore lagerten.",al={"vorherige quest","welche quest kommt davor"}},{q="Wo ist Zor Einbaum?",a="Zor Einbaum ist in Orgrimmar.",al={"zor einbaum aufenthaltsort","wo ist zor einbaum"}}},fp="13,197,17.379.0,13.204.1,44.167.0,39.200.0,28.104.0,22.29.0"}
P.entries["quest:1264"] = {n="Der vermisste Diplomat",s="Ein Schankwirt schickt Euch zu Kommandant Samaul in Theramore, wo Hendel vielleicht noch stationiert ist.",h="Ein Schankwirt schickt Euch zu Kommandant Samaul in Theramore, wo Hendel vielleicht noch stationiert ist.",kw={"schwarzdrachen","kommandant samaul","düstermarschen","elling","hendel","marines von kul tiras","miss proudmoore","theramore"},sec={{t="Eine Spur in Theramore",b="Der Schankwirt glaubt, Hendel sei unter den Marines von Kul Tiras, die regelmäßig vorbeischauen. Sie erhalten zu Beginn jedes Monats ihren Sold und verlassen Theramore gewöhnlich danach. Kommandant Samaul weiß vielleicht, ob Hendel noch dort stationiert ist. Erwähnt Ellings Namen, dann hilft Samaul Euch vielleicht diskret."},{t="Samauls Warnung",b="Kommandant Samaul ist der Offizier, der Miss Proudmoores Streitkräfte in Theramore befehligt. Er ist beschäftigt, bietet aber an, Eure Fragen zu beantworten. Im Marschland jenseits der Stadt leben Oger, Orcs und Murlocs. In seinen südlichen Ausläufern hausen Schwarzdrachen."}},faq={{q="Wer ist Hendel?",a="Hendel ist ein Marine von Kul Tiras, der vielleicht zu den regelmäßigen Gästen einer Taverne gehört. Der Schankwirt glaubt, Kommandant Samaul in Theramore wisse vielleicht, ob Hendel noch dort stationiert ist.",al={"hendel","marine hendel","wer ist hendel"}},{q="Wer ist Kommandant Samaul?",a="Kommandant Samaul befehligt Miss Proudmoores Streitkräfte in Theramore.",al={"samaul","der kommandant","kommandant von theramore"}},{q="Warum suche ich Samaul?",a="Der Schankwirt glaubt, Samaul könne Euch helfen, Hendel zu finden, falls Hendel noch in Theramore stationiert ist.",al={"samaul finden","warum samaul","quest missing diplomat"}},{q="Wer ist Elling?",a="Der Schankwirt rät Euch, Ellings Namen zu erwähnen, wenn Ihr Kommandant Samaul nach Hendel fragt.",al={"elling","ellings namen erwähnen","ellings name"}},{q="Wann verlassen die Marines von Kul Tiras Theramore?",a="Die Marines von Kul Tiras erhalten zu Beginn jedes Monats ihren Sold und verlassen Theramore gewöhnlich danach.",al={"marines brechen auf","zahltag","wann gehen sie"}},{q="Welche Gefahren erwähnt Samaul?",a="Samaul warnt vor Ogern, Orcs und Murlocs im Marschland jenseits der Stadt und vor Schwarzdrachen in seinen südlichen Ausläufern.",al={"gefahren in theramore","was ist im sumpf","gefahren im marschland"}}},fp="20,96,19.286.0,16.234.0,14.179.0,24.71.0,28.101.0,14.98.0,46.100.0,33.112.0"}
P.entries["quest:1265"] = {n="Der vermisste Diplomat",s="Elling schickt Euch auf die Suche nach Private Hendel, und ein örtlicher Offizier befürchtet einen beunruhigenden Grund. Hendel war bei der Späherwacht stationiert, dem ersten Turm außerhalb Theramores, wo Ihr nach Spuren von ihm suchen sollt.",h="Elling schickt Euch auf die Suche nach Private Hendel, und ein örtlicher Offizier befürchtet einen...",kw={"elling","hendel","offizier","private hendel","späherwacht","theramore","turm"},sec={{t="Am Turm",b="Ein örtlicher Offizier kennt Private Hendel und sagt, er sei bei der Späherwacht stationiert gewesen, dem ersten Turm außerhalb Theramores. Der Offizier befürchtet, Elling habe Euch zuerst dorthin geschickt, weil Euer Anliegen beunruhigend sein könnte. Erzählt dem Offizier, was Ihr mitteilen könnt. Die Wache muss diese Lande schützen, daher ist jede Unruhe von Bedeutung."}},faq={{q="Wer ist Private Hendel?",a="Private Hendel ist der Mann, den Ihr im Auftrag von Elling finden sollt. Ein örtlicher Offizier sagt, Hendel sei am ersten Turm außerhalb Theramores stationiert gewesen.",al={"private hendel","wer ist hendel","hendels hintergrund"}},{q="Wo soll ich nach Hendel suchen?",a="Sucht bei der Späherwacht nach Spuren von Private Hendel, dem ersten Turm außerhalb Theramores.",al={"hendels aufenthaltsort","wo ist hendel","späherwacht hendel"}},{q="Wer hat mich geschickt, um Hendel zu finden?",a="Elling hat Euch geschickt, um Private Hendel zu finden.",al={"wer hat mich geschickt","elling hendel","suche nach hendel"}},{q="Warum ist der Offizier besorgt?",a="Der Offizier befürchtet, Elling habe Euch zuerst dorthin geschickt, weil Euer Anliegen beunruhigend sein könnte. Der Offizier möchte wissen, was Ihr mitteilen könnt, um die Lande zu schützen.",al={"warum besorgt","offizier besorgt","was ist beunruhigend"}}},fp="20,210,12.301.0,22.130.0,31.84.0,27.39.0,29.152.0"}
P.entries["quest:1266"] = {n="The Missing Diplomat",s="Theramores Leute beobachten Brackenwall und andere Gefahren nahe ihren Grenzen. Ihr werdet nach Westen durch die Düstermarschen geschickt, um Private Hendel zu finden.",h="Theramores Leute beobachten Brackenwall und andere Gefahren nahe ihren Grenzen.",kw={"brackenwall","düstermarschen","hordestützpunkt","infiltratoren","private hendel","the missing diplomat","theramore"},ang={["faction:Alliance"]="Als Reisender der Allianz werdet Ihr losgeschickt, um einen Wachmann aus Theramore zu finden, der den Hordestützpunkt Brackenwall und weitere Bedrohungen für die Grenzen beobachtet."},sec={{t="Die Straße nach Westen",b="Eine Wachmannschaft wartet westlich von Euch in den Düstermarschen, wo Private Hendel über Theramores Infiltratoren wacht. Sie haben Brackenwall beobachtet und nach weiteren Bedrohungen nahe den Grenzen gesucht. Sucht nach den Zelten entlang der Straße, um Hendel zu finden."}},faq={{q="Wer ist Private Hendel?",a="Private Hendel hält Wache und beschützt Theramores Infiltratoren, während sie sich ausruhen.",al={"private hendel","hendel wer","wer ist hendel"}},{q="Was beobachten die Infiltratoren?",a="Sie haben Brackenwall, den Stützpunkt der Horde, im Auge behalten und nach weiteren Bedrohungen für Theramores Grenzen gesucht.",al={"was beobachten sie","brackenwall beobachten","infiltratoren"}},{q="Wo kann ich Private Hendel finden?",a="Private Hendel ist westlich von Euch bei den Zelten entlang der Straße in den Düstermarschen.",al={"wo hendel","hendel finden","hendel standort"}},{q="Warum sind die Infiltratoren dort?",a="Sie beobachten Brackenwall und suchen nach weiteren Gefahren nahe Theramores Grenzen.",al={"warum infiltratoren","theramore spione","was machen sie"}}},fp="20,148,19.250.0,22.85.0,35.113.0,32.79.0,31.85.0"}
P.entries["quest:1268"] = {n="Verdächtige Hufabdrücke",s="Am Gasthaus Zur süßen Ruh führen Hufabdrücke in den Sumpf. Sein bloßes Gerippe raucht noch, und die Spuren verlieren sich im weichen Boden. Krog in Brackenwall sollte davon erfahren.",h="Am Gasthaus Zur süßen Ruh führen Hufabdrücke in den Sumpf.",kw={"brackenwall","zentauren","düstermarschen","hufabdrücke","kagoro","krog","borstennacken","gasthaus zur süßen ruh","verdächtige hufabdrücke"},sec={{t="Abdrücke im Schlamm",b="Das Gasthaus Zur süßen Ruh ist ein rauchendes Gerippe, von dem Hufabdrücke in den Sumpf führen. Einige Abdrücke sind deutlich zu erkennen, während andere im weichen Boden beinahe verloren gehen. Ihr überbringt Krog in Brackenwall Nachricht von den Spuren."},{t="Krogs Antwort",b="Krog vermutet, dass die Borstennacken oder die Zentauren das Gasthaus niedergebrannt haben könnten. Beide sind im Brachland stark vertreten, und beide kämen als Täter infrage. Der Besitzer des Gasthauses verlor außerdem eine Frau und ein Junges, die beide getötet wurden. Deshalb schickt Krog Kagoro los, um herauszufinden, wohin die Spuren führen."}},faq={{q="Wo sind die Hufabdrücke?",a="Die Hufabdrücke führen vom Gasthaus Zur süßen Ruh weg, dessen bloßes Gerippe noch raucht, und über den weichen Boden des Sumpfes.",al={"hufabdrücke fundort","wo sind die spuren","gasthaus zur süßen ruh abdrücke"}},{q="Wer sollte von den Hufabdrücken erfahren?",a="Ihr solltet Krog in Brackenwall von den Hufabdrücken berichten.",al={"wem berichten","krog aufenthaltsort","wo hufabdrücke melden"}},{q="Wie viele Abdrücke gibt es?",a="Einige wenige Hufabdrücke sind deutlich zu erkennen, während weitere Reihen im Schlamm beinahe verloren gehen.",al={"wie viele hufabdrücke","wie viele spuren"}}},fp="21,176,17.227.0,12.254.1,25.115.0,37.64.0,26.74.0"}
P.entries["quest:1269"] = {n="Leutnant Paval Reethe",s="In Brackenwall erwartet Krog das Abzeichen von Leutnant Paval Reethe und Neuigkeiten vom Gasthaus Zur süßen Ruh.",h="In Brackenwall erwartet Krog das Abzeichen von Leutnant Paval Reethe und Neuigkeiten vom Gasthaus Zur süßen...",kw={"abzeichen","brackenwall","insignie","krog","ogron","paval","reethe","theramore"},sec={{t="Ein Glanz in den Trümmern",b="Unter Trümmern und Gestrüpp findet Ihr ein Abzeichen mit dem Zeichen von Theramore. Asche und Schutt bedecken es, doch unter dem goldenen Anker ist der Name von Leutnant Paval Reethe eingeprägt. Krog wartet in Brackenwall. Er fragt, ob Ihr erfahren habt, was dem Gasthaus Zur süßen Ruh widerfahren ist."},{t="Was Krog weiß",b="Krog nennt Paval Reethe einen erbärmlichen Menschen, der die Soldaten im Stich ließ, mit denen er diente. Nun versteckt sich Reethe in den Wäldern. Krog verdächtigt ihn, Vorräte zu stehlen, und hat deshalb Ogron losgeschickt, um ihn aufzuspüren. Andere teilen diesen Verdacht. Krog glaubt, dass Ogron auf dem Weg nach Südosten gesehen wurde."}},faq={{q="Was steht auf dem Abzeichen?",a="Das Abzeichen trägt das Zeichen von Theramore, einen goldenen Anker auf weißem Email. Darunter ist der Name von Leutnant Paval Reethe eingeprägt.",al={"was steht auf dem abzeichen","zeichen auf dem abzeichen der wache von theramore","wem gehört das abzeichen"}},{q="Wer bekommt das Abzeichen?",a="Bringt das Abzeichen zu Krog in Brackenwall.",al={"zu wem das abzeichen bringen","wohin gehört reethes abzeichen","abzeichen abgeben"}},{q="Wo wurde das Abzeichen gefunden?",a="Ihr habt das Abzeichen unter Trümmern gefunden, verkrustet mit Asche und Schutt. Krog fragt, ob Ihr erfahren habt, was dem Gasthaus Zur süßen Ruh widerfahren ist.",al={"fundort des abzeichens","wo wurde reethes abzeichen gefunden"}}},fp="23,99,21.269.0,15.265.1,21.123.0,19.47.0,26.127.0"}
P.entries["quest:127"] = {n="Fischhandel",s="Hafenmeister Baren braucht Gefleckte Sonnenfische aus dem Immerruhsee. Die Fische ernähren Seenhain, doch Murlocs am Ufer machen ihren Fang gefährlich.",h="Hafenmeister Baren braucht Gefleckte Sonnenfische aus dem Immerruhsee.",kw={"hafenmeister baren","der immerruhsee","seenhain","murloc","rotkammgebirge","fischhandel","gefleckter sonnenfisch"},ang={["faction:Alliance"]="Als Reisende der Allianz könnt Ihr helfen, die Nahrungsversorgung des Rotkammgebirges zu sichern, da das Königreich Sturmwind der Region kaum militärische Hilfe bietet.",["profession:Cooking"]="Als Koch könnt Ihr in Seenhains Gewässern nach Gefleckten Sonnenfischen suchen, einer in der Stadt geschätzten Süßwasserdelikatesse."},sec={{t="Ein Grundnahrungsmittel vom Immerruhsee",b="Gefleckte Sonnenfische sind rund um den Immerruhsee begehrt, und Stadtbewohner sowie durchreisende Händler halten die Nachfrage hoch. Dennoch werden Seenhains Vorräte oft knapp, obwohl die Fische unter der Wasseroberfläche schwimmen. Örtliche Bedrohungen bringen die Stadt an ihre Grenzen, sodass selbst der grundlegende Handel von Reisenden abhängt."},{t="Ärger im flachen Wasser",b="Die Angler der Umgebung konnten Hafenmeister Barens Aufträge einst mühelos erfüllen. Heute treiben aggressive Murlocstämme im flachen Wasser und an den Ufern ihr Unwesen und halten gewöhnliche Stadtbewohner vom Wasser fern. Ihr könnt angeln und dabei nach Gefahren Ausschau halten oder den nahrungssuchenden Murlocs, die das Ufer heimsuchen, Sonnenfische abnehmen."}},faq={{q="Wer ist Hafenmeister Baren?",a="Hafenmeister Baren beaufsichtigt die Anlegestellen und den Bootsverkehr auf dem Immerruhsee in Seenhain. Er verwaltet den Handel der Stadt auf dem Wasser und verlässt sich auf fähige Reisende, die frischen Fisch bringen und Bedrohungen am See entgegentreten.",al={"baren","wer ist der hafenmeister","hafenmeister baren"}},{q="Warum sind Gefleckte Sonnenfische so gefragt?",a="Gefleckte Sonnenfische sind rund um den Immerruhsee berühmt und daher ein Grundnahrungsmittel sowie ein wichtiges Handelsgut in Seenhain. Die Vorräte der Stadt werden knapp, weil gewöhnliche Angler nicht sicher fischen können, solange feindselige Kreaturen den See heimsuchen.",al={"warum sonnenfische","geschichte der gefleckten sonnenfische","warum braucht seenhain fisch"}},{q="Wie kommen Murlocs an die Sonnenfische?",a="Die Murlocstämme am Immerruhsee suchen im flachen Wasser nach Nahrung und jagen dort. Sie töten oder vertreiben einheimische Fischer und sammeln dann Fische für ihre Lager, wo Reisende den Fang erbeuten können, statt selbst zu angeln.",al={"murlocfische","warum lassen murlocs fische fallen","murlocs stehlen fische"}},{q="Wo findet man Gefleckte Sonnenfische?",a="Gefleckte Sonnenfische leben im Immerruhsee im Rotkammgebirge. Ihr könnt sie mit einer Angel fangen oder sie Murlocs an den Ufern und im flachen Wasser abnehmen.",al={"wo sind sonnenfische","fische im immerruhsee finden","wie bekommt man gefleckte sonnenfische"}},{q="Wie hängt diese Quest mit Murloc Poachers zusammen?",a="Hafenmeister Baren bietet Hilfe gegen die wildernden Murlocs an, während er nach Sonnenfischen sucht. Da Murlocs am See umherstreifen und seine Fische fangen, lässt sich im Kampf gegen sie auch ihr gesammelter Fang erbeuten.",al={"verbindung zu murloc poachers","barens andere quest","quests des hafenmeisters"}},{q="Muss man angeln, um Hafenmeister Baren zu helfen?",a="Ihr braucht weder Angelausrüstung noch Angelfertigkeiten, um Hafenmeister Baren zu helfen. Ihr könnt Sonnenfische angeln oder den Murlocstämmen, die im See jagen, die Fische mit Gewalt abnehmen, wie Baren offen vorschlägt.",al={"ist angeln nötig","geht es ohne angel","angeln erforderlich"}}},fx={["2b5f9eab"]={q="Warum benötigt Hafenmeister Baren mehr Gefleckter Sonnenfisch?",a="Der Immerruhsee ist für seinen Gefleckten Sonnenfisch bekannt, was stetigen Handel und Appetit schafft, die Hafenmeister Baren an den Docks von Seenhain beschäftigen. Da sein lokaler Vorrat gefährlich knapp wird, benötigt er eine frische Charge von zehn Stück, um die Nachfrage zu erfüllen und seinen Tauschhandel am Laufen zu halten.",al={"warum will baren fisch","hafenmeister baren motiv","warum selling fish"}},d0647bad={q="Wozu wird der Gefleckter Sonnenfisch verwendet?",a="Gefleckter Sonnenfisch sind Süßwasserfische, die im Immerruhsee beheimatet sind und im gesamten Rotkammgebirge für ihren Geschmack geschätzt werden. Sie dienen als lokales Grundnahrungsmittel und als wertvolles Handelsgut für den Handel in Seenhain, das bei Reisenden und Bewohnern gleichermaßen einen zuverlässigen Absatz findet.",al={"was sind gefleckte sonnenfische","hintergrund gefleckter sonnenfisch","wofür wird gefleckter sonnenfisch verwendet"}}},fp="12,143,26.271.0,23.275.0,24.207.0,44.220.0,39.204.0,35.155.0,45.192.0,45.181.0"}
P.entries["quest:1270"] = {n="Stinkis Flucht",s="Im Sumpf wird Stinki Ignatz von Kreaturen umzingelt, bevor er Fieberklee findet. Mebok Mizzyrix aus Ratschet braucht die Blätter für einen Trank, also bittet Ignatz Euch, ihn zu befreien und bei seiner Suche zu beschützen. Sucht danach Mebok in Ratschet auf.",h="Im Sumpf wird Stinki Ignatz von Kreaturen umzingelt, bevor er Fieberklee findet.",kw={"fieberklee","düstermarschen","begleitung","mebok mizzyrix","ratschet","stinki ignatz"},sec={{t="Umzingelt im Sumpf",b="Stinki Ignatz ist froh, jemanden zu treffen, der ihn nicht fressen will. Mebok Mizzyrix, ein Goblin aus Ratschet, braucht Fieberkleeblätter für einen Trank. Ignatz sagt, der Grund sei egal; die Bezahlung war gut, und er kennt den Sumpf. Doch bevor er die Pflanze fand, wurde er von Kreaturen umzingelt. Er bittet Euch, ihm bei der Flucht zu helfen und ihn bei seiner Suche zu beschützen."},{t="Nachricht von Mebok",b="Mebok sagt, Ignatz sei mit den Kräutern zurückgekehrt und habe ihm erzählt, wie Ihr geholfen habt. Ein Freund von Stinki ist auch sein Freund. Bevor Ignatz wieder nach Süden ins Moor aufbrach, bat er Mebok, Euch etwas zu geben, falls Ihr ihm je begegnen solltet."}},faq={{q="Wer ist Stinki Ignatz?",a="Stinki Ignatz sucht im Sumpf nach Fieberkleeblättern für Mebok Mizzyrix. Er sagt, er kenne den Sumpf, doch Kreaturen umzingelten ihn, bevor er die Pflanze fand.",al={"wer ist stinki","stinki ignatz","wer ist der mann zum begleiten"}},{q="Warum sammelt Ignatz Fieberkleeblätter?",a="Mebok Mizzyrix, ein Goblin aus Ratschet, braucht Fieberkleeblätter für einen Trank. Ignatz sagt, der Grund sei egal; die Bezahlung war gut.",al={"warum fieberklee","wofür ist fieberklee","mebok fieberklee"}},{q="Wer ist Mebok Mizzyrix?",a="Mebok Mizzyrix ist ein Goblin aus Ratschet, der Fieberkleeblätter braucht, um einen Trank zu brauen.",al={"mebok","wer ist mebok mizzyrix","goblin in ratschet"}},{q="Mit wem solltet Ihr danach sprechen?",a="Sucht Mebok Mizzyrix in Ratschet auf, nachdem Ihr Ignatz geholfen habt.",al={"wohin geht stinki","wo stinkis flucht abgeben"}}},fp="15,223,23.341.0,15.212.1,23.164.0,39.131.0,22.82.0,34.53.0"}
P.entries["quest:1271"] = {n="Festmahl im Blauen Eremiten",s="In den Düstermarschen schließt Ihr Eure Arbeit für Morgan Stern mit ... and Bugs ab und kehrt dann zu Angus Stern im Blauen Eremiten zurück.",h="In den Düstermarschen schließt Ihr Eure Arbeit für Morgan Stern mit ...",kw={"angus stern","düstermarschen","festmahl im blauen eremiten","familie stern","der blaue eremit","morgan stern"},sec={{t="Zurück zum Blauen Eremiten",b="Angus Stern ist Morgan Sterns Onkel. Ihr kehrt zu Angus im Blauen Eremiten zurück, nachdem Ihr Morgan bei seiner Rezeptforschung in den Düstermarschen geholfen habt."},{t="Was Angus gehört hat",b="Angus hat von Morgan gehört, dass Ihr seine Forschung unterstützt und einem seiner Gefährten aus der Klemme geholfen habt. Die Sterns kümmern sich um ihre Freunde, und ein Fest zu Euren Ehren beginnt in Kürze."}},faq={{q="Wer ist Angus Stern?",a="Angus Stern ist Morgan Sterns Onkel und steht mit dem Blauen Eremiten in Verbindung.",al={"angus stern","gastgeber im blauen eremiten","wer veranstaltet das festmahl"}},{q="In welchem Verhältnis steht Angus Stern zu Morgan Stern?",a="Angus ist Morgans Onkel. Er schickte Morgan nach Theramore, um Rezepte für die neue Speisekarte des Blauen Eremiten zum Thema Bayou zu sammeln.",al={"verwandtschaft angus morgan","familie stern","ist morgan angus’ neffe"}},{q="Welche Quest geht dieser voraus?",a="Sie folgt auf ... and Bugs, Eure letzte Aufgabe für Morgan Stern in Theramore.",al={"vorherige quest","was kommt vor dem festmahl"}}},fp="25,125,24.135.0,20.191.1,19.73.0,45.116.0,29.77.0"}
P.entries["quest:1273"] = {n="Befragt Reethe",s="Ogron hat Reethe endlich gefunden und bittet Euch, bei seiner Befragung zu helfen. Er meint, Reethe habe sich für einen Menschen gut versteckt, doch die Tage im Sumpf könnten ihn um den Verstand gebracht haben. Danach kehrt Ihr zu Krog in Brackenwall zurück.",h="Ogron hat Reethe endlich gefunden und bittet Euch, bei seiner Befragung zu helfen.",kw={"brackenwall","dustwallow","verhör","krog","sumpf","ogron","reethe"},sec={{t="Ogrons Suche",b="Ogron hat Reethe nach langer Suche gefunden. Nach Ogrons Einschätzung hat sich Reethe für einen Menschen gut versteckt. Doch Ogron fürchtet, die Tage im Sumpf könnten Reethe den Verstand geraubt haben, und möchte Euch an seiner Seite haben, um Antworten zu erhalten. Sobald Ihr mit Reethe gesprochen habt, kehrt Ihr zu Krog in Brackenwall zurück."},{t="Zurück bei Krog",b="Krog ist erfreut, dass Reethe aus dem Sumpf verschwunden ist. Er verspottet Menschen als zu schwächlich, um sich selbst von einer kleinen Pfeilwunde zu erholen. Krog kommt zu dem Schluss, dass diese Spur des Rätsels ins Nichts führte. Die Suche muss anderswo weitergehen."}},faq={{q="Wer hat Reethe gefunden?",a="Ogron hat Reethe nach langer Suche gefunden und möchte Euch an seiner Seite haben, um Antworten zu erhalten.",al={"wer vergibt befragt reethe","befragt reethe questgeber","ogron reethe"}},{q="Warum möchte Ogron Begleitung?",a="Ogron fürchtet, Reethe könnte nach so langer Zeit im Sumpf den Verstand verloren haben.",al={"warum ogron helfen","ist reethe verrückt","warum reethe zur rede stellen"}},{q="Wem erstattet Ihr danach Bericht?",a="Ihr erstattet Krog in Brackenwall Bericht.",al={"wo befragt reethe abgeben","mit wem nach reethe sprechen","reethe abgeben"}}},fp="18,210,14.273.0,14.208.1,17.79.0,28.64.0,31.42.0"}
P.entries["quest:1274"] = {n="Der vermisste Diplomat",s="Eine leise Bitte in Sturmwind führt Euch zu Bischof DeLavey in Burg Sturmwind. Kirche und Krone brauchen Hilfe in einer Angelegenheit, die für öffentliche Wege zu gefährlich ist.",h="Eine leise Bitte in Sturmwind führt Euch zu Bischof DeLavey in Burg Sturmwind.",kw={"bischof delavey","diplomat","ermittlung","burg sturmwind","der vermisste diplomat","thomas"},ang={["faction:Alliance"]="Den vermissten Diplomaten zu finden, ist für den Zusammenhalt und die Verteidigung der Allianz von Bedeutung. Die Untersuchung könnte Bedrohungen an Sturmwinds eigenem Hof aufdecken.",["race:Human"]="Als Mensch aus Sturmwind steht Ihr vor einer Angelegenheit, die mit der Stabilität Eurer Heimat während einer unsicheren Regentschaft verbunden ist."},sec={{t="Ein stiller Ruf",b="Während Ihr durch Sturmwind reist, tritt Thomas, ein Messdiener, mit einer leisen Bitte an Euch heran. Bischof DeLavey, ein angesehener Geistlicher der Kirche des Heiligen Lichts, braucht in Burg Sturmwind die Hilfe eines Außenstehenden. Er nennt die Angelegenheit heikel und dringend. Ihr müsst diskret vorgehen, damit die Bevölkerung nicht in Panik gerät."},{t="Flüstern in der Burg",b="In Burg Sturmwind erklärt Euch Bischof DeLavey, warum die Angelegenheit geheim bleiben muss: Ein hochrangiger Würdenträger des Königreichs ist unter mysteriösen Umständen verschwunden. Im Inneren brauen sich Unruhen zusammen, und König Varian Wrynn wird vermisst. Jedes Anzeichen eines Verbrechens in den höchsten Rängen des Königreichs könnte dessen zerbrechlichen Frieden gefährden."}},faq={{q="Wer ist Thomas?",a="Thomas ist ein Messdiener in der Kathedrale des Lichts, der Botengänge für Bischof DeLavey erledigt. Er hält auf Sturmwinds Straßen nach fähigen Abenteurern Ausschau und schickt sie zur Burg, wenn kirchliche oder staatliche Angelegenheiten diskrete Hilfe erfordern.",al={"wer ist thomas","thomas sturmwind","thomas questgeber"}},{q="Wer ist Bischof DeLavey?",a="Bischof DeLavey ist ein hochrangiger Geistlicher der Kirche des Heiligen Lichts in Burg Sturmwind. Er arbeitet mit dem königlichen Hof an vertraulichen Sicherheitsfragen und heiklen Ermittlungen, denen die Stadtwachen nicht offen nachgehen können.",al={"wer ist bischof delavey","delavey","bischof delavey"}},{q="Warum wird diese Angelegenheit geheim behandelt?",a="In Sturmwind herrscht bereits Unruhe: König Varian Wrynn wird vermisst, und die Bruderschaft der Defias schürt in ganz Westfall eine Rebellion. Die Nachricht, dass ein weiterer bedeutender Diplomat oder Amtsträger verschwunden ist, könnte Panik verbreiten oder Schwächen am Hof offenlegen.",al={"warum diskret","warum geheimhaltung","warum geheim"}},{q="Wohin führt diese Ermittlung?",a="Die Untersuchung beginnt bei Bischof DeLavey in Burg Sturmwind. Sie führt durch Sturmwind und die umliegenden Gebiete der Menschen, dann in gefährliche Länder jenseits des Meeres.",al={"wohin führt der vermisste diplomat","der vermisste diplomat nächster schritt"}},{q="Wer ist der vermisste Diplomat?",a="Bischof DeLavey hält die Identität des Diplomaten zu Beginn der Untersuchung geheim. Sie preiszugeben könnte die Ermittlungen gefährden und den vermissten Amtsträger sowie das Königreich in Gefahr bringen.",al={"wer ist der diplomat","identität des vermissten diplomaten"}}},fx={["46e2b0bf"]={q="Warum will Thomas, dass Ihr Bischof DeLavey aufsucht?",a="Der junge Thomas handelt direkt auf Befehl von Bischof DeLavey. DeLavey hat ihn damit beauftragt, unauffällig fähige Abenteurer in ganz Sturmwind auszukundschaften, die sich einer heiklen und dringenden Angelegenheit für das Königreich annehmen könnten. Thomas hat kein persönliches Interesse daran, außer dem Bischof gewissenhaft zu dienen und dafür zu sorgen, dass Ihr die Burg erreicht, ohne Alarm zu schlagen.",al={"warum schickt thomas euch","thomas motiv vermisster diplomat","warum bischof delavey aufsuchen"}},["227c4a3f"]={q="Warum rekrutiert Bischof DeLavey Abenteurer anstelle der Stadtwache?",a="Die Mission betrifft eine Angelegenheit von größter Bedeutung, die streng vertraulich bleiben muss. Die Mobilisierung der Stadtwache von Sturmwind oder die Aufmerksamkeit des offiziellen Militärs würde das Risiko bergen, dass sensible Informationen in der ganzen Stadt durchsickern. Indem Thomas diskret unabhängige Abenteurer wie Euch anspricht, kann der Bischof seine stillen Nachforschungen anstellen, ohne potenzielle Feinde zu alarmieren oder die Öffentlichkeit zu beunruhigen.",al={"warum nicht die stadtwache","warum abenteurer rekrutieren vermisster diplomat","warum braucht bischof delavey euch"}}},fp="20,154,15.290.0,20.306.1,14.221.0,22.207.0,37.236.0,35.165.0,28.177.0"}
P.entries["quest:1275"] = {n="Erforschung der Verderbnis",s="In Auberdine sucht Gershala Nachtraunen verdorbene Hirnstämme aus der Tiefschwarzen Grotte. Blutelfen jenseits des Meeres sollen sich dämonischer Magie zuwenden. Er hofft, von den Naga und Satyren zu lernen, wie er verhindern kann, dass sich die Geschichte wiederholt.",h="In Auberdine sucht Gershala Nachtraunen verdorbene Hirnstämme aus der Tiefschwarzen Grotte.",kw={"eschental","auberdine","tiefschwarze grotte","blutelfen","verderbter hirnstamm","the corruption abroad","gershala nachtraunen","naga","satyren"},ang={["class:Druid"]="Als Druide empfindet Ihr Abscheu vor Satyren. Ihre Teufelsverderbnis entweiht den natürlichen Traum und verformt das Land.",["class:Mage"]="Als Magier erkennt Ihr den körperlichen und geistigen Preis einer leichtfertigen Abhängigkeit von Magie.",["faction:Alliance"]="Als Mitglied der Allianz hört Ihr Berichte von Blutelfen jenseits des Meeres, die sich den dunklen Künsten zuwenden. Ihr fürchtet eine neue dämonische Bedrohung.",["race:NightElf"]="Als Nachtelf lebt Ihr mit einer Wunde, die im Gedächtnis Eures Volkes noch frisch ist. Eure Verwandten wurden zu den Satyren und Naga, die Kalimdor heimsuchen."},sec={{t="Eine Warnung aus der Geschichte",b="Nachtelfen in ganz Kalimdor erinnern sich noch an den Untergang ihrer uralten Verwandten. Vor zehntausend Jahren erlagen die Hochgeborenen dämonischen Energien und wurden zu Satyren oder Naga. Nun nennen sich die Hochelfen Blutelfen und verschreiben sich der dunklen Magie. Gershala Nachtraunen sieht das alte Unheil erneut Gestalt annehmen."},{t="Hinab in die Grotte",b="Die Tiefschwarze Grotte bietet Gershala einen Ort, um die Verderbnis zu erforschen. Ihre Tempelruinen liegen unter dem Zoramstrand in Eschental, wo Satyrenkultisten und Naga hausen. Er bittet Euch, Hirnstämme von beiden zu sammeln. Er hofft, den Zusammenhang zwischen Arkansucht, dämonischer Verderbnis und körperlichem Verfall aufzuspüren."},{t="Ein verzweifeltes Heilmittel",b="Gershala erforscht den Körper in der Hoffnung, einen weiteren Untergang zu verhindern. Die gemeinsamen Mutationen von Satyren und Naga könnten ihm zeigen, wie er die Blutelfen vor der Verdammnis bewahren kann. Können Forschungen an der Dunkelküste die verzweifelten Elfen von Quel'Thalas umstimmen? Die Antwort bleibt ungewiss."}},faq={{q="Warum kümmert sich Gershala Nachtraunen um die Blutelfen?",a="Gershala fürchtet, dass die Hinwendung der Blutelfen zu dämonischen Mächten ein weiteres Volk entstellter Ungeheuer hervorbringen könnte. Einst ließ elfischer Hochmut die Satyren und Naga entstehen.",al={"warum blutelfen helfen","gershalas verbindung zu blutelfen","auberdine blutelfen"}},{q="Wo sammelt Ihr die verdorbenen Hirnstämme?",a="Sammelt Hirnstämme von Satyren und Naga in der Tiefschwarzen Grotte. Die uralte Tempelanlage liegt unter dem Zoramstrand an Eschentals Nordwestküste.",al={"wo sind hirnstämme","hirnstamm fundort","verdorbener hirnstamm beute"}},{q="Warum will er gerade Proben von Satyren und Naga?",a="Satyren und Naga waren ursprünglich Elfen, die durch unnatürliche Kräfte entstellt wurden. Satyren wurden durch dämonische Pakte verwandelt, während die Sundering die Naga hervorbrachte. Gershala vergleicht die Mutationen ihrer Gehirne, um zu erfahren, wie dunkle Macht elfischen Körpern schadet.",al={"warum satyren und naga","verbindung zwischen satyren und naga"}},{q="Wer führt Euch zu dieser Aufgabe?",a="Eine einführende Quest namens The Corruption Abroad kann Euch zu Gershala Nachtraunen in Auberdine führen. Er kann Euch die Untersuchung auch direkt anbieten.",al={"vorausgesetzte quest","the corruption abroad zusammenhang"}},{q="Was hat Gershala mit den Proben vor?",a="Gershala will die körperlichen Auswirkungen der beiden Formen der Verderbnis vergleichen. Er hofft, mit seinen Erkenntnissen die Verwandlung der Blutelfen in Ungeheuer verlangsamen zu können.",al={"hirnstamm untersuchung","gershalas forschungsziel"}},{q="Ist Auberdine unmittelbar durch die Tiefschwarze Grotte bedroht?",a="Die Tiefschwarze Grotte liegt gleich jenseits von Eschentals Südgrenze. Die Nachtelfen von Auberdine beobachten die Küste auf Anzeichen zunehmender dämonischer Verderbnis und Twilight-Verderbnis.",al={"warum auberdine sich kümmert","tiefschwarze grotte bedrohung dunkelküste"}}},fx={["57dc4e51"]={q="Gegen wen werdet Ihr in der Tiefschwarzen Grotte ausgesandt?",a="Gershala sendet Euch gegen die Satyrn und Naga aus, die in der Tiefschwarzen Grotte an der Küste des Eschentals hausen. Beide Spezies waren einst Nachtelfen, bevor sie groteske magische Verwandlungen durchliefen – die Satyrn wurden während des Krieges der Ahnen durch dämonische Verderbnis verzerrt, und die Naga wurden durch uralte dunkle Mächte unter dem Meer mutiert. Nun bewohnen beide Fraktionen die überfluteten Tempelruinen.",al={"welche feinde für researching the corruption","gegen wen kämpfe ich tiefschwarze grotte","researching the corruption ziele"}}},fp="26,240,22.301.0,14.301.0,16.261.1,58.153.0,46.150.0,53.223.0,27.148.0,49.144.0,54.164.0"}
P.entries["quest:1276"] = {n="Der Schwarze Schild",s="In Donnerfels bringt Krog einen geschwärzten Eisenschild zu einem Schmied, um Antworten zu erhalten. Reethe hatte ihm nichts Nützliches verraten, sodass Mosarn seine einzige Spur blieb.",h="In Donnerfels bringt Krog einen geschwärzten Eisenschild zu einem Schmied, um Antworten zu erhalten.",kw={"geschwärzter eisenschild","schmied","dustwallow","der irdene ring","krog","mosarn","reethe","donnerfels"},sec={{t="Der Name eines Schmieds",b="Krog erinnert sich an Mosarn als einen hochgeschätzten Schmied in Donnerfels. Der Irdene Ring dankte Krog einst mit einer Rüstung, die Mosarn gefertigt hatte, und Krog spricht lobend über diese Arbeit. Er glaubt, dass Mosarn auch den Schild gefertigt hat und vielleicht mehr weiß. Es ist eine vage Spur. Reethe hatte nichts Nützliches verraten, also bringt Krog den geschwärzten Eisenschild zu Mosarn in Donnerfels."},{t="Mosarns Wort",b="Mosarn bestätigt, dass er den Schild selbst gefertigt hat, erinnert sich aber an kaum etwas anderes. Er hat so viele Schilde und Rüstungssets gefertigt, dass er sich nicht an alle erinnern kann."}},faq={{q="Wer ist Mosarn?",a="Mosarn ist ein hochgeschätzter Schmied in Donnerfels. Er fertigte die Rüstung, die der Irdene Ring Krog schenkte.",al={"wer ist mosarn","wo ist mosarn","mosarn donnerfels"}},{q="Warum den Schild zu Mosarn bringen?",a="Krog glaubt, dass Mosarn den Schild gefertigt hat und vielleicht mehr darüber weiß. Reethe hatte nichts Nützliches verraten, also ist diese vage Spur alles, was Krog hat.",al={"warum mosarn den schild zeigen","geschwärzter schild spur","was weiß mosarn"}},{q="Woher kennt Krog Mosarn?",a="Der Irdene Ring dankte Krog mit einer Rüstung, die Mosarn gefertigt hatte.",al={"verbindung zwischen krog und mosarn","woher kennt krog den schmied"}}},fp="16,142,14.349.0,13.150.1,14.105.0,30.130.0,26.59.0"}
P.entries["quest:128"] = {n="Kopfgeld auf den Schwarzfelsklan",s="In Seenhain lockt Kopfgeld auf den Schwarzfelsklan Kämpfer an, während sich Schwarzfelstruppen im nördlichen Rotkammgebirge sammeln. Sturmwind schickt keine königlichen Soldaten, daher bieten Magistrat Solomon und Wache Howe unabhängigen Kämpfern Bezahlung, wenn sie Champions des Schwarzfels angreifen und den Angriff des Klans stören.",h="In Seenhain lockt Kopfgeld auf den Schwarzfelsklan Kämpfer an, während sich Schwarzfelstruppen im nördlichen...",kw={"schwarzfels","kopfgeld","brennende steppe","champion","wache howe","seenhain","magistrat solomon","rotkammgebirge","sturmwind"},ang={["class:Warrior"]="Als Krieger steht Ihr Champions des Schwarzfels gegenüber, schwer gepanzerten und kampferprobten Nahkämpfern. Ihre Kampfkunst stellt Eure Disziplin und Ausdauer auf die Probe.",["faction:Alliance"]="Seenhain ist Sturmwinds östlicher Schild. Wenn die Schwarzfelsorcs durch die Berglager brechen, steht das landwirtschaftliche Kernland der Allianz einer Invasion offen.",["race:Human"]="Als Mensch steht Ihr einem Klan gegenüber, der im Ersten Krieg das ursprüngliche Königreich Sturmwind zerstörte. Die erneute Rückkehr des Schwarzfelsklans nach Süden aufzuhalten, ist eine bittere Pflicht gegenüber Euren Vorfahren."},sec={{t="Die Hoheitsgrenze halten",b="Das Rotkammgebirge gehört zum Königreich Sturmwind, doch der Schwarzfelsklan missachtet menschliche Grenzen. Orcs strömen aus der Brennenden Steppe durch die Gebirgspässe und befestigen Lager im gesamten nördlichen Rotkammgebirge. König Varian Wrynn wird vermisst, und Sturmwinds Regentschaft hält königliche Soldaten zurück. Während Seenhains Kassen schwinden, loben Magistrat Solomon und andere örtliche Anführer Kopfgelder aus, um die Stadt zu schützen."},{t="Die Champions im Visier",b="Wache Howe bezeichnet die Champions des Schwarzfels als das Rückgrat der einfallenden Vorhut. Diese Truppführer sind kampferprobte Veteranen, die ihre Kriegstrupps koordinieren und einfache Grunts vorantreiben. Seenhains Verteidiger hoffen, mit einem Kopfgeld auf die Champions die taktische Führung des Klans zu zerschlagen und einen groß angelegten Vorstoß nach Süden aufzuhalten. Die äußeren Verteidigungsanlagen der Stadt könnten bald zusammenbrechen."}},faq={{q="Warum lobt Wache Howe Kopfgelder aus, statt die Stadtwache zu schicken?",a="Seenhains Garnison ist überlastet. Ihre Wachen patrouillieren am Immerruhsee, schützen die Brücken und halten Gnolle und plündernde Orcs fern. Sie können nicht genug Kämpfer für einen Angriff auf die befestigten Orclager entbehren, ohne die Stadt schutzlos zurückzulassen.",al={"warum kopfgelder","wo ist die stadtwache","wache howe kopfgeld"}},{q="Wo befinden sich die Champions des Schwarzfels?",a="Die Champions des Schwarzfels sind in den weitläufigen Schwarzfelslagern im nördlichen Rotkammgebirge stationiert, unmittelbar westlich der Höhenstraße, die zur Brennenden Steppe hinaufführt.",al={"wo sind die champions","standort der champions","lager der champions des schwarzfels"}},{q="Warum fallen die Schwarzfelsorcs ins Rotkammgebirge ein?",a="Der Schwarzfelsklan operiert vom Schwarzfels im Norden aus und will die umliegenden Hügel erobern und plündern. Da Sturmwinds Verteidigung zersplittert ist, wollen die Orcs die menschlichen Siedlungen vertreiben und die Gebirgspässe an sich reißen.",al={"warum schwarzfelsklan im rotkammgebirge","warum greifen orcs seenhain an","invasion des schwarzfelsklans"}},{q="Warum schickt Sturmwind keine königlichen Soldaten, um sie zu vertreiben?",a="König Varian Wrynn wird vermisst, und der königliche Hof unter Regent Bolvar Fordragon und Lady Prestor erklärt, die Armeen des Königreichs seien unabkömmlich. Seenhain hat die Hauptstadt wiederholt um Hilfe gebeten, doch seine Gesuche werden abgelehnt. Der Stadt bleibt nur, durchreisende Söldner anzuheuern.",al={"warum keine armee aus sturmwind","wo bleibt sturmwinds hilfe","magistrat solomon verstärkung"}},{q="Welche Rolle erfüllen Champions im Schwarzfelsklan?",a="Champions des Schwarzfels sind taktische Anführer an der Front. Sie lenken Angriffe, erzwingen brutale Disziplin und führen Sturmangriffe auf das Gebiet der Allianz an.",al={"was sind champions des schwarzfels","rang der champions","anführereinheit des schwarzfelsklans"}},{q="Wer hat diesen Kopfgeldauftrag genehmigt?",a="Magistrat Solomon, Seenhains ziviles Oberhaupt, hat das Kopfgeld genehmigt und Wache Howe beauftragt, fähige Kämpfer anzuwerben, um die Reihen der Champions zu lichten.",al={"wer zahlt das kopfgeld","wer will die champions tot sehen","magistrat solomon kopfgeld"}}},fx={ae8dcd14={q="Warum will Wache Howe, dass die Champions des Schwarzfels getötet werden?",a="Der Schwarzfelsklan hat das souveräne Gebiet von Sturmwind offen angegriffen und bedroht Seenhain sowie das umliegende Rotkammgebirge. Wache Howe handelt auf direkten Befehl von Magistrat Solomon, um die Gemeinde zu verteidigen. Indem sie die Champions angreifen – die kampferprobten Anführer der Einheit, die das Lager leiten –, will die Stadt die Befehlsstruktur der Invasoren zerschlagen, bevor ein Großangriff die geringen Verteidigungsanlagen von Rotkammgebirge überrennt.",al={"warum blackrock-champions töten","wache howe motiv","warum will howe sie tot sehen"}}},fp="16,272,26.389.0,23.375.0,70.240.0,42.169.0,45.234.0,60.275.0,55.141.0,36.150.0"}
P.entries["quest:1282"] = {n="Sie nennen ihn den lächelnden Jim",s="Wache Byron schickt Euch nach Theramore, um die Geschichte vom lächelnden Jim zu erfahren. Er deutet an, dass Jims Leben nicht immer so war.",h="Wache Byron schickt Euch nach Theramore, um die Geschichte vom lächelnden Jim zu erfahren.",kw={"captain garran mumm","düstermarschen","wache byron","james hyal","gasthaus zur süßen ruh","smiling jim","theramore"},sec={{t="Eine traurige Geschichte",b="Wache Byron erinnert sich an das schöne Gasthaus, das Smiling Jim einst im Sumpf führte. Er bedauert Jim, möchte aber lieber nicht darüber sprechen, was sich geändert hat. Fragt Captain Garran Mumm in Theramore nach der ganzen Geschichte."},{t="Mumms Bericht",b="Captain Garran Mumm sagt, der Mann habe James Hyal geheißen. Hyal baute am Rande des Brachlands ein Gasthaus als angenehme Raststätte für Reisende, und eine Zeit lang florierte es.\n\nDann verlor Theramore die Kontrolle über die Sumpfstraßen, und Oger rückten ein. Hyal hielt an seinem Traum fest, statt hinter Theramores Mauern Schutz zu suchen. Feuer verzehrte das Gasthaus Zur süßen Ruh. Die Untersuchung hat bislang wenig ergeben, und wer helfen möchte, kann die Trümmer durchsuchen."}},faq={{q="Wer ist Smiling Jim?",a="Wache Byron bedauert Smiling Jim und sagt, dass sein Leben nicht immer so war. Jim führte einst ein schönes Gasthaus im Sumpf.",al={"wer ist jim","smiling jim identität","wer ist der lächelnde mann"}},{q="Warum schickt Euch Wache Byron zu Captain Mumm?",a="Byron möchte lieber nicht über Jims Vergangenheit sprechen und schickt Euch deshalb zu Captain Garran Mumm in Theramore.",al={"warum mit mumm sprechen","byron quest","wache byron grund"}},{q="Wo finde ich Captain Garran Mumm?",a="Captain Garran Mumm ist in Theramore.",al={"wer ist captain mumm","captain mumm dustwallow"}}},fp="25,128,11.188.0,15.439.1,19.112.0,47.96.0,37.37.0"}
P.entries["quest:1284"] = {n="Verdächtige Hufabdrücke",s="Rauch steigt vom Gasthaus Zur süßen Ruh auf, und Verdächtige Hufabdrücke durchziehen das Marschland. Einige Abdrücke sind deutlich zu erkennen; andere verlieren sich im weichen Schlamm. Captain Garran Mumm in Theramore braucht den Bericht.",h="Rauch steigt vom Gasthaus Zur süßen Ruh auf, und Verdächtige Hufabdrücke durchziehen das Marschland.",kw={"brachland","captain garran mumm","zentauren","düstermarschen","falgran hastil","hufabdrücke","gasthaus zur süßen ruh","theramore"},sec={{t="Abdrücke im Schlamm",b="Hufabdrücke führen von der rauchenden Ruine des Gasthauses Zur süßen Ruh ins Marschland. Einige sind leicht zu erkennen, während andere im weichen Schlamm beinahe verschwinden. Captain Garran Mumm in Theramore muss davon erfahren."},{t="Was Mumm davon hält",b="Zentauren sind nahe den Düstermarschen häufig aktiv. Kurze Ausflüge ins Brachland haben ihre Lager und Besitztümer aufgedeckt, die über das Gebiet verstreut sind. Mumm wird Falgran Hastil, einen der Fährtenleser, entsenden, um herauszufinden, wohin die Abdrücke führen."}},faq={{q="Wo sind die Hufabdrücke zu finden?",a="Die Abdrücke führen vom noch rauchenden Gasthaus Zur süßen Ruh durch den weichen Schlamm des Marschlands.",al={"wo sind die spuren","fundort der hufabdrücke","gasthaus zur süßen ruh abdrücke"}},{q="Wer erhält den Bericht über die Abdrücke?",a="Captain Garran Mumm in Theramore erhält den Bericht.",al={"wem die hufabdrücke melden","wer erhält den bericht über die hufabdrücke","garran mumm hufabdrücke"}},{q="Wie leicht lassen sich die Abdrücke verfolgen?",a="Einige Abdrücke sind deutlich zu erkennen, doch viele verschwinden beinahe im Schlamm.",al={"sind die abdrücke schwer zu erkennen","schwache spuren im marschland"}}},fp="21,183,17.201.0,22.229.1,31.84.0,41.54.0,34.57.0"}
P.entries["quest:1285"] = {n="Daelins Männer",s="Adjutant Tesoran hat Lieutenant Paval Reethe in den Aufzeichnungen der Wache gefunden. Sie zeichnen Reethes Dienst nach, vom Eintritt bei den Marines von Kul Tiras mit sechzehn Jahren über Beförderungen für herausragende Dienste bis zur Wache von Theramore mit Lady Proudmoores Rekruten. Der letzte Eintrag führt Reethe als vermisst, und Captain Garran Mumm soll die Nachricht erhalten.",h="Adjutant Tesoran hat Lieutenant Paval Reethe in den Aufzeichnungen der Wache gefunden.",kw={"adjutant tesoran","daelins männer","deserteure","düstermarschen","garran mumm","kul tiras","paval reethe","theramore"},sec={{t="Was die Aufzeichnungen sagen",b="Captain Garran Mumm schickte Euch zu Adjutant Tesoran, der die Bücher durchsuchte und Lieutenant Paval Reethe fand. Reethe verpflichtete sich mit sechzehn Jahren bei den Marines von Kul Tiras, und herausragende Dienste brachten ihm Beförderungen ein. Später trat er der Wache von Theramore bei, zusammen mit den meisten Rekruten, die mit Lady Proudmoore übergesetzt waren. Die Aufzeichnungen enden damit, dass er als vermisst geführt wird. Mumm in Theramore soll die Nachricht erhalten."},{t="Die Reaktion des Hauptmanns",b="Captain Garran Mumm hält „vermisst“ für Tesorans freundliche Umschreibung für einen Verräter. Er ist sicher, dass Reethe einer jener Narren ist, deren blinde Loyalität gegenüber Admiral Daelin sie zu Verrätern werden lässt. Mumm sieht darin eine bittere Ironie, da die Deserteure Theramore vorwerfen, die Allianz zu verraten."}},faq={{q="Wer ist Adjutant Tesoran?",a="Adjutant Tesoran durchsuchte die Aufzeichnungen der Wache nach Lieutenant Paval Reethe und las vor, was darin steht.",al={"tesoran","wer vergibt daelins männer"}},{q="Was sagen die Aufzeichnungen über Paval Reethe?",a="Lieutenant Paval Reethe verpflichtete sich mit sechzehn Jahren bei den Marines von Kul Tiras, verdiente sich durch herausragende Dienste Beförderungen und trat später der Wache von Theramore bei, zusammen mit den Rekruten, die mit Lady Proudmoore übergesetzt waren. Die Aufzeichnungen enden damit, dass Reethe als vermisst geführt wird.",al={"reethes vorgeschichte","reethe aufzeichnungen","paval reethes geschichte"}},{q="Wer erhält die Nachricht über Reethe?",a="Captain Garran Mumm erhält die Nachricht in Theramore.",al={"warum zurück zu mumm","garran mumm reethe"}}},fp="12,341,20.397.0,22.274.1,24.101.0,43.257.0,31.48.0"}
P.entries["quest:1286"] = {n="Die Deserteure",s="An der verlassenen Wacht befragt Captain Garran Mumm Deserteure, die Theramores verlassenen Turm besetzt haben.",h="An der verlassenen Wacht befragt Captain Garran Mumm Deserteure, die Theramores verlassenen Turm besetzt...",kw={"balos jacken","captain garran mumm","deserteure","düstermarschen","die verlassene wacht","reethe","wachturm"},sec={{t="Ein besetzter Turm",b="Captain Garran Mumm ringt darum, die Marschen zu halten, doch seine Leute halten mehrere Wachtürme aufrecht. Späher haben Deserteure in einem verlassenen Turm an der verlassenen Wacht südöstlich des Gasthauses entdeckt. Ein Mann namens Jacken führt sie an. Mumm bittet Euch, herauszufinden, was Jacken über Reethe weiß, doch der Mann gibt die Informationen womöglich nicht ohne Weiteres preis."}},faq={{q="Wer schickt Euch aus, um Euch um die Deserteure zu kümmern?",a="Captain Garran Mumm schickt Euch. Seine Späher berichten, dass sich Deserteure in einem Turm niedergelassen haben, den Theramore aufgegeben hat.",al={"wer startet the deserters","wer gibt die quest the deserters"}},{q="Wo verstecken sich die Deserteure?",a="Die Deserteure verstecken sich an der verlassenen Wacht südöstlich des Gasthauses in einem verlassenen Turm in den Düstermarschen.",al={"aufenthaltsort der deserteure","wo liegt die verlassene wacht"}},{q="Wer führt die Deserteure an der verlassenen Wacht an?",a="Ein Mann namens Jacken, auch als Balos Jacken bekannt, führt die Deserteure an. Mumm warnt, dass Jacken Informationen womöglich nicht ohne Weiteres preisgibt.",al={"wer ist balos jacken","anführer der deserteure"}},{q="Was will Captain Mumm von Balos Jacken?",a="Captain Mumm will von Balos Jacken und den Deserteuren Informationen über Reethe erhalten.",al={"warum jacken finden","was will mumm"}}},fp="13,95,13.328.0,41.104.0,31.104.0,38.129.0,47.81.0"}
P.entries["quest:1287"] = {n="Die Deserteure",s="Reethe wurde aus der Deserteursbande vertrieben, und Balos Jacken nennt ihn einen Feigling. Jacken bittet Euch, die Begegnung zu vergessen. Captain Garran Mumm in Theramore wartet auf Nachricht über Reethe.",h="Reethe wurde aus der Deserteursbande vertrieben, und Balos Jacken nennt ihn einen Feigling.",kw={"balos jacken","brackenwall","caldwell","deserteure","garran mumm","die verlassene wacht","reethe","theramore"},sec={{t="Hinausgeworfen",b="Balos Jacken sagt, die Deserteure hätten Reethe vertrieben, weil er wiederholt die Vorräte der Oger in Brackenwall geplündert habe. Die Bande sei zu klein, um es mit diesen Ogern aufzunehmen, und Reethe sei einmal zu oft zu weit gegangen. Sie überließen Reethe sich selbst. Als Gegenleistung für die Antwort bittet Jacken Euch, die Begegnung zu vergessen."},{t="Zurück in Theramore",b="Captain Garran Mumm sagt, Lieutenant Caldwell werde gegen die Deserteure der verlassenen Wacht ausgesandt und außerdem beauftragt, Reethe zu finden. Mumm hält das Moor weder für groß noch für unwegsam genug, um Caldwell daran zu hindern, Reethe zu finden."}},faq={{q="Warum wurde Reethe aus dem Lager der Deserteure geworfen?",a="Jacken sagt, Reethe habe immer wieder die Vorräte der Oger in Brackenwall geplündert. Die Deserteure sind zu wenige, um es mit ihnen aufzunehmen, also überließen sie Reethe sich selbst.",al={"warum haben die deserteure reethe verbannt","reethe brackenwall","warum hat balos reethe rausgeworfen"}},{q="Wer ist Balos Jacken?",a="Balos Jacken führt die Deserteure der verlassenen Wacht an. Auf Reethe angesprochen, nennt er ihn einen Feigling.",al={"wer ist balos jacken","balos jacken geschichte","balos jacken dustwallow"}},{q="Wer will etwas über Reethe erfahren?",a="Captain Garran Mumm in Theramore will etwas über Reethe erfahren. Jacken hofft, dass Ihr vergesst, den Deserteuren jemals begegnet zu sein.",al={"wo die deserteure abgeben","wer will informationen über reethe"}}},fp="13,189,10.313.0,17.228.1,47.155.0,20.92.0,31.118.0"}
P.entries["quest:1288"] = {n="Mumms Bericht",s="Captain Garran Mumm lobt Eure Arbeit als die beste, die er je von einem Laien gesehen hat. Nun bringt Ihr seinen Bericht für Lady Jaina Prachtmeer nach Theramore.",h="Captain Garran Mumm lobt Eure Arbeit als die beste, die er je von einem Laien gesehen hat.",kw={"dustwallow","garran mumm","jaina prachtmeer","bericht","theramore","mumm"},sec={{t="Ein Bericht für Lady Prachtmeer",b="Lady Jaina Prachtmeer bat Captain Mumm, sie über eine heikle Situation auf dem Laufenden zu halten. Er hat seit einiger Zeit nicht mehr mit ihr gesprochen. Er wollte den Bericht später überbringen, schickt nun aber Euch an seiner Stelle. Vielleicht habt Ihr bessere Antworten auf ihre Fragen als er."}},faq={{q="Wer gibt Euch den Bericht für Jaina Prachtmeer?",a="Captain Garran Mumm gibt Euch seinen Bericht für Lady Jaina Prachtmeer in Theramore.",al={"wer startet mumms bericht","wer gibt den bericht","wer schrieb mumms bericht"}},{q="Warum schickt Captain Mumm Euch, statt selbst zu gehen?",a="Mumm hat seit einiger Zeit nicht mehr mit Lady Prachtmeer gesprochen, deshalb schickt er Euch an seiner Stelle. Er glaubt, dass Ihr vielleicht bessere Antworten auf ihre Fragen habt.",al={"warum mich schicken","warum überbringt mumm ihn nicht","warum bericht für jaina"}},{q="Wohin muss der Bericht gebracht werden?",a="Bringt den Bericht zu Lady Jaina Prachtmeer in Theramore.",al={"wo mumms bericht abgeben","wo ist jaina prachtmeer","ziel des berichts"}}},fp="14,146,28.263.0,53.81.0,57.142.0,33.54.0"}
P.entries["quest:1289"] = {n="<nyi> Mumms Bericht",s="Lady Jaina Prachtmeer hat Mumms Bericht gelesen und dankt Euch für Eure Hilfe bei Captain Garran Mumms Untersuchung. Sie schickt Euch zurück zu Mumm in Theramore, um dabei zu helfen, das Geheimnis zu lüften.",h="Lady Jaina Prachtmeer hat Mumms Bericht gelesen und dankt Euch für Eure Hilfe bei Captain Garran Mumms...",kw={"captain garran mumm","düstermarschen","untersuchung","lady jaina prachtmeer","theramore","mumms bericht"},sec={{t="Zurück zum Captain",b="Lady Jaina Prachtmeer dankt Euch für Eure Hilfe bei Captain Mumms Untersuchung. Sein Bericht beruhigt sie, weil die Angelegenheit in fähigen Händen liegt. Sie schickt Euch zurück zu ihm in Theramore, um dabei zu helfen, das Geheimnis zu lüften."}},faq={{q="Wer schickt Euch zurück zu Captain Mumm?",a="Lady Jaina Prachtmeer schickt Euch zurück, nachdem sie Captain Mumms Bericht gelesen hat.",al={"wer gibt mumms bericht","jaina questgeberin","wer schickt mich zu mumm"}},{q="Was hält Lady Jaina von dem Bericht?",a="Lady Jaina sagt, dass Eure Hilfe die Untersuchung vorangebracht hat, und dankt Euch dafür. Es beruhigt sie zu wissen, dass die Angelegenheit in fähigen Händen liegt.",al={"jainas reaktion","was sagt jaina zu mumms bericht"}},{q="Wo findet Ihr Captain Garran Mumm?",a="Captain Garran Mumm ist in Theramore.",al={"wo ist captain mumm","captain mumm aufenthaltsort","wo mumms bericht abgeben"}}},fp="14,179,19.209.0,36.74.0,41.129.0,39.37.0"}
P.entries["quest:129"] = {n="Ein geschenktes Mittagessen",s="Darcy hat eine Mahlzeit für Wache Parker an der südlichen Straße von Seenhain bereit. Gnolle und Schwarzfelsorcs bedrohen die Zufahrten, während die Stadtwachen kaum ausreichen.",h="Darcy hat eine Mahlzeit für Wache Parker an der südlichen Straße von Seenhain bereit.",kw={"schwarzfelsorcs","darcy","dunkelhain","geschenktes mittagessen","gnolle","wache parker","seenhain","parkers mittagessen","rotkammgebirge"},ang={["faction:Alliance"]="Als Reisender der Allianz zeigt Ihr mit dem Überbringen von Darcys Essen die Belastung einfacher Leute und Wachposten in abgelegenen, weitgehend sich selbst überlassenen Siedlungen.",["profession:Cooking"]="Als Koch wisst Ihr, dass eine warme Mahlzeit einen einsamen Wachposten stärken kann, der in feindseligem Gebiet Wache hält."},sec={{t="Eine Mahlzeit für unterwegs",b="Darcy, die Köchin in Seenhain, hat eine Mahlzeit für Wache Parker eingepackt. Sie kann sie nicht selbst aus der Stadt hinausbringen. Gnolle im Rotkammgebirge und umherziehende Orc-Kriegstrupps machen die Straßen außerhalb der Tore für eine Zivilistin zu gefährlich. Deshalb bittet sie durchreisende Reisende, das Essen in Richtung Dunkelhain zu bringen, wo Parker Wache hält."},{t="Wache an der Grenze",b="Wache Parker bewacht die südliche Straße von Seenhain in Richtung Dämmerwald. Das Rotkammgebirge erhält zu wenig Verstärkung von der Armee von Sturmwind, um den wachsenden Gnollrudeln und dem Schwarzfelsklan in den Bergen entgegenzutreten. Wachposten wie Parker halten allein in feindseligem Gebiet Wache. Eine warme Mahlzeit aus der Stadt kann ihre Stimmung heben."}},faq={{q="Wo ist Wache Parker zu finden?",a="Wache Parker patrouilliert auf der südlichen unbefestigten Straße von Seenhain in Richtung Dämmerwald und Dunkelhain.",al={"wache parker standort","wo ist parker","wache parker finden"}},{q="Warum bringt Darcy das Mittagessen nicht selbst?",a="Darcy ist eine Zivilistin und hält die Umgebung von Seenhain für zu gefährlich, um allein unterwegs zu sein. Gnolle und Schwarzfelsorcs streifen auf den Straßen außerhalb der Stadt umher.",al={"warum kann darcy nicht gehen","darcy rotkammgebirge"}},{q="Welchen Bedrohungen steht Wache Parker gegenüber?",a="Parker steht auf der südlichen Straße Gnollrudeln aus dem Rotkammgebirge und Kriegstrupps der Schwarzfelsorcs gegenüber.",al={"parker feinde","rotkammgebirge bedrohungen"}},{q="Was geschieht, nachdem Wache Parker sein Mittagessen erhalten hat?",a="Darcys Mahlzeit bringt ihr Parkers Dankbarkeit ein. Anschließend schickt er Euch auf weitere Botengänge zwischen den Wachen und den Stadtbewohnern, beginnend mit einem Besuch beim örtlichen Kräuterkundigen.",al={"ein geschenktes mittagessen nächste quest","parker folgequest"}},{q="Warum haben die Wachen von Sturmwind Mühe, das Rotkammgebirge zu sichern?",a="Sturmwind hat zu wenig Verstärkung in abgelegene Siedlungen wie Seenhain geschickt. Die Stadtwachen stellen sich den Bedrohungen mit wenig Unterstützung.",al={"warum ist seenhain unverteidigt","sturmwind vernachlässigt rotkammgebirge"}},{q="Welche Belohnung verspricht Darcy?",a="Darcy verspricht, Euch ein kostenloses Mittagessen zuzubereiten und zu servieren, wenn Ihr mit Parkers Mahlzeit in die Stadt zurückkehrt.",al={"was ist das geschenkte mittagessen","darcy belohnung"}}},fx={a6c03f8c={q="Warum will Darcy, dass Parker dieses Mittagessen bekommt?",a="Darcy hat ein gütiges Herz und kümmert sich um die Verteidiger der Stadt. Wache Parker ist weit draußen auf der Straße in Richtung Dämmerwald stationiert und sieht sich ohne Ablösung ständig der Bedrohung durch Gnolle und Schwarzfelsorcs gegenüber. Da sie weiß, wie zermürbend und einsam der Wachdienst in diesen gefährlichen Zeiten sein kann, hat Darcy eine frische Mahlzeit zubereitet, um ihn zu stärken und zu zeigen, dass Seenhain seinen Dienst zu schätzen weiß.",al={"darcy motiv mittagessen","warum parker mittagessen schicken","darcy kümmert sich um parker"}}},fp="12,171,19.302.0,19.306.0,32.89.0,44.147.0,42.85.0,47.158.1,58.135.0,32.96.0"}
P.entries["quest:13"] = {n="Die Volksmiliz",s="Westfalls Freiwillige stehen einer wachsenden Bedrohung durch die Defias gegenüber. Unter Gryan Starkmantels Führung stellt sich die Volksmiliz nun Dieben entgegen, die über bloße Wegelagerei hinausgehen und Mondbruch sowie den Goldküstensteinbruch plündern. Die Miliz fordert härtere Vergeltungsmaßnahmen.",h="Westfalls Freiwillige stehen einer wachsenden Bedrohung durch die Defias gegenüber.",kw={"alexstons bauernhof","plünderer der defias","brandschatzer der defias","der goldküstensteinbruch","gryan starkmantel","mondbruch","volksmiliz","späherkuppe","westfall"},ang={["class:Paladin"]="Als Paladin hört Ihr, wie Gryan Starkmantel das Licht anruft, um Westfall von verbrecherischer Verderbnis zu reinigen. Dieser Feldzug ist für Euch ein unmittelbarer Auftrag im Namen der Gerechtigkeit.",["faction:Alliance"]="Als Kämpfer der Allianz seht Ihr die bittere Kluft zwischen dem behaglichen Leben hinter Sturmwinds Mauern und seinen hungernden Grenzgebieten, die völlig sich selbst überlassen sind.",["race:Human"]="Als Mensch steht Ihr in einem tragischen Kampf gegen ehemalige Steinmetze und Nachbarn, die sich gewaltsam gegen ihr eigenes Volk gewandt haben."},sec={{t="Eskalierende Gewalt",b="Die Angriffe der Defias haben sich von den Straßen auf Westfalls Wirtschaftszentren ausgeweitet. Plünderer der Defias und feuerschleudernde Brandschatzer besetzen Mondbruch und den Goldküstensteinbruch. Auch Alexstons Bauernhof plündern sie aus. Gryan Starkmantel erkennt, was ihre Kontrolle über diese Orte bedeuten könnte: Ohne eine reguläre königliche Armee lässt sich Westfall womöglich nicht mehr zurückerobern."},{t="Die Grundsätze der Miliz",b="Sturmwind hat Gryan Starkmantel weder Soldaten noch Vorräte geschickt. Deshalb setzt er auf das Heilige Licht und die Entschlossenheit der verbliebenen Bauern Westfalls. Freiwillige tragen den Kampf in die Hochburgen der Defias und zermürben die Bruderschaft. Die Vertreibung der Plünderer wird ihnen Ressourcen entziehen und den verängstigten Bewohnern zeigen, dass noch immer Verteidiger für Westfalls Frieden und Wohlstand kämpfen."}},faq={{q="Was ist die Volksmiliz?",a="Gryan Starkmantel gründete die Volksmiliz als bewaffnete Freiwilligentruppe zur Verteidigung Westfalls. Ihre Mitglieder sind überwiegend vertriebene Bauern aus Westfall und wohlgesinnte Reisende. Sie schlossen sich zum Widerstand gegen die Bruderschaft der Defias zusammen, nachdem Sturmwinds Königshof sich geweigert hatte, Stadtwachen zu entsenden.",al={"volksmiliz","wer ist die miliz","westfall miliz"}},{q="Wer ist Gryan Starkmantel?",a="Gryan Starkmantel ist ein erfahrener menschlicher Befehlshaber, der Westfalls Verteidigung von der Schanze auf der Späherkuppe aus leitet. Dem Licht und seiner Heimat verpflichtet, führt er den verzweifelten Widerstand der Volksmiliz gegen die Herrschaft der Gesetzlosen an.",al={"gryan","wer ist starkmantel","starkmantel geschichte"}},{q="Warum plündern die Defias Bauernhöfe und Steinbrüche?",a="Die Bruderschaft der Defias will Westfalls Nahrungsversorgung lahmlegen und Rohstoffe an sich reißen. Durch die Einnahme des Goldküstensteinbruchs kontrollieren sie Stein und Mineralien. Die Eroberung von Mondbruch und den Bauernhöfen vertreibt ehrliche Leute und verschafft ihnen Stützpunkte für ihre verbrecherischen Machenschaften.",al={"warum plündern die defias","defias in mondbruch","warum brandschatzer im steinbruch"}},{q="Warum hat Sturmwind keine Soldaten nach Westfall geschickt?",a="Sturmwind hat keine Soldaten geschickt, weil König Varian Wrynn auf mysteriöse Weise verschwunden ist. Der Kindkönig Anduin sitzt unter der Regentschaft von Hochlord Bolvar Fordragon auf dem Thron. Blockaden im adligen House of Nobles strapazieren die Mittel der Krone, sodass entlegene Gebiete wie Westfall ihren örtlichen Verteidigern überlassen bleiben.",al={"wo sind sturmwinds wachen","warum keine hilfe aus sturmwind","könig varian westfall"}},{q="Wo findet man Brandschatzer und Plünderer der Defias?",a="Brandschatzer und Plünderer der Defias sammeln sich um eroberte Siedlungen im Süden und Westen Westfalls. Man findet sie in der verlassenen Stadt Mondbruch, im Goldküstensteinbruch entlang der westlichen Steilküste und auf dem verwüsteten Alexstons Bauernhof.",al={"brandschatzer fundort","wo sind die plünderer","defias fundorte"}}},fx={["3f9873c1"]={q="Warum will Gryan Starkmantel, dass die Defias-Plünderer und Defias-Diebe getötet werden?",a="Defias-Plünderer und Defias-Diebe überfallen aktiv die verbliebenen Gehöfte und lebenswichtigen Ressourcen in Westfall, einschließlich Mondbruch, dem Goldküstensteinbruch und Alexstons Bauernhof. Gryan Starkmantel weigert sich, die Diebe den örtlichen Familien den letzten Rest an Frieden und Lebensunterhalt rauben zu lassen. Indem er ihre Überfalltrupps dezimiert, hofft er, ihren Schwung zu bremsen, die überlebenden Siedler zu schützen und eine unmissverständliche Botschaft zu senden, dass Gesetzlosigkeit und Korruption mit Gewalt begegnet wird.",al={"warum defias-plünderer töten","gryan starkmantel motiv","warum will gryan plünderer tot"}},["599e05d4"]={q="Wer sind die Defias-Plünderer und Defias-Diebe, die in dieser Aufgabe ins Visier genommen werden?",a="Es handelt sich um die einfachen Plünderer und Zauberer der The Defias Brotherhood, die ausgesandt wurden, um Westfall völlig auszurauben. Während einfache Taschendiebe auf den offenen Feldern herumlaufen, schlagen diese Plünderer und Diebe direkt in etablierten Siedlungen wie Mondbruch und dem Goldküstensteinbruch zu. Bewaffnet mit Waffen und zerstörerischer Feuermagie sammeln sie Vorräte, plündern verlassene Anwesen und vertreiben gewaltsam alle Siedler, die versuchen, sich ihnen in den Weg zu stellen.",al={"wer sind defias-plünderer","wer sind defias-diebe","defias-ziele westfall"}},["7d97eb03"]={q="Warum braucht Gryan Starkmantel Eure Hilfe, anstatt sich auf die The People's Militia zu verlassen?",a="Die The People's Militia ist bis aufs Äußerste strapaziert. Da sich Sturmwind weigert, militärische Unterstützung zu leisten, hat die Späherkuppe nur eine Handvoll Freiwilliger, Bauern und Veteranen im Ruhestand, um die Straße zu bewachen und ihren befestigten Hügel zu halten. Sie können keine Soldaten für umfassende Gegenoffensiven in der gesamten Region abkommandieren, ohne ihre Basis schutzlos zurückzulassen. Fähige Abenteurer wie Ihr liefern den offensiven Schlag, der der The People's Militia schmerzlich fehlt.",al={"warum braucht gryan mich","warum nicht die miliz benutzen","warum abenteurer benutzen"}}},fp="20,249,19.343.0,24.368.0,29.282.0,25.223.0,46.263.0,47.298.0,45.231.0"}
P.entries["quest:130"] = {n="Besuch im Kräuterladen",s="Wache Parker bittet Euch, in Seenhain Blumen für Darcy zu kaufen. Das Geschenk soll geheim bleiben, bevor Ihr zum Gasthaus zurückkehrt.",h="Wache Parker bittet Euch, in Seenhain Blumen für Darcy zu kaufen.",kw={"narzissen","darcy","blumen","wache parker","seenhain","martie jainrose","rotkammgebirge","besuch im kräuterladen"},ang={["faction:Alliance"]="Gnollrudel und Schwarzfelsorcs bedrohen das Rotkammgebirge, während die Liebe unter Seenhains Verteidigern noch immer einen Platz findet.",["profession:Herbalism"]="Martie Jainrose ist Seenhains Händlerin für Kräuterkunde und Alchemie am westlichen Ortsrand."},sec={{t="Die geheime Bitte einer Wache",b="Wache Parker hält am südlichen Zugang zu Seenhain nach Schwarzfelsorcs und Gnollen Ausschau. Ihr bringt ihm eine warme Mahlzeit von Darcy aus dem Gasthaus von Seenhain. Dankbar für ihre Freundlichkeit bittet er Euch, im Kräuterladen am westlichen Ende des Ortes Blumen für sie zu kaufen."},{t="Ortsklatsch und heimliches Werben",b="Parker bittet Euch, den Auftrag geheim zu halten, wenn Ihr Martie Jainrose, Seenhains Kräuterkundige, besucht. Der Ort ist klein, und er möchte nicht, dass Martie erfährt, wer die Blumen schickt oder wer sie erhalten wird. Im Laden neckt Martie Euch und vermutet, dass Ihr bereits eine Liebste im Ort gefunden habt. Orc-Einfälle und Briganten machen dem Rotkammgebirge zu schaffen, daher sorgt eine kleine romantische Geste für willkommene Erleichterung."}},faq={{q="Wer schickt Euch zur Kräuterkundigen?",a="Wache Parker, der an der südlichen Straße ins Rotkammgebirge gleich nördlich des Dämmerwalds stationiert ist, schickt Euch zur Kräuterkundigen.",al={"wer vergibt diese quest","questgeber","wache parker"}},{q="Wer ist die Kräuterkundige in Seenhain?",a="Martie Jainrose ist Seenhains Kräuterkundige und Blumenhändlerin. Ihr Laden liegt am westlichen Ende des Ortes.",al={"wer ist martie jainrose","wo ist die kräuterkundige","kräuterkundige in seenhain"}},{q="Warum möchte Wache Parker Blumen?",a="Parker möchte Darcy, der Schankmaid im Gasthaus von Seenhain, für das kostenlose Mittagessen danken und mit Blumen sein romantisches Interesse zeigen.",al={"warum blumen kaufen","für wen sind die blumen","parkers beweggrund"}},{q="Warum möchte Parker den Kauf geheim halten?",a="Parker ist schüchtern, wenn es darum geht, um Darcy zu werben, und möchte den Kauf vor Martie Jainrose und den anderen Ortsbewohnern verheimlichen.",al={"warum die geheimhaltung","warum verheimlichen für wen die blumen sind","martie nichts verraten"}},{q="Was geschieht nach dem Gespräch mit Martie Jainrose?",a="Martie stellt einen Strauß Narzissen zusammen, den Ihr Darcy im Gasthaus von Seenhain bringen sollt.",al={"what comes next","delivering daffodils","nach der kräuterkundigen"}},{q="Wo steht dieser Besuch in der Questreihe?",a="Dieser Besuch folgt auf 'A Free Lunch', bei dem Ihr Wache Parker das Mittagessen bringt, und kommt vor 'Delivering Daffodils', bei dem Ihr die Blumen zu Darcy zurückbringt.",al={"questreihe","voraussetzung","questreihe zum kostenlosen mittagessen"}}},fx={["07240ec3"]={q="Warum bittet Euch Wache Parker, die Kräuterkundige aufzusuchen, anstatt selbst zu gehen?",a="Parker ist im Dienst und bewacht die Straßen von Rotkammgebirge und kann seinen Posten nicht einfach verlassen, um persönliche Besorgungen in der Stadt zu machen. Wichtiger noch, es ist ihm zutiefst peinlich, was er für Darcy empfindet. Er möchte, dass die romantische Geste vor Martie Jainrose und dem Rest von Seenhain geheim gehalten wird, was unmöglich wäre, wenn man ihn selbst Blumen kaufen sehen würde.",al={"warum braucht parker mich","warum kann parker die blumen nicht selbst holen","warum bitten mich, die kräuterkundige zu besuchen"}}},fp="19,120,24.249.0,31.383.0,37.124.0,34.93.0,35.127.0,46.118.0,46.85.1,39.155.1"}
P.entries["quest:1302"] = {n="James Hyal",s="Jenseits des großen Meeres wartet James Hyals Familie auf Nachricht aus Kalimdor. Er segelte mit der Expedition von Lady Jaina Prachtmeer dorthin und brach auf, um im Grenzland ein Gasthaus zu eröffnen. Nun hofft seine Familie, in Theramores Aufzeichnungen Neuigkeiten zu finden.",h="Jenseits des großen Meeres wartet James Hyals Familie auf Nachricht aus Kalimdor.",kw={"clerk lendry","koch","gastwirt","jaina prachtmeer","james hyal","kalimdor","theramore"},ang={["faction:Alliance"]="James segelte während des Dritten Krieges mit Lady Jaina Prachtmeer nach Westen, und seine Familie verbindet die Östlichen Königreiche über das große Meer hinweg mit der Insel Theramore.",["profession:Cooking"]="James war in seiner Heimat als begabter Koch bekannt. Er ging nach Kalimdor, um mit einem Gasthaus und der Bewirtung von Reisenden seinen Lebensunterhalt zu verdienen."},sec={{t="Über das große Meer",b="Während des Dritten Krieges verließen viele ihre Heimat in den Östlichen Königreichen, um Lady Jaina Prachtmeer über das große Meer zu folgen. James Hyal zog mit ihnen, in seiner Heimat bekannt für seine Kochkünste. Nachdem die Kämpfe geendet hatten und die Insel Theramore gegründet worden war, suchte er auf Kalimdor sein Auskommen. Er plante, ein Gasthaus für Reisende und andere Siedler zu eröffnen."},{t="Suche nach einem Bruder",b="Daheim in den Östlichen Königreichen macht sich James' Bruder zunehmend Sorgen. Es sind keine Briefe von jenseits des Meeres eingetroffen, doch er hofft, dass James damit beschäftigt ist, eine Schankstube am Wegesrand zu führen. Er bittet Reisende, seinen Bruder aufzuspüren. Die Suche beginnt in Theramore, wo Clerk Lendry Aufzeichnungen über Expeditionsmitglieder führt, die sich in die Wildnis gewagt haben."}},faq={{q="Wer ist James Hyal?",a="James Hyal ist ein menschlicher Siedler und begabter Koch, der mit der Expedition von Lady Jaina Prachtmeer das große Meer überquerte. Nachdem die Kämpfe geendet hatten, brach er auf, um auf Kalimdor ein Gasthaus zu eröffnen und damit seinen Lebensunterhalt zu verdienen.",al={"wer ist james hyal","james hyal hintergrundgeschichte","wer ist james"}},{q="Wo kann ich James Hyal finden?",a="Nach seiner Ankunft mit der Expedition von Lady Proudmoore brach James auf, um irgendwo auf Kalimdor ein Gasthaus zu eröffnen. Seine Familie hat in letzter Zeit nichts von ihm gehört, und Clerk Lendry auf der Insel Theramore führt Aufzeichnungen, die Hinweise auf seinen Aufenthaltsort geben könnten.",al={"wo ist james hyal","james hyal finden","james hyal aufenthaltsort"}},{q="Wer ist Clerk Lendry?",a="Clerk Lendry verwaltet die örtlichen Aufzeichnungen auf der Insel Theramore. Reisende, die nach Siedlern wie James Hyal suchen, können Lendry bitten, diese Aufzeichnungen durchzusehen.",al={"wer ist clerk lendry","clerk lendry aufenthaltsort","theramore schreiber"}},{q="Warum reiste James nach Kalimdor?",a="James segelte während des Dritten Krieges mit der Expedition von Lady Jaina Prachtmeer und gehörte zu jenen, die die Östlichen Königreiche verließen. Nachdem die Kämpfe geendet hatten, beschloss er, auf Kalimdor zu bleiben und ein Gasthaus für Reisende und Siedler zu eröffnen.",al={"warum ging james nach kalimdor","james hyal expedition"}},{q="Wer sucht nach James Hyal?",a="James' Bruder in den Östlichen Königreichen sucht nach ihm, nachdem er seit einiger Zeit keine Nachricht mehr erhalten hat. Er erinnert sich an James als guten Koch und glaubt, dass er vielleicht damit beschäftigt ist, sein Gasthaus aufzubauen.",al={"wer vergibt die quest james hyal","wer ist james' bruder"}},{q="Ist James Hyal in Gefahr?",a="James' Bruder glaubt, dass er womöglich mit seinem neuen Geschäft beschäftigt ist. Seine Familie hat seit einiger Zeit keine direkte Nachricht von ihm erhalten.",al={"ist james hyal in sicherheit","was ist mit james hyal geschehen"}}},fp="10,225,20.341.0,22.329.0,18.197.0,28.232.0,20.138.0,33.215.0,30.179.0,28.127.0"}
P.entries["quest:131"] = {n="Narzissen für eine Dame",s="In Seenhain führt Euch Narzissen für eine Dame von Wache Parkers Dank zu einem angespannten Gespräch im Gasthaus. Zuerst bringt Ihr Parker sein Mittagessen, dann Blumen von Martie Jainrose zu Darcy.",h="In Seenhain führt Euch Narzissen für eine Dame von Wache Parkers Dank zu einem angespannten Gespräch im...",kw={"narzissenstrauß","darcy","narzissen für eine dame","wache parker","seenhain","martie jainrose","rotkammgebirge","sautierter sonnenfisch"},ang={["faction:Alliance"]="Die Hilfe für die Ortswache und die Gastwirtin in Seenhain stärkt die Moral der Zivilbevölkerung angesichts der Einfälle von Blackrock und Gnollen.",["profession:Cooking"]="Darcy belohnt Euch mit gewürztem sautiertem Sonnenfisch, einer Kostprobe der einfachen Küche am See im Rotkammgebirge.",["profession:Herbalism"]="Martie Jainrose nutzt ihr Pflanzenwissen und ihren Blick für frische Blumen am Seeufer und zeigt damit die ruhigere Seite des Kräutersammelns."},sec={{t="Ein duftender Botengang",b="Wache Parker dankt Euch dafür, dass Ihr ihm sein Mittagessen gebracht habt. Darcy, die Köchin, die es zubereitet hat, verdient eine nette Geste, also bittet Parker Euch, Blumen von Martie Jainrose zu holen. Martie bindet einen Strauß Narzissen, ihre eigenen Lieblingsblumen. Sie weiß nicht, wer sie erhalten wird."},{t="Rivalitäten im Ort",b="Im Gasthaus von Seenhain freut sich Darcy über den Strauß, wird dann aber misstrauisch. Sie weiß, dass Narzissen Marties Lieblingsblumen sind, und betrachtet Martie als eifersüchtige Rivalin. Darcy fürchtet, Martie hätte die Stängel womöglich vergiftet, wenn sie gewusst hätte, dass die Blumen für sie bestimmt waren. Sie gibt Euch keine Schuld und überreicht Euch für Eure Mühen heißen sautierten Sonnenfisch."}},faq={{q="Wer ist Darcy?",a="Darcy arbeitet im Gasthaus von Seenhain im Rotkammgebirge, wo sie Mahlzeiten für Einheimische und die Ortswachen zubereitet. Sie schickte Wache Parker ein Mittagessen, woraufhin er Euch bat, ihr zum Dank Blumen zu bringen.",al={"darcy","wer ist darcy in seenhain","seenhain köchin darcy"}},{q="Wer ist Martie Jainrose?",a="Martie Jainrose ist die Kräuterkundige von Seenhain und eine Blumenliebhaberin. Wache Parker schickt Euch zu ihr, um einen Strauß zu holen, und sie wählt Narzissen, ihre eigenen Lieblingsblumen.",al={"martie jainrose","seenhain kräuterkundige","wer gab die blumen"}},{q="Warum ärgert sich Darcy über die Narzissen?",a="Darcy erkennt die Narzissen als Marties Lieblingsblumen und betrachtet Martie als eifersüchtige Rivalin. Sie fürchtet, Martie hätte die Stängel womöglich vergiftet, wenn sie gewusst hätte, dass der Strauß für Darcy bestimmt war.",al={"warum ist darcy wütend","darcy martie fehde","warum vergiftete blumen"}},{q="Hat Martie den Strauß tatsächlich vergiftet?",a="Nein. Martie wusste nicht, dass die Blumen für Darcy waren. Parker bat Euch lediglich, einen Strauß abzuholen, also wählte Martie ihre eigenen Lieblingsblumen.",al={"sind narzissen vergiftet","ist der strauß vergiftet"}},{q="Welche Quests führen zu dieser Lieferung?",a="Die Questreihe beginnt mit A Free Lunch, wo Ihr Darcys Mahlzeit zu Wache Parker bringt. Parker schickt Euch dann in Visit the Herbalist zu Martie Jainrose, um ein Geschenk zu kaufen, was zu Narzissen für eine Dame führt.",al={"questreihe","narzissen voraussetzungen","narzissen für eine dame questreihe"}},{q="Welche Belohnung erhaltet Ihr für die Blumenlieferung?",a="Darcy gibt Euch eine reichliche Portion sautierten Sonnenfisch, etwas Kupfer und Erfahrung sowie Ansehen beim Königreich Sturmwind.",al={"questbelohnung","narzissen belohnungen"}}},fx={["12ade65f"]={q="Warum will Martie Jainrose, dass Ihr Narzissen an Darcy überbringt?",a="Martie Jainrose hat Narzissen einfach deshalb gewählt, weil es ihre eigenen Lieblingsblumen sind, ohne zu wissen, für wen Parker sie bestimmt hatte. Wache Parker bat Euch, einen Strauß zu besorgen, um Darcys Freundlichkeit zu erwidern, und Martie stellte glücklich ihre persönlichen Favoriten für diese Geste zusammen. Was sie als hübsches Arrangement sieht, nimmt Darcy jedoch sofort als Beleidigung eines kleinen romantischen Rivalen wahr.",al={"warum narzissen","martie jainrose motiv","warum narzissen schicken"}}},fp="20,189,17.265.0,14.341.1,13.186.0,23.163.0,39.194.1,39.130.1,37.199.0,50.123.0"}
P.entries["quest:1319"] = {n="Der Schwarze Schild",s="In Theramores Schmiede schickt Captain Garran Mumm einen Schild zu einem Schmied, der vielleicht dessen Hersteller kennt.",h="In Theramores Schmiede schickt Captain Garran Mumm einen Schild zu einem Schmied, der vielleicht dessen...",kw={"geschwärzter eisenschild","captain garran mumm","caz twosprocket","düstermarschen","der schwarze schild","theramore"},sec={{t="Ein Schmied, der weiterweiß",b="Captain Garran Mumm weiß wenig über den Schild. Deshalb schickt er Euch zu Caz Twosprocket, einem der besten Schmiede weit und breit. Caz hütet die Esse in Theramores Schmiede und kann Euch vielleicht mehr erzählen."},{t="Das Urteil des Schmieds",b="Caz Twosprocket untersucht das Eisen und nennt es ein interessantes Stück. Caz sagt, es sei weder das eigene Werk noch das eines Schmieds, den Caz diesseits des Wassers kennt."}},faq={{q="Wer schickt Euch, den Schild untersuchen zu lassen?",a="Captain Garran Mumm in Theramore schickt Euch zu einem Schmied, der vielleicht mehr über den Schild weiß.",al={"wer vergibt den schwarzen schild","questgeber schwarzer schild","bei wem beginnt der schwarze schild"}},{q="Wer ist Caz Twosprocket?",a="Caz Twosprocket hütet die Esse in Theramores Schmiede. Mumm zählt Caz zu den besten Schmieden weit und breit.",al={"caz twosprocket","wer ist der schmied in theramore"}},{q="Welcher Schild wird Caz gezeigt?",a="Der Geschwärzte Eisenschild.",al={"geschwärzter eisenschild","welchen schild caz zeigen"}}},fp="16,93,19.199.0,19.162.1,36.90.0,23.106.0,28.26.0"}
P.entries["quest:132"] = {n="Die Bruderschaft der Defias",s="Am Rande des Rotkammgebirges und Westfalls warnt Wiley der Schwarze Gryan Starkmantel. Seine Erkenntnisse zeigen, dass die Bedrohung durch die Defias über Wegelagerei hinausgeht, und Gryan muss erfahren, wie weit sie reicht.",h="Am Rande des Rotkammgebirges und Westfalls warnt Wiley der Schwarze Gryan Starkmantel.",kw={"bruderschaft der defias","gnolle","goblins","gryan starkmantel","kobolde","späherkuppe","westfall","wiley der schwarze","wileys nachricht"},ang={["class:Rogue"]="Als Schurke erkennt Ihr, wie Wiley der Schwarze zwischen Gesetzlosem und nützlichem Informanten wandelt und wie Verbindungen zur Unterwelt im Krieg wichtige Erkenntnisse liefern.",["faction:Alliance"]="Für die Allianz zeigt die Zusammenarbeit zwischen menschlichen Gesetzlosen, Gnollen und Goblins die gewaltige Sicherheitslücke an Sturmwinds Westgrenzen.",["race:Human"]="Als Mensch wisst Ihr, dass die Nachricht bestätigt, dass die Banditen, die Familiengehöfte in Westfall und im Rotkammgebirge plündern, einen gezielten, koordinierten Feldzug führen."},sec={{t="Eine gefährliche Depesche",b="Wiley der Schwarze sagt, die Weitergabe seines Wissens könnte ihn das Leben kosten. Seine versiegelte Nachricht beschreibt, wie die Bruderschaft Gruppen im ganzen Umland koordiniert hat, obwohl diese Gruppen einander gewöhnlich feindlich gesinnt sind."},{t="Unwahrscheinliche Bündnisse",b="Wiley warnt, dass die Defias ein beunruhigendes Netzwerk um sich geschart haben. Die rot maskierten Gesetzlosen haben Gnollrudel, grabende Kobolde und Gobliningenieure angeworben, statt allein zu arbeiten. Ihre rohe Muskelkraft, grabende Arbeitskraft und technische Raffinesse deuten auf ein Unterfangen hin, das über die ursprünglichen Erwartungen der Volksmiliz hinausgeht."},{t="Starkmantels widerwillige Abhängigkeit",b="Gryan Starkmantel hegt wenig Sympathie für Wiley. Er beklagt offen, dass er den Schurken nicht verrotten ließ, als er die Gelegenheit dazu hatte. Doch Westfall kann sich keinen Stolz leisten. Die Volksmiliz muss brauchbare Erkenntnisse annehmen, wo immer sie welche finden kann."}},faq={{q="Worum geht es in Wileys Nachricht?",a="Die Nachricht von Wiley dem Schwarzen warnt, dass die Bruderschaft der Defias ihr Vorgehen mit Gnollen, Kobolden und Gobliningenieuren abstimmt. Sie teilt der Volksmiliz mit, dass die Gesetzlosen eine Unternehmung vorbereiten, die weit über gewöhnliche Wegelagerei hinausgeht.",al={"wileys nachricht","was steht in der nachricht","nachricht von wiley dem schwarzen"}},{q="Wer ist Wiley der Schwarze?",a="Wiley der Schwarze ist ein zwielichtiger Kontaktmann, der sich in Seenhain im Rotkammgebirge aufhält. Gryan Starkmantel hält ihn für einen unzuverlässigen Schurken, doch Wiley hat weitreichende Verbindungen zur Unterwelt und entscheidende Informationen über die Aktivitäten der Defias.",al={"wer ist wiley","geschichte von wiley dem schwarzen","wiley seenhain"}},{q="Warum sollten sich die Defias mit Gnollen und Kobolden verbünden?",a="Die Defias nutzen einheimische Kreaturen, um Gebiete zu kontrollieren und billige Arbeitskräfte zu gewinnen. Gnolle lenken als brutale Plänkler die Verteidiger ab, Kobolde graben in den Minen der Region, und Goblintüftler steuern schwere Maschinen und Sprengwerkzeuge bei.",al={"warum nutzen defias gnolle","kobolde und defias","verbündete der defias"}},{q="Warum mag Gryan Starkmantel Wiley nicht?",a="Gryan Starkmantel ist ein disziplinierter ehemaliger Soldat, der Wiley für einen gewöhnlichen Beutelschneider und Verbrecher hält. Er bereut, Wiley vor dem Gefängnis bewahrt zu haben, doch Wileys Ohren in der Unterwelt sind unverzichtbar.",al={"starkmantel und wiley","warum wiley hassen"}},{q="Welche Rolle spielt diese Nachricht bei den Ermittlungen der Miliz?",a="Wileys Nachricht führt die Ermittlungen der Miliz von örtlicher Aufklärung zur tieferen Verschwörung der Defias. Ihre Überbringung veranlasst Starkmantel, die Führung und die Aufmarschgebiete der Verschwörung zu untersuchen.",al={"schritt der defias-questreihe","welche quest ist das"}},{q="Warum kümmert sich Sturmwind nicht um diese Bedrohung?",a="Da König Varian Wrynn verschwunden ist, weigert sich das House of Nobles von Sturmwind, königliche Soldaten oder Gelder zur Verteidigung Westfalls bereitzustellen. Starkmantels zusammengewürfelte Volksmiliz muss die Region allein verteidigen.",al={"sturmwinds hilfe für westfall","wo sind die wachen"}}},fx={["3bfb9fad"]={q="Warum schickt Euch Wiley der Schwarze zu Gryan Starkmantel?",a="Wiley weiß, dass die The Defias Brotherhood etwas Katastrophales plant, da er Gerüchte zusammengepuzzelt hat, dass sie sich mit Gnollen, Kobolden und Goblins koordinieren. Er ist sich wohl bewusst, dass er mit dem Besitz solcher gefährlichen Geheimnisse sein eigenes Leben aufs Spiel setzt. Indem er sein Wissen in eine versiegelte Nachricht für Gryan Starkmantel packt, überträgt Wiley die Last des Handelns auf die The People's Militia und leistet seinen Beitrag, die Verschwörung zu vereiteln, während er selbst sicher aus dem Fadenkreuz bleibt.",al={"warum hilft wiley","wiley der schwarze motiv","warum wiley notiz schicken"}},["6813809b"]={q="Warum verlässt sich Wiley auf Euch, anstatt die Nachricht selbst zu überbringen?",a="Wiley ist ein krimineller Schurke, der sich in der Taverne von Seenhain unauffällig verhält, weit weg von den wachsamen Augen der Behörden und der The Defias Brotherhood. Ein Fußmarsch durch feindliches Gebiet bis nach Westfall würde ihn in große Gefahr bringen, und seine Vergangenheit mit Gryan Starkmantel macht ihn eher zu einer verhassten Figur als zu einem willkommenen Gast. Ihr seid ein fähiger Kurier, der unbemerkt durch die Wildnis schlüpfen und die Warnung direkt an die Späherkuppe überbringen kann.",al={"warum braucht wiley euch","warum kann wiley nicht nach westfall","warum ich wiley notiz"}}},fp="22,190,20.216.0,18.318.0,29.235.0,27.217.0,23.229.0,50.238.0,41.187.0,61.203.0,41.193.0"}
P.entries["quest:1320"] = {n="Der Schwarze Schild",s="Caz Twosprocket untersucht den schwarzen Schild, der mit dem Geheimnis um das Gasthaus Zur süßen Ruh verbunden ist. Ein Detail entgeht beinahe der Aufmerksamkeit, und Caz schickt Euch mit den Erkenntnissen zu Captain Garran Mumm nach Theramore.",h="Caz Twosprocket untersucht den schwarzen Schild, der mit dem Geheimnis um das Gasthaus Zur süßen Ruh...",kw={"schwarzer schild","caz twosprocket","düstermarschen","garran mumm","gasthaus zur süßen ruh","tauren","theramore"},sec={{t="Ein verbrannter Riemen",b="Ein letztes Detail entgeht Caz Twosprocket beinahe bei der Untersuchung des schwarzen Schildes. Der Lederriemen auf seiner Rückseite ist weggebrannt, doch er scheint für eine große Person gemacht worden zu sein. Caz tippt auf einen Tauren. Mehr kann Caz nicht sagen, also werdet Ihr mit dieser Nachricht und Caz' Entschuldigung, keine größere Hilfe gewesen zu sein, zu Captain Garran Mumm nach Theramore geschickt."},{t="Was Mumm davon hält",b="Captain Garran Mumm findet in Caz' Erkenntnissen nur wenige Anhaltspunkte. Dennoch sagt er, dass er sie im Hinterkopf behalten wird. Er hofft, dass sich weitere Teile des Geheimnisses zusammenfügen und deutlicher zeigen, was geschehen ist."}},faq={{q="Was findet Caz Twosprocket über den Schild heraus?",a="Der Lederriemen auf der Rückseite des Schildes ist weggebrannt, doch er scheint für eine große Person gemacht worden zu sein. Caz tippt auf einen Tauren.",al={"caz erkenntnisse","schild hinweise","schwarzer schild hinweis"}},{q="Wer sollte von Caz' Erkenntnissen erfahren?",a="Captain Garran Mumm in Theramore.",al={"wem vom schild berichten","schwarzen schild abgeben","wo über den schild berichten"}}},fp="16,186,19.337.0,22.202.1,52.128.0,31.34.0"}
P.entries["quest:1321"] = {n="Der Schwarze Schild",s="Krog schickt Euch nach Brackenwall, um Do'gol nach dem Geschwärzten Eisenschild zu fragen.",h="Krog schickt Euch nach Brackenwall, um Do'gol nach dem Geschwärzten Eisenschild zu fragen.",kw={"schwarzer schild","geschwärzter eisenschild","brackenwall","do'gol","düstermarschen","krog"},sec={{t="Eine zweite Meinung",b="Krog findet nichts Ungewöhnliches am Geschwärzten Eisenschild. Dennoch glaubt er, dass Do'gol, der Schmied in Brackenwall, vielleicht mehr erkennen kann. Er mahnt Euch, nicht zu viel zu erwarten."},{t="Do'gols Antwort",b="Do'gol nennt den Schild gut, stark und schwer. Doch er stellt Schilde her, statt sie zu kaufen, und hat daher keine Verwendung dafür. Er sagt, das solltet Ihr wissen."}},faq={{q="Wer schickt Euch mit dem Schild zu Do'gol?",a="Krog schickt Euch zu Do'gol, nachdem er nichts Ungewöhnliches am Geschwärzten Eisenschild gefunden hat.",al={"wer vergibt die quest der schwarze schild","wo beginnt der schwarze schild","questgeber der schwarze schild"}},{q="Wo ist Do'gol zu finden?",a="Do'gol ist der Schmied in Brackenwall.",al={"do'gol standort","wo ist do'gol","do'gol finden"}},{q="Warum schickt Krog Euch zu Do'gol?",a="Krog hofft, dass Do'gol ihm mehr über den Schild sagen kann, obwohl er sich wenig von der Begutachtung verspricht.",al={"warum do'gol aufsuchen","warum dem schmied den schild zeigen"}}},fp="16,84,16.180.0,15.150.1,40.87.0,26.48.0,33.99.0"}
P.entries["quest:1322"] = {n="Der Schwarze Schild",s="In Brackenwall sucht Do'gol Gift für einen Schild, dessen Schrift unter verbrannten Rückständen verborgen liegt. Sechs Beutel von den Darkfang-Spinnen des Sumpfes enthalten Säure, die seinen Rand säubern kann.",h="In Brackenwall sucht Do'gol Gift für einen Schild, dessen Schrift unter verbrannten Rückständen verborgen...",kw={"säurehaltige giftbeutel","brackenwall","darkfang","do'gol","düstermarschen","der schwarze schild"},sec={{t="Den Rand säubern",b="In Brackenwall untersucht Do'gol die Schrift am Rand eines Schildes. Eingebrannter Schmutz macht sie schwer lesbar, doch Säure kann die Rückstände entfernen. Die Darkfang-Spinnen im Sumpf tragen dafür geeignetes Gift in sich, also bittet Do'gol Euch um sechs ihrer Giftbeutel."},{t="Sobald die Beutel eintreffen",b="Do'gol mag keine Spinnen, die zu groß sind, um sich daraufzusetzen und sie zu zerquetschen. Nachdem Do'gol Euch für die Beutel gedankt hat, reißt er sie auf und gießt ihr Gift auf den Schild."}},faq={{q="Wer bittet um das Spinnengift?",a="Do'gol bittet in Brackenwall um Spinnengift.",al={"wer vergibt der schwarze schild","dogol quest","wer startet der schwarze schild"}},{q="Warum braucht Do'gol Giftbeutel?",a="Do'gol braucht Säure, um die verbrannten Rückstände zu entfernen, die die Schrift am Schildrand verdecken. Das Gift der Darkfang-Spinnen eignet sich dafür.",al={"warum spinnensäure","zweck der säurehaltigen giftbeutel","warum den schild säubern"}},{q="Woher stammen die säurehaltigen Giftbeutel?",a="Die säurehaltigen Giftbeutel stammen von Darkfang-Spinnen, die im Sumpf nahe Brackenwall leben.",al={"welche spinnen haben beutel","fundort der darkfang-spinnen","woher säurehaltiges gift bekommen"}},{q="Wie viele Beutel möchte Do'gol haben?",a="Do'gol möchte sechs säurehaltige Giftbeutel haben.",al={"wie viele giftbeutel"}}},fp="16,175,16.251.0,20.150.1,30.52.0,32.116.0,41.94.0,31.35.0"}
P.entries["quest:1323"] = {n="Der Schwarze Schild",s="In Brackenwall schickt Do'gol Euch zu Krog, um einen Namen auf dem Schild zu entziffern. Die Schrift scheint Mosarn zu lauten, doch Do'gol kennt den Namen nicht.",h="In Brackenwall schickt Do'gol Euch zu Krog, um einen Namen auf dem Schild zu entziffern.",kw={"säure","schwarzer schild","brackenwall","do'gol","düstermarschen","krog","mosarn"},sec={{t="Ein Name auf dem Rand",b="Do'gol hat den Schild mit zu viel Säure abgerieben, doch seine Schrift ist noch immer schwer zu lesen. Der Name scheint Mosarn zu lauten, doch Do'gol kennt ihn nicht. Krog kennt viele Leute in Brackenwall, also schickt Do'gol Euch los, um mit Krog zu sprechen."},{t="Krogs Antwort",b="Krog kommt der Name Mosarn bekannt vor, doch er kann ihn nicht zuordnen. Krog hofft, dass er sich wieder daran erinnern wird. Dennoch sagt Krog, dass der Name vielleicht keine Rolle spielt. Schilde kommen von allen möglichen Orten und haben keine Bedeutung."}},faq={{q="Wer ist Do'gol?",a="Do'gol reinigt den Schild mit Säure, damit seine Schrift lesbar wird.",al={"dogol","wer gibt den schwarzen schild"}},{q="Welcher Name steht auf dem Schild?",a="Die Schrift ist schwer zu lesen, doch Do'gol glaubt, dass dort Mosarn steht. Der Name ist Do'gol unbekannt.",al={"welcher name steht auf dem schild","wer ist mosarn","schildinschrift name"}},{q="Warum wegen des Schildes mit Krog sprechen?",a="Do'gol weiß nicht, wer Mosarn ist, sagt aber, dass Krog viele Leute kennt.",al={"warum mit krog sprechen","wer ist krog"}},{q="Wo befindet sich Krog?",a="Krog ist in Brackenwall.",al={"krog standort","wo ist krog zu finden"}}},fp="16,147,17.231.0,13.196.1,14.67.0,27.96.0,34.68.0,22.31.0"}
P.entries["quest:1324"] = {n="The Missing Diplomat",s="Ein Vertreter in den Düstermarschen bittet Euch, Private Hendel zu besiegen. Er soll zur Befragung nach Theramore gebracht werden, während die Suche nach dem König weitergeht.",h="Ein Vertreter in den Düstermarschen bittet Euch, Private Hendel zu besiegen.",kw={"düstermarschen","lady proudmoore","vermisster diplomat","vermisster könig","private hendel","theramore"},sec={{t="Eine Befragung in Theramore",b="Die Suche nach dem König ist noch nicht abgeschlossen, und Private Hendel soll zur Befragung nach Theramore gebracht werden. Ihr sollt ihn in den Düstermarschen besiegen. Danach wartet Lady Proudmoore darauf, von Euch zu hören, und Hendels Befragung könnte bei der Suche nach dem König helfen."}},faq={{q="Wer ist Private Hendel?",a="Private Hendel ist der Mann, den Ihr in den Düstermarschen besiegen und zur Befragung nach Theramore bringen sollt.",al={"hendel","private hendel","wer ist hendel"}},{q="Warum wird Hendel nach Theramore gebracht?",a="Hendel soll in Theramore befragt werden, während nach dem König gesucht wird.",al={"warum theramore","hendels befragung","warum ihn mitnehmen"}},{q="Wer ist Lady Proudmoore?",a="Lady Proudmoore möchte Euch für Eure Hilfe danken.",al={"proudmoore","lady jaina","wer ist sie"}},{q="Was ist mit dem König geschehen?",a="Die Suche nach dem König dauert an.",al={"vermisster könig","wo ist der könig","könig vermisst"}}},fp="20,156,26.273.0,22.108.0,39.70.0,23.72.0,26.35.0"}
P.entries["quest:133"] = {n="Ein Ghulbildnis",s="Im Dämmerwald bedrängen die Toten Calvinius’ Hütte. Er bittet Euch um Ghulrippen, um eine grimmige Vogelscheuche zu bauen und sein Heim zu schützen.",h="Im Dämmerwald bedrängen die Toten Calvinius’ Hütte.",kw={"calvinius","knochenkauer","dunkelhain","dämmerwald","bildnis","fleischesser","ghulrippe","einsiedler"},ang={["class:Paladin"]="Als Paladin könnt Ihr Fleischesser und Knochenkauer jagen, um den Boden des Dämmerwalds zu reinigen. Ihre Überreste einem Einsiedler zu überlassen, könnte Euch beunruhigen.",["class:Priest"]="Als Priester könnt Ihr einem verängstigten Einsiedler inmitten dunkler Geister helfen. Bildnisse aus gesammelten Überresten zu fertigen, könnte Euren Magen auf die Probe stellen.",["faction:Alliance"]="Die Nachtwache hat Mühe, die Straßen zu schützen, weshalb abgeschieden lebende Waldbewohner wie Calvinius auf durchreisende Allianzreisende angewiesen sind, um sich vor den ruhelosen Toten zu schützen."},sec={{t="Die Not eines Einsiedlers",b="Jenseits der bewachten Grenzen von Dunkelhain lebt Calvinius allein zwischen den schattigen Bäumen des Dämmerwalds. Fleischesser und Knochenkauer streifen ungehindert durch die Wildnis. Er sagt, gefräßige Leichen hätten kürzlich seine Wände eingerissen, und bittet Euch deshalb, ihm ihre Rippen zu bringen. Er hofft, ein grausiges Bildnis werde die hungrigen Toten von seinem Heim fernhalten."},{t="Eine bizarre Verteidigung",b="Zum Schutz seiner Holzhütte vertraut Calvinius eher auf einen grimmigen Plan als auf die Nachtwache oder stärkere Wände. Er glaubt, ein Bildnis aus Ghulüberresten werde andere aasfressende Tote verscheuchen. Eine Vogelscheuche aus erschlagenen Untoten zu bauen, ist verstörend. Doch Reisende im Dämmerwald tun oft, worum der Einsiedler bittet, um sich dringend benötigte Münzen zu verdienen."}},faq={{q="Wo lebt Calvinius?",a="Calvinius lebt in einer einsamen Hütte im westlichen Dämmerwald, gleich nordöstlich des Friedhofs von Rabenflucht und fern vom Schutz Dunkelhains.",al={"calvinius standort","wo ist calvinius’ hütte","einsiedlerhütte dämmerwald"}},{q="Warum braucht Calvinius Ghulrippen?",a="Calvinius sagt, dass Ghule in Rudeln gegen die Wände seiner Hütte hämmern. Er will aus ihren Knochen eine grausige Vogelscheuche bauen, um aasfressende Untote zu verscheuchen.",al={"ghulrippen zweck","warum ghulrippen","wozu dient das bildnis"}},{q="Welche Kreaturen lassen Ghulrippen fallen?",a="Ihr könnt die Rippen von Untoten sammeln, die auf den Straßen und Friedhöfen des Dämmerwalds umherstreifen: Fleischesser, Knochenkauer, Brain Eaters, Rotted Ones und Plague Spreaders.",al={"woher rippen bekommen","ghulrippe beute","welche ghule lassen rippen fallen"}},{q="Vertreibt eine Vogelscheuche aus Untoten tatsächlich Ghule?",a="Untote fürchten selten etwas, weshalb erfahrene Monsterjäger an Calvinius’ Plan zweifeln. Der Einsiedler besteht darauf, und in diesen verzweifelten Wäldern stellen nur wenige jemanden infrage, der zahlt.",al={"wirken bildnisse gegen ghule","ghulvogelscheuche logik"}},{q="Warum zieht Calvinius nicht einfach nach Dunkelhain?",a="Calvinius lebt aus freien Stücken allein, fern von der Nachtwache und der Stadtverwaltung. Trotz der Gefahren des Dämmerwalds kümmert er sich lieber um seine Hütte und verlässt sich auf seine eigenen sonderbaren Schutzmaßnahmen.",al={"warum im wald leben","warum zieht calvinius nicht um","dunkelhain sicherheit"}},{q="Was folgt nach dem Sammeln der Rippen?",a="Sobald Calvinius die Ghulrippen hat, kommt ein weiteres seltsames Problem ans Licht: Oger aus der Gegend haben seine Habseligkeiten gestohlen, und er schickt Euch in die Wildnis, um Euch um sie zu kümmern.",al={"nächste quest","was folgt auf ein ghulbildnis"}}},fx={d0d16021={q="Wofür werden die Ghulrippen verwendet?",a="Calvinius behauptet, er brauche die Rippen lokaler Ghule, um ein makabres Bildnis – eine untote Vogelscheuche – zu bauen, das er außerhalb seiner abgelegenen Hütte aufstellen will. Da er weit abseits der Sicherheit von Dunkelhain lebt, besteht er darauf, dass das groteske Konstrukt die fleischfressenden Schrecken abschrecken wird, die an seinen Mauern entlangstreifen.",al={"wofür sind ghulrippen","ghulrippe verwenden","warum ghulrippen sammeln"}},["0ad10362"]={q="Warum braucht Calvinius Euch, um die Rippen zu sammeln?",a="Calvinius ist ein exzentrischer, gebrechlicher Einsiedler, der draußen im Wald festsitzt und weder für Dunkelhain noch für dessen The Nachtwache viel übrig hat. Von den Ghulen, die gegen die Wände seiner Hütte hämmern, verängstigt, fehlt ihm die kämpferische Stärke, sich den verwesenden Schrecken selbst zu stellen, was ihn von vorbeikommenden Abenteurern abhängig macht, die bereit sind, die Gefahren des Dämmerwalds für ein paar Münzen zu riskieren.",al={"warum mich fragen","warum macht calvinius das nicht selbst","warum nicht die night watch fragen"}},cd024384={q="Warum durchstreifen Ghule den Dämmerwald?",a="Der schleichende Schatten, der die Region in ewige Dämmerung hüllte, hat auch ihre Toten aufgewühlt. Ruhelose Untote, von gefräßigen Knochenkauern bis hin zu fleischfressenden Ghulen, erheben sich nun in der Finsternis und auf den Friedhöfen, durchstreifen die verfallenden Wälder und machen unerbittlich Jagd auf jede lebende Seele, die dumm genug ist, sich außerhalb der befestigten Siedlungen zu wagen.",al={"warum gibt es hier ghule","dämmerwald ghule","woher kommen die ghule"}}},fp="15,130,17.313.0,17.305.0,28.135.0,37.160.0,36.155.0,56.165.0,53.182.0,41.166.0"}
P.entries["quest:1338"] = {n="Sturmlanzes Bestellung",s="In Loch Modan schickt Gebirgsjäger Sturmlanze eine Schildbestellung nach Süden, nach Sturmwind. Er bittet Euch, sie Furen Langbart zu überbringen, dem Rüstungsschmied seines Vertrauens.",h="In Loch Modan schickt Gebirgsjäger Sturmlanze eine Schildbestellung nach Süden, nach Sturmwind.",kw={"rüstungsschmied","der zwergendistrikt","furen langbart","eisenschmiede","loch modan","schild","sturmlanze","sturmwind"},ang={["faction:Alliance"]="Als Reisender der Allianz könnt Ihr die Handelsbeziehungen und kulturellen Bande zwischen den Zwergenfestungen von Khaz Modan und Sturmwind erkennen, die durch die Tiefenbahn verbunden sind.",["profession:Blacksmithing"]="Als Schmied könnt Ihr auf Eurer Reise durch Sturmwind auf Furen Langbart aufmerksam werden, einen außergewöhnlichen Rüstungsschmied, der selbst über die Grenzen der Königreiche hinaus bekannt ist.",["race:Dwarf"]="Als Zwerg seht Ihr, wie weit der Ruf eines Klans reichen kann. Sturmlanzes Bestellung wirft auch die Frage auf, warum ein Rüstungsmeister menschliches Mauerwerk Eisenschmiede vorziehen würde."},sec={{t="Ein Schild, der die Reise lohnt",b="Sturmlanze vertraut seinen Schild keinem anderen Schmied an. Er bietet gute Bezahlung dafür, den Auftrag in Furen Langbarts Hände zu legen, obwohl Sturmwind weit südlich von Loch Modan liegt."},{t="Von Eisenschmiede zum Zwergendistrikt",b="Sturmlanze fragt sich, warum Furen so weit entfernt von Eisenschmiede und der Großen Schmiede arbeitet, wo viele Zwerge zu Hause sind. Er vermutet, dass die Menschen von Sturmwind dem Schmied ein königliches Vermögen zahlen.\n\nAls der Auftrag Furen an seinem Amboss erreicht, erfüllt es ihn mit Stolz, vom angesehenen Klan der Sturmlanzen zu hören. Eifrig bereitet er sich darauf vor, den Schild zu schmieden."}},faq={{q="Wer ist Gebirgsjäger Sturmlanze?",a="Gebirgsjäger Sturmlanze ist ein Wachposten der Allianz, der in Loch Modan stationiert ist. Er gehört dem stolzen und einflussreichen Klan der Sturmlanzen an und dient unter den zwergischen Gebirgsjägern, die die Gebirgspässe und Täler bewachen.",al={"gebirgsjäger sturmlanze","wer vergibt die quest","questgeber"}},{q="Wer ist Furen Langbart?",a="Furen Langbart ist ein versierter zwergischer Rüstungsschmied, der im Zwergendistrikt von Sturmwind lebt. Sein Ruf als Schmied feiner Schilde und Rüstungen reicht bis nach Khaz Modan im Norden.",al={"furen langbart","wer ist furen","der rüstungsschmied"}},{q="Warum lebt Furen in Sturmwind statt in Eisenschmiede?",a="Furen Langbart arbeitet im Zwergendistrikt von Sturmwind und bedient menschliche Adlige, Stadtwachen und reisende Abenteurer. Gebirgsjäger Sturmlanze fragt sich, warum ein zwergischer Meister Eisenschmiede verlassen würde, doch Furen verdient vermutlich reichlich menschliche Münzen.",al={"warum ist furen in sturmwind","warum zwergendistrikt","furen verlässt eisenschmiede"}},{q="Welche Rolle spielt die Tiefenbahn bei der Zustellung dieser Bestellung?",a="Reisende mit Sturmlanzes Schreiben gehen meist von Loch Modan nach Westen nach Eisenschmiede und nehmen dann die Tiefenbahn unterirdisch zum Zwergendistrikt von Sturmwind, wo Furens Schmiede liegt.",al={"reise nach sturmwind","wie kommt man nach sturmwind","die tiefenbahn"}},{q="Was kommt vor dieser Quest?",a="Bevor Gebirgsjäger Sturmlanze Euch die Lieferung nach Sturmwind anvertraut, prüft er Euren Mut und Eure Zuverlässigkeit in Loch Modan mit 'Gebirgsjäger Sturmlanzes Aufgabe'.",al={"voraussetzungen","vorherige quest","gebirgsjäger sturmlanzes aufgabe"}},{q="Schmiedet Furen Langbart den Schild sofort?",a="Als Furen Langbart den Brief erhält und das Ansehen des Namens Sturmlanze erkennt, nimmt er den Auftrag an. Er verspricht, noch vor Ende des Tages mit dem Schmieden des Schildes zu beginnen.",al={"was passiert als nächstes","folgequest","furens reaktion"}}},fx={["317873dc"]={q="Warum möchte Gebirgsjäger Sturmlanze, dass dies erledigt wird?",a="Gebirgsjäger Sturmlanze benötigt einen neuen Schild und hält die Handwerkskunst von Furen Langbart für außergewöhnlich hochwertig, da er das Können des Rüstungsschmieds als unübertroffen betrachtet. Obwohl er darüber verwundert ist, dass ein meisterhafter Zwergenschmied so weit entfernt bei den Menschen von Sturmwind lebt anstatt in der Nähe von Eisenschmiede, will sich Sturmlanze nicht mit minderwertigem Schutz zufriedengeben und besteht darauf, einen Schild von Furen persönlich schmieden zu lassen.",al={"warum braucht sturmlanze einen schild","motiv gebirgsjäger sturmlanze","warum bei furen bestellen"}},["02c191af"]={q="Warum bittet Euch Gebirgsjäger Sturmlanze darum, anstatt selbst zu gehen?",a="Als aktiver Gebirgsjäger, der in den hohen Pässen von Loch Modan stationiert ist, kann Sturmlanze seinen Posten, an dem er die Zwergengrenzen bewacht, nicht einfach verlassen, um in den Süden in die Menschenlande zu reisen. Die Übermittlung eines Auftrags an den Zwergendistrikt in Sturmwind erfordert eine lange Reise, daher wendet er sich an reisende Abenteurer, die Zeit übrig haben und bereit sind, sein Schreiben gegen ehrliche Bezahlung zu überbringen.",al={"warum einen abenteurer zu furen schicken","warum kann sturmlanze den auftrag nicht selbst überbringen","warum ich sturmlanze auftrag"}}},fp="17,152,26.173.0,38.326.0,29.208.0,23.180.0,54.242.0,57.195.0,29.160.0,50.191.0"}
P.entries["quest:1339"] = {n="Gebirgsjäger Sturmlanzes Aufgabe",s="An seinem Posten in Loch Modan braucht Gebirgsjäger Sturmlanze einen Läufer für dringende Angelegenheiten jenseits des Tals. Gebirgsjäger Kadrell schickt Euch zu ihm, da Sturmlanze seine Wache nicht verlassen kann.",h="An seinem Posten in Loch Modan braucht Gebirgsjäger Sturmlanze einen Läufer für dringende Angelegenheiten...",kw={"wachturm","eisenschmiede","loch modan","gebirgsjäger kadrell","gebirgsjäger sturmlanze","läufer","stormpike's order","thelsamar"},ang={["faction:Alliance"]="Als Reisender der Allianz helft Ihr den örtlichen Gebirgsjägern, Depeschen zu überbringen, die die Versorgung und Koordination von Eisenschmiedes Garnisonen in den östlichen Gebieten sichern.",["race:Dwarf"]="Als Zwerg fühlt Ihr Euch vielleicht von Natur aus verpflichtet, einem anderen Zwerg aus dem berühmten Geschlecht der Stormpike zu helfen und die Clanbande über Khaz Modan hinweg zu ehren."},sec={{t="Ein Wachmann braucht einen Läufer",b="Der nördliche Wachturm ist Sturmlanzes Posten, und sein Wachdienst hält ihn in Loch Modan fest. Troggs und umherstreifende Wildtiere bringen die Gebirgsjäger an ihre Grenzen. Deshalb verweist Kadrell fähige Reisende an Wachen, die ihre Pflichten nicht vernachlässigen können. Sturmlanze braucht einen Boten für Angelegenheiten weit jenseits der Grenzen dieser Region."},{t="Vom Turm zu fernen Straßen",b="Ihr findet Sturmlanze oben auf dem nördlichen Wachturm, von wo aus er über das Tal blickt. Er gehört dem angesehenen Stormpike-Clan an und hat Angelegenheiten jenseits der Grenzverteidigung von Thelsamar zu regeln. Mit seiner Nachricht und seinen Vorräten überschreitet Ihr in seinem Namen die Grenzen der Region. Euer Weg führt Euch vom Loch auf die großen Straßen von Khaz Modan."}},faq={{q="Wo finde ich Gebirgsjäger Sturmlanze?",a="Gebirgsjäger Sturmlanze hält oben auf dem nördlichen Wachturm in Loch Modan Wache und überblickt die umliegenden Pfade.",al={"sturmlanze standort","wo ist sturmlanze","sturmlanzes turm finden"}},{q="Wer vergibt diese Quest?",a="Gebirgsjäger Kadrell patrouilliert nahe Thelsamar in Loch Modan und weist Euch den Weg zu Sturmlanzes Turm.",al={"wer vergibt gebirgsjäger sturmlanzes aufgabe","questgeber","kadrell standort"}},{q="Warum braucht Sturmlanze einen Abenteurer?",a="Sturmlanze kann seinen Posten am Turm nicht verlassen. Seine privaten Angelegenheiten führen weit über Loch Modan hinaus, deshalb braucht er einen Reisenden, der seine Nachricht überbringt.",al={"warum einen läufer brauchen","sturmlanzes problem","was will sturmlanze"}},{q="Was geschieht, nachdem ich mich bei Sturmlanze gemeldet habe?",a="Wenn Ihr Euch bei Sturmlanze meldet, schließt Ihr diesen ersten Schritt ab und erhaltet seinen Folgeauftrag zur Lieferung, 'Stormpike's Order', der Euch in ein anderes Gebiet führt.",al={"nächste quest","was kommt nach gebirgsjäger sturmlanzes aufgabe","sturmlanze folgequest"}},{q="Hängt das mit der Stormpikegarde in Alterac zusammen?",a="Gebirgsjäger Sturmlanze trägt den Namen und das Blut des Stormpike-Clans, der für die Stormpikegarde und seine Bergbauexpeditionen bekannt ist. Seine Arbeit hier ist eine bescheidene örtliche Besorgung.",al={"verbindung zum stormpike-clan","alteractal sturmlanze","sind das die stormpikes aus dem av"}},{q="Gibt es hier eine entsprechende Quest für Spieler der Horde?",a="Nein. Loch Modan ist Zwergengebiet, das zur Allianz gehört, und seine Gebirgsjäger greifen Reisende der Horde auf Sicht an.",al={"hordenversion","kann die horde das machen"}}},fx={d38a276d={q="Warum will Gebirgsjäger Kadrell, dass dies erledigt wird?",a="Gebirgsjäger Kadrell fungiert lediglich als wachsamer Späher und Verbindungsmann für seine Mitwachen. Da er an der Straße stationiert ist, weiß er, dass Gebirgsjäger Sturmlanze einen fähigen Läufer für einen abgelegenen Auftrag braucht, den Wachen im Dienst nicht erledigen können, da sie ihre Posten nicht verlassen dürfen. Als er einen fähigen Reisenden entdeckt, gibt Kadrell die Nachricht weiter, damit Sturmlanze die Hilfe finden kann, die er benötigt.",al={"warum schickt kadrell euch zu sturmlanze","gebirgsjäger kadrell motiv","warum mit sturmlanze sprechen"}}},fp="28,185,30.320.0,27.323.0,38.115.0,22.96.0,38.140.0,42.141.0,50.168.0,47.116.0"}
P.entries["quest:134"] = {n="Ogerdiebe",s="Im westlichen Dämmerwald schickt Calvinius Reisende zur Ogerfestung im Ogerhort Vul'Gol. Er sagt, sie hätten ihn beim Sammeln überfallen und eine Kiste mit unersetzlichen Kräutern und Werkzeugen geraubt.",h="Im westlichen Dämmerwald schickt Calvinius Reisende zur Ogerfestung im Ogerhort Vul'Gol.",kw={"calvinius","kiste","dämmerwald","einsiedler","oger","vul'gol"},ang={["class:Paladin"]="Als Paladin könnte Euch Calvinius' eifrige, verschwiegene Freude über die Rückkehr seiner Kiste dazu veranlassen, dem zurückgezogen lebenden Einsiedler nicht blindlings zu helfen.",["class:Warlock"]="Als Hexenmeister erkennt Ihr in Calvinius' Versprecher womöglich ein Lob auf dunkle Zauberkunst statt bloßer Pflanzenliebe.",["profession:Herbalism"]="Als Kräuterkundiger fragt Ihr Euch vielleicht, welch bizarre Pflanzen Calvinius so verzweifelt darauf erpicht machen, seine Kiste aus einem Ogerhort zurückzuholen."},sec={{t="Die verlorenen Güter eines Einsiedlers",b="An den feuchten Straßen des westlichen Dämmerwalds erzählt Calvinius, er sei beim Sammeln von Vorräten angegriffen worden. Unholde aus dem südlichen Ogerhort vertrieben den betagten Einsiedler. Er ließ eine robuste Holzkiste voller kostbarer Kräuter und empfindlicher Instrumente zurück."},{t="Die Bedrohung durch Vul'Gol",b="Im südlichen Dämmerwald ist der Ogerhort Vul'Gol eine Gefahr für unachtsame Wanderer. Feindselige Oger bedrängen dort Reisende, und Calvinius' Kiste liegt nahe dem Eingang zwischen brüllenden Unholden und zauberwirkenden Magiern."},{t="Ein Versprecher",b="Als Calvinius seine Güter zurückbekommt, weicht seine exzentrische Art manischer Begeisterung. Beinahe ruft er ein Lob auf „den Nek—“ aus, bevor er sich besinnt und stattdessen Euch dankt. Dann schließt er sich eifrig im Dunkeln ein, um seine wiedererlangten Vorräte zu nutzen."}},faq={{q="Wer ist Calvinius?",a="Calvinius ist ein exzentrischer Einsiedler in einer heruntergekommenen Hütte im westlichen Dämmerwald. Er gibt sich gebrechlich und hilflos und scheint Unterstützung zu brauchen, doch sein hektisches Verhalten und seine seltsamen Bitten deuten auf finsterere Beweggründe hin.",al={"calvinius geschichte","wer hat mir diese quest gegeben","wer ist der einsiedler"}},{q="Wohin haben die Oger Calvinius' Kiste gebracht?",a="Die Oger brachten Calvinius' Kiste zum Ogerhort Vul'Gol im südlichen Dämmerwald. Sie liegt offen auf dem Erdboden direkt vor dem Eingang des Horts.",al={"wo ist die kiste","fundort der kiste","vul'gol kiste"}},{q="Warum gibt es Oger im Dämmerwald?",a="Die aggressiven und opportunistischen Oger des Vul'Gol-Clans haben sich in den zerklüfteten südlichen Hügeln des Dämmerwalds festgesetzt. Sie überfallen Vorbeireisende, lauern einsamen Wanderern auf und horten geraubte Beute rund um ihren Hort.",al={"dämmerwald oger","herkunft der oger von vul'gol","warum sind hier oger"}},{q="Was ist wirklich in der Kiste?",a="Calvinius behauptet, die Kiste enthalte seltene Kräuter und spezielle Erntewerkzeuge, die er beim Angriff zurückgelassen habe. Er ist überglücklich, sie wiederzuhaben.",al={"was hat calvinius verloren","inhalt der kiste"}},{q="Was hätte Calvinius beim Empfang der Kiste beinahe gesagt?",a="Als Calvinius seine Kiste zurückbekommt, setzt er dazu an, jemand anderem zu danken, besinnt sich dann aber abrupt und dankt stattdessen Euch. Voller Freude blickt er den kommenden Nächten entgegen.",al={"dank dem nek","was wollte calvinius sagen","calvinius zitat"}},{q="Hängt diese Quest mit anderen Aufgaben am Ogerhort zusammen?",a="Reisende auf dem Weg zum Ogerhort Vul'Gol sammeln womöglich auch Ogermonokel für Viktori Prism'Antras.",al={"ogerhort quests","quests bei vulgol"}}},fx={["7ac39a32"]={q="Warum will Calvinius seine Kiste zurück?",a="Calvinius behauptet, er sei weit weg von seiner Hütte auf Futtersuche gewesen, als ihn Oger überfielen und ihn zwangen, eine Sammlung seltener Kräuter und empfindlicher Werkzeuge zurückzulassen. Für einen isolierten Einsiedler, der am Rande des Friedhofs lebt, ist es fast unmöglich, solche Vorräte alleine zu ersetzen. Doch seine extreme Aufregung und seine verzweifelte Erleichterung bei deren Rückkehr deuten darauf hin, dass der Inhalt einem Vorhaben dient, das weitaus finsterer ist als gewöhnliche Kräuterkunde.",al={"warum kiste zurückholen","calvinius kiste motiv","warum will er die kiste"}},["1d020e8a"]={q="Wer sind die Oger, die die Kiste festhalten?",a="Die Diebe gehören zu den Ogern vom Ogerhort Vul'Gol, brutale Ausgestoßene, die sich einen abscheulichen Hügel in den Felsen des südlichen Dämmerwalds ausgehauen haben. Bekannt für das Ausrauben von Reisenden auf den dunklen Pfaden, stießen sie auf Calvinius, als er außerhalb seiner üblichen Aufenthaltsorte umherstreifte, vertrieben den alten Einsiedler und schleppten seine Ladung zusammen mit anderer Beute in ihre Siedlung.",al={"wer hat die kiste genommen","vul'gol oger","dämmerwald oger kiste"}},["504b8e87"]={q="Warum bittet Calvinius Euch anstelle der The Nachtwache?",a="Calvinius ist ein gebrechlicher, zurückgezogener Einsiedler, dem es sowohl an der Kraft fehlt, sich einem Lager aus massigen Bestien entgegenzustellen, als auch an jeglichem Wohlwollen seitens Dunkelhain. Misstrauische Stadtbewohner und die überlastete The Nachtwache halten sich von seiner Hütte fern und bewachen nur die Hauptstraßen und den Stadtrand. Da er sich nicht auf die örtlichen Behörden verlassen kann, ist der Einsiedler auf reisende Abenteurer angewiesen, die bereit sind, den Gefahren des Ogerhorts Vul'Gol zu trotzen.",al={"warum mich fragen","warum nicht night watch","warum braucht calvinius hilfe"}}},fp="12,192,21.250.0,18.204.0,20.264.1,19.201.0,45.143.0,32.210.0,34.145.1,57.170.1,57.100.0"}
P.entries["quest:135"] = {n="Die Bruderschaft der Defias",s="In Westfall vermutet Gryan Starkmantel Verbindungen zwischen der Bruderschaft der Defias und Sturmwinds alter Steinmetzgilde. Er schickt Euch mit Wileys Nachricht dorthin.",h="In Westfall vermutet Gryan Starkmantel Verbindungen zwischen der Bruderschaft der Defias und Sturmwinds alter...",kw={"bruderschaft","defias","gryan starkmantel","mathias shaw","die altstadt","si:7","steinmetze","westfall","wileys nachricht"},ang={["class:Rogue"]="Im SI:7-Hauptquartier begegnet Ihr Mathias Shaw, dem Großmeister von Sturmwinds Schurken und Spionen. Seine Arbeit verbindet Westfalls örtliche Unruhen mit weiterreichender Spionagetätigkeit.",["faction:Alliance"]="Als Mitglied der Allianz seht Ihr Risse im wichtigsten Königreich der Allianz. Manche Bedrohungen gehen von verratenen Bürgern aus, nicht von monströsen Fremden.",["race:Human"]="Als Mensch aus Sturmwind seht Ihr, wie Westfalls gesetzloses Grenzland auf die bitteren politischen Skandale trifft, die seit dem Wiederaufbau Eurer Hauptstadt ungelöst blieben."},sec={{t="Ein Versprecher",b="Wileys Erwähnung der Steinmetze weckt Gryans Aufmerksamkeit. Die Gilde baute Sturmwind nach dem Ersten Krieg wieder auf, doch viele glauben, sie habe sich zerstreut oder aufgelöst. Wenn die Defias mit der Gilde verbunden sind, könnte Westfalls ländlicher Aufstand mehr sein als eine Bande von Gesetzlosen."},{t="Geheimnisse der Altstadt",b="Gryan kann seinen Verdacht von der Späherkuppe aus nicht überprüfen, also schickt er Euch zu Meister Mathias Shaw, dem Leiter von Sturmwinds verdecktem Geheimdienst SI:7. Shaw arbeitet von der Kaserne in der Altstadt aus und sammelt Gerüchte und Geheimnisse aus dem gesamten Reich. Vielleicht kann er die Ursprünge der Bruderschaft der Defias ergründen."},{t="Der Schatten über der Krone",b="Als Ihr Meister Mathias Shaw Wileys Nachricht bringt, erkennt er, dass Westfalls Rebellion tiefer reicht, als Gryan versteht. Sie ist auch politisch vielschichtiger. Ihre Wurzeln reichen in Sturmwinds bewegte Vergangenheit zurück."}},faq={{q="Warum schickt Gryan Starkmantel Euch nach Sturmwind?",a="Wileys Nachricht erwähnt die Steinmetze, weshalb Gryan Starkmantel hinter dem Banditentum politische Intrigen vermutet. Er schickt Euch zu Meister Mathias Shaw, um die Verbindung bestätigen zu lassen.",al={"warum nach sturmwind","warum sturmwind quest","starkmantel sturmwind botengang"}},{q="Wer ist Mathias Shaw?",a="Meister Mathias Shaw leitet SI:7, Sturmwinds verdeckten Geheimdienst und Spionageabteilung. Er arbeitet von der Kaserne in der Altstadt aus.",al={"wer ist shaw","mathias shaw aufgabe","si7 anführer"}},{q="Wo finde ich Mathias Shaw?",a="Ihr findet Meister Mathias Shaw im zweiten Stock des SI:7-Hauptquartiers in der Kaserne in Sturmwinds Altstadt.",al={"wo ist shaw","shaw standort","mathias shaw finden"}},{q="Welche Verbindung besteht zwischen den Defias und den Steinmetzen?",a="Die Steinmetzgilde baute Sturmwind nach seiner Zerstörung im Ersten Krieg wieder auf. Gryan Starkmantel vermutet, dass Wileys Erwähnung der Gilde sie mit den Defias verbindet, und Mathias Shaw könnte diese Verbindung bestätigen oder widerlegen.",al={"defias steinmetze","sind defias steinmetze","verbindung zu den steinmetzen"}},{q="Was ist Wileys Nachricht?",a="Wileys Nachricht stammt von Wiley dem Schwarzen, einem Schurken, mit dem Gryan Starkmantel schon früher zu tun hatte. Sie warnt davor, dass die Defias mit Gnollen, Kobolden und Goblins gemeinsame Pläne schmieden. Wileys Erwähnung der Steinmetze könnte die Bruderschaft der Defias mit der ehemaligen Gilde verbinden.",al={"wileys nachricht","was ist die nachricht","nachricht an shaw"}},{q="Wissen Hochlord Bolvar oder der Kindkönig davon?",a="Geheime Staatsangelegenheiten laufen über Mathias Shaw und SI:7, bevor sie Hochlord Bolvar Fordragon und den Thron erreichen. Shaw sagt, die Angelegenheit könnte vielschichtiger sein, als Starkmantel ahnt.",al={"weiß der könig davon","weiß bolvar davon","wissensstand der regierung von sturmwind"}}},fx={f764ce01={q="Warum schickt Euch Gryan Starkmantel anstelle eines Soldaten der The People's Militia?",a="Die The People's Militia ist bis aufs Äußerste strapaziert, nur um die Späherkuppe und die verstreuten Farmen von Westfall zu verteidigen. Gryan Starkmantel kann es sich nicht leisten, kampfbereite Verteidiger von der Front abzuziehen, um Nachrichten zurück in die Hauptstadt zu bringen. Außerdem seid Ihr ein Außenstehender, der Wileys Hinweise bereits zusammengesetzt hat, was Euch zu einem vertrauenswürdigen Kurier macht, der sensible Anfragen direkt zum Spionagemeister von Sturmwind bringen kann.",al={"warum mich schicken","warum nicht miliz","warum braucht starkmantel euch"}}},fp="22,147,20.262.0,16.290.0,25.216.1,49.178.0,20.125.0,29.118.0,62.212.1,21.254.0,53.181.0"}
P.entries["quest:1358"] = {n="Probe für Helbrim",s="Im Wegekreuz wartet Apotheker Helbrim auf ein Wolfsherz von jenseits des Meeres. Apothekerin Zinge hat es aus Unterstadt geschickt, um die Forschung der Verlassenen im zentralen Kalimdor zu unterstützen.",h="Im Wegekreuz wartet Apotheker Helbrim auf ein Wolfsherz von jenseits des Meeres.",kw={"apotheker helbrim","apothekerin zinge","das wegekreuz","königliche apothekervereinigung","probe für helbrim","brachland","unterstadt","wolfherzprobe"},ang={["faction:Horde"]="Als Mitglied der Horde seht Ihr, wie Orcs und Tauren die Hilfe der Verlassenen bei der Verteidigung des Wegekreuzes begrüßen. Die stillen Untersuchungen verseuchter Überreste durch die Apotheker bringen eine beunruhigende Präsenz ins friedliche Brachland.",["race:Undead"]="Als Untoter tragt Ihr die verseuchten Proben der Königlichen Apothekervereinigung durch die ganze Welt. Ihr seid Teil ihrer weitreichenden Bemühungen, die Vorherrschaft der Verlassenen durch chemische Überlegenheit zu sichern."},sec={{t="Eine Seuche über das Meer",b="Apothekerin Zinge schickt eine Wolfherzprobe aus Unterstadt zu Apotheker Helbrim ins Brachland. Die Experimente der Königlichen Apothekervereinigung reichen nun über Lordaerons Ruinen hinaus. Apotheker Renferrel im Silberwald hatte verdorbene Organe geschickt, bevor Zinge ihre Forschung über die ganze Welt ausdehnen wollte. Nun bringt ein Kurier die Probe über das Meer zu Helbrim, einem Alchemisten, der in der trockenen Savanne des Brachlands stationiert ist."},{t="Helbrims Ehrgeiz",b="Im Wegekreuz untersucht Apotheker Helbrim, wie Kalimdors einheimische Bestien auf Verbindungen aus den Pestländern reagieren. Das Wolfsherz könnte zeigen, wie diese Giftstoffe auf einheimische Kreaturen wirken. Helbrim glaubt, dass seine Sezierung und Untersuchung neben diesen Kreaturen den Verlassenen helfen wird, Gifte und unnatürliche Leiden zu beherrschen."}},faq={{q="Was enthält das Paket, das Helbrim überbracht wird?",a="Das Paket enthält eine Wolfherzprobe. Apotheker Renferrel entnahm sie den verderbten Wölfen des Silberwalds, und Apothekerin Zinge untersuchte sie in Unterstadt.",al={"was ist die probe","paket mit wolfsherz","was hat zinge mir gegeben"}},{q="Warum will Apotheker Helbrim ein verseuchtes Wolfsherz?",a="Helbrim untersucht, wie Giftstoffe aus Lordaeron auf Kalimdors Tierwelt wirken. Er hofft, dass die extreme Giftigkeit des Herzens dabei hilft, stärkere Mixturen und Gifte für die Königliche Apothekervereinigung zu entwickeln.",al={"warum braucht helbrim ein wolfsherz","helbrims forschung","helbrims absicht"}},{q="Wo befindet sich Apotheker Helbrim?",a="Apotheker Helbrim ist im Wegekreuz im Brachland stationiert, auf der oberen Außenplattform des zentralen Wachturms mit Blick über die Siedlung.",al={"wo ist helbrim","helbrims standort","helbrim finden"}},{q="Wie gelangt ein Reisender von Unterstadt zum Wegekreuz?",a="Nehmt den Zeppelin vom Turm vor Unterstadt nach Orgrimmar in Durotar. Reist durch Durotar nach Süden und überquert den Südstrom ins Brachland. Folgt dann der Hauptstraße nach Westen zum Wegekreuz.",al={"reise zum wegekreuz","wie zu helbrim gelangen","von unterstadt ins brachland"}},{q="Wer sind Apotheker Renferrel und Apothekerin Zinge?",a="Apotheker Renferrel und Apothekerin Zinge sind Forscher der Königlichen Apothekervereinigung. Renferrel arbeitet im Grabmal im Silberwald, während Zinge im Apothekarium in Unterstadt forscht.",al={"wer ist renferrel","wer ist zinge","geschichte von zinge und renferrel"}},{q="Welcher Fraktion dient diese Forschung?",a="Die Forschung dient den Verlassenen und der Königlichen Apothekervereinigung unter Fürstin Sylvanas Windläufer. Sie bringt ihre Bemühungen voran, tödliche chemische und biologische Waffen zu erschaffen.",al={"wem nützt es","ist das für sylvanas","ziel des apothekers"}}},fx={d2670c0d={q="Warum möchte Apothekerin Zinge, dass diese Probe zu Helbrim geliefert wird?",a="Apothekerin Zinge möchte die umfassendere Forschung der Königlichen Apothekergesellschaft auf beiden Kontinenten unterstützen. Ihr Kollege Apotheker Helbrim ist in Kalimdor stationiert und untersucht, wie die verseuchten Gifte aus Lordaeron auf einheimische Bestien reagieren. Da sie glaubt, dass die verseuchten Wolfsherzen aus dem Silberwald ihr gemeinsames Wissen über bösartige Gifte erweitern könnten, entsendet Zinge Euch, damit Helbrim das Material für seine Experimente erhält.",al={"warum probe zu helbrim","motive von zinge zur probe","warum will zinge die lieferung"}}},fp="18,190,26.403.0,18.308.0,47.166.0,54.192.0,36.146.0,57.202.0,50.205.0,38.172.0"}
P.entries["quest:1359"] = {n="Zinges Lieferung",s="Vom Grabmal aus schickt Apotheker Renferrel seltsame Wolfsherzen nach Unterstadt. Ihre Gifte hätten die Bestien töten müssen, und Apothekerin Zinge nimmt sie zur Untersuchung durch die Königliche Apothekervereinigung entgegen.",h="Vom Grabmal aus schickt Apotheker Renferrel seltsame Wolfsherzen nach Unterstadt.",kw={"das apothekarium","apotheker renferrel","apothekerin zinge","das grabmal","silberwald","unterstadt","wolfherzproben","zinges lieferung"},ang={["faction:Horde"]="Als Mitglied der Horde wisst Ihr, dass Boten mit biologischen Reagenzien entlegene Außenposten wie das Grabmal mit Unterstadts Anführern und Forschungshallen verbinden.",["race:Undead"]="Als Untoter wisst Ihr, dass Feldproben aus Lordaeron die alchemistischen Labore unter den Ruinen von Capital City erreichen und die Wissenschaft der Verlassenen voranbringen."},sec={{t="Eine giftige Anomalie",b="In den verwüsteten Wäldern des Silberwalds fand Apotheker Renferrel Wölfe mit einer tödlichen Eigenschaft. Die Gifte in ihren Herzen waren so stark, dass sie die Tiere hätten töten müssen. Er konservierte mehrere Gewebeproben und verpackte sie für seine Kollegen im Apothekarium in Unterstadt."},{t="Die Augen des Apothekariums",b="Im unterirdischen Hauptquartier der Königlichen Apothekervereinigung in Unterstadt nimmt Apothekerin Zinge die konservierten Organe entgegen. Die Vereinigung sucht nach wirksamen Seuchen und neuen alchemistischen Verbindungen, weshalb Gifte, die ihre Wirte am Leben lassen, ihre Aufmerksamkeit wecken. Zinge begrüßt die Proben für weitere Versuche in den Laboren des gesamten alchemistischen Netzwerks der Verlassenen."}},faq={{q="Was sind die Wolfherzproben?",a="Die Proben bestehen aus konserviertem Gewebe von Wölfen aus dem Silberwald. Apotheker Renferrel fand in ihren Herzen natürliche Gifte, die so tödlich waren, dass die Tiere sie nicht hätten überleben dürfen.",al={"wolfsherzen","was sind wolfherzproben","renferrel proben"}},{q="Wer ist Apotheker Renferrel?",a="Apotheker Renferrel ist ein Mitglied der Königlichen Apothekervereinigung, das im Grabmal im Silberwald stationiert ist. Er leitet die Feldforschung zu Pflanzen und Tieren der Region und sammelt Zutaten und Wissen für die Alchemie der Verlassenen.",al={"wer ist renferrel","renferrel silberwald"}},{q="Wer ist Apothekerin Zinge?",a="Apothekerin Zinge ist eine alchemistische Forscherin im Apothekarium von Unterstadt. Sie untersucht eintreffende biologische Proben auf neue Gifte und alchemistische Wirkstoffe für die Verlassenen.",al={"wer ist zinge","zinge unterstadt","apothekerin zinge hintergrund"}},{q="Wohin führt diese Lieferung als Nächstes?",a="Apothekerin Zinge nimmt das seltsame Herzgewebe entgegen und untersucht es, bevor Proben an andere alchemistische Außenposten gehen. Einer dieser Außenposten gehört Apotheker Helbrim, jenseits des Meeres im Brachland.",al={"nächste quest","was geschieht nach zinges lieferung","folgequest"}},{q="Warum interessiert sich die Königliche Apothekervereinigung für Wolfsherzen?",a="Die Königliche Apothekervereinigung sucht nach ungewöhnlichen Giften, Krankheiten und biologischen Anomalien. Eine Bestie, die tödliche Gifte im eigenen Herzen überlebt, könnte chemische Wege zu neuen Seuchen und Verbindungen aufzeigen.",al={"warum wollen apotheker wolfsherzen","ras wolfsherzen"}},{q="Wo liegt das Apothekarium in Unterstadt?",a="Das Apothekarium nimmt den südwestlichen Flügel von Unterstadt ein. Es ist der zentrale Laborkomplex und das Hauptquartier der Königlichen Apothekervereinigung.",al={"unterstadt apotheker standort","wo ist zinge","apothekarium karte"}}},fx={["37fb7d35"]={q="Warum schickt Apotheker Renferrel Euch, anstatt selbst zu gehen?",a="Apotheker Renferrel ist am Grabmal im Silberwald stationiert, wo er aktive Feldarbeit und fortlaufende Forschungen an der örtlichen Tierwelt betreibt. Wenn er seinen Außenposten verlässt, um Proben in die Hauptstadt zu bringen, würde ihn das von seinen Experimenten abhalten. Daher ist ein fähiger Reisender der ideale Kurier, um die zerbrechlichen Proben direkt zu Apothekerin Zinge ins Apothekarium zu transportieren.",al={"warum ich renferrel","warum braucht renferrel einen kurier","warum einen abenteurer mit der lieferung schicken"}}},fp="16,206,15.270.0,28.346.0,32.186.0,28.227.0,24.187.0,35.190.1,62.192.0,39.144.0"}
P.entries["quest:136"] = {n="Käpt'n Sanders' versteckter Schatz",s="An Westfalls Küste beginnt Käpt'n Sanders' versteckter Schatz mit einer ramponierten Pergamentkarte. Sie schickt Euch auf die Suche nach seiner persönlichen Seemannskiste und dann weiter zu seiner versteckten Beute quer durch die Region.",h="An Westfalls Küste beginnt Käpt'n Sanders' versteckter Schatz mit einer ramponierten Pergamentkarte.",kw={"käpt'n sanders","seemannskiste","versteckter schatz","rostiger anker","schiffswrack","schatzkarte","westfalls küste"},ang={["class:Rogue"]="Als Schurke wisst Ihr, wie wertvoll es ist, der Karte eines toten Seemanns an einer gesetzlosen Küste zu folgen. Die Schatzsuche eines Piraten passt zu Schurken und Freibeutern.",["faction:Alliance"]="Als Abenteurer der Allianz ist die Bergung eines Vermögens von Westfalls wrackgesäumter Küste für Euch ein kleiner Sieg inmitten der Unruhen im Grenzland des Königreichs. Küstenmurlocs bedrohen das Ufer."},sec={{t="Das letzte Vermächtnis eines Seemanns",b="Käpt'n Sanders war ein alter Seefahrer, der vor Westfalls Westküste ein nasses Grab fand. Er hinterließ rätselhafte Anweisungen, damit sein hart erarbeitetes Vermögen nicht an das große Meer verloren ging oder Plünderern in die Hände fiel. Ihr könnt der Spur folgen, die er hinterließ. Schiffswracks und die rastlosen Geister ertrunkener Seeleute säumen die Westküste."},{t="Der rostige Anker",b="Ein einzelner rostiger Anker in der Brandung markiert den ersten Hinweis an Westfalls Westküste. Nahe einem Wrack liegt Käpt'n Sanders' alte Seemannskiste, halb im Sand vergraben und von den Wellen arg mitgenommen. Darin befinden sich Meerwasser, Sand und eine umherhuschende Krabbe, die das nächste Teil von Sanders' Rätsel umklammert."}},faq={{q="Wer war Käpt'n Sanders?",a="Käpt'n Sanders war ein alter Kapitän, der laut seiner Karte in einem nassen Grab liegt. Er hinterließ die Karte und eine Reihe von Hinweisen, die zu seiner versteckten Beute führen.",al={"käpt'n sanders hintergrundgeschichte","wer ist sanders","sanders vorgeschichte"}},{q="Wo befindet sich die Seemannskiste?",a="Die Seemannskiste liegt halb im Sand vergraben an Westfalls Westküste, nahe einem einzelnen rostigen Anker am Ufer.",al={"fundort der seemannskiste","wo ist der rostige anker","sanders seemannskiste finden"}},{q="Enthält die Seemannskiste den Schatz des Kapitäns?",a="Die Karte führt Euch zu einer Seemannskiste und zum nächsten Hinweis einer längeren Schatzsuche.",al={"ist der schatz in der truhe","was ist in der seemannskiste","wo ist das gold"}},{q="Wie viele Hinweise gibt es bei Käpt'n Sanders' Schatzsuche?",a="Die Suche umfasst vier Schritte entlang der Küste und durch das Hinterland von Westfall. Sie beginnt mit der Karte und endet bei Käpt'n Sanders' eigentlicher Schatztruhe auf einer Insel vor der Küste.",al={"wie lange dauert sanders quest","wie viele teile","sanders questreihe"}},{q="Warum vergrub Käpt'n Sanders seinen Schatz in Westfall?",a="Käpt'n Sanders' Karte verrät nicht, warum er Westfall wählte. Darauf steht, dass er mit einem nassen Grab rechnete und wollte, dass jemand seinen Hinweisen folgte und seinen Schatz fand. Die Hinweise sind entlang der Küste und auf den Klippen darüber verstreut.",al={"warum den schatz verstecken","warum westfalls küste"}},{q="Können Spieler der Horde dieser Schatzkarte folgen?",a="Ja. Käpt'n Sanders' Karte und Hinweise sind neutral, sodass jeder Abenteurer, der Westfalls Küste erreicht, seiner Spur folgen kann.",al={"kann die horde das machen","horde sanders quest","fraktionsneutraler schatz"}}},fx={["1a1a7b8a"]={q="Warum hat Kapitän Sanders diese Schatzkarte hinterlassen?",a="Kapitän Sanders wusste, dass ihm ein nasses Grab bevorstand, und er hatte nicht die Absicht, seine angehäuften Reichtümer vergessen auf dem Meeresgrund verrotten zu lassen. Er legte eine kryptische Spur aus Hinweisen für jeden aus, der die Gerissenheit und den Mut besaß, sein Pergament zu entdecken. Indem er ehrgeizige Reisende herausfordert, seine alte Kiste aufzuspüren, stellt er sicher, dass sein Name und sein Vermächtnis noch lange nach seinem Tod fortbestehen.",al={"warum sanders karte","sanders motiv schatzkarte","warum schatzkarte hinterlassen"}}},fp="32,203,23.321.0,16.274.1,24.149.0,32.122.0,51.78.1,53.168.0,54.220.0,43.117.0"}
P.entries["quest:1360"] = {n="Reclaimed Treasures",s="Krom Starkarm bittet Euch, einen wertvollen Besitz aus Uldaman zurückzuholen. Er wartet in Eisenschmiede darauf.",h="Krom Starkarm bittet Euch, einen wertvollen Besitz aus Uldaman zurückzuholen.",kw={"truhe","eisenschmiede","krom starkarm","north common hall","zurückgeholte schätze","wertvoller besitz","uldaman"},ang={["faction:Alliance"]="Als Mitglied der Allianz sollt Ihr Krom Starkarms wertvollen Besitz aus Uldaman zu ihm nach Eisenschmiede bringen.",["race:Dwarf"]="Als Zwerg helft Ihr Krom Starkarm, einen wertvollen Besitz zurückzuholen und zu ihm nach Eisenschmiede zu bringen."},sec={{t="Ein verlorener Besitz",b="Krom Starkarm hat eine Truhe in Uldamans North Common Hall. Ihr sollt seinen wertvollen Besitz daraus holen und zu ihm nach Eisenschmiede bringen."}},faq={{q="Wer bittet um Hilfe?",a="Krom Starkarm bittet Euch, seinen wertvollen Besitz aus einer Truhe in Uldaman zurückzuholen.",al={"wer möchte das","krom starkarm bitte"}},{q="Wo steht Kroms Truhe?",a="Krom Starkarms Truhe steht in Uldamans North Common Hall.",al={"wo truhe","standort der truhe"}},{q="Was möchte Krom zurückhaben?",a="Krom möchte seinen wertvollen Besitz aus der Truhe in Uldaman zurückhaben.",al={"kroms schatz","welcher besitz"}},{q="Wohin soll ich es bringen?",a="Bringt Krom Starkarms wertvollen Besitz zu ihm nach Eisenschmiede.",al={"wohin bringen","zu krom bringen"}}},fp="19,100,17.134.0,23.83.0,22.61.0,25.62.0,20.63.0"}
P.entries["quest:1361"] = {n="Regthar Totenfurt",s="Im Brachland ruft Regthar Totenfurt erfahrene Kämpfer der Horde nach Westen. Er sammelt Freiwillige für einen Feldzug über die Berge nach Desolace, wo Zentaurenklans das Grenzland terrorisieren.",h="Im Brachland ruft Regthar Totenfurt erfahrene Kämpfer der Horde nach Westen.",kw={"belgrom rockmaul","das wegekreuz","desolace","kolkar","krusk","nazgrel","regthar totenfurt","brachland","vol'jin"},ang={["class:Warrior"]="Als Krieger könnt Ihr Regthars Ruf mit Eurer Kampffertigkeit und Disziplin im feindseligen Ödland von Desolace folgen.",["faction:Horde"]="Die Horde will ihr Grenzland sichern, indem sie die Zentauren im benachbarten Desolace unterwirft, bevor sie tiefer ins Brachland vorstoßen können.",["race:Tauren"]="Als Tauren habt Ihr nach Generationen des Konflikts mit Zentauren im zentralen Kalimdor ein persönliches Interesse daran, Regthar beim Angriff auf die Kolkar zu helfen."},sec={{t="Ruf der Leutnants des Kriegshäuptlings",b="Die Anführer der Horde halten an ihren Grenzen nach Bedrohungen Ausschau. Im Brachland hat Regthar Totenfurt einen Verteidigungsposten errichtet, um die westlichen Pässe zu bewachen. Deshalb schicken Offiziere der Horde bewährte Kämpfer westlich vom Wegekreuz, um seinem Ruf zu folgen."},{t="Der Weg nach Desolace",b="Regthar Totenfurt wartet in einer befestigten Redoute entlang der Bergkämme westlich vom Wegekreuz. Von dort aus überwacht er die Bergpfade nach Desolace. Er sammelt eine Vorhut, um feindliches Gebiet zu durchqueren und die Kolkar sowie andere kriegführende Zentaurenklans anzugreifen, bevor ihre Ausbreitung das Gebiet der Horde bedroht."}},faq={{q="Wer ist Regthar Totenfurt?",a="Regthar Totenfurt ist ein orkischer Krieger und Kommandant der Horde, der im Brachland stationiert ist. Er leitet Spähtrupps und militärische Vorstöße nach Desolace.",al={"wer ist regthar","regthar totenfurt hintergrundgeschichte","wer ist der questgeber"}},{q="Wo befindet sich Regthar Totenfurt?",a="Regthar Totenfurt befindet sich im Brachland, in den Bunkern der Horde am Hügelpfad westlich vom Wegekreuz. Von dort aus überblickt er den westlichen Gebirgspass.",al={"wo ist regthar","regthar standort","regthar totenfurt finden"}},{q="Wer vergibt die Quest, Regthar aufzusuchen?",a="Schattenjäger Vol'jin, Nazgrel, Belgrom Rockmaul und Krusk fordern Euch auf, Regthar aufzusuchen. Vol'jin, Nazgrel und Belgrom Rockmaul sind in Orgrimmar; Krusk ist in Tarrens Mühle.",al={"wer startet regthar totenfurt","wo gibt es regthars quest"}},{q="Was ist das Hauptziel von Regthars Mission?",a="Regthar sammelt Krieger, um die Berge nach Desolace zu überqueren und die feindlichen Zentaurenklans anzugreifen, besonders die Kolkar.",al={"was will regthar","regthar totenfurt aufgabe"}},{q="Warum sorgt sich die Horde um Desolace?",a="Aggressive Zentaurenklans überrennen Desolace. Werden sie nicht aufgehalten, könnten ihre Raubzüge über die Berge bis ins Brachland und in nahe gelegene Siedlungen der Horde führen.",al={"warum nach desolace gehen","interesse der horde an desolace"}},{q="Was folgt nach dem Gespräch mit Regthar Totenfurt?",a="Wenn Ihr Euch bei Regthar meldet, unterrichtet er Euch über die Lande jenseits der westlichen Berge. Dann schickt er Euch über die Grenze zu Eurem ersten Angriff auf die Kolkar.",al={"nächste quest nach regthar","regthar folgequest"}}},fp="17,191,34.219.0,20.300.0,25.135.0,35.154.0,40.167.0,51.127.0,41.146.0,54.162.0"}
P.entries["quest:1362"] = {n="Die Kolkar von Desolace",s="Regthar Totenfurt schickt Champions der Horde westwärts nach Desolace, um Späher Felgur Zweischneid am Geistwandlerposten zu verstärken. Von ihrer dortigen Hochburg aus bedrohen die Kolkar die Gebiete der Horde.",h="Regthar Totenfurt schickt Champions der Horde westwärts nach Desolace, um Späher Felgur Zweischneid am...",kw={"zentauren","desolace","felgur zweischneid","geistwandlerposten","horde","kolkar","regthar deathgate","brachland"},ang={["faction:Horde"]="Für die Horde markiert dies den Übergang vom Schutz junger Siedlungen in Durotar und im Brachland zum Kampf in feindlichen Gebieten.",["race:Orc"]="Als Orc habt Ihr einen Stützpunkt im Osten Kalimdors gesichert. Die ungezähmten Zentaurenklans bedrohen weiterhin die Versorgungslinien der Horde.",["race:Tauren"]="Als Tauren wisst Ihr, dass die Angriffe der Zentauren Eure nomadischen Stämme vor Eurem Bündnis mit Thrall an den Rand der Auslöschung brachten. Sie in ihrer Heimat Desolace zu bekämpfen, fordert einen persönlichen Preis."},sec={{t="Eine Bedrohung jenseits der Berge",b="Zentaurenplünderer dringen immer weiter ins Brachland vor. Regthar Totenfurt weiß, dass die Kämpfe dort nicht enden werden, solange die Kolkar aus ihren angestammten Gebieten an Kalimdors Westküste Kraft schöpfen. Ihre Hochburg bleibt außerhalb der Kontrolle der Horde, und immer weitere Plünderer strömen durch die Gebirgspässe. Die Horde muss sie in ihrer Heimat angreifen."},{t="Geistwandlerposten",b="Der Geistwandlerposten bietet der Horde einen Stützpunkt tief in Desolace. Späher Felgur Zweischneid beobachtet vom Vorposten aus die rivalisierenden Zentaurenklans. Regthar schickt erfahrene Kämpfer aus dem Brachland, die unter Felgur dienen sollen. Von diesem Lager aus trägt die Horde ihren Feldzug nach Westen und geht von der Verteidigung zum direkten Angriff über."}},faq={{q="Wer schickt mich auf diese Mission?",a="Regthar Totenfurt, ein Orc-Krieger am Bunker westlich des Wegekreuzes im Brachland, schickt Euch, um den Kampf in die angestammten Gebiete der Kolkar zu tragen.",al={"questgeber","wer vergibt die quest","regthar"}},{q="Wo liegt der Geistwandlerposten?",a="Der Geistwandlerposten ist ein abgelegenes Lager der Horde an den zerklüfteten Wegen von Desolace, westlich des Gebirgskamms von Kalimdor.",al={"wo ist der geistwandlerposten","felgur zweischneid standort","lager in desolace"}},{q="Warum konzentriert sich die Horde auf Desolace?",a="Die Kolkar, die das Brachland überfallen, gehören zu den größeren Zentaurenklans, deren Wurzeln in Desolace liegen. Regthar weiß, dass Verteidigung allein die Einfälle nicht aufhalten kann, solange ihre Hochburg unversehrt bleibt.",al={"warum nach desolace","warum kolkar in desolace bekämpfen","verbindung zu den zentauren"}},{q="Wer ist Felgur Zweischneid?",a="Felgur Zweischneid ist ein Späher der Horde am Geistwandlerposten. Er beobachtet die rivalisierenden Zentaurenklans in Desolace und organisiert Angriffe gegen sie.",al={"felgur zweischneid","wer ist felgur"}},{q="Kommt es bei dieser Quest zu Kämpfen?",a="Nein. Ihr überbringt eine Nachricht aus dem Brachland nach Desolace, wo härtere Herausforderungen auf Abenteurer der Horde warten.",al={"kämpfe in der quest","kampfquest"}},{q="Gegen welchen Zentaurenklan richtet sich diese Quest?",a="Das Ziel ist der Kolkarklan. Seine Zentaurenplünderer stammen aus Desolace und sind ins Brachland und nach Durotar vorgedrungen.",al={"welche zentauren","welcher klan","kolkarklan"}}},fx={["4557df46"]={q="Warum benötigt Regthar Totenfurt Euch für eine Reise nach Desolace?",a="Regthar Totenfurt koordiniert die Verteidigung an der Front und die Aufklärung gegen die Kolkar im Brachland und hält die örtlichen Streitkräfte der Horde mit unmittelbaren Bedrohungen der Oasen auf Trab. Um an die Wurzel des Problems zu gelangen, benötigt er einen fähigen, mobilen Abenteurer, der sich über die Grenzen hinaus in die Einöde von Desolace wagt und direkt Kontakt mit dem Späher Felgur Zweischneid aufnimmt.",al={"warum ich nach desolace","warum braucht regthar mich","warum ich kolkar von desolace"}}},fp="22,175,29.328.0,17.289.0,29.150.0,35.111.0,38.179.0,22.136.0,31.104.0,42.115.0"}
P.entries["quest:1365"] = {n="Khan Dez'hepah",s="Nach The Kolkar of Desolace wendet sich Felgur Zweischneid gegen Khan Dez'hepah. Viele Zentaurenclans bekämpfen einander in ganz Desolace, und Felgur will die Kolkar schwächen, bevor sie sich vereinen.",h="Nach The Kolkar of Desolace wendet sich Felgur Zweischneid gegen Khan Dez'hepah.",kw={"zentauren","desolace","dez'hepah","felgur zweischneid","khan dez'hepah","kolkar"},sec={{t="Zerstrittene Clans",b="In ganz Desolace bekämpfen Zentaurenclans einander. Die Kolkar sind einer von vielen, durchstreifen die trockenen Ebenen und töten ihresgleichen. Felgur Zweischneid trauert ihren Verlusten nicht nach. Zentauren sind stark und brutal, und vereint wären sie ein gefährlicher Feind für die Horde. Felgur will die Kolkar schwächen, bevor es dazu kommen kann."},{t="Der Anführer der Kolkar",b="Felgur Zweischneid beginnt damit, die Kolkar in Aufruhr zu versetzen. Ihr Dorf liegt nordöstlich von Felgurs Standort. Felgur will, dass ihm Khan Dez'hepahs Kopf gebracht wird."}},faq={{q="Warum will Felgur Zweischneid Khan Dez'hepah tot sehen?",a="Felgur Zweischneid fürchtet, dass sich die Zentaurenclans gegen die Horde vereinen könnten. Felgur will zunächst die Kolkar in Aufruhr versetzen, indem er Khan Dez'hepah töten lässt.",al={"warum dezhepah töten","khan dezhepah zweck","grund für dezhepahs tötung"}},{q="Wo befindet sich Khan Dez'hepah?",a="Khan Dez'hepah befindet sich in Kolkar, nordöstlich von Felgur Zweischneid in Desolace.",al={"khan dezhepah standort","wo ist dezhepah","kolkar standort"}},{q="Was soll Felgur gebracht werden?",a="Felgur Zweischneid will, dass ihm Khan Dez'hepahs Kopf gebracht wird.",al={"khan dezhepah beweis","was felgur bringen"}},{q="Was kommt vor Khan Dez'hepah?",a="The Kolkar of Desolace kommt zuerst. Danach schickt Felgur Zweischneid Euch gegen den Anführer der Kolkar, Khan Dez'hepah.",al={"vorherige quest dezhepah","voraussetzung für khan dezhepah"}}},fp="14,172,13.308.0,17.149.0,49.135.0,32.81.0,35.56.0,33.114.0"}
P.entries["quest:1366"] = {n="Zentaurenkopfgeld",s="In Desolace verlangt Felgur Zweischneid nach Khan Dez'hepah Blut. Er will fünfzehn Ohren von Zentauren beliebiger Clans.",h="In Desolace verlangt Felgur Zweischneid nach Khan Dez'hepah Blut.",kw={"zentauren","zentaurenkopfgeld","zentaurenohren","desolace","felgur zweischneid","khan dez'hepah"},sec={{t="Zeit, sie bluten zu lassen",b="Felgur Zweischneid sagt, die Zentaurenclans seien verängstigt. Nun, sagt er, sei es Zeit, sie bluten zu lassen. Jagt auf Euren Reisen durch Desolace Zentauren beliebiger Clans und sammelt fünfzehn Ohren. Felgur will ihre Reihen lichten und ihre Entschlossenheit schwächen. Er will jeglichen Expansionsgedanken ein Ende setzen."},{t="Felgurs Urteil",b="Wenn Ihr zurückkehrt, sagt Felgur, die Zentauren müssten Euren Namen inzwischen kennen. Er glaubt, dass sie Euch respektieren und fürchten. Sie kennen auch das Banner, unter dem Ihr reitet: das der Horde."}},faq={{q="Wer setzt dieses Kopfgeld auf die Zentauren aus?",a="Felgur Zweischneid setzt das Kopfgeld in Desolace aus. Er will, dass Ihr ihm fünfzehn Zentaurenohren bringt.",al={"wer vergibt zentaurenkopfgeld","zentaurenkopfgeld questgeber"}},{q="Welche Zentaurenclans müssen gejagt werden?",a="Ihr könnt Zentauren beliebiger Clans jagen. Felgur verlangt nur, dass Ihr Ohren sammelt.",al={"welche zentauren töten","welcher clan für zentaurenkopfgeld"}},{q="Warum will Felgur so viele Zentaurenohren?",a="Felgur will die Zahl der Zentauren verringern. Er glaubt, dass weniger Zentauren ihre Entschlossenheit schwächen und jeglichen Expansionsgedanken ein Ende setzen werden.",al={"warum zentauren in desolace töten","grund für zentaurenkopfgeld"}},{q="Was ging diesem Kopfgeld voraus?",a="Das Kopfgeld folgt auf Khan Dez'hepah. Felgur sagt, die Zentaurenclans seien verängstigt, und nun sei es Zeit, sie bluten zu lassen.",al={"zentaurenkopfgeld voraussetzung","vorherige quest zentaurenkopfgeld"}}},fp="14,113,18.282.0,16.165.1,38.96.0,38.74.0,42.130.0,29.116.0"}
P.entries["quest:1367"] = {n="Allianz mit den Magram",s="In Desolace fordert Gurda Wildmane Euch auf, den Hass der Zentaurenklans gegen sie selbst zu wenden. Schließt Freundschaft mit einem Klan, um zu erfahren, wie alle besiegt werden können. Wenn Ihr Euch auf die Seite der Magram stellt, tötet die Gelkis und sprecht dann mit Warug am Rande von Magram im Südosten von Desolace.",h="In Desolace fordert Gurda Wildmane Euch auf, den Hass der Zentaurenklans gegen sie selbst zu wenden.",kw={"zentauren","desolace","gelkis","gurda wildmane","magram","warug"},sec={{t="Hass als Waffe",b="Gurda Wildmane fordert Euch auf, den Hass der Zentaurenklans gegen sie selbst zu wenden. Wählt einen Klan als Verbündeten und lernt von ihm, wie alle besiegt werden können. Wenn Ihr Euch auf die Seite der Magram stellt, verdient Ihr Euch ihren Respekt, indem Ihr ihre Feinde, die Gelkis, tötet."},{t="Der Sprecher",b="Warug, der Sprecher der Magram, wartet am Rande von Magram im Südosten von Desolace, sobald Ihr Euch genug Respekt verdient habt. Zuvor hat er Euch nichts zu sagen. Die Magram haben keine Worte für die Schwachen. Stattdessen töten sie sie. Um Eure Stärke zu beweisen, schickt Warug Euch gegen viele Gelkis in den Kampf."},{t="Warugs Urteil",b="Warug sagt, die Gelkis weinen beim Klang Eures Namens. Sie fürchten und hassen Euch ebenso wie die Magram. Vielleicht, räumt er ein, seid Ihr so stark wie die Magram. Er wird sich selbst ein Urteil bilden."}},faq={{q="Wer schlägt ein Bündnis mit den Magram vor?",a="Gurda Wildmane fordert Euch auf, den Hass der Zentaurenklans gegen sie selbst zu wenden. Stellt Euch auf die Seite eines Klans und lernt, wie alle besiegt werden können.",al={"wer vergibt allianz mit den magram","magram questgeber","gurda wildmane quest"}},{q="Wie verdient Ihr Euch den Respekt der Magram?",a="Tötet die Gelkis, die Feinde der Magram, um Euch deren Respekt zu verdienen.",al={"wie bei den magram freundlich werden","magram ruf","magram freundlich stimmen"}},{q="Wo ist Warug?",a="Warug, der Sprecher der Magram, wartet am Rande von Magram im Südosten von Desolace.",al={"wo ist warug","warug finden","warug standort"}},{q="Warum weigert sich Warug anfangs zu sprechen?",a="Warug sagt, die Magram haben keine Worte für die Schwachen und töten sie stattdessen. Beweist Eure Stärke, indem Ihr viele Gelkis tötet.",al={"warum spricht warug nicht","warug wütend","warug dialog"}}},fp="15,256,18.222.0,13.295.0,16.179.1,41.124.0,42.58.0,15.92.0,40.115.0"}
P.entries["quest:1368"] = {n="Allianz mit den Gelkis",s="Im Südwesten von Desolace nutzt Gurda Wildmane den Hass der Zentaurenclans, um sie zu besiegen. Schließt Freundschaft mit einem Clan, um zu erfahren, wie die anderen besiegt werden können. Die Gelkis verlangen, dass Ihr ihre verhassten Feinde, die Magram, tötet, bevor Ihr Uthek die Weise im Dorf der Gelkis trefft.",h="Im Südwesten von Desolace nutzt Gurda Wildmane den Hass der Zentaurenclans, um sie zu besiegen.",kw={"zentaur","desolace","gelkis","dorf der gelkis","gurda wildmane","magram","uthek die weise"},sec={{t="Hass als Waffe",b="Gurda Wildmane will den Hass der Zentaurenclans gegen sie selbst wenden. Schließt Freundschaft mit einem Clan, und was Ihr dabei lernt, könnte zeigen, wie sie alle zu besiegen sind. Wählt die Gelkis. Um ihren Respekt zu gewinnen, tötet die Magram, den Clan, den sie am meisten hassen."},{t="Der Schamane",b="Sobald die Gelkis Euch respektieren, trefft Uthek die Weise, ihren Schamanen, am Rande des Dorfes der Gelkis im Südwesten von Desolace. Bis dahin seid Ihr dort nicht willkommen. Uthek sagt, Ihr betretet die Erde der Gelkis. Beweist Eure Freundschaft, indem Ihr Magram-Zentauren tötet, und kehrt zurück, wenn ihr Blut den Boden getränkt hat."},{t="Utheks Wort",b="Uthek die Weise sagt, die Erde erzähle, wie viele Magram Ihr getötet habt. Er sagt, das sei gut. Als Freund der Gelkis könnt Ihr weitere Arbeit von Uthek annehmen."}},faq={{q="Wer schlägt ein Bündnis mit den Gelkis vor?",a="Gurda Wildmane schlägt vor, den Hass der Zentaurenclans gegen sie selbst zu wenden. Verbündet Euch mit einem Clan, und Ihr könnt erfahren, wie sie alle zu besiegen sind.",al={"wer vergibt allianz mit den gelkis","allianz mit den gelkis questgeber"}},{q="Wie gewinnt Ihr die Gunst der Gelkis?",a="Tötet die Magram, den Clan, den die Gelkis am meisten hassen, um ihre Gunst zu gewinnen.",al={"wie bei den gelkis freundlich werden","gelkis ruf"}},{q="Mit wem sprecht Ihr bei den Gelkis?",a="Sprecht mit Uthek der Weisen, einem Schamanen der Gelkis, am Rande des Dorfes der Gelkis im Südwesten von Desolace.",al={"wo ist uthek","uthek die weise aufenthaltsort"}},{q="Was verlangt Uthek, bevor er Euch willkommen heißt?",a="Uthek sagt, Ihr seid auf der Erde der Gelkis nicht willkommen, bis Ihr Eure Freundschaft beweist, indem Ihr Magram-Zentauren tötet.",al={"warum weist uthek mich ab","dorf der gelkis feindselig"}}},fp="15,262,18.223.0,10.299.0,12.155.1,41.133.0,40.68.0,37.99.0,45.105.0"}
P.entries["quest:1369"] = {n="Zerbrochene Tränen",s="Warug will, dass Ihr in der Höhle im Dorf der Gelkis die Kristalle zerbrecht, die sie die Tränen von Theradras nennen. Er verlangt drei Bruchstücke und behauptet, die Zentaurenmutter könne sie nicht beschützen.",h="Warug will, dass Ihr in der Höhle im Dorf der Gelkis die Kristalle zerbrecht, die sie die Tränen von...",kw={"zerbrochene tränen","zentauren","desolace","gelkis","magram","theradras","warug"},sec={{t="Kristalle in der Höhle",b="Warug verspottet die Gelkis, weil sie darauf vertrauen, dass Theradras, die Mutter der Zentauren, sie beschützt. Er sagt, niemand beschütze die Zentauren, während die Magram die Stärksten seien und keinen Schutz bräuchten. In einer Höhle im Dorf der Gelkis horten die Gelkis Kristalle, die als die Tränen von Theradras bekannt sind. Warug schickt Euch los, um sie zu zerschlagen und ihm drei Bruchstücke zu bringen. Er vertraut Euch diese Aufgabe nur an, wenn Ihr kein Feind der Magram seid."},{t="Warugs Prahlerei",b="Warug nimmt die zerbrochenen Kristalle erfreut entgegen. Er sagt, die Gelkis würden lernen, dass Theradras ihnen nicht helfen kann und keine ihrer Tränen fallen werden, wenn die Magram sie zermalmen. Die Magram werden herrschen, verkündet er. Ihr seid weise, Euch auf die Seite der Stärksten zu schlagen."}},faq={{q="Wer ist Warug?",a="Warug ist ein Zentaur der Magram in Magram in Desolace. Er bittet Euch, die Tränen von Theradras in der Höhle der Gelkis zu zerstören.",al={"warug","wer vergibt zerbrochene tränen","questgeber zerbrochene tränen"}},{q="Was sind die Tränen von Theradras?",a="Die Tränen von Theradras sind Kristalle, die die Gelkis in einer Höhle in ihrem Dorf horten.",al={"tränen von theradras","geschichte von zerbrochene tränen","kristalle der gelkis"}},{q="Warum will Warug die Tränen zerstören lassen?",a="Die Gelkis glauben, dass Theradras, die Zentaurenmutter, sie beschützt. Warug nennt sie töricht und sagt, die Magram bräuchten keinen Schutz. Er will den Gelkis zeigen, dass sie sich irren.",al={"warum die tränen zerstören","beweggrund der magram","warum kristalle zerbrechen"}},{q="Wo sind die Kristalle zu finden?",a="Die Kristalle befinden sich in einer Höhle im Dorf der Gelkis. Warug bittet Euch, ihm drei Bruchstücke zu bringen.",al={"wo sind zerbrochene tränen","lage der höhle der gelkis","wo sind die tränen"}}},fp="12,181,20.397.0,13.228.1,13.122.0,32.80.0,40.173.0,29.98.0"}
P.entries["quest:1370"] = {n="Diebstahl von Vorräten",s="In Desolace schickt Euch Uthek die Weise nach Osten, um die Vorräte der Magram zu holen. Die Gelkis glauben, dass Fleisch ihnen Stärke verleiht, während die Magram Vorräte für die Tage zwischen den Jagden aufbewahren.",h="In Desolace schickt Euch Uthek die Weise nach Osten, um die Vorräte der Magram zu holen.",kw={"zentaur","desolace","gelkis","magram","fleisch","vorräte","uthek"},sec={{t="Fleisch und Stärke",b="Uthek die Weise sagt, die Gelkis schöpften ihre Stärke aus Fleisch. Ein voller Bauch kämpft härter als ein leerer. Die Magram bewahren zusätzliche Vorräte für die Tage zwischen den Jagden auf. Daher werdet Ihr in ihr Dorf im Osten geschickt, um sechs Beutel grob getrocknetes Fleisch zu Uthek im Dorf der Gelkis zurückzubringen."}},faq={{q="Wer schickt Euch, diese Vorräte zu holen?",a="Uthek die Weise von den Gelkis entsendet Euch aus Desolace.",al={"questgeber","wer vergibt diebstahl von vorräten","uthek die weise"}},{q="Warum will Uthek, dass den Magram das Fleisch genommen wird?",a="Die Gelkis glauben, dass Fleisch ihnen Stärke verleiht. Uthek sagt, ihnen ihre Reserve zu nehmen würde die Magram schwächen, während sie zwischen den Jagden kämpfen.",al={"warum fleisch stehlen","nahrung der magram","grund für den fleischraub"}},{q="Wo werden die Vorräte der Magram aufbewahrt?",a="Die Magram bewahren ihre Vorräte in ihrem Dorf im Osten auf.",al={"wo liegt magram","wo sind die vorräte","standort der magram"}},{q="Wie viel Fleisch will Uthek?",a="Uthek die Weise will, dass Ihr ihr sechs Beutel grob getrocknetes Fleisch ins Dorf der Gelkis bringt.",al={"wie viel fleisch","was zu uthek bringen"}}},fp="17,175,17.285.0,37.53.0,42.132.0,35.60.0,30.90.0"}
P.entries["quest:1371"] = {n="Gizmo für Warug",s="In Magram will Warug nun eine neue Zielattrappe als Ersatz für den hölzernen Menschen, den er zerbrochen hat.",h="In Magram will Warug nun eine neue Zielattrappe als Ersatz für den hölzernen Menschen, den er zerbrochen hat.",kw={"zentaur","desolace","gnom","magram","zielattrappe","warug"},sec={{t="Der Karren des Gnoms",b="Warug erinnert sich an einen Gnom, der vor langer Zeit mit Pferden und einem Karren nach Desolace kam. Darin waren merkwürdige Dinge: Manche brannten in verschiedenen Farben, andere bewegten sich, obwohl sie nicht lebendig waren. Warug tötete den Gnom, doch zuvor brachte der Gnom ihn zum Lachen.\n\nWarug behielt sein Lieblingsstück aus dem Karren, einen hölzernen Menschen, der ihm zuwinkte. Er schlug darauf ein und zerbrach ihn. Nun will er eine hochentwickelte Zielattrappe als Ersatz und erwartet eine von jedem, der kein Feind der Magram ist."}},faq={{q="Wer ist Warug?",a="Warug ist ein Zentaur der Magram in Magram. Er erwartet, dass jene, mit denen er zu tun hat, in der Gunst der Magram bleiben.",al={"warug","wer vergibt gizmo für warug"}},{q="Was will Warug?",a="Warug will eine hochentwickelte Zielattrappe als Ersatz für den hölzernen Menschen aus dem Karren des Gnoms, den er zerbrochen hat.",al={"welchen gegenstand braucht warug","warug gizmo gegenstand"}},{q="Warum will Warug eine Zielattrappe?",a="Vor langer Zeit tötete Warug einen Gnom, der mit einem Karren voller seltsamer, lustiger Dinge nach Desolace kam. Der Gnom brachte ihn zum Lachen, und Warugs Lieblingsstück war ein hölzerner Mensch, der ihm zuwinkte. Warug schlug darauf ein und zerbrach ihn, also will er nun einen neuen.",al={"warum will warug eine zielattrappe","warug zielattrappe grund"}},{q="Was kommt davor in der Geschichte der Magram?",a="Broken Tears kommt davor in Euren Beziehungen zu den Magram.",al={"gizmo für warug questreihe","was kommt vor gizmo für warug"}}},fp="15,91,16.470.0,13.116.0,21.101.0,35.228.0,43.64.0"}
P.entries["quest:1373"] = {n="Ongeku",s="Uthek schickt Euch von Desolace aus los, um einen Splitter draenethyst zu finden. Die Erde hat ihr von dem roten Kristall zugeflüstert, und Ongeku besitzt einen Splitter in den Sümpfen des Elends.",h="Uthek schickt Euch von Desolace aus los, um einen Splitter draenethyst zu finden.",kw={"desolace","draenethyst","gelkis","lost one","magram","ongeku","sümpfe des elends","uthek die weise"},sec={{t="Ein Kristall aus der Ferne",b="Nach Stealing Supplies schickt Uthek die Weise Euch weit fort von Desolace, um einen roten Kristall namens draenethyst zu holen. Sie sagt, die Erde teile ihre Geheimnisse mit denen, die lauschen. Der Kristall ist erst kürzlich in dieses Land gelangt, aus einer Gegend mit fliegenden Bergen, die von Dämonen beherrscht wird.\n\nUthek sagt, ein Splitter werde die Magie stärken. Ongeku, der lost one, besitzt einen in den Sümpfen des Elends in den Östlichen Königreichen. Wenn Ihr zurückkehrt, wird Uthek nach einem Beweis suchen, dass die Gelkis Euch noch immer einen Freund nennen können."}},faq={{q="Wer ist Uthek die Weise?",a="Uthek die Weise ist eine Zentaurin der Gelkis im Dorf der Gelkis in Desolace. Uthek sagt, die Erde flüstere ihre Geheimnisse denen zu, die lauschen.",al={"uthek","gelkisälteste","zentaurenquestgeber"}},{q="Was ist draenethyst?",a="draenethyst ist ein roter Kristall, der laut Uthek erst kürzlich in dieses Land gelangt ist. Uthek sagt, er stamme aus einer Gegend mit fliegenden Bergen, die von Dämonen beherrscht wird.",al={"splitter draenethyst","roter kristall","was ist draenethyst"}},{q="Wer ist Ongeku?",a="Ongeku ist ein lost one, der einen Splitter draenethyst im Zentrum der Sümpfe des Elends in den Östlichen Königreichen besitzt.",al={"wo ist ongeku","ongekus standort","ongeku finden"}},{q="Warum will Uthek einen Splitter draenethyst?",a="Uthek sagt, ein Splitter draenethyst werde die Magie stärken.",al={"warum draenethyst holen","utheks magie"}},{q="Was kam davor?",a="Stealing Supplies kam davor. Uthek hat Euch diese Aufgabe zuvor gegeben.",al={"vorherige quest","voraussetzung"}}},fp="6,162,23.483.0,22.128.0,20.151.0,14.107.0,40.58.0,22.65.0"}
P.entries["quest:1374"] = {n="Khan Jehn",s="Im Dorf der Gelkis sagt Uthek die Weise, dass Khan Jehn fallen muss, da die Magram schwächer werden. Er bittet Euch, den Kopf des Khans zurückzubringen.",h="Im Dorf der Gelkis sagt Uthek die Weise, dass Khan Jehn fallen muss, da die Magram schwächer werden.",kw={"zentauren","desolace","gelkis","dorf der gelkis","kopf von jehn","khan jehn","magram","uthek die weise"},sec={{t="Der Khan der Magram",b="Im Dorf der Gelkis lauscht Uthek die Weise dem, was die Erde ihm sagt. Die Magram werden schwächer, und ihr Khan, Jehn, soll niedergestreckt werden. Uthek bittet Euch, den Kopf des Khans der Magram zurückzubringen. Er erwartet, dass Ihr als Freund der Gelkis zurückkehrt."}},faq={{q="Wer ist Khan Jehn?",a="Khan Jehn führt die Zentauren der Magram an.",al={"khan jehn","wer ist jehn","anführer der magram"}},{q="Warum will Uthek die Weise Khan Jehn tot sehen?",a="Uthek sagt, die Erde verrate ihr, dass die Magram schwächer werden. Deshalb glaubt sie, dass die Zeit gekommen ist, ihren Khan zu töten.",al={"warum jehn töten","utheks beweggründe","warum den khan der magram töten"}},{q="Was kam davor?",a="Dies folgt auf Ongeku.",al={"was kommt vor khan jehn","reihenfolge der questreihe","vorherige quest"}},{q="Wo ist Uthek die Weise?",a="Uthek die Weise ist im Dorf der Gelkis in Desolace.",al={"utheks standort","wo ist uthek"}}},fp="9,126,15.253.0,17.35.0,44.113.0,22.20.0,24.48.0"}
P.entries["quest:1375"] = {n="Khan Shaka",s="Warug von den Magram schickt Euch nun gegen Khan Shaka, den Khan der Gelkis. Bringt ihm Shakas Kopf, damit er ihn anstarren und seinen Feind auslachen kann.",h="Warug von den Magram schickt Euch nun gegen Khan Shaka, den Khan der Gelkis.",kw={"zentaur","desolace","gelkis","kopf von khan shaka","khan shaka","magram","warug"},sec={{t="Ein rivalisierender Khan",b="In Magram sagt Warug, dass Eure Hilfe ihn erfreut und den Magram gute Dienste geleistet hat. Nun will er, dass Khan Shaka, der Khan der Gelkis, getötet und sein Kopf zurückgebracht wird. Warug will ihn anstarren und seinen Feind auslachen. Er erwartet, dass Ihr mit den Magram auf gutem Fuße bleibt."}},faq={{q="Wer ist Khan Shaka?",a="Khan Shaka führt den Zentaurenklan der Gelkis in Desolace an. Warug von den Magram will seinen Kopf.",al={"khan shaka hintergrundgeschichte","wer ist shaka","shaka zentaur"}},{q="Warum will Warug Khan Shaka tot sehen?",a="Warug will Khan Shakas Kopf, damit er ihn anstarren und seinen Feind auslachen kann.",al={"warum shaka töten","warugs groll gegen shaka"}},{q="Wo ist Warug?",a="Warug ist in Magram in Desolace.",al={"khan shaka aufenthaltsort","wo ist warug"}},{q="Was ging dem voraus?",a="Nach Gizmo for Warug sagt Warug, dass er Euch mag, weil Ihr den Magram geholfen habt.",al={"khan shaka voraussetzungen","vorherige quest shaka"}}},fp="10,139,12.265.0,18.89.0,36.77.0,15.39.0,20.70.0"}
P.entries["quest:138"] = {n="Käpt'n Sanders' versteckter Schatz",s="An Westfalls Küste führt Euch Käpt'n Sanders' versteckter Schatz landeinwärts. Ihr verlasst die Küste und folgt der nächsten Markierung auf seiner verstreuten Spur.",h="An Westfalls Küste führt Euch Käpt'n Sanders' versteckter Schatz landeinwärts.",kw={"zerbrochenes fass","captain sanders","schornstein","pirat","sanders' schatz","schatzsuche","westfall"},ang={["class:Rogue"]="Als Schurke könnt Ihr mit Verstohlenheit und List Piratengeheimschriften entschlüsseln und verlassene Ruinen nach vergessener Beute durchsuchen.",["faction:Alliance"]="Als Reisender der Allianz könnt Ihr Sanders' Spur entlang Westfalls gesetzloser Küste und ungepflegter Straßen im Landesinneren folgen. Die örtliche Miliz kämpft gegen organisierte Gesetzlose."},sec={{t="Eine Rätselspur ins Landesinnere",b="Captain Sanders hinterließ Rätsel auf dem Land, statt ein einzelnes Versteck am Strand zu markieren. Die entschlüsselte Geheimschrift weist über felsige Klippen hinaus zu Westfalls Hauptstraßen."},{t="Ruinen am Straßenrand",b="Zwischen den Ruinen am Straßenrand markiert ein alter Schornstein die nächste Station. Ein weggeworfenes, verwittertes Fass in der Nähe birgt eine weitere Botschaft, und das verfallene Gehöft dient Sanders als Wegmarke für seine Spur."}},faq={{q="Wer war Captain Sanders?",a="Captain Sanders war ein Piratenkapitän, der entlang der Küsten Westfalls segelte. Er verstreute Hinweise und Rätsel in der ganzen Region für alle, die nach seinen verborgenen Reichtümern suchten.",al={"captain sanders hintergrund","wer ist sanders","sanders pirat"}},{q="Wohin führt Euch dieser Hinweis?",a="Der Hinweis führt Euch vom Meer im Westen nach Osten, die Klippen hinauf und zur Straße. Neben einem alten steinernen Schornstein in den Ruinen birgt ein zerbrochenes Fass das nächste Puzzleteil.",al={"wohin geht es","fundort des hinweises","standort des schornsteins"}},{q="Warum versteckte Sanders seinen Schatz in Teilen?",a="Sanders verteilte die Wegbeschreibung auf mehrere Rätsel, damit Rivalen und die Obrigkeit seine verborgenen Reichtümer nicht finden konnten. Nur beharrliche, einfallsreiche Suchende können der Spur bis zum letzten Versteck folgen.",al={"warum hinweise","warum die schnitzeljagd"}},{q="Ist es gefährlich, der Schatzsuche zu folgen?",a="Die Hinweise bestehen aus Pergament und alten Behältern, doch Westfalls Straßen und Felder bergen Gefahren. Umherstreifende Bestien, lauernde Gnolle und feindselige Mitglieder der Bruderschaft der Defias bedrohen Reisende nahe verlassener Gehöfte.",al={"ist es sicher","gefahren in westfall"}},{q="Bei welchen Ruinen ist das Fass versteckt?",a="Das Fass liegt neben dem bröckelnden steinernen Schornstein eines verfallenen Gebäudes nahe der Straße. Viele Gehöfte Westfalls wurden in den vergangenen Jahren der Unruhen verlassen oder zerstört.",al={"schornsteinruinen","welches gebäude"}},{q="Enthüllt diese Quest den Schatz selbst?",a="Nein. Dieser Schritt enthüllt einen weiteren Hinweis. Sanders legte mehrere Etappen in der ganzen Region an, die durchlaufen werden müssen, bevor jemand den eigentlichen Schatz finden kann.",al={"ist dies die letzte truhe","gibt es jetzt beute"}}},fp="32,143,25.169.0,20.186.0,24.159.0,30.174.0,44.198.0,41.216.0,45.177.0,43.126.0"}
P.entries["quest:1380"] = {n="Khan Hratha",s="Im Dorf der Gelkis schickt Euch Uthek die Weise gegen die Maraudine, nachdem Ihr gegen die Magram geholfen habt. Ihr Anführer, Khan Hratha, trägt ein Stück eines Schlüssels bei sich, das Uthek zurückgebracht haben möchte.",h="Im Dorf der Gelkis schickt Euch Uthek die Weise gegen die Maraudine, nachdem Ihr gegen die Magram geholfen...",kw={"zentauren","desolace","dorf der gelkis","khan hratha","maraudine","maraudine war horn","uthek die weise","das tal der speere"},sec={{t="Die Maraudine herausfordern",b="Die Gelkis brauchen Eure Hilfe gegen die Maraudine, erzählt Euch Uthek die Weise. Ihr War Horn steht auf einer hohen Klippe im Tal der Speere. Lasst es ertönen, und Khan Hratha wird dem Ruf folgen. Doch zuerst braucht Ihr ein Warhorn Mouthpiece. Nur vertrauenswürdige Zentauren der Maraudine tragen eines bei sich, und sie sind selten. Weitere Zentauren treffen ein, wenn das Horn ertönt. Hratha kommt als Letzter."},{t="Ein Stück eines Schlüssels",b="Khan Hratha besitzt ein Stück eines Schlüssels. Uthek möchte, dass Ihr es ins Dorf der Gelkis bringt."},{t="Bei Eurer Rückkehr",b="Bei Eurer Rückkehr frohlockt Uthek, dass Khan Hratha tot und die Maraudine dem Untergang geweiht sind. Er gelobt, dass sich die Gelkis an Euch erinnern werden, wenn sie über dieses Land herrschen. Die Geister der Erde, sagt er, werden Euren Namen für immer besingen."}},faq={{q="Wer schickt Euch in den Kampf gegen Khan Hratha?",a="Uthek die Weise schickt Euch vom Dorf der Gelkis aus in den Kampf gegen Khan Hratha, nachdem Ihr den Gelkis gegen die Magram geholfen habt.",al={"wer vergibt khan hratha","khan hratha questgeber","wo gibt es khan hratha"}},{q="Wie wird Khan Hratha zum Kampf hervorgelockt?",a="Lasst das Maraudine War Horn auf einer hohen Klippe im Tal der Speere ertönen. Zuerst folgen Zentauren dem Ruf, dann kommt Khan Hratha.",al={"khan hratha standort","wo ist khan hratha","khan hratha finden"}},{q="Wie blast Ihr das Maraudine War Horn?",a="Das Horn benötigt ein Warhorn Mouthpiece, das selten ist und nur von vertrauenswürdigen Zentauren der Maraudine getragen wird.",al={"warhorn mouthpiece","wie maraudine war horn benutzen","maraudine war horn blasen"}},{q="Was kommt davor?",a="Dies folgt auf Khan Jehn. Uthek erinnert Euch daran, dass Ihr den Gelkis gegen die Magram geholfen habt.",al={"khan hratha voraussetzungen","welche quest vor khan hratha","khan hratha questreihe"}},{q="Was besitzt Khan Hratha?",a="Khan Hratha besitzt ein Stück eines Schlüssels. Uthek bittet Euch, es ihr ins Dorf der Gelkis zu bringen.",al={"khan hratha gegenstand","maraudine schlüsselfragment","was lässt hratha fallen"}}},fp="11,182,25.340.0,16.82.0,14.206.1,35.119.0,40.116.0,39.88.0,23.88.0,27.88.0"}
P.entries["quest:1381"] = {n="Khan Hratha",s="In Desolace nimmt Warug nach dem Tod des Khans der Gelkis Khan Hratha ins Visier. Er schickt Euch gegen den Khan der Maraudine aus, damit Ihr mit dem Teil eines Schlüssels zurückkehrt, den dieser bei sich trägt.",h="In Desolace nimmt Warug nach dem Tod des Khans der Gelkis Khan Hratha ins Visier.",kw={"desolace","schlüsselfragment","khan hratha","magram","maraudine","das tal der speere","kriegshorn","warug"},sec={{t="Ein Horn auf der Anhöhe",b="Warug will Khan Hratha, den Khan der Maraudine, tot sehen. Ein Horn auf einer Anhöhe im Tal der Speere lockt ihn hervor, doch zuerst braucht Ihr dessen Mundstück von einem Zentauren der Maraudine. Blast das Horn, und Zentauren der Maraudine versammeln sich am Turm. Nach ihnen erscheint Hratha."},{t="Ein Teil eines Schlüssels",b="Khan Hratha trägt einen Teil eines Schlüssels bei sich, und Warug will, dass Ihr ihn zu ihm nach Magram bringt. Er erwartet, dass Ihr Euch als Verbündete der Magram beweist."},{t="Herren der Zentauren",b="Nach Khan Hrathas Tod erklärt Warug die Magram zu den mächtigsten Zentauren. Er sagt, sie seien dazu bestimmt, ihre Rivalen zu zerschmettern und Desolace zu beherrschen. Warug verspricht, dass man sich an Euch erinnern und Euch verschonen wird, wenn die Übrigen niedergetrampelt werden."}},faq={{q="Wer schickt Euch los, um Khan Hratha zu besiegen?",a="Warug schickt Euch nach dem Tod des Khans der Gelkis von Magram in Desolace aus los.",al={"wer vergibt khan hratha","khan hratha questgeber"}},{q="Wie erreicht Ihr Khan Hratha?",a="Um Hratha gegenüberzutreten, blast das Horn auf der Anhöhe im Tal der Speere. Nehmt zuerst einem Zentauren der Maraudine dessen Mundstück ab. Die Zentauren versammeln sich am Turm, und nach ihnen erscheint Hratha.",al={"wie hratha beschwören","khan hratha finden","horn im tal der speere blasen"}},{q="Wo erscheint Khan Hratha?",a="Hratha erscheint am Turm im Tal der Speere, nachdem das Horn ertönt ist und sich die Zentauren der Maraudine dort versammelt haben.",al={"khan hratha fundort","wo ist hratha"}},{q="Was trägt Khan Hratha bei sich?",a="Hratha trägt einen Teil eines Schlüssels bei sich, den Ihr Warug auf dessen Bitte hin bringen sollt.",al={"was lässt hratha fallen","maraudine schlüsselfragment"}}},fp="11,167,19.256.0,16.148.0,22.222.1,36.78.0,29.185.0,30.113.0,27.67.0"}
P.entries["quest:1382"] = {n="Seltsame Allianz",s="Captain Pentigast strebt ein Bündnis mit den Gelkis in Desolace an. Sie liegen mit den Magram im Krieg, und er schickt Euch nach Südwesten zu Uthek der Weisen.",h="Captain Pentigast strebt ein Bündnis mit den Gelkis in Desolace an.",kw={"zentauren","desolace","gelkis","magram","pentigast","seltsame allianz","uthek"},sec={{t="Gespaltene Klans",b="Captain Pentigast sieht in den Streitigkeiten der Zentaurenklans eine Chance. Vereint wären sie nicht aufzuhalten. Er hofft, dass ihre Spaltung der Allianz dienen wird. Die Gelkis und die Magram führen einen brutalen Krieg, sodass Angriffe auf die Magram die Gelkis zum Beitritt zur Allianz bewegen könnten."},{t="Die Suche nach Uthek",b="Uthek die Weise befindet sich dort, wo die Lager der Gelkis im Südwesten von Desolace beginnen. Pentigast hofft, dass sie helfen kann, ein Bündnis zu sichern. Zunächst schickt sie Euch fort. Sie fordert Euch auf, erst zurückzukehren, nachdem Ihr viele Magram getötet habt."},{t="Utheks Antwort",b="Uthek die Weise erzählt Euch, dass die Gelkis nun Euren Namen flüstern, nachdem Ihr viele Magram getötet habt. Sie heißt dies gut und ist bereit, darüber zu sprechen, was Ihr dem Klan bieten könnt und was er Euch bieten kann."}},faq={{q="Wer schickt Euch, um Kontakt mit den Gelkis aufzunehmen?",a="Captain Pentigast schickt Euch, um Kontakt mit den Gelkis aufzunehmen, in der Hoffnung, ein Bündnis mit dem Klan zu schließen.",al={"wer vergibt seltsame allianz","seltsame allianz questgeber","wer startet seltsame allianz"}},{q="Wo befindet sich Uthek die Weise?",a="Im Südwesten von Desolace, am Rand der Lager der Gelkis.",al={"uthek standort","uthek die weise finden","wo ist uthek"}},{q="Warum spricht Uthek die Weise nicht sofort mit Neuankömmlingen?",a="Uthek die Weise fordert Euch auf, fortzugehen und erst zurückzukehren, nachdem Ihr viele Magram getötet habt.",al={"warum ist uthek feindselig","uthek spricht nicht","wie mit uthek sprechen"}},{q="Warum will die Allianz einen Pakt mit den Gelkis schließen?",a="Captain Pentigast sieht in den Streitigkeiten der Zentaurenklans eine Chance, da sie vereint nicht aufzuhalten wären. Die Gelkis liegen mit den Magram im Krieg, und Angriffe auf die Magram könnten die Freundschaft der Gelkis gewinnen.",al={"warum ein bündnis mit den gelkis","allianz zentauren grund","warum der gelkis-klan"}}},fp="16,143,13.282.0,13.202.0,14.187.1,36.92.0,32.67.0,57.71.0,50.210.0"}
P.entries["quest:1384"] = {n="Überfall auf die Kolkar",s="In Desolace schickt Uthek die Weise Euch nach Nordosten gegen die Zentauren der Kolkar. Nach Strange Alliance will er zehn ihrer Talismane zurückgebracht haben.",h="In Desolace schickt Uthek die Weise Euch nach Nordosten gegen die Zentauren der Kolkar.",kw={"zentaur","crude charms","desolace","gelkis","kolkar","uthek"},sec={{t="Verachtung für die Magie der Kolkar",b="Uthek verachtet die Zentauren der Kolkar, weil sie auf ihre Magie vertrauen. Seiner Ansicht nach verstehen sie nichts von solchen Dingen. Also zieht Ihr nach Nordosten, tötet Kolkar und nehmt ihre Talismane. Uthek will zehn Crude Charms ins Feuer werfen und lachen, während sie verbrennen."},{t="Utheks Urteil",b="Uthek nennt Eure Tat gut für die Gelkis. Er sagt, die Kolkar seien schwach und dem Untergang geweiht, und ihre Magie könne sie nicht retten. Sie haben Euer Werk gesehen und werden die Gelkis umso mehr fürchten. Furcht schwächt sie, und in den Ländern der Gelkis sterben die Schwachen bald."}},faq={{q="Wer ist Uthek die Weise?",a="Uthek die Weise wartet im Dorf der Gelkis in Desolace und will die Talismane der Kolkar.",al={"wer vergibt überfall auf die kolkar","uthek","geschichte von uthek der weisen"}},{q="Wo befinden sich die Kolkar?",a="Uthek sagt, die Kolkar seien im Nordosten.",al={"wo kolkar finden","kolkar fundort desolace"}},{q="Was sind die Crude Charms?",a="Crude Charms werden den Kolkar abgenommen. Uthek will zehn davon ins Feuer geworfen haben, damit sie lachen kann, während sie verbrennen.",al={"crude charm","talismane der kolkar"}},{q="Wie passt das in die Questreihe der Gelkis?",a="Überfall auf die Kolkar folgt auf Strange Alliance.",al={"questreihe der gelkis","was kommt vor überfall auf die kolkar"}}},fp="18,143,25.237.0,15.243.1,22.81.0,29.36.0,26.105.0,40.44.0"}
P.entries["quest:1385"] = {n="Brutale Politik",s="Captain Pentigast fürchtet, dass der siegreiche Zentaurenclan von Desolace die Festungen der Allianz bedrohen wird. Er sucht die Freundschaft eines Clans, damit die Allianz lernen kann, wie sie die Zentauren besiegt.",h="Captain Pentigast fürchtet, dass der siegreiche Zentaurenclan von Desolace die Festungen der Allianz bedrohen...",kw={"brutale politik","zentaur","desolace","gelkis","magram","pentigast","warug"},sec={{t="Ein Land im Krieg",b="Zentaurenclans führen in ganz Desolace Krieg. Captain Pentigast fürchtet, dass sich der Sieger gegen die Festungen der Allianz wenden wird, und sucht deshalb einen Weg, diese Gefahr abzuwenden. Die Allianz braucht einen Zentaurenclan als Freund, um zu lernen, wie sie die anderen besiegen kann."},{t="Die Magram",b="Die Magram bekämpfen die Gelkis, daher könnten Angriffe auf die Gelkis Euch die Gunst der Magram einbringen. Verdient Euch diese Gunst und sucht dann Warug in Magram im Südosten von Desolace auf. Warug sagt, dass Ihr durch das Töten von Gelkis zu Freunden der Magram werdet."}},faq={{q="Warum will die Allianz ein Bündnis mit einem Zentaurenclan?",a="Captain Pentigast fürchtet, dass der siegreiche Zentaurenclan die Festungen der Allianz bedrohen wird. Die Allianz braucht einen Clan als Freund, damit sie lernen kann, wie sie die Zentauren besiegt.",al={"warum ein bündnis mit den magram","pentigasts plan","grund für ein bündnis mit zentauren"}},{q="Wie gewinnt Ihr die Gunst der Magram?",a="Die Magram bekämpfen die Gelkis, daher könnten Angriffe auf die Gelkis sie dazu bewegen, ein Bündnis in Betracht zu ziehen. Warug sagt, dass Ihr durch das Töten von Gelkis zu Freunden der Magram werdet.",al={"wie ruf bei den magram erhalten","magram freundlich","gelkis töten"}},{q="Wo ist Warug?",a="Warug ist in Magram im Südosten von Desolace.",al={"warugs aufenthaltsort","wo ist warug","kontakt zu den magram"}}},fp="15,181,13.237.0,10.231.0,59.169.0,40.163.0,15.56.0"}
P.entries["quest:1386"] = {n="Angriff auf die Kolkar",s="In Magram will Warug, dass Ihr beweist, dass Ihr Kolkar so töten könnt, wie die Magram es tun. Nach Brutal Politics zieht Ihr nach Norden, um Euch Kolkarzentauren, Spähern und Schlägern zu stellen.",h="In Magram will Warug, dass Ihr beweist, dass Ihr Kolkar so töten könnt, wie die Magram es tun.",kw={"brutal politics","zentaur","desolace","kolkar","magram","warug"},sec={{t="Wir lachen und wir töten",b="Warug verspottet die Kolkar und ihren Glauben, stark zu sein. Die Magram lachen, während sie sie töten, und Warug will, dass Ihr beweist, dass Ihr dasselbe tun könnt. Zieht nach Norden und erschlagt zwölf Kolkarzentauren, zwölf Späher und sechs Schläger."},{t="Warugs Anerkennung",b="Als Ihr zurückkehrt, sagt Warug, dass die Kolkar Euch nun fürchten. Er hofft, dass Ihr gelacht habt, als Ihr sie getötet habt, damit der Feind seine eigene Schwäche erkennen konnte."}},faq={{q="Wer schickt Euch gegen die Kolkar?",a="Warug von den Magram schickt Euch von Magram in Desolace aus los.",al={"wer vergibt angriff auf die kolkar","questgeber angriff auf die kolkar","wo angriff auf die kolkar annehmen"}},{q="Was kam vor diesem Schritt?",a="Dies folgt auf Brutal Politics.",al={"vorherige quest","voraussetzung für angriff auf die kolkar","angriff auf die kolkar voraussetzung"}},{q="Wo befinden sich die Kolkar?",a="Warug sagt Euch, dass Ihr nach Norden ziehen sollt, um die Kolkar zu finden.",al={"kolkar standort","wo sind kolkarzentauren","wo kolkar finden"}},{q="Warum will Warug die Kolkar töten lassen?",a="Warug verspottet die Kolkar, weil sie sich für stark halten. Er will, dass Ihr zeigt, dass Ihr sie so töten könnt, wie die Magram es tun.",al={"warum kolkar töten","magram kolkar rivalität","warum hasst warug die kolkar"}}},fp="21,164,20.222.0,16.134.1,35.62.0,27.29.0,29.49.0,38.111.0"}
P.entries["quest:1387"] = {n="Zentaurenkopfgeld",s="An der Nijelspitze schickt Corporal Melkins Euch auf die Jagd nach Desolaces Zentaurenklans. Er verlangt fünfzehn Ohren, da er glaubt, dass kein Frieden einkehren kann, solange sie bleiben.",h="An der Nijelspitze schickt Corporal Melkins Euch auf die Jagd nach Desolaces Zentaurenklans.",kw={"allianz","kopfgeld","zentauren","zentaurenohr","corporal melkins","desolace","ohren","die nijelspitze"},sec={{t="Eine Gemeinsamkeit",b="An der Nijelspitze spricht Corporal Melkins von Desolaces Zentaurenklans. Jeder hat seinen eigenen Anführer und eigene Pläne. Doch alle teilen dieselbe Grausamkeit. Melkins sagt, Frieden könne erst einkehren, wenn die Zentauren verschwunden sind."},{t="Ohren für die Allianz",b="Während Ihr durch Desolace streift, jagt Ihr Zentauren und nehmt ihre Ohren. Melkins bittet Euch, fünfzehn zu bringen. Er nennt dies einen Dienst an der Allianz, der das Ende des Krieges näherbringt."}},faq={{q="Wer setzt das Kopfgeld auf die Zentauren aus?",a="Corporal Melkins setzt das Kopfgeld von der Nijelspitze in Desolace aus.",al={"zentaurenkopfgeld questgeber","wer vergibt zentaurenkopfgeld","melkins kopfgeld"}},{q="Warum will Corporal Melkins die Zentauren töten lassen?",a="Melkins sagt, die Klans unterscheiden sich in ihren Anführern und Zielen, doch alle sind grausam. Er glaubt, Frieden sei unmöglich, solange die Zentauren bleiben.",al={"warum zentauren töten","melkins beweggrund","warum zentaurenohren"}},{q="Was sollt Ihr Corporal Melkins bringen?",a="Melkins bittet Euch, fünfzehn Zentaurenohren zu bringen, die Ihr auf Euren Streifzügen durch Desolace den gejagten Zentauren abnehmt.",al={"was sammeln","zentaurenkopfgeld gegenstände","zentaurenkopfgeld trophäe"}},{q="Welche Zentaurenklans müssen gejagt werden?",a="Melkins nennt keinen einzelnen Klan. Er sagt, alle Klans teilen dieselbe Grausamkeit, und bittet Euch, Zentauren in Desolace zu jagen.",al={"welche zentauren","welchen zentaurenklan jagen","welcher klan für ohren"}}},fp="14,149,19.197.0,21.166.0,37.66.0,50.133.0,44.99.0,38.107.0"}
P.entries["quest:1389"] = {n="Draenethystkristalle",s="Im Sicheren Hafen bittet Magtoor Euch, sechs Draenethystkristalle zurückzuholen, die aus der Zuflucht der Verirrten gestohlen wurden. Die Kristalle sind seinem Volk heilig und mit seiner Furcht verbunden, vom Weg abzukommen.",h="Im Sicheren Hafen bittet Magtoor Euch, sechs Draenethystkristalle zurückzuholen, die aus der Zuflucht der...",kw={"draenethyst","zuflucht der verirrten","der sichere hafen","verirrte","magtoor","sümpfe des elends"},sec={{t="Die Verirrten",b="Die Verirrten der Zuflucht der Verirrten ähneln Magtoors Volk. Die Reise nach Azeroth trieb sie in den Wahnsinn. Einst waren sie Brüder, doch nun hausen sie in der Zuflucht im Osten und nehmen jeden gefangen oder töten jeden, der sich zu nah heranwagt. Sie haben außerdem Draenethystkristalle gestohlen, die Magtoors Volk heilig sind."},{t="Ohne die Kristalle",b="Magtoors Volk fehlt die Kraft, die Zuflucht der Verirrten zu betreten und den Draenethyst zwischen den Hütten und Lagerfeuern zurückzuholen. Ohne die Kristalle fürchten sie, dass auch sie vom Weg abkommen könnten. Darum bittet Magtoor Euch, sechs davon zurückzubringen."}},faq={{q="Wer bittet um die Draenethystkristalle?",a="Magtoor bittet im Sicheren Hafen um die Kristalle.",al={"wer gibt draenethystkristalle","magtoor quest","wer will draenethyst"}},{q="Warum sind die Draenethystkristalle für Magtoor wichtig?",a="Die Draenethystkristalle sind Magtoors Volk heilig. Ohne sie fürchtet Magtoor, dass auch sie vom Weg abkommen könnten.",al={"warum draenethystkristalle","was bewirken draenethystkristalle","draenethyst zweck"}},{q="Wer hat die Kristalle gestohlen?",a="Die Verirrten der Zuflucht der Verirrten haben die Kristalle genommen. Sie waren einst Magtoors Brüder, bis die Strapazen der Reise nach Azeroth sie in den Wahnsinn trieben.",al={"wer hat draenethyst gestohlen","wer hat die kristalle","zuflucht der verirrten feinde"}},{q="Wo sind die Kristalle zu finden?",a="Ihr könnt die Kristalle zwischen den Hütten und Lagerfeuern der Zuflucht der Verirrten im Osten finden.",al={"draenethystkristall fundort","wo sind draenethystkristalle","draenethyst finden"}},{q="Warum kann Magtoors Volk sie nicht selbst zurückholen?",a="Magtoors Volk fehlt die Kraft, die Zuflucht zu betreten und die Kristalle zurückzuholen.",al={"warum kämpft magtoor nicht","warum magtoor helfen"}}},fp="20,184,13.285.0,20.222.0,43.49.0,54.113.0,22.150.0,32.92.0,52.85.0"}
P.entries["quest:139"] = {n="Käpt'n Sanders' versteckter Schatz",s="Ein zerbrochenes Fass an Westfalls Westküste eröffnet die Spur zu Käpt'n Sanders' verstecktem Schatz. Sein Hinweis führt nach Norden zu einem alten Krug neben einer Küstenwindmühle, einen Schritt näher an die Reichtümer des verstorbenen Piraten.",h="Ein zerbrochenes Fass an Westfalls Westküste eröffnet die Spur zu Käpt'n Sanders' verstecktem Schatz.",kw={"klippen","zerbrochenes fass","käpt'n sanders","versteckter schatz","alter krug","piratenhinweis","westfall","windmühle"},ang={["class:Rogue"]="Als Schurke mag Euch die Spur eines Halunken aus verborgenen Nachrichten und versteckten Markierungen entlang der Klippen vertraut vorkommen.",["faction:Alliance"]="Während Westfall von Hungersnot und gesetzlosen Defias heimgesucht wird, bietet Euch Sanders' verschollene Piratenbeute einen willkommenen Geldsegen."},sec={{t="Die Spur eines Piraten",b="Käpt'n Sanders hinterließ Hinweise, die jeweils nur zum nächsten Versteck führen. Kein einzelnes Pergament zeigt, wo seine Beute liegt, also bleibt die Spur ein Rätsel, bis Ihr jede Nachricht gefunden habt."},{t="Nach Norden zu den Klippen",b="Das Pergament schickt Euch vom Fass genau nach Norden zu den Meeresklippen. Eine einsame Windmühle steht auf den Klippen, und in einem verlassenen Krug daneben liegt ein weiterer Hinweis. Murlocs und Defias-Plünderer streifen an der Küste umher und machen den Weg gefährlich."}},faq={{q="Was ist Käpt'n Sanders' versteckter Schatz?",a="Käpt'n Sanders war ein Freibeuter, der seine Reichtümer entlang der Küste von Westfall versteckte. Statt einer Karte hinterließ er schriftliche Rätsel in Fässern, Truhen und Krügen, die über das Land verstreut waren.",al={"sanders schatz","was ist das für eine quest","wer ist sanders"}},{q="Wohin führt dieser dritte Hinweis?",a="Das Pergament weist vom zerbrochenen Fass genau nach Norden zu den Meeresklippen. Nahe einer einsamen Windmühle birgt ein alter Krug den nächsten Hinweis.",al={"wohin geht es","standort des krugs","wo ist die windmühle"}},{q="Warum versteckte Sanders seine Wegbeschreibung in Teilen?",a="Sanders teilte seine Wegbeschreibung auf, um seinen Schatz vor meuternden Besatzungsmitgliedern und rivalisierenden Plünderern zu schützen. Ein einzelner Hinweis würde nicht den gesamten Weg verraten.",al={"warum hinweise","warum keine vollständige karte"}},{q="Können Spieler der Horde dieser Spur bis zum Ende folgen?",a="Ja. Jeder Abenteurer kann Käpt'n Sanders' Hinweisen folgen und die Gegenstände benutzen, die zu seinem Versteck gehören, obwohl Westfall tief im Gebiet der Allianz liegt.",al={"nur für die allianz","horde sanders schatz"}},{q="Verrät dieser Hinweis direkt den Standort der Truhe?",a="Nein. Der Krug nahe der Küstenwindmühle birgt einen weiteren Hinweis, der zu Sanders' Truhe führt. Dies ist der vorletzte Schritt der Schatzsuche.",al={"ist der schatz im krug","letzter schritt"}},{q="Welche Gefahren lauern auf dem Weg zur Windmühle?",a="Riverpaw-Gnolle, Küstenmurlocs und umherziehende Defias-Banditen durchstreifen Westfalls westliche Klippen und Strände. Ein gerader Marsch nach Norden kann tückisch sein.",al={"gefahren auf den klippen","welche gegner gibt es dort"}}},fx={["03354d32"]={q="Warum ist der Hinweis in einem zerbrochenen Fass versteckt?",a="Das Fass selbst hat keinen eigenen Willen und keine persönlichen Interessen – es ist lediglich ein unbelesener Ablagepunkt, der entlang der Küste von Westfall hinterlassen wurde. Kapitän Sanders versteckte seine Rätsel absichtlich in unscheinbarem Treibgut und zurückgelassenem Schrott, um zu verhindern, dass Gelegenheitsplünderer und konkurrierende Schurken den vollständigen Weg zu seiner Truhe zusammensetzen können.",al={"warum zerbrochenes fass","warum ist die notiz in einem fass","sanders zerbrochenes fass"}}},fp="32,198,27.177.0,23.231.0,41.171.0,32.128.0,46.146.0,38.144.0,41.126.0,48.147.0"}
P.entries["quest:1392"] = {n="Noboru der Knüppel",s="Im Sicheren Hafen leiden die Draenei seit Monaten unter Noboru dem Knüppel. Ihr tragt seinen Knüppel zu ihrem Anführer, ein Zeichen der Grausamkeit, die die Verirrten ihnen angetan haben.",h="Im Sicheren Hafen leiden die Draenei seit Monaten unter Noboru dem Knüppel.",kw={"knüppel","draenei","der sichere hafen","verirrte","magtoor","noboru","sümpfe des elends"},sec={{t="Ein Zeichen der Brutalität",b="Seit Monaten quält Noboru die Draenei, die im Sicheren Hafen leben. Sein Knüppel erinnert an die Grausamkeit, die die Verirrten ihnen angetan haben. Ihr tragt ihn zu ihrem Anführer."},{t="Magtoors Empfang",b="Magtoor fragt, ob die Waffe bedeutet, dass Noboru tot ist. Er nennt es einen Tag der Freude für den Sicheren Hafen. Noboru und seine Bande terrorisierten die Draenei, während sie durch die Sümpfe streiften, und töteten jeden, der ihren Weg kreuzte. Noboru bedrohte ihr bloßes Überleben, und ihnen fehlte die Kraft, sich ihm zu stellen."}},faq={{q="Wer ist Noboru?",a="Noboru ist einer der Verirrten und quält die Draenei des Sicheren Hafens seit Monaten.",al={"wer ist noboru","noborus geschichte","noboru kerl mit knüppel"}},{q="Warum will der Sichere Hafen Noborus Knüppel haben?",a="Der Knüppel erinnert an die Grausamkeit, die die Verirrten den Draenei des Sicheren Hafens angetan haben.",al={"warum den knüppel abgeben","noborus knüppel zweck","warum den knüppel zu magtoor bringen"}},{q="Wer erhält den Knüppel?",a="Magtoor, der Anführer des Sicheren Hafens, erhält den Knüppel.",al={"wer ist magtoor","wohin kommt der knüppel"}},{q="Wo liegt der Sichere Hafen?",a="Der Sichere Hafen liegt in den Sümpfen des Elends, wo seine Draenei leben.",al={"wo ist der sichere hafen","sicherer hafen lage"}}},fp="17,176,21.163.0,17.289.1,14.86.0,44.85.0,24.58.0,31.65.0"}
P.entries["quest:1393"] = {n="Galens Flucht",s="In der Zuflucht der Verirrten ruft Galen Goodward um Hilfe, während Kreaturen ihn umringen. Er bietet einen großen Schatz aus seinem Lager nördlich von Steinard an.",h="In der Zuflucht der Verirrten ruft Galen Goodward um Hilfe, während Kreaturen ihn umringen.",kw={"schwarzes harz","zuflucht der verirrten","galen goodward","galens flucht","steinard","geldkassette","sümpfe des elends"},sec={{t="Ein Flehen um Rettung",b="Galen Goodward ruft aus der Zuflucht der Verirrten, voller Angst, dass die Kreaturen um ihn herum ihn fressen werden. Er verspricht jedem, der ihn herausholt, einen großen Schatz. Er liegt in einer Geldkassette in seinem Lager im Sumpf nördlich von Steinard. Nur Galen kennt den Trick, um sie zu öffnen, und er wird ihn jedem beibringen, der ihn rettet."},{t="An der Geldkassette",b="In Galens Lager verstopft schwarzes Harz das Schlüsselloch der Geldkassette. Galen hat Euch von einem Riegel erzählt, der unter der Kassette verborgen ist. Nach kurzer Suche findet Ihr ihn, und als Ihr ihn umlegt, öffnet sich die Geldkassette."}},faq={{q="Wer ist Galen Goodward?",a="Galen Goodward wird in der Zuflucht der Verirrten festgehalten, wo er fürchtet, dass die Kreaturen ihn fressen werden. Er bietet jedem, der ihm bei der Flucht hilft, einen großen Schatz an.",al={"wer ist galen","galen goodward geschichte","typ aus galens flucht"}},{q="Wo liegt Galens Lager?",a="Galens Lager liegt im Sumpf nördlich von Steinard, in den Sümpfen des Elends.",al={"wo ist galens lager","galens geldkassette fundort","wo ist die geldkassette"}},{q="Warum lässt sich die Geldkassette nicht auf die übliche Weise öffnen?",a="Schwarzes Harz verstopft das Schlüsselloch der Geldkassette, und Galen kennt einen verborgenen Riegel unter ihr. Er verspricht jedem, der ihm bei der Flucht hilft, den Trick beizubringen.",al={"wie geldkassette öffnen","galen truhe schlüssel"}}},fp="14,144,17.304.0,16.180.1,22.149.0,30.73.0,51.149.0"}
P.entries["quest:1394"] = {n="Letzte Überfahrt",s="Ihr habt Parqual Fintallas' Prüfung und alle davor bestanden. Nun schickt er Euch zu Dorn Ebenenpirscher in Tausend Nadeln, der beurteilen wird, ob Ihr an Geist, Körper und Seele stark genug geworden seid, um Ehre zu verdienen.",h="Ihr habt Parqual Fintallas' Prüfung und alle davor bestanden.",kw={"dorn ebenenpirscher","letzte überfahrt","freiwindposten","parqual fintallas","test of faith","test of lore","tausend nadeln","der wetterwinkel"},ang={["faction:Horde"]="Als Mitglied der Horde stellt Ihr Euch dieser Prüfungsreihe, die bei Dorn Ebenenpirscher endet."},sec={{t="Zurück zum Wetterwinkel",b="Dorn Ebenenpirscher begann Test of Faith, und die Prüfungen erreichen nun ihren letzten Schritt. Er wartet im Wetterwinkel, in einer Höhle, die über eine Rampe nördlich vom Freiwindposten erreichbar ist. Parqual Fintallas mahnt Euch, das Gleichgewicht zu bewahren, das Ihr während der Prüfungen gezeigt habt."},{t="Dorns Willkommen",b="Dorn Ebenenpirscher sagt, viele Monde seien vergangen, seit Euer erster Sprung Euch auf diesen Pfad führte. Ihr wart lange Zeit fern seiner Heimat. Er findet Euch stärker und erleuchteter als zuvor, und das freut ihn. Dorn sagt, Ihr verdient Ehre dafür, dass Ihr seine Prüfungen bis zum Ende durchgestanden habt."}},faq={{q="Wer schickt Euch auf diesen letzten Schritt?",a="Parqual Fintallas sagt Euch, dass Ihr seine Prüfung und alle davor bestanden habt.",al={"questgeber","wer beginnt letzte überfahrt","parqual fintallas"}},{q="Wohin gehe ich als Nächstes?",a="Kehrt zu Dorn Ebenenpirscher in Tausend Nadeln zurück. Er wartet im Wetterwinkel, in einer Höhle, die über eine Rampe nördlich vom Freiwindposten erreichbar ist.",al={"wo ist dorn","wo abgeben","dorn ebenenpirscher standort","wetterwinkel standort"}},{q="Was kommt davor?",a="Test of Lore geht diesem Schritt als frühere Prüfung derselben Reihe voraus.",al={"vorherige quest","voraussetzung","was führt zu letzte überfahrt"}},{q="Was war der allererste Schritt dieser Reise?",a="Dorn Ebenenpirscher gab Euch Test of Faith im Wetterwinkel. Dies ist der letzte Schritt der Reihe.",al={"erste quest","wo begann das","test of faith questreihe"}},{q="Warum schickt Parqual Euch zu Dorn zurück?",a="Parqual sagt, Dorn werde bemerken, wie Ihr Euch verändert habt, und beurteilen, ob Ihr an Geist, Körper und Seele stark genug seid, um Ehre zu verdienen.",al={"warum dorn","parquals grund"}}},fp="13,219,26.252.0,14.282.1,33.86.0,19.132.0,23.69.0,45.95.0,39.125.0"}
P.entries["quest:1396"] = {n="Lauernde Tierwelt",s="Nachdem Verirrte die Karawane von Behüter Biggs verwüstet haben, streifen wilde Kreaturen nahe seinem Lager umher. Biggs überlebt als Einziger und bittet Euch, die verbliebenen Vorräte mit zu verteidigen. Dies folgt auf Help Watcher Biggs.",h="Nachdem Verirrte die Karawane von Behüter Biggs verwüstet haben, streifen wilde Kreaturen nahe seinem Lager...",kw={"karawane","verirrte","sawtooth crocolisk","sorrow spinner","vorräte","swamp jaguar","sümpfe des elends","behüter biggs"},sec={{t="Ein bewachtes Lager",b="Die Karawane von Behüter Biggs brach zur Ostküste auf, kam dort jedoch nie an. Verirrte griffen an, töteten die Wachen und zerstörten die Vorräte. Biggs überlebte als Einziger und hat geschworen, die verbliebenen Vorräte zu beschützen. Nun schleichen wilde Kreaturen nahe dem Lager umher, und Biggs bittet Euch, bei seiner Verteidigung zu helfen."},{t="Die Kreaturen in der Nähe",b="Young sawtooth crocolisks, sorrow spinners und swamp jaguars drängen nahe an das Lager heran. Biggs nennt acht crocolisks, zehn spinners und zehn jaguars, die getötet werden sollen."}},faq={{q="Wohin war die Karawane von Behüter Biggs unterwegs?",a="Die Karawane von Behüter Biggs war auf dem Weg zur Ostküste, kam dort jedoch nie an.",al={"wohin wollte biggs","ziel der karawane","route von biggs' karawane"}},{q="Wer griff die Karawane von Behüter Biggs an?",a="Verirrte griffen die Karawane an, töteten die Wachen und zerstörten die Vorräte. Behüter Biggs überlebte als Einziger.",al={"wer griff biggs an","wer zerstörte die karawane","überfall auf die karawane"}},{q="Welche Bestien bedrohen das Lager?",a="Young sawtooth crocolisks, sorrow spinners und swamp jaguars schleichen nahe dem Lager umher.",al={"welche bestien dringen vor","welche tiere greifen biggs an","sumpfbestien"}},{q="Warum bleibt Behüter Biggs im Lager?",a="Behüter Biggs hat geschworen, die verbliebenen Vorräte der Karawane zu beschützen.",al={"warum bleibt biggs","warum nicht fliehen","biggs' vorräte"}}},fp="20,190,18.281.0,20.157.0,44.78.0,37.107.0,30.81.0,42.77.0"}
P.entries["quest:1398"] = {n="Treibholz",s="Behüter Biggs schickt Euch nach Osten an die Küste, um trockenes Treibholz zu holen. Er braucht es, um seinen Wagen zu reparieren, bevor er Nethergarde erreichen kann.",h="Behüter Biggs schickt Euch nach Osten an die Küste, um trockenes Treibholz zu holen.",kw={"treibholz","nethergarde","sonnengetrocknetes treibholz","sümpfe des elends","wagen","behüter biggs"},sec={{t="Holz für den Wagen",b="Behüter Biggs dankt Euch und bittet erneut um Hilfe. Sein Wagen muss repariert werden, bevor er Nethergarde erreichen kann. Das Holz des Sumpfes ist zu schwammig und verwachsen, um es zu verwenden, also braucht er starkes, trockenes Holz."},{t="Treibholz von der Küste",b="Behüter Biggs schickt Euch nach Osten an die Küste, um von der Sonne getrocknetes Treibholz zu holen. Bringt ihm acht Stücke in die Sümpfe des Elends zurück."}},faq={{q="Warum braucht Behüter Biggs Holz?",a="Biggs braucht Holz, um seinen Wagen zu reparieren, damit er Nethergarde erreichen kann. Die Bäume des Sumpfes sind zu schwammig und verwachsen.",al={"treibholz grund","warum braucht biggs treibholz","warum treibholz"}},{q="Wohin schickt Euch Behüter Biggs, um das Holz zu holen?",a="Er schickt Euch nach Osten an die Küste, um von der Sonne getrocknetes Treibholz zu holen.",al={"treibholz fundort","wo treibholz finden","wo ist das holz"}},{q="Was kam davor?",a="Zuerst kommt The Lost Caravan. Danach bittet Biggs Euch um weitere Hilfe.",al={"treibholz vorherige quest","was führt zu treibholz","welche quest kommt vor treibholz"}},{q="Wie viel Treibholz wird benötigt?",a="Acht Stücke von der Sonne getrocknetes Treibholz.",al={"treibholz anzahl","wie viel treibholz"}},{q="Was kommt nach dem Sammeln des Treibholzes?",a="Danach folgt Deliver the Shipment.",al={"treibholz folgequest","was kommt nach treibholz","treibholz nächste quest"}}},fp="9,123,18.187.0,24.129.0,33.109.0,47.62.0,22.64.0,29.43.0,41.29.0"}
P.entries["quest:14"] = {n="Die Volksmiliz",s="Im Süden Westfalls kämpfen Freiwillige der Volksmiliz weiter gegen die Defias. Die erfahrenen Banditen halten die Dolchhügel, und Gryan Starkmantel führt einen Feldzug an, um die Straßen und Höfe zu befreien. Schließt die Patrouillen ab, und Ihr werdet auf der Späherkuppe vollwertig in die Miliz aufgenommen.",h="Im Süden Westfalls kämpfen Freiwillige der Volksmiliz weiter gegen die Defias.",kw={"die dolchhügel","wegelagerer der defias","schläger der defias","wegelagerin der defias","gryan starkmantel","volksmiliz","späherkuppe","westfall"},ang={["class:Paladin"]="Als Paladin hört Ihr, wie Starkmantel das Licht anruft, um neue Mitglieder zu segnen. Seine Worte spiegeln die heiligen Ideale der Gerechtigkeit und des Schutzes der Wehrlosen vor räuberischen Gesetzlosen wider.",["faction:Alliance"]="Als Mitglied der Allianz seht Ihr, wie Sturmwinds Versagen beim Schutz Westfalls das einfache Volk zwingt, sein eigenes Blut zu vergießen, um die Ordnung in seiner Heimat zu wahren.",["race:Human"]="Als Mensch aus Sturmwind steht Ihr für vergessene Landsleute ein, deren Lebensgrundlagen die politische Elite der Hauptstadt preisgegeben hat."},sec={{t="Säuberung der Dolchhügel",b="Die Bruderschaft der Defias hat großes Leid über Westfalls nördliches Ackerland gebracht. Wer Gryan Starkmantels ersten Säuberungen entkam, floh nach Süden in die felsigen Dolchhügel. Von dort aus überfallen Wegelagerer, Wegelagerinnen und Schläger der Defias weiterhin Gehöfte und lauern Reisenden auf. Ihr schließt Euch gestählten Rekruten an, die in die Hügel geschickt werden, um die Herrschaft der Banditen über das südliche Westfall zu brechen."},{t="Starkmantels Kreuzzug",b="Nach seiner Rückkehr vom Kampf gegen die Geißel in Lordaeron fand Gryan Starkmantel Westfall von Sturmwinds königlicher Garnison verlassen vor. Ein Verbrechersyndikat schaltete ungehindert, und Hunger trieb Bauern von ihrem Land. Also scharte er einheimische Freiwillige um sich, die zu den Waffen griffen. Schließt diese letzte Patrouille ab, und Starkmantel segnet Euch im Licht, während er Euch feierlich in die Miliz aufnimmt. Der Kampf gegen die Bruderschaft verschärft sich."}},faq={{q="Wo liegen die Dolchhügel?",a="Die Dolchhügel liegen im Süden Westfalls, südwestlich der Späherkuppe. Ihre zerklüfteten Höhenzüge und verlassenen Mineneingänge bieten den zäheren Kämpfern der Bruderschaft der Defias einen Ort, an dem sie sich sammeln und verschanzen können.",al={"lage der dolchhügel","wo sind die dolchhügel zu finden","wo sind die wegelagerer"}},{q="Warum kämpft die Volksmiliz allein gegen die Defias?",a="Da König Varian Wrynn verschwunden ist und die Mittel knapp sind, weigert sich Sturmwinds House of Nobles, die königliche Armee zum Schutz des ländlichen Westfall zu entsenden. Gryan Starkmantel und einheimische Bauern bilden ihre eigene Freiwilligentruppe, um ihre Heimat zu verteidigen.",al={"warum keine wachen aus sturmwind","wo ist sturmwinds armee","warum ist westfall verlassen"}},{q="Was bewirkt der Abschluss dieser Aufgabe?",a="Die Beseitigung der Wegelagerer, Wegelagerinnen und Schläger bricht die Kontrolle der Defias über die Straßen im Süden Westfalls. Ihr verdient Euch die förmliche Aufnahme in die Volksmiliz unter Gryan Starkmantels Befehl.",al={"volksmiliz abschluss","aufnahme in die miliz","was bringt der abschluss"}},{q="Wer ist Gryan Starkmantel?",a="Gryan Starkmantel ist ein erfahrener Soldat, der während des Dritten Krieges in Lordaeron gegen die Geißel kämpfte. Er kehrte nach Westfall zurück und sah, dass das Königreich Sturmwind seine Landbevölkerung im Stich gelassen hatte. Auf der Späherkuppe gründete er die Volksmiliz, um die Defias zu bekämpfen.",al={"gryans hintergrund","wer ist starkmantel","anführer der späherkuppe"}},{q="Welche Defias verbergen sich in den Dolchhügeln?",a="Die Dolchhügel bieten erfahrenen Wegelagerern, tödlichen Wegelagerinnen und brutalen Schlägern der Defias Unterschlupf. Sie führen Überfälle im gesamten Süden Westfalls an und bewachen die tiefer gelegenen Stützpunkte der Bruderschaft.",al={"defias-gegner im südlichen westfall","was sind wegelagerinnen und schläger","wer ist in den dolchhügeln"}},{q="Welche Verbindung gibt es zu Lordaeron?",a="Gryan Starkmantel sagt, er sei kürzlich aus den verseuchten Landen Lordaerons zurückgekehrt, wo die Allianz gegen die Geißel kämpfte. Diesen erbitterten Kampf überlebt zu haben, bestärkte ihn darin, Westfalls Verteidigung zu organisieren, nachdem die örtlichen Machthaber versagt hatten.",al={"starkmantel lordaeron","verseuchte lande von lordaeron","gryans kriegsgeschichte"}}},fx={["12e61ece"]={q="Warum will Gryan Starkmantel, dass diese Defias getötet werden?",a="Plünderer der The Defias Brotherhood sind tief in das südliche Westfall vorgedrungen, plündern Farmen und weichen den Milizpatrouillen aus. Gryan Starkmantels Späher haben sie in Die Dolchhügel aufgespürt, wo sie sich aktiv versammeln, um ihren nächsten Schlag zu planen. Wenn sie jetzt nicht ausgerottet und zerschlagen werden, werden die verbleibenden Gehöfte im Süden vollständig unter ihre Kontrolle fallen.",al={"warum defias in den dolchhügeln töten","motive von gryan","warum will gryan sie tot"}}},fp="20,276,24.379.0,21.422.0,27.188.0,54.236.0,39.201.0,25.264.0,45.192.0,35.225.0"}
P.entries["quest:140"] = {n="Käpt'n Sanders' versteckter Schatz",s="Ein whiskeygetränkter Hinweis führt Euch von Westfalls Küste nach Westen über das große Meer. Captain Sanders' Spur endet auf einem abgelegenen Inselchen, wo seine verborgene Beute wartet.",h="Ein whiskeygetränkter Hinweis führt Euch von Westfalls Küste nach Westen über das große Meer.",kw={"captain sanders","letzter hinweis","versteckter schatz","insel","verschlossene truhe","alter krug","schatzsuche","westfall"},ang={["class:Rogue"]="Der Spur eines Schurken über verlassene Strände und hinaus aufs Meer zu folgen, liegt einem Schurken im Blut, der Piratenschmuggelware schätzt.",["race:Human"]="Als Mensch, der Westfall gegen Briganten der Defias und Gnolle verteidigt, begrüßt Ihr vielleicht eine Pause von den Hofpatrouillen, während Ihr den vergessenen Schatz eines örtlichen Piraten aufspürt."},sec={{t="Die Spur eines Seemanns",b="Captain Sanders hinterließ entlang der Küste von Westfall Hinweise, die Ihr zusammensetzen sollt. Das letzte Pergament stammte aus dem Bodensatz seines liebsten Whiskeykrugs. Es gibt die letzte Peilung vor: Geht nach Westen bis ans Wasser und schwimmt dann hinaus in die Wellen."},{t="Das einsame Inselchen",b="Vor Westfall ragen kleine Felsen aus dem großen Meer. Schwimmt genau nach Westen, um die abgelegene Insel zu erreichen, auf der Captain Sanders seine Beute versteckte. Dort wartet eine verschlossene Truhe, deren Scharniere durch jahrelange salzige Brandung verrostet sind. Brecht sie auf, und die Spur des Freibeuters endet."}},faq={{q="Wohin führt der letzte Hinweis?",a="Der Zettel im Alten Krug schickt Euch nach Westen an Westfalls Küste und dann hinaus aufs Meer. Die Truhe wartet auf einer kleinen Insel.",al={"wo ist die truhe","sanders schatz fundort","ziel des letzten hinweises"}},{q="Wer war Captain Sanders?",a="Captain Sanders war ein Freibeuter, der an Westfalls Küste entlangsegelte. Er hinterließ am Ufer eine rätselhafte Spur aus Hinweisen, die zu einer Truhe auf einer abgelegenen Insel führte statt zu einer Bank oder Festung.",al={"wer ist captain sanders","sanders geschichte","captain sanders hintergrund"}},{q="Warum riecht der letzte Hinweis nach Whiskey?",a="Captain Sanders versteckte die letzten Anweisungen in seinem weggeworfenen Whiskeykrug nahe der Küste. Feuchtigkeit und Schnaps ließen die Tinte mit der Zeit verlaufen, doch die Wegbeschreibung bleibt lesbar.",al={"whiskeyzettel","alter krug hinweis"}},{q="Wie viele Schritte umfasst diese Schatzsuche?",a="Die Suche hat vier Etappen. Sie beginnt mit einer vom Meer mitgenommenen Karte an der Küste und führt dann über eine Schließkiste, ein Fass und einen Whiskeykrug zur Inseltruhe.",al={"wie lang ist sanders questreihe","sanders questteile","captain sanders questreihe"}},{q="Ist der Weg zur Insel gefährlich?",a="Die größte Herausforderung ist die lange Schwimmstrecke hinaus ins große Meer. In Westfalls Küstengewässern lauern oft angriffslustige Murlocs und Meeresbestien, während Sanders seinen Schatz auf dem Inselchen aufbewahrte.",al={"zu sanders truhe schwimmen","gefahren auf der insel","murlocs nahe der truhe"}},{q="In welchem Zustand ist die Schatztruhe?",a="Seeluft und tosende Brandung haben der Truhe zugesetzt. Ihre Scharniere sind stark verrostet, doch mit Hebelkraft lässt sie sich aufbrechen, um an die Waren darin zu gelangen.",al={"zustand der truhe","ist die truhe verschlossen","rostige truhe"}}},fp="32,165,16.229.0,16.257.1,31.123.0,24.189.0,44.178.0,41.169.0,33.176.0,36.139.0"}
P.entries["quest:141"] = {n="Die Bruderschaft der Defias",s="Aus Sturmwind schickt Mathias Shaw Gryan Starkmantel einen vertraulichen Bericht zur Späherkuppe. Shaw hat die ehemalige Steinmetzgilde untersucht, um Starkmantel dabei zu helfen, die Ursprünge der Bruderschaft der Defias aufzudecken.",h="Aus Sturmwind schickt Mathias Shaw Gryan Starkmantel einen vertraulichen Bericht zur Späherkuppe.",kw={"defias","späherkuppe","shaw","steinmetze","sturmwind","starkmantel","van cleef","westfall"},ang={["class:Rogue"]="Als Schurke seht Ihr, wie Streitigkeiten unter Sturmwinds ehemaligen Handwerkern weit entfernte Siedlungen in Bedrängnis bringen können.",["faction:Alliance"]="Für die Allianz offenbart der Aufstand der Steinmetze tiefe Risse im Königreich. Die Arbeiter, die Sturmwinds steinerne Stadtmauern wiederaufbauten, drohen nun, sie niederzureißen.",["race:Human"]="Als Mensch aus Sturmwind betrifft Euch diese Enthüllung ganz persönlich. Die Mauern Eurer Häuser und selbst die Cathedral wurden von denselben Männern erbaut, die nun das Umland von Westfall plündern."},sec={{t="Vom Baumeister zum Banditen",b="Seit Monaten stehen Gryan Starkmantel und die Volksmiliz in ganz Westfall einem Aufstand ohne klares Gesicht gegenüber. Wegelagerer, Diebe und Halsabschneider schlagen entlang der Straßen und im Umland zu. Meister Mathias Shaw vom SI:7 untersucht Wileys Nachricht und setzt die Wahrheit Stück für Stück zusammen. Die Gilde der Architekten und Steinmetze, die Sturmwinds weiße Stadtmauern wiederaufbauten, hat sich nie aufgelöst. Ihr Anführer, Edwin van Cleef, führte sie in den Untergrund."},{t="Verbitterung und Verrat",b="Nachdem der Erste Krieg Sturmwind in Schutt und Asche gelegt hatte, machte sich van Cleefs Steinmetzgilde daran, die Hauptstadt des Königreichs wiederaufzubauen. Ihre Arbeit ließ Sturmwind erneut zu einem Juwel der Menschheit werden. Als die Arbeit beendet war, entbrannte ein erbitterter Streit über die Entlohnung. Van Cleef und seine Handwerker waren mit ihrer Behandlung durch die Krone und das Haus der Adligen unzufrieden. Also griffen sie zu Dolchen und roten Bandanas und tauschten ihr Handwerk im Dienste der Stadt gegen gewaltsame Rebellion gegen den Thron."},{t="Starkmantels Unglaube",b="Shaws Bericht erreicht die Späherkuppe, und Gryan Starkmantel fällt es schwer, seinen Inhalt zu akzeptieren. Er erinnert sich an van Cleef als fleißigen, begabten Handwerker, nicht als Halsabschneider, der sich in den Schatten des Umlands verbirgt. Van Cleefs Arbeit bot Tausenden zurückkehrenden Bürgern Schutz. Der Milizkommandant fordert konkrete Beweise, bevor er die alarmierende Anschuldigung vollends akzeptiert, dass Sturmwinds Chefarchitekt Westfalls Untergang lenkt."}},faq={{q="Was ist Shaws Bericht?",a="Mathias Shaws vertraulicher Bericht enthält seine Erkenntnisse über die ehemalige Steinmetzgilde und die Defias. Ihr bringt ihn zu Gryan Starkmantel.",al={"shaws bericht","mathias shaws dokument","der bericht an starkmantel"}},{q="Wer ist Edwin van Cleef?",a="Edwin van Cleef führte die Steinmetzgilde an, die Sturmwind wiederaufbaute. Shaws Bericht untersucht die spätere Geschichte der Gilde.",al={"van cleefs identität","wer ist edwin van cleef","edwin van cleefs geschichte"}},{q="Warum steht Gryan Starkmantel dem Bericht skeptisch gegenüber?",a="Gryan Starkmantel kann Shaws Anschuldigungen nur schwer verdauen. Er fordert konkrete Beweise, bevor er sie vollends akzeptiert, und erfährt die Einzelheiten beim Lesen des Berichts.",al={"warum glaubt gryan es nicht","starkmantels reaktion","warum braucht gryan beweise"}},{q="Warum wandten sich die Steinmetze gegen Sturmwind?",a="Die Steinmetze bauten Sturmwind wieder auf und gerieten anschließend in einen erbitterten Streit über die Entlohnung. Sie waren mit ihrer Behandlung durch die Krone und das Haus der Adligen unzufrieden.",al={"warum sind die defias wütend","streit der steinmetze","van cleefs beweggrund"}},{q="Welche Rolle spielt der SI:7 bei dieser Quest?",a="Mathias Shaw vom SI:7 untersucht mögliche Verbindungen zwischen der ehemaligen Gilde und den Gesetzlosen und schickt seine Erkenntnisse dann an Starkmantel.",al={"warum mathias shaw","beteiligung des si:7","schurke gilde sturmwind"}},{q="Wohin führt diese Untersuchung als Nächstes?",a="Ihr überbringt den Bericht und helft Starkmantel dann, im Zuge der laufenden Ermittlungen gegen die Defias weitere Beweise zu suchen.",al={"what comes next","nächste quest defias","nach shaws bericht"}}},fx={b90c31ae={q="Warum möchte Meister Mathias Shaw, dass dieser Bericht zugestellt wird?",a="Mathias Shaw sendet seine Erkenntnisse an Gryan Starkmantel, damit die The People's Militia weiterhin gegen The Defias Brotherhood ermitteln kann. Der vertrauliche Bericht stützt sich auf Shaws Forschungen über die ehemalige Gilde der Steinmetze.",al={"warum bericht schicken","motive von shaw","warum shaw bericht an gryan schickt"}},d51cfbac={q="Warum verlässt sich Mathias Shaw darauf, dass Ihr den Bericht überbringt?",a="Ihr seid auf direkte Empfehlung von Gryan Starkmantel in Sturmwind eingetroffen und habt Euch bereits im Feld bewährt. Anstatt offizielle Kuriere des SI:7 oder Stadtwachen zu riskieren, während Infiltratoren der Defias möglicherweise zuschauen, vertraut Shaw darauf, dass Ihr seine vertraulichen Erkenntnisse direkt an die The People's Militia zurückbringt.",al={"warum keine wachen schicken","warum einen abenteurer nutzen","warum ich shaw"}}},fp="22,201,23.426.1,23.458.1,23.423.1,22.139.0,22.118.0,49.171.0,47.167.0,39.129.0,40.106.1"}
P.entries["quest:1418"] = {n="Neeka Blutnarbe",s="In Steinard schickt Helgrum der Hurtige Euch nach Kargath, wo seine Nachrichten oft nicht ankommen.",h="In Steinard schickt Helgrum der Hurtige Euch nach Kargath, wo seine Nachrichten oft nicht ankommen.",kw={"ödland","oberste späherin","helgrum der hurtige","kargath","loch modan","neeka blutnarbe","steinard","sümpfe des elends"},sec={{t="Eine unterbrochene Verbindung",b="Im Ödland, einem rauen Land nahe dem von der Allianz gehaltenen Loch Modan, kommen Nachrichten zwischen Steinard und Kargath oft nicht an. Helgrum bittet Euch, Euch zu beweisen, indem Ihr nach Kargath reist und mit Neeka Blutnarbe sprecht, der obersten Späherin des Außenpostens. Dann bringt Ihr Neekas Bericht zu Helgrum zurück."},{t="Neekas Antwort",b="Neeka Blutnarbe erzählt Euch, dass vor kaum drei Tagen ein Vorläufer nach Steinard aufgebrochen ist. Da keine Nachricht von Neeka Steinard erreicht hat, muss der Läufer versagt haben. Neeka hofft, dass der nächste mehr Geschick oder Glück hat."}},faq={{q="Wohin schickt Euch Helgrum der Hurtige?",a="Helgrum der Hurtige schickt Euch von Steinard nach Kargath, einem Außenposten im Ödland, um mit dessen oberster Späherin Neeka Blutnarbe zu sprechen.",al={"wohin gehen","neeka blutnarbe standort","wo ist neeka"}},{q="Warum ist die Verbindung zwischen Steinard und Kargath unterbrochen?",a="Das Ödland ist ein raues Land nahe Loch Modan, das von der Allianz gehalten wird. Nachrichten zwischen Steinard und Kargath kommen oft nicht an.",al={"warum ist die verbindung unterbrochen","ödland verbindungsproblem","warum von steinard nach kargath"}},{q="Wer ist Neeka Blutnarbe?",a="Neeka Blutnarbe ist die oberste Späherin im Außenposten Kargath im Ödland.",al={"wer ist neeka","neekas rolle","neeka blutnarbe geschichte"}},{q="Was folgt nach dem Gespräch mit Neeka Blutnarbe?",a="Nach dem Gespräch mit Neeka Blutnarbe erstattet Ihr Helgrum Bericht.",al={"was als nächstes","folgequest","nach neeka blutnarbe"}}},fp="15,92,10.267.0,14.202.1,38.127.0,57.122.0,23.73.0,47.64.0"}
P.entries["quest:1419"] = {n="Kojoten-Diebe",s="In Kargath haben Felsenkojoten Nahrung gestohlen, und Neeka Bloodscar will, dass sie gejagt werden. Sie bittet Euch, dreißig Kieferknochen zurückzubringen.",h="In Kargath haben Felsenkojoten Nahrung gestohlen, und Neeka Bloodscar will, dass sie gejagt werden.",kw={"ödland","kojoten-diebe","felsenkojote","kieferknochen","kargath","neeka bloodscar"},sec={{t="Diebe von Kargath",b="Neeka Bloodscar fragt, ob Ihr viele Tage im Ödland verbracht, seine Hitze gespürt und die Bestien seiner staubigen Ebenen getroffen habt. Felsenkojoten sind zäh und haben sich nach Kargath geschlichen, um Nahrung aus dem Außenposten zu stehlen. Sie möchte, dass Ihr sie jagt und ihre Kieferknochen zurückbringt. Bringt genug davon, und Neeka glaubt vielleicht, dass Ihr das Ödland kennt."}},faq={{q="Warum will Neeka Bloodscar Kojotenkieferknochen?",a="Felsenkojoten haben sich nach Kargath geschlichen und Nahrung aus dem Außenposten gestohlen. Neeka will, dass sie gejagt werden, und ihre Kieferknochen werden zeigen, dass Ihr das Ödland kennt.",al={"warum kojotenkieferknochen","neeka bloodscars beweggründe","warum kieferknochen sammeln"}},{q="Wo sorgen die Kojoten für Ärger?",a="Felsenkojoten durchstreifen die staubigen Ebenen des Ödlands und haben sich nach Kargath geschlichen, um Nahrung zu stehlen.",al={"kojoten fundort","wo felsenkojoten finden","wo sind die kojoten"}},{q="Wie viele Kieferknochen will Neeka Bloodscar?",a="Neeka Bloodscar möchte, dass Ihr ihr dreißig Kojotenkieferknochen nach Kargath bringt.",al={"wie viele kieferknochen","anzahl der kojotenkieferknochen"}},{q="Wer ist Neeka Bloodscar?",a="Neeka Bloodscar befindet sich im Außenposten Kargath im Ödland. Sie bittet Euch, Felsenkojoten zu jagen.",al={"wer ist neeka","neeka bloodscar"}}},fp="14,125,18.331.0,46.152.0,38.89.0,44.73.0,23.93.0"}
P.entries["quest:142"] = {n="Die Bruderschaft der Defias",s="Gryan Starkmantel schickt Euch auf die Jagd nach einem schwer fassbaren Kurier der Defias, um zu erfahren, wie die Bruderschaft ihre Streitkräfte lenkt.",h="Gryan Starkmantel schickt Euch auf die Jagd nach einem schwer fassbaren Kurier der Defias, um zu erfahren...",kw={"defias","jangoschacht","bote","mondbruch","steinbruch","saldean","starkmantel","westfall"},ang={["class:Rogue"]="Als Schurke könnt Ihr erkennen, wie geschickte Späher und Taschendiebe direkt unter den Augen der Miliz ein weitverzweigtes Schattennetzwerk koordinieren.",["faction:Alliance"]="Ohne Unterstützung von Sturmwinds königlicher Garnison übernimmt die Volksmiliz die Aufklärung in Westfall allein und verfolgt Kuriere auf einsamen Feldwegen.",["race:Human"]="Als Mensch könnt Ihr die Depeschen zu Edwin van Cleef zurückverfolgen und die bitteren, anhaltenden Folgen von Sturmwinds politischen Streitigkeiten und Arbeitskonflikten erkennen."},sec={{t="Den Kurier abfangen",b="Gryan Starkmantels Späher haben einen schwer fassbaren Defias Messenger zwischen Mondbruch, dem Goldküstensteinbruch und dem Jangoschacht beobachtet. Anders als die Schläger, die das Umland besetzt halten, trägt dieser Kurier schriftliche Befehle durch die Region. Starkmantel will ihn gefangen nehmen oder töten lassen, damit die Volksmiliz die Schreiben in seiner Tasche lesen und erfahren kann, wohin die Bruderschaft ihre Streitkräfte lenkt."},{t="Eine Spur aus Tinte",b="Die sichergestellte Nachricht bestätigt, dass Edwin van Cleef, der legendäre ehemalige Anführer der Stonemasons Guild, den Aufstand der Defias persönlich leitet. Sie bestätigt seine Befehlsgewalt über die örtlichen Zellen, verrät aber nicht, wo er seinen geheimen Stützpunkt eingerichtet hat."},{t="Eine glückliche Wendung",b="Die Nachricht bestätigt van Cleefs Führungsrolle, und der Volksmiliz kommt ein glücklicher Zufall zu Hilfe. Ein verzweifelter Bandit wird beim Versuch ertappt, Bauer Saldeans Wagen zu stehlen, und erklärt sich bereit, für sein Leben Verrat zu begehen. Mit dem schriftlichen Beweis in der Hand richtet Starkmantel seine Aufmerksamkeit auf den Überläufer, der hoffentlich eine Eskorte mitten in das Defias Hideout führen kann."}},faq={{q="Wo ist der Defias Messenger unterwegs?",a="Der Defias Messenger beginnt seine Patrouille in Mondbruch vor der Schmiede. Er geht nach Norden zum Goldküstensteinbruch und zum Jangoschacht, betritt beide unterirdischen Abbaustätten und kehrt dann auf demselben Weg nach Mondbruch zurück.",al={"route des boten","wo ist defias messenger","boten finden"}},{q="Was verrät die abgefangene Nachricht?",a="Starkmantel hofft, dass die Befehle des Kuriers die Befehlsstruktur der Bruderschaft offenlegen und helfen, ihr Versteck zu finden. Der Inhalt der Nachricht wird bekannt, sobald sie sichergestellt ist.",al={"was stand in der nachricht","text der geheimnisvollen nachricht","van cleefs notiz"}},{q="Wer ist Gryan Starkmantel?",a="Gryan Starkmantel befehligt die Volksmiliz von ihrem Hauptquartier auf der Späherkuppe aus. Da es zu wenige königliche Wachen aus Sturmwind gibt, organisiert er Freiwillige und Abenteurer, um Westfall gegen Überfälle der Defias zu verteidigen.",al={"starkmantels rolle","wer vergibt diese quest"}},{q="Warum besucht der Bote die Minen?",a="Die Bruderschaft hat Westfalls Bodenschätze unter ihre Kontrolle gebracht und nutzt den Jangoschacht und den Goldküstensteinbruch als Rohstoffquellen, Unterschlupf und Aufmarschgebiete. Der Bote überbringt Nachrichten zwischen diesen Betrieben und der Führung der Bruderschaft.",al={"warum goldküstensteinbruch","warum jangoschacht"}},{q="Verrät die Ergreifung des Boten, wo das Defias Hideout liegt?",a="Starkmantel will die abgefangenen Befehle nutzen, um die Suche nach dem Versteck fortzusetzen. Ihr erfahrt von der nächsten Spur, wenn Ihr zu ihm zurückkehrt.",al={"haben wir das versteck gefunden","wo ist das versteck"}},{q="Wer ist Edwin van Cleef?",a="Edwin van Cleef war Großbaumeister der Stonemasons Guild, die Sturmwind wiederaufbaute. Starkmantels Ermittlungen gehen van Cleefs möglicher Verbindung zur Bruderschaft nach.",al={"wer ist van cleef","anführer der defias"}}},fx={["885172ef"]={q="Warum möchte Gryan Starkmantel, dass dies erledigt wird?",a="Gryan Starkmantel und die The People's Militia führen einen verzweifelten Feldzug, um Westfall von The Defias Brotherhood zurückzuerobern. Während die Miliz weiß, dass die Diebe auf den Farmen und in den Minen der Provinz operieren, wissen sie immer noch nicht, wo sich das Hauptversteck der Bruderschaft befindet. Diesen Boten abzufangen, ist Starkmantels beste Spur, um ihr Bollwerk zu entdecken und direkt gegen ihre Führung vorzugehen.",al={"motive von gryan starkmantel","warum boten abfangen","warum defias boten fangen"}},fc5d2b39={q="Wer ist der Bote der Defias?",a="Der Kurier ist ein Agent der Defias, der damit beauftragt ist, Depeschen zwischen den wichtigsten Stützpunkten der Bruderschaft in Westfall zu überbringen: der besetzten Stadt Mondbruch, dem Goldküstensteinbruch und dem Jangoschacht. Da er die Bewegungen zwischen diesen verstreuten Außenposten koordiniert, bietet seine Gefangennahme oder die Beschlagnahmung seiner Befehle der The People's Militia ein seltenes Fenster in die Kommandostruktur der Verschwörer.",al={"defias bote","wer ist der bote","ziel bote"}},a4c1678d={q="Warum benötigt Gryan Starkmantel Euch für diese Aufgabe?",a="Die The People's Militia ist bis an ihre absolute Grenze belastet, während sie einen dünnen Verteidigungsring um die Späherkuppe aufrechterhält und flüchtende Farmer vor grassierenden Banditen und Gnollen verteidigt. Sturmwind hat sich geweigert, Verstärkungen oder königliche Truppen nach Westfall zu schicken, wodurch Starkmantel keine Soldaten übrig bleiben, um Kuriere durch feindliches Gebiet zu jagen.",al={"warum ich","warum macht gryan es nicht","warum braucht miliz mich"}}},fp="22,116,24.376.0,14.251.1,17.347.1,39.213.0,41.173.1,25.204.0,40.235.0,54.134.0,22.171.1"}
P.entries["quest:1420"] = {n="Bericht für Helgrum",s="In Kargath gibt Euch Neeka Bloodscar einen neuen Bericht für Helgrum den Hurtigen in Steinard. Ihr habt dort gerade mit ihr gesprochen.",h="In Kargath gibt Euch Neeka Bloodscar einen neuen Bericht für Helgrum den Hurtigen in Steinard.",kw={"ödland","helgrum der hurtige","geheimdienstinformationen der horde","neeka bloodscar","vorläufer","bericht","steinard"},sec={{t="Ein Bericht für Steinard",b="Neeka Bloodscar gibt Euch einen neuen Bericht für Helgrum in Steinard. Sie warnt, dass jeder, der sich Vorläufer nennt, auf dem Weg bleiben muss und keinem Feind zum Opfer fallen darf."},{t="Helgrum liest den Bericht",b="Helgrum der Hurtige liest Neekas Bericht und erfährt, dass die Allianz ihre eigenen Probleme hat. Er glaubt, dass die Horde und die Allianz einige gemeinsame Feinde haben könnten."}},faq={{q="Wer schickt Euch mit dem Bericht los?",a="Neeka Bloodscar hat einen neuen Bericht für Helgrum verfasst und bittet Euch, ihn zu überbringen.",al={"wer gibt den bericht für helgrum","questgeber bericht für helgrum","wer beginnt diese quest"}},{q="Wohin muss der Bericht gebracht werden?",a="Überbringt den Bericht Helgrum dem Hurtigen in Steinard.",al={"wo bericht für helgrum abgeben","helgrums standort","wo ist helgrum"}},{q="Was geht dem voraus?",a="Dies folgt auf Euren früheren Besuch bei Neeka Bloodscar in Kargath.",al={"vorherige quest","voraussetzung für bericht für helgrum","welche quest kommt zuerst"}}},fp="17,123,20.169.0,24.149.1,30.80.0,43.51.0,23.62.0"}
P.entries["quest:1421"] = {n="Die verlorene Karawane",s="Behüter Biggs möchte die Reagenzien der Karawane zurückhaben, nachdem die Verirrten einen Wagen nach Norden zur Zuflucht der Verirrten gebracht haben. Die Kiste enthält Vorräte für die Zauberer der Burg Nethergarde.",h="Behüter Biggs möchte die Reagenzien der Karawane zurückhaben, nachdem die Verirrten einen Wagen nach Norden...",kw={"das dunkle portal","zuflucht der verirrten","verirrte","burg nethergarde","sümpfe des elends","behüter biggs","reagenzien der zauberer"},sec={{t="Der gestohlene Wagen",b="Behüter Biggs wurde bewusstlos geschlagen, als die Verirrten die Karawane angriffen. Bevor er fiel, sah er, wie sie einen der Wagen nach Norden zur Zuflucht der Verirrten schleppten, ihrem Dorf. An Bord war eine Kiste mit Reagenzien, die die Zauberer der Burg Nethergarde für ihre Studien sehr schätzen. Biggs bittet Euch, die Kiste zu finden und ihren Inhalt zurückzubringen."},{t="Nachricht von Biggs",b="Als Ihr die Reagenzien zurückbringt, ist Behüter Biggs erfreut. Die Zauberer von Nethergarde können ihre Arbeit fortsetzen, auch wenn Biggs nicht weiß, worin diese Arbeit besteht. Er weiß, dass sie das Dunkle Portal in den Verwüsteten Landen betrifft und für die Sicherheit der Allianz von großer Bedeutung ist."}},faq={{q="Wer ist Behüter Biggs?",a="Behüter Biggs hat einen Wagen der Karawane an die Verirrten verloren und möchte die Reagenzien daraus zurückhaben.",al={"behüter biggs","wer vergibt die verlorene karawane"}},{q="Wohin haben die Verirrten die Kiste der Karawane gebracht?",a="Behüter Biggs sah, wie der Wagen mit der Kiste nach Norden zur Zuflucht der Verirrten geschleppt wurde, dem Dorf der Verirrten.",al={"fundort der karawanenkiste","wo ist die zuflucht der verirrten","wo sind die reagenzien"}},{q="Warum sind die Reagenzien wichtig?",a="Die Zauberer der Burg Nethergarde sind für ihre Studien auf die Reagenzien angewiesen.",al={"warum sind reagenzien wichtig","zweck der reagenzien für nethergarde"}},{q="Was folgt nach der Bergung der Kiste?",a="Driftwood folgt, sobald Behüter Biggs die Reagenzien hat.",al={"nächste quest nach die verlorene karawane","questreihe die verlorene karawane"}}},fp="16,179,16.328.0,15.263.1,21.97.0,47.112.0,31.73.0,38.54.0"}
P.entries["quest:1422"] = {n="Gefahr aus dem Meer",s="Tok'Kar arbeitet an Eurer Waffe, während Katar berichtet, die Strandpatrouillen könnten Hilfe gebrauchen.",h="Tok'Kar arbeitet an Eurer Waffe, während Katar berichtet, die Strandpatrouillen könnten Hilfe gebrauchen.",kw={"strand","katar","patrouille","ufer","sümpfe des elends","gefahr aus dem meer","tok'kar"},sec={{t="Ein Wort mit Katar",b="Tok'Kar arbeitet an Eurer Waffe und schickt Euch zu Katar. Katar sagt, die Strandpatrouillen könnten Hilfe gebrauchen. Einige Nichtsnutze im Lager trinken, doch Tok'Kar möchte lieber, dass Ihr bei klarem Verstand bleibt und Eure Waffen bereithaltet, als Euch ihnen anzuschließen."},{t="Über dem Tosen des Meeres",b="Katar bittet Euch um einen Moment der Stille. Über dem dumpfen Tosen des Meeres könnt Ihr das widerliche Gurgeln der Fischmenschen hören."}},faq={{q="Warum schickt Tok'Kar Euch zu Katar?",a="Tok'Kar ist mit Eurer Waffe beschäftigt, also schickt er Euch zu Katar und will, dass Ihr bei klarem Verstand bleibt und Eure Waffen bereithaltet, statt mit den Nichtsnutzen im Lager zu trinken.",al={"warum mit katar sprechen","tok'kars grund","warum katar aufsuchen"}},{q="Wobei braucht Katar Unterstützung?",a="Katar sagt, die Patrouillen entlang des Strandes könnten etwas Hilfe gebrauchen.",al={"katars problem","was will katar","katar patrouille"}},{q="Was kam vor diesem Schritt?",a="Nach Lack of Surplus beginnt Tok'Kar mit der Arbeit an Eurer Waffe.",al={"vorherige quest","voraussetzung","gefahr aus dem meer questreihe"}}},fp="19,82,17.213.0,24.114.1,35.153.0,37.59.0,27.58.0"}
P.entries["quest:1423"] = {n="Die verlorenen Vorräte",s="Ein Fass für Burg Nethergarde trägt den Namen von Rüstmeister Lungertz.",h="Ein Fass für Burg Nethergarde trägt den Namen von Rüstmeister Lungertz.",kw={"fass","dunkelhain","verlorene vorräte","burg nethergarde","rüstmeister lungertz","sümpfe des elends"},sec={{t="Ein gestempeltes Fass",b="Stechend riechendes gelbes Wachs versiegelt die Fugen eines kleinen, robusten Fasses. Sein Boden trägt einen Stempel, der Rüstmeister Lungertz und Burg Nethergarde nennt und damit angibt, wohin es gehört."},{t="Nachricht vom Rüstmeister",b="Rüstmeister Lungertz dankt Euch für die wiederbeschafften Vorräte. Auf dem Weg von Dunkelhain nach Nethergarde gehen sie oft verloren. Ein Teil wurde nun gefunden."}},faq={{q="Wer soll die verlorenen Vorräte erhalten?",a="Das Fass ist für Rüstmeister Lungertz auf Burg Nethergarde bestimmt.",al={"wer bekommt das fass","empfänger der verlorenen vorräte","wohin geht das fass"}},{q="Woran erkennt Ihr, wem das Fass gehört?",a="Ein Stempel auf dem Fassboden nennt Rüstmeister Lungertz und Burg Nethergarde.",al={"markierungen am fass","fassbeschriftung lesen","rüstmeister lungertz stempel"}},{q="Wie sieht das Fass aus?",a="Es ist ein kleines, robustes Fass, dessen Fugen mit stechend riechendem gelbem Wachs versiegelt sind.",al={"verlorene vorräte fass","fassbeschreibung"}}},fp="17,74,16.164.0,27.151.1,42.68.0,37.81.0,31.71.0"}
P.entries["quest:1424"] = {n="Tränenteich",s="In Steinard schickt Fel'zerul Euch zum Tränenteich, um nach Atal'ai-Artefakten zu suchen. Die Leute des Kriegshäuptlings kamen, um seltsame Vorkommnisse im Tempel von Atal'Hakkar zu untersuchen, und fanden ihn versunken vor.",h="In Steinard schickt Fel'zerul Euch zum Tränenteich, um nach Atal'ai-Artefakten zu suchen.",kw={"artefakte","atal'ai","fel'zerul","grüne drachen","tränenteich","steinard","sümpfe des elends","der tempel von atal'hakkar","kriegshäuptling"},sec={{t="Der Versunkene Tempel",b="Die Atal'ai-Trolle sind ein Stamm finsterer Zauberwirker, der für verbotene Magie bekannt ist. Fel'zeruls Gruppe erreichte den Tempel von Atal'Hakkar und fand ihn versunken vor. Grüne Drachen wachen nun über den Tempel und nennen sich Beschützer von Azeroth."},{t="Teile eines Puzzles",b="Fel'zerul will erfahren, was geschehen ist, und bittet Euch deshalb, rund um den Tränenteich Atal'ai-Artefakte zu sammeln. Die Stücke könnten helfen, das Puzzle zusammenzusetzen. Niemand weiß, welche dunklen Riten die Trolle im Tempel praktizierten, nur dass sie große magische Kräfte einsetzten. Fel'zerul hofft, dass ihre Zauber der Horde helfen könnten. Er will erfahren, wonach die Atal'ai strebten und was so schrecklich schiefging."}},faq={{q="Wer ist Fel'zerul?",a="Fel'zerul ist in Steinard und gehört zu jenen, die der Kriegshäuptling entsandte, um seltsame Vorkommnisse im Tempel von Atal'Hakkar zu untersuchen.",al={"fel'zerul","felzerul","wer vergibt tränenteich"}},{q="Warum interessiert sich die Horde für die Atal'ai-Trolle?",a="Fel'zerul sagt, dass im Tempel große magische Kräfte eingesetzt wurden. Er hofft, dass sich die Zauber der Atal'ai für die Horde als nützlich erweisen könnten.",al={"warum die horde die atal'ai will","atal'ai magie horde"}},{q="Wo befinden sich die Atal'ai-Artefakte?",a="Die Atal'ai-Artefakte liegen auf dem Grund des Tränenteichs, nahe dem Tempel.",al={"atal'ai artefakte fundort","wo artefakte finden","tränenteich artefakte"}},{q="Wer bewacht jetzt den versunkenen Tempel?",a="Grüne Drachen wachen über den versunkenen Tempel und nennen sich Beschützer von Azeroth.",al={"warum sind grüne drachen hier","grüne drachen tempel von atal'hakkar","grüne drachen sümpfe des elends"}},{q="Was kommt als Nächstes, nachdem die Artefakte abgegeben wurden?",a="Der Verbannte der Atal'ai folgt.",al={"nächste quest nach tränenteich","tränenteich folgequest","was nach tränenteich"}}},fp="13,187,17.227.0,18.384.0,17.114.0,50.121.0,40.75.0,33.85.0,50.26.0"}
P.entries["quest:1425"] = {n="Überbringen der Lieferung",s="Nach Driftwood bittet Euch Behüter Biggs, Vorräte zu Rüstmeister Lungertz in Burg Nethergarde zu bringen, während sein Wagen repariert wird.",h="Nach Driftwood bittet Euch Behüter Biggs, Vorräte zu Rüstmeister Lungertz in Burg Nethergarde zu bringen...",kw={"azoran crystals","verwüstete lande","das dunkle portal","burg nethergarde","rüstmeister lungertz","lieferung","sümpfe des elends","behüter biggs"},sec={{t="Eine letzte Lieferung für Biggs",b="Behüter Biggs packt die wichtigsten Vorräte, die vor den Angriffen der Oger gerettet wurden, für Euren Transport zusammen. Er bleibt zurück, um den Wagen zu reparieren. Burg Nethergarde liegt in den nördlichen Hügeln der Verwüsteten Lande und wacht über das Dunkle Portal. Biggs schickt Euch auf der Straße nach Osten, dann an der Abzweigung nach Süden in die Verwüsteten Lande. Biegt an der nächsten Weggabelung links ab und bleibt wachsam."},{t="In Nethergarde",b="Rüstmeister Lungertz ist überrascht, als Ihr mit einem Paket aus Biggs' Karawane eintrefft. In der Burg hatte man die Karawane und Biggs bereits verloren geglaubt. Lungertz dankt Euch und hofft, dass die Vorräte Azoran Crystals enthalten, ein Reagenz, das die Burg dringend benötigt und dessen Vorrat zur Neige geht."}},faq={{q="Wer schickt die Lieferung nach Nethergarde?",a="Behüter Biggs hat die wichtigsten Vorräte zusammengepackt, die vor den Angriffen der Oger gerettet wurden, während er zurückbleibt, um den Wagen zu reparieren.",al={"wer vergibt überbringen der lieferung","überbringen der lieferung questgeber","behüter biggs lieferung"}},{q="Wohin muss diese Lieferung gebracht werden?",a="Ihr bringt die Vorräte zu Rüstmeister Lungertz in Burg Nethergarde in den nördlichen Hügeln der Verwüsteten Lande.",al={"wo ist burg nethergarde","wie gelangt man nach nethergarde","rüstmeister lungertz standort"}},{q="Was kommt unmittelbar vor dieser Lieferung?",a="Diese Lieferung folgt auf Driftwood.",al={"überbringen der lieferung voraussetzung","welche quest kommt vor überbringen der lieferung"}},{q="Welcher Weg führt vom Sumpf zur Burg?",a="Folgt der Straße nach Osten und biegt dann an der Abzweigung nach Süden in die Verwüsteten Lande ab. Biegt an der nächsten Weggabelung links ab.",al={"wegbeschreibung zur burg nethergarde","weg in die verwüsteten lande"}},{q="Worüber wacht Burg Nethergarde?",a="Burg Nethergarde wacht über das Dunkle Portal.",al={"zweck der burg nethergarde","warum liegt nethergarde in den verwüsteten landen"}}},fp="20,132,25.356.0,14.262.1,38.110.0,36.106.0,41.32.0,44.117.0,39.46.0"}
P.entries["quest:1426"] = {n="Gefahr aus dem Meer",s="Tok'Kar schickt Euch zu Katar in den Sümpfen des Elends. Katar hasst das Meer und sieht mit Freude zu, wie Fischmenschen durch jene fallen, die der Horde dienen. Nun fragt Katar, wie viele Ihr erschlagen könnt und ob Ihr Euch ihrer stärksten Art stellen könnt.",h="Tok'Kar schickt Euch zu Katar in den Sümpfen des Elends.",kw={"katar","marsh flesheater","marsh inkspewer","marsh murloc","murloc","sümpfe des elends","gefahr aus dem meer"},sec={{t="Groll gegen das Meer",b="In den Sümpfen des Elends bittet Katar Euch, marsh murlocs, marsh inkspewers und marsh flesheaters zu töten. Katar verabscheut das Meer und jede Kreatur, die daraus hervorkommt. Für Katar ist das Meer eine starke, aber blinde, gefühllose und brutale Herrin. Fischmenschen zu Hunderten zu erschlagen, würde Katar entzücken, wenn es möglich wäre. Vorerst verschafft es etwas Genugtuung, zuzusehen, wie sie durch jene fallen, die der Horde dienen."},{t="Katars Urteil",b="Wenn Ihr zurückkehrt, sagt Katar, das Meer mag riesig und unerbittlich erscheinen, doch seine Brut trägt nun Euer blutiges Mal. Die Fischmenschen kennen Schmerz und müssen ihre Reihen wieder aufbauen, was Katar erfreut. Jedes Mal, wenn einer zum Schweigen gebracht wird, wird Katar lächeln und Euch einladen, weitere zu erschlagen."}},faq={{q="Warum will Katar die Murlocs vernichtet sehen?",a="Katar hasst das Meer und jede Kreatur, die daraus hervorkommt, und würde gern sehen, wie Fischmenschen zu Hunderten erschlagen werden. Zuzusehen, wie sie durch die Hände jener sterben, die der Horde dienen, bereitet Katar etwas Freude.",al={"warum murlocs töten","katar murlocs","warum das meer hassen"}},{q="Wo findet diese Jagd statt?",a="Ihr jagt marsh murlocs, marsh inkspewers und marsh flesheaters in den Sümpfen des Elends.",al={"wo sind die marsh murlocs","gefahr aus dem meer ort"}},{q="Wer erteilt den Auftrag zu dieser Jagd?",a="Katar erteilt den Jagdauftrag in den Sümpfen des Elends, nachdem Tok'Kar Euch geschickt hat, um mit Katar zu sprechen.",al={"wer vergibt gefahr aus dem meer","gefahr aus dem meer questgeber"}},{q="Was geht dieser Jagd voraus?",a="Sie folgt auf die erste Quest „Gefahr aus dem Meer“, in der Tok'Kar Euch geschickt hat, um mit Katar zu sprechen.",al={"gefahr aus dem meer voraussetzung","gefahr aus dem meer vorherige quest"}}},fp="19,228,24.383.0,15.257.1,42.187.0,32.87.0,20.90.0,28.84.0"}
P.entries["quest:1427"] = {n="Gefahr aus dem Meer",s="Katar schickt Euch zu Tok'Kar zurück, bevor Ihr Euch ausruht. Er glaubt, dass Tok'Kar während Eurer Abwesenheit ein paar Waffen fertiggestellt hat und Euch eine davon für Eure Hilfe angeboten wird.",h="Katar schickt Euch zu Tok'Kar zurück, bevor Ihr Euch ausruht.",kw={"katar","murloc","sawtooth meat","sümpfe des elends","gefahr aus dem meer","tok'kar"},sec={{t="Zurück zu Tok'Kar",b="Bevor Ihr Euch ausruht, schickt Katar Euch zu Tok'Kar zurück. Er glaubt, dass Tok'Kar während Eurer Abwesenheit ein paar Waffen fertiggestellt hat. Tok'Kar wird Euch eine davon für Eure Hilfe anbieten. Katar sagt, Ihr könntet ihre Stärke an den Murlocs erproben, sobald Ihr bereit seid, was ihn noch mehr freuen würde."},{t="Tok'Kars Dank",b="Tok'Kar freut sich, Euch wiederzusehen. Weitere Waffen für den Krieg gegen die Murlocs sind hergestellt worden. Zum Dank dafür, dass Ihr frisches Sawtooth Meat gebracht und Katar ein kleines Lächeln ins Gesicht gezaubert habt, gibt er Euch eine davon."}},faq={{q="Wer schickt Euch zu Tok'Kar, um mit ihm zu sprechen?",a="Katar schickt Euch noch einmal zu Tok'Kar, um mit ihm zu sprechen, bevor Ihr Euch in den Sümpfen des Elends ausruht.",al={"wer gibt diese quest","wo gibt es gefahr aus dem meer","wer startet das"}},{q="Warum bietet Tok'Kar eine Waffe an?",a="Katar glaubt, dass Tok'Kar während Eurer Abwesenheit ein paar Waffen fertiggestellt hat und Euch eine davon als Dank für Eure Hilfe anbieten wird.",al={"warum gibt tok'kar eine waffe","was hat tok'kar hergestellt","grund für tok'kars belohnung"}},{q="Was kommt nach dem Gespräch mit Tok'Kar?",a="Continued Threat folgt.",al={"was ist die nächste quest","wohin danach","was folgt auf gefahr aus dem meer"}}},fp="19,158,15.258.0,16.194.1,36.88.0,33.114.0,44.25.0"}
P.entries["quest:1428"] = {n="Fortwährende Gefahr",s="Am Strand der Sümpfe des Elends sieht Katar, wie Euer Hass auf die Fischmenschen wächst, genau wie ihr eigener.",h="Am Strand der Sümpfe des Elends sieht Katar, wie Euer Hass auf die Fischmenschen wächst, genau wie ihr...",kw={"fortwährende gefahr","fischmenschen","katar","marsh flesheater","marsh inkspewer","marsh oracle","murlocs","sümpfe des elends"},sec={{t="Weiter am Strand entlang",b="Katar schickt Euch weiter am Strand entlang, um marsh inkspewers, marsh flesheaters und marsh oracles zu jagen. Kehrt zurück, wenn Ihr genug vom Kampf habt. Sie wird keine Freude empfinden, bis das Meer und all seine Kinder zum Schweigen gebracht sind, wobei sie vor allem an die abstoßenden Fischmenschen denkt."}},faq={{q="Wer vergibt diese Quest?",a="Katar gibt Euch diesen Auftrag am Strand der Sümpfe des Elends.",al={"wer startet fortwährende gefahr","fortwährende gefahr questgeber","katar sümpfe des elends"}},{q="Welche Kreaturen müssen gejagt werden?",a="Katar will, dass Ihr am Strand marsh inkspewers, marsh flesheaters und marsh oracles jagt.",al={"was töten fortwährende gefahr","fortwährende gefahr ziele","welche murlocs"}},{q="Warum will Katar die Murlocs dezimieren lassen?",a="Katar wird keine Freude empfinden, bis das Meer und seine Brut zum Schweigen gebracht sind, besonders die Fischmenschen.",al={"warum murlocs töten","katars beweggrund","warum fischmenschen hassen"}},{q="Was ging diesem Schritt voraus?",a="Dies folgt auf Threat From the Sea, wonach Tok'Kar Euch eine Waffe angeboten hat.",al={"fortwährende gefahr voraussetzung","vorherige quest fortwährende gefahr"}}},fp="16,94,20.277.0,21.56.0,33.94.0,39.94.0,27.75.0"}
